window.EX_BANK = [{"type": "mcq", "level": "A1", "topic": "Verbo To Be", "instruction": "Escolha a forma correta do verbo to be.", "explain": "Com \"my parents\" (eles, plural) usamos \"are\".", "prompt": "My parents ___ teachers.", "options": ["is", "am", "are", "be"], "correctIndex": 2, "id": "bkA1-0"}, {"type": "gaps", "level": "A1", "topic": "Verbo To Be", "instruction": "Complete o diálogo com am, is ou are (afirmativo ou negativo).", "explain": "\"You\" usa \"are\", \"I\" usa \"am\", \"she\" usa \"is\"; a resposta negativa é \"is not / isn't\".", "prompt": "A: Where ___ you from?\nB: I ___ from Brazil.\nA: ___ your sister from Brazil too?\nB: No, she ___. She is from Portugal.", "answers": [["are"], ["am"], ["Is"], ["is not", "isn't"]], "id": "bkA1-1"}, {"type": "choose", "level": "A1", "topic": "Verbo To Be", "instruction": "Escolha a forma correta do verbo to be.", "explain": "\"Tom\" (he) usa \"is\"; \"we\" usa \"are\".", "prompt": "Tom [is*/are/am] my friend, and we [is/are*/am] in the same class.", "id": "bkA1-2"}, {"type": "error", "level": "A1", "topic": "Verbo To Be", "instruction": "Encontre o erro e corrija.", "explain": "\"Carla and Pedro\" são duas pessoas (they), então o verbo é \"are\".", "sentence": "Carla and Pedro is at the beach.", "wrong": "is", "fix": ["are"], "id": "bkA1-3"}, {"type": "rewrite", "level": "A1", "topic": "Verbo To Be", "instruction": "Reescreva a frase na forma negativa.", "explain": "Na negativa do verbo to be, colocamos \"not\" depois de \"is\": \"is not / isn't\".", "prompt": "She is a doctor.", "accept": ["She is not a doctor.", "She isn't a doctor.", "She's not a doctor."], "id": "bkA1-4"}, {"type": "order", "level": "A1", "topic": "Verbo To Be", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Na pergunta com to be, o verbo vem antes do sujeito: \"Is your brother...?\"", "words": ["Is", "your", "brother", "a", "student"], "id": "bkA1-5"}, {"type": "tf", "level": "A1", "topic": "Verbo To Be", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que Lucas é de Salvador, Julia tem 20 anos e é estudante, e eles estão felizes.", "text": "Hi! My name is Lucas. I am 25 years old, and I am from Salvador. My sister Julia is 20. She is a student. We are very happy in our new house.", "items": [{"s": "Lucas is from Salvador.", "a": true}, {"s": "Julia is 25 years old.", "a": false}, {"s": "Julia is a student.", "a": true}, {"s": "Lucas and Julia are sad.", "a": false}], "id": "bkA1-6"}, {"type": "match", "level": "A1", "topic": "Verbo To Be", "instruction": "Ligue cada pergunta à resposta correta.", "explain": "A resposta curta repete o sujeito e o verbo: \"Are you...? Yes, I am.\"", "left": ["Are you tired?", "Is Maria at home?", "Are they from Chile?", "Is it cold today?"], "right": ["Yes, she is.", "No, it isn't.", "Yes, I am.", "No, they aren't."], "correctMap": [2, 0, 3, 1], "id": "bkA1-7"}, {"type": "sort", "level": "A1", "topic": "Verbo To Be", "instruction": "Separe as palavras de acordo com a forma do verbo to be.", "explain": "\"I\" usa \"am\"; he, she, it e nomes no singular usam \"is\"; we, you, they usam \"are\".", "prompt": "Sort the words: am, is or are?", "groups": ["am", "is", "are"], "items": [{"w": "I", "g": 0}, {"w": "she", "g": 1}, {"w": "it", "g": 1}, {"w": "my dad", "g": 1}, {"w": "we", "g": 2}, {"w": "they", "g": 2}, {"w": "you", "g": 2}, {"w": "Ana and I", "g": 2}], "id": "bkA1-8"}, {"type": "reading", "level": "A1", "topic": "Verbo To Be", "instruction": "Leia o texto e responda às perguntas.", "explain": "O texto diz que Kenji é do Japão, Clara é dentista e o restaurante fica em São Paulo.", "text": "Hello! This is my friend Kenji. He is from Japan, but now he is in Brazil. He is a cook in a Japanese restaurant in São Paulo. His wife is Brazilian. Her name is Clara, and she is a dentist. They are very nice people.", "questions": [{"q": "Where is Kenji from?", "options": ["Brazil", "Japan", "China"], "correctIndex": 1}, {"q": "What is Clara's job?", "options": ["She is a dentist.", "She is a cook.", "She is a teacher."], "correctIndex": 0}, {"q": "Where is the restaurant?", "options": ["In Japan", "In Rio", "In São Paulo"], "correctIndex": 2}], "id": "bkA1-9"}, {"type": "mcq", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Escolha o pronome correto.", "explain": "Depois de preposição (with) usamos pronome objeto: \"him\".", "prompt": "This is my brother. I play soccer with ___ on Sundays.", "options": ["he", "him", "his", "they"], "correctIndex": 1, "id": "bkA1-10"}, {"type": "choose", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Escolha o pronome correto.", "explain": "\"I\" é sujeito (antes do verbo); \"it\" substitui \"pizza\" (singular) como objeto.", "prompt": "[Me/I*] love pizza, but my sister doesn't like [it*/them].", "id": "bkA1-11"}, {"type": "gaps", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Complete com a forma correta do pronome entre parênteses.", "explain": "Antes do verbo usamos pronome sujeito (we); depois do verbo, pronome objeto (us).", "prompt": "Ana and I are friends. ___ (we) go to school together. Our teacher likes ___ (we) a lot.", "answers": [["We"], ["us"]], "id": "bkA1-12"}, {"type": "error", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Encontre o erro e corrija.", "explain": "Depois do verbo \"help\" usamos pronome objeto: \"me\", não \"I\".", "sentence": "Can you help I with my bag?", "wrong": "I", "fix": ["me"], "id": "bkA1-13"}, {"type": "rewrite", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Reescreva a frase trocando \"Maria and Paulo\" por um pronome.", "explain": "\"Maria and Paulo\" é objeto e plural, então usamos \"them\".", "prompt": "I see Maria and Paulo every day.", "accept": ["I see them every day.", "Every day I see them."], "id": "bkA1-14"}, {"type": "order", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Ordem: sujeito (She) + verbo (calls) + objeto (me) + tempo.", "words": ["She", "calls", "me", "every", "night"], "alt": ["Every night she calls me"], "id": "bkA1-15"}, {"type": "match", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Ligue cada pronome sujeito ao pronome objeto correspondente.", "explain": "I→me, he→him, she→her, we→us, they→them.", "left": ["I", "he", "she", "we", "they"], "right": ["them", "her", "me", "us", "him"], "correctMap": [2, 4, 1, 3, 0], "id": "bkA1-16"}, {"type": "sort", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Separe os pronomes: sujeito ou objeto.", "explain": "Pronomes sujeito vêm antes do verbo (I, he, she, they); objeto vêm depois (me, him, us, them).", "prompt": "Sort the pronouns: subject or object?", "groups": ["Pronome sujeito", "Pronome objeto"], "items": [{"w": "I", "g": 0}, {"w": "me", "g": 1}, {"w": "he", "g": 0}, {"w": "him", "g": 1}, {"w": "they", "g": 0}, {"w": "us", "g": 1}, {"w": "she", "g": 0}, {"w": "them", "g": 1}], "id": "bkA1-17"}, {"type": "dorder", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Primeiro a pergunta \"Who...?\", depois quem é; em seguida, a pergunta sobre ele (\"him\").", "lines": ["A: Who is that man?", "B: He is my uncle, Carlos.", "A: Do you see him often?", "B: Yes, I visit him every Sunday."], "id": "bkA1-18"}, {"type": "odd", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Encontre a palavra que não pertence ao grupo.", "explain": "\"She\" é pronome sujeito; me, him e us são pronomes objeto.", "prompt": "Which word does not belong?", "options": ["me", "him", "she", "us"], "correctIndex": 2, "id": "bkA1-19"}, {"type": "mcq", "level": "A1", "topic": "Possessivos", "instruction": "Escolha o possessivo correto.", "explain": "Lucas é homem, então o possessivo é \"his\".", "prompt": "Lucas has a dog. ___ dog is very big.", "options": ["He", "His", "Her", "Him"], "correctIndex": 1, "id": "bkA1-20"}, {"type": "gaps", "level": "A1", "topic": "Possessivos", "instruction": "Complete com o adjetivo possessivo do pronome entre parênteses.", "explain": "I→my, she→her, they→their. O possessivo vem antes do substantivo.", "prompt": "This is my family. ___ (I) mother is a nurse, and ___ (she) name is Rosa. My parents love ___ (they) garden.", "answers": [["My"], ["her"], ["their"]], "id": "bkA1-21"}, {"type": "choose", "level": "A1", "topic": "Possessivos", "instruction": "Escolha a palavra correta.", "explain": "Antes de substantivo usamos possessivo: \"our house\", \"their rooms\".", "prompt": "We love [our*/us] new house, and the kids love [their*/they] rooms.", "id": "bkA1-22"}, {"type": "error", "level": "A1", "topic": "Possessivos", "instruction": "Encontre o erro e corrija.", "explain": "Antes de substantivo usamos \"our\"; \"ours\" é usado sozinho, sem substantivo depois.", "sentence": "We visit ours grandparents every Sunday.", "wrong": "ours", "fix": ["our"], "id": "bkA1-23"}, {"type": "rewrite", "level": "A1", "topic": "Possessivos", "instruction": "Reescreva usando um pronome possessivo (mine, yours...).", "explain": "\"My book\" vira \"mine\" no final da frase: \"This book is mine.\"", "prompt": "This is my book.", "start": "This book is", "accept": ["This book is mine."], "id": "bkA1-24"}, {"type": "order", "level": "A1", "topic": "Possessivos", "instruction": "Ordene as palavras para formar uma frase.", "explain": "O possessivo \"their\" vem antes do substantivo \"house\".", "words": ["Their", "house", "is", "near", "the", "beach"], "id": "bkA1-25"}, {"type": "match", "level": "A1", "topic": "Possessivos", "instruction": "Ligue cada pronome ao possessivo correspondente.", "explain": "I→my, you→your, he→his, she→her, we→our.", "left": ["I", "you", "he", "she", "we"], "right": ["his", "our", "your", "my", "her"], "correctMap": [3, 2, 0, 4, 1], "id": "bkA1-26"}, {"type": "reading", "level": "A1", "topic": "Possessivos", "instruction": "Leia o texto e responda às perguntas.", "explain": "Theo é filho de Beatriz, gosta de um carro vermelho, e a casa grande fica em São Paulo.", "text": "Hello! I'm Beatriz, and I live in Curitiba. My husband's name is Rafael. Our apartment is small but nice. Our son, Theo, is five. His favorite toy is a red car. Rafael's parents live in São Paulo, and their house is very big.", "questions": [{"q": "Who is Theo?", "options": ["Beatriz's son", "Beatriz's brother", "Rafael's father"], "correctIndex": 0}, {"q": "What is Theo's favorite toy?", "options": ["A ball", "A red car", "A small apartment"], "correctIndex": 1}, {"q": "Where is the big house?", "options": ["In Curitiba", "In Rio", "In São Paulo"], "correctIndex": 2}], "id": "bkA1-27"}, {"type": "odd", "level": "A1", "topic": "Possessivos", "instruction": "Encontre a palavra que não pertence ao grupo.", "explain": "\"Mine\" é pronome possessivo (usado sozinho); my, your e their vêm antes de substantivo.", "prompt": "Find the odd one out.", "options": ["my", "your", "mine", "their"], "correctIndex": 2, "id": "bkA1-28"}, {"type": "dorder", "level": "A1", "topic": "Possessivos", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta \"Whose...?\" vem primeiro; depois alguém sugere o dono, a correção e a resposta final.", "lines": ["A: Whose jacket is this?", "B: I think it's Mark's.", "A: No, his jacket is black. This one is blue.", "B: Oh, then it's mine! Thank you."], "id": "bkA1-29"}, {"type": "mcq", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Escolha o demonstrativo correto.", "explain": "\"Shoes\" é plural e está longe (\"over there\"), então usamos \"those\".", "prompt": "___ shoes over there are expensive.", "options": ["This", "That", "These", "Those"], "correctIndex": 3, "id": "bkA1-30"}, {"type": "choose", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Escolha o demonstrativo correto.", "explain": "\"This\" = singular e perto (here); \"those\" = plural e longe (over there).", "prompt": "[This*/These] apple here is red, but [that/those*] apples over there are green.", "id": "bkA1-31"}, {"type": "gaps", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Complete o diálogo com this, that, these ou those.", "explain": "Perto e singular: this; longe e singular: that; perto e plural: these.", "prompt": "A: Is ___ your pen? It's here, on my desk.\nB: No, my pen is ___ one over there.\nA: Are ___ your keys here, in my hand?\nB: Yes, thank you!", "answers": [["this"], ["that"], ["these"]], "id": "bkA1-32"}, {"type": "error", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Encontre o erro e corrija.", "explain": "\"Birds\" é plural, então usamos \"these\" (perto) ou \"those\" (longe), não \"this\".", "sentence": "Look at this birds in the tree!", "wrong": "this", "fix": ["these", "those"], "id": "bkA1-33"}, {"type": "rewrite", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Reescreva a frase no plural.", "explain": "O plural de \"this is\" é \"these are\", e \"friend\" vira \"friends\".", "prompt": "This is my friend.", "start": "These", "accept": ["These are my friends."], "id": "bkA1-34"}, {"type": "order", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"Those\" (plural, longe) vem antes do substantivo \"cars\".", "words": ["Those", "cars", "over", "there", "are", "very", "old"], "id": "bkA1-35"}, {"type": "sort", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Separe os substantivos: combinam com \"this\" (singular) ou \"these\" (plural)?", "explain": "\"This\" vai com singular (book, car); \"these\" vai com plural (apples, children, people).", "prompt": "Sort the words: this or these?", "groups": ["this", "these"], "items": [{"w": "book", "g": 0}, {"w": "apples", "g": 1}, {"w": "car", "g": 0}, {"w": "children", "g": 1}, {"w": "house", "g": 0}, {"w": "shoes", "g": 1}, {"w": "bus", "g": 0}, {"w": "people", "g": 1}], "id": "bkA1-36"}, {"type": "tf", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "\"This dress\" indica que o vestido está perto de Paula; \"those shoes\" indica sapatos longe.", "text": "Paula is at a store with her friend Leo. She has a green dress in her hands and says, \"I love this dress!\" Leo points to some shoes far away and says, \"Look at those shoes!\" The dress is cheap, but the shoes are expensive.", "items": [{"s": "The green dress is near Paula.", "a": true}, {"s": "The shoes are near Leo.", "a": false}, {"s": "The shoes are expensive.", "a": true}], "id": "bkA1-37"}, {"type": "match", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Ligue as partes para formar frases.", "explain": "This = singular/perto; these = plural/perto; that = singular/longe; those = plural/longe.", "left": ["This is", "These are", "That is", "Those are"], "right": ["my sisters, over there.", "my car, here.", "my house, over there.", "my kids, here with me."], "correctMap": [1, 3, 2, 0], "id": "bkA1-38"}, {"type": "odd", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Encontre a palavra que não pertence ao grupo.", "explain": "\"They\" é pronome pessoal; this, that e these são demonstrativos.", "prompt": "Which one is different?", "options": ["this", "that", "these", "they"], "correctIndex": 3, "id": "bkA1-39"}, {"type": "mcq", "level": "A1", "topic": "Artigos A / An", "instruction": "Qual opção está correta?", "explain": "Usamos \"an\" antes de som de vogal: \"an orange\". Car usa \"a\"; umbrella e hour usam \"an\".", "prompt": "Which is correct?", "options": ["an car", "a umbrella", "an orange", "a hour"], "correctIndex": 2, "id": "bkA1-40"}, {"type": "choose", "level": "A1", "topic": "Artigos A / An", "instruction": "Escolha a ou an.", "explain": "\"Brother\" começa com som de consoante (a); \"uncle\" com som de vogal (an).", "prompt": "I have [a*/an] brother and [a/an*] uncle in Manaus.", "id": "bkA1-41"}, {"type": "gaps", "level": "A1", "topic": "Artigos A / An", "instruction": "Complete com a ou an.", "explain": "\"An\" antes de som de vogal (actor, old); \"a\" antes de som de consoante (big).", "prompt": "Marcos is ___ actor. He has ___ big house and ___ old car.", "answers": [["an"], ["a"], ["an"]], "id": "bkA1-42"}, {"type": "error", "level": "A1", "topic": "Artigos A / An", "instruction": "Encontre o erro e corrija.", "explain": "\"University\" começa com som de \"iu\" (consoante), então usamos \"a\".", "sentence": "USP is an university in São Paulo.", "wrong": "an", "fix": ["a"], "id": "bkA1-43"}, {"type": "rewrite", "level": "A1", "topic": "Artigos A / An", "instruction": "Reescreva a frase no singular.", "explain": "No singular precisamos do artigo; \"engineer\" começa com vogal, então \"an engineer\".", "prompt": "They are engineers.", "start": "He is", "accept": ["He is an engineer."], "id": "bkA1-44"}, {"type": "order", "level": "A1", "topic": "Artigos A / An", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"An\" antes de \"egg\" (som de vogal) e \"a\" antes de \"banana\".", "words": ["I", "want", "an", "egg", "and", "a", "banana"], "alt": ["I want a banana and an egg"], "id": "bkA1-45"}, {"type": "sort", "level": "A1", "topic": "Artigos A / An", "instruction": "Separe as palavras: usam \"a\" ou \"an\"?", "explain": "O que importa é o som: \"hour\" tem h mudo (an); \"uniform\" soa \"iu\" (a).", "prompt": "Sort the words: a or an?", "groups": ["a", "an"], "items": [{"w": "dog", "g": 0}, {"w": "elephant", "g": 1}, {"w": "hour", "g": 1}, {"w": "house", "g": 0}, {"w": "umbrella", "g": 1}, {"w": "uniform", "g": 0}, {"w": "orange", "g": 1}, {"w": "car", "g": 0}], "id": "bkA1-46"}, {"type": "odd", "level": "A1", "topic": "Artigos A / An", "instruction": "Qual palavra não usa \"an\"?", "explain": "\"Horse\" tem h pronunciado, então usa \"a\"; egg, island e hour (h mudo) usam \"an\".", "prompt": "Which word does not use \"an\"?", "options": ["egg", "island", "hour", "horse"], "correctIndex": 3, "id": "bkA1-47"}, {"type": "dorder", "level": "A1", "topic": "Artigos A / An", "instruction": "Coloque o diálogo na ordem correta.", "explain": "O atendente oferece ajuda, o cliente pede, o atendente pergunta se quer mais algo e informa o preço.", "lines": ["A: Hi! Can I help you?", "B: Yes, I want a coffee, please.", "A: Anything else?", "B: Yes, an orange juice too. How much is it?", "A: It's ten reais."], "id": "bkA1-48"}, {"type": "blank", "level": "A1", "topic": "Artigos A / An", "instruction": "Complete com a ou an.", "explain": "\"Artist\" começa com som de vogal, então usamos \"an\".", "prompt": "My cousin is ___ artist.", "accept": ["an"], "id": "bkA1-49"}, {"type": "mcq", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Escolha a resposta correta.", "explain": "15 + 5 = 20, que em inglês é \"twenty\".", "prompt": "What is 15 + 5?", "options": ["fifty", "fifteen", "twenty", "twelve"], "correctIndex": 2, "id": "bkA1-50"}, {"type": "gaps", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Complete com o número ordinal (first, second...) por extenso.", "explain": "Para posição/ordem usamos ordinais: 1 = first, 3 = third.", "prompt": "January is the ___ (1) month of the year. March is the ___ (3) month.", "answers": [["first", "1st"], ["third", "3rd"]], "id": "bkA1-51"}, {"type": "choose", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Escolha a forma correta do número.", "explain": "Datas usam ordinal (\"the twentieth\"); idade usa cardinal (\"thirty years old\").", "prompt": "My birthday is on the [twenty/twentieth*] of May, and I am [thirty*/thirtieth] years old.", "id": "bkA1-52"}, {"type": "error", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Encontre o erro e corrija.", "explain": "Para andar (floor) usamos número ordinal: \"the third floor\".", "sentence": "My office is on the three floor.", "wrong": "three", "fix": ["third", "3rd"], "id": "bkA1-53"}, {"type": "match", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Ligue cada número à palavra correspondente.", "explain": "12 = twelve, 13 = thirteen, 40 = forty, 90 = ninety, 2nd = second.", "left": ["12", "13", "40", "90", "2nd"], "right": ["ninety", "second", "twelve", "forty", "thirteen"], "correctMap": [2, 4, 3, 0, 1], "id": "bkA1-54"}, {"type": "sort", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Separe os números: cardinais ou ordinais?", "explain": "Cardinais indicam quantidade (seven); ordinais indicam ordem (fifth, first).", "prompt": "Sort the numbers: cardinal or ordinal?", "groups": ["Cardinal", "Ordinal"], "items": [{"w": "seven", "g": 0}, {"w": "fifth", "g": 1}, {"w": "eleven", "g": 0}, {"w": "ninth", "g": 1}, {"w": "twenty", "g": 0}, {"w": "first", "g": 1}, {"w": "thirty", "g": 0}, {"w": "twelfth", "g": 1}], "id": "bkA1-55"}, {"type": "reading", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Leia o texto e responda às perguntas.", "explain": "O texto diz: a academia fica no terceiro andar, o café da manhã começa às sete e o quarto custa noventa dólares.", "text": "Welcome to the City Hotel! Our hotel has five floors. The restaurant is on the first floor, and the gym is on the third floor. Breakfast is from seven to ten in the morning. A room for two people is ninety dollars a night.", "questions": [{"q": "Where is the gym?", "options": ["On the first floor", "On the third floor", "On the fifth floor"], "correctIndex": 1}, {"q": "When does breakfast start?", "options": ["At seven", "At ten", "At nine"], "correctIndex": 0}, {"q": "How much is a room for two people?", "options": ["Nineteen dollars", "Nine dollars", "Ninety dollars"], "correctIndex": 2}], "id": "bkA1-56"}, {"type": "blank", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Escreva o resultado por extenso, em inglês.", "explain": "20 + 30 = 50, que em inglês é \"fifty\".", "prompt": "Twenty plus thirty is ___.", "accept": ["fifty", "50"], "id": "bkA1-57"}, {"type": "odd", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Encontre a palavra que não pertence ao grupo.", "explain": "\"Six\" é cardinal; second, fourth e tenth são ordinais.", "prompt": "One word is different. Which one?", "options": ["second", "fourth", "six", "tenth"], "correctIndex": 2, "id": "bkA1-58"}, {"type": "tf", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "São quarenta (forty) corredores; Ana chega em primeiro e Rodrigo em terceiro.", "text": "Today there is a race in Fortaleza with forty runners. Rodrigo finishes in third place. His friend Ana finishes in first place. Rodrigo is twenty-eight years old, and Ana is thirty-one.", "items": [{"s": "There are fourteen runners in the race.", "a": false}, {"s": "Ana finishes first.", "a": true}, {"s": "Ana is thirty-one years old.", "a": true}, {"s": "Rodrigo finishes second.", "a": false}], "id": "bkA1-59"}, {"type": "mcq", "level": "A1", "topic": "There is / There are", "instruction": "Escolha a opção correta.", "explain": "\"Two banks\" é plural, então usamos \"there are\".", "prompt": "___ two banks on my street.", "options": ["There is", "There are", "It is", "They are"], "correctIndex": 1, "id": "bkA1-60"}, {"type": "gaps", "level": "A1", "topic": "There is / There are", "instruction": "Complete o texto com is, are, isn't ou aren't.", "explain": "Singular usa \"is\", plural usa \"are\"; na negativa, \"aren't\"; na pergunta, \"Is there...?\".", "prompt": "Welcome to my town! There ___ a big park near my house. There ___ many trees in the park. There ___ a school, but there ___ any hospitals. ___ there a supermarket? Yes, there ___.", "answers": [["is"], ["are"], ["is"], ["are not", "aren't"], ["Is"], ["is"]], "id": "bkA1-61"}, {"type": "choose", "level": "A1", "topic": "There is / There are", "instruction": "Escolha is ou are.", "explain": "\"A cat\" é singular (there is); \"three dogs\" é plural (there are).", "prompt": "There [is*/are] a cat on the sofa, and there [is/are*] three dogs in the garden.", "id": "bkA1-62"}, {"type": "error", "level": "A1", "topic": "There is / There are", "instruction": "Encontre o erro e corrija.", "explain": "\"Five people\" é plural, então o correto é \"there are\".", "sentence": "There is five people in my family.", "wrong": "is", "fix": ["are"], "id": "bkA1-63"}, {"type": "rewrite", "level": "A1", "topic": "There is / There are", "instruction": "Transforme a frase em pergunta.", "explain": "Na pergunta, invertemos: \"There is\" vira \"Is there...?\".", "prompt": "There is a pharmacy near here.", "start": "Is", "accept": ["Is there a pharmacy near here?"], "id": "bkA1-64"}, {"type": "order", "level": "A1", "topic": "There is / There are", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"There are\" + plural (two bedrooms) + lugar.", "words": ["There", "are", "two", "bedrooms", "in", "my", "apartment"], "alt": ["In my apartment there are two bedrooms", "In my apartment, there are two bedrooms"], "id": "bkA1-65"}, {"type": "dorder", "level": "A1", "topic": "There is / There are", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pessoa pergunta pelo banco, recebe a resposta, pergunta sobre restaurantes e agradece.", "lines": ["A: Excuse me, is there a bank near here?", "B: Yes, there is. It's on Flores Street.", "A: Great. Are there any restaurants on that street?", "B: Yes, there are two good restaurants.", "A: Thank you very much!"], "id": "bkA1-66"}, {"type": "tf", "level": "A1", "topic": "There is / There are", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto fala de doze carteiras, um computador, nenhuma janela e um pôster na parede.", "text": "My classroom is small. There are twelve desks and one big table. There is a computer on the table. There aren't any windows, but there is a nice poster on the wall.", "items": [{"s": "There are twelve desks.", "a": true}, {"s": "There are two computers.", "a": false}, {"s": "There are three windows.", "a": false}, {"s": "There is a poster on the wall.", "a": true}], "id": "bkA1-67"}, {"type": "match", "level": "A1", "topic": "There is / There are", "instruction": "Ligue cada pergunta à resposta correta.", "explain": "\"Is there\" responde com \"there is\"; \"Are there\" responde com \"there are / there aren't\".", "left": ["Is there a TV in your room?", "Are there any eggs?", "Is there a bus stop here?", "Are there any students in the class?"], "right": ["Yes, there are twenty.", "No, there aren't. Let's buy some.", "Yes, there is. It's next to my bed.", "Yes, there is. It's on the corner."], "correctMap": [2, 1, 3, 0], "id": "bkA1-68"}, {"type": "blank", "level": "A1", "topic": "There is / There are", "instruction": "Complete com Is ou Are.", "explain": "\"Milk\" é incontável (singular), então a pergunta é \"Is there...?\".", "prompt": "___ there any milk in the fridge?", "accept": ["Is"], "id": "bkA1-69"}, {"type": "mcq", "level": "A1", "topic": "Simple Present", "instruction": "Escolha a forma correta do verbo.", "explain": "Com he/she/it (my brother) acrescentamos -es a \"watch\": \"watches\".", "prompt": "My brother ___ TV every night.", "options": ["watch", "watches", "watching", "is watch"], "correctIndex": 1, "id": "bkA1-70"}, {"type": "gaps", "level": "A1", "topic": "Simple Present", "instruction": "Complete com o verbo entre parênteses no Simple Present.", "explain": "Com \"she\" o verbo ganha -s (lives, works); na negativa usamos \"doesn't\" + verbo base.", "prompt": "Julia ___ (live) in Porto Alegre. She ___ (work) in a bank. She ___ (not / like) cold weather.", "answers": [["lives"], ["works"], ["does not like", "doesn't like"]], "id": "bkA1-71"}, {"type": "choose", "level": "A1", "topic": "Simple Present", "instruction": "Escolha a forma correta.", "explain": "Com \"your father\" (he) usamos \"does\" na pergunta e \"doesn't\" na resposta.", "prompt": "[Do/Does*] your father drink coffee? No, he [don't/doesn't*].", "id": "bkA1-72"}, {"type": "error", "level": "A1", "topic": "Simple Present", "instruction": "Encontre o erro e corrija.", "explain": "Com \"she\" a negativa é \"doesn't\", não \"don't\".", "sentence": "She don't eat meat.", "wrong": "don't", "fix": ["doesn't", "does not"], "id": "bkA1-73"}, {"type": "rewrite", "level": "A1", "topic": "Simple Present", "instruction": "Reescreva a frase na forma negativa.", "explain": "Com \"they\" a negativa usa \"don't\" + verbo base.", "prompt": "They play soccer on Saturdays.", "accept": ["They don't play soccer on Saturdays.", "They do not play soccer on Saturdays."], "id": "bkA1-74"}, {"type": "rewrite", "level": "A1", "topic": "Simple Present", "instruction": "Transforme a frase em pergunta.", "explain": "Com \"he\" a pergunta começa com \"Does\", e o verbo volta à forma base (speak).", "prompt": "He speaks Spanish.", "start": "Does", "accept": ["Does he speak Spanish?"], "id": "bkA1-75"}, {"type": "order", "level": "A1", "topic": "Simple Present", "instruction": "Ordene as palavras para formar uma frase.", "explain": "O advérbio \"usually\" vem antes do verbo principal (have).", "words": ["We", "usually", "have", "dinner", "at", "eight"], "alt": ["Usually we have dinner at eight", "At eight we usually have dinner"], "id": "bkA1-76"}, {"type": "reading", "level": "A1", "topic": "Simple Present", "instruction": "Leia a mensagem e responda às perguntas.", "explain": "Pedro trabalha num café, termina às 3 da tarde e vai à academia depois do trabalho.", "text": "Hi Carol! How are you? I have a new job now. I work in a café in Belo Horizonte. I start at 7 a.m. and finish at 3 p.m. After work, I go to the gym. My boss is nice, and I like my coworkers. See you soon! Pedro", "questions": [{"q": "Where does Pedro work?", "options": ["In a gym", "In a café", "In a bank"], "correctIndex": 1}, {"q": "What time does he finish work?", "options": ["At 3 p.m.", "At 7 a.m.", "At 7 p.m."], "correctIndex": 0}, {"q": "What does he do after work?", "options": ["He goes home.", "He goes to the gym.", "He meets Carol."], "correctIndex": 1}], "id": "bkA1-77"}, {"type": "sort", "level": "A1", "topic": "Simple Present", "instruction": "Com he/she/it, o verbo ganha -s ou -es? Separe.", "explain": "Verbos terminados em -ch, -sh, -x e -o ganham -es (watches, goes); os outros, -s.", "prompt": "Sort the verbs: + s or + es?", "groups": ["+ s (plays)", "+ es (watches)"], "items": [{"w": "play", "g": 0}, {"w": "watch", "g": 1}, {"w": "go", "g": 1}, {"w": "read", "g": 0}, {"w": "fix", "g": 1}, {"w": "eat", "g": 0}, {"w": "wash", "g": 1}, {"w": "sleep", "g": 0}], "id": "bkA1-78"}, {"type": "match", "level": "A1", "topic": "Simple Present", "instruction": "Ligue cada pergunta à resposta correta.", "explain": "\"Do you...?\" responde com \"I do\"; \"Does Ana...?\" com \"she doesn't\"; What time/Where pedem hora e lugar.", "left": ["Do you like pizza?", "Does Ana work here?", "What time do you wake up?", "Where do they live?"], "right": ["In Natal.", "At six o'clock.", "Yes, I do. I love it!", "No, she doesn't."], "correctMap": [2, 3, 1, 0], "id": "bkA1-79"}, {"type": "mcq", "level": "A1", "topic": "Wh- Words", "instruction": "Escolha a palavra interrogativa correta.", "explain": "A resposta é um mês (July), então perguntamos com \"When\" (quando).", "prompt": "___ is your birthday? It's in July.", "options": ["What", "When", "Who", "Where"], "correctIndex": 1, "id": "bkA1-80"}, {"type": "match", "level": "A1", "topic": "Wh- Words", "instruction": "Ligue cada palavra interrogativa à resposta adequada.", "explain": "Who = pessoa; Where = lugar; When = tempo; Why = motivo (because).", "left": ["Who", "Where", "When", "Why"], "right": ["In the kitchen.", "Because I'm tired.", "My teacher.", "On Monday."], "correctMap": [2, 0, 3, 1], "id": "bkA1-81"}, {"type": "gaps", "level": "A1", "topic": "Wh- Words", "instruction": "Complete o diálogo com What, Where ou How.", "explain": "What = o quê/qual (nome); Where = onde; How old = quantos anos.", "prompt": "A: ___ is your name?\nB: My name is Diego.\nA: ___ are you from?\nB: I'm from Uruguay.\nA: ___ old are you?\nB: I'm 22.", "answers": [["What"], ["Where"], ["How"]], "id": "bkA1-82"}, {"type": "choose", "level": "A1", "topic": "Wh- Words", "instruction": "Escolha a palavra interrogativa correta.", "explain": "\"What\" pergunta sobre coisas (comida); \"where\" pergunta sobre lugar.", "prompt": "[What*/Who] do you eat for breakfast, and [where*/who] do you have lunch?", "id": "bkA1-83"}, {"type": "error", "level": "A1", "topic": "Wh- Words", "instruction": "Encontre o erro e corrija.", "explain": "Para perguntar qual é a cor favorita usamos \"What\", não \"Where\" (onde).", "sentence": "Where is your favorite color?", "wrong": "Where", "fix": ["What"], "id": "bkA1-84"}, {"type": "rewrite", "level": "A1", "topic": "Wh- Words", "instruction": "Faça uma pergunta sobre o lugar (Recife).", "explain": "Para perguntar sobre lugar usamos \"Where\" + does + she + verbo base.", "prompt": "She lives in Recife.", "start": "Where", "accept": ["Where does she live?"], "id": "bkA1-85"}, {"type": "order", "level": "A1", "topic": "Wh- Words", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Estrutura: What time + does + sujeito + verbo base.", "words": ["What", "time", "does", "the", "movie", "start"], "id": "bkA1-86"}, {"type": "dorder", "level": "A1", "topic": "Wh- Words", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Primeiro \"Who\" (quem é), depois \"Where\" (onde mora), e por fim \"Why\" (por que está aqui).", "lines": ["A: Hi! Who is that girl?", "B: That's Lara, my cousin.", "A: Where does she live?", "B: She lives in Lisbon, in Portugal.", "A: Oh! So why is she in Brazil?", "B: Because she's on vacation."], "id": "bkA1-87"}, {"type": "odd", "level": "A1", "topic": "Wh- Words", "instruction": "Encontre a palavra que não pertence ao grupo.", "explain": "\"Very\" não é palavra interrogativa; what, where e when são.", "prompt": "Which word is not in the group?", "options": ["what", "where", "when", "very"], "correctIndex": 3, "id": "bkA1-88"}, {"type": "tf", "level": "A1", "topic": "Wh- Words", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "Valentina é guia de turismo, começa às nove, adora o Pelourinho e mora com dois gatos.", "text": "Valentina is a tour guide in Salvador. She works from Tuesday to Sunday. She starts work at nine in the morning. Her favorite place in the city is Pelourinho because it is very colorful. She lives with her two cats.", "items": [{"s": "Valentina is a teacher.", "a": false}, {"s": "She starts work at 9 a.m.", "a": true}, {"s": "Her favorite place is Pelourinho.", "a": true}, {"s": "She lives with two dogs.", "a": false}], "id": "bkA1-89"}, {"type": "mcq", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Escolha a resposta correta.", "explain": "Depois de Monday (segunda) vem Tuesday (terça).", "prompt": "The day after Monday is ___.", "options": ["Sunday", "Tuesday", "Thursday", "Wednesday"], "correctIndex": 1, "id": "bkA1-90"}, {"type": "gaps", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Complete com o dia ou mês correto.", "explain": "January é o primeiro mês, December o último; o fim de semana é Saturday e Sunday.", "prompt": "The first month of the year is ___. The last month is ___. The weekend is Saturday and ___.", "answers": [["January"], ["December"], ["Sunday"]], "id": "bkA1-91"}, {"type": "choose", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Escolha a palavra correta.", "explain": "No Brasil, o Natal é em dezembro, que é verão no hemisfério sul.", "prompt": "In Brazil, Christmas is in [summer*/winter], and it is in [December*/July].", "id": "bkA1-92"}, {"type": "error", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Encontre o erro e corrija.", "explain": "September (setembro) vem antes de October (outubro), não depois.", "sentence": "September comes after October.", "wrong": "after", "fix": ["before"], "id": "bkA1-93"}, {"type": "order", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Com dias da semana usamos \"on\": \"on Tuesdays and Thursdays\".", "words": ["We", "have", "class", "on", "Tuesdays", "and", "Thursdays"], "alt": ["We have class on Thursdays and Tuesdays", "On Tuesdays and Thursdays we have class", "On Thursdays and Tuesdays we have class"], "id": "bkA1-94"}, {"type": "sort", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Separe as palavras: dias, meses ou estações.", "explain": "Friday, Sunday, Wednesday são dias; April, October, June são meses; spring e fall são estações.", "prompt": "Sort the words: days, months or seasons?", "groups": ["Dias", "Meses", "Estações"], "items": [{"w": "Friday", "g": 0}, {"w": "Sunday", "g": 0}, {"w": "April", "g": 1}, {"w": "October", "g": 1}, {"w": "spring", "g": 2}, {"w": "fall", "g": 2}, {"w": "Wednesday", "g": 0}, {"w": "June", "g": 1}], "id": "bkA1-95"}, {"type": "reading", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Leia o cartão-postal e responda às perguntas.", "explain": "Grace diz que é inverno em janeiro, que esquia aos sábados e que em julho faz calor.", "text": "Hi Mia! Greetings from Canada. It is January, and it's winter here. It is very cold, and there is a lot of snow. I go skiing on Saturdays. In July it's summer, so it's hot. Come and visit me in the summer! Love, Grace", "questions": [{"q": "What season is it in Canada now?", "options": ["Summer", "Winter", "Spring"], "correctIndex": 1}, {"q": "When does Grace go skiing?", "options": ["On Saturdays", "On Sundays", "In July"], "correctIndex": 0}, {"q": "When is it hot in Canada?", "options": ["In January", "In December", "In July"], "correctIndex": 2}], "id": "bkA1-96"}, {"type": "match", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Ligue cada descrição à resposta correta.", "explain": "Antes de Friday vem Thursday; depois de May vem June; depois do inverno vem spring; depois de Saturday vem Sunday.", "left": ["The day before Friday", "The month after May", "The season after winter", "The day after Saturday"], "right": ["June", "Sunday", "Thursday", "spring"], "correctMap": [2, 0, 3, 1], "id": "bkA1-97"}, {"type": "odd", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Encontre a palavra que não pertence ao grupo.", "explain": "\"Tuesday\" é dia da semana; July, March e November são meses.", "prompt": "Choose the word that does not belong.", "options": ["July", "Tuesday", "March", "November"], "correctIndex": 1, "id": "bkA1-98"}, {"type": "dorder", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta vem primeiro; B responde e devolve a pergunta (\"And yours?\"); A responde e B comenta.", "lines": ["A: When is your birthday?", "B: It's on October 12th. And yours?", "A: Mine is in June.", "B: Oh, that's in the winter here in Brazil!"], "id": "bkA1-99"}, {"type": "mcq", "level": "A1", "topic": "Imperativo", "instruction": "Escolha a forma correta do imperativo.", "explain": "O imperativo usa o verbo na forma base, sem sujeito: \"Close\".", "prompt": "It's cold. ___ the window, please.", "options": ["Close", "Closes", "Closing", "To close"], "correctIndex": 0, "id": "bkA1-100"}, {"type": "gaps", "level": "A1", "topic": "Imperativo", "instruction": "Complete com o imperativo do verbo entre parênteses.", "explain": "Imperativo negativo: \"Don't\" + verbo base; afirmativo: só o verbo base (\"Be\").", "prompt": "___ (not / run) in the hallway! ___ (be) quiet in the library.", "answers": [["Do not run", "Don't run"], ["Be"]], "id": "bkA1-101"}, {"type": "choose", "level": "A1", "topic": "Imperativo", "instruction": "Escolha a forma correta.", "explain": "No imperativo usamos o verbo na forma base: \"sit\", \"open\".", "prompt": "Please [sit*/sits] down and [open*/opening] your books.", "id": "bkA1-102"}, {"type": "error", "level": "A1", "topic": "Imperativo", "instruction": "Encontre o erro e corrija.", "explain": "O imperativo negativo sempre usa \"Don't\" (Do not), nunca \"Doesn't\".", "sentence": "Doesn't touch the oven. It's hot!", "wrong": "Doesn't", "fix": ["Don't", "Do not"], "id": "bkA1-103"}, {"type": "rewrite", "level": "A1", "topic": "Imperativo", "instruction": "Reescreva a frase na forma negativa.", "explain": "Imperativo negativo: \"Don't\" + verbo base.", "prompt": "Open the door.", "accept": ["Don't open the door.", "Do not open the door."], "id": "bkA1-104"}, {"type": "order", "level": "A1", "topic": "Imperativo", "instruction": "Ordene as palavras para formar uma instrução.", "explain": "O imperativo começa com o verbo: \"Turn left...\".", "words": ["Turn", "left", "at", "the", "next", "street"], "id": "bkA1-105"}, {"type": "match", "level": "A1", "topic": "Imperativo", "instruction": "Ligue cada situação ao conselho adequado.", "explain": "Frio→casaco; fome→sanduíche; cansaço→dormir cedo; atraso→\"Hurry up!\" (depressa).", "left": ["I'm cold.", "I'm hungry.", "I'm tired.", "I'm late!"], "right": ["Go to bed early.", "Hurry up!", "Put on a jacket.", "Eat a sandwich."], "correctMap": [2, 3, 0, 1], "id": "bkA1-106"}, {"type": "tf", "level": "A1", "topic": "Imperativo", "instruction": "Leia as regras e marque verdadeiro (true) ou falso (false).", "explain": "As regras mandam tomar banho antes, não correr, crianças com adulto, e a piscina fecha às 20h.", "text": "Pool rules: Take a shower before you swim. Don't run near the pool. Don't eat in the water. Children under 10: swim with an adult. The pool closes at 8 p.m.", "items": [{"s": "You can run near the pool.", "a": false}, {"s": "Swimmers take a shower before they swim.", "a": true}, {"s": "A 7-year-old child can swim alone.", "a": false}, {"s": "The pool closes at 8 p.m.", "a": true}], "id": "bkA1-107"}, {"type": "dorder", "level": "A1", "topic": "Imperativo", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pede a direção, B dá instruções no imperativo, A pergunta a distância e agradece.", "lines": ["A: Excuse me, where is the train station?", "B: Go straight and turn right at the bank.", "A: Is it far?", "B: No, it's close. Walk for five minutes.", "A: Thanks a lot!"], "id": "bkA1-108"}, {"type": "sort", "level": "A1", "topic": "Imperativo", "instruction": "Separe as frases: imperativo afirmativo ou negativo?", "explain": "O negativo começa com \"Don't\"; o afirmativo começa com o verbo base.", "prompt": "Sort the sentences: affirmative or negative?", "groups": ["Afirmativo", "Negativo"], "items": [{"w": "Sit down.", "g": 0}, {"w": "Don't talk.", "g": 1}, {"w": "Listen!", "g": 0}, {"w": "Don't worry.", "g": 1}, {"w": "Come here.", "g": 0}, {"w": "Don't be late.", "g": 1}], "id": "bkA1-109"}, {"type": "mcq", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Escolha a preposição correta.", "explain": "Com horas usamos \"at\": \"at 3 p.m.\".", "prompt": "The meeting is ___ 3 p.m.", "options": ["in", "on", "at", "to"], "correctIndex": 2, "id": "bkA1-110"}, {"type": "gaps", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Complete com in, on ou at.", "explain": "Datas usam \"on\"; partes do dia usam \"in the morning\"; \"noon\" usa \"at\".", "prompt": "My birthday is ___ April 5th. I go to school ___ the morning. We have lunch ___ noon.", "answers": [["on"], ["in"], ["at"]], "id": "bkA1-111"}, {"type": "choose", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Escolha a preposição correta.", "explain": "\"On\" = sobre uma superfície (table); \"in\" = dentro (box).", "prompt": "The keys are [on*/at] the table, and the cat is [in*/at] the box.", "id": "bkA1-112"}, {"type": "error", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Encontre o erro e corrija.", "explain": "Com dias da semana usamos \"on\": \"on Sundays\".", "sentence": "We don't work in Sundays.", "wrong": "in", "fix": ["on"], "id": "bkA1-113"}, {"type": "sort", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Separe as expressões de tempo: in, on ou at?", "explain": "\"In\" para meses, anos, estações; \"on\" para dias e datas; \"at\" para horas e \"night\".", "prompt": "Sort the time words: in, on or at?", "groups": ["in", "on", "at"], "items": [{"w": "July", "g": 0}, {"w": "2025", "g": 0}, {"w": "Monday", "g": 1}, {"w": "my birthday", "g": 1}, {"w": "7 o'clock", "g": 2}, {"w": "night", "g": 2}, {"w": "the summer", "g": 0}, {"w": "Christmas Day", "g": 1}], "id": "bkA1-114"}, {"type": "order", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Cidades e estados usam \"in\": \"in a small town in Minas Gerais\".", "words": ["She", "lives", "in", "a", "small", "town", "in", "Minas", "Gerais"], "id": "bkA1-115"}, {"type": "match", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Ligue cada expressão à preposição correta.", "explain": "Dizemos \"at night\", \"on Saturday\" e \"in the morning\".", "left": ["night", "Saturday", "the morning"], "right": ["in", "at", "on"], "correctMap": [1, 2, 0], "id": "bkA1-116"}, {"type": "reading", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Leia a mensagem e responda às perguntas.", "explain": "A festa é no sábado, na casa da Camila, e Nina chega às 8h30.", "text": "Hi Leo! The party for Nina is on Saturday at 8 p.m. It's at my house, on Flores Street. Please bring a drink. Nina arrives at 8:30, so don't be late! See you! Camila", "questions": [{"q": "What day is the party?", "options": ["On Friday", "On Saturday", "On Sunday"], "correctIndex": 1}, {"q": "What time does Nina arrive?", "options": ["At 8:30", "At 8:00", "In the morning"], "correctIndex": 0}, {"q": "Where is the party?", "options": ["At Nina's house", "At a restaurant", "At Camila's house"], "correctIndex": 2}], "id": "bkA1-117"}, {"type": "blank", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Complete com in, on ou at.", "explain": "Com países usamos \"in\": \"in Brazil\".", "prompt": "I live ___ Brazil.", "accept": ["in"], "id": "bkA1-118"}, {"type": "tf", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "Tiago estuda segundas e quartas às 19h, trabalha nos fins de semana e viaja no verão.", "text": "Tiago is a student in Belém. He has classes on Mondays and Wednesdays. His classes start at 7 p.m. On weekends, he works at a restaurant. In the summer, he travels with his family.", "items": [{"s": "Tiago has classes on Tuesdays.", "a": false}, {"s": "His classes start in the evening.", "a": true}, {"s": "He works on weekends.", "a": true}, {"s": "He travels in the winter.", "a": false}], "id": "bkA1-119"}, {"type": "mcq", "level": "A1", "topic": "Verbo To Be", "instruction": "Escolha a forma correta do verbo to be.", "explain": "Com \"I\" usamos sempre \"am\".", "prompt": "I ___ hungry. Can we eat now?", "options": ["am", "is", "are", "be"], "correctIndex": 0, "id": "bkA1-120"}, {"type": "mcq", "level": "A1", "topic": "Verbo To Be", "instruction": "Escolha a palavra que começa a pergunta.", "explain": "\"The museum\" é singular, então a pergunta começa com \"Is\".", "prompt": "___ the museum open on Mondays?", "options": ["Is", "Are", "Am", "Be"], "correctIndex": 0, "id": "bkA1-121"}, {"type": "mcq", "level": "A1", "topic": "Verbo To Be", "instruction": "Escolha a forma correta para falar a idade.", "explain": "Em inglês, idade usa o verbo to be: \"She is 19\", nunca \"has\".", "prompt": "Luana ___ nineteen years old.", "options": ["is", "has", "have", "are"], "correctIndex": 0, "id": "bkA1-122"}, {"type": "gaps", "level": "A1", "topic": "Verbo To Be", "instruction": "Complete o diálogo com am, is ou are (afirmativo ou negativo).", "explain": "Com \"I\" usamos \"am\"; com \"you\", \"are\". A resposta curta negativa é \"I'm not\".", "prompt": "A: Hi, I ___ Renata, the new designer.\nB: Nice to meet you! I ___ Marcos. ___ you from Recife?\nA: No, I ___. I'm from Natal.", "answers": [["am"], ["am"], ["Are"], ["am not", "'m not"]], "id": "bkA1-123"}, {"type": "gaps", "level": "A1", "topic": "Verbo To Be", "instruction": "Complete o texto com is ou are.", "explain": "\"Phone\", \"camera\", \"screen\" e \"it\" são singulares (is); \"apps\" é plural (are).", "prompt": "My new phone ___ great. The camera ___ excellent, and the apps ___ fast. The screen ___ big, but it ___ not heavy.", "answers": [["is"], ["is"], ["are"], ["is"], ["is"]], "id": "bkA1-124"}, {"type": "choose", "level": "A1", "topic": "Verbo To Be", "instruction": "Clique na forma correta do verbo to be.", "explain": "\"The children\" é plural (are); \"the baby\" é singular (is).", "prompt": "The children [is/are*] at school, but the baby [is*/are] at home with me.", "id": "bkA1-125"}, {"type": "choose", "level": "A1", "topic": "Verbo To Be", "instruction": "Clique na forma correta do verbo to be.", "explain": "\"You and Rita\" é plural: pergunta com \"Are\" e resposta com \"we are\".", "prompt": "[Am/Are*] you and Rita cousins? Yes, we [are*/is].", "id": "bkA1-126"}, {"type": "error", "level": "A1", "topic": "Verbo To Be", "instruction": "Encontre o erro na frase.", "explain": "\"Agree\" já é verbo; não se usa \"am\" antes dele: \"I agree\".", "sentence": "I am agree with you.", "wrong": "am agree", "fix": ["agree"], "id": "bkA1-127"}, {"type": "error", "level": "A1", "topic": "Verbo To Be", "instruction": "Encontre o erro na frase.", "explain": "Com \"she\" a pergunta começa com \"Is\", não \"Are\".", "sentence": "Are she your teacher?", "wrong": "Are", "fix": ["Is"], "id": "bkA1-128"}, {"type": "rewrite", "level": "A1", "topic": "Verbo To Be", "instruction": "Transforme em pergunta.", "explain": "Na pergunta com to be, o verbo vem antes do sujeito: \"Is Diego...?\"", "prompt": "Diego is at work.", "start": "Is", "accept": ["Is Diego at work?"], "id": "bkA1-129"}, {"type": "rewrite", "level": "A1", "topic": "Verbo To Be", "instruction": "Reescreva na forma negativa.", "explain": "Na negativa, \"not\" vem depois do verbo to be: \"are not\" ou \"aren't\".", "prompt": "We are hungry.", "accept": ["We are not hungry.", "We aren't hungry.", "We're not hungry."], "id": "bkA1-130"}, {"type": "order", "level": "A1", "topic": "Verbo To Be", "instruction": "Ordene as palavras para formar uma frase negativa.", "explain": "Negativa com to be: sujeito + are + not + resto da frase.", "words": ["My", "parents", "are", "not", "at", "home", "today"], "alt": ["Today my parents are not at home", "Today, my parents are not at home"], "id": "bkA1-131"}, {"type": "order", "level": "A1", "topic": "Verbo To Be", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Na pergunta, \"Are\" vem antes do sujeito \"you\".", "words": ["Are", "you", "a", "nurse", "or", "a", "doctor"], "alt": ["Are you a doctor or a nurse"], "id": "bkA1-132"}, {"type": "match", "level": "A1", "topic": "Verbo To Be", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "A resposta curta repete o verbo to be e o pronome da pergunta.", "left": ["Is Pedro your brother?", "Are you from Manaus?", "Is the soup hot?", "Are we late?"], "right": ["Yes, it is. Be careful!", "No, he's my cousin.", "No, we aren't. It's only 7:55.", "Yes, I am."], "correctMap": [1, 3, 0, 2], "id": "bkA1-133"}, {"type": "sort", "level": "A1", "topic": "Verbo To Be", "instruction": "Separe as frases em certas e erradas.", "explain": "Idade, fome, frio e ter razão usam \"be\" em inglês, não \"have\".", "prompt": "Is the sentence correct?", "groups": ["Correta", "Errada"], "items": [{"w": "I am 30 years old.", "g": 0}, {"w": "I have 30 years.", "g": 1}, {"w": "She is hungry.", "g": 0}, {"w": "She has hunger.", "g": 1}, {"w": "They are right.", "g": 0}, {"w": "They have reason.", "g": 1}, {"w": "I am cold.", "g": 0}, {"w": "I have cold.", "g": 1}], "id": "bkA1-134"}, {"type": "odd", "level": "A1", "topic": "Verbo To Be", "instruction": "Qual palavra NÃO é uma forma do verbo to be?", "explain": "\"Am\", \"is\" e \"are\" são formas de \"be\"; \"do\" é outro verbo.", "prompt": "Which word is not a form of \"be\"?", "options": ["am", "is", "are", "do"], "correctIndex": 3, "id": "bkA1-135"}, {"type": "tf", "level": "A1", "topic": "Verbo To Be", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O texto diz que Igor é motorista, os gêmeos têm 8 anos e a família não é rica.", "text": "This is Fernanda. She is a nurse in Florianópolis. Her husband, Igor, is a taxi driver. Their children are twins, and they are eight years old. The family is not rich, but they are very happy.", "items": [{"s": "Igor is a nurse.", "a": false}, {"s": "The twins are eight years old.", "a": true}, {"s": "The family is rich.", "a": false}, {"s": "Fernanda and her family are happy.", "a": true}], "id": "bkA1-136"}, {"type": "reading", "level": "A1", "topic": "Verbo To Be", "instruction": "Leia o perfil e responda.", "explain": "O perfil diz: 34 anos, \"I'm not married\" e Caio e Léo são colegas de trabalho.", "text": "Name: Samuel Costa. Age: 34. City: Belo Horizonte. I'm a software developer. I'm not married. My favorite sport is volleyball. My best friends are Caio and Léo. They're my coworkers.", "questions": [{"q": "How old is Samuel?", "options": ["24", "34", "43"], "correctIndex": 1}, {"q": "Is Samuel married?", "options": ["Yes, he is.", "No, he isn't.", "We don't know."], "correctIndex": 1}, {"q": "Who are Caio and Léo?", "options": ["Samuel's brothers", "Samuel's neighbors", "Samuel's coworkers"], "correctIndex": 2}], "id": "bkA1-137"}, {"type": "dorder", "level": "A1", "topic": "Verbo To Be", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Primeiro a pergunta de identificação, depois a apresentação e, por fim, a pergunta sobre o hotel.", "lines": ["A: Excuse me, are you Mr. Tanaka?", "B: Yes, I am. Are you from the hotel?", "A: Yes, I'm Bruno, your driver. Welcome to Rio!", "B: Thank you. Is the hotel far from here?", "A: No, it isn't. It's twenty minutes by car."], "id": "bkA1-138"}, {"type": "blank", "level": "A1", "topic": "Verbo To Be", "instruction": "Complete com am, is ou are.", "explain": "\"My glasses\" é plural, então usamos \"are\".", "prompt": "Where ___ my glasses? I can't see!", "accept": ["are"], "id": "bkA1-139"}, {"type": "mcq", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Escolha o pronome correto.", "explain": "Depois do verbo (\"talk to\") usamos o pronome objeto; Paula é mulher: \"her\".", "prompt": "Where is Paula? I need to talk to ___.", "options": ["she", "her", "hers", "him"], "correctIndex": 1, "id": "bkA1-140"}, {"type": "mcq", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Escolha o pronome sujeito correto.", "explain": "\"My grandparents\" = they. Antes do verbo, usamos pronome sujeito.", "prompt": "My grandparents live in Bahia. ___ have a big farm.", "options": ["They", "Them", "Their", "He"], "correctIndex": 0, "id": "bkA1-141"}, {"type": "mcq", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Escolha o sujeito correto.", "explain": "Em inglês a frase precisa de sujeito; para o tempo usamos \"it\": \"It is raining\".", "prompt": "___ is very hot today. Let's go to the beach!", "options": ["It", "They", "We", "Them"], "correctIndex": 0, "id": "bkA1-142"}, {"type": "gaps", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Complete com o pronome certo (sujeito ou objeto).", "explain": "\"He\" é sujeito; depois de \"help\" usamos objeto: \"him\" e \"me\".", "prompt": "Rafael is my neighbor. ___ is very nice. I often help ___ with his car, and he helps ___ with my computer.", "answers": [["He"], ["him"], ["me"]], "id": "bkA1-143"}, {"type": "gaps", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Complete com o pronome da palavra entre parênteses.", "explain": "Depois do verbo usamos objeto (them, her); antes do verbo, sujeito (they).", "prompt": "A: Do you know Bia and Caio?\nB: Yes, I know ___ (they) very well. ___ (they) are my cousins.\nA: Is Bia your favorite cousin?\nB: Yes! I love ___ (she).", "answers": [["them"], ["They"], ["her"]], "id": "bkA1-144"}, {"type": "choose", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Clique no pronome correto.", "explain": "Como sujeito dizemos \"my dad and I\"; depois do verbo \"helps\" usamos \"us\".", "prompt": "My dad and [I*/me] cook dinner on Fridays, and Mom sometimes helps [we/us*].", "id": "bkA1-145"}, {"type": "choose", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Clique na palavra correta.", "explain": "Depois de \"for\" usamos pronome objeto (you); \"message\" é singular: \"it\".", "prompt": "This message is for [you*/your]. Please read [it*/them] now.", "id": "bkA1-146"}, {"type": "error", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Encontre o erro na frase.", "explain": "Como sujeito, usamos \"Julia and I\" (e por educação o \"I\" vem por último).", "sentence": "Me and Julia are in the same class.", "wrong": "Me and Julia", "fix": ["Julia and I"], "id": "bkA1-147"}, {"type": "error", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Encontre o erro na frase.", "explain": "Depois do verbo \"gives\" usamos pronome objeto: \"us\", não \"we\".", "sentence": "The teacher gives we a lot of homework.", "wrong": "we", "fix": ["us"], "id": "bkA1-148"}, {"type": "rewrite", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Troque \"Lucas and I\" pelo pronome sujeito correto.", "explain": "\"Lucas and I\" (eu + outra pessoa) = \"we\".", "prompt": "Lucas and I watch movies on Fridays.", "accept": ["We watch movies on Fridays.", "On Fridays we watch movies.", "On Fridays, we watch movies."], "id": "bkA1-149"}, {"type": "rewrite", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Troque \"your mother\" por um pronome objeto.", "explain": "\"Your mother\" é mulher e vem depois do verbo: \"her\".", "prompt": "Call your mother tonight.", "accept": ["Call her tonight.", "Tonight call her.", "Tonight, call her."], "id": "bkA1-150"}, {"type": "order", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Depois de \"help\" vem o pronome objeto \"us\".", "words": ["Can", "you", "help", "us", "with", "the", "boxes"], "id": "bkA1-151"}, {"type": "order", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Ordem: sujeito (They) + verbo + objeto (him) + coisa (a message).", "words": ["They", "send", "him", "a", "message", "every", "morning"], "alt": ["Every morning they send him a message", "Every morning, they send him a message"], "id": "bkA1-152"}, {"type": "match", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Ligue cada frase à continuação certa.", "explain": "O pronome combina com a palavra anterior: Marta = she, shoes = them, coffee = it, Pedro = him.", "left": ["Marta is a doctor.", "Where are my shoes?", "Here is your coffee.", "I miss Pedro."], "right": ["I can't find them.", "Drink it now.", "She works at a hospital.", "I want to see him."], "correctMap": [2, 0, 1, 3], "id": "bkA1-153"}, {"type": "sort", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Separe as palavras pelo pronome que as substitui.", "explain": "Homem = he/him; mulher = she/her; mais de uma pessoa ou coisa = they/them.", "prompt": "Which pronouns replace these words?", "groups": ["he / him", "she / her", "they / them"], "items": [{"w": "my uncle", "g": 0}, {"w": "Grandma", "g": 1}, {"w": "the boys", "g": 2}, {"w": "Mr. Silva", "g": 0}, {"w": "my sister", "g": 1}, {"w": "Ana and Rui", "g": 2}, {"w": "Aunt Rosa", "g": 1}, {"w": "my grandfather", "g": 0}], "id": "bkA1-154"}, {"type": "odd", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Encontre a palavra diferente.", "explain": "\"He\", \"she\" e \"we\" são pronomes sujeito; \"them\" é pronome objeto.", "prompt": "Which pronoun is different?", "options": ["he", "she", "we", "them"], "correctIndex": 3, "id": "bkA1-155"}, {"type": "dorder", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Coloque o diálogo na ordem certa.", "explain": "A pergunta por Carla vem primeiro; depois se fala do celular e de devolver a ela.", "lines": ["A: Hi, Leo! Is Carla with you?", "B: No, she's at work. Why?", "A: I have her phone. It's here in my bag.", "B: Oh! Give it to me. I can take it to her."], "id": "bkA1-156"}, {"type": "reading", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Leia a mensagem e responda.", "explain": "Gabi está com Marcos, ele tem as chaves, e ela pede dois sanduíches.", "text": "Hi Duda! I'm at the gym with Marcos. He has my keys, so please wait for us at the café. Can you buy two sandwiches for us? I can pay you later. Thanks! Gabi", "questions": [{"q": "Who is with Gabi?", "options": ["Duda", "Marcos", "Nobody"], "correctIndex": 1}, {"q": "Who has Gabi's keys?", "options": ["Marcos", "Duda", "The café"], "correctIndex": 0}, {"q": "What does Gabi want Duda to buy?", "options": ["Two coffees", "New keys", "Two sandwiches"], "correctIndex": 2}], "id": "bkA1-157"}, {"type": "tf", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O texto diz que Ícaro os visita em dezembro, Otto é chef e cozinha, e Lia lava a louça.", "text": "My name is Ícaro. I have a sister, Lia. She lives in Belém with her husband, Otto. I visit them every December. Otto is a chef, and he cooks for us every night. Lia doesn't cook, but she washes the dishes.", "items": [{"s": "Ícaro visits Lia and Otto in December.", "a": true}, {"s": "Lia cooks every night.", "a": false}, {"s": "Otto is a chef.", "a": true}], "id": "bkA1-158"}, {"type": "blank", "level": "A1", "topic": "Pronomes (sujeito/objeto)", "instruction": "Complete com o pronome certo.", "explain": "\"My phone\" é uma coisa e vem depois do verbo: \"it\".", "prompt": "Where is my phone? I can't find ___.", "accept": ["it"], "id": "bkA1-159"}, {"type": "mcq", "level": "A1", "topic": "Possessivos", "instruction": "Escolha o possessivo correto.", "explain": "O dono é Mariana (mulher), então \"her\", mesmo que o irmão seja homem.", "prompt": "Mariana loves ___ brother.", "options": ["his", "her", "she", "hers"], "correctIndex": 1, "id": "bkA1-160"}, {"type": "mcq", "level": "A1", "topic": "Possessivos", "instruction": "Escolha o possessivo correto.", "explain": "O dono é Paulo (homem), então \"his\", mesmo que \"mãe\" seja feminino.", "prompt": "Paulo calls ___ mother every day.", "options": ["his", "her", "he", "him"], "correctIndex": 0, "id": "bkA1-161"}, {"type": "mcq", "level": "A1", "topic": "Possessivos", "instruction": "Escolha a palavra correta.", "explain": "Sem substantivo depois, usamos o pronome possessivo \"mine\".", "prompt": "Is this your umbrella? No, it isn't ___.", "options": ["my", "mine", "me", "I"], "correctIndex": 1, "id": "bkA1-162"}, {"type": "gaps", "level": "A1", "topic": "Possessivos", "instruction": "Complete com o possessivo da palavra entre parênteses.", "explain": "Antes de substantivo: \"your\"; sozinho no fim da frase: \"mine\".", "prompt": "A: Is this ___ (you) bag?\nB: No, it's not ___ (I). It's Laura's.\nA: Are you sure? It's the same color as ___ (you) old bag.", "answers": [["your"], ["mine"], ["your"]], "id": "bkA1-163"}, {"type": "gaps", "level": "A1", "topic": "Possessivos", "instruction": "Complete o texto com as palavras do quadro.", "explain": "I = my; Sol = her; Nico = his; \"my parents and I\" = our.", "prompt": "I'm Tomás, and this is ___ blog. My sister Sol lives in Canada with ___ husband. My brother Nico loves ___ new bike. My parents and I live in Santiago. ___ apartment is small but nice.", "answers": [["my"], ["her"], ["his"], ["Our"]], "bank": ["my", "her", "his", "our", "their", "your"], "id": "bkA1-164"}, {"type": "choose", "level": "A1", "topic": "Possessivos", "instruction": "Clique na palavra correta.", "explain": "Sozinho, no fim da frase: \"yours\"; antes de substantivo: \"my\".", "prompt": "Is this jacket [your/yours*]? No, [my*/mine] jacket is black.", "id": "bkA1-165"}, {"type": "choose", "level": "A1", "topic": "Possessivos", "instruction": "Clique na palavra correta.", "explain": "\"Its\" (sem apóstrofo) é possessivo; \"it's\" = it is. \"Their\" é possessivo; \"there\" = lá.", "prompt": "The dog is eating [its*/it's] food, and the cats are sleeping in [their*/there] beds.", "id": "bkA1-166"}, {"type": "error", "level": "A1", "topic": "Possessivos", "instruction": "Encontre o erro na frase.", "explain": "Em inglês não se usa artigo antes do possessivo: \"my car\", não \"the my car\".", "sentence": "The my car is in the garage.", "wrong": "The my", "fix": ["My"], "id": "bkA1-167"}, {"type": "error", "level": "A1", "topic": "Possessivos", "instruction": "Encontre o erro na frase.", "explain": "A esposa é do Leo (homem), então o possessivo é \"his\".", "sentence": "My brother's name is Leo, and her wife is Kátia.", "wrong": "her wife", "fix": ["his wife"], "id": "bkA1-168"}, {"type": "rewrite", "level": "A1", "topic": "Possessivos", "instruction": "Reescreva usando o pronome possessivo.", "explain": "\"Her phone\" vira \"hers\" quando o possessivo fica sozinho no fim.", "prompt": "This is her phone.", "start": "This phone is", "accept": ["This phone is hers."], "id": "bkA1-169"}, {"type": "rewrite", "level": "A1", "topic": "Possessivos", "instruction": "Reescreva usando o adjetivo possessivo.", "explain": "\"Ours\" vira \"our\" quando vem antes do substantivo \"bikes\".", "prompt": "Those bikes are ours.", "start": "Those are", "accept": ["Those are our bikes."], "id": "bkA1-170"}, {"type": "order", "level": "A1", "topic": "Possessivos", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta com to be: \"Is\" + \"this coffee\" + \"yours or mine\".", "words": ["Is", "this", "coffee", "yours", "or", "mine"], "alt": ["Is this coffee mine or yours"], "id": "bkA1-171"}, {"type": "order", "level": "A1", "topic": "Possessivos", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "\"Your sister's name\" = o nome da sua irmã; a pergunta começa com \"What is\".", "words": ["What", "is", "your", "sister's", "name"], "id": "bkA1-172"}, {"type": "match", "level": "A1", "topic": "Possessivos", "instruction": "Ligue cada frase ao possessivo certo.", "explain": "I = my, Ana = her, Tom = his, we = our, the kids = their.", "left": ["I have a cat.", "Ana has a cat.", "Tom has a cat.", "We have a cat.", "The kids have a cat."], "right": ["It's our cat.", "It's his cat.", "It's their cat.", "It's my cat.", "It's her cat."], "correctMap": [3, 4, 1, 0, 2], "id": "bkA1-173"}, {"type": "sort", "level": "A1", "topic": "Possessivos", "instruction": "Separe: vem antes de substantivo ou fica sozinho?", "explain": "\"My, your, her, our\" vêm antes do substantivo; \"mine, yours, hers, ours\" ficam sozinhos.", "prompt": "Before a noun or alone?", "groups": ["Antes do substantivo (my book)", "Sozinho (It's mine.)"], "items": [{"w": "my", "g": 0}, {"w": "mine", "g": 1}, {"w": "your", "g": 0}, {"w": "yours", "g": 1}, {"w": "her", "g": 0}, {"w": "hers", "g": 1}, {"w": "our", "g": 0}, {"w": "ours", "g": 1}], "id": "bkA1-174"}, {"type": "odd", "level": "A1", "topic": "Possessivos", "instruction": "Encontre a palavra diferente.", "explain": "\"Her\", \"our\" e \"their\" são possessivos; \"we\" é pronome sujeito.", "prompt": "Which word is not a possessive?", "options": ["her", "our", "their", "we"], "correctIndex": 3, "id": "bkA1-175"}, {"type": "tf", "level": "A1", "topic": "Possessivos", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "A fazenda é do tio, o cavalo é do pai, o chapéu é da mãe e os cães são dos irmãos.", "text": "Hi, I'm Yasmin. This is a photo of my family at a farm in Goiás. My father is next to his horse, Trovão. My mother has her favorite hat. My brothers are with their dogs. The farm isn't ours; it's my uncle's.", "items": [{"s": "The farm is Yasmin's uncle's.", "a": true}, {"s": "The horse is Yasmin's.", "a": false}, {"s": "Yasmin's brothers have dogs.", "a": true}, {"s": "The hat is Yasmin's father's.", "a": false}], "id": "bkA1-176"}, {"type": "dorder", "level": "A1", "topic": "Possessivos", "instruction": "Coloque o diálogo na ordem certa.", "explain": "O guarda pergunta a Lia, ela indica o homem, e o homem confirma que a mala é dele.", "lines": ["Guard: Excuse me, is this suitcase yours?", "Lia: No, mine is red. Maybe it's that man's.", "Guard: Sir! Is this your suitcase?", "Man: Yes, it's mine! Thank you so much."], "id": "bkA1-177"}, {"type": "reading", "level": "A1", "topic": "Possessivos", "instruction": "Leia o aviso e responda.", "explain": "O texto diz: quarto no segundo andar, a chave abre o quarto e a porta, cozinha para todos.", "text": "Welcome to our hostel in Paraty! Your room is on the second floor. Your key opens your room and the front door. The kitchen is for all guests, but please wash your dishes. Our breakfast is from 7 to 10.", "questions": [{"q": "Where is the room?", "options": ["On the first floor", "On the second floor", "On the third floor"], "correctIndex": 1}, {"q": "What does the key open?", "options": ["The room and the front door", "Only the room", "The kitchen"], "correctIndex": 0}, {"q": "Who can use the kitchen?", "options": ["Only the staff", "Nobody", "All guests"], "correctIndex": 2}], "id": "bkA1-178"}, {"type": "blank", "level": "A1", "topic": "Possessivos", "instruction": "Complete com o possessivo da palavra entre parênteses.", "explain": "\"We\" vira \"our\" antes de substantivo.", "prompt": "We love ___ (we) new neighbors.", "accept": ["our"], "id": "bkA1-179"}, {"type": "mcq", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Escolha a palavra correta.", "explain": "Ao telefone, para se apresentar, usamos \"This is...\".", "prompt": "Hello? ___ is Marina. Can I talk to Pedro?", "options": ["This", "These", "Those", "They"], "correctIndex": 0, "id": "bkA1-180"}, {"type": "mcq", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Escolha a palavra correta.", "explain": "\"Stars\" é plural e está longe (no céu): \"those\".", "prompt": "Look at ___ stars in the sky tonight!", "options": ["this", "that", "those", "it"], "correctIndex": 2, "id": "bkA1-181"}, {"type": "mcq", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Escolha a palavra correta.", "explain": "\"Tomatoes\" é plural e está perto (na minha cesta): \"these\".", "prompt": "How much are ___ tomatoes here in my basket?", "options": ["this", "that", "these", "those"], "correctIndex": 2, "id": "bkA1-182"}, {"type": "gaps", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Complete o diálogo com this, that, these ou those.", "explain": "Perto e singular: this; longe e plural: those. Na resposta, \"they\" ou \"those\" retomam \"jeans\".", "prompt": "A: How much is ___ T-shirt here, in my hand?\nB: It's forty reais.\nA: And ___ jeans over there?\nB: ___ are ninety reais.", "answers": [["this"], ["those"], ["They", "Those"]], "id": "bkA1-183"}, {"type": "gaps", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Complete com this, that, these ou those.", "explain": "Perto e singular: \"this\"; longe e plural: \"those\".", "prompt": "Mom, ___ is my friend Theo, here with me. And ___ are his parents, over there by the car.", "answers": [["this"], ["those"]], "id": "bkA1-184"}, {"type": "choose", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Clique na palavra correta.", "explain": "\"Pizza\" é singular (this); \"fries\" é plural (those).", "prompt": "[This*/These] pizza is delicious, but [that/those*] fries are cold.", "id": "bkA1-185"}, {"type": "choose", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Clique na palavra correta.", "explain": "\"Glasses\" (óculos) é plural: perto = these, longe = those.", "prompt": "Are [this/these*] your glasses? No, [that/those*] are my glasses, on the table over there.", "id": "bkA1-186"}, {"type": "error", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Encontre o erro na frase.", "explain": "\"Laptop\" é singular, então usamos \"This\" (ou \"That\"), não \"These\".", "sentence": "These is my new laptop.", "wrong": "These", "fix": ["This", "That"], "id": "bkA1-187"}, {"type": "error", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Encontre o erro na frase.", "explain": "\"Child\" é singular e está longe: \"That\", não \"Those\".", "sentence": "Those child over there is my son.", "wrong": "Those", "fix": ["That"], "id": "bkA1-188"}, {"type": "rewrite", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Reescreva a frase no plural.", "explain": "O plural de \"that\" é \"those\"; \"bag\" vira \"bags\" e \"is\" vira \"are\".", "prompt": "That bag is heavy.", "start": "Those", "accept": ["Those bags are heavy."], "id": "bkA1-189"}, {"type": "rewrite", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Transforme em pergunta.", "explain": "Na pergunta, \"are\" vem antes de \"these\".", "prompt": "These are Ana's shoes.", "start": "Are", "accept": ["Are these Ana's shoes?"], "id": "bkA1-190"}, {"type": "order", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "\"That\" + \"over there\" = algo longe; a pergunta começa com \"Is\".", "words": ["Is", "that", "your", "brother", "over", "there"], "id": "bkA1-191"}, {"type": "order", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"These\" combina com o plural \"photos\".", "words": ["I", "love", "these", "old", "photos", "of", "my", "grandparents"], "id": "bkA1-192"}, {"type": "match", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "Cada resposta combina com o objeto ou as pessoas da pergunta.", "left": ["What's this?", "Who are those people?", "Are these seats free?", "Is that your dog?"], "right": ["They're my neighbors.", "Yes, you can sit here.", "It's a gift for you.", "No, it's my sister's."], "correctMap": [2, 0, 1, 3], "id": "bkA1-193"}, {"type": "sort", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Separe as palavras: perto ou longe?", "explain": "\"This, these, here\" = perto; \"that, those, there\" = longe.", "prompt": "Near or far?", "groups": ["Perto (near)", "Longe (far)"], "items": [{"w": "this", "g": 0}, {"w": "that", "g": 1}, {"w": "these", "g": 0}, {"w": "those", "g": 1}, {"w": "here", "g": 0}, {"w": "there", "g": 1}], "id": "bkA1-194"}, {"type": "odd", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Encontre a palavra diferente.", "explain": "\"This\", \"that\" e \"those\" são demonstrativos; \"there\" indica lugar (lá).", "prompt": "Which word is not a demonstrative?", "options": ["this", "that", "those", "there"], "correctIndex": 3, "id": "bkA1-195"}, {"type": "tf", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "\"This painting here\" está perto; \"that painting over there\" está longe; não se senta nas cadeiras.", "text": "Guide: Good morning, everyone! This painting here is from 1920. That big painting over there is by Portinari. These chairs are very old, so please don't sit on them. Those doors at the end go to the café.", "items": [{"s": "The painting near the guide is from 1920.", "a": true}, {"s": "The Portinari painting is near the guide.", "a": false}, {"s": "Visitors can sit on the old chairs.", "a": false}, {"s": "The café is behind those doors.", "a": true}], "id": "bkA1-196"}, {"type": "dorder", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Primeiro o cumprimento, depois as perguntas de preço e as respostas.", "lines": ["A: Good morning! Can I help you?", "B: Yes. How much are these rolls?", "A: They're fifty cents each.", "B: OK, six rolls, please. And is that cake fresh?", "A: Yes, it's from today."], "id": "bkA1-197"}, {"type": "blank", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Complete com this, that, these ou those.", "explain": "\"Car\" é singular e está longe (over there): \"That\".", "prompt": "Look! ___ car over there is just like mine.", "accept": ["That"], "id": "bkA1-198"}, {"type": "reading", "level": "A1", "topic": "Demonstrativos (this/that/these/those)", "instruction": "Leia a mensagem e responda.", "explain": "As mangas estão perto (these, here) e baratas; os abacates estão longe (those); o abacaxi é doce.", "text": "Hi Rita! I'm at the market. These mangoes here are very cheap today, only 5 reais a kilo. Those avocados at the other stand are very big, but they're expensive. Do you want this pineapple too? It's sweet. Joana", "questions": [{"q": "What is cheap today?", "options": ["The avocados", "The mangoes", "The pineapple"], "correctIndex": 1}, {"q": "Which fruit is far from Joana?", "options": ["The avocados", "The mangoes", "The pineapple"], "correctIndex": 0}, {"q": "What does Joana say about the pineapple?", "options": ["It's expensive.", "It's big.", "It's sweet."], "correctIndex": 2}], "id": "bkA1-199"}, {"type": "mcq", "level": "A1", "topic": "Artigos A / An", "instruction": "Escolha a palavra correta.", "explain": "Profissão no singular precisa de artigo; \"nurse\" começa com som de consoante: \"a\".", "prompt": "My mother is ___ nurse.", "options": ["a", "an", "some", "any"], "correctIndex": 0, "id": "bkA1-200"}, {"type": "mcq", "level": "A1", "topic": "Artigos A / An", "instruction": "Escolha a palavra correta.", "explain": "Em \"hour\" o \"h\" é mudo; o som inicial é de vogal, então \"an\".", "prompt": "I need ___ hour to finish this report.", "options": ["a", "an", "some", "many"], "correctIndex": 1, "id": "bkA1-201"}, {"type": "mcq", "level": "A1", "topic": "Artigos A / An", "instruction": "Qual está correto?", "explain": "\"European\" começa com som /ju/ (consoante), por isso \"a European\".", "prompt": "Which phrase is correct?", "options": ["a European city", "an European city", "a Asian city", "an big city"], "correctIndex": 0, "id": "bkA1-202"}, {"type": "gaps", "level": "A1", "topic": "Artigos A / An", "instruction": "Complete com a ou an.", "explain": "Som de vogal (engineer, Italian, apartment) = an; som de consoante (small) = a.", "prompt": "Gustavo is ___ engineer. He works for ___ Italian company in Joinville. He drives ___ small car and has ___ apartment near the river.", "answers": [["an"], ["an"], ["a"], ["an"]], "id": "bkA1-203"}, {"type": "gaps", "level": "A1", "topic": "Artigos A / An", "instruction": "Complete o diálogo com a ou an.", "explain": "\"Sandwich\" e \"glass\" começam com som de consoante (a); \"apple\" com vogal (an).", "prompt": "A: Do you want ___ sandwich?\nB: No, thanks. I just want ___ apple and ___ glass of water.", "answers": [["a"], ["an"], ["a"]], "id": "bkA1-204"}, {"type": "choose", "level": "A1", "topic": "Artigos A / An", "instruction": "Clique no artigo correto.", "explain": "\"Honest\" tem \"h\" mudo (an); \"good\" começa com consoante (a).", "prompt": "She is [a/an*] honest person and [a*/an] good friend.", "id": "bkA1-205"}, {"type": "choose", "level": "A1", "topic": "Artigos A / An", "instruction": "Clique no artigo correto.", "explain": "\"Useful\" começa com som /ju/ (a); \"English\" com som de vogal (an).", "prompt": "It is [a*/an] useful app for [a/an*] English student.", "id": "bkA1-206"}, {"type": "error", "level": "A1", "topic": "Artigos A / An", "instruction": "Encontre o erro na frase.", "explain": "Profissão no singular precisa de artigo: \"is a doctor\".", "sentence": "My father is doctor in Recife.", "wrong": "is doctor", "fix": ["is a doctor"], "id": "bkA1-207"}, {"type": "error", "level": "A1", "topic": "Artigos A / An", "instruction": "Encontre o erro na frase.", "explain": "\"Interview\" começa com som de vogal, então \"an interview\".", "sentence": "I have a interview tomorrow.", "wrong": "a interview", "fix": ["an interview"], "id": "bkA1-208"}, {"type": "rewrite", "level": "A1", "topic": "Artigos A / An", "instruction": "Reescreva no singular, usando a ou an.", "explain": "\"Orange\" começa com som de vogal: \"an orange\".", "prompt": "Those are oranges.", "start": "That is", "accept": ["That is an orange."], "id": "bkA1-209"}, {"type": "rewrite", "level": "A1", "topic": "Artigos A / An", "instruction": "Reescreva no singular, usando a ou an.", "explain": "\"Umbrella\" começa com som de vogal: \"an umbrella\".", "prompt": "I have two umbrellas.", "start": "I have", "accept": ["I have an umbrella."], "id": "bkA1-210"}, {"type": "order", "level": "A1", "topic": "Artigos A / An", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"English\" começa com vogal, por isso \"an English teacher\".", "words": ["She", "is", "an", "English", "teacher", "in", "Curitiba"], "alt": ["In Curitiba she is an English teacher", "In Curitiba, she is an English teacher"], "id": "bkA1-211"}, {"type": "order", "level": "A1", "topic": "Artigos A / An", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "\"University\" começa com som /ju/, então \"a university\".", "words": ["Is", "there", "a", "university", "in", "your", "city"], "id": "bkA1-212"}, {"type": "match", "level": "A1", "topic": "Artigos A / An", "instruction": "Ligue cada descrição à palavra certa.", "explain": "Repare no artigo: an hour, a university, an elephant, a uniform.", "left": ["It's sixty minutes.", "Students study there.", "It's a big gray animal.", "Police officers wear it."], "right": ["an elephant", "a uniform", "an hour", "a university"], "correctMap": [2, 3, 0, 1], "id": "bkA1-213"}, {"type": "sort", "level": "A1", "topic": "Artigos A / An", "instruction": "Separe as palavras: a, an ou sem artigo?", "explain": "Som de consoante = a; som de vogal = an; plural não usa a/an.", "prompt": "A, an or no article (plural)?", "groups": ["a", "an", "sem artigo"], "items": [{"w": "cat", "g": 0}, {"w": "idea", "g": 1}, {"w": "books", "g": 2}, {"w": "hour", "g": 1}, {"w": "year", "g": 0}, {"w": "friends", "g": 2}, {"w": "yellow bag", "g": 0}, {"w": "eggs", "g": 2}], "id": "bkA1-214"}, {"type": "odd", "level": "A1", "topic": "Artigos A / An", "instruction": "Qual palavra usa \"a\", e não \"an\"?", "explain": "\"Unit\" começa com som /ju/, então é \"a unit\"; as outras usam \"an\".", "prompt": "Which word takes \"a\", not \"an\"?", "options": ["uncle", "onion", "ice cream", "unit"], "correctIndex": 3, "id": "bkA1-215"}, {"type": "dorder", "level": "A1", "topic": "Artigos A / An", "instruction": "Coloque o diálogo na ordem certa.", "explain": "O cliente pede um quarto, escolhe o single e pergunta sobre o elevador.", "lines": ["A: Good evening. Do you have a room for tonight?", "B: Yes, we have a double room and a single room.", "A: A single room, please. Is there an elevator?", "B: Yes, there is. Your room is on the fourth floor."], "id": "bkA1-216"}, {"type": "tf", "level": "A1", "topic": "Artigos A / An", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Otávio é arquiteto (Sônia é veterinária), a casa é antiga e eles não têm carro.", "text": "Hi! I'm Otávio. I'm an architect, and my wife, Sônia, is a vet. We have a son and a daughter. We live in an old house near a park in Campinas. We have a dog, but we don't have a car.", "items": [{"s": "Otávio is a vet.", "a": false}, {"s": "Their house is old.", "a": true}, {"s": "They have a car.", "a": false}, {"s": "They live near a park.", "a": true}], "id": "bkA1-217"}, {"type": "blank", "level": "A1", "topic": "Artigos A / An", "instruction": "Complete com a ou an.", "explain": "\"Easy\" começa com som de vogal: \"an easy exercise\".", "prompt": "It's ___ easy exercise.", "accept": ["an"], "id": "bkA1-218"}, {"type": "reading", "level": "A1", "topic": "Artigos A / An", "instruction": "Leia o anúncio e responda.", "explain": "O anúncio diz: bicicleta azul, guitarra por 800 reais, ligar depois das 18h.", "text": "For sale: a blue bike and an electric guitar. The bike is 300 reais. The guitar is 800 reais, and it comes with a bag. Call Hugo after 6 p.m. at 99876-5432.", "questions": [{"q": "What color is the bike?", "options": ["Red", "Blue", "Black"], "correctIndex": 1}, {"q": "How much is the guitar?", "options": ["300 reais", "600 reais", "800 reais"], "correctIndex": 2}, {"q": "When can you call Hugo?", "options": ["After 6 p.m.", "Before 6 p.m.", "Only in the morning"], "correctIndex": 0}], "id": "bkA1-219"}, {"type": "mcq", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Escolha o número correto.", "explain": "17 = seventeen (-teen); seventy é 70.", "prompt": "How do you say 17?", "options": ["seventy", "seventeen", "seven", "seventh"], "correctIndex": 1, "id": "bkA1-220"}, {"type": "mcq", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Escolha a forma correta.", "explain": "Em datas usamos ordinais: September seventh (7 de setembro).", "prompt": "Brazil's Independence Day is on September ___.", "options": ["seven", "seventh", "seventeen", "seventy"], "correctIndex": 1, "id": "bkA1-221"}, {"type": "mcq", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Escolha a forma correta.", "explain": "\"Hundred\" não vai para o plural depois de um número: three hundred fifty.", "prompt": "The ticket is 350 reais. How do you say 350?", "options": ["three hundreds fifty", "three hundred fifty", "thirty fifty", "three fifty hundred"], "correctIndex": 1, "id": "bkA1-222"}, {"type": "gaps", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Complete com o número ordinal (por extenso ou 5th, 2nd).", "explain": "Para andares usamos ordinais: fifth (5º), second (2º).", "prompt": "A: What floor is the dentist's office on?\nB: It's on the ___ (5) floor.\nA: And the bathroom?\nB: It's on the ___ (2) floor.", "answers": [["fifth", "5th"], ["second", "2nd"]], "id": "bkA1-223"}, {"type": "gaps", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Escreva os números por extenso.", "explain": "7 = seven, 12 = twelve, 28 = twenty-eight (com hífen).", "prompt": "There are ___ (7) days in a week and ___ (12) months in a year. February has ___ (28) days, sometimes 29.", "answers": [["seven"], ["twelve"], ["twenty-eight", "twenty eight"]], "id": "bkA1-224"}, {"type": "choose", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Clique na forma correta.", "explain": "Andar usa ordinal (twelfth); quantidade usa cardinal (three).", "prompt": "Our apartment is on the [twelve/twelfth*] floor, and it has [three*/third] bedrooms.", "id": "bkA1-225"}, {"type": "choose", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Clique na forma correta.", "explain": "Aniversário de casamento e datas usam ordinais: fifth, twenty-first.", "prompt": "Come to our [five/fifth*] wedding anniversary party on May [twenty-one/twenty-first*].", "id": "bkA1-226"}, {"type": "error", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Encontre o erro na frase.", "explain": "Para dizer \"terceira vez\" usamos o ordinal: \"third time\".", "sentence": "This is my three time in Brazil.", "wrong": "three", "fix": ["third", "3rd"], "id": "bkA1-227"}, {"type": "error", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Encontre o erro na frase.", "explain": "Idade usa número cardinal: ninety-four years old.", "sentence": "My grandmother is ninety-fourth years old.", "wrong": "ninety-fourth", "fix": ["ninety-four", "ninety four", "94"], "id": "bkA1-228"}, {"type": "rewrite", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Reescreva com os números por extenso.", "explain": "2 = two, 3 = three.", "prompt": "I have 2 brothers and 3 sisters.", "accept": ["I have two brothers and three sisters."], "id": "bkA1-229"}, {"type": "rewrite", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Reescreva a frase dizendo a posição de Clara.", "explain": "Número 2 numa corrida = second (segunda colocada).", "prompt": "Clara is number 2 in the race.", "start": "Clara finishes", "accept": ["Clara finishes second.", "Clara finishes in second place.", "Clara finishes 2nd.", "Clara finishes in 2nd place.", "Clara finishes second in the race.", "Clara finishes the race second.", "Clara finishes the race in second place.", "Clara finishes in second place in the race."], "id": "bkA1-230"}, {"type": "order", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Andar usa ordinal: \"on the ninth floor\".", "words": ["My", "office", "is", "on", "the", "ninth", "floor"], "id": "bkA1-231"}, {"type": "order", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"There are\" + número cardinal + substantivo no plural.", "words": ["There", "are", "sixty", "minutes", "in", "an", "hour"], "alt": ["In an hour there are sixty minutes", "In an hour, there are sixty minutes"], "id": "bkA1-232"}, {"type": "match", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Ligue cada número à forma escrita.", "explain": "21st = twenty-first, 30 = thirty, 3rd = third, 14 = fourteen, 1,000 = one thousand.", "left": ["21st", "30", "3rd", "14", "1,000"], "right": ["third", "one thousand", "twenty-first", "fourteen", "thirty"], "correctMap": [2, 4, 0, 3, 1], "id": "bkA1-233"}, {"type": "sort", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Separe os números: -teen (13–19) ou -ty (20, 30...)?", "explain": "\"-teen\" vai de 13 a 19; \"-ty\" são as dezenas: 30, 50, 80, 90.", "prompt": "Sort the numbers: -teen or -ty?", "groups": ["13–19 (-teen)", "20, 30... (-ty)"], "items": [{"w": "thirteen", "g": 0}, {"w": "thirty", "g": 1}, {"w": "fifteen", "g": 0}, {"w": "fifty", "g": 1}, {"w": "eighteen", "g": 0}, {"w": "eighty", "g": 1}, {"w": "nineteen", "g": 0}, {"w": "ninety", "g": 1}], "id": "bkA1-234"}, {"type": "odd", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Encontre a palavra que não é número.", "explain": "\"Forty\", \"fourteen\" e \"fourth\" são números; \"for\" é preposição.", "prompt": "Which word is not a number?", "options": ["forty", "fourteen", "fourth", "for"], "correctIndex": 3, "id": "bkA1-235"}, {"type": "reading", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Leia a mensagem e responda.", "explain": "A mensagem diz: 3 de março, 11º andar, chegar 15 minutos antes das 14h15, ou seja, às 14h.", "text": "Hi, this is Dr. Almeida's office. Your appointment is on Thursday, March 3rd, at 2:15 p.m. Our address is 480 Augusta Street, eleventh floor, room 1104. Please arrive fifteen minutes early.", "questions": [{"q": "What is the date of the appointment?", "options": ["March 3rd", "March 13th", "May 3rd"], "correctIndex": 0}, {"q": "What floor is the office on?", "options": ["The fourth floor", "The eleventh floor", "The fourteenth floor"], "correctIndex": 1}, {"q": "What time is good to arrive?", "options": ["At 2:30 p.m.", "At 2:15 p.m.", "At 2:00 p.m."], "correctIndex": 2}], "id": "bkA1-236"}, {"type": "tf", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Bruno é o primeiro (20 anos), Lara a segunda (17), e os gêmeos têm 11. São quatro filhos.", "text": "The Silva family has four children. Bruno is the first child; he is twenty. Lara is the second; she is seventeen. The twins, Davi and Enzo, are the youngest. They are eleven.", "items": [{"s": "Lara is the oldest child.", "a": false}, {"s": "Bruno is twenty years old.", "a": true}, {"s": "Davi and Enzo are eleven.", "a": true}, {"s": "The family has three children.", "a": false}], "id": "bkA1-237"}, {"type": "dorder", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Pedido, preço, pagamento, troco e, no fim, a pergunta sobre a fileira.", "lines": ["A: Two tickets for the nine o'clock movie, please.", "B: Sure. That's forty-six reais.", "A: Here's fifty.", "B: Thank you. Here's your change, four reais.", "A: Thanks! Which row are our seats in?", "B: The fifth row."], "id": "bkA1-238"}, {"type": "blank", "level": "A1", "topic": "Números cardinais e ordinais", "instruction": "Escreva o resultado.", "explain": "30 − 18 = 12 (twelve).", "prompt": "Thirty minus eighteen is ___.", "accept": ["twelve", "12"], "id": "bkA1-239"}, {"type": "mcq", "level": "A1", "topic": "There is / There are", "instruction": "Escolha a opção correta.", "explain": "\"A problem\" é singular: \"There is\".", "prompt": "___ a problem with my computer.", "options": ["There is", "There are", "It has", "Have"], "correctIndex": 0, "id": "bkA1-240"}, {"type": "mcq", "level": "A1", "topic": "There is / There are", "instruction": "Escolha a opção correta.", "explain": "Para \"tem/há\" usamos \"there are\" (plural), não \"have\".", "prompt": "___ many people at the beach today.", "options": ["Have", "There are", "There is", "It has"], "correctIndex": 1, "id": "bkA1-241"}, {"type": "mcq", "level": "A1", "topic": "There is / There are", "instruction": "Escolha a resposta curta correta.", "explain": "\"Sugar\" é incontável (singular): \"No, there isn't.\"", "prompt": "A: Is there any sugar?\nB: No, ___.", "options": ["there isn't", "there aren't", "it isn't", "isn't there"], "correctIndex": 0, "id": "bkA1-242"}, {"type": "gaps", "level": "A1", "topic": "There is / There are", "instruction": "Complete o diálogo com is, are ou Are.", "explain": "Plural (restaurants) = are; singular (a restaurant) = is.", "prompt": "A: ___ there any good restaurants in your neighborhood?\nB: Yes, there ___. There ___ a great Japanese restaurant next to my building.", "answers": [["Are"], ["are"], ["is"]], "id": "bkA1-243"}, {"type": "gaps", "level": "A1", "topic": "There is / There are", "instruction": "Complete o texto com as palavras do quadro.", "explain": "Singular = is/isn't; plural = are/aren't. \"Can't watch\" indica que não há TV; \"any towels\" indica negativa.", "prompt": "My hotel room in Lisbon is nice. There ___ a big bed, and it's very comfortable. There ___ two windows with a view of the river. There ___ a TV, so I can't watch the news. There ___ any towels, so I need to call the reception.", "answers": [["is"], ["are"], ["isn't"], ["aren't"]], "bank": ["is", "are", "isn't", "aren't"], "id": "bkA1-244"}, {"type": "choose", "level": "A1", "topic": "There is / There are", "instruction": "Clique na forma correta.", "explain": "\"Milk\" é incontável (is); \"cookies\" é plural (aren't any).", "prompt": "There [is*/are] some milk, but there [isn't/aren't*] any cookies.", "id": "bkA1-245"}, {"type": "choose", "level": "A1", "topic": "There is / There are", "instruction": "Clique na forma correta.", "explain": "\"Buses\" é plural: pergunta com \"Are\" e resposta \"there are\".", "prompt": "[Is/Are*] there any buses to the airport? Yes, there [is/are*] a lot.", "id": "bkA1-246"}, {"type": "error", "level": "A1", "topic": "There is / There are", "instruction": "Encontre o erro na frase.", "explain": "Para \"tem/há\" em inglês usamos \"There is\", não \"Have\".", "sentence": "Have a pharmacy on the corner.", "wrong": "Have", "fix": ["There is", "There's"], "id": "bkA1-247"}, {"type": "error", "level": "A1", "topic": "There is / There are", "instruction": "Encontre o erro na frase.", "explain": "\"A big supermarket\" é singular: \"There is\".", "sentence": "There are a big supermarket near my house.", "wrong": "are", "fix": ["is"], "id": "bkA1-248"}, {"type": "rewrite", "level": "A1", "topic": "There is / There are", "instruction": "Reescreva na forma negativa.", "explain": "Na negativa usamos \"aren't any\" ou \"are no\".", "prompt": "There are some students in the lab.", "accept": ["There aren't any students in the lab.", "There are not any students in the lab.", "There are no students in the lab."], "id": "bkA1-249"}, {"type": "rewrite", "level": "A1", "topic": "There is / There are", "instruction": "Transforme em pergunta.", "explain": "Na pergunta, \"Is\" vem antes de \"there\".", "prompt": "There is a gym in this building.", "start": "Is", "accept": ["Is there a gym in this building?"], "id": "bkA1-250"}, {"type": "order", "level": "A1", "topic": "There is / There are", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta de quantidade: How many + substantivo + are there...?", "words": ["How", "many", "people", "are", "there", "in", "your", "family"], "id": "bkA1-251"}, {"type": "order", "level": "A1", "topic": "There is / There are", "instruction": "Ordene as palavras para formar uma frase negativa.", "explain": "Negativa no singular: There isn't a...", "words": ["There", "isn't", "a", "bus", "stop", "on", "this", "street"], "alt": ["On this street there isn't a bus stop", "On this street, there isn't a bus stop"], "id": "bkA1-252"}, {"type": "match", "level": "A1", "topic": "There is / There are", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "Cada resposta combina com o assunto da pergunta (quartos, garagem, lojas, Wi-Fi).", "left": ["How many bedrooms are there?", "Is there a garage?", "Are there any shops nearby?", "Is there Wi-Fi?"], "right": ["Yes, there are two on the next street.", "There are three.", "Yes, and the password is on the fridge.", "No, there isn't, but you can park on the street."], "correctMap": [1, 3, 0, 2], "id": "bkA1-253"}, {"type": "sort", "level": "A1", "topic": "There is / There are", "instruction": "Separe: there is ou there are?", "explain": "Singular ou incontável = there is; plural = there are.", "prompt": "Sort: there is or there are?", "groups": ["There is", "There are"], "items": [{"w": "a cat", "g": 0}, {"w": "some water", "g": 0}, {"w": "two cats", "g": 1}, {"w": "a lot of people", "g": 1}, {"w": "an old church", "g": 0}, {"w": "some eggs", "g": 1}, {"w": "a problem", "g": 0}, {"w": "many problems", "g": 1}], "id": "bkA1-254"}, {"type": "odd", "level": "A1", "topic": "There is / There are", "instruction": "Qual expressão NÃO combina com \"There are\"?", "explain": "\"There are\" pede plural; \"a chair\" é singular.", "prompt": "Which one does not go with \"There are\"?", "options": ["three chairs", "some books", "a chair", "many people"], "correctIndex": 2, "id": "bkA1-255"}, {"type": "tf", "level": "A1", "topic": "There is / There are", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O texto diz: não há carros nem banco; há mais de cem praias e lojas.", "text": "Welcome to Ilha Grande! There are no cars on the island, so you walk or take a boat. There are more than one hundred beaches. There is a small village with restaurants and shops. There isn't a bank, so bring cash.", "items": [{"s": "There are a lot of cars on the island.", "a": false}, {"s": "There are more than 100 beaches.", "a": true}, {"s": "There is a bank in the village.", "a": false}, {"s": "There are shops in the village.", "a": true}], "id": "bkA1-256"}, {"type": "reading", "level": "A1", "topic": "There is / There are", "instruction": "Leia o anúncio e responda.", "explain": "O anúncio diz: dois quartos, uma varanda com vista, ponto de ônibus na frente e sem garagem.", "text": "Apartment for rent in Florianópolis. There are two bedrooms and one bathroom. There is a small balcony with a view of the sea. There isn't a garage, but there is a bus stop in front of the building. Rent: 2,500 reais a month.", "questions": [{"q": "How many bedrooms are there?", "options": ["One", "Two", "Three"], "correctIndex": 1}, {"q": "What does the apartment have?", "options": ["A balcony", "A garage", "Two bathrooms"], "correctIndex": 0}, {"q": "What is in front of the building?", "options": ["The sea", "A garage", "A bus stop"], "correctIndex": 2}], "id": "bkA1-257"}, {"type": "dorder", "level": "A1", "topic": "There is / There are", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Pedido de mesa, resposta negativa, pergunta sobre a espera e decisão de esperar.", "lines": ["A: Excuse me, is there a table for four?", "B: Sorry, there aren't any free tables right now.", "A: Oh. Is there a long wait?", "B: Not long. About ten minutes.", "A: OK, we can wait."], "id": "bkA1-258"}, {"type": "blank", "level": "A1", "topic": "There is / There are", "instruction": "Complete com is ou are.", "explain": "\"Traffic\" é incontável, então usamos \"there is\".", "prompt": "There ___ a lot of traffic in São Paulo every day.", "accept": ["is"], "id": "bkA1-259"}, {"type": "mcq", "level": "A1", "topic": "Simple Present", "instruction": "Escolha a forma correta do verbo.", "explain": "Verbos terminados em -sh ganham -es com he/she/it: washes.", "prompt": "Carlos ___ his car every Sunday.", "options": ["wash", "washs", "washes", "washing"], "correctIndex": 2, "id": "bkA1-260"}, {"type": "mcq", "level": "A1", "topic": "Simple Present", "instruction": "Escolha o auxiliar correto.", "explain": "Com \"you\" a pergunta no presente usa \"Do\".", "prompt": "___ you speak English at work?", "options": ["Do", "Does", "Are", "Is"], "correctIndex": 0, "id": "bkA1-261"}, {"type": "mcq", "level": "A1", "topic": "Simple Present", "instruction": "Escolha a forma correta do verbo.", "explain": "Consoante + y: troca o y por -ies com he/she/it: cries.", "prompt": "My baby brother ___ a lot at night.", "options": ["cry", "crys", "cries", "crying"], "correctIndex": 2, "id": "bkA1-262"}, {"type": "gaps", "level": "A1", "topic": "Simple Present", "instruction": "Complete o diálogo com do, don't, does ou doesn't.", "explain": "\"Your parents/they\" usa do; \"your dad/he\" usa does.", "prompt": "A: ___ your parents live in São Paulo?\nB: No, they ___. They live in Campinas.\nA: ___ your dad work there too?\nB: Yes, he ___.", "answers": [["Do"], ["don't", "do not"], ["Does"], ["does"]], "id": "bkA1-263"}, {"type": "gaps", "level": "A1", "topic": "Simple Present", "instruction": "Complete com o verbo entre parênteses no presente.", "explain": "Com he: gets, has (have é irregular), goes; negativa: doesn't + verbo base.", "prompt": "Every day, Beto ___ (get) up at 6. He ___ (have) coffee and ___ (go) to work by train. He ___ (not / eat) lunch at home.", "answers": [["gets"], ["has"], ["goes"], ["doesn't eat", "does not eat"]], "id": "bkA1-264"}, {"type": "gaps", "level": "A1", "topic": "Simple Present", "instruction": "Complete o texto com as palavras do quadro.", "explain": "Com \"he\" o verbo leva -s/-es/-ies; na negativa, \"doesn't\" + verbo base.", "prompt": "My friend Kaio is a busy student. He ___ medicine at UFMG. In the evening, he ___ volleyball on the university team. He ___ a part-time job at a bookstore. He ___ go out much, but he ___ soccer games on TV on Sundays.", "answers": [["studies"], ["plays"], ["has"], ["doesn't", "does not"], ["watches"]], "bank": ["studies", "plays", "has", "doesn't", "watches"], "id": "bkA1-265"}, {"type": "choose", "level": "A1", "topic": "Simple Present", "instruction": "Clique na forma correta do verbo.", "explain": "\"My cat\" (it) leva -s: sleeps; \"my dogs\" (they) não leva: play.", "prompt": "My cat [sleep/sleeps*] all day, but my dogs [play*/plays] in the garden.", "id": "bkA1-266"}, {"type": "error", "level": "A1", "topic": "Simple Present", "instruction": "Encontre o erro na frase.", "explain": "Com \"my brother\" (he), o verbo \"have\" vira \"has\".", "sentence": "My brother have two kids.", "wrong": "have", "fix": ["has"], "id": "bkA1-267"}, {"type": "error", "level": "A1", "topic": "Simple Present", "instruction": "Encontre o erro na frase.", "explain": "\"Your mother\" é he/she, então a pergunta usa \"Does\".", "sentence": "Do your mother cook on Sundays?", "wrong": "Do", "fix": ["Does"], "id": "bkA1-268"}, {"type": "rewrite", "level": "A1", "topic": "Simple Present", "instruction": "Transforme em pergunta.", "explain": "Pergunta com she: Does + sujeito + verbo base (drink, sem -s).", "prompt": "Isabela drinks coffee in the morning.", "start": "Does", "accept": ["Does Isabela drink coffee in the morning?"], "id": "bkA1-269"}, {"type": "rewrite", "level": "A1", "topic": "Simple Present", "instruction": "Reescreva na forma negativa.", "explain": "Negativa com he: doesn't + verbo base (watch, sem -es).", "prompt": "My grandfather watches the news.", "accept": ["My grandfather doesn't watch the news.", "My grandfather does not watch the news."], "id": "bkA1-270"}, {"type": "order", "level": "A1", "topic": "Simple Present", "instruction": "Ordene as palavras para formar uma frase negativa.", "explain": "Negativa com he: doesn't + verbo base (drink).", "words": ["My", "father", "doesn't", "drink", "coffee", "after", "lunch"], "alt": ["After lunch my father doesn't drink coffee", "After lunch, my father doesn't drink coffee"], "id": "bkA1-271"}, {"type": "order", "level": "A1", "topic": "Simple Present", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta com Wh-: Where + does + sujeito + verbo base.", "words": ["Where", "does", "your", "brother", "work"], "id": "bkA1-272"}, {"type": "match", "level": "A1", "topic": "Simple Present", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "A resposta curta usa o mesmo auxiliar e o pronome certo: do/does, I/he/they/it.", "left": ["Do you play the guitar?", "Does Leo speak French?", "Do your friends like funk?", "Does it rain a lot here?"], "right": ["Yes, they love it.", "No, I don't. I play the drums.", "Yes, it does, in the summer.", "No, he doesn't. He speaks Italian."], "correctMap": [1, 3, 0, 2], "id": "bkA1-273"}, {"type": "sort", "level": "A1", "topic": "Simple Present", "instruction": "Separe os verbos pela forma com he/she/it.", "explain": "Regra geral: +s; -ch, -ss, -o: +es; consoante + y: -ies (mas buy → buys).", "prompt": "How do these verbs change with \"he\"?", "groups": ["+ s (cooks)", "+ es (catches)", "y → ies (studies)"], "items": [{"w": "cook", "g": 0}, {"w": "buy", "g": 0}, {"w": "catch", "g": 1}, {"w": "kiss", "g": 1}, {"w": "do", "g": 1}, {"w": "study", "g": 2}, {"w": "fly", "g": 2}, {"w": "cry", "g": 2}], "id": "bkA1-274"}, {"type": "odd", "level": "A1", "topic": "Simple Present", "instruction": "Qual forma NÃO é usada com he/she/it?", "explain": "\"Goes\", \"has\" e \"does\" são formas de terceira pessoa; \"have\" não.", "prompt": "Which form is not for he, she or it?", "options": ["goes", "has", "does", "have"], "correctIndex": 3, "id": "bkA1-275"}, {"type": "reading", "level": "A1", "topic": "Simple Present", "instruction": "Leia o texto e responda.", "explain": "Akira é comissário de bordo; a esposa trabalha de segunda a sexta; aos domingos visitam os pais dela.", "text": "My name is Akira, and I'm a flight attendant. I don't have a normal routine. Some weeks I work five days, and other weeks only three. When I'm at home in Guarulhos, I sleep a lot and cook Japanese food. My wife is a teacher, so she works from Monday to Friday. On Sundays, we visit her parents.", "questions": [{"q": "What is Akira's job?", "options": ["He is a teacher.", "He is a flight attendant.", "He is a cook."], "correctIndex": 1}, {"q": "When does his wife work?", "options": ["From Monday to Friday", "On weekends", "Three days a week"], "correctIndex": 0}, {"q": "What do they do on Sundays?", "options": ["They go to Japan.", "They work.", "They visit her parents."], "correctIndex": 2}], "id": "bkA1-276"}, {"type": "tf", "level": "A1", "topic": "Simple Present", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "A padaria fecha às segundas, o filho faz o café e os turistas adoram a tapioca.", "text": "Dona Célia has a small bakery in Olinda. She opens it at 5 a.m. every day except Monday. She makes bread and cakes, and her son helps her with the coffee. Tourists love her tapioca.", "items": [{"s": "The bakery opens on Mondays.", "a": false}, {"s": "Célia makes bread.", "a": true}, {"s": "Her daughter makes the coffee.", "a": false}, {"s": "Tourists like her tapioca.", "a": true}], "id": "bkA1-277"}, {"type": "dorder", "level": "A1", "topic": "Simple Present", "instruction": "Coloque o diálogo na ordem certa.", "explain": "\"What do you do?\" pergunta a profissão; depois vem \"Do you like it?\" e a resposta.", "lines": ["A: What do you do?", "B: I'm a programmer. I work from home.", "A: Do you like it?", "B: Yes, I do. But I don't see my coworkers very often."], "id": "bkA1-278"}, {"type": "blank", "level": "A1", "topic": "Simple Present", "instruction": "Complete com o verbo entre parênteses na negativa.", "explain": "\"My parents\" = they, então a negativa é \"don't have\".", "prompt": "My parents ___ (not / have) a car.", "accept": ["don't have", "do not have"], "id": "bkA1-279"}, {"type": "mcq", "level": "A1", "topic": "Wh- Words", "instruction": "Escolha a palavra interrogativa correta.", "explain": "Para perguntar preço usamos \"How much\".", "prompt": "___ does this bag cost? It's 80 reais.", "options": ["How much", "How many", "How old", "Which"], "correctIndex": 0, "id": "bkA1-280"}, {"type": "mcq", "level": "A1", "topic": "Wh- Words", "instruction": "Escolha a palavra interrogativa correta.", "explain": "\"Brothers\" é contável: \"How many\".", "prompt": "___ brothers do you have? Two.", "options": ["How much", "How many", "How old", "Why"], "correctIndex": 1, "id": "bkA1-281"}, {"type": "mcq", "level": "A1", "topic": "Wh- Words", "instruction": "Escolha a palavra interrogativa correta.", "explain": "Para perguntar sobre uma pessoa usamos \"Who\".", "prompt": "___ is that man? He's my boss.", "options": ["Who", "Where", "Whose", "When"], "correctIndex": 0, "id": "bkA1-282"}, {"type": "gaps", "level": "A1", "topic": "Wh- Words", "instruction": "Complete o diálogo com a palavra interrogativa certa.", "explain": "Meio de transporte = How; horário = What time/When; lugar = Where.", "prompt": "A: ___ do you go to work?\nB: By bike. It's fast and cheap.\nA: ___ do you leave home?\nB: At 7:30.\nA: ___ is your office?\nB: Near Ibirapuera Park.", "answers": [["How"], ["What time", "When"], ["Where"]], "id": "bkA1-283"}, {"type": "gaps", "level": "A1", "topic": "Wh- Words", "instruction": "Complete o diálogo com a palavra interrogativa certa.", "explain": "Dono = Whose; cor = What (ou Which, com opções).", "prompt": "A: ___ car is this? It's very nice.\nB: It's my uncle's.\nA: ___ color is it? Dark blue or black?\nB: It's dark blue.", "answers": [["Whose"], ["What", "Which"]], "id": "bkA1-284"}, {"type": "choose", "level": "A1", "topic": "Wh- Words", "instruction": "Clique na palavra correta.", "explain": "Pergunta de motivo = Why; resposta de motivo = Because.", "prompt": "[Why*/Where] are you so happy? [Because*/Why] today is my birthday!", "id": "bkA1-285"}, {"type": "choose", "level": "A1", "topic": "Wh- Words", "instruction": "Clique na palavra correta.", "explain": "Escolha entre opções = Which; duração/distância = How long.", "prompt": "[Which*/Who] bus goes to the airport, the 100 or the 200? And [how*/what] long is the trip?", "id": "bkA1-286"}, {"type": "error", "level": "A1", "topic": "Wh- Words", "instruction": "Encontre o erro na frase.", "explain": "\"Money\" é incontável, então usamos \"How much\".", "sentence": "How many money do you have?", "wrong": "many", "fix": ["much"], "id": "bkA1-287"}, {"type": "error", "level": "A1", "topic": "Wh- Words", "instruction": "Encontre o erro na frase.", "explain": "Pergunta no presente precisa do auxiliar: \"What do you do...?\"", "sentence": "What you do on weekends?", "wrong": "What you", "fix": ["What do you"], "id": "bkA1-288"}, {"type": "rewrite", "level": "A1", "topic": "Wh- Words", "instruction": "Faça a pergunta para a informação \"at 6 p.m.\".", "explain": "Para horário: What time + does + sujeito + verbo base.", "prompt": "The store closes at 6 p.m.", "start": "What time", "accept": ["What time does the store close?"], "id": "bkA1-289"}, {"type": "rewrite", "level": "A1", "topic": "Wh- Words", "instruction": "Faça a pergunta com Who para descobrir quem cozinha.", "explain": "Quando \"Who\" é o sujeito, não usamos do/does: \"Who cooks dinner?\"", "prompt": "Marta cooks dinner.", "start": "Who", "accept": ["Who cooks dinner?"], "id": "bkA1-290"}, {"type": "order", "level": "A1", "topic": "Wh- Words", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "\"How often\" pergunta a frequência.", "words": ["How", "often", "do", "you", "go", "to", "the", "gym"], "id": "bkA1-291"}, {"type": "order", "level": "A1", "topic": "Wh- Words", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "\"Whose\" pergunta o dono: Whose + objeto + is...?", "words": ["Whose", "phone", "is", "on", "the", "table"], "id": "bkA1-292"}, {"type": "match", "level": "A1", "topic": "Wh- Words", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "How old = idade; How far = distância; What = profissão; Which = escolha; Whose = dono.", "left": ["How old is your son?", "How far is the beach?", "What's your job?", "Which one do you want, red or blue?", "Whose keys are these?"], "right": ["Blue, please.", "They're Tânia's.", "I'm an electrician.", "He's six.", "About two kilometers."], "correctMap": [3, 4, 2, 0, 1], "id": "bkA1-293"}, {"type": "sort", "level": "A1", "topic": "Wh- Words", "instruction": "Separe as respostas: Who, Where ou When?", "explain": "Pessoas respondem \"Who\"; lugares, \"Where\"; tempo, \"When\".", "prompt": "Sort the answers: Who, Where or When?", "groups": ["Who?", "Where?", "When?"], "items": [{"w": "my teacher", "g": 0}, {"w": "in Brasília", "g": 1}, {"w": "at noon", "g": 2}, {"w": "Dr. Souza", "g": 0}, {"w": "next to the bank", "g": 1}, {"w": "on Friday", "g": 2}, {"w": "my neighbor", "g": 0}, {"w": "in March", "g": 2}], "id": "bkA1-294"}, {"type": "odd", "level": "A1", "topic": "Wh- Words", "instruction": "Encontre a palavra que não é interrogativa.", "explain": "\"Who\", \"whose\" e \"which\" são palavras interrogativas; \"while\" significa \"enquanto\".", "prompt": "Which word is not a question word?", "options": ["who", "whose", "which", "while"], "correctIndex": 3, "id": "bkA1-295"}, {"type": "dorder", "level": "A1", "topic": "Wh- Words", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Nome, origem e número de noites, cada pergunta seguida da resposta.", "lines": ["A: Hi! What's your name?", "B: I'm Sofía Ramos.", "A: Where are you from, Sofía?", "B: I'm from Mexico.", "A: How many nights do you want?", "B: Three nights, please."], "id": "bkA1-296"}, {"type": "reading", "level": "A1", "topic": "Wh- Words", "instruction": "Leia o e-mail e responda.", "explain": "O e-mail diz: primeiro dia na segunda, Joel é o gerente, levar documento e foto.", "text": "Hi Nara! Welcome to the team. Your first day is Monday. Please come to the third floor at 9 a.m. and ask for Joel. He is your manager. Bring your ID card and a photo. Lunch is at noon in the cafeteria. See you soon! Helena, HR", "questions": [{"q": "When is Nara's first day?", "options": ["On Monday", "On Tuesday", "At noon"], "correctIndex": 0}, {"q": "Who is Joel?", "options": ["Her friend", "Her manager", "A cook"], "correctIndex": 1}, {"q": "What does Nara need to bring?", "options": ["Her lunch", "A computer", "Her ID card and a photo"], "correctIndex": 2}], "id": "bkA1-297"}, {"type": "tf", "level": "A1", "topic": "Wh- Words", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Rodrigo trabalha à noite porque gosta de ruas tranquilas e mora com a avó.", "text": "Rodrigo is a bus driver in Porto Alegre. He works at night because he likes quiet streets. He lives with his grandmother in a small house. On Saturdays, he plays chess in the park with his friends.", "items": [{"s": "Rodrigo works at night.", "a": true}, {"s": "He works at night because the pay is good.", "a": false}, {"s": "He lives with his parents.", "a": false}, {"s": "He plays chess on Saturdays.", "a": true}], "id": "bkA1-298"}, {"type": "blank", "level": "A1", "topic": "Wh- Words", "instruction": "Complete com a palavra interrogativa certa.", "explain": "Para perguntar quais idiomas: What ou Which + languages.", "prompt": "___ languages do you speak? Portuguese and English.", "accept": ["What", "Which"], "id": "bkA1-299"}, {"type": "mcq", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Escolha o mês correto.", "explain": "A ordem é March, April, May.", "prompt": "The month between March and May is ___.", "options": ["April", "June", "February", "August"], "correctIndex": 0, "id": "bkA1-300"}, {"type": "mcq", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Escolha o mês correto.", "explain": "No Brasil, as férias escolares são em janeiro (verão) e em julho.", "prompt": "In Brazil, students have school vacation in ___ and July.", "options": ["January", "April", "October", "November"], "correctIndex": 0, "id": "bkA1-301"}, {"type": "mcq", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Escolha a estação correta.", "explain": "\"Fall\" (ou autumn) é o outono, quando as folhas caem.", "prompt": "In ___, the leaves fall from the trees.", "options": ["fall", "summer", "winter", "spring"], "correctIndex": 0, "id": "bkA1-302"}, {"type": "gaps", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Complete com os dias e o mês que faltam.", "explain": "Segunda a sexta: Monday, Tuesday, Wednesday, Thursday, Friday. Setembro também tem 30 dias.", "prompt": "The weekdays are Monday, ___, Wednesday, ___ and Friday. April, June, ___ and November have thirty days.", "answers": [["Tuesday"], ["Thursday"], ["September"]], "id": "bkA1-303"}, {"type": "gaps", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Complete o diálogo.", "explain": "O dia antes de sábado é Friday; a data usa ordinal: the thirtieth (30th).", "prompt": "A: What day is it today?\nB: It's ___. Tomorrow is Saturday!\nA: Great! And what's the date?\nB: It's June ___ (30).", "answers": [["Friday"], ["thirtieth", "30th"]], "id": "bkA1-304"}, {"type": "choose", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Clique na palavra correta.", "explain": "O Carnaval costuma ser em fevereiro, que é verão no Brasil.", "prompt": "Carnival is usually in [February*/August], in the Brazilian [summer*/winter].", "id": "bkA1-305"}, {"type": "choose", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Clique na palavra correta.", "explain": "Setembro em inglês é \"September\" (com p); nos EUA, é outono (fall).", "prompt": "In the U.S., the school year starts in [September*/Setember], in the [fall*/spring].", "id": "bkA1-306"}, {"type": "error", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Encontre o erro na frase.", "explain": "Fevereiro em inglês se escreve \"February\", com r depois do b.", "sentence": "Our trip to Chile is in Febuary.", "wrong": "Febuary", "fix": ["February"], "id": "bkA1-307"}, {"type": "error", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Encontre o erro na frase.", "explain": "Um ano tem doze meses (twelve).", "sentence": "There are thirteen months in a year.", "wrong": "thirteen", "fix": ["twelve", "12"], "id": "bkA1-308"}, {"type": "rewrite", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Transforme em pergunta com When.", "explain": "Pergunta com to be: When + is + her birthday.", "prompt": "Her birthday is in August.", "start": "When", "accept": ["When is her birthday?", "When's her birthday?"], "id": "bkA1-309"}, {"type": "rewrite", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Responda com uma frase completa.", "explain": "Depois de quarta (Wednesday) vem quinta (Thursday).", "prompt": "What day comes after Wednesday?", "start": "Thursday comes", "accept": ["Thursday comes after Wednesday."], "id": "bkA1-310"}, {"type": "order", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Período de meses: from + mês + to + mês.", "words": ["The", "rainy", "season", "in", "Manaus", "is", "from", "December", "to", "May"], "alt": ["In Manaus the rainy season is from December to May", "In Manaus, the rainy season is from December to May"], "id": "bkA1-311"}, {"type": "order", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "\"Season\" = estação do ano.", "words": ["What", "is", "your", "favorite", "season"], "alt": ["What season is your favorite"], "id": "bkA1-312"}, {"type": "match", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Ligue cada data comemorativa ao dia certo.", "explain": "Natal 25/12, Ano Novo 1/1, Valentine's Day 14/2 e Independência do Brasil 7/9.", "left": ["Christmas Day", "New Year's Day", "Valentine's Day (U.S.)", "Brazil's Independence Day"], "right": ["February 14th", "September 7th", "December 25th", "January 1st"], "correctMap": [2, 3, 0, 1], "id": "bkA1-313"}, {"type": "sort", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Separe os dias: dia útil ou fim de semana?", "explain": "O fim de semana é Saturday e Sunday; os outros são dias úteis (weekdays).", "prompt": "Sort the days: weekday or weekend?", "groups": ["Weekday", "Weekend"], "items": [{"w": "Monday", "g": 0}, {"w": "Saturday", "g": 1}, {"w": "Tuesday", "g": 0}, {"w": "Sunday", "g": 1}, {"w": "Thursday", "g": 0}, {"w": "Wednesday", "g": 0}, {"w": "Friday", "g": 0}], "id": "bkA1-314"}, {"type": "odd", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Encontre a palavra diferente.", "explain": "\"Spring\", \"autumn\" e \"winter\" são estações; \"weekend\" é fim de semana.", "prompt": "Which word is not a season?", "options": ["spring", "autumn", "winter", "weekend"], "correctIndex": 3, "id": "bkA1-315"}, {"type": "tf", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "No Sul, o inverno vai de junho a setembro e a primavera começa em setembro.", "text": "In the south of Brazil, winter is from June to September. It is cold, and sometimes it snows in the mountains. Summer is from December to March. In summer, many people go to the beach in Santa Catarina. Spring starts in September.", "items": [{"s": "Winter starts in December.", "a": false}, {"s": "It sometimes snows in the mountains.", "a": true}, {"s": "People go to the beach in summer.", "a": true}, {"s": "Spring starts in March.", "a": false}], "id": "bkA1-316"}, {"type": "reading", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Leia o calendário e responda.", "explain": "Aulas começam em 3/2, não há aula no Carnaval (3 a 5/3) e 27/6 é sexta-feira.", "text": "School Calendar – First Semester. Classes start on Monday, February 3rd. There are no classes during Carnival, from March 3rd to March 5th. The winter vacation starts on Friday, June 27th. Classes start again on Monday, July 28th.", "questions": [{"q": "When do classes start?", "options": ["On February 3rd", "On March 3rd", "On July 28th"], "correctIndex": 0}, {"q": "Are there classes on March 4th?", "options": ["Yes, there are.", "No, there aren't.", "Only in the morning."], "correctIndex": 1}, {"q": "What day of the week is June 27th?", "options": ["Monday", "Sunday", "Friday"], "correctIndex": 2}], "id": "bkA1-317"}, {"type": "dorder", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Convite para quinta, recusa com sugestão de sexta, aceitação e despedida.", "lines": ["A: Are you free on Thursday?", "B: No, I have English class on Thursdays. What about Friday?", "A: Friday is perfect. Let's go to the movies!", "B: Great! See you on Friday."], "id": "bkA1-318"}, {"type": "blank", "level": "A1", "topic": "Dias, meses e estações", "instruction": "Complete com o mês correto.", "explain": "Depois de julho (July) vem agosto (August).", "prompt": "The month after July is ___.", "accept": ["August"], "id": "bkA1-319"}, {"type": "mcq", "level": "A1", "topic": "Imperativo", "instruction": "Escolha a opção correta.", "explain": "Imperativo negativo: Don't + verbo base.", "prompt": "___ worry. Everything is OK.", "options": ["Don't", "Not", "No", "Doesn't"], "correctIndex": 0, "id": "bkA1-320"}, {"type": "mcq", "level": "A1", "topic": "Imperativo", "instruction": "Escolha a opção correta.", "explain": "O imperativo do verbo to be é \"Be\".", "prompt": "___ careful! The floor is wet.", "options": ["Be", "Are", "Is", "Being"], "correctIndex": 0, "id": "bkA1-321"}, {"type": "mcq", "level": "A1", "topic": "Imperativo", "instruction": "Escolha a opção correta.", "explain": "Depois de \"Let's\" usamos o verbo base, sem \"to\".", "prompt": "Let's ___ a pizza tonight!", "options": ["order", "to order", "ordering", "orders"], "correctIndex": 0, "id": "bkA1-322"}, {"type": "gaps", "level": "A1", "topic": "Imperativo", "instruction": "Complete a receita com as palavras do quadro.", "explain": "Imperativo = verbo base no início da frase; negativo = Don't + verbo.", "prompt": "How to make a fruit salad: ___ the bananas and apples into small pieces. ___ them in a big bowl. ___ some orange juice and ___ well. ___ add sugar. The fruit is sweet!", "answers": [["Cut"], ["Put", "Mix"], ["Add", "Put"], ["mix", "Mix"], ["Don't", "Do not"]], "bank": ["Cut", "Put", "Add", "Mix", "Don't", "Wait"], "id": "bkA1-323"}, {"type": "gaps", "level": "A1", "topic": "Imperativo", "instruction": "Complete com o imperativo do verbo entre parênteses.", "explain": "Afirmativo: verbo base (Go, turn); negativo: Don't + verbo base.", "prompt": "A: Excuse me, how do I get to the bus station?\nB: ___ (go) straight on this street and ___ (turn) left at the church. ___ (not / take) a taxi. It's very close!", "answers": [["Go"], ["turn"], ["Don't take", "Do not take"]], "id": "bkA1-324"}, {"type": "choose", "level": "A1", "topic": "Imperativo", "instruction": "Clique na forma correta.", "explain": "Negativo: Don't + verbo; afirmativo: verbo base (call).", "prompt": "[Don't*/Not] forget your passport, and [call*/calls] me when you arrive.", "id": "bkA1-325"}, {"type": "choose", "level": "A1", "topic": "Imperativo", "instruction": "Clique na forma correta.", "explain": "Imperativo usa o verbo base: be, turn.", "prompt": "Please [be*/is] quiet and [turn*/turning] off your phones.", "id": "bkA1-326"}, {"type": "error", "level": "A1", "topic": "Imperativo", "instruction": "Encontre o erro na frase.", "explain": "O imperativo não usa \"to\": \"Please sit here.\"", "sentence": "Please to sit here.", "wrong": "to sit", "fix": ["sit"], "id": "bkA1-327"}, {"type": "error", "level": "A1", "topic": "Imperativo", "instruction": "Encontre o erro na frase.", "explain": "Proibição: \"Don't smoke\" (ou a placa \"No smoking\"), não \"No smoke\".", "sentence": "No smoke here, please.", "wrong": "No smoke", "fix": ["Don't smoke", "Do not smoke", "No smoking"], "id": "bkA1-328"}, {"type": "rewrite", "level": "A1", "topic": "Imperativo", "instruction": "Reescreva na forma afirmativa.", "explain": "Para o afirmativo, basta tirar o \"Don't\".", "prompt": "Don't close the window.", "accept": ["Close the window."], "id": "bkA1-329"}, {"type": "rewrite", "level": "A1", "topic": "Imperativo", "instruction": "Transforme a sugestão usando Let's.", "explain": "\"Let's\" + verbo base faz uma sugestão para nós.", "prompt": "Suggestion: we go to the beach together.", "start": "Let's", "accept": ["Let's go to the beach together.", "Let's go to the beach."], "id": "bkA1-330"}, {"type": "order", "level": "A1", "topic": "Imperativo", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Imperativo negativo: Don't + verbo base; \"please\" pode vir no início ou no fim.", "words": ["Please", "don't", "leave", "your", "bags", "here"], "alt": ["Don't leave your bags here please"], "id": "bkA1-331"}, {"type": "order", "level": "A1", "topic": "Imperativo", "instruction": "Ordene as palavras para formar uma frase.", "explain": "O imperativo começa com o verbo base: Wash.", "words": ["Wash", "your", "hands", "before", "dinner"], "alt": ["Before dinner wash your hands", "Before dinner, wash your hands"], "id": "bkA1-332"}, {"type": "match", "level": "A1", "topic": "Imperativo", "instruction": "Ligue cada situação ao conselho certo.", "explain": "Cada conselho no imperativo resolve a situação: chuva, bebê dormindo, sopa quente, prova.", "left": ["It's raining.", "The baby is sleeping.", "The soup is very hot.", "You have a test tomorrow."], "right": ["Study tonight!", "Don't eat it now.", "Take an umbrella.", "Don't make noise."], "correctMap": [2, 3, 1, 0], "id": "bkA1-333"}, {"type": "sort", "level": "A1", "topic": "Imperativo", "instruction": "Separe as frases em certas e erradas.", "explain": "Imperativo usa o verbo base, sem -s e sem \"to\"; negativo com \"Don't\".", "prompt": "Is the imperative correct?", "groups": ["Correta", "Errada"], "items": [{"w": "Open the door.", "g": 0}, {"w": "Opens the door.", "g": 1}, {"w": "Don't talk.", "g": 0}, {"w": "No talk.", "g": 1}, {"w": "Be happy!", "g": 0}, {"w": "Are happy!", "g": 1}, {"w": "Let's eat.", "g": 0}, {"w": "Let's to eat.", "g": 1}], "id": "bkA1-334"}, {"type": "odd", "level": "A1", "topic": "Imperativo", "instruction": "Qual frase NÃO está no imperativo?", "explain": "As outras dão ordens com o verbo base; \"She sits down.\" descreve uma ação.", "prompt": "Which sentence is different?", "options": ["Sit down.", "Come here.", "Turn left.", "She sits down."], "correctIndex": 3, "id": "bkA1-335"}, {"type": "dorder", "level": "A1", "topic": "Imperativo", "instruction": "Coloque o diálogo na ordem certa.", "explain": "O médico cumprimenta, o paciente diz o problema, recebe instruções e pergunta sobre o café.", "lines": ["Doctor: Hello! Please sit down. What's the problem?", "Patient: I have a bad headache.", "Doctor: OK. Take this medicine twice a day.", "Patient: Can I drink coffee?", "Doctor: No, don't drink coffee this week."], "id": "bkA1-336"}, {"type": "reading", "level": "A1", "topic": "Imperativo", "instruction": "Leia as dicas e responda.", "explain": "As dicas dizem: chegue 10 minutos antes, não use o celular em reuniões, faça perguntas.", "text": "Tips for your first day at work: Arrive ten minutes early. Smile and say hello to your coworkers. Don't use your phone in meetings. Ask questions, because nobody knows everything on the first day! And don't forget your lunch.", "questions": [{"q": "When do you arrive?", "options": ["Ten minutes early", "Ten minutes late", "At lunchtime"], "correctIndex": 0}, {"q": "What don't you do in meetings?", "options": ["Ask questions", "Use your phone", "Smile"], "correctIndex": 1}, {"q": "Why do you ask questions?", "options": ["Your boss likes it.", "Meetings are short.", "Nobody knows everything on the first day."], "correctIndex": 2}], "id": "bkA1-337"}, {"type": "tf", "level": "A1", "topic": "Imperativo", "instruction": "Leia o bilhete e marque verdadeiro ou falso.", "explain": "O bilhete diz: jantar às 7, sem doces, TV até 8h30 e depois cama; a comida está na geladeira.", "text": "Hi Bianca! The kids eat dinner at 7. Give them rice and chicken. It's in the fridge. Don't give them candy. They can watch TV until 8:30. Then put them in bed. Call me if there's a problem. Thanks, Marcela", "items": [{"s": "The kids eat dinner at 7.", "a": true}, {"s": "The kids can eat candy.", "a": false}, {"s": "The kids go to bed before 8:30.", "a": false}, {"s": "The food is in the fridge.", "a": true}], "id": "bkA1-338"}, {"type": "blank", "level": "A1", "topic": "Imperativo", "instruction": "Complete com o imperativo negativo do verbo entre parênteses.", "explain": "Imperativo negativo: Don't + verbo base.", "prompt": "___ (not / eat) in the classroom, please.", "accept": ["Don't eat", "Do not eat"], "id": "bkA1-339"}, {"type": "mcq", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Escolha a preposição correta.", "explain": "Com anos usamos \"in\": in 2014.", "prompt": "The World Cup in Brazil was ___ 2014.", "options": ["in", "on", "at", "to"], "correctIndex": 0, "id": "bkA1-340"}, {"type": "mcq", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Escolha a preposição correta.", "explain": "Para um ponto específico (parada de ônibus) usamos \"at\".", "prompt": "Wait for me ___ the bus stop.", "options": ["at", "in", "on", "to"], "correctIndex": 0, "id": "bkA1-341"}, {"type": "mcq", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Escolha a preposição correta.", "explain": "Sobre uma superfície (parede) usamos \"on\".", "prompt": "There's a spider ___ the wall!", "options": ["on", "in", "at", "to"], "correctIndex": 0, "id": "bkA1-342"}, {"type": "gaps", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Complete o diálogo com in, on ou at.", "explain": "\"At work\", \"at 6 p.m.\" (horário) e \"in bed\" são expressões fixas.", "prompt": "A: Where's Lucas?\nB: He's ___ work. He finishes ___ 6 p.m.\nA: And Jana?\nB: She's ___ bed. She's sick.", "answers": [["at"], ["at"], ["in"]], "id": "bkA1-343"}, {"type": "gaps", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Complete com in, on ou at.", "explain": "Cidade = in; data = on; \"at night\" é expressão fixa.", "prompt": "I was born ___ Recife ___ March 10th, 1995, ___ night.", "answers": [["in"], ["on"], ["at"]], "id": "bkA1-344"}, {"type": "gaps", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Complete com in, on ou at.", "explain": "Cidade = in; rua = on; número exato = at.", "prompt": "A: Where do you live?\nB: I live ___ Santos, ___ Paraná Street, ___ number 45.", "answers": [["in"], ["on"], ["at"]], "id": "bkA1-345"}, {"type": "choose", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Clique na preposição correta.", "explain": "Ponto específico = at; dia da semana = on; partes do dia = in the afternoon.", "prompt": "Let's meet [at*/on] the entrance [on*/in] Friday [at/in*] the afternoon.", "id": "bkA1-346"}, {"type": "choose", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Clique na preposição correta.", "explain": "Andar = on; dentro de um prédio = in; avenida/rua = on (inglês americano).", "prompt": "Ana lives [on*/at] the fifth floor, [in*/on] a building [on*/in] Paulista Avenue.", "id": "bkA1-347"}, {"type": "error", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Encontre o erro na frase.", "explain": "Com horários usamos \"at\": at 8 o'clock.", "sentence": "See you in 8 o'clock!", "wrong": "in", "fix": ["at"], "id": "bkA1-348"}, {"type": "error", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Encontre o erro na frase.", "explain": "Com hospital usamos \"in\" ou \"at\", não \"on\".", "sentence": "My brother is on the hospital.", "wrong": "on", "fix": ["in", "at"], "id": "bkA1-349"}, {"type": "rewrite", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Responda com uma frase completa. Dica: a aula é na terça.", "explain": "Com dias da semana usamos \"on\".", "prompt": "When is your class? (Tuesday)", "start": "My class is", "accept": ["My class is on Tuesday.", "My class is on Tuesdays."], "id": "bkA1-350"}, {"type": "order", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"At school\" e \"at home\" usam \"at\"; \"until noon\" = até meio-dia.", "words": ["The", "kids", "are", "at", "school", "until", "noon"], "alt": ["Until noon the kids are at school", "Until noon, the kids are at school"], "id": "bkA1-351"}, {"type": "order", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"At home\" (em casa) e \"on Sundays\" (dias da semana).", "words": ["We", "have", "dinner", "at", "home", "on", "Sundays"], "alt": ["On Sundays we have dinner at home", "On Sundays, we have dinner at home", "We have dinner on Sundays at home"], "id": "bkA1-352"}, {"type": "match", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Ligue as partes das frases.", "explain": "Superfície = on; região = in; horário = at; dia específico = on.", "left": ["Put the plates", "Natal is a city", "The alarm clock rings", "Mother's Day in Brazil is"], "right": ["at 5:40 a.m.", "on the table.", "on the second Sunday of May.", "in the northeast of Brazil."], "correctMap": [1, 3, 0, 2], "id": "bkA1-353"}, {"type": "sort", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Separe os lugares: in, on ou at?", "explain": "Dentro (kitchen, pocket, país) = in; superfície/andar = on; ponto ou expressão fixa = at.", "prompt": "Sort the places: in, on or at?", "groups": ["in", "on", "at"], "items": [{"w": "the kitchen", "g": 0}, {"w": "Japan", "g": 0}, {"w": "my pocket", "g": 0}, {"w": "the wall", "g": 1}, {"w": "the second floor", "g": 1}, {"w": "home", "g": 2}, {"w": "work", "g": 2}, {"w": "the bus stop", "g": 2}], "id": "bkA1-354"}, {"type": "odd", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Qual palavra NÃO usa \"on\"?", "explain": "Dias e datas usam \"on\"; meses como June usam \"in\".", "prompt": "Which one does not take \"on\"?", "options": ["Monday", "my birthday", "July 4th", "June"], "correctIndex": 3, "id": "bkA1-355"}, {"type": "dorder", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Coloque o diálogo na ordem certa.", "explain": "A pergunta onde Clara está, ela responde, vem o convite e a resposta com o local.", "lines": ["A: Hi, Clara! Are you at home?", "B: No, I'm at the mall. Why?", "A: Let's have lunch together. Is 1 p.m. OK?", "B: Sure! Meet me at the food court on the third floor."], "id": "bkA1-356"}, {"type": "reading", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Leia o cartaz e responda.", "explain": "O cartaz diz: sábado, primeira banda às 16h, food trucks perto do lago.", "text": "Rock in the Park! Saturday, November 8th, at Ibirapuera Park. The gates open at 2 p.m., and the first band plays at 4 p.m. The food trucks are near the lake. If it rains, the show is on Sunday at the same time.", "questions": [{"q": "What day is the show?", "options": ["On Friday", "On Saturday", "On Sunday"], "correctIndex": 1}, {"q": "What time does the first band play?", "options": ["At 4 p.m.", "At 2 p.m.", "At 8 p.m."], "correctIndex": 0}, {"q": "Where are the food trucks?", "options": ["At the gates", "On the stage", "Near the lake"], "correctIndex": 2}], "id": "bkA1-357"}, {"type": "tf", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Marina mora no sexto andar, trabalha nos fins de semana e à noite, voa para a Europa em dezembro.", "text": "Marina is a flight attendant. She lives in Brasília, in a small apartment on the sixth floor. She works on weekends and at night. In December, she flies to Europe a lot. On her days off, she stays at home and reads.", "items": [{"s": "Marina lives on the sixth floor.", "a": true}, {"s": "She works only in the morning.", "a": false}, {"s": "She flies to Europe in December.", "a": true}, {"s": "On her days off, she goes to the beach.", "a": false}], "id": "bkA1-358"}, {"type": "blank", "level": "A1", "topic": "Preposições In / On / At", "instruction": "Complete com in, on ou at.", "explain": "Local de trabalho: \"at a bank\" ou \"in a bank\" estão corretos.", "prompt": "My father works ___ a bank.", "accept": ["at", "in"], "id": "bkA1-359"}, {"type": "mcq", "level": "A2", "topic": "Present Continuous", "instruction": "Escolha a opção correta.", "explain": "\"Look!\" mostra uma ação acontecendo agora: are + verbo com -ing.", "prompt": "Look! The children ___ in the garden.", "options": ["play", "are playing", "plays", "played"], "correctIndex": 1, "id": "bkA2-0"}, {"type": "gaps", "level": "A2", "topic": "Present Continuous", "instruction": "Complete com o Present Continuous dos verbos entre parênteses.", "explain": "\"Right now\" indica ação em andamento: is/are + -ing. Marcos → is; his sisters → are.", "prompt": "Right now, Marcos ___ (cook) dinner and his sisters ___ (set) the table.", "answers": [["is cooking"], ["are setting"]], "id": "bkA2-1"}, {"type": "gaps", "level": "A2", "topic": "Present Continuous", "instruction": "Complete o texto com as palavras do quadro.", "explain": "Cada ação combina com o contexto: carro → washing, livro → reading, games → playing, bebê → sleeping.", "prompt": "It's Saturday morning at the Oliveira house. Dad ___ the car in the garage. Mom ___ a book on the sofa. The twins ___ video games in the living room, and the baby ___ in her crib.", "answers": [["is washing"], ["is reading"], ["are playing"], ["is sleeping"]], "bank": ["is washing", "is reading", "are playing", "is sleeping", "are eating"], "id": "bkA2-2"}, {"type": "choose", "level": "A2", "topic": "Present Continuous", "instruction": "Escolha a forma correta.", "explain": "As ações estão acontecendo agora, por isso usamos be + -ing: is sleeping, am trying.", "prompt": "Please be quiet. The baby [sleeps/is sleeping*] and I [am trying*/try] to work.", "id": "bkA2-3"}, {"type": "error", "level": "A2", "topic": "Present Continuous", "instruction": "Encontre o erro e corrija.", "explain": "No Present Continuous, depois de is/am/are o verbo vai com -ing: is studying.", "sentence": "She is study English at the moment.", "wrong": "study", "fix": ["studying"], "id": "bkA2-4"}, {"type": "rewrite", "level": "A2", "topic": "Present Continuous", "instruction": "Transforme em pergunta.", "explain": "Na pergunta, o verbo to be vem antes do sujeito: Are they working...?", "prompt": "They are working from home today.", "start": "Are", "accept": ["Are they working from home today?"], "id": "bkA2-5"}, {"type": "order", "level": "A2", "topic": "Present Continuous", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta: Wh- word + are + sujeito + verbo com -ing.", "words": ["Why", "are", "you", "wearing", "a", "coat", "today"], "alt": [], "id": "bkA2-6"}, {"type": "dorder", "level": "A2", "topic": "Present Continuous", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta onde Julia está, ela responde; depois A pergunta o que ela compra.", "lines": ["A: Hi, Julia! Where are you?", "B: I'm at the mall. I'm buying a present for Leo.", "A: Oh, nice! What are you buying?", "B: A T-shirt. He loves blue, so I'm looking for a blue one."], "id": "bkA2-7"}, {"type": "tf", "level": "A2", "topic": "Present Continuous", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O texto diz o que cada pessoa está fazendo agora: Renata lê, Caio cozinha, o cachorro dorme.", "text": "It's 8 p.m. in São Paulo. Renata is sitting on the balcony. She isn't watching TV tonight; she's reading a novel. Her husband, Caio, is cooking pasta in the kitchen. Their dog is sleeping under the table.", "items": [{"s": "Renata is watching TV.", "a": false}, {"s": "Caio is in the kitchen.", "a": true}, {"s": "The dog is playing.", "a": false}, {"s": "Renata is reading.", "a": true}], "id": "bkA2-8"}, {"type": "match", "level": "A2", "topic": "Present Continuous", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "Cada resposta usa o mesmo sujeito e o mesmo verbo da pergunta, no Present Continuous.", "left": ["What are you doing?", "Where is Dad going?", "Why are the kids laughing?", "Is it raining?"], "right": ["He's going to the bank.", "Because they're watching a funny movie.", "I'm doing my homework.", "No, it isn't. It's sunny."], "correctMap": [2, 0, 1, 3], "id": "bkA2-9"}, {"type": "mcq", "level": "A2", "topic": "Simple Past", "instruction": "Escolha a opção correta.", "explain": "\"Last summer\" indica passado. O passado de go é went (irregular).", "prompt": "Last summer, we ___ to Salvador by plane.", "options": ["go", "went", "gone", "going"], "correctIndex": 1, "id": "bkA2-10"}, {"type": "gaps", "level": "A2", "topic": "Simple Past", "instruction": "Complete com o Simple Past dos verbos.", "explain": "Wake é irregular (woke); miss e arrive são regulares (+ed / +d).", "prompt": "Yesterday, Bia ___ (wake) up late, ___ (miss) the bus and ___ (arrive) at work at ten.", "answers": [["woke"], ["missed"], ["arrived"]], "id": "bkA2-11"}, {"type": "choose", "level": "A2", "topic": "Simple Past", "instruction": "Escolha a palavra correta.", "explain": "Com verbos principais (see, have), perguntas e negativas no passado usam did/didn't.", "prompt": "[Did*/Were] you see the game last night? No, I [didn't*/wasn't] have time.", "id": "bkA2-12"}, {"type": "error", "level": "A2", "topic": "Simple Past", "instruction": "Encontre o erro e corrija.", "explain": "Depois de didn't, o verbo volta para a forma base: didn't go.", "sentence": "We didn't went to the beach last weekend.", "wrong": "went", "fix": ["go"], "id": "bkA2-13"}, {"type": "rewrite", "level": "A2", "topic": "Simple Past", "instruction": "Transforme em pergunta no passado.", "explain": "Pergunta no passado: Did + sujeito + verbo na forma base (buy, não bought).", "prompt": "Carla bought a new phone last week.", "start": "Did", "accept": ["Did Carla buy a new phone last week?"], "id": "bkA2-14"}, {"type": "order", "level": "A2", "topic": "Simple Past", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta no passado: Where + did + sujeito + verbo na forma base.", "words": ["Where", "did", "you", "spend", "your", "last", "vacation"], "alt": [], "id": "bkA2-15"}, {"type": "reading", "level": "A2", "topic": "Simple Past", "instruction": "Leia a mensagem e responda.", "explain": "As respostas estão no texto: chegou na sexta, estava nublado, foi à praia no domingo.", "text": "Hi Tom! My trip to Rio was amazing. I arrived on Friday night and stayed at a small hotel near Copacabana. On Saturday, I visited the Christ the Redeemer statue, but it was very cloudy, so I didn't see much. On Sunday, the sun came out and I spent the whole day at the beach. I came home on Monday morning. Love, Lucy", "questions": [{"q": "When did Lucy arrive in Rio?", "options": ["On Friday", "On Saturday", "On Monday"], "correctIndex": 0}, {"q": "Why didn't she see much from the statue?", "options": ["It was closed.", "She arrived late.", "It was very cloudy."], "correctIndex": 2}, {"q": "What did she do on Sunday?", "options": ["She visited a museum.", "She spent the day at the beach.", "She came home."], "correctIndex": 1}], "id": "bkA2-16"}, {"type": "sort", "level": "A2", "topic": "Simple Past", "instruction": "Classifique os verbos no passado: regulares ou irregulares.", "explain": "Regulares terminam em -ed (watched, studied); irregulares mudam a forma (went, ate).", "prompt": "Regular or irregular?", "groups": ["Regular (-ed)", "Irregular"], "items": [{"w": "watched", "g": 0}, {"w": "worked", "g": 0}, {"w": "studied", "g": 0}, {"w": "visited", "g": 0}, {"w": "went", "g": 1}, {"w": "ate", "g": 1}, {"w": "bought", "g": 1}, {"w": "took", "g": 1}], "id": "bkA2-17"}, {"type": "match", "level": "A2", "topic": "Simple Past", "instruction": "Ligue cada verbo ao seu passado.", "explain": "São verbos irregulares: write→wrote, see→saw, make→made, think→thought.", "left": ["write", "see", "make", "think"], "right": ["thought", "wrote", "made", "saw"], "correctMap": [1, 3, 2, 0], "id": "bkA2-18"}, {"type": "blank", "level": "A2", "topic": "Simple Past", "instruction": "Complete com o Simple Past do verbo.", "explain": "Ação terminada no passado (2015 a 2019): live + d = lived.", "prompt": "My family ___ (live) in Recife from 2015 to 2019.", "accept": ["lived"], "id": "bkA2-19"}, {"type": "mcq", "level": "A2", "topic": "Will x Going To", "instruction": "Escolha a opção correta.", "explain": "Previsão com evidência (nuvens escuras): is going to + verbo.", "prompt": "Look at those dark clouds! It ___ rain.", "options": ["will to", "is going to", "going to", "goes to"], "correctIndex": 1, "id": "bkA2-20"}, {"type": "mcq", "level": "A2", "topic": "Will x Going To", "instruction": "Escolha a opção correta.", "explain": "Decisão tomada na hora, oferecendo ajuda: will + verbo.", "prompt": "A: I'm so thirsty.\nB: Wait here. I ___ get you a glass of water.", "options": ["will", "am going", "going to", "will to"], "correctIndex": 0, "id": "bkA2-21"}, {"type": "gaps", "level": "A2", "topic": "Will x Going To", "instruction": "Complete com a forma de futuro adequada.", "explain": "Plano já decidido (passagens compradas) → going to; opinião sobre o futuro (\"I'm sure\") → will.", "prompt": "A: What are your plans for the holidays?\nB: My wife and I ___ (visit) her parents in Curitiba. We bought the tickets last month.\nA: That sounds great! I'm sure you ___ (have) a good time.", "answers": [["are going to visit", "are visiting"], ["will have", "are going to have"]], "id": "bkA2-22"}, {"type": "choose", "level": "A2", "topic": "Will x Going To", "instruction": "Escolha a forma correta.", "explain": "Going to precisa do verbo be (is going to); will nunca leva -s nem \"to\".", "prompt": "My sister [is going to*/going to] have a baby in June, and I think she [will*/wills] be a great mom.", "id": "bkA2-23"}, {"type": "error", "level": "A2", "topic": "Will x Going To", "instruction": "Encontre o erro e corrija.", "explain": "Depois de will usamos o verbo direto, sem \"to\": will be.", "sentence": "I think it will to be sunny tomorrow.", "wrong": "will to", "fix": ["will", "is going to"], "id": "bkA2-24"}, {"type": "rewrite", "level": "A2", "topic": "Will x Going To", "instruction": "Passe para a forma negativa.", "explain": "Negativa de going to: be + not + going to (are not / aren't).", "prompt": "They are going to buy a new car.", "start": "They", "accept": ["They are not going to buy a new car.", "They aren't going to buy a new car.", "They're not going to buy a new car."], "id": "bkA2-25"}, {"type": "order", "level": "A2", "topic": "Will x Going To", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta sobre planos: What + are + you + going to + verbo.", "words": ["What", "are", "you", "going", "to", "do", "tonight"], "alt": [], "id": "bkA2-26"}, {"type": "dorder", "level": "A2", "topic": "Will x Going To", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A convida, B explica o problema, A decide na hora ajudar (I'll), B agradece.", "lines": ["A: Hey, are you going to the party on Saturday?", "B: I don't know. I don't have a ride.", "A: Don't worry. I'll pick you up at eight.", "B: Great, thanks! I'll be ready."], "id": "bkA2-27"}, {"type": "tf", "level": "A2", "topic": "Will x Going To", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Diego tem um plano (is going to study); os amigos e a mãe fazem previsões com will.", "text": "Next year, Diego is going to study in Canada. He already has a place at a college in Toronto. He is worried about the cold weather, but his friends say he will love the city. His mother thinks he will miss Brazilian food.", "items": [{"s": "Diego has plans to study in Canada.", "a": true}, {"s": "Diego is worried about the food.", "a": false}, {"s": "His friends think he will love Toronto.", "a": true}, {"s": "Diego doesn't have a college yet.", "a": false}], "id": "bkA2-28"}, {"type": "match", "level": "A2", "topic": "Will x Going To", "instruction": "Ligue cada situação à frase certa.", "explain": "Evidência ou plano → going to; decisão na hora → will.", "left": ["Look at that car! It's going too fast.", "I have a headache.", "I bought paint and brushes.", "The phone is ringing."], "right": ["I'll answer it.", "It's going to crash!", "I'm going to paint my bedroom.", "I'll take an aspirin."], "correctMap": [1, 3, 2, 0], "id": "bkA2-29"}, {"type": "mcq", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Escolha a opção correta.", "explain": "Comparando com todas as montanhas do mundo → superlativo: the highest.", "prompt": "Mount Everest is the ___ mountain in the world.", "options": ["higher", "highest", "most high", "more high"], "correctIndex": 1, "id": "bkA2-30"}, {"type": "gaps", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Complete com o comparativo dos adjetivos.", "explain": "Big (curto) → bigger (dobra o g); expensive (longo) → more expensive.", "prompt": "My new apartment is ___ (big) than my old one, but it's also ___ (expensive).", "answers": [["bigger"], ["more expensive"]], "id": "bkA2-31"}, {"type": "choose", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Escolha a forma correta.", "explain": "Bad é irregular (worse, the worst); boring é longo → more boring.", "prompt": "This is the [worst*/baddest] movie of the year, and it's [more boring*/boringer] than the first one.", "id": "bkA2-32"}, {"type": "error", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Encontre o erro e corrija.", "explain": "Hot já vira hotter; não se usa more junto com -er.", "sentence": "Rio is more hotter than Porto Alegre in the winter.", "wrong": "more hotter", "fix": ["hotter"], "id": "bkA2-33"}, {"type": "rewrite", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Reescreva a frase com o comparativo, começando como indicado.", "explain": "\"Not as fast as\" = o outro é mais rápido: faster than.", "prompt": "My car is not as fast as your car.", "start": "Your car is", "accept": ["Your car is faster than my car.", "Your car is faster than mine."], "id": "bkA2-34"}, {"type": "rewrite", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Reescreva usando o superlativo.", "explain": "Nenhuma outra cidade é tão grande → the biggest/the largest.", "prompt": "No other city in Brazil is as big as São Paulo.", "start": "São Paulo is", "accept": ["São Paulo is the biggest city in Brazil.", "São Paulo is the largest city in Brazil."], "id": "bkA2-35"}, {"type": "order", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Superlativo de adjetivo longo: the most + adjetivo + substantivo.", "words": ["This", "is", "the", "most", "beautiful", "beach", "in", "Bahia"], "alt": [], "id": "bkA2-36"}, {"type": "reading", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Leia o texto e responda.", "explain": "Compare preços e distâncias: Serra é o mais barato, Flor o mais perto, Serra tem a melhor vista.", "text": "Three friends are looking for a hotel in Gramado. Hotel Pinheiro costs R$300 a night and is ten minutes from the center. Hotel Serra costs R$250. It is the farthest from the center, but it has the best view. Hotel Flor is the most expensive, at R$400 a night, but it is the closest to the center.", "questions": [{"q": "Which hotel is the cheapest?", "options": ["Hotel Pinheiro", "Hotel Serra", "Hotel Flor"], "correctIndex": 1}, {"q": "Which hotel is closer to the center than Hotel Pinheiro?", "options": ["Hotel Flor", "Hotel Serra", "No hotel"], "correctIndex": 0}, {"q": "Which hotel has the best view?", "options": ["Hotel Flor", "Hotel Pinheiro", "Hotel Serra"], "correctIndex": 2}], "id": "bkA2-37"}, {"type": "sort", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Classifique os adjetivos pela forma do comparativo.", "explain": "Curtos: -er (taller, happier); longos: more; good/bad são irregulares (better, worse).", "prompt": "Sort the adjectives.", "groups": ["-er / -est", "more / most", "Irregular"], "items": [{"w": "tall", "g": 0}, {"w": "cheap", "g": 0}, {"w": "happy", "g": 0}, {"w": "interesting", "g": 1}, {"w": "comfortable", "g": 1}, {"w": "expensive", "g": 1}, {"w": "good", "g": 2}, {"w": "bad", "g": 2}], "id": "bkA2-38"}, {"type": "odd", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Qual palavra não pertence ao grupo?", "explain": "Três são comparativos (-er); tallest é superlativo.", "prompt": "Which word does not belong?", "options": ["bigger", "nicer", "tallest", "older"], "correctIndex": 2, "id": "bkA2-39"}, {"type": "mcq", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Escolha a opção correta.", "explain": "Para dar conselho usamos should.", "prompt": "You look tired. You ___ go to bed early tonight.", "options": ["should", "can't", "mustn't", "don't"], "correctIndex": 0, "id": "bkA2-40"}, {"type": "gaps", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Complete o diálogo com o modal correto.", "explain": "Para falar de habilidade usamos can; na resposta curta: Yes, I can.", "prompt": "A: ___ you swim?\nB: Yes, I ___. I learned when I was six.", "answers": [["Can"], ["can"]], "id": "bkA2-41"}, {"type": "choose", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Escolha a forma correta.", "explain": "Modais não usam \"to\" depois: mustn't use, must turn. Mustn't = proibição.", "prompt": "Students [mustn't*/shouldn't to] use their phones during the exam. They [must*/can to] turn them off.", "id": "bkA2-42"}, {"type": "error", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Encontre o erro e corrija.", "explain": "Depois de should o verbo vem sem \"to\": should drink.", "sentence": "You should to drink more water.", "wrong": "should to", "fix": ["should"], "id": "bkA2-43"}, {"type": "rewrite", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Transforme em pergunta.", "explain": "Com modais, a pergunta começa com o modal: Can + sujeito + verbo.", "prompt": "Maria can speak three languages.", "start": "Can", "accept": ["Can Maria speak three languages?"], "id": "bkA2-44"}, {"type": "order", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Must + verbo na forma base expressa obrigação.", "words": ["You", "must", "wear", "a", "helmet", "on", "a", "motorcycle"], "alt": ["On a motorcycle you must wear a helmet"], "id": "bkA2-45"}, {"type": "dorder", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pede permissão (can I), B nega, A pede conselho (should), B indica o lugar.", "lines": ["A: Excuse me, can I park here?", "B: No, sorry. You can't park here. It's for buses only.", "A: Oh! Where should I park, then?", "B: There's a parking lot on the next street."], "id": "bkA2-46"}, {"type": "tf", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Leia o aviso e marque verdadeiro ou falso.", "explain": "Can = permitido; mustn't = proibido; must = obrigatório.", "text": "Welcome to Parque das Aves! Visitors can take photos, but they mustn't use flash. You shouldn't feed the birds because human food can make them sick. Children under 12 must be with an adult. The park opens at 8:30 a.m.", "items": [{"s": "You can take photos in the park.", "a": true}, {"s": "You can use flash.", "a": false}, {"s": "Children under 12 can visit the park alone.", "a": false}, {"s": "The park opens at 8:30 a.m.", "a": true}], "id": "bkA2-47"}, {"type": "match", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Ligue cada situação à frase adequada.", "explain": "Should = conselho; mustn't = proibição; can = possibilidade; can't = incapacidade.", "left": ["It's very cold outside.", "The sign says 'No smoking'.", "I don't understand this exercise.", "My brother is only two years old."], "right": ["He can't read yet.", "You should wear a coat.", "You can ask the teacher.", "You mustn't smoke here."], "correctMap": [1, 3, 2, 0], "id": "bkA2-48"}, {"type": "blank", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Complete com a forma negativa do modal.", "explain": "Eu tenho que trabalhar, então não posso ir: can't (cannot).", "prompt": "I'm sorry, I ___ (can) come to your party on Saturday. I have to work.", "accept": ["can't", "cannot", "can not"], "id": "bkA2-49"}, {"type": "mcq", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Escolha a opção correta.", "explain": "Put on = vestir, colocar (roupa). Está frio, então coloque a jaqueta.", "prompt": "It's cold. ___ your jacket before you leave.", "options": ["Put on", "Take off", "Turn on", "Give up"], "correctIndex": 0, "id": "bkA2-50"}, {"type": "mcq", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Escolha a opção correta.", "explain": "Look for = procurar. As chaves estão perdidas.", "prompt": "I can't find my keys. Can you help me ___ them?", "options": ["look after", "look for", "look at", "look up"], "correctIndex": 1, "id": "bkA2-51"}, {"type": "gaps", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Complete o texto com as palavras do quadro.", "explain": "Wake up = acordar; get up = levantar; turn on = ligar; go out = sair para se divertir.", "prompt": "Every day, Lucas ___ at 6 a.m., but he ___ at 6:30 because he loves his bed. In the kitchen, he ___ the radio to listen to the news. After work, he often ___ with his friends.", "answers": [["wakes up"], ["gets up"], ["turns on"], ["goes out"]], "bank": ["wakes up", "gets up", "turns on", "goes out", "gives up"], "id": "bkA2-52"}, {"type": "choose", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Escolha o phrasal verb correto.", "explain": "Turn off = desligar (economizar energia); pick up = buscar alguém.", "prompt": "Please [turn off*/turn on] the lights when you leave, and [pick up*/give up] the kids at school at five.", "id": "bkA2-53"}, {"type": "error", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Encontre o erro e corrija.", "explain": "Look after = cuidar de. Look at significa apenas olhar para.", "sentence": "My grandmother looks at my little brother when my parents are at work.", "wrong": "looks at", "fix": ["looks after", "takes care of"], "id": "bkA2-54"}, {"type": "match", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Ligue cada phrasal verb ao seu significado.", "explain": "Give up = desistir; find out = descobrir; come back = voltar; sit down = sentar.", "left": ["give up", "find out", "come back", "sit down"], "right": ["return", "stop trying", "discover", "take a seat"], "correctMap": [1, 2, 0, 3], "id": "bkA2-55"}, {"type": "match", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Ligue as partes para formar frases.", "explain": "Try on = experimentar roupa; turn down = abaixar o volume; give up = desistir; fill out = preencher.", "left": ["I'm going to try on", "Please turn down", "Don't give up", "Can you fill out"], "right": ["this form, please?", "the music. It's too loud.", "these jeans.", "now! You can do it."], "correctMap": [2, 1, 3, 0], "id": "bkA2-56"}, {"type": "reading", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Leia o bilhete e responda.", "explain": "Ana volta na segunda (come back on Monday) e quer que Carol cuide (look after) da gata.", "text": "Hi Carol, I need a favor. I'm going away this weekend, and I'll come back on Monday. Can you look after my cat, Mimi? You just need to fill up her water bowl and give her food twice a day. Please don't let her go out because she always runs away! The key is under the plant. Thanks! Ana", "questions": [{"q": "When will Ana come back?", "options": ["On Saturday", "On Sunday", "On Monday"], "correctIndex": 2}, {"q": "What does Ana want Carol to do?", "options": ["Take care of her cat", "Find her cat", "Buy a plant"], "correctIndex": 0}, {"q": "Why shouldn't the cat go out?", "options": ["It gets sick.", "It runs away.", "It's too cold."], "correctIndex": 1}], "id": "bkA2-57"}, {"type": "odd", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Qual expressão não pertence ao grupo?", "explain": "Put on, take off e try on são usados com roupas; look after significa cuidar.", "prompt": "Which one does not belong?", "options": ["put on", "take off", "try on", "look after"], "correctIndex": 3, "id": "bkA2-58"}, {"type": "order", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Turn off = desligar; o objeto pode vir depois de off ou entre turn e off.", "words": ["Please", "turn", "off", "your", "phone", "during", "the", "movie"], "alt": ["Please turn your phone off during the movie", "During the movie please turn off your phone", "During the movie please turn your phone off"], "id": "bkA2-59"}, {"type": "mcq", "level": "A2", "topic": "Quantificadores", "instruction": "Escolha a opção correta.", "explain": "Sugar é incontável: how much.", "prompt": "How ___ sugar do you want in your coffee?", "options": ["many", "much", "few", "any"], "correctIndex": 1, "id": "bkA2-60"}, {"type": "gaps", "level": "A2", "topic": "Quantificadores", "instruction": "Complete com much ou many.", "explain": "People é contável (plural) → how many; food é incontável → how much.", "prompt": "How ___ people are coming to the party? And how ___ food do we need?", "answers": [["many"], ["much"]], "id": "bkA2-61"}, {"type": "choose", "level": "A2", "topic": "Quantificadores", "instruction": "Escolha a forma correta.", "explain": "A few + contável plural (friends); a little + incontável (Spanish).", "prompt": "I have [a few*/a little] friends in Manaus, and I speak [a little*/a few] Spanish.", "id": "bkA2-62"}, {"type": "choose", "level": "A2", "topic": "Quantificadores", "instruction": "Escolha a forma correta.", "explain": "Traffic é incontável: verbo no singular (isn't) e much.", "prompt": "There [isn't*/aren't] [much*/many] traffic today.", "id": "bkA2-63"}, {"type": "error", "level": "A2", "topic": "Quantificadores", "instruction": "Encontre o erro e corrija.", "explain": "Chairs é contável (plural): usamos many, não much.", "sentence": "There aren't much chairs in the classroom.", "wrong": "much", "fix": ["many", "any", "enough"], "id": "bkA2-64"}, {"type": "rewrite", "level": "A2", "topic": "Quantificadores", "instruction": "Passe para a forma negativa.", "explain": "Na negativa, some vira any (ou usamos no com verbo afirmativo).", "prompt": "There is some juice in the bottle.", "start": "There", "accept": ["There isn't any juice in the bottle.", "There is not any juice in the bottle.", "There is no juice in the bottle.", "There's no juice in the bottle."], "id": "bkA2-65"}, {"type": "dorder", "level": "A2", "topic": "Quantificadores", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Pedido com some, pergunta com how many, pergunta com any, resposta negativa com any.", "lines": ["A: Good morning. Can I have some bread rolls, please?", "B: Sure. How many rolls do you want?", "A: Six, please. And do you have any cheese?", "B: Sorry, we don't have any cheese today."], "id": "bkA2-66"}, {"type": "tf", "level": "A2", "topic": "Quantificadores", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Marta tem muito arroz e muitas bananas, mas nenhum café e só poucos ovos.", "text": "Marta is making a shopping list. She has a lot of rice and some pasta at home, but she doesn't have any coffee. There are only a few eggs in the fridge, so she needs to buy more. She doesn't need any fruit because she has many bananas.", "items": [{"s": "Marta has a lot of rice.", "a": true}, {"s": "She has some coffee.", "a": false}, {"s": "She has a lot of eggs.", "a": false}, {"s": "She has many bananas.", "a": true}], "id": "bkA2-67"}, {"type": "sort", "level": "A2", "topic": "Quantificadores", "instruction": "Classifique: usamos 'much' ou 'many'?", "explain": "Much com incontáveis (time, money); many com contáveis no plural (books, people).", "prompt": "Much or many?", "groups": ["much", "many"], "items": [{"w": "time", "g": 0}, {"w": "money", "g": 0}, {"w": "water", "g": 0}, {"w": "information", "g": 0}, {"w": "books", "g": 1}, {"w": "people", "g": 1}, {"w": "cars", "g": 1}, {"w": "friends", "g": 1}], "id": "bkA2-68"}, {"type": "match", "level": "A2", "topic": "Quantificadores", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "How much → quantidade incontável; how many → número; any/some concordam com contável ou incontável.", "left": ["How much water do you drink?", "How many brothers do you have?", "Is there any coffee?", "Are there any good restaurants here?"], "right": ["Two. They're both older than me.", "About two liters a day.", "Yes, there are a lot.", "Yes, there's some in the kitchen."], "correctMap": [1, 0, 3, 2], "id": "bkA2-69"}, {"type": "mcq", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Escolha a opção correta.", "explain": "Vegetarianos não comem carne: never (nunca).", "prompt": "Paula is a vegetarian. She ___ eats meat.", "options": ["always", "often", "never", "usually"], "correctIndex": 2, "id": "bkA2-70"}, {"type": "gaps", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Complete com always ou never.", "explain": "Every morning = sempre (always); ele odeia chá = nunca (never).", "prompt": "My dad drinks coffee every morning. He ___ has coffee with his breakfast. He hates tea, so he ___ drinks it.", "answers": [["always"], ["never"]], "id": "bkA2-71"}, {"type": "choose", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Escolha a ordem correta.", "explain": "O advérbio vem depois do verbo to be (is always) e antes dos outros verbos (often goes).", "prompt": "Tom [is always*/always is] tired after work, and he [often goes*/goes often] to bed at nine.", "id": "bkA2-72"}, {"type": "error", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Encontre o erro e corrija.", "explain": "O advérbio de frequência vem antes do verbo principal: usually go.", "sentence": "We go usually to the beach on Sundays.", "wrong": "go usually", "fix": ["usually go"], "id": "bkA2-73"}, {"type": "rewrite", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Reescreva incluindo o advérbio entre parênteses na posição correta.", "explain": "Com o verbo to be, o advérbio vem depois dele: is always.", "prompt": "Marina is happy on Fridays. (always)", "accept": ["Marina is always happy on Fridays.", "Marina's always happy on Fridays.", "On Fridays, Marina is always happy."], "id": "bkA2-74"}, {"type": "order", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Hardly ever (quase nunca) vem antes do verbo principal.", "words": ["I", "hardly", "ever", "watch", "TV", "during", "the", "week"], "alt": ["During the week I hardly ever watch TV"], "id": "bkA2-75"}, {"type": "order", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "How often = com que frequência; depois vem do + sujeito + verbo.", "words": ["How", "often", "do", "you", "go", "to", "the", "gym"], "alt": [], "id": "bkA2-76"}, {"type": "reading", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Leia o texto e responda.", "explain": "O texto usa advérbios: always (5 a.m.), usually (almoço no hospital), never (domingos).", "text": "Hello, I'm Kenji, and I'm a nurse in Belo Horizonte. I always get up at 5 a.m. because my shift starts at 7. I usually have lunch at the hospital, but I sometimes bring food from home. I rarely go out on weeknights because I'm tired. On weekends, I often play soccer with my friends. I never work on Sundays.", "questions": [{"q": "What time does Kenji get up?", "options": ["At 5 a.m.", "At 7 a.m.", "At 6 a.m."], "correctIndex": 0}, {"q": "Where does he usually have lunch?", "options": ["At home", "At a restaurant", "At the hospital"], "correctIndex": 2}, {"q": "What does he never do?", "options": ["Play soccer", "Work on Sundays", "Bring food from home"], "correctIndex": 1}], "id": "bkA2-77"}, {"type": "sort", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Classifique os advérbios pela frequência.", "explain": "Always, usually, often, normally = frequente; rarely, hardly ever, never = pouco ou nada.", "prompt": "Sort the adverbs.", "groups": ["Frequente", "Pouco ou nunca"], "items": [{"w": "always", "g": 0}, {"w": "usually", "g": 0}, {"w": "often", "g": 0}, {"w": "normally", "g": 0}, {"w": "rarely", "g": 1}, {"w": "hardly ever", "g": 1}, {"w": "never", "g": 1}], "id": "bkA2-78"}, {"type": "match", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Ligue cada porcentagem ao advérbio correspondente.", "explain": "Always = 100%; usually ≈ 80–90%; sometimes ≈ 50%; never = 0%.", "left": ["100%", "80%", "50%", "0%"], "right": ["sometimes", "never", "always", "usually"], "correctMap": [2, 3, 0, 1], "id": "bkA2-79"}, {"type": "mcq", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Escolha a opção correta.", "explain": "\"They share it\" indica mais de uma irmã: plural terminado em s recebe só apóstrofo (sisters').", "prompt": "This is ___ bedroom. They share it.", "options": ["my sisters'", "my sister's", "my sisters", "my sister"], "correctIndex": 0, "id": "bkA2-80"}, {"type": "gaps", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Complete com o caso genitivo das palavras entre parênteses.", "explain": "Boss → boss's; children é plural irregular (sem s) → children's.", "prompt": "My ___ (boss) name is Carlos. His ___ (children) names are Pedro and Lia.", "answers": [["boss's", "boss'"], ["children's"]], "id": "bkA2-81"}, {"type": "choose", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Escolha a forma correta.", "explain": "Singular: 's (Julia's). Plural terminado em s: só apóstrofo (parents').", "prompt": "[Julia's*/Julias'] phone is new, but her [parents'*/parents's] car is very old.", "id": "bkA2-82"}, {"type": "error", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Encontre o erro e corrija.", "explain": "Para indicar posse, acrescentamos 's ao dono: Pedro's bike.", "sentence": "This is Pedro bike.", "wrong": "Pedro", "fix": ["Pedro's"], "id": "bkA2-83"}, {"type": "rewrite", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Reescreva usando o caso genitivo.", "explain": "Grandparents é plural terminado em s: grandparents' house.", "prompt": "The house of my grandparents is in Minas Gerais.", "start": "My", "accept": ["My grandparents' house is in Minas Gerais."], "id": "bkA2-84"}, {"type": "rewrite", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Reescreva usando o caso genitivo.", "explain": "Em inglês, a posse de pessoas se expressa com 's: my brother's laptop.", "prompt": "This is the laptop of my brother.", "start": "This is", "accept": ["This is my brother's laptop."], "id": "bkA2-85"}, {"type": "order", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Father's office = o escritório do pai; o dono vem antes da coisa.", "words": ["Where", "is", "your", "father's", "office"], "alt": [], "id": "bkA2-86"}, {"type": "dorder", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta de quem é (whose), B sugere Leo, A discorda, B sugere Sara.", "lines": ["A: Whose jacket is this?", "B: I think it's Leo's.", "A: No, Leo's jacket is black. This one is blue.", "B: Oh, then it's probably Sara's."], "id": "bkA2-87"}, {"type": "tf", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O 's mostra de quem é: Bruno's dog = o cachorro do Bruno; Lara's bedroom = o quarto da Lara.", "text": "This is the Costa family. Mr. Costa's name is Jorge, and his wife's name is Helena. Their children's names are Bruno and Lara. Bruno's dog, Rex, sleeps in Lara's bedroom. The family's house is near the beach in Natal.", "items": [{"s": "Helena is Jorge's wife.", "a": true}, {"s": "Rex is Lara's dog.", "a": false}, {"s": "Rex sleeps in Bruno's bedroom.", "a": false}, {"s": "The Costa family lives near the beach.", "a": true}], "id": "bkA2-88"}, {"type": "match", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "Whose pergunta o dono; a resposta usa 's (Tiago's) ou só apóstrofo no plural (kids').", "left": ["Whose bag is this?", "Where is Mom's car?", "Who is Carla?", "Whose shoes are these?"], "right": ["She's my cousin's wife.", "They're the kids'.", "It's in my uncle's garage.", "It's Tiago's."], "correctMap": [3, 2, 0, 1], "id": "bkA2-89"}, {"type": "mcq", "level": "A2", "topic": "Direções", "instruction": "Escolha a opção correta.", "explain": "Between = entre duas coisas (the pharmacy and the bakery).", "prompt": "The bank is ___ the pharmacy and the bakery.", "options": ["between", "next", "opposite of", "across"], "correctIndex": 0, "id": "bkA2-90"}, {"type": "gaps", "level": "A2", "topic": "Direções", "instruction": "Complete as instruções com as palavras do quadro.", "explain": "Go straight ahead = siga em frente; turn = vire; past = passe por; corner = esquina; opposite = em frente a.", "prompt": "___ right at the traffic lights. Then go ___ ahead for two blocks. Walk ___ the school, and the museum is on the ___ of Rua Bahia and Rua Goiás. It's ___ the post office.", "answers": [["Turn", "turn"], ["straight"], ["past"], ["corner"], ["opposite"]], "bank": ["straight", "corner", "next", "opposite", "Turn", "past"], "id": "bkA2-91"}, {"type": "choose", "level": "A2", "topic": "Direções", "instruction": "Escolha a palavra correta.", "explain": "How can I get to...? = Como chego a...? Para posição na sequência usamos ordinal: the second street.", "prompt": "A: Excuse me, [how*/where] can I get to the station?\nB: Go straight and take the [second*/two] street on the left.", "id": "bkA2-92"}, {"type": "error", "level": "A2", "topic": "Direções", "instruction": "Encontre o erro e corrija.", "explain": "A expressão correta é next to (ao lado de).", "sentence": "The supermarket is next of the bank.", "wrong": "next of", "fix": ["next to"], "id": "bkA2-93"}, {"type": "order", "level": "A2", "topic": "Direções", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Is there...? pergunta se existe algo; near here = aqui perto.", "words": ["Is", "there", "a", "pharmacy", "near", "here"], "alt": [], "id": "bkA2-94"}, {"type": "dorder", "level": "A2", "topic": "Direções", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta se há um ponto, B confirma, A pergunta como chegar, B explica, A agradece.", "lines": ["A: Excuse me, is there a bus stop near here?", "B: Yes, there's one on Avenida Paulista.", "A: How do I get there?", "B: Go straight and turn left at the second corner. It's in front of a bank.", "A: Thank you very much!"], "id": "bkA2-95"}, {"type": "reading", "level": "A2", "topic": "Direções", "instruction": "Leia as instruções e responda.", "explain": "Siga a sequência: vire à direita, na esquina do posto vire à esquerda, cerca de dez minutos.", "text": "Welcome to our hotel! Here's how to get to the beach. When you leave the hotel, turn right and walk to the end of the street. At the gas station, turn left. Walk past the supermarket and cross the avenue at the traffic lights. The beach is right in front of you. It takes about ten minutes.", "questions": [{"q": "What do you do when you leave the hotel?", "options": ["Turn left", "Turn right", "Cross the avenue"], "correctIndex": 1}, {"q": "Where do you turn left?", "options": ["At the gas station", "At the supermarket", "At the traffic lights"], "correctIndex": 0}, {"q": "How long does it take to walk to the beach?", "options": ["Five minutes", "Twenty minutes", "About ten minutes"], "correctIndex": 2}], "id": "bkA2-96"}, {"type": "match", "level": "A2", "topic": "Direções", "instruction": "Ligue cada expressão à sua tradução.", "explain": "Turn left = vire à esquerda; go straight ahead = siga em frente; cross = atravesse; go past = passe por.", "left": ["turn left", "go straight ahead", "cross the street", "go past the bank"], "right": ["passe pelo banco", "siga em frente", "vire à esquerda", "atravesse a rua"], "correctMap": [2, 1, 3, 0], "id": "bkA2-97"}, {"type": "odd", "level": "A2", "topic": "Direções", "instruction": "Qual palavra não pertence ao grupo?", "explain": "Between, opposite e next to indicam posição (preposições); turn é um verbo.", "prompt": "Which word is different?", "options": ["between", "opposite", "next to", "turn"], "correctIndex": 3, "id": "bkA2-98"}, {"type": "tf", "level": "A2", "topic": "Direções", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "A casa fica em frente à farmácia (opposite), entre a escola e o parque; não há supermercado.", "text": "My street is small and quiet. There is a bakery on the corner. Next to the bakery, there is a pharmacy. My house is opposite the pharmacy, between a school and a small park. There isn't a supermarket on my street.", "items": [{"s": "The bakery is on the corner.", "a": true}, {"s": "The house is next to the pharmacy.", "a": false}, {"s": "The house is between a school and a park.", "a": true}, {"s": "There is a supermarket on the street.", "a": false}], "id": "bkA2-99"}, {"type": "mcq", "level": "A2", "topic": "Conectores básicos", "instruction": "Escolha a opção correta.", "explain": "So indica consequência: estava com fome, então fiz um sanduíche.", "prompt": "I was hungry, ___ I made a sandwich.", "options": ["because", "but", "so", "or"], "correctIndex": 2, "id": "bkA2-100"}, {"type": "gaps", "level": "A2", "topic": "Conectores básicos", "instruction": "Complete com and, but, or, so ou because.", "explain": "Or oferece opções (tea or coffee); but indica contraste (gosto dos dois, mas prefiro café).", "prompt": "Do you want tea ___ coffee? I like both, ___ I prefer coffee.", "answers": [["or"], ["but"]], "id": "bkA2-101"}, {"type": "choose", "level": "A2", "topic": "Conectores básicos", "instruction": "Escolha o conector correto.", "explain": "Because dá a causa (estava doente); and soma a informação seguinte.", "prompt": "Ana didn't go to school [because*/so] she was sick, [and*/or] she stayed in bed all day.", "id": "bkA2-102"}, {"type": "error", "level": "A2", "topic": "Conectores básicos", "instruction": "Encontre o erro e corrija.", "explain": "A chuva é a causa de ficar em casa, então o conector é because.", "sentence": "I stayed home so it was raining.", "wrong": "so", "fix": ["because", "as", "since"], "id": "bkA2-103"}, {"type": "rewrite", "level": "A2", "topic": "Conectores básicos", "instruction": "Una as frases usando because.", "explain": "Because introduz a causa: estou cansado porque trabalhei muito.", "prompt": "I'm tired. I worked a lot today.", "start": "I'm tired", "accept": ["I'm tired because I worked a lot today."], "id": "bkA2-104"}, {"type": "rewrite", "level": "A2", "topic": "Conectores básicos", "instruction": "Una as frases usando so.", "explain": "So introduz a consequência: estava frio, então não fomos à praia.", "prompt": "It was very cold. We didn't go to the beach.", "start": "It was very cold", "accept": ["It was very cold, so we didn't go to the beach."], "id": "bkA2-105"}, {"type": "order", "level": "A2", "topic": "Conectores básicos", "instruction": "Ordene as palavras para formar uma frase.", "explain": "First e then mostram a sequência das ações.", "words": ["First", "we", "had", "dinner", "and", "then", "we", "watched", "a", "movie"], "alt": ["We had dinner first and then we watched a movie", "We first had dinner and then we watched a movie"], "id": "bkA2-106"}, {"type": "dorder", "level": "A2", "topic": "Conectores básicos", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A convida, B recusa com but, A oferece pagar, B aceita com so.", "lines": ["A: Let's go to the movies tonight!", "B: I'd love to, but I don't have any money.", "A: Don't worry. I can pay this time, and you can pay next time.", "B: OK, so let's meet at the mall at seven."], "id": "bkA2-107"}, {"type": "tf", "level": "A2", "topic": "Conectores básicos", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Os conectores explicam: so (comprou violão porque o piano era caro), because (quer tocar no casamento).", "text": "Felipe loves music, but he can't play an instrument. Last year, he wanted to learn the guitar or the piano. The piano was very expensive, so he bought a guitar. Now he practices every day because he wants to play at his sister's wedding.", "items": [{"s": "Felipe can play the piano.", "a": false}, {"s": "He bought a guitar because the piano was expensive.", "a": true}, {"s": "He practices once a week.", "a": false}, {"s": "He wants to play at a wedding.", "a": true}], "id": "bkA2-108"}, {"type": "match", "level": "A2", "topic": "Conectores básicos", "instruction": "Ligue as partes para formar frases.", "explain": "Because = causa; or = alternativa; but = contraste; so = consequência.", "left": ["I called you", "We can go by bus,", "She studied a lot,", "It started to rain,"], "right": ["so we went inside.", "because I need your help.", "but she didn't pass the test.", "or we can take a taxi."], "correctMap": [1, 3, 2, 0], "id": "bkA2-109"}, {"type": "mcq", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Escolha a opção correta.", "explain": "Water é incontável: não usamos a/an nem many; usamos some.", "prompt": "Can I have ___ water, please?", "options": ["a", "an", "some", "many"], "correctIndex": 2, "id": "bkA2-110"}, {"type": "gaps", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Complete com is ou are.", "explain": "Furniture é incontável (verbo no singular: is); chairs é contável no plural (are).", "prompt": "There ___ (be) a lot of furniture in the living room, and there ___ (be) three chairs in the kitchen.", "answers": [["is"], ["are"]], "id": "bkA2-111"}, {"type": "choose", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Escolha a forma correta.", "explain": "Advice é incontável (some advice); umbrella é contável (an umbrella).", "prompt": "My mom gave me [some*/an] advice and [an*/some] umbrella before my trip.", "id": "bkA2-112"}, {"type": "error", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Encontre o erro e corrija.", "explain": "Homework é incontável: não tem plural.", "sentence": "I have a lot of homeworks tonight.", "wrong": "homeworks", "fix": ["homework"], "id": "bkA2-113"}, {"type": "odd", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Qual palavra não pertence ao grupo?", "explain": "Milk, money e rice são incontáveis; coin é contável (one coin, two coins).", "prompt": "Find the odd one out.", "options": ["milk", "money", "rice", "coin"], "correctIndex": 3, "id": "bkA2-114"}, {"type": "sort", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Classifique os substantivos: contáveis ou incontáveis.", "explain": "Contáveis têm plural (apples, chairs); incontáveis não (bread, furniture, luggage, music).", "prompt": "Countable or uncountable?", "groups": ["Countable", "Uncountable"], "items": [{"w": "apple", "g": 0}, {"w": "chair", "g": 0}, {"w": "egg", "g": 0}, {"w": "bottle", "g": 0}, {"w": "bread", "g": 1}, {"w": "furniture", "g": 1}, {"w": "luggage", "g": 1}, {"w": "music", "g": 1}], "id": "bkA2-115"}, {"type": "reading", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Leia o aviso e responda.", "explain": "O aviso cita café, chá e suco (não leite), ovos à vontade e proíbe levar comida ao quarto.", "text": "Dear guests, breakfast is served from 6:30 to 10:00. We have fresh bread, cheese, ham and a lot of fruit. There is also coffee, tea and orange juice. You can have as many eggs as you want; just ask the cook. Please don't take any food to your room. Enjoy your stay!", "questions": [{"q": "Which drink is NOT mentioned?", "options": ["Milk", "Tea", "Orange juice"], "correctIndex": 0}, {"q": "How many eggs can guests have?", "options": ["Only one", "As many as they want", "None"], "correctIndex": 1}, {"q": "What can't guests do?", "options": ["Ask the cook for eggs", "Drink coffee", "Take food to their rooms"], "correctIndex": 2}], "id": "bkA2-116"}, {"type": "order", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Money é incontável: how much money.", "words": ["How", "much", "money", "do", "you", "need"], "alt": [], "id": "bkA2-117"}, {"type": "match", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Ligue cada embalagem ao produto certo.", "explain": "Usamos recipientes para contar incontáveis: a loaf of bread, a tube of toothpaste, a bar of soap, a carton of milk.", "left": ["a loaf of", "a tube of", "a bar of", "a carton of"], "right": ["soap", "milk", "bread", "toothpaste"], "correctMap": [2, 3, 0, 1], "id": "bkA2-118"}, {"type": "rewrite", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Faça uma pergunta sobre a quantidade de água.", "explain": "Water é incontável, então a pergunta usa how much.", "prompt": "I drink two liters of water every day.", "start": "How much", "accept": ["How much water do you drink every day?", "How much water do you drink a day?"], "id": "bkA2-119"}, {"type": "mcq", "level": "A2", "topic": "Present Continuous", "instruction": "Escolha a opção correta.", "explain": "Pergunta no Present Continuous: are + you + verbo com -ing.", "prompt": "Why ___ you smiling, Beatriz?", "options": ["are", "is", "do", "does"], "correctIndex": 0, "id": "bkA2-120"}, {"type": "mcq", "level": "A2", "topic": "Present Continuous", "instruction": "Escolha a opção correta.", "explain": "Know é verbo de estado: não costuma ir para o Present Continuous.", "prompt": "Ask Rafael. He ___ the answer.", "options": ["knows", "is knowing", "know", "knowing"], "correctIndex": 0, "id": "bkA2-121"}, {"type": "mcq", "level": "A2", "topic": "Present Continuous", "instruction": "Escolha a opção correta.", "explain": "Listen! indica ação acontecendo agora: is + knocking (somebody = singular).", "prompt": "Listen! Somebody ___ at the door.", "options": ["knocks", "is knocking", "knock", "are knocking"], "correctIndex": 1, "id": "bkA2-122"}, {"type": "gaps", "level": "A2", "topic": "Present Continuous", "instruction": "Complete o diálogo com a resposta curta e o Present Continuous.", "explain": "Resposta curta negativa: No, he isn't. Depois: is + studying.", "prompt": "A: Is Gabriel playing soccer now?\nB: No, he ___. He ___ (study) for a test.", "answers": [["is not", "isn't"], ["is studying"]], "id": "bkA2-123"}, {"type": "gaps", "level": "A2", "topic": "Present Continuous", "instruction": "Complete o cartão-postal com as palavras do banco.", "explain": "Cada sujeito pede a forma certa de be: I am, my kids are, my husband is, we are.", "prompt": "Hi from Florianópolis! The weather is perfect today. I ___ on the beach right now. My kids ___ in the sea, and my husband ___ a volleyball game with some friends. We ___ a great time!", "answers": [["am sitting"], ["are swimming"], ["is watching"], ["are having"]], "bank": ["am sitting", "are swimming", "is watching", "are having", "is raining"], "id": "bkA2-124"}, {"type": "choose", "level": "A2", "topic": "Present Continuous", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Look! pede ação agora (is wearing); like é verbo de estado (doesn't like).", "prompt": "Look! Diego [is wearing*/wears] his new sneakers, but he [doesn't like*/isn't liking] them.", "id": "bkA2-125"}, {"type": "choose", "level": "A2", "topic": "Present Continuous", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Pergunta no Present Continuous: Are + sujeito + verbo com -ing.", "prompt": "[Are*/Do] your parents [travel/traveling*/travels] this week?", "id": "bkA2-126"}, {"type": "error", "level": "A2", "topic": "Present Continuous", "instruction": "Encontre o erro e corrija.", "explain": "Não se pode omitir o verbo be: We are waiting.", "sentence": "We waiting for the bus at the moment.", "wrong": "We waiting", "fix": ["We are waiting", "We're waiting"], "id": "bkA2-127"}, {"type": "error", "level": "A2", "topic": "Present Continuous", "instruction": "Encontre o erro e corrija.", "explain": "Swim termina em consoante-vogal-consoante: dobra o m → swimming.", "sentence": "The kids are swiming in the pool.", "wrong": "swiming", "fix": ["swimming"], "id": "bkA2-128"}, {"type": "rewrite", "level": "A2", "topic": "Present Continuous", "instruction": "Faça uma pergunta com What sobre o que Carla está pintando.", "explain": "Wh- + is + sujeito + verbo com -ing: What is Carla painting?", "prompt": "Carla is painting the kitchen.", "start": "What", "accept": ["What is Carla painting?", "What's Carla painting?"], "id": "bkA2-129"}, {"type": "rewrite", "level": "A2", "topic": "Present Continuous", "instruction": "Transforme em frase negativa.", "explain": "Negativa: am + not + verbo com -ing.", "prompt": "I am using the computer now.", "accept": ["I am not using the computer now.", "I'm not using the computer now."], "id": "bkA2-130"}, {"type": "order", "level": "A2", "topic": "Present Continuous", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta: What + is + sujeito + verbo com -ing.", "words": ["What", "is", "your", "sister", "watching", "on", "TV"], "id": "bkA2-131"}, {"type": "order", "level": "A2", "topic": "Present Continuous", "instruction": "Ordene as palavras para formar a frase.", "explain": "Negativa: are + not + staying.", "words": ["We", "are", "not", "staying", "at", "a", "hotel", "this", "time"], "alt": ["This time we are not staying at a hotel"], "id": "bkA2-132"}, {"type": "dorder", "level": "A2", "topic": "Present Continuous", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Ligação de trabalho: pedir para falar, explicar o que a pessoa está fazendo, despedir-se.", "lines": ["A: Hello, can I speak to Mr. Almeida, please?", "B: Sorry, he's in a meeting. He's talking to some clients.", "A: OK. Is his assistant working today?", "B: No, she isn't. She's traveling this week.", "A: No problem. I'll call back later."], "id": "bkA2-133"}, {"type": "tf", "level": "A2", "topic": "Present Continuous", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O texto diz o que cada pessoa está fazendo agora ou nesta semana.", "text": "Fernanda is at Guarulhos Airport. She is waiting for her flight to Lisbon. The flight is late, so she is having a coffee and checking her emails. Her brother is not traveling with her; he is working in São Paulo this week.", "items": [{"s": "Fernanda is waiting for her flight.", "a": true}, {"s": "She is drinking tea.", "a": false}, {"s": "Her brother is working this week.", "a": true}, {"s": "The flight is on time.", "a": false}], "id": "bkA2-134"}, {"type": "reading", "level": "A2", "topic": "Present Continuous", "instruction": "Leia a mensagem e responda.", "explain": "A mensagem descreve o que cada um está fazendo agora e o plano de Nina.", "text": "Hi, Mom! I'm writing from the school library. I'm not coming home for lunch today because I'm doing a project with Lívia and Tiago. We're making a video about the Amazon rainforest. Tiago is filming, and Lívia and I are writing the script. I'm coming home at six. Love, Nina", "questions": [{"q": "Where is Nina now?", "options": ["At home", "At the school library", "At Lívia's house"], "correctIndex": 1}, {"q": "What is Tiago doing?", "options": ["Writing the script", "Filming", "Cooking lunch"], "correctIndex": 1}, {"q": "When is Nina coming home?", "options": ["For lunch", "At six", "Tomorrow"], "correctIndex": 1}], "id": "bkA2-135"}, {"type": "sort", "level": "A2", "topic": "Present Continuous", "instruction": "Separe os verbos: de ação ou de estado.", "explain": "Verbos de estado (know, want, understand, need) normalmente não vão para o -ing.", "prompt": "Can we use it in the Present Continuous?", "groups": ["Action verbs (OK with -ing)", "State verbs (usually no -ing)"], "items": [{"w": "run", "g": 0}, {"w": "cook", "g": 0}, {"w": "dance", "g": 0}, {"w": "write", "g": 0}, {"w": "know", "g": 1}, {"w": "want", "g": 1}, {"w": "understand", "g": 1}, {"w": "need", "g": 1}], "id": "bkA2-136"}, {"type": "match", "level": "A2", "topic": "Present Continuous", "instruction": "Ligue cada verbo à sua forma com -ing.", "explain": "make→making (tira o e), sit→sitting (dobra), lie→lying (ie vira y), study→studying.", "left": ["make", "sit", "lie", "study"], "right": ["studying", "lying", "making", "sitting"], "correctMap": [2, 3, 1, 0], "id": "bkA2-137"}, {"type": "odd", "level": "A2", "topic": "Present Continuous", "instruction": "Qual verbo normalmente NÃO usamos no Present Continuous?", "explain": "Believe é verbo de estado; play, eat e read são verbos de ação.", "prompt": "Which verb do we NOT usually use in the Present Continuous?", "options": ["play", "eat", "believe", "read"], "correctIndex": 2, "id": "bkA2-138"}, {"type": "blank", "level": "A2", "topic": "Present Continuous", "instruction": "Complete com o Present Continuous (plano já combinado para o futuro).", "explain": "Present Continuous para compromissos futuros combinados: are having.", "prompt": "We ___ (have) a barbecue at my uncle's house next Sunday. Do you want to come?", "accept": ["are having"], "id": "bkA2-139"}, {"type": "mcq", "level": "A2", "topic": "Simple Past", "instruction": "Escolha a opção correta.", "explain": "Pergunta com be no passado: Were you...? (you → were).", "prompt": "A: ___ you at home last night?\nB: No, I was at the gym.", "options": ["Were", "Did", "Was", "Are"], "correctIndex": 0, "id": "bkA2-140"}, {"type": "mcq", "level": "A2", "topic": "Simple Past", "instruction": "Escolha a opção correta.", "explain": "Negativa no passado: didn't + verbo na forma base (do).", "prompt": "Rodrigo ___ his homework yesterday because he was sick.", "options": ["didn't do", "didn't did", "doesn't do", "not did"], "correctIndex": 0, "id": "bkA2-141"}, {"type": "mcq", "level": "A2", "topic": "Simple Past", "instruction": "Escolha a opção correta.", "explain": "Pergunta no passado com verbo comum: Wh- + did + sujeito + verbo base.", "prompt": "Where ___ you buy that jacket? It's beautiful!", "options": ["did", "were", "was", "are"], "correctIndex": 0, "id": "bkA2-142"}, {"type": "gaps", "level": "A2", "topic": "Simple Past", "instruction": "Complete o diálogo com respostas curtas e perguntas no passado.", "explain": "Respostas curtas e perguntas com did: Yes, I did / Did...? / No, she didn't.", "prompt": "A: Did you like the concert?\nB: Yes, I ___. It was fantastic!\nA: ___ Marcela go with you?\nB: No, she ___. She was at work.", "answers": [["did"], ["Did"], ["did not", "didn't"]], "id": "bkA2-143"}, {"type": "gaps", "level": "A2", "topic": "Simple Past", "instruction": "Complete o texto com os verbos do banco.", "explain": "Todos são passados irregulares: went, made, flew, took, got.", "prompt": "Last Saturday, my family and I ___ to Ibirapuera Park for a picnic. My mom ___ delicious sandwiches for everybody. My little brother ___ his new kite high in the sky, and my dad ___ a lot of photos. We ___ home at six, tired but happy.", "answers": [["went"], ["made", "brought", "took"], ["flew"], ["took"], ["got", "went", "came", "arrived"]], "bank": ["went", "made", "flew", "took", "got", "ate"], "id": "bkA2-144"}, {"type": "choose", "level": "A2", "topic": "Simple Past", "instruction": "Escolha a forma correta em cada grupo.", "explain": "I → was; negativa com didn't + verbo base (have).", "prompt": "When I [was*/were] a child, I [didn't have*/didn't had] a cell phone.", "id": "bkA2-145"}, {"type": "choose", "level": "A2", "topic": "Simple Past", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Last night pede passado: eat → ate (irregular), watch → watched.", "prompt": "Last night we [ate*/eat/eated] pizza and [watched*/watch] a movie.", "id": "bkA2-146"}, {"type": "error", "level": "A2", "topic": "Simple Past", "instruction": "Encontre o erro e corrija.", "explain": "Buy é irregular: o passado é bought.", "sentence": "She buyed a new dress for the party.", "wrong": "buyed", "fix": ["bought"], "id": "bkA2-147"}, {"type": "error", "level": "A2", "topic": "Simple Past", "instruction": "Encontre o erro e corrija.", "explain": "We pede were no passado do verbo be.", "sentence": "We was very tired after the trip.", "wrong": "was", "fix": ["were"], "id": "bkA2-148"}, {"type": "rewrite", "level": "A2", "topic": "Simple Past", "instruction": "Faça uma pergunta com Where sobre a frase.", "explain": "Where + did + sujeito + verbo base (go).", "prompt": "Paulo went to Argentina.", "start": "Where", "accept": ["Where did Paulo go?"], "id": "bkA2-149"}, {"type": "rewrite", "level": "A2", "topic": "Simple Past", "instruction": "Transforme em frase negativa.", "explain": "Negativa do be no passado: were + not (weren't).", "prompt": "The kids were at school yesterday.", "accept": ["The kids were not at school yesterday.", "The kids weren't at school yesterday."], "id": "bkA2-150"}, {"type": "order", "level": "A2", "topic": "Simple Past", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta no passado: What time + did + you + get up.", "words": ["What", "time", "did", "you", "get", "up", "this", "morning"], "id": "bkA2-151"}, {"type": "order", "level": "A2", "topic": "Simple Past", "instruction": "Ordene as palavras para formar a frase.", "explain": "Para nascimento usamos was/were born.", "words": ["I", "was", "born", "in", "Porto", "Alegre", "in", "1998"], "alt": ["In 1998 I was born in Porto Alegre", "I was born in 1998 in Porto Alegre"], "id": "bkA2-152"}, {"type": "dorder", "level": "A2", "topic": "Simple Past", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Conversa de segunda-feira sobre o fim de semana, toda no passado.", "lines": ["A: Hi, Sérgio! How was your weekend?", "B: It was great. I went to a wedding in Belo Horizonte.", "A: Really? Whose wedding was it?", "B: My cousin's. The party finished at 3 a.m.!"], "id": "bkA2-153"}, {"type": "tf", "level": "A2", "topic": "Simple Past", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O texto conta o dia de Ricardo em ordem, no passado.", "text": "Ricardo had a bad day yesterday. His alarm didn't ring, so he woke up at 8:30. He took a taxi to the office, but there was a lot of traffic. He arrived late for an important meeting. In the evening, he ordered a pizza and went to bed early.", "items": [{"s": "Ricardo woke up early.", "a": false}, {"s": "He went to work by taxi.", "a": true}, {"s": "He was on time for the meeting.", "a": false}, {"s": "He went to bed early.", "a": true}], "id": "bkA2-154"}, {"type": "reading", "level": "A2", "topic": "Simple Past", "instruction": "Leia o texto e responda.", "explain": "Texto biográfico no passado: datas e fatos da vida de Santos Dumont.", "text": "Santos Dumont was born in Minas Gerais in 1873. When he was 18, he moved to Paris. There, he built balloons and airships. In 1906, he flew his plane, the 14-bis, in front of a big crowd. Many Brazilians say he was the father of aviation. He died in 1932.", "questions": [{"q": "Where was Santos Dumont born?", "options": ["In Paris", "In Minas Gerais", "In São Paulo"], "correctIndex": 1}, {"q": "What did he do in 1906?", "options": ["He flew the 14-bis", "He moved to Paris", "He was born"], "correctIndex": 0}, {"q": "How old was he when he moved to Paris?", "options": ["18", "33", "59"], "correctIndex": 0}], "id": "bkA2-155"}, {"type": "sort", "level": "A2", "topic": "Simple Past", "instruction": "Separe os sujeitos: usam was ou were?", "explain": "I, he, she, it e nomes no singular → was; you, we, they e plurais → were.", "prompt": "Which verb goes with each subject: was or were?", "groups": ["was", "were"], "items": [{"w": "I", "g": 0}, {"w": "he", "g": 0}, {"w": "she", "g": 0}, {"w": "the movie", "g": 0}, {"w": "you", "g": 1}, {"w": "we", "g": 1}, {"w": "they", "g": 1}, {"w": "my parents", "g": 1}], "id": "bkA2-156"}, {"type": "match", "level": "A2", "topic": "Simple Past", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "When → tempo; Who → pessoa; How → opinião; Why → motivo (because).", "left": ["When did you arrive?", "Who did you meet?", "How was the trip?", "Why did you leave early?"], "right": ["Because I was tired.", "Last Tuesday.", "It was amazing!", "My old teacher."], "correctMap": [1, 3, 2, 0], "id": "bkA2-157"}, {"type": "odd", "level": "A2", "topic": "Simple Past", "instruction": "Qual verbo tem passado regular?", "explain": "Play → played é regular; go (went), eat (ate) e write (wrote) são irregulares.", "prompt": "Which verb has a regular past form?", "options": ["go", "eat", "play", "write"], "correctIndex": 2, "id": "bkA2-158"}, {"type": "blank", "level": "A2", "topic": "Simple Past", "instruction": "Complete com a negativa do Simple Past.", "explain": "Negativa no passado: did not (didn't) + verbo base.", "prompt": "Ana ___ (not/call) me last night.", "accept": ["did not call", "didn't call"], "id": "bkA2-159"}, {"type": "mcq", "level": "A2", "topic": "Will x Going To", "instruction": "Escolha a opção correta.", "explain": "Decisão tomada na hora da fala: will + verbo base.", "prompt": "A: We don't have any milk.\nB: Oh, really? I ___ buy some on my way home.", "options": ["will", "am", "going to", "will to"], "correctIndex": 0, "id": "bkA2-160"}, {"type": "mcq", "level": "A2", "topic": "Will x Going To", "instruction": "Escolha a opção correta.", "explain": "Previsão com evidência (o copo está na beirada): going to.", "prompt": "Be careful! That glass is at the edge of the table. It ___ fall.", "options": ["is going to", "will to", "goes to", "going"], "correctIndex": 0, "id": "bkA2-161"}, {"type": "mcq", "level": "A2", "topic": "Will x Going To", "instruction": "Escolha a opção correta.", "explain": "Promessa: will + verbo base (sem s, sem to).", "prompt": "Don't worry, Mom. I ___ call you when I arrive in Recife.", "options": ["will", "am going", "going", "wills"], "correctIndex": 0, "id": "bkA2-162"}, {"type": "gaps", "level": "A2", "topic": "Will x Going To", "instruction": "Complete o diálogo.", "explain": "Pergunta com going to: Are you going to...? Plano: am going to study.", "prompt": "A: ___ you going to watch the final tonight?\nB: No, I'm not. I ___ (study) for my exam.", "answers": [["Are"], ["am going to study", "am studying", "will study"]], "id": "bkA2-163"}, {"type": "gaps", "level": "A2", "topic": "Will x Going To", "instruction": "Complete o diálogo com o verbo be.", "explain": "Going to precisa do be: you are going to / I am going to.", "prompt": "A: What ___ you going to do after the course?\nB: I ___ going to look for a job in Portugal.", "answers": [["are"], ["am"]], "id": "bkA2-164"}, {"type": "choose", "level": "A2", "topic": "Will x Going To", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Pergunta com going to: Are you going to + verbo base.", "prompt": "[Are*/Do] you going to [buy*/buying] a new laptop?", "id": "bkA2-165"}, {"type": "choose", "level": "A2", "topic": "Will x Going To", "instruction": "Escolha a forma correta.", "explain": "Opinião sobre o futuro (I think): will + verbo base. Going sem to está errado.", "prompt": "I think Brazil [will*/is going] win the next World Cup.", "id": "bkA2-166"}, {"type": "error", "level": "A2", "topic": "Will x Going To", "instruction": "Encontre o erro e corrija.", "explain": "Going to precisa do to antes do verbo: going to study.", "sentence": "She is going study medicine next year.", "wrong": "going study", "fix": ["going to study"], "id": "bkA2-167"}, {"type": "error", "level": "A2", "topic": "Will x Going To", "instruction": "Encontre o erro e corrija.", "explain": "Depois de will vem o verbo base, sem to.", "sentence": "Will you to help me with the dishes?", "wrong": "to help", "fix": ["help"], "id": "bkA2-168"}, {"type": "rewrite", "level": "A2", "topic": "Will x Going To", "instruction": "Transforme em pergunta.", "explain": "Pergunta com will: Will + sujeito + verbo base.", "prompt": "Lara will be at the meeting.", "start": "Will", "accept": ["Will Lara be at the meeting?"], "id": "bkA2-169"}, {"type": "rewrite", "level": "A2", "topic": "Will x Going To", "instruction": "Reescreva o plano usando going to.", "explain": "Plano já decidido: be + going to + verbo base.", "prompt": "Sofia plans to learn to drive next year.", "start": "Sofia is going to", "accept": ["Sofia is going to learn to drive next year.", "Sofia is going to learn how to drive next year."], "id": "bkA2-170"}, {"type": "order", "level": "A2", "topic": "Will x Going To", "instruction": "Ordene as palavras para formar a frase.", "explain": "Promessa com will not (won't).", "words": ["I", "promise", "I", "will", "not", "be", "late", "again"], "id": "bkA2-171"}, {"type": "order", "level": "A2", "topic": "Will x Going To", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta com going to: Where + are + they + going to + verbo.", "words": ["Where", "are", "they", "going", "to", "stay", "in", "Rome"], "id": "bkA2-172"}, {"type": "dorder", "level": "A2", "topic": "Will x Going To", "instruction": "Coloque o diálogo na ordem certa.", "explain": "No restaurante, decidimos na hora: I'll have...", "lines": ["A: Are you ready to order?", "B: Yes. I'll have the grilled fish, please.", "A: And what would you like to drink?", "B: I'll have an orange juice."], "id": "bkA2-173"}, {"type": "tf", "level": "A2", "topic": "Will x Going To", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Going to = planos do casal; will = opiniões sobre o tempo.", "text": "Carolina and Pedro are going to get married in December. They are going to have the party at a farm near Campinas. They invited 150 guests. Carolina thinks it will rain, but Pedro is sure the weather will be perfect.", "items": [{"s": "The wedding is in December.", "a": true}, {"s": "The party is going to be at a hotel.", "a": false}, {"s": "Pedro thinks it will rain.", "a": false}, {"s": "They invited 150 people.", "a": true}], "id": "bkA2-174"}, {"type": "reading", "level": "A2", "topic": "Will x Going To", "instruction": "Leia o e-mail e responda.", "explain": "Going to para os planos de Marina; will para previsões (I'm sure I'll...).", "text": "Hi Jess, Big news! I'm going to start a new job in April. I'm going to work for a tech company in Recife, so I'm going to move there next month. I don't know anybody in the city, but I'm sure I'll make friends quickly. Will you visit me? You'll love the beaches! Hugs, Marina", "questions": [{"q": "What is Marina going to do in April?", "options": ["Start a new job", "Visit Jess", "Go on vacation"], "correctIndex": 0}, {"q": "Where is she going to live?", "options": ["In Recife", "In São Paulo", "She doesn't know yet"], "correctIndex": 0}, {"q": "What does Marina think?", "options": ["She won't have friends.", "She will make friends fast.", "She will hate the beaches."], "correctIndex": 1}], "id": "bkA2-175"}, {"type": "sort", "level": "A2", "topic": "Will x Going To", "instruction": "Separe as situações: will ou going to?", "explain": "Will: decisão na hora, promessa, oferta. Going to: plano feito antes ou evidência.", "prompt": "Will or going to? Sort the situations.", "groups": ["will (decision now, promise, offer)", "going to (plan, evidence)"], "items": [{"w": "The phone rings. You decide to answer it.", "g": 0}, {"w": "You promise to help a friend.", "g": 0}, {"w": "You offer to open the window.", "g": 0}, {"w": "You bought plane tickets for July.", "g": 1}, {"w": "There are black clouds in the sky.", "g": 1}, {"w": "You planned a trip to Chile last month.", "g": 1}], "id": "bkA2-176"}, {"type": "match", "level": "A2", "topic": "Will x Going To", "instruction": "Ligue cada situação à resposta certa.", "explain": "Oferta e decisão na hora → will; evidência e plano → going to.", "left": ["I'm hungry.", "It's cold in here.", "Look at that man on the ladder!", "We already have the tickets."], "right": ["He's going to fall!", "We're going to see the show on Friday.", "I'll make you a sandwich.", "I'll close the window."], "correctMap": [2, 3, 0, 1], "id": "bkA2-177"}, {"type": "odd", "level": "A2", "topic": "Will x Going To", "instruction": "Qual frase NÃO fala do futuro?", "explain": "We went... está no passado; as outras usam will ou going to.", "prompt": "Which sentence is NOT about the future?", "options": ["I'll call you later.", "She's going to travel.", "We went to the beach.", "They will win."], "correctIndex": 2, "id": "bkA2-178"}, {"type": "blank", "level": "A2", "topic": "Will x Going To", "instruction": "Complete com will ou going to.", "explain": "Oferta de ajuda decidida na hora: will fix.", "prompt": "A: The printer isn't working.\nB: Don't worry. I ___ (fix) it for you.", "accept": ["will fix"], "id": "bkA2-179"}, {"type": "mcq", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Escolha a opção correta.", "explain": "Hot é curto e termina em consoante-vogal-consoante: dobra o t → hotter.", "prompt": "Today is ___ than yesterday. Let's go to the beach!", "options": ["hotter", "more hot", "hottest", "hoter"], "correctIndex": 0, "id": "bkA2-180"}, {"type": "mcq", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Escolha a opção correta.", "explain": "Good é irregular: good → better → the best.", "prompt": "Paulo is the ___ student in our class. He always gets top grades.", "options": ["best", "better", "goodest", "most good"], "correctIndex": 0, "id": "bkA2-181"}, {"type": "mcq", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Escolha a opção correta.", "explain": "No comparativo usamos than (do que), não that nem then.", "prompt": "This phone is cheaper ___ that one.", "options": ["than", "that", "of", "then"], "correctIndex": 0, "id": "bkA2-182"}, {"type": "gaps", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Complete com o comparativo ou o superlativo.", "explain": "Comparando dois: younger than. O mais alto da família inteira: the tallest.", "prompt": "Maria is ___ (young) than her brother, but she's the ___ (tall) person in the family.", "answers": [["younger"], ["tallest"]], "id": "bkA2-183"}, {"type": "gaps", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Complete o diálogo com a forma comparativa.", "explain": "Easy → easier (y vira ier); useful é longo → more useful.", "prompt": "A: Which is ___ (easy), Spanish or English?\nB: For me, Spanish is ___ (easy) than English, but English is ___ (useful) for my job.", "answers": [["easier"], ["easier"], ["more useful"]], "id": "bkA2-184"}, {"type": "choose", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Escolha a forma correta.", "explain": "Delicious é longo: superlativo com the most.", "prompt": "My grandma makes the [most delicious*/more delicious] feijoada in the family.", "id": "bkA2-185"}, {"type": "choose", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Heavy → heavier (y vira ier). Entre todas as malas do ônibus: the biggest.", "prompt": "Your bag is [heavier*/more heavy] than mine, and it's [the biggest*/the bigger] bag on the bus.", "id": "bkA2-186"}, {"type": "error", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Encontre o erro e corrija.", "explain": "O restaurante mais caro da cidade: superlativo the most expensive.", "sentence": "This is the more expensive restaurant in the city.", "wrong": "the more expensive", "fix": ["the most expensive"], "id": "bkA2-187"}, {"type": "error", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Encontre o erro e corrija.", "explain": "Comparativo + than (do que).", "sentence": "My brother is taller that my father.", "wrong": "that", "fix": ["than"], "id": "bkA2-188"}, {"type": "rewrite", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Reescreva com o mesmo sentido, começando como indicado.", "explain": "Se o vermelho é mais barato, o azul é mais caro: more expensive than.", "prompt": "The red dress is cheaper than the blue dress.", "start": "The blue dress", "accept": ["The blue dress is more expensive than the red dress.", "The blue dress is more expensive than the red one."], "id": "bkA2-189"}, {"type": "rewrite", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Reescreva usando as ... as.", "explain": "Mesma altura: as + adjetivo + as.", "prompt": "Marta is 1.65 m tall. Clara is 1.65 m tall too.", "start": "Marta is as", "accept": ["Marta is as tall as Clara.", "Marta is as tall as Clara is."], "id": "bkA2-190"}, {"type": "order", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Superlativo: the + longest.", "words": ["Which", "is", "the", "longest", "river", "in", "Brazil"], "id": "bkA2-191"}, {"type": "order", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Ordene as palavras para formar a frase.", "explain": "Interesting é longo: more interesting than.", "words": ["My", "new", "job", "is", "more", "interesting", "than", "my", "old", "one"], "id": "bkA2-192"}, {"type": "dorder", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Comparando dois celulares: better, more expensive, cheaper.", "lines": ["A: I like these two phones. Which one is better?", "B: The black one has a better camera.", "A: But it's more expensive, right?", "B: Yes, it's R$500 more than the white one.", "A: OK, I'll take the white one. It's cheaper."], "id": "bkA2-193"}, {"type": "tf", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Compare os tempos e as idades: menor tempo = mais rápido.", "text": "Three friends ran a race in Brasília. Bruno finished in 25 minutes, Lia in 22 minutes and Jorge in 30 minutes. Jorge is the oldest of the three; he is 45. Lia is younger than Bruno. She trains the most, so she was the fastest.", "items": [{"s": "Bruno was the fastest.", "a": false}, {"s": "Jorge was slower than Lia.", "a": true}, {"s": "Lia is older than Bruno.", "a": false}, {"s": "Jorge is the oldest.", "a": true}], "id": "bkA2-194"}, {"type": "reading", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Leia o texto e responda.", "explain": "O texto compara dois notebooks: lighter, bigger, better, more expensive, cheaper.", "text": "Laura is choosing a laptop for college. The Zeta 3 is lighter and smaller than the Nova X, so it's easier to carry. The Nova X has a bigger screen and a better battery. It is also R$800 more expensive. Laura watches a lot of movies, but she doesn't have much money. In the end, she chooses the cheaper laptop.", "questions": [{"q": "Which laptop is lighter?", "options": ["The Zeta 3", "The Nova X", "They are the same."], "correctIndex": 0}, {"q": "Which one has the better battery?", "options": ["The Zeta 3", "The Nova X", "Both"], "correctIndex": 1}, {"q": "Which laptop does Laura buy?", "options": ["The Zeta 3", "The Nova X", "Neither"], "correctIndex": 0}], "id": "bkA2-195"}, {"type": "sort", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Separe: comparativo ou superlativo?", "explain": "Comparativo compara dois (-er, more); superlativo usa the (-est, the most).", "prompt": "Comparative or superlative?", "groups": ["Comparative", "Superlative"], "items": [{"w": "smaller", "g": 0}, {"w": "more famous", "g": 0}, {"w": "worse", "g": 0}, {"w": "farther", "g": 0}, {"w": "the smallest", "g": 1}, {"w": "the most famous", "g": 1}, {"w": "the worst", "g": 1}, {"w": "the farthest", "g": 1}], "id": "bkA2-196"}, {"type": "match", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Ligue cada palavra ao seu superlativo.", "explain": "São superlativos irregulares: the best, the worst, the farthest, the most.", "left": ["good", "bad", "far", "many"], "right": ["the most", "the worst", "the farthest", "the best"], "correctMap": [3, 1, 2, 0], "id": "bkA2-197"}, {"type": "odd", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Qual comparativo está ERRADO?", "explain": "Good é irregular: o comparativo é better, não gooder.", "prompt": "Which one is NOT a correct comparative?", "options": ["bigger", "gooder", "happier", "worse"], "correctIndex": 1, "id": "bkA2-198"}, {"type": "blank", "level": "A2", "topic": "Comparativos e superlativos", "instruction": "Complete com o superlativo.", "explain": "O mais frio de todos os meses: the coldest.", "prompt": "July is usually the ___ (cold) month of the year in São Paulo.", "accept": ["coldest"], "id": "bkA2-199"}, {"type": "mcq", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Escolha a opção correta.", "explain": "Para pedir permissão usamos Can I...?", "prompt": "___ I use your charger? My phone is dead.", "options": ["Can", "Must", "Am", "Does"], "correctIndex": 0, "id": "bkA2-200"}, {"type": "mcq", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Escolha a opção correta.", "explain": "Regra/lei = obrigação: must.", "prompt": "In Brazil, you ___ be 18 to get a driver's license.", "options": ["must", "can", "should", "mustn't"], "correctIndex": 0, "id": "bkA2-201"}, {"type": "mcq", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Escolha a opção correta.", "explain": "Impossibilidade: can't + verbo base. Não existe doesn't can nem mustn't to.", "prompt": "Bruno broke his leg, so he ___ play in the match on Sunday.", "options": ["can't", "mustn't to", "can", "doesn't can"], "correctIndex": 0, "id": "bkA2-202"}, {"type": "gaps", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Complete o diálogo com can ou can't.", "explain": "Pergunta: Can + sujeito + verbo. Resposta curta: No, he can't. Habilidade: he can.", "prompt": "A: Your English is great! ___ your brother speak English too?\nB: No, he ___. But he ___ speak Spanish very well.", "answers": [["Can"], ["cannot", "can't"], ["can"]], "id": "bkA2-203"}, {"type": "gaps", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Complete os conselhos do médico com um modal.", "explain": "Conselho: should; conselho negativo: shouldn't (must/mustn't também são possíveis, mais fortes).", "prompt": "Doctor: You have a bad cold. You ___ stay in bed for two days, and you ___ go to work. You ___ drink hot tea with honey.", "answers": [["should", "must"], ["should not", "shouldn't", "must not", "mustn't", "cannot", "can't"], ["should", "can", "must", "could"]], "id": "bkA2-204"}, {"type": "choose", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Escolha a forma correta.", "explain": "Negativa de should: shouldn't (não usamos don't com modais).", "prompt": "You [shouldn't*/don't should] eat so much sugar. It's bad for your teeth.", "id": "bkA2-205"}, {"type": "choose", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Modais não usam do: Can you...? / I can't.", "prompt": "[Can you*/Do you can] help me? I [can't*/don't can] open this jar.", "id": "bkA2-206"}, {"type": "error", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Encontre o erro e corrija.", "explain": "Modais não recebem s na 3ª pessoa: she can.", "sentence": "She cans play the piano very well.", "wrong": "cans", "fix": ["can"], "id": "bkA2-207"}, {"type": "error", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Encontre o erro e corrija.", "explain": "Must não usa do na pergunta: Must I...? (ou Do I have to...?).", "sentence": "Do I must wear a tie to the party?", "wrong": "Do I must", "fix": ["Must I", "Do I have to", "Should I"], "id": "bkA2-208"}, {"type": "rewrite", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Transforme em pergunta.", "explain": "Pergunta com modal: Should + sujeito + verbo base.", "prompt": "We should take a taxi.", "start": "Should", "accept": ["Should we take a taxi?"], "id": "bkA2-209"}, {"type": "rewrite", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Reescreva a regra como proibição, com mustn't.", "explain": "Proibição: must not (mustn't) + verbo base.", "prompt": "Phones are not allowed in the exam room.", "start": "You", "accept": ["You mustn't use your phone in the exam room.", "You mustn't use phones in the exam room.", "You mustn't use your phones in the exam room.", "You mustn't use a phone in the exam room.", "You mustn't use cell phones in the exam room.", "You mustn't have your phone in the exam room.", "You must not use your phone in the exam room.", "You must not use phones in the exam room.", "You must not use your phones in the exam room.", "You must not use a phone in the exam room.", "You must not use cell phones in the exam room.", "You must not have your phone in the exam room."], "id": "bkA2-210"}, {"type": "order", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Ordene as palavras para formar a frase.", "explain": "Conselho negativo: shouldn't + verbo base.", "words": ["You", "shouldn't", "go", "to", "bed", "so", "late"], "id": "bkA2-211"}, {"type": "order", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Ordene as palavras para formar um pedido.", "explain": "Pedido educado: Can you + verbo + please.", "words": ["Can", "you", "speak", "more", "slowly", "please"], "alt": ["Can you please speak more slowly"], "id": "bkA2-212"}, {"type": "dorder", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Coloque o diálogo na ordem certa.", "explain": "No médico: problema, pergunta, resposta e conselho com should.", "lines": ["A: Doctor, I always feel tired.", "B: How many hours do you sleep?", "A: About five hours a night.", "B: That's not enough. You should sleep at least seven hours.", "A: OK, I'll try. Thank you, doctor."], "id": "bkA2-213"}, {"type": "tf", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Leia as regras e marque verdadeiro ou falso.", "explain": "Must = obrigação; can = permissão; mustn't = proibição; should = conselho.", "text": "Rules for the pool at Clube Atlântico: Everybody must take a shower before swimming. You can use the pool from 7 a.m. to 9 p.m. You mustn't eat or drink in the water. Children under 10 can swim only with an adult. You should bring your own towel.", "items": [{"s": "You must take a shower before you swim.", "a": true}, {"s": "You can swim at 10 p.m.", "a": false}, {"s": "You can eat in the pool.", "a": false}, {"s": "A nine-year-old can swim with his father.", "a": true}], "id": "bkA2-214"}, {"type": "reading", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Leia a mensagem e responda.", "explain": "Can = permitido; mustn't = proibido; should = recomendação.", "text": "Welcome to my apartment! You can use the kitchen and the washing machine. You mustn't smoke inside, but you can smoke on the balcony. Please don't make noise after 10 p.m. because my neighbors are very strict. You should visit the market on Sunday; it's great. Enjoy! Rosa", "questions": [{"q": "Where can guests smoke?", "options": ["In the kitchen", "On the balcony", "Nowhere"], "correctIndex": 1}, {"q": "What should guests visit?", "options": ["The market on Sunday", "The neighbors", "The beach"], "correctIndex": 0}, {"q": "What can guests use?", "options": ["Only the balcony", "The kitchen and the washing machine", "The neighbors' car"], "correctIndex": 1}], "id": "bkA2-215"}, {"type": "sort", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Separe as frases corretas e as incorretas.", "explain": "Modais não levam s, to nem do, e o verbo depois fica na forma base.", "prompt": "Is the sentence correct?", "groups": ["Correct", "Incorrect"], "items": [{"w": "She can drive.", "g": 0}, {"w": "You should rest.", "g": 0}, {"w": "We must go now.", "g": 0}, {"w": "Can I sit here?", "g": 0}, {"w": "She cans drive.", "g": 1}, {"w": "You should to rest.", "g": 1}, {"w": "We must going now.", "g": 1}, {"w": "Do I can sit here?", "g": 1}], "id": "bkA2-216"}, {"type": "match", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Ligue cada problema ao conselho ou regra certa.", "explain": "Should dá conselho; mustn't indica proibição.", "left": ["I have a toothache.", "I want to learn English faster.", "The museum sign says 'No photos'.", "I lost my passport."], "right": ["You mustn't use your camera.", "You should go to the police.", "You should watch series in English.", "You should see a dentist."], "correctMap": [3, 2, 0, 1], "id": "bkA2-217"}, {"type": "odd", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Qual palavra NÃO é um modal?", "explain": "Can, must e should são modais; want é verbo comum (wants, to + verbo).", "prompt": "Which word is NOT a modal verb?", "options": ["can", "must", "should", "want"], "correctIndex": 3, "id": "bkA2-218"}, {"type": "blank", "level": "A2", "topic": "Modais básicos (can, should, must)", "instruction": "Complete com um modal de conselho.", "explain": "Para dar conselho usamos should (must também é possível, mais forte).", "prompt": "You look sick. I think you ___ go to the doctor.", "accept": ["should", "must"], "id": "bkA2-219"}, {"type": "mcq", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Escolha a opção correta.", "explain": "Take off = tirar (roupa, sapatos).", "prompt": "Please ___ your shoes before you come in. The floor is clean.", "options": ["take off", "put on", "get off", "turn off"], "correctIndex": 0, "id": "bkA2-220"}, {"type": "mcq", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Escolha a opção correta.", "explain": "Run out of = ficar sem, acabar (o leite acabou).", "prompt": "We ___ of milk, so I went to the supermarket.", "options": ["ran out", "ran away", "ran into", "ran up"], "correctIndex": 0, "id": "bkA2-221"}, {"type": "mcq", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Escolha a opção correta.", "explain": "Get off = descer de ônibus, trem, avião.", "prompt": "This is our stop. Let's ___ the bus.", "options": ["get off", "get on", "get up", "get out"], "correctIndex": 0, "id": "bkA2-222"}, {"type": "gaps", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Complete com o verbo entre parênteses no tempo certo.", "explain": "grow up (cresceu, passado: grew); work out (malha); go out (sai).", "prompt": "Kátia ___ (grow) up in a small town in Bahia, but now she lives in São Paulo. She ___ (work) out at the gym every morning and ___ (go) out with friends on Fridays.", "answers": [["grew"], ["works"], ["goes"]], "id": "bkA2-223"}, {"type": "gaps", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Complete o diálogo com as partículas do banco.", "explain": "call back = retornar a ligação; write down = anotar; hang up = desligar o telefone.", "prompt": "A: Hello, can I speak to Dr. Lima?\nB: Sorry, she's out. Can she call you ___ later?\nA: Yes, please. My number is 98765-4321.\nB: Just a moment, I'll write it ___.\nA: Thanks. OK, I'm going to hang ___ now. Bye!", "answers": [["back"], ["down"], ["up"]], "bank": ["back", "down", "up", "off", "on"], "id": "bkA2-224"}, {"type": "choose", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Escolha o phrasal verb correto em cada grupo.", "explain": "Take off = tirar a roupa; throw away = jogar fora.", "prompt": "It's hot in here. Can I [take off*/put on] my jacket? And please don't [throw away*/throw up] that box. I need it.", "id": "bkA2-225"}, {"type": "choose", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Escolha a ordem correta em cada grupo.", "explain": "Com pronome (it, them), ele fica entre o verbo e a partícula: hang it up, pick them up.", "prompt": "My jacket? I hung [it up*/up it] in the closet. And your books are on the floor. Please [pick them up*/pick up them].", "id": "bkA2-226"}, {"type": "error", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Encontre o erro e corrija.", "explain": "Com frio, queremos desligar ou diminuir o ar: turn off / turn down (turn up = aumentar).", "sentence": "I'm freezing! Can you turn up the air conditioning?", "wrong": "up", "fix": ["off", "down"], "id": "bkA2-227"}, {"type": "error", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Encontre o erro e corrija.", "explain": "Anotar = write down.", "sentence": "Please write up your name and address here.", "wrong": "up", "fix": ["down"], "id": "bkA2-228"}, {"type": "rewrite", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Reescreva trocando 'your shoes' por um pronome.", "explain": "Com pronome, ele vai no meio: take them off.", "prompt": "Take off your shoes.", "start": "Take", "accept": ["Take them off."], "id": "bkA2-229"}, {"type": "rewrite", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Reescreva usando o phrasal verb 'break down' no passado.", "explain": "Break down = quebrar (carro, máquina); passado: broke down.", "prompt": "My car stopped working on the road.", "start": "My car", "accept": ["My car broke down on the road."], "id": "bkA2-230"}, {"type": "order", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Take off = decolar (avião). Pergunta: What time + does + sujeito + verbo.", "words": ["What", "time", "does", "your", "flight", "take", "off"], "id": "bkA2-231"}, {"type": "order", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Ordene as palavras para formar a frase.", "explain": "Eat out = comer fora; o advérbio usually vem antes do verbo.", "words": ["We", "usually", "eat", "out", "on", "Saturday", "nights"], "alt": ["On Saturday nights we usually eat out", "Usually we eat out on Saturday nights"], "id": "bkA2-232"}, {"type": "dorder", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Coloque o diálogo na ordem certa.", "explain": "No hotel: check in (entrada) e check out (saída).", "lines": ["A: Good afternoon. I'd like to check in, please.", "B: Of course. Can I see your passport?", "A: Here you are.", "B: Thank you. Your room is 305. Breakfast is from seven to ten.", "A: Great. And what time do I need to check out?", "B: Before noon, please."], "id": "bkA2-233"}, {"type": "tf", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "give up = parar; throw away = jogar fora; look up = pesquisar; work out = malhar.", "text": "Last month, Rafael decided to give up sugar. It was difficult at first. He threw away all the chocolate in his house and looked up healthy recipes online. Now he works out three times a week, and he feels great. His sister wants to try it too.", "items": [{"s": "Rafael stopped eating sugar.", "a": true}, {"s": "He kept the chocolate in the kitchen.", "a": false}, {"s": "He found recipes on the internet.", "a": true}, {"s": "He exercises every day.", "a": false}], "id": "bkA2-234"}, {"type": "reading", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Leia o bilhete e responda.", "explain": "take out = levar para fora; put away = guardar; come over = vir visitar.", "text": "Hi Leo, I'm going out to the supermarket. Before you go to school, please take out the trash and put away the dishes. Don't forget to turn off the computer. Your grandma is coming over at five, so please clean up your room! See you later, Dad", "questions": [{"q": "Where is Dad going?", "options": ["To school", "To the supermarket", "To Grandma's house"], "correctIndex": 1}, {"q": "What does Leo need to do with the dishes?", "options": ["Wash them", "Put them away", "Throw them away"], "correctIndex": 1}, {"q": "Who is visiting at five?", "options": ["Leo's grandma", "Leo's friends", "Dad's boss"], "correctIndex": 0}], "id": "bkA2-235"}, {"type": "sort", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Separe: roupas ou aparelhos?", "explain": "Put on, take off, try on, dress up → roupas; turn on, switch off, turn up, plug in → aparelhos.", "prompt": "Clothes or machines?", "groups": ["Clothes", "Machines"], "items": [{"w": "put on", "g": 0}, {"w": "take off", "g": 0}, {"w": "try on", "g": 0}, {"w": "dress up", "g": 0}, {"w": "turn on", "g": 1}, {"w": "switch off", "g": 1}, {"w": "turn up", "g": 1}, {"w": "plug in", "g": 1}], "id": "bkA2-236"}, {"type": "match", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Ligue cada phrasal verb ao seu significado.", "explain": "grow up = crescer; call back = retornar ligação; eat out = comer fora; calm down = acalmar-se.", "left": ["grow up", "call back", "eat out", "calm down"], "right": ["have a meal in a restaurant", "relax and stop being nervous", "become an adult", "return a phone call"], "correctMap": [2, 3, 0, 1], "id": "bkA2-237"}, {"type": "odd", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Qual phrasal verb NÃO tem relação com viagem?", "explain": "Check in, take off e get on são de viagem; clean up = arrumar, limpar.", "prompt": "Which one is NOT about travel?", "options": ["check in", "take off", "get on", "clean up"], "correctIndex": 3, "id": "bkA2-238"}, {"type": "blank", "level": "A2", "topic": "Phrasal Verbs", "instruction": "Complete com o verbo que forma o phrasal verb.", "explain": "Look up = procurar (no dicionário, na internet).", "prompt": "I don't know this word. I'm going to ___ it up in the dictionary.", "accept": ["look"], "id": "bkA2-239"}, {"type": "mcq", "level": "A2", "topic": "Quantificadores", "instruction": "Escolha a opção correta.", "explain": "Frase afirmativa com substantivo contável plural: a lot of.", "prompt": "There are ___ tourists in Gramado in July. The hotels are full.", "options": ["a lot of", "much", "a little", "any"], "correctIndex": 0, "id": "bkA2-240"}, {"type": "mcq", "level": "A2", "topic": "Quantificadores", "instruction": "Escolha a opção correta.", "explain": "Time é incontável; em negativas usamos much.", "prompt": "I don't have ___ time today. Can we talk tomorrow?", "options": ["much", "many", "a few", "some"], "correctIndex": 0, "id": "bkA2-241"}, {"type": "mcq", "level": "A2", "topic": "Quantificadores", "instruction": "Escolha a opção correta.", "explain": "Em ofertas (Would you like...?) usamos some, mesmo sendo pergunta.", "prompt": "Would you like ___ cake?", "options": ["some", "many", "a few", "a lot"], "correctIndex": 0, "id": "bkA2-242"}, {"type": "gaps", "level": "A2", "topic": "Quantificadores", "instruction": "Complete o diálogo.", "explain": "Pergunta: any (ou some). Pouca quantidade de incontável: a little.", "prompt": "A: Is there ___ milk in the fridge?\nB: Yes, but only ___ little. We need to buy more.", "answers": [["any", "some"], ["a"]], "id": "bkA2-243"}, {"type": "gaps", "level": "A2", "topic": "Quantificadores", "instruction": "Complete o texto com as palavras do banco.", "explain": "a lot of (muitos); many em negativa; only a few (poucos); too much + incontável.", "prompt": "My city is great for food. It has ___ of good restaurants — more than 500! But it doesn't have ___ parks; there are only two. There are only ___ trees on the main avenue, and there is too ___ traffic.", "answers": [["a lot", "lots"], ["many"], ["a few"], ["much"]], "bank": ["a lot", "many", "a few", "much", "little"], "id": "bkA2-244"}, {"type": "choose", "level": "A2", "topic": "Quantificadores", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Enough = suficiente; too many + contável plural (cars).", "prompt": "I can't buy it. I don't have [enough*/too] money. And there are [too many*/too much] cars in the city.", "id": "bkA2-245"}, {"type": "choose", "level": "A2", "topic": "Quantificadores", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Languages é contável → many. Homework é incontável → a lot of.", "prompt": "How [many*/much] languages do you speak? I have [a lot of*/many] homework today.", "id": "bkA2-246"}, {"type": "error", "level": "A2", "topic": "Quantificadores", "instruction": "Encontre o erro e corrija.", "explain": "Em inglês não usamos duas negativas: don't have any money.", "sentence": "I don't have no money.", "wrong": "no", "fix": ["any"], "id": "bkA2-247"}, {"type": "error", "level": "A2", "topic": "Quantificadores", "instruction": "Encontre o erro e corrija.", "explain": "Water é incontável: a little, não a few.", "sentence": "There is a few water in the bottle.", "wrong": "a few", "fix": ["a little", "some"], "id": "bkA2-248"}, {"type": "rewrite", "level": "A2", "topic": "Quantificadores", "instruction": "Transforme em negativa usando much.", "explain": "Negativa com incontável: don't have much.", "prompt": "I have a lot of free time.", "accept": ["I don't have much free time.", "I do not have much free time."], "id": "bkA2-249"}, {"type": "rewrite", "level": "A2", "topic": "Quantificadores", "instruction": "Transforme em pergunta.", "explain": "Em perguntas, some normalmente vira any: Are there any...?", "prompt": "There are some good hotels near the beach.", "start": "Are", "accept": ["Are there any good hotels near the beach?"], "id": "bkA2-250"}, {"type": "order", "level": "A2", "topic": "Quantificadores", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "People é contável plural: How many people...?", "words": ["How", "many", "people", "work", "in", "your", "office"], "id": "bkA2-251"}, {"type": "order", "level": "A2", "topic": "Quantificadores", "instruction": "Ordene as palavras para formar a frase.", "explain": "Negativa com incontável: isn't much food.", "words": ["There", "isn't", "much", "food", "left", "in", "the", "kitchen"], "id": "bkA2-252"}, {"type": "dorder", "level": "A2", "topic": "Quantificadores", "instruction": "Coloque o diálogo na ordem certa.", "explain": "any (pergunta), a lot of, how many, some (vou comprar alguns).", "lines": ["A: Let's make a cake for Dani's birthday. Do we have any flour?", "B: Yes, we have a lot of flour.", "A: Great. How many eggs do we need?", "B: Four. But we only have two.", "A: OK, I'll go and buy some."], "id": "bkA2-253"}, {"type": "tf", "level": "A2", "topic": "Quantificadores", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "only a few = poucos; a lot of = muitos; not many = poucos; a little = um pouco.", "text": "Vila Nova is a small village in the mountains. There are only a few houses, and there isn't a hospital. There are a lot of cows and horses, but there aren't many cars. In winter, there is a little snow, and many tourists come to see it.", "items": [{"s": "There are many houses in Vila Nova.", "a": false}, {"s": "There is no hospital.", "a": true}, {"s": "There are a lot of cars.", "a": false}, {"s": "It snows a little in winter.", "a": true}], "id": "bkA2-254"}, {"type": "reading", "level": "A2", "topic": "Quantificadores", "instruction": "Leia a mensagem e responda.", "explain": "any (negativa), a little (pouco), too many (demais), some (alguns).", "text": "Hi Beto, can you go to the market? We need a lot of things for the barbecue on Sunday. Please buy two kilos of meat and some sausages. We don't need any bread; I bought some yesterday. We have only a little charcoal, so buy one bag. And don't buy too many drinks, because Carla is bringing some. Thanks! Vera", "questions": [{"q": "What does Beto NOT need to buy?", "options": ["Bread", "Meat", "Charcoal"], "correctIndex": 0}, {"q": "How much charcoal do they have now?", "options": ["A lot", "A little", "None"], "correctIndex": 1}, {"q": "Why shouldn't Beto buy a lot of drinks?", "options": ["They are expensive.", "Carla is bringing some.", "Nobody drinks."], "correctIndex": 1}], "id": "bkA2-255"}, {"type": "sort", "level": "A2", "topic": "Quantificadores", "instruction": "Separe as frases: completam com some ou any?", "explain": "Some em afirmativas e ofertas; any em negativas.", "prompt": "Some or any? Sort the sentences.", "groups": ["some", "any"], "items": [{"w": "We need ___ eggs for the cake.", "g": 0}, {"w": "There's ___ milk in the fridge.", "g": 0}, {"w": "I bought ___ apples at the market.", "g": 0}, {"w": "Would you like ___ tea?", "g": 0}, {"w": "We don't have ___ bread.", "g": 1}, {"w": "She didn't buy ___ shoes.", "g": 1}, {"w": "There aren't ___ buses today.", "g": 1}, {"w": "I don't need ___ help, thanks.", "g": 1}], "id": "bkA2-256"}, {"type": "match", "level": "A2", "topic": "Quantificadores", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "How much (preço/incontável), How many (contável), any (existe?), enough (suficiente).", "left": ["How much does it cost?", "How many kids do you have?", "Is there any coffee left?", "Do you have enough chairs?"], "right": ["No, we need three more.", "Two, a boy and a girl.", "Just a little. I'll make more.", "Twenty reais."], "correctMap": [3, 1, 2, 0], "id": "bkA2-257"}, {"type": "odd", "level": "A2", "topic": "Quantificadores", "instruction": "Qual palavra NÃO é um quantificador?", "explain": "Much, many e a lot of indicam quantidade; very intensifica adjetivos.", "prompt": "Which word is NOT a quantifier?", "options": ["much", "many", "a lot of", "very"], "correctIndex": 3, "id": "bkA2-258"}, {"type": "blank", "level": "A2", "topic": "Quantificadores", "instruction": "Complete com much ou many.", "explain": "People é contável plural: too many people.", "prompt": "There are too ___ people on this bus. Let's wait for the next one.", "accept": ["many"], "id": "bkA2-259"}, {"type": "mcq", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Escolha a resposta certa para How often.", "explain": "How often pergunta a frequência: once a month (uma vez por mês).", "prompt": "A: How often do you visit your grandparents?\nB: ___", "options": ["Once a month.", "Tomorrow.", "Yesterday.", "For two hours."], "correctIndex": 0, "id": "bkA2-260"}, {"type": "mcq", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Escolha a opção correta.", "explain": "Com o verbo be, o advérbio vem depois: is never.", "prompt": "My boss ___ late for meetings.", "options": ["is never", "never is", "never", "is not never"], "correctIndex": 0, "id": "bkA2-261"}, {"type": "mcq", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Escolha a opção correta.", "explain": "Uma vez a cada dois anos é pouquíssimo: rarely.", "prompt": "I ___ go to the dentist, maybe once every two years.", "options": ["rarely", "always", "usually", "often"], "correctIndex": 0, "id": "bkA2-262"}, {"type": "gaps", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Complete o diálogo com advérbios de frequência.", "explain": "Toda sexta = com frequência (usually/often); difícil demais = nunca ou quase nunca.", "prompt": "A: Do you ever eat sushi?\nB: Yes, I ___ eat it on Fridays with my team. But I ___ make it at home. It's too difficult!", "answers": [["usually", "often", "sometimes", "always", "normally"], ["never", "rarely", "hardly ever", "seldom"]], "id": "bkA2-263"}, {"type": "gaps", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Complete o texto com os advérbios do banco.", "explain": "Todo dia = always; duas vezes por semana = sometimes; quase nunca = rarely; não gosta = never.", "prompt": "Hi! I'm Joana and I work at a bakery. I ___ start work at 5 a.m., every single day. I ___ have a coffee at 9, about twice a week. I ___ take a day off; I only had two days off last year. And I ___ eat the bread I make, because I don't like bread!", "answers": [["always"], ["sometimes", "occasionally"], ["rarely", "hardly ever", "seldom"], ["never"]], "bank": ["always", "sometimes", "rarely", "never", "usually"], "id": "bkA2-264"}, {"type": "choose", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Escolha a palavra correta em cada grupo.", "explain": "Pergunta: Do you ever...? Resposta negativa: I never (sem not).", "prompt": "Do you [ever*/never] play video games? No, I [never*/ever] play them.", "id": "bkA2-265"}, {"type": "choose", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Com modal, o advérbio vem depois dele: can never. Sometimes pode abrir a frase.", "prompt": "She [can never*/never can] remember my birthday. [Sometimes*/Ever] I walk to work.", "id": "bkA2-266"}, {"type": "error", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Encontre o erro e corrija.", "explain": "Com o verbo be, o advérbio vem depois: is always.", "sentence": "Rodrigo always is happy in the morning.", "wrong": "always is", "fix": ["is always"], "id": "bkA2-267"}, {"type": "error", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Encontre o erro e corrija.", "explain": "Never já é negativo: não use com don't.", "sentence": "I don't never drink soda.", "wrong": "don't never", "fix": ["never", "don't ever", "do not ever"], "id": "bkA2-268"}, {"type": "rewrite", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Reescreva a frase colocando o advérbio entre parênteses.", "explain": "Com verbo comum, o advérbio vem antes do verbo: usually goes.", "prompt": "Carla goes to the gym. (usually)", "accept": ["Carla usually goes to the gym.", "Usually Carla goes to the gym.", "Usually, Carla goes to the gym."], "id": "bkA2-269"}, {"type": "rewrite", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Faça a pergunta sobre a frequência.", "explain": "How often + does + sujeito + verbo base.", "prompt": "Leo plays tennis twice a week.", "start": "How often", "accept": ["How often does Leo play tennis?"], "id": "bkA2-270"}, {"type": "order", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Ordene as palavras para formar a frase.", "explain": "O advérbio vem antes do verbo principal: sometimes watch.", "words": ["My", "parents", "sometimes", "watch", "movies", "on", "Sunday", "afternoons"], "alt": ["Sometimes my parents watch movies on Sunday afternoons", "On Sunday afternoons my parents sometimes watch movies"], "id": "bkA2-271"}, {"type": "order", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Ordene as palavras para formar a frase.", "explain": "Com o verbo be, o advérbio vem depois: are never.", "words": ["We", "are", "never", "at", "home", "on", "Saturday", "mornings"], "alt": ["On Saturday mornings we are never at home"], "id": "bkA2-272"}, {"type": "dorder", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Conversa sobre hábitos com often, usually e sometimes.", "lines": ["A: Do you often cook at home?", "B: Not really. I usually have lunch at the office.", "A: And what about dinner?", "B: I sometimes make pasta, but I often order food."], "id": "bkA2-273"}, {"type": "tf", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Observe os advérbios: usually, often, never, sometimes.", "text": "Gustavo is a taxi driver in Rio. He usually works from 6 a.m. to 4 p.m. He often has lunch in his car. He never works on Sundays because he goes to church with his family. He sometimes plays soccer on the beach in the evening.", "items": [{"s": "Gustavo usually starts work at 6 a.m.", "a": true}, {"s": "He always has lunch in a restaurant.", "a": false}, {"s": "He works every Sunday.", "a": false}, {"s": "He sometimes plays soccer.", "a": true}], "id": "bkA2-274"}, {"type": "reading", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Leia a pesquisa e responda.", "explain": "Os números mostram a frequência dos hábitos dos alunos.", "text": "We asked 100 students at our school about their habits. Ninety students always use their phones before bed. Sixty students usually have breakfast at home. Only 15 students often read books for fun, and 5 students never do their homework! Most students sometimes play sports on the weekend.", "questions": [{"q": "What do almost all the students do before bed?", "options": ["Read books", "Use their phones", "Do homework"], "correctIndex": 1}, {"q": "How many students often read for fun?", "options": ["15", "60", "90"], "correctIndex": 0}, {"q": "How often do most students play sports on the weekend?", "options": ["Always", "Sometimes", "Never"], "correctIndex": 1}], "id": "bkA2-275"}, {"type": "sort", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Separe: advérbio de uma palavra ou expressão de frequência?", "explain": "Advérbios (always, often...) vêm antes do verbo; expressões (every day...) vêm no fim da frase.", "prompt": "One-word adverb or time expression?", "groups": ["One-word adverb (before the verb)", "Expression (usually at the end)"], "items": [{"w": "always", "g": 0}, {"w": "often", "g": 0}, {"w": "seldom", "g": 0}, {"w": "usually", "g": 0}, {"w": "every day", "g": 1}, {"w": "twice a week", "g": 1}, {"w": "once a month", "g": 1}, {"w": "on weekends", "g": 1}], "id": "bkA2-276"}, {"type": "match", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "Cada resposta combina com a pergunta sobre frequência.", "left": ["How often do you go to the movies?", "Are you ever late for work?", "Do you always walk to school?", "How often does your grandma call you?"], "right": ["No, sometimes I take the bus.", "Almost every day. She misses me!", "Hardly ever. I'm very punctual.", "About once a month."], "correctMap": [3, 2, 0, 1], "id": "bkA2-277"}, {"type": "odd", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Qual palavra NÃO é advérbio de frequência?", "explain": "Quickly é advérbio de modo (como), não de frequência.", "prompt": "Which word is NOT an adverb of frequency?", "options": ["often", "rarely", "quickly", "usually"], "correctIndex": 2, "id": "bkA2-278"}, {"type": "blank", "level": "A2", "topic": "Advérbios de frequência", "instruction": "Complete com um advérbio de frequência.", "explain": "Toma café da manhã todo dia, então nunca pula: never.", "prompt": "A: Do you eat breakfast?\nB: Yes, every day. I ___ skip it.", "accept": ["never"], "id": "bkA2-279"}, {"type": "mcq", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Escolha a opção correta.", "explain": "Um dono (my father) → father's car.", "prompt": "This is my ___ car. He bought it last year.", "options": ["father's", "fathers", "father", "fathers'"], "correctIndex": 0, "id": "bkA2-280"}, {"type": "mcq", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Escolha a opção correta.", "explain": "Women é plural irregular (sem s): acrescentamos 's → women's.", "prompt": "The ___ bathroom is on the left, next to the stairs.", "options": ["women's", "womens'", "woman", "womens"], "correctIndex": 0, "id": "bkA2-281"}, {"type": "mcq", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Escolha a opção correta.", "explain": "Whose pergunta de quem é algo. Who's = who is.", "prompt": "A: ___ umbrella is this?\nB: It's Tânia's.", "options": ["Whose", "Who's", "Who", "Which"], "correctIndex": 0, "id": "bkA2-282"}, {"type": "gaps", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Complete o diálogo.", "explain": "Para coisas usamos of (the name of the street); para pessoas, 's.", "prompt": "A: What's the name ___ this street?\nB: Rua das Flores. My ___ (grandmother) house is at the end ___ the street.", "answers": [["of"], ["grandmother's"], ["of"]], "id": "bkA2-283"}, {"type": "gaps", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Complete o texto com as palavras do banco.", "explain": "aunt's wedding (casamento da tia); her husband; their daughter; filha da tia = cousin.", "prompt": "Look at this photo from my ___ wedding. The woman in the white dress is my aunt Rita. The tall man next to her is her ___, my uncle Paulo. The girl with them is ___ daughter, Bia. So Bia is my ___!", "answers": [["aunt's"], ["husband"], ["their"], ["cousin"]], "bank": ["cousin's", "husband", "their", "cousin", "aunt's", "brother"], "id": "bkA2-284"}, {"type": "choose", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Escolha a forma correta.", "explain": "Children é plural irregular: children's.", "prompt": "The [children's*/childrens'] toys are all over the floor.", "id": "bkA2-285"}, {"type": "choose", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Whose = de quem. Posse: my brother's keys.", "prompt": "[Whose*/Who's] keys are these? I think they're [my brother's*/my brother] keys.", "id": "bkA2-286"}, {"type": "error", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Encontre o erro e corrija.", "explain": "Não usamos artigo antes de nome com 's: Ana's dress.", "sentence": "The Ana's dress is beautiful.", "wrong": "The Ana's", "fix": ["Ana's"], "id": "bkA2-287"}, {"type": "error", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Encontre o erro e corrija.", "explain": "Para mostrar posse de pessoa, falta o 's: my friend's house.", "sentence": "We stayed at my friend house in Belém.", "wrong": "friend house", "fix": ["friend's house"], "id": "bkA2-288"}, {"type": "rewrite", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Reescreva usando o genitivo ('s).", "explain": "Carolina é a dona: Carolina's dog.", "prompt": "The dog belongs to Carolina.", "start": "It", "accept": ["It's Carolina's dog.", "It is Carolina's dog."], "id": "bkA2-289"}, {"type": "rewrite", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Faça uma pergunta com Whose.", "explain": "Whose + objeto + is this?", "prompt": "This is Rui's phone.", "start": "Whose", "accept": ["Whose phone is this?", "Whose is this phone?"], "id": "bkA2-290"}, {"type": "order", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Ordene as palavras para formar a frase.", "explain": "O 's liga o dono (my best friend) à pessoa (mother).", "words": ["My", "best", "friend's", "mother", "is", "a", "nurse"], "id": "bkA2-291"}, {"type": "order", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Ordene as palavras para formar a frase.", "explain": "at + nome's + house = na casa de alguém.", "words": ["We", "had", "dinner", "at", "Rafael's", "house", "last", "night"], "alt": ["Last night we had dinner at Rafael's house", "We had dinner last night at Rafael's house"], "id": "bkA2-292"}, {"type": "dorder", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Achados e perdidos: teachers' room = sala dos professores.", "lines": ["A: Excuse me, I lost my backpack yesterday.", "B: What color is it?", "A: It's green, with a small Brazilian flag.", "B: Is this yours? It was in the teachers' room.", "A: Yes, that's mine! Thank you!"], "id": "bkA2-293"}, {"type": "tf", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Observe quem é o dono de cada coisa: grandparents' farm, uncle's band.", "text": "Today is Lucas's birthday. The party is at his grandparents' farm. Lucas's mom made the cake, and his uncle's band is going to play. Lucas's best friend, Téo, can't come because he's sick.", "items": [{"s": "The party is at Lucas's house.", "a": false}, {"s": "Lucas's mother made the cake.", "a": true}, {"s": "Lucas's uncle has a band.", "a": true}, {"s": "Téo is at the party.", "a": false}], "id": "bkA2-294"}, {"type": "reading", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Leia o anúncio e responda.", "explain": "Maria's son = o filho de Maria; Dr. Kato's dental clinic = a clínica do Dr. Kato; the shop's phone number = o telefone da loja.", "text": "Maria's Pet Shop is on Rua Sete, next to Dr. Kato's dental clinic. It's open from Monday to Saturday. Maria's son, Felipe, gives the dogs their baths. On Saturdays, children can bring old pet toys and change them for new ones. The shop's phone number is 3222-1010.", "questions": [{"q": "Who washes the dogs?", "options": ["Maria", "Maria's son", "Dr. Kato"], "correctIndex": 1}, {"q": "What is next to the pet shop?", "options": ["A dental clinic", "A school", "A bakery"], "correctIndex": 0}, {"q": "What can children bring on Saturdays?", "options": ["Their friends", "Old pet toys", "Their dogs"], "correctIndex": 1}], "id": "bkA2-295"}, {"type": "sort", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Separe: um dono ou mais de um dono?", "explain": "Singular: 's (boy's). Plural com s: só apóstrofo (boys'). Plural irregular: 's (children's).", "prompt": "One owner or more than one owner?", "groups": ["One owner", "More than one owner"], "items": [{"w": "the boy's bike", "g": 0}, {"w": "the teacher's desk", "g": 0}, {"w": "my friend's car", "g": 0}, {"w": "the woman's bag", "g": 0}, {"w": "the boys' bikes", "g": 1}, {"w": "the teachers' room", "g": 1}, {"w": "the children's toys", "g": 1}, {"w": "my parents' house", "g": 1}], "id": "bkA2-296"}, {"type": "match", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Ana e Leo são casados e Rosa é filha deles. Ligue as partes.", "explain": "wife = esposa; husband = marido; daughter = filha; mother = mãe.", "left": ["Ana is Leo's", "Leo is Ana's", "Rosa is Ana and Leo's", "Ana is Rosa's"], "right": ["daughter.", "mother.", "wife.", "husband."], "correctMap": [2, 3, 0, 1], "id": "bkA2-297"}, {"type": "odd", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Em qual opção o 's NÃO indica posse?", "explain": "Em She's tired, 's = is (She is tired).", "prompt": "Which one does NOT show possession?", "options": ["Carla's bag", "my dad's car", "She's tired.", "the dog's bed"], "correctIndex": 2, "id": "bkA2-298"}, {"type": "blank", "level": "A2", "topic": "Caso genitivo ('s)", "instruction": "Complete com o lugar certo.", "explain": "at the dentist's = no consultório do dentista (também se diz at the dentist).", "prompt": "A: Where's Bruno?\nB: He's at the ___. He has a toothache.", "accept": ["dentist's", "dentist"], "id": "bkA2-299"}, {"type": "mcq", "level": "A2", "topic": "Direções", "instruction": "Escolha a opção correta.", "explain": "Na esquina = on the corner.", "prompt": "A: Excuse me, where's the nearest ATM?\nB: It's ___ the corner, next to the bakery.", "options": ["on", "between", "through", "under"], "correctIndex": 0, "id": "bkA2-300"}, {"type": "mcq", "level": "A2", "topic": "Direções", "instruction": "Escolha a opção correta.", "explain": "Atravessar a ponte = go across the bridge.", "prompt": "Go ___ the bridge and turn right.", "options": ["across", "between", "next", "opposite"], "correctIndex": 0, "id": "bkA2-301"}, {"type": "mcq", "level": "A2", "topic": "Direções", "instruction": "Escolha a opção correta.", "explain": "Do outro lado da rua, de frente = opposite.", "prompt": "The pharmacy is ___ the bank. You just need to cross the street.", "options": ["opposite", "next to", "behind", "between"], "correctIndex": 0, "id": "bkA2-302"}, {"type": "gaps", "level": "A2", "topic": "Direções", "instruction": "Complete o diálogo.", "explain": "Where = onde; far = longe; walk down/along = seguir pela rua; turn left at = vire à esquerda em.", "prompt": "A: Excuse me. ___ is the train station?\nB: It's not ___ from here. Walk ___ this street and turn left ___ the church.", "answers": [["Where"], ["far"], ["down", "up", "along"], ["at", "after", "before", "by"]], "id": "bkA2-303"}, {"type": "gaps", "level": "A2", "topic": "Direções", "instruction": "Complete as instruções com as palavras do banco.", "explain": "Walk along = siga por; take = pegue (a rua); go past = passe por; on the square = na praça.", "prompt": "To get to Pelourinho from the hotel, ___ Avenida Sete for about five minutes. ___ the second street on the right. Go ___ a big church, and you'll see a square. The restaurant is ___ the square, between a souvenir shop and a bank.", "answers": [["walk along", "go along", "walk down", "go down"], ["Take"], ["past"], ["on", "in"]], "bank": ["Take", "past", "on", "walk along", "through", "Turn"], "id": "bkA2-304"}, {"type": "choose", "level": "A2", "topic": "Direções", "instruction": "Escolha a palavra correta em cada grupo.", "explain": "Siga em frente = go straight ahead; pegue a primeira à esquerda = take the first left.", "prompt": "Go [straight*/right] ahead and [take*/make] the first left.", "id": "bkA2-305"}, {"type": "choose", "level": "A2", "topic": "Direções", "instruction": "Escolha a forma correta em cada grupo.", "explain": "In front of precisa do of; no fim da rua = at the end of the street.", "prompt": "The café is [in front of*/in front] the museum, [at*/in] the end of the street.", "id": "bkA2-306"}, {"type": "error", "level": "A2", "topic": "Direções", "instruction": "Encontre o erro e corrija.", "explain": "Em inglês: turn left (sem at). \"Vire à esquerda\" não se traduz palavra por palavra.", "sentence": "Turn at left at the supermarket.", "wrong": "at left", "fix": ["left"], "id": "bkA2-307"}, {"type": "error", "level": "A2", "topic": "Direções", "instruction": "Encontre o erro e corrija.", "explain": "Between ... and ... (entre isto e aquilo).", "sentence": "The post office is between the bank or the gym.", "wrong": "or", "fix": ["and"], "id": "bkA2-308"}, {"type": "rewrite", "level": "A2", "topic": "Direções", "instruction": "Reescreva como instrução no imperativo.", "explain": "Para dar direções usamos o imperativo: Turn right...", "prompt": "You must turn right at the traffic lights.", "accept": ["Turn right at the traffic lights.", "Turn right at the lights."], "id": "bkA2-309"}, {"type": "rewrite", "level": "A2", "topic": "Direções", "instruction": "Reescreva com o mesmo sentido, começando como indicado.", "explain": "Se a padaria está à esquerda do banco, o banco está à direita da padaria.", "prompt": "The bakery is to the left of the bank.", "start": "The bank", "accept": ["The bank is to the right of the bakery.", "The bank is on the right of the bakery."], "id": "bkA2-310"}, {"type": "order", "level": "A2", "topic": "Direções", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta útil: How do I get to...?", "words": ["How", "do", "I", "get", "to", "the", "airport", "from", "here"], "alt": ["How do I get from here to the airport"], "id": "bkA2-311"}, {"type": "order", "level": "A2", "topic": "Direções", "instruction": "Ordene as palavras para formar a frase.", "explain": "Across from = em frente, do outro lado da rua.", "words": ["The", "bus", "stop", "is", "across", "from", "the", "hospital"], "id": "bkA2-312"}, {"type": "dorder", "level": "A2", "topic": "Direções", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Pedir informação: distância, caminho, agradecimento.", "lines": ["A: Excuse me, is the shopping mall far from here?", "B: No, it's about five minutes on foot.", "A: Great. Which way do I go?", "B: Go down this street and turn right at the gas station.", "A: Thanks a lot!", "B: You're welcome."], "id": "bkA2-313"}, {"type": "tf", "level": "A2", "topic": "Direções", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Observe as preposições: on your right, next to, at the end of, opposite.", "text": "Welcome to Colégio Estrela! When you enter, the office is on your right. The library is on the second floor, next to the computer room. The cafeteria is at the end of the hall, opposite the gym. The bathrooms are near the stairs.", "items": [{"s": "The office is on your left when you enter.", "a": false}, {"s": "The library is next to the computer room.", "a": true}, {"s": "The gym is opposite the cafeteria.", "a": true}, {"s": "The cafeteria is next to the entrance.", "a": false}], "id": "bkA2-314"}, {"type": "reading", "level": "A2", "topic": "Direções", "instruction": "Leia a mensagem e responda.", "explain": "Get off = descer; turn left onto = vire à esquerda na; across from = em frente a.", "text": "Hi Nando! The party is at my new apartment. Get off the subway at Consolação station. Walk up Rua Augusta for two blocks and turn left onto Rua Luís Coelho. My building is the third on the right, across from a small park. It's gray with a red door. I'm on the 7th floor, apartment 72. See you at eight! Bia", "questions": [{"q": "Where should Nando get off the subway?", "options": ["At Consolação", "At Rua Augusta", "At Rua Luís Coelho"], "correctIndex": 0}, {"q": "What is across from the building?", "options": ["A subway station", "A park", "A gray building"], "correctIndex": 1}, {"q": "What color is the door?", "options": ["Gray", "Red", "Green"], "correctIndex": 1}], "id": "bkA2-315"}, {"type": "sort", "level": "A2", "topic": "Direções", "instruction": "Separe: a frase diz onde fica ou como chegar?", "explain": "Frases com preposição de lugar dizem onde fica; imperativos (turn, go, cross, take) dizem como chegar.", "prompt": "Is it about place or movement?", "groups": ["Place (Where is it?)", "Movement (How do I get there?)"], "items": [{"w": "It's next to the bank.", "g": 0}, {"w": "It's opposite the park.", "g": 0}, {"w": "It's on the corner.", "g": 0}, {"w": "It's between two stores.", "g": 0}, {"w": "Turn left at the lights.", "g": 1}, {"w": "Go past the church.", "g": 1}, {"w": "Cross the bridge.", "g": 1}, {"w": "Take the first right.", "g": 1}], "id": "bkA2-316"}, {"type": "match", "level": "A2", "topic": "Direções", "instruction": "Ligue cada pergunta à resposta certa.", "explain": "Far → perto/longe; walk → sim, a pé; where → localização; how long → tempo.", "left": ["Is it far?", "Can I walk there?", "Where exactly is it?", "How long does it take?"], "right": ["It's between the bank and the bakery.", "About ten minutes.", "No, it's very close.", "Yes, it's only two blocks away."], "correctMap": [2, 3, 0, 1], "id": "bkA2-317"}, {"type": "odd", "level": "A2", "topic": "Direções", "instruction": "Qual palavra NÃO tem relação com ruas e direções?", "explain": "Traffic lights, corner e block são da rua; pillow (travesseiro) não.", "prompt": "Which word is NOT about streets and directions?", "options": ["traffic lights", "corner", "block", "pillow"], "correctIndex": 3, "id": "bkA2-318"}, {"type": "blank", "level": "A2", "topic": "Direções", "instruction": "Complete com a preposição correta.", "explain": "Atravessar por dentro de um túnel = go through.", "prompt": "Go ___ the tunnel and you'll see the stadium on your left.", "accept": ["through"], "id": "bkA2-319"}, {"type": "mcq", "level": "A2", "topic": "Conectores básicos", "instruction": "Escolha a opção correta.", "explain": "Ideias opostas (queria ir x ingressos esgotados): but.", "prompt": "I wanted to go to the concert, ___ the tickets were sold out.", "options": ["but", "so", "because", "or"], "correctIndex": 0, "id": "bkA2-320"}, {"type": "mcq", "level": "A2", "topic": "Conectores básicos", "instruction": "Escolha a opção correta.", "explain": "Motivo: because (porque).", "prompt": "Mariana is learning Japanese ___ she wants to work in Tokyo.", "options": ["because", "so", "but", "or"], "correctIndex": 0, "id": "bkA2-321"}, {"type": "mcq", "level": "A2", "topic": "Conectores básicos", "instruction": "Escolha a opção correta.", "explain": "Or aqui significa \"senão\": corra, senão vamos perder o ônibus.", "prompt": "Hurry up, ___ we'll miss the bus!", "options": ["or", "and", "because", "but"], "correctIndex": 0, "id": "bkA2-322"}, {"type": "gaps", "level": "A2", "topic": "Conectores básicos", "instruction": "Complete o diálogo com or ou because.", "explain": "Or = opção entre duas coisas; because = motivo.", "prompt": "A: Do you want to go out ___ stay home tonight?\nB: Let's stay home. I don't want to go out ___ it's raining.", "answers": [["or"], ["because"]], "id": "bkA2-323"}, {"type": "gaps", "level": "A2", "topic": "Conectores básicos", "instruction": "Complete o texto com as palavras do banco.", "explain": "Sequência: First, After that, Then; contraste: but; consequência: so.", "prompt": "Yesterday was a busy day. ___, I went to the bank. ___ that, I had lunch with my friend Rui. ___ I went to the gym, ___ I was very tired, ___ I went home early.", "answers": [["First"], ["After"], ["Then", "Later"], ["but"], ["so"]], "bank": ["First", "After", "Then", "but", "so"], "id": "bkA2-324"}, {"type": "choose", "level": "A2", "topic": "Conectores básicos", "instruction": "Escolha o conector correto em cada grupo.", "explain": "So = consequência (fizeram um bolo); and = adição.", "prompt": "It was my birthday, [so*/but] my friends made a cake, [and*/or] we sang together.", "id": "bkA2-325"}, {"type": "choose", "level": "A2", "topic": "Conectores básicos", "instruction": "Escolha o conector correto em cada grupo.", "explain": "And soma gostos; but mostra contraste (não gosta de funk).", "prompt": "Rafa likes rock [and*/but] pop, [but*/so] he doesn't like funk.", "id": "bkA2-326"}, {"type": "error", "level": "A2", "topic": "Conectores básicos", "instruction": "Encontre o erro e corrija.", "explain": "Dormir cedo é consequência do cansaço: so, não because.", "sentence": "She was tired, because she went to bed early.", "wrong": "because", "fix": ["so"], "id": "bkA2-327"}, {"type": "error", "level": "A2", "topic": "Conectores básicos", "instruction": "Encontre o erro e corrija.", "explain": "Para escolher entre opções usamos or.", "sentence": "We can take the bus and walk. Which do you prefer?", "wrong": "and", "fix": ["or"], "id": "bkA2-328"}, {"type": "rewrite", "level": "A2", "topic": "Conectores básicos", "instruction": "Una as duas frases com but.", "explain": "But liga duas ideias em contraste.", "prompt": "The hotel was beautiful. It was very expensive.", "accept": ["The hotel was beautiful, but it was very expensive.", "The hotel was beautiful but very expensive."], "id": "bkA2-329"}, {"type": "rewrite", "level": "A2", "topic": "Conectores básicos", "instruction": "Reescreva usando because, começando como indicado.", "explain": "So mostra consequência; because mostra a causa (perdeu o ônibus).", "prompt": "Paula missed the bus, so she was late.", "start": "Paula was late", "accept": ["Paula was late because she missed the bus."], "id": "bkA2-330"}, {"type": "order", "level": "A2", "topic": "Conectores básicos", "instruction": "Ordene as palavras para formar a frase.", "explain": "But liga duas ideias contrárias.", "words": ["I", "called", "Pedro", "but", "he", "didn't", "answer"], "id": "bkA2-331"}, {"type": "order", "level": "A2", "topic": "Conectores básicos", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Or apresenta duas opções.", "words": ["Do", "you", "prefer", "the", "beach", "or", "the", "mountains"], "alt": ["Do you prefer the mountains or the beach"], "id": "bkA2-332"}, {"type": "dorder", "level": "A2", "topic": "Conectores básicos", "instruction": "Coloque o diálogo na ordem certa.", "explain": "Why pede resposta com because; but mostra contraste.", "lines": ["A: Why are you so happy today?", "B: Because I passed my driving test!", "A: Congratulations! Was it difficult?", "B: Yes, it was, but I practiced a lot."], "id": "bkA2-333"}, {"type": "tf", "level": "A2", "topic": "Conectores básicos", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Os conectores mostram causa (because), consequência (so) e contraste (but).", "text": "Júlio and Camila opened a small restaurant in Belém last year. At first, they had only a few customers, so Júlio started a page on Instagram. Now the restaurant is always full, but they are very tired because they work every day. Next year, they want to hire two more cooks.", "items": [{"s": "The restaurant had many customers at first.", "a": false}, {"s": "Júlio used Instagram to get more customers.", "a": true}, {"s": "They work only on weekends.", "a": false}, {"s": "They want to hire more cooks.", "a": true}], "id": "bkA2-334"}, {"type": "reading", "level": "A2", "topic": "Conectores básicos", "instruction": "Leia a história e responda.", "explain": "First, then, but, so e finally organizam a história.", "text": "Last Sunday, Tiago wanted to go fishing with his dad. First, they packed some sandwiches and drinks. Then they drove to a lake near Goiânia. They waited for three hours, but they didn't catch any fish. So they ate their sandwiches and went swimming. Finally, they bought a fish at the market on the way home!", "questions": [{"q": "What did they do first?", "options": ["They drove to the lake.", "They packed food.", "They went swimming."], "correctIndex": 1}, {"q": "Did they catch any fish at the lake?", "options": ["Yes, a lot.", "Yes, one.", "No, none."], "correctIndex": 2}, {"q": "Where did their fish come from?", "options": ["The lake", "The market", "A restaurant"], "correctIndex": 1}], "id": "bkA2-335"}, {"type": "sort", "level": "A2", "topic": "Conectores básicos", "instruction": "Separe: conector para unir ideias ou para mostrar sequência?", "explain": "And, but, or, so unem ideias; first, then, after that, finally mostram ordem.", "prompt": "Joining ideas or showing sequence?", "groups": ["Joining ideas", "Showing sequence"], "items": [{"w": "and", "g": 0}, {"w": "but", "g": 0}, {"w": "or", "g": 0}, {"w": "so", "g": 0}, {"w": "first", "g": 1}, {"w": "then", "g": 1}, {"w": "after that", "g": 1}, {"w": "finally", "g": 1}], "id": "bkA2-336"}, {"type": "match", "level": "A2", "topic": "Conectores básicos", "instruction": "Ligue as duas partes de cada frase.", "explain": "so = consequência; or = opção; but = contraste; because = motivo.", "left": ["It was hot,", "Do you want juice", "I like juice,", "I drank some water"], "right": ["or water?", "because I was thirsty.", "but I don't like soda.", "so we went to the beach."], "correctMap": [3, 0, 2, 1], "id": "bkA2-337"}, {"type": "odd", "level": "A2", "topic": "Conectores básicos", "instruction": "Qual palavra NÃO indica ordem/sequência?", "explain": "First, then e finally mostram sequência; because indica motivo.", "prompt": "Which word does NOT show order?", "options": ["first", "then", "finally", "because"], "correctIndex": 3, "id": "bkA2-338"}, {"type": "blank", "level": "A2", "topic": "Conectores básicos", "instruction": "Complete com um conector.", "explain": "Consequência: não tinha guarda-chuva, então se molhou (so).", "prompt": "I didn't have an umbrella, ___ I got wet.", "accept": ["so", "and"], "id": "bkA2-339"}, {"type": "mcq", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Escolha a opção correta.", "explain": "Money é incontável: some money (não a nem many).", "prompt": "I need ___ money to buy the tickets.", "options": ["some", "a", "many", "a few"], "correctIndex": 0, "id": "bkA2-340"}, {"type": "mcq", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Escolha a opção correta.", "explain": "Bottles é contável: How many.", "prompt": "How ___ bottles of water do we need for the trip?", "options": ["many", "much", "any", "a little"], "correctIndex": 0, "id": "bkA2-341"}, {"type": "mcq", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Escolha a opção correta.", "explain": "News é incontável e fica no singular: The news is.", "prompt": "The news ___ very good today!", "options": ["is", "are", "were", "have"], "correctIndex": 0, "id": "bkA2-342"}, {"type": "gaps", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Complete o diálogo.", "explain": "a glass / a sandwich (contáveis no singular); ice é incontável: some ou any.", "prompt": "A: Can I have ___ glass of water and ___ sandwich, please?\nB: Sure. Do you want ___ ice in your water?", "answers": [["a", "one"], ["a", "one"], ["some", "any"]], "id": "bkA2-343"}, {"type": "gaps", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Complete o texto com as palavras do banco.", "explain": "an antes de som de vogal (oven); a + contável; some + incontável (furniture, fruit, bread).", "prompt": "In my kitchen there is ___ oven, ___ big table and ___ old furniture from my grandma. I always have ___ fruit in a bowl and ___ bread for breakfast.", "answers": [["an"], ["a"], ["some"], ["some"], ["some"]], "bank": ["an", "a", "some", "any"], "id": "bkA2-344"}, {"type": "choose", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Help é incontável (some help); exercise aqui é contável (a difficult exercise).", "prompt": "Can you give me [some*/a] help with my homework? It's [a*/some] difficult exercise.", "id": "bkA2-345"}, {"type": "choose", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Escolha a forma correta em cada grupo.", "explain": "Rice é incontável: there is + a lot of (many é só para contáveis).", "prompt": "There [is*/are] [a lot of*/many] rice in the bag.", "id": "bkA2-346"}, {"type": "error", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Encontre o erro e corrija.", "explain": "Furniture é incontável: não tem plural.", "sentence": "I need to buy new furnitures for my apartment.", "wrong": "furnitures", "fix": ["furniture"], "id": "bkA2-347"}, {"type": "error", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Encontre o erro e corrija.", "explain": "Information é incontável: some information (sem an).", "sentence": "Can you give me an information about the tour?", "wrong": "an information", "fix": ["some information", "information", "any information"], "id": "bkA2-348"}, {"type": "rewrite", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Faça a pergunta sobre a quantidade.", "explain": "Cousins é contável: How many.", "prompt": "Rita has five cousins.", "start": "How many", "accept": ["How many cousins does Rita have?"], "id": "bkA2-349"}, {"type": "rewrite", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Corrija a frase usando 'pieces of'.", "explain": "Advice é incontável; para contar usamos pieces of advice.", "prompt": "She gave me two advices.", "start": "She gave me two", "accept": ["She gave me two pieces of advice."], "id": "bkA2-350"}, {"type": "order", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Tea é incontável; para contar usamos a cup of.", "words": ["Would", "you", "like", "a", "cup", "of", "tea"], "id": "bkA2-351"}, {"type": "order", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Ordene as palavras para formar a frase.", "explain": "Furniture é incontável: don't have much furniture.", "words": ["We", "don't", "have", "much", "furniture", "in", "our", "new", "house"], "id": "bkA2-352"}, {"type": "dorder", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Coloque o diálogo na ordem certa.", "explain": "How much + incontável (cheese); How many + contável (tomatoes).", "lines": ["A: What do we need for the lasagna?", "B: Some cheese, some tomatoes and an onion.", "A: How much cheese?", "B: About half a kilo.", "A: OK. And how many tomatoes?", "B: Five or six big ones."], "id": "bkA2-353"}, {"type": "tf", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Furniture e money são incontáveis; boxes é contável.", "text": "Hi, I'm Débora. I'm moving to a new apartment next week. I have a lot of furniture, so I need a big truck. I don't have much money, but my friends are going to help me for free. I also have three boxes of books and a lot of kitchen equipment.", "items": [{"s": "Débora has only a little furniture.", "a": false}, {"s": "She has a lot of money.", "a": false}, {"s": "Her friends are going to help her.", "a": true}, {"s": "She has some boxes of books.", "a": true}], "id": "bkA2-354"}, {"type": "reading", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Leia o aviso e responda.", "explain": "Luggage é incontável: one piece of luggage. Fruit e cheese também.", "text": "Traveling with Air Sol? Please read. You can take one piece of hand luggage. Liquids must be in small bottles (maximum 100 ml). You can't bring fresh food from other countries into Brazil, like fruit or cheese. Please arrive two hours early. Have a good flight!", "questions": [{"q": "How many pieces of hand luggage can you take?", "options": ["One", "Two", "Three"], "correctIndex": 0}, {"q": "What can't you bring into Brazil?", "options": ["Books", "Fresh fruit", "Clothes"], "correctIndex": 1}, {"q": "When should you arrive?", "options": ["Two hours early", "At the time of the flight", "One day before"], "correctIndex": 0}], "id": "bkA2-355"}, {"type": "sort", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Separe as palavras: a/an ou some?", "explain": "Contáveis no singular usam a/an; incontáveis usam some.", "prompt": "Which goes before each word: a/an or some?", "groups": ["a / an", "some"], "items": [{"w": "onion", "g": 0}, {"w": "umbrella", "g": 0}, {"w": "cookie", "g": 0}, {"w": "potato", "g": 0}, {"w": "cheese", "g": 1}, {"w": "butter", "g": 1}, {"w": "salt", "g": 1}, {"w": "honey", "g": 1}], "id": "bkA2-356"}, {"type": "match", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Ligue cada expressão ao item certo.", "explain": "a slice of pizza, a bowl of cereal, a can of soda, a piece of advice.", "left": ["a slice of", "a bowl of", "a can of", "a piece of"], "right": ["soda", "advice", "cereal", "pizza"], "correctMap": [3, 2, 0, 1], "id": "bkA2-357"}, {"type": "odd", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Qual palavra é contável?", "explain": "Advice, news e homework são incontáveis; suggestion é contável (a suggestion).", "prompt": "Which word is countable?", "options": ["advice", "news", "homework", "suggestion"], "correctIndex": 3, "id": "bkA2-358"}, {"type": "blank", "level": "A2", "topic": "Contáveis x Incontáveis", "instruction": "Complete com o verbo be no passado.", "explain": "Traffic é incontável: there was (singular).", "prompt": "There ___ (be) a lot of traffic on the way to work this morning.", "accept": ["was"], "id": "bkA2-359"}, {"level": "B1", "topic": "Present Perfect x Simple Past", "type": "mcq", "instruction": "Escolha a forma correta do verbo.", "prompt": "We ___ to Salvador three times so far.", "options": ["went", "have been", "are going", "go"], "correctIndex": 1, "explain": "\"So far\" indica período até agora, então usamos o Present Perfect.", "id": "bkB1-0"}, {"level": "B1", "topic": "Present Perfect x Simple Past", "type": "mcq", "instruction": "Escolha a forma correta do verbo.", "prompt": "My parents ___ married in 1998.", "options": ["got", "have got", "have gotten", "get"], "correctIndex": 0, "explain": "Com data específica no passado (in 1998) usamos o Simple Past.", "id": "bkB1-1"}, {"level": "B1", "topic": "Present Perfect x Simple Past", "type": "gaps", "instruction": "Complete o diálogo com os verbos na forma correta.", "prompt": "A: Have you ever ___ (try) açaí?\nB: Yes, I ___ (try) it last summer in Belém. It ___ (be) delicious.", "answers": [["tried"], ["tried"], ["was"]], "explain": "\"Have ever\" pede particípio; \"last summer\" pede Simple Past.", "id": "bkB1-2"}, {"level": "B1", "topic": "Present Perfect x Simple Past", "type": "choose", "instruction": "Escolha a forma correta em cada grupo.", "prompt": "Carla [has lived*/lived] in Recife since 2019. Before that, she [has lived/lived*] in Natal for two years.", "explain": "\"Since 2019\" continua até hoje (Present Perfect); \"before that\" é passado terminado.", "id": "bkB1-3"}, {"level": "B1", "topic": "Present Perfect x Simple Past", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "I have seen that movie last weekend.", "wrong": "have seen", "fix": ["saw"], "explain": "\"Last weekend\" é tempo passado definido, então usamos o Simple Past.", "id": "bkB1-4"}, {"level": "B1", "topic": "Present Perfect x Simple Past", "type": "rewrite", "instruction": "Reescreva usando o Present Perfect e \"since\".", "prompt": "Paulo moved to Curitiba in 2020 and he still lives there.", "start": "Paulo has", "accept": ["Paulo has lived in Curitiba since 2020", "Paulo has been living in Curitiba since 2020", "Paulo has been in Curitiba since 2020", "Paulo has lived there since 2020"], "explain": "Ação que começou no passado e continua: Present Perfect + since.", "id": "bkB1-5"}, {"level": "B1", "topic": "Present Perfect x Simple Past", "type": "order", "instruction": "Ordene as palavras para formar uma pergunta.", "words": ["Have", "you", "ever", "been", "to", "the", "Amazon"], "explain": "Pergunta sobre experiência de vida: Have + sujeito + ever + particípio.", "id": "bkB1-6"}, {"level": "B1", "topic": "Present Perfect x Simple Past", "type": "match", "instruction": "Ligue as duas partes de cada frase.", "left": ["I've known Pedro", "We met", "They have already", "Did you see"], "right": ["the game last night?", "finished the project.", "at a party in 2012.", "since we were kids."], "correctMap": [3, 2, 1, 0], "explain": "Since/already combinam com Present Perfect; 2012 e last night com Simple Past.", "id": "bkB1-7"}, {"level": "B1", "topic": "Present Perfect x Simple Past", "type": "sort", "instruction": "Classifique as expressões de tempo pelo tempo verbal mais usado.", "groups": ["Present Perfect", "Simple Past"], "items": [{"w": "since 2010", "g": 0}, {"w": "yesterday", "g": 1}, {"w": "ever", "g": 0}, {"w": "last year", "g": 1}, {"w": "so far", "g": 0}, {"w": "two days ago", "g": 1}, {"w": "up to now", "g": 0}, {"w": "in 2005", "g": 1}], "explain": "Present Perfect liga passado ao presente; Simple Past usa momentos terminados.", "prompt": "Put each item in the right group: Present Perfect or Simple Past.", "id": "bkB1-8"}, {"level": "B1", "topic": "Present Perfect x Simple Past", "type": "tf", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Lucas is a photographer from Florianópolis. He has traveled to twelve countries so far. His first trip abroad was to Argentina in 2014. He has never been to Asia, but he wants to visit Japan next year. Last month, he went to Chile for a wedding.", "items": [{"s": "Lucas has visited Asia.", "a": false}, {"s": "He went to Argentina in 2014.", "a": true}, {"s": "He has been to more than ten countries.", "a": true}, {"s": "He went to Chile for work.", "a": false}], "explain": "O texto diz que ele nunca foi à Ásia e foi ao Chile para um casamento.", "id": "bkB1-9"}, {"level": "B1", "topic": "Condicionais (0, 1, 2)", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "If I ___ more free time, I would learn to play the guitar.", "options": ["have", "had", "will have", "would have"], "correctIndex": 1, "explain": "Condicional tipo 2: If + Simple Past, would + verbo.", "id": "bkB1-10"}, {"level": "B1", "topic": "Condicionais (0, 1, 2)", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "If it rains tomorrow, we ___ the barbecue.", "options": ["will cancel", "would cancel", "canceled", "had canceled"], "correctIndex": 0, "explain": "Condicional tipo 1 (possibilidade real no futuro): If + presente, will + verbo.", "id": "bkB1-11"}, {"level": "B1", "topic": "Condicionais (0, 1, 2)", "type": "gaps", "instruction": "Complete com os verbos na forma correta.", "prompt": "If I ___ (be) you, I ___ (talk) to the manager about the problem.", "answers": [["were", "was"], ["would talk"]], "explain": "Conselho com tipo 2: If I were you, I would + verbo.", "id": "bkB1-12"}, {"level": "B1", "topic": "Condicionais (0, 1, 2)", "type": "choose", "instruction": "Escolha a forma correta em cada grupo.", "prompt": "If she [will study/studies*] hard, she [will pass*/would pass] the exam next week.", "explain": "Tipo 1: presente depois de \"if\" e \"will\" na outra oração.", "id": "bkB1-13"}, {"level": "B1", "topic": "Condicionais (0, 1, 2)", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "If I would have a car, I would drive to work.", "wrong": "would have", "fix": ["had"], "explain": "No tipo 2, a oração com \"if\" usa Simple Past, não \"would\".", "id": "bkB1-14"}, {"level": "B1", "topic": "Condicionais (0, 1, 2)", "type": "rewrite", "instruction": "Reescreva como condicional tipo 2 (situação imaginária).", "prompt": "I don't have money, so I can't buy a new phone.", "start": "If I", "accept": ["If I had money, I could buy a new phone", "If I had money, I would buy a new phone", "If I had some money, I could buy a new phone", "If I had some money, I would buy a new phone", "If I had more money, I could buy a new phone", "If I had more money, I would buy a new phone", "If I had enough money, I could buy a new phone", "If I had enough money, I would buy a new phone", "If I had money, I'd buy a new phone", "If I had some money, I'd buy a new phone", "If I had more money, I'd buy a new phone", "If I had enough money, I'd buy a new phone", "If I had the money, I could buy a new phone", "If I had the money, I would buy a new phone", "If I had the money, I'd buy a new phone"], "explain": "Situação irreal no presente: If + Simple Past, would/could + verbo.", "id": "bkB1-15"}, {"level": "B1", "topic": "Condicionais (0, 1, 2)", "type": "order", "instruction": "Ordene as palavras para formar uma pergunta.", "words": ["What", "would", "you", "do", "if", "you", "won", "the", "lottery"], "alt": ["If you won the lottery what would you do"], "explain": "Tipo 2 para situação imaginária: would + verbo e if + Simple Past.", "id": "bkB1-16"}, {"level": "B1", "topic": "Condicionais (0, 1, 2)", "type": "match", "instruction": "Ligue as duas partes de cada frase.", "left": ["If you press this button,", "If I see Marta tomorrow,", "If we lived near the beach,", "If you don't sleep enough,"], "right": ["we would go surfing every day.", "you feel tired.", "the machine starts.", "I'll give her your message."], "correctMap": [2, 3, 0, 1], "explain": "Tipo 0 para fatos gerais, tipo 1 para futuro real, tipo 2 para imaginário.", "id": "bkB1-17"}, {"level": "B1", "topic": "Condicionais (0, 1, 2)", "type": "sort", "instruction": "Classifique cada frase pelo tipo de condicional.", "groups": ["Zero Conditional", "First Conditional", "Second Conditional"], "items": [{"w": "If you boil water, it evaporates.", "g": 0}, {"w": "If plants don't get light, they die.", "g": 0}, {"w": "If it's sunny tomorrow, we'll go to the beach.", "g": 1}, {"w": "If you call me, I'll pick you up.", "g": 1}, {"w": "If I were rich, I'd buy a farm.", "g": 2}, {"w": "If he spoke Spanish, he could work in Chile.", "g": 2}], "explain": "Tipo 0: presente + presente; tipo 1: presente + will; tipo 2: passado + would/could.", "prompt": "Put each item in the right group: Zero Conditional or First Conditional or Second Conditional.", "id": "bkB1-18"}, {"level": "B1", "topic": "Condicionais (0, 1, 2)", "type": "reading", "instruction": "Leia o e-mail e responda às perguntas.", "text": "Hi Bruno,\nThanks for inviting me to your party on Saturday! If I finish work early, I'll definitely come. If I finish late, I'll stop by for dessert at least. By the way, if I had a car, I would give Júlia a ride, but mine is at the mechanic. If you need anything for the party, just send me a message.\nSee you soon,\nTati", "questions": [{"q": "What will Tati do if she finishes work late?", "options": ["She won't go to the party.", "She will go for dessert.", "She will give Júlia a ride."], "correctIndex": 1}, {"q": "Why can't Tati give Júlia a ride?", "options": ["Her car is at the mechanic.", "She doesn't like driving.", "Júlia lives too far away."], "correctIndex": 0}, {"q": "What should Bruno do if he needs something?", "options": ["Call Júlia.", "Send Tati a message.", "Go to the mechanic."], "correctIndex": 1}], "explain": "As respostas estão nas frases com \"if\" do e-mail.", "id": "bkB1-19"}, {"level": "B1", "topic": "Gerúndio x Infinitivo", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "I really enjoy ___ in the rain.", "options": ["walk", "to walk", "walking", "walked"], "correctIndex": 2, "explain": "\"Enjoy\" é seguido de verbo com -ing.", "id": "bkB1-20"}, {"level": "B1", "topic": "Gerúndio x Infinitivo", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "They decided ___ a house in Campinas.", "options": ["buying", "to buy", "buy", "bought"], "correctIndex": 1, "explain": "\"Decide\" é seguido de to + verbo.", "id": "bkB1-21"}, {"level": "B1", "topic": "Gerúndio x Infinitivo", "type": "gaps", "instruction": "Complete o texto com as palavras do quadro.", "prompt": "My sister Bia is trying to live a healthier life. She wants ___ more vegetables, and she has stopped ___ soda. She also avoids ___ fast food. Next month, she plans ___ a yoga class, and she hopes ___ better at night.", "bank": ["to eat", "drinking", "eating", "to join", "to sleep", "joining"], "answers": [["to eat"], ["drinking"], ["eating"], ["to join"], ["to sleep"]], "explain": "Want, plan e hope pedem \"to\"; stop e avoid pedem -ing.", "id": "bkB1-22"}, {"level": "B1", "topic": "Gerúndio x Infinitivo", "type": "choose", "instruction": "Escolha a forma correta em cada grupo.", "prompt": "I'm looking forward to [see/seeing*] you, and I promise [to arrive*/arriving] on time.", "explain": "\"Look forward to\" pede -ing; \"promise\" pede to + verbo.", "id": "bkB1-23"}, {"level": "B1", "topic": "Gerúndio x Infinitivo", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "Would you mind to close the window?", "wrong": "to close", "fix": ["closing"], "explain": "\"Mind\" é seguido de verbo com -ing.", "id": "bkB1-24"}, {"level": "B1", "topic": "Gerúndio x Infinitivo", "type": "rewrite", "instruction": "Reescreva começando com \"It is\" e use o infinitivo.", "prompt": "Learning a new language is fun.", "start": "It is", "accept": ["It is fun to learn a new language"], "explain": "Estrutura: It is + adjetivo + to + verbo.", "id": "bkB1-25"}, {"level": "B1", "topic": "Gerúndio x Infinitivo", "type": "order", "instruction": "Ordene as palavras para formar uma frase.", "words": ["She", "gave", "up", "eating", "meat", "two", "years", "ago"], "alt": ["Two years ago she gave up eating meat"], "explain": "Depois de phrasal verbs como \"give up\", usamos -ing.", "id": "bkB1-26"}, {"level": "B1", "topic": "Gerúndio x Infinitivo", "type": "match", "instruction": "Ligue as duas partes de cada frase.", "left": ["I miss", "We finished", "He refused", "Do you feel like"], "right": ["to answer the reporter's questions.", "going out tonight?", "painting the kitchen at 6 p.m.", "living near my grandparents."], "correctMap": [3, 2, 0, 1], "explain": "Miss, finish e feel like pedem -ing; refuse pede to + verbo.", "id": "bkB1-27"}, {"level": "B1", "topic": "Gerúndio x Infinitivo", "type": "sort", "instruction": "Classifique os verbos pela forma que vem depois deles.", "groups": ["+ verbo com -ing", "+ to + verbo"], "items": [{"w": "enjoy", "g": 0}, {"w": "avoid", "g": 0}, {"w": "mind", "g": 0}, {"w": "finish", "g": 0}, {"w": "want", "g": 1}, {"w": "hope", "g": 1}, {"w": "decide", "g": 1}, {"w": "promise", "g": 1}], "explain": "Cada verbo exige uma forma fixa: -ing ou to + verbo.", "prompt": "Put each item in the right group: + verbo com -ing or + to + verbo.", "id": "bkB1-28"}, {"level": "B1", "topic": "Gerúndio x Infinitivo", "type": "dorder", "instruction": "Coloque as falas do diálogo na ordem correta.", "lines": ["A: Do you want to go to the movies tonight?", "B: I'd love to, but I need to study for my test.", "A: Oh, come on! You can't keep studying all day.", "B: You're right. What time does the movie start?", "A: At eight. I'll buy the tickets."], "explain": "Convite, desculpa, insistência, aceitação e combinação do horário.", "id": "bkB1-29"}, {"level": "B1", "topic": "Voz Passiva", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "This bridge ___ in 1974.", "options": ["built", "was built", "has built", "is building"], "correctIndex": 1, "explain": "A ponte não constrói; ela foi construída: was + particípio.", "id": "bkB1-30"}, {"level": "B1", "topic": "Voz Passiva", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "English ___ in many countries around the world.", "options": ["speaks", "is spoken", "is speaking", "spoken"], "correctIndex": 1, "explain": "Passiva no presente: is/are + particípio.", "id": "bkB1-31"}, {"level": "B1", "topic": "Voz Passiva", "type": "gaps", "instruction": "Complete com os verbos na voz passiva.", "prompt": "The Christ the Redeemer statue ___ (finish) in 1931. Today, it ___ (visit) by millions of tourists every year.", "answers": [["was finished", "was completed"], ["is visited"]], "explain": "1931 pede passado (was + particípio); hábito atual pede is + particípio.", "id": "bkB1-32"}, {"level": "B1", "topic": "Voz Passiva", "type": "choose", "instruction": "Escolha a forma correta em cada grupo.", "prompt": "The emails [was/were*] sent yesterday, and the report [is*/are] being written now.", "explain": "\"Emails\" é plural (were); \"report\" é singular (is).", "id": "bkB1-33"}, {"level": "B1", "topic": "Voz Passiva", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "The package was deliver this morning.", "wrong": "deliver", "fix": ["delivered"], "explain": "A voz passiva usa o verbo to be + particípio (delivered).", "id": "bkB1-34"}, {"level": "B1", "topic": "Voz Passiva", "type": "rewrite", "instruction": "Reescreva na voz passiva, sem dizer quem fez a ação.", "prompt": "Someone stole my bike last night.", "start": "My bike", "accept": ["My bike was stolen last night"], "explain": "Passado na passiva: was + particípio (stolen).", "id": "bkB1-35"}, {"level": "B1", "topic": "Voz Passiva", "type": "rewrite", "instruction": "Reescreva na voz passiva, sem dizer quem fez a ação.", "prompt": "They make these shoes in Franca.", "start": "These shoes", "accept": ["These shoes are made in Franca"], "explain": "Presente na passiva: are + particípio (made).", "id": "bkB1-36"}, {"level": "B1", "topic": "Voz Passiva", "type": "order", "instruction": "Ordene as palavras para formar uma frase.", "words": ["The", "results", "will", "be", "announced", "next", "Friday"], "alt": ["Next Friday the results will be announced"], "explain": "Passiva no futuro: will be + particípio.", "id": "bkB1-37"}, {"level": "B1", "topic": "Voz Passiva", "type": "odd", "instruction": "Qual frase NÃO está na voz passiva?", "prompt": "Which sentence is NOT in the passive voice?", "options": ["The door was opened.", "Rice is grown in the South.", "The kids were playing outside.", "The letters have been sent."], "correctIndex": 2, "explain": "\"Were playing\" é passado contínuo ativo; as outras usam be + particípio.", "id": "bkB1-38"}, {"level": "B1", "topic": "Voz Passiva", "type": "tf", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "The first coffee plants were brought to Brazil from French Guiana in 1727. Today, Brazil is the largest coffee producer in the world. Most of the coffee is grown in Minas Gerais, São Paulo and Espírito Santo. A large part of it is exported to the United States and Europe.", "items": [{"s": "The first coffee plants were brought to Brazil from Europe.", "a": false}, {"s": "Brazil produces more coffee than any other country.", "a": true}, {"s": "Most Brazilian coffee is grown in the North.", "a": false}, {"s": "Some Brazilian coffee is sold to Europe.", "a": true}], "explain": "O texto cita a Guiana Francesa e estados do Sudeste; exporta para a Europa.", "id": "bkB1-39"}, {"level": "B1", "topic": "Relative Clauses", "type": "mcq", "instruction": "Escolha o pronome relativo correto.", "prompt": "The woman ___ lives next door is a doctor.", "options": ["which", "who", "whose", "where"], "correctIndex": 1, "explain": "\"Who\" se refere a pessoas.", "id": "bkB1-40"}, {"level": "B1", "topic": "Relative Clauses", "type": "mcq", "instruction": "Escolha o pronome relativo correto.", "prompt": "That's the restaurant ___ we had our first date.", "options": ["which", "who", "where", "whose"], "correctIndex": 2, "explain": "\"Where\" se refere a lugares.", "id": "bkB1-41"}, {"level": "B1", "topic": "Relative Clauses", "type": "gaps", "instruction": "Complete com o pronome relativo correto.", "prompt": "I have a friend ___ father is a pilot. He lives in a town ___ there are no traffic lights.", "answers": [["whose"], ["where", "in which"]], "explain": "\"Whose\" indica posse; \"where\" indica lugar.", "id": "bkB1-42"}, {"level": "B1", "topic": "Relative Clauses", "type": "choose", "instruction": "Escolha o pronome correto em cada grupo.", "prompt": "The book [who/which*] you lent me was great, and the author, [who*/which] is from Bahia, is very famous.", "explain": "\"Which\" para coisas; \"who\" para pessoas.", "id": "bkB1-43"}, {"level": "B1", "topic": "Relative Clauses", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "This is the man which helped me at the airport.", "wrong": "which", "fix": ["who", "that"], "explain": "Para pessoas usamos \"who\" ou \"that\", não \"which\".", "id": "bkB1-44"}, {"level": "B1", "topic": "Relative Clauses", "type": "rewrite", "instruction": "Junte as frases usando um pronome relativo.", "prompt": "I met a girl. She speaks five languages.", "start": "I met a girl", "accept": ["I met a girl who speaks five languages", "I met a girl that speaks five languages"], "explain": "\"Who/that\" substitui \"she\" e liga as duas frases.", "id": "bkB1-45"}, {"level": "B1", "topic": "Relative Clauses", "type": "order", "instruction": "Ordene as palavras para formar uma frase.", "words": ["The", "phone", "that", "I", "bought", "last", "week", "is", "broken"], "explain": "A oração \"that I bought last week\" descreve \"the phone\".", "id": "bkB1-46"}, {"level": "B1", "topic": "Relative Clauses", "type": "match", "instruction": "Ligue as partes para formar definições.", "left": ["A chef is a person", "A bakery is a place", "A key is a thing", "An orphan is a child"], "right": ["whose parents have died.", "who cooks in a restaurant.", "that opens a door.", "where you buy bread."], "correctMap": [1, 3, 2, 0], "explain": "Who para pessoas, where para lugares, that para coisas, whose para posse.", "id": "bkB1-47"}, {"level": "B1", "topic": "Relative Clauses", "type": "sort", "instruction": "Classifique cada expressão pelo pronome que completa a lacuna.", "groups": ["who", "which", "where"], "items": [{"w": "a teacher ___ explains well", "g": 0}, {"w": "the city ___ I was born", "g": 2}, {"w": "a machine ___ makes coffee", "g": 1}, {"w": "the hotel ___ we stayed", "g": 2}, {"w": "my cousin ___ plays in a band", "g": 0}, {"w": "the movie ___ won the Oscar", "g": 1}], "explain": "Who: pessoas; which: coisas; where: lugares.", "prompt": "Put each item in the right group: who or which or where.", "id": "bkB1-48"}, {"level": "B1", "topic": "Relative Clauses", "type": "reading", "instruction": "Leia o anúncio e responda às perguntas.", "text": "WANTED: WEEKEND ASSISTANT\nCasa Verde is a family-run garden shop which has been open in Porto Alegre since 1990. We are looking for someone who loves plants and enjoys talking to customers. The person who gets the job will work on Saturdays and Sundays. Candidates whose Spanish is good will have an advantage, because many of our customers come from Uruguay. Send your CV to the email address below.", "questions": [{"q": "What kind of person is the shop looking for?", "options": ["Someone who loves plants.", "Someone who is from Uruguay.", "Someone who can drive."], "correctIndex": 0}, {"q": "When will the new assistant work?", "options": ["On weekdays.", "On weekends.", "Only on Sundays."], "correctIndex": 1}, {"q": "Why is Spanish useful for this job?", "options": ["The owners are from Spain.", "Many customers come from Uruguay.", "The shop sells Spanish plants."], "correctIndex": 1}], "explain": "As orações com who/whose descrevem o candidato ideal.", "id": "bkB1-49"}, {"level": "B1", "topic": "Tag Questions", "type": "mcq", "instruction": "Escolha a tag question correta.", "prompt": "You're from Manaus, ___?", "options": ["aren't you", "don't you", "isn't it", "are you"], "correctIndex": 0, "explain": "Frase afirmativa com \"are\" pede tag negativa com \"aren't\".", "id": "bkB1-50"}, {"level": "B1", "topic": "Tag Questions", "type": "mcq", "instruction": "Escolha a tag question correta.", "prompt": "She didn't call you, ___?", "options": ["didn't she", "did she", "does she", "wasn't she"], "correctIndex": 1, "explain": "Frase negativa no passado pede tag afirmativa com \"did\".", "id": "bkB1-51"}, {"level": "B1", "topic": "Tag Questions", "type": "gaps", "instruction": "Complete o diálogo com as tag questions.", "prompt": "A: It's a beautiful day, ___?\nB: Yes, it is! You haven't been to this park before, ___?\nA: No, I haven't. We can come back next week, ___?", "answers": [["isn't it"], ["have you"], ["can't we"]], "explain": "A tag repete o auxiliar com a polaridade oposta.", "id": "bkB1-52"}, {"level": "B1", "topic": "Tag Questions", "type": "choose", "instruction": "Escolha a forma correta em cada grupo.", "prompt": "Let's order pizza, [shall*/will/do] we? You like pepperoni, [don't*/doesn't] you?", "explain": "\"Let's\" pede \"shall we\"; \"you like\" pede \"don't you\".", "id": "bkB1-53"}, {"level": "B1", "topic": "Tag Questions", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "He can swim, doesn't he?", "wrong": "doesn't", "fix": ["can't"], "explain": "O auxiliar da frase é \"can\", então a tag é \"can't he\".", "id": "bkB1-54"}, {"level": "B1", "topic": "Tag Questions", "type": "rewrite", "instruction": "Acrescente a tag question correta.", "prompt": "They live in Belo Horizonte.", "start": "They live in Belo Horizonte", "accept": ["They live in Belo Horizonte, don't they?"], "explain": "Presente afirmativo com \"they\" pede \"don't they\".", "id": "bkB1-55"}, {"level": "B1", "topic": "Tag Questions", "type": "match", "instruction": "Ligue cada frase à sua tag question.", "left": ["I'm late,", "Nobody called,", "Tom has a dog,", "Don't forget the tickets,"], "right": ["did they?", "aren't I?", "will you?", "doesn't he?"], "correctMap": [1, 0, 3, 2], "explain": "\"I am\" usa \"aren't I\"; \"nobody\" usa \"they\"; imperativo usa \"will you\".", "id": "bkB1-56"}, {"level": "B1", "topic": "Tag Questions", "type": "sort", "instruction": "A tag question destas frases é positiva ou negativa?", "groups": ["Tag positiva", "Tag negativa"], "items": [{"w": "You aren't hungry, ...", "g": 0}, {"w": "She never eats meat, ...", "g": 0}, {"w": "They went to Bahia, ...", "g": 1}, {"w": "It's cold today, ...", "g": 1}, {"w": "We can't park here, ...", "g": 0}, {"w": "He has finished, ...", "g": 1}], "explain": "Frase negativa (inclusive com \"never\") pede tag positiva, e vice-versa.", "prompt": "Put each item in the right group: Tag positiva or Tag negativa.", "id": "bkB1-57"}, {"level": "B1", "topic": "Tag Questions", "type": "odd", "instruction": "Qual tag question está INCORRETA?", "prompt": "Which tag question is NOT correct?", "options": ["It's late, isn't it?", "You were tired, weren't you?", "She speaks French, isn't she?", "They won't come, will they?"], "correctIndex": 2, "explain": "\"She speaks\" usa o auxiliar \"does\": \"doesn't she?\".", "id": "bkB1-58"}, {"level": "B1", "topic": "Tag Questions", "type": "dorder", "instruction": "Coloque as falas do diálogo na ordem correta.", "lines": ["A: You're the new designer, aren't you?", "B: Yes, I am. I started on Monday.", "A: Welcome! You haven't met the boss yet, have you?", "B: No, not yet. Is she in the office today?", "A: Yes, she is. I'll introduce you."], "explain": "Apresentação, confirmação, pergunta sobre a chefe e oferta de apresentá-la.", "id": "bkB1-59"}, {"level": "B1", "topic": "Dedução (must/can't) & Used to", "type": "mcq", "instruction": "Escolha a palavra correta.", "prompt": "He's been working for 14 hours. He ___ be exhausted.", "options": ["must", "can't", "used to", "doesn't"], "correctIndex": 0, "explain": "\"Must\" expressa certeza lógica positiva.", "id": "bkB1-60"}, {"level": "B1", "topic": "Dedução (must/can't) & Used to", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "When I was a kid, I ___ play video games every afternoon.", "options": ["use to", "used to", "am used to", "using to"], "correctIndex": 1, "explain": "\"Used to\" + verbo indica hábito no passado.", "id": "bkB1-61"}, {"level": "B1", "topic": "Dedução (must/can't) & Used to", "type": "gaps", "instruction": "Complete com must ou can't.", "prompt": "That ___ be Ana at the door. She's in London this week! It ___ be the delivery guy. I ordered a pizza and I'm not expecting anyone else.", "answers": [["can't", "cannot"], ["must"]], "explain": "\"Can't\" para impossibilidade; \"must\" para certeza lógica.", "id": "bkB1-62"}, {"level": "B1", "topic": "Dedução (must/can't) & Used to", "type": "choose", "instruction": "Escolha a forma correta em cada grupo.", "prompt": "My grandfather [used to*/uses to] work on a farm, but he [didn't use to*/didn't used to] like it.", "explain": "Afirmativa: used to; negativa com \"didn't\": use to.", "id": "bkB1-63"}, {"level": "B1", "topic": "Dedução (must/can't) & Used to", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "Did you used to live in Salvador?", "wrong": "used", "fix": ["use"], "explain": "Depois de \"did\", o verbo fica na forma base: \"use to\".", "id": "bkB1-64"}, {"level": "B1", "topic": "Dedução (must/can't) & Used to", "type": "rewrite", "instruction": "Reescreva usando \"must\".", "prompt": "I'm sure she is at home.", "start": "She", "accept": ["She must be at home", "She must be home"], "explain": "Certeza lógica no presente: must + be.", "id": "bkB1-65"}, {"level": "B1", "topic": "Dedução (must/can't) & Used to", "type": "order", "instruction": "Ordene as palavras para formar uma frase.", "words": ["We", "used", "to", "go", "camping", "every", "summer"], "alt": ["Every summer we used to go camping"], "explain": "Used to + verbo base para hábito passado.", "id": "bkB1-66"}, {"level": "B1", "topic": "Dedução (must/can't) & Used to", "type": "match", "instruction": "Ligue as duas partes de cada frase.", "left": ["His car is outside, so", "She's only 12, so", "They used to live in Rio, so", "You didn't sleep last night, so"], "right": ["they must know the city well.", "you must be tired.", "he must be at home.", "she can't be the new manager."], "correctMap": [2, 3, 0, 1], "explain": "Cada conclusão com must/can't se baseia na evidência da primeira parte.", "id": "bkB1-67"}, {"level": "B1", "topic": "Dedução (must/can't) & Used to", "type": "sort", "instruction": "Qual palavra completa cada frase: must ou can't?", "groups": ["must", "can't"], "items": [{"w": "He won the lottery. He ___ be rich.", "g": 0}, {"w": "It's 40°C outside. You ___ be cold.", "g": 1}, {"w": "They've been walking all day. They ___ be tired.", "g": 0}, {"w": "She just ate a huge lunch. She ___ be hungry.", "g": 1}, {"w": "The restaurant is always full. The food ___ be good.", "g": 0}, {"w": "He doesn't have a car. That ___ be his car.", "g": 1}], "explain": "\"Must\" para certeza positiva; \"can't\" para certeza de que não é verdade.", "prompt": "Put each item in the right group: must or can't.", "id": "bkB1-68"}, {"level": "B1", "topic": "Dedução (must/can't) & Used to", "type": "tf", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "When Rafael was a teenager, he used to live in a small town in Goiás. He used to ride his bike to school, and he didn't use to have a phone. Now he lives in São Paulo and works in an office. He doesn't have much free time, and he misses the quiet life he used to have.", "items": [{"s": "Rafael lived in Goiás when he was young.", "a": true}, {"s": "He used to go to school by bus.", "a": false}, {"s": "He had a phone when he was a teenager.", "a": false}, {"s": "He misses his old life.", "a": true}], "explain": "O texto diz que ele ia de bicicleta e não tinha celular.", "id": "bkB1-69"}, {"level": "B1", "topic": "Do x Make", "type": "mcq", "instruction": "Escolha o verbo correto.", "prompt": "Can you ___ me a favor?", "options": ["make", "do", "give", "take"], "correctIndex": 1, "explain": "A expressão fixa é \"do someone a favor\".", "id": "bkB1-70"}, {"level": "B1", "topic": "Do x Make", "type": "mcq", "instruction": "Escolha o verbo correto.", "prompt": "Be quiet! Don't ___ so much noise.", "options": ["do", "make", "have", "take"], "correctIndex": 1, "explain": "A expressão fixa é \"make noise\".", "id": "bkB1-71"}, {"level": "B1", "topic": "Do x Make", "type": "gaps", "instruction": "Complete com do ou make.", "prompt": "On Saturday mornings, I ___ the housework. First, I ___ my bed. Then I ___ the dishes and ___ breakfast for my kids. In the afternoon, I ___ some exercise at the park.", "answers": [["do"], ["make"], ["do"], ["make"], ["do"]], "explain": "Do: housework, dishes, exercise. Make: bed, breakfast.", "id": "bkB1-72"}, {"level": "B1", "topic": "Do x Make", "type": "choose", "instruction": "Escolha o verbo correto em cada grupo.", "prompt": "I need to [do*/make] my homework before I [do/make*] a phone call.", "explain": "Dizemos \"do homework\" e \"make a phone call\".", "id": "bkB1-73"}, {"level": "B1", "topic": "Do x Make", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "My brother did a lot of money selling cars.", "wrong": "did", "fix": ["made"], "explain": "A expressão correta é \"make money\".", "id": "bkB1-74"}, {"level": "B1", "topic": "Do x Make", "type": "odd", "instruction": "Qual expressão NÃO combina com MAKE?", "prompt": "Which word does NOT go with MAKE?", "options": ["a cake", "a decision", "the laundry", "friends"], "correctIndex": 2, "explain": "Dizemos \"do the laundry\"; as outras vão com \"make\".", "id": "bkB1-75"}, {"level": "B1", "topic": "Do x Make", "type": "sort", "instruction": "Classifique as expressões: DO ou MAKE?", "groups": ["DO", "MAKE"], "items": [{"w": "homework", "g": 0}, {"w": "a mistake", "g": 1}, {"w": "the shopping", "g": 0}, {"w": "a plan", "g": 1}, {"w": "business", "g": 0}, {"w": "an effort", "g": 1}, {"w": "your best", "g": 0}, {"w": "a promise", "g": 1}], "explain": "Do: tarefas e atividades. Make: criar ou produzir algo.", "prompt": "Put each item in the right group: DO or MAKE.", "id": "bkB1-76"}, {"level": "B1", "topic": "Do x Make", "type": "match", "instruction": "Ligue as duas partes de cada frase.", "left": ["I'm not ready to make", "Could you do", "He always does", "Stop making"], "right": ["his best at work.", "fun of your sister!", "a decision yet.", "the washing-up tonight?"], "correctMap": [2, 3, 0, 1], "explain": "Make a decision, do the washing-up, do your best, make fun of.", "id": "bkB1-77"}, {"level": "B1", "topic": "Do x Make", "type": "order", "instruction": "Ordene as palavras para formar uma pergunta.", "words": ["Did", "you", "make", "any", "plans", "for", "the", "weekend"], "explain": "Dizemos \"make plans\".", "id": "bkB1-78"}, {"level": "B1", "topic": "Do x Make", "type": "reading", "instruction": "Leia a mensagem e responda às perguntas.", "text": "Hi Marina! I've made a list of things we need to do before the party. Can you do the shopping on Friday? I'll make the cake and the snacks. Pedro said he would make a playlist, but he's doing overtime at work, so he might be late. Please don't make any noise when you arrive. Grandma will be sleeping!\nLove,\nClara", "questions": [{"q": "What does Clara want Marina to do?", "options": ["Make the cake.", "Do the shopping.", "Make a playlist."], "correctIndex": 1}, {"q": "Why might Pedro be late?", "options": ["He's working extra hours.", "He's making the snacks.", "He's sleeping."], "correctIndex": 0}, {"q": "Who will make the cake?", "options": ["Marina", "Pedro", "Clara"], "correctIndex": 2}], "explain": "A mensagem diz quem faz cada tarefa e que Pedro está fazendo hora extra.", "id": "bkB1-79"}, {"level": "B1", "topic": "To x For", "type": "mcq", "instruction": "Escolha a opção correta.", "prompt": "I went to the pharmacy ___ some medicine.", "options": ["for buy", "to buy", "for buying", "to buying"], "correctIndex": 1, "explain": "Para indicar finalidade com verbo, usamos to + verbo.", "id": "bkB1-80"}, {"level": "B1", "topic": "To x For", "type": "mcq", "instruction": "Escolha a preposição correta.", "prompt": "This knife is ___ cutting bread.", "options": ["to", "for", "by", "of"], "correctIndex": 1, "explain": "Para dizer a função de um objeto, usamos for + -ing.", "id": "bkB1-81"}, {"level": "B1", "topic": "To x For", "type": "gaps", "instruction": "Complete com to ou for.", "prompt": "I bought some flowers ___ my mom. I gave them ___ her on Sunday.", "answers": [["for"], ["to"]], "explain": "Buy something for someone (beneficiário); give something to someone (destino).", "id": "bkB1-82"}, {"level": "B1", "topic": "To x For", "type": "choose", "instruction": "Escolha a preposição correta em cada grupo.", "prompt": "We waited [to/for*] the bus [for*/to] forty minutes.", "explain": "\"Wait for\" algo; \"for\" também indica duração.", "id": "bkB1-83"}, {"level": "B1", "topic": "To x For", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "I came to Canada for learn English.", "wrong": "for learn", "fix": ["to learn"], "explain": "Finalidade com verbo: to + verbo, nunca for + verbo base.", "id": "bkB1-84"}, {"level": "B1", "topic": "To x For", "type": "rewrite", "instruction": "Reescreva usando \"to\" para expressar finalidade.", "prompt": "I went to the bank because I wanted to open an account.", "start": "I went to the bank", "accept": ["I went to the bank to open an account", "I went to the bank in order to open an account"], "explain": "To + verbo expressa o objetivo da ação.", "id": "bkB1-85"}, {"level": "B1", "topic": "To x For", "type": "order", "instruction": "Ordene as palavras para formar uma pergunta.", "words": ["Is", "this", "gift", "for", "me", "or", "for", "your", "sister"], "alt": ["Is this gift for your sister or for me"], "explain": "\"For\" indica para quem é algo.", "id": "bkB1-86"}, {"level": "B1", "topic": "To x For", "type": "match", "instruction": "Ligue as duas partes de cada frase.", "left": ["Thank you", "She moved to Lisbon", "This room is", "He explained the rule"], "right": ["to the new students.", "for your help.", "to study design.", "for guests only."], "correctMap": [1, 2, 3, 0], "explain": "Thank you for; to + verbo (finalidade); for (destinado a); explain to someone.", "id": "bkB1-87"}, {"level": "B1", "topic": "To x For", "type": "sort", "instruction": "Qual preposição completa cada expressão?", "groups": ["to", "for"], "items": [{"w": "listen ___ music", "g": 0}, {"w": "wait ___ someone", "g": 1}, {"w": "look ___ your keys", "g": 1}, {"w": "talk ___ your boss", "g": 0}, {"w": "pay ___ the tickets", "g": 1}, {"w": "belong ___ someone", "g": 0}], "explain": "São combinações fixas de verbo + preposição.", "prompt": "Put each item in the right group: to or for.", "id": "bkB1-88"}, {"level": "B1", "topic": "To x For", "type": "tf", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Every morning, Júlia goes to the bakery to buy fresh bread for her family. On Saturdays, she buys a chocolate cake for her son, Theo. Last week, she also bought a card for Theo's teacher and gave it to her on the last day of class. Theo wrote a thank-you message inside the card.", "items": [{"s": "Júlia goes to the bakery to buy bread.", "a": true}, {"s": "The chocolate cake is for her husband.", "a": false}, {"s": "Theo gave the card to his teacher.", "a": false}, {"s": "Theo wrote a message in the card.", "a": true}], "explain": "O bolo é para Theo, e foi Júlia quem entregou o cartão.", "id": "bkB1-89"}, {"level": "B1", "topic": "Conectores avançados", "type": "mcq", "instruction": "Escolha o conector correto.", "prompt": "___ it was raining, we went for a walk.", "options": ["Despite", "Although", "However", "Because of"], "correctIndex": 1, "explain": "\"Although\" + oração completa expressa contraste.", "id": "bkB1-90"}, {"level": "B1", "topic": "Conectores avançados", "type": "mcq", "instruction": "Escolha o conector correto.", "prompt": "The hotel was expensive. ___, the service was terrible.", "options": ["Moreover", "Although", "Despite", "Unless"], "correctIndex": 0, "explain": "\"Moreover\" acrescenta outra informação negativa.", "id": "bkB1-91"}, {"level": "B1", "topic": "Conectores avançados", "type": "gaps", "instruction": "Complete o texto com as palavras do quadro.", "prompt": "I wanted to study abroad last year. ___, I didn't have enough money, so I got a part-time job. ___ working long hours, I kept studying English every night. My brother loves big cities, ___ I prefer quiet places, so I chose a small town in Ireland. I'll go next year ___ something unexpected happens.", "bank": ["However", "Despite", "whereas", "unless", "Therefore", "because"], "answers": [["However"], ["Despite", "In spite of"], ["whereas", "while", "although", "but"], ["unless"]], "explain": "However e whereas: contraste; despite + -ing; unless = a menos que.", "id": "bkB1-92"}, {"level": "B1", "topic": "Conectores avançados", "type": "choose", "instruction": "Escolha o conector correto em cada grupo.", "prompt": "She passed the exam [despite*/although] being sick, and her parents were very proud. She had studied a lot. [Therefore*/Unless], the result was no surprise.", "explain": "\"Despite\" + -ing; \"therefore\" indica consequência.", "id": "bkB1-93"}, {"level": "B1", "topic": "Conectores avançados", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "Despite of the traffic, we arrived on time.", "wrong": "Despite of", "fix": ["Despite", "In spite of"], "explain": "Dizemos \"despite\" ou \"in spite of\", nunca \"despite of\".", "id": "bkB1-94"}, {"level": "B1", "topic": "Conectores avançados", "type": "rewrite", "instruction": "Reescreva começando com \"Although\".", "prompt": "It was cold, but they went swimming.", "start": "Although", "accept": ["Although it was cold, they went swimming"], "explain": "\"Although\" introduz a oração de contraste e substitui \"but\".", "id": "bkB1-95"}, {"level": "B1", "topic": "Conectores avançados", "type": "rewrite", "instruction": "Reescreva começando com \"In spite of\".", "prompt": "He was tired, but he finished the report.", "start": "In spite of", "accept": ["In spite of being tired, he finished the report", "In spite of feeling tired, he finished the report", "In spite of his tiredness, he finished the report", "In spite of the fact that he was tired, he finished the report"], "explain": "\"In spite of\" é seguido de -ing ou substantivo, não de oração.", "id": "bkB1-96"}, {"level": "B1", "topic": "Conectores avançados", "type": "match", "instruction": "Ligue as duas partes de cada frase.", "left": ["You won't pass", "Carlos is very shy,", "The flight was delayed;", "She speaks four languages;"], "right": ["therefore, we missed our connection.", "moreover, she can play the piano.", "unless you study harder.", "whereas his sister is very outgoing."], "correctMap": [2, 3, 0, 1], "explain": "Unless: condição; whereas: contraste; therefore: consequência; moreover: adição.", "id": "bkB1-97"}, {"level": "B1", "topic": "Conectores avançados", "type": "sort", "instruction": "Classifique os conectores pela função.", "groups": ["Contraste", "Adição", "Consequência"], "items": [{"w": "although", "g": 0}, {"w": "however", "g": 0}, {"w": "nevertheless", "g": 0}, {"w": "moreover", "g": 1}, {"w": "furthermore", "g": 1}, {"w": "in addition", "g": 1}, {"w": "therefore", "g": 2}, {"w": "as a result", "g": 2}], "explain": "Cada conector tem uma função: opor ideias, somar ou mostrar resultado.", "prompt": "Put each item in the right group: Contraste or Adição or Consequência.", "id": "bkB1-98"}, {"level": "B1", "topic": "Conectores avançados", "type": "dorder", "instruction": "Coloque as falas do diálogo na ordem correta.", "lines": ["A: Did you enjoy the concert last night?", "B: Yes, although it was really crowded.", "A: Really? I heard the tickets were sold out.", "B: They were. However, my cousin had an extra one.", "A: Lucky you! I couldn't get one."], "explain": "Pergunta, resposta com \"although\", comentário, explicação com \"however\" e reação.", "id": "bkB1-99"}, {"level": "B1", "topic": "Perguntas indiretas", "type": "mcq", "instruction": "Escolha a opção correta.", "prompt": "Could you tell me where ___?", "options": ["is the station", "the station is", "does the station", "the station"], "correctIndex": 1, "explain": "Na pergunta indireta, a ordem é sujeito + verbo.", "id": "bkB1-100"}, {"level": "B1", "topic": "Perguntas indiretas", "type": "mcq", "instruction": "Escolha a opção correta.", "prompt": "I wonder ___ he will come to the party.", "options": ["that", "if", "does", "what"], "correctIndex": 1, "explain": "Perguntas de sim/não viram indiretas com \"if\" ou \"whether\".", "id": "bkB1-101"}, {"level": "B1", "topic": "Perguntas indiretas", "type": "gaps", "instruction": "Complete com os verbos na forma correta.", "prompt": "Do you know what time the museum ___ (open)? I'd also like to know how much the tickets ___ (cost).", "answers": [["opens", "will open"], ["cost", "will cost"]], "explain": "Sem \"do/does\": o verbo fica na forma afirmativa normal.", "id": "bkB1-102"}, {"level": "B1", "topic": "Perguntas indiretas", "type": "choose", "instruction": "Escolha a opção correta em cada grupo.", "prompt": "Can you tell me [what time is it/what time it is*]? And do you know [if*/does] the bank is open?", "explain": "Ordem afirmativa (it is) e \"if\" para perguntas de sim/não.", "id": "bkB1-103"}, {"level": "B1", "topic": "Perguntas indiretas", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "I don't know where does she live.", "wrong": "does she live", "fix": ["she lives"], "explain": "Em perguntas indiretas não usamos \"does\"; fica sujeito + verbo.", "id": "bkB1-104"}, {"level": "B1", "topic": "Perguntas indiretas", "type": "rewrite", "instruction": "Transforme em pergunta indireta.", "prompt": "Where is the nearest hospital?", "start": "Could you tell me", "accept": ["Could you tell me where the nearest hospital is?"], "explain": "O verbo \"is\" vai para depois do sujeito.", "id": "bkB1-105"}, {"level": "B1", "topic": "Perguntas indiretas", "type": "rewrite", "instruction": "Transforme em pergunta indireta.", "prompt": "Did the package arrive?", "start": "Do you know", "accept": ["Do you know if the package arrived?", "Do you know whether the package arrived?", "Do you know if the package has arrived?", "Do you know whether the package has arrived?"], "explain": "Sem \"did\": use if/whether + sujeito + verbo no passado.", "id": "bkB1-106"}, {"level": "B1", "topic": "Perguntas indiretas", "type": "order", "instruction": "Ordene as palavras para formar uma pergunta.", "words": ["Do", "you", "know", "how", "long", "the", "trip", "takes"], "explain": "Depois de \"Do you know\", a ordem é sujeito + verbo.", "id": "bkB1-107"}, {"level": "B1", "topic": "Perguntas indiretas", "type": "odd", "instruction": "Qual pergunta indireta está INCORRETA?", "prompt": "Which indirect question is NOT correct?", "options": ["Can you tell me where the restrooms are?", "I'd like to know how much it costs.", "Do you know what time does the bus leave?", "Could you tell me if she is at home?"], "correctIndex": 2, "explain": "Não se usa \"does\" em pergunta indireta: \"what time the bus leaves\".", "id": "bkB1-108"}, {"level": "B1", "topic": "Perguntas indiretas", "type": "reading", "instruction": "Leia a mensagem e responda às perguntas.", "text": "Hello! My name is Diego, and I'm moving to Florianópolis next month. I'd like to know if there are any Portuguese courses for foreigners in the city. Could you also tell me how much the courses cost and whether they have evening classes? I work during the day, so I can only study after 6 p.m.\nThank you in advance!\nDiego Ramírez", "questions": [{"q": "What does Diego want to know first?", "options": ["If there are Portuguese courses.", "Where he can find a job.", "How big the city is."], "correctIndex": 0}, {"q": "Why does Diego need evening classes?", "options": ["He sleeps late.", "He works during the day.", "He lives far from the school."], "correctIndex": 1}], "explain": "Diego faz perguntas indiretas sobre cursos e diz que trabalha de dia.", "id": "bkB1-109"}, {"type": "mcq", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Escolha a opção correta.", "explain": "\"Since Christmas\" indica algo que começou no passado e continua: present perfect (have had).", "prompt": "How long ___ you had this phone? — Since Christmas.", "options": ["do", "did", "have", "are"], "correctIndex": 2, "id": "bkB1-110"}, {"type": "mcq", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Escolha a opção correta.", "explain": "A resposta dá um ano específico (2014), então a pergunta usa simple past: did + verbo base.", "prompt": "When ___ Brazil host the World Cup for the second time? — In 2014.", "options": ["has", "did", "have", "was"], "correctIndex": 1, "id": "bkB1-111"}, {"type": "mcq", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Escolha a opção correta.", "explain": "\"Has gone\" = foi e ainda não voltou. \"Has been\" = foi e já voltou, o que contradiz \"isn't here\".", "prompt": "Rodrigo isn't here right now. He ___ to the gym.", "options": ["has gone", "has been", "have gone", "go"], "correctIndex": 0, "id": "bkB1-112"}, {"type": "gaps", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Complete com o present perfect ou o simple past.", "explain": "\"An hour ago\" pede simple past (sent); \"yet\" na negativa pede present perfect (hasn't replied).", "prompt": "A: Have you ___ (finish) the report?\nB: Yes, I ___ (send) it to the boss an hour ago, but he ___ (not / reply) yet.", "answers": [["finished"], ["sent"], ["hasn't replied", "has not replied"]], "id": "bkB1-113"}, {"type": "gaps", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Complete o e-mail com as palavras do quadro.", "explain": "Present perfect para período até agora e experiência (never); simple past com tempo definido (last weekend, yesterday).", "prompt": "Hi Leo! I ___ in Lisbon for three weeks now, and I love it. Last weekend I ___ to Sintra by train. I ___ never ___ such beautiful palaces! Yesterday I ___ my first pastel de nata here.", "bank": ["have been", "went", "have", "seen", "tried", "saw", "have gone"], "answers": [["have been"], ["went"], ["have"], ["seen"], ["tried", "ate"]], "id": "bkB1-114"}, {"type": "choose", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Escolha a forma verbal correta.", "explain": "\"Last night\" pede simple past; \"yet\" pede present perfect (haven't seen).", "prompt": "[Did you watch*/Have you watched] the final last night? I [didn't see/haven't seen*] it yet, so don't tell me the score!", "id": "bkB1-115"}, {"type": "choose", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Escolha a forma verbal correta.", "explain": "A avó ainda trabalha: present perfect. O avô já se aposentou: simple past (ação terminada).", "prompt": "My grandmother [has been*/was] a nurse for forty years, and she still loves her job. My grandfather [has worked/worked*] as a taxi driver until he retired.", "id": "bkB1-116"}, {"type": "error", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Encontre o erro e corrija.", "explain": "Para experiência com \"ever\" e o particípio \"been\", usamos \"Have you ever been...?\".", "sentence": "Did you ever been to Chile?", "wrong": "Did", "fix": ["Have"], "id": "bkB1-117"}, {"type": "error", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Encontre o erro e corrija.", "explain": "\"When I was ten\" é um momento terminado no passado: usamos simple past (moved).", "sentence": "We have moved to Fortaleza when I was ten.", "wrong": "have moved", "fix": ["moved"], "id": "bkB1-118"}, {"type": "rewrite", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Reescreva com present perfect e \"for\".", "explain": "Ação que começou no passado e continua: have worked / have been working + for + período.", "prompt": "I started working here three years ago.", "start": "I have", "accept": ["I have worked here for three years.", "I have been working here for three years.", "I have been here for three years."], "id": "bkB1-119"}, {"type": "rewrite", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Transforme em pergunta.", "explain": "Na pergunta, \"has\" vem antes do sujeito; \"yet\" é comum em perguntas no present perfect.", "prompt": "Sofia has already bought the tickets.", "start": "Has", "accept": ["Has Sofia already bought the tickets?", "Has Sofia bought the tickets yet?", "Has Sofia bought the tickets already?"], "id": "bkB1-120"}, {"type": "order", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"Just\" fica entre \"has\" e o particípio: has just finished.", "words": ["She", "has", "just", "finished", "her", "first", "marathon"], "id": "bkB1-121"}, {"type": "order", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "\"How many times\" + have you + particípio pergunta sobre experiência até hoje.", "words": ["How", "many", "times", "have", "you", "visited", "Bahia"], "id": "bkB1-122"}, {"type": "match", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Ligue as partes para formar frases.", "explain": "\"Since\" + situação atual = present perfect; período encerrado e \"When\" = simple past.", "left": ["I have lived in Manaus", "I lived in Manaus", "Have you ever", "When did you"], "right": ["start learning English?", "since 2018, and I love it.", "tried skydiving?", "for two years, then I moved to Belém."], "correctMap": [1, 3, 2, 0], "id": "bkB1-123"}, {"type": "sort", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Classifique as frases pelo tempo verbal.", "explain": "Present perfect: have/has + particípio. Simple past: verbo no passado, muitas vezes com tempo definido.", "prompt": "Is each sentence in the Present Perfect or the Simple Past?", "groups": ["Present Perfect", "Simple Past"], "items": [{"w": "I've never seen snow.", "g": 0}, {"w": "She lost her wallet on Monday.", "g": 1}, {"w": "They've just arrived.", "g": 0}, {"w": "We had lunch at noon.", "g": 1}, {"w": "Have you finished yet?", "g": 0}, {"w": "He called me two hours ago.", "g": 1}], "id": "bkB1-124"}, {"type": "odd", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Qual expressão não combina com o present perfect?", "explain": "\"A week ago\" indica um momento terminado e pede simple past; as outras combinam com present perfect.", "prompt": "Which time expression is NOT used with the Present Perfect?", "options": ["just", "lately", "a week ago", "recently"], "correctIndex": 2, "id": "bkB1-125"}, {"type": "blank", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Complete com a forma correta do verbo.", "explain": "\"So far\" (até agora) pede present perfect: has written.", "prompt": "Paula ___ (write) three books so far, and she's working on a fourth.", "accept": ["has written"], "id": "bkB1-126"}, {"type": "tf", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Desde 2017 ela trabalha na empresa; esteve na Europa só uma vez; ainda não voltou à Alemanha.", "text": "Marina is a software developer from Recife. She has worked for the same tech company since 2017. Last year, she went to a conference in Berlin, and it was her first time in Europe. She has studied German for six months, but she hasn't been back to Germany yet. Her team has just launched a new health app.", "items": [{"s": "Marina started at her company in 2017.", "a": true}, {"s": "She has visited Europe many times.", "a": false}, {"s": "She has returned to Germany.", "a": false}, {"s": "Her team launched a new app recently.", "a": true}], "id": "bkB1-127"}, {"type": "reading", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Leia o texto e responda às perguntas.", "explain": "Ela assinou ontem; ainda não se mudou porque o dono está pintando; o apartamento tem varanda.", "text": "Hi Gabi,\nGuess what? I've finally found an apartment! I saw it on Tuesday and signed the contract yesterday. It's small, but it has a balcony with a view of the sea. I haven't moved in yet, because the owner is still painting the walls. My brother has offered to help with the boxes next Saturday. Have you ever visited Vitória? You should come!\nHugs,\nNanda", "questions": [{"q": "When did Nanda sign the contract?", "options": ["On Tuesday", "Yesterday", "Next Saturday"], "correctIndex": 1}, {"q": "Why hasn't she moved in yet?", "options": ["The walls are being painted.", "She hasn't signed the contract.", "Her brother is busy."], "correctIndex": 0}, {"q": "What does the apartment have?", "options": ["A garden", "A balcony", "Two bedrooms"], "correctIndex": 1}], "id": "bkB1-128"}, {"type": "dorder", "level": "B1", "topic": "Present Perfect x Simple Past", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Pergunta de experiência (Have you ever) → resposta com data (simple past) → detalhes da viagem.", "lines": ["A: Have you ever been to Foz do Iguaçu?", "B: Yes, I have. I went there in 2019.", "A: Did you see the waterfalls from the Argentinian side too?", "B: No, I didn't. I only had one day.", "A: That's a pity. I've heard it's amazing."], "id": "bkB1-129"}, {"type": "mcq", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Escolha a opção correta.", "explain": "Zero conditional (fato geral): if + presente, presente.", "prompt": "If you heat ice, it ___.", "options": ["melts", "would melt", "melted", "will melting"], "correctIndex": 0, "id": "bkB1-130"}, {"type": "mcq", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Escolha a opção correta.", "explain": "Second conditional (situação imaginária): na parte do if usamos passado (could).", "prompt": "Where would you live if you ___ choose any city in the world?", "options": ["can", "could", "will", "would"], "correctIndex": 1, "id": "bkB1-131"}, {"type": "mcq", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Escolha a opção correta.", "explain": "First conditional: depois de \"if\" usamos presente, não \"will\".", "prompt": "I'll lend you my umbrella if you ___ it back tomorrow.", "options": ["bring", "will bring", "would bring", "brought"], "correctIndex": 0, "id": "bkB1-132"}, {"type": "gaps", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Complete com o second conditional.", "explain": "Situação imaginária: if + passado (lost, didn't have) e would/could + verbo base na outra parte.", "prompt": "A: What ___ you do if you lost your passport abroad?\nB: I ___ (go) to the Brazilian embassy.\nA: And if you ___ (not / have) any money?\nB: I ___ (call) my parents.", "answers": [["would", "could"], ["would go", "could go"], ["didn't have", "did not have"], ["would call", "could call"]], "id": "bkB1-133"}, {"type": "gaps", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Complete com o first conditional.", "explain": "Depois de if/unless usamos presente (rains, is); na outra parte, will + verbo base.", "prompt": "Unless it ___ (rain), we'll have lunch in the garden. If it ___ (be) too hot, we ___ (sit) under the mango tree.", "answers": [["rains"], ["is"], ["will sit", "can sit"]], "id": "bkB1-134"}, {"type": "choose", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Escolha a forma correta.", "explain": "Second conditional: if + were (passado) e would + verbo para situação imaginária.", "prompt": "If I [were*/am] taller, I [would play*/will play] volleyball professionally.", "id": "bkB1-135"}, {"type": "choose", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Escolha a forma correta.", "explain": "Zero conditional (verdade geral): presente nas duas partes.", "prompt": "Plants [die*/would die] if they [don't get*/wouldn't get] enough water.", "id": "bkB1-136"}, {"type": "error", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Encontre o erro e corrija.", "explain": "No first conditional não usamos \"will\" na parte do if: If he calls.", "sentence": "If he will call me, I'll tell him the news.", "wrong": "will call", "fix": ["calls"], "id": "bkB1-137"}, {"type": "error", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Encontre o erro e corrija.", "explain": "Second conditional: if + passado (had) pede would/could na outra parte, não will.", "sentence": "If we had a bigger kitchen, we will cook more at home.", "wrong": "will", "fix": ["would", "could"], "id": "bkB1-138"}, {"type": "rewrite", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Reescreva usando o second conditional.", "explain": "Situação irreal no presente: If + passado (spoke), could/would + verbo base.", "prompt": "She doesn't speak English, so she can't get the job.", "start": "If she", "accept": ["If she spoke English, she could get the job.", "If she spoke English, she would get the job.", "If she spoke English, she would be able to get the job.", "If she could speak English, she could get the job.", "If she could speak English, she would get the job.", "If she spoke English, she'd get the job.", "If she spoke English, she'd be able to get the job.", "If she could speak English, she'd get the job."], "id": "bkB1-139"}, {"type": "rewrite", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Reescreva usando o first conditional.", "explain": "Condição real no futuro: If + presente (don't hurry), will + verbo base.", "prompt": "Hurry up, or you'll miss the train.", "start": "If you don't", "accept": ["If you don't hurry up, you'll miss the train.", "If you don't hurry, you'll miss the train.", "If you don't hurry up, you will miss the train.", "If you don't hurry, you will miss the train."], "id": "bkB1-140"}, {"type": "order", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Zero conditional para fato geral: if + presente, presente.", "words": ["If", "you", "mix", "blue", "and", "yellow", "you", "get", "green"], "alt": ["You get green if you mix blue and yellow"], "id": "bkB1-141"}, {"type": "order", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta no second conditional: Would you + verbo ... if + passado.", "words": ["Would", "you", "accept", "the", "job", "if", "they", "offered", "it", "to", "you"], "alt": ["If they offered it to you would you accept the job", "If they offered the job to you would you accept it", "Would you accept it if they offered the job to you"], "id": "bkB1-142"}, {"type": "match", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Ligue as partes para formar frases.", "explain": "Zero = fato (turns); first = possível (I'll complain); second = imaginário (would fly); oferta = presente.", "left": ["If you're hungry,", "If I had wings,", "If you freeze water,", "If the bus is late again,"], "right": ["it turns into ice.", "I'll complain to the company.", "there's some lasagna in the fridge.", "I would fly to the beach every day."], "correctMap": [2, 3, 0, 1], "id": "bkB1-143"}, {"type": "sort", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Classifique cada frase pelo tipo de condicional.", "explain": "Zero: presente/presente. First: presente/will. Second: passado/would.", "prompt": "Which conditional is each sentence: zero, first or second?", "groups": ["Zero Conditional", "First Conditional", "Second Conditional"], "items": [{"w": "If you drop an egg, it breaks.", "g": 0}, {"w": "Metal expands if you heat it.", "g": 0}, {"w": "If Ana gets the visa, she'll travel in May.", "g": 1}, {"w": "We'll miss the flight if we don't leave now.", "g": 1}, {"w": "If I knew his number, I'd call him.", "g": 2}, {"w": "She would be happier if she lived near the sea.", "g": 2}], "id": "bkB1-144"}, {"type": "odd", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Qual frase NÃO está correta?", "explain": "Não usamos \"would\" na parte do if: If I knew, I'd tell you.", "prompt": "Which sentence is NOT correct?", "options": ["If I were you, I'd rest.", "If it rains, we'll stay home.", "If I would know, I'd tell you.", "If you touch fire, you get burned."], "correctIndex": 2, "id": "bkB1-145"}, {"type": "blank", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Complete com a forma correta do verbo.", "explain": "First conditional: depois de if usamos presente simples (wins), com \"s\" para terceira pessoa.", "prompt": "If my team ___ (win) the championship this Sunday, I'll be so happy!", "accept": ["wins"], "id": "bkB1-146"}, {"type": "tf", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Neve é rara; Laura queria mais férias (não tem); ela visitará Portugal se economizar.", "text": "Laura works at a hotel in Gramado. If guests arrive before 2 p.m., they can leave their bags at the reception. If it snows, which is very rare, the hotel prepares hot chocolate for everyone. Laura often says, \"If I had more vacation days, I would travel to Japan.\" If she saves enough money this year, she will visit her sister in Portugal.", "items": [{"s": "Guests who arrive early can leave their bags.", "a": true}, {"s": "It often snows in Gramado.", "a": false}, {"s": "Laura has a lot of vacation days.", "a": false}, {"s": "Laura may visit Portugal this year.", "a": true}], "id": "bkB1-147"}, {"type": "reading", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Leia o texto e responda às perguntas.", "explain": "As respostas estão nas frases com if: sessão com treinador, multa de R$20 e limite quando lotado.", "text": "GYM RULES\nIf you are a new member, please book a free session with a trainer. If you use a machine, clean it after you finish. Towels are free, but if you lose one, you will pay R$20. If the gym is very crowded, please don't use the same machine for more than 20 minutes. If you have any questions, talk to the staff at the front desk.", "questions": [{"q": "What should new members do?", "options": ["Book a session with a trainer.", "Pay R$20.", "Bring their own towels."], "correctIndex": 0}, {"q": "What happens if you lose a towel?", "options": ["You can't come back.", "You pay R$20.", "You get a new one for free."], "correctIndex": 1}, {"q": "When is there a time limit on machines?", "options": ["When the gym is crowded.", "On weekends.", "For new members."], "correctIndex": 0}], "id": "bkB1-148"}, {"type": "dorder", "level": "B1", "topic": "Condicionais (0, 1, 2)", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Convite → condição (if I finish) → pergunta sobre a outra possibilidade → consequência → oferta.", "lines": ["A: Are you coming to the beach with us on Saturday?", "B: Maybe. If I finish my project on Friday, I'll go.", "A: And if you don't finish it?", "B: Then I'll have to work all weekend, unfortunately.", "A: Well, if you need help, just call me."], "id": "bkB1-149"}, {"type": "mcq", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Escolha a opção correta.", "explain": "Como sujeito da frase, usamos o gerúndio (-ing): Swimming is...", "prompt": "___ is good for your back.", "options": ["Swim", "Swimming", "To swimming", "Swims"], "correctIndex": 1, "id": "bkB1-150"}, {"type": "mcq", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Escolha a opção correta.", "explain": "\"Afford\" é seguido de to + verbo: can't afford to buy.", "prompt": "Marcos can't afford ___ a new car this year.", "options": ["buying", "to buy", "buy", "bought"], "correctIndex": 1, "id": "bkB1-151"}, {"type": "mcq", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Escolha a opção correta.", "explain": "\"Interested in\": depois de preposição usamos -ing.", "prompt": "Are you interested ___ a course in Canada?", "options": ["to take", "in taking", "in take", "for taking"], "correctIndex": 1, "id": "bkB1-152"}, {"type": "gaps", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Complete com -ing ou to + verbo.", "explain": "\"Suggest\" é seguido de -ing; \"agree\" é seguido de to + verbo.", "prompt": "My boss suggested ___ (have) the meeting online, and everyone agreed ___ (start) at nine.", "answers": [["having"], ["to start"]], "id": "bkB1-153"}, {"type": "gaps", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Complete com -ing ou to + verbo.", "explain": "\"Remember + -ing\" = lembrar de algo já feito; \"forget to\" = esquecer de fazer algo.", "prompt": "A: Do you remember ___ (lock) the door when we left?\nB: Yes, I do. And don't forget ___ (feed) the cat tonight.", "answers": [["locking"], ["to feed"]], "id": "bkB1-154"}, {"type": "choose", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Escolha a forma correta.", "explain": "\"Keep\" é seguido de -ing; \"ask someone\" é seguido de to + verbo.", "prompt": "Thiago keeps [to check/checking*] his phone during class, so the teacher asked him [to stop*/stopping].", "id": "bkB1-155"}, {"type": "choose", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Escolha a forma correta.", "explain": "Em \"be used to\", o \"to\" é preposição: vem -ing. \"Mind\" também pede -ing.", "prompt": "I'm used to [wake/waking*] up early, and I don't mind [to work/working*] late either.", "id": "bkB1-156"}, {"type": "error", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Encontre o erro e corrija.", "explain": "Depois de preposição (about) usamos -ing: thinking about changing.", "sentence": "I'm thinking about to change jobs.", "wrong": "to change", "fix": ["changing"], "id": "bkB1-157"}, {"type": "error", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Encontre o erro e corrija.", "explain": "\"Promise\" é seguido de to + verbo: promised to call.", "sentence": "Paulo promised calling me after the game.", "wrong": "calling", "fix": ["to call"], "id": "bkB1-158"}, {"type": "rewrite", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Reescreva começando com o gerúndio.", "explain": "O gerúndio pode ser sujeito da frase: Learning Chinese is difficult.", "prompt": "It is difficult to learn Chinese.", "start": "Learning", "accept": ["Learning Chinese is difficult."], "id": "bkB1-159"}, {"type": "rewrite", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Reescreva usando stop + verbo.", "explain": "\"Stop + -ing\" = parar de fazer algo.", "prompt": "He doesn't eat sugar anymore.", "start": "He has stopped", "accept": ["He has stopped eating sugar."], "id": "bkB1-160"}, {"type": "order", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"Imagine\" é seguido de -ing: imagine living.", "words": ["I", "can't", "imagine", "living", "without", "my", "phone"], "id": "bkB1-161"}, {"type": "order", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"Hope\" é seguido de to + verbo: hope to visit.", "words": ["They", "hope", "to", "visit", "Fernando", "de", "Noronha", "next", "year"], "alt": ["Next year they hope to visit Fernando de Noronha"], "id": "bkB1-162"}, {"type": "match", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Ligue cada frase ao seu significado.", "explain": "Stop + -ing = parar de; stop + to = parar para. Remember + -ing = lembrar do passado; remember to = lembrar de fazer.", "left": ["We stopped smoking.", "We stopped to smoke.", "I remember visiting Ouro Preto.", "Remember to visit Ouro Preto."], "right": ["Lembre-se de visitar Ouro Preto.", "Paramos para fumar.", "Paramos de fumar.", "Lembro que visitei Ouro Preto."], "correctMap": [2, 1, 3, 0], "id": "bkB1-163"}, {"type": "sort", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Separe os verbos: seguidos de -ing ou de to + verbo.", "explain": "Keep, suggest, practice e consider pedem -ing; manage, offer, seem e learn pedem to + verbo.", "prompt": "Which verbs are followed by -ing and which by to + verb?", "groups": ["+ -ing", "+ to + verbo"], "items": [{"w": "keep", "g": 0}, {"w": "suggest", "g": 0}, {"w": "practice", "g": 0}, {"w": "consider", "g": 0}, {"w": "manage", "g": 1}, {"w": "offer", "g": 1}, {"w": "seem", "g": 1}, {"w": "learn", "g": 1}], "id": "bkB1-164"}, {"type": "odd", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Qual verbo NÃO costuma ser seguido de -ing?", "explain": "\"Deserve\" pede to + verbo (deserve to win); os outros pedem -ing.", "prompt": "Which verb is NOT usually followed by -ing?", "options": ["finish", "keep", "deserve", "practice"], "correctIndex": 2, "id": "bkB1-165"}, {"type": "blank", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Complete com a forma correta do verbo.", "explain": "A expressão \"it's worth\" é seguida de -ing.", "prompt": "It's worth ___ (visit) the old town in Paraty.", "accept": ["visiting"], "id": "bkB1-166"}, {"type": "tf", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Ela odiava cozinhar; queimava o arroz no início; aprendeu a fazer pão; ainda não abriu o café.", "text": "Beatriz used to hate cooking, but last year she decided to take a cooking class in São Paulo. At first, she kept burning the rice! Now she enjoys trying new recipes, and she has learned to make bread. She wants to open a small café one day, but she can't afford to do it yet.", "items": [{"s": "Beatriz always loved cooking.", "a": false}, {"s": "She had problems with rice at the beginning.", "a": true}, {"s": "She has learned to make bread.", "a": true}, {"s": "She has already opened a café.", "a": false}], "id": "bkB1-167"}, {"type": "reading", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Leia o texto e responda às perguntas.", "explain": "O clube ajuda iniciantes, recomenda levar água, e para participar basta responder ao e-mail.", "text": "Hi everyone,\nI'm writing to invite you to try our new running club! We meet every Saturday at 7 a.m. in Ibirapuera Park. Don't worry about being slow. Our goal is to help beginners start running without getting hurt. We recommend bringing water and wearing comfortable shoes. If you'd like to join, reply to this email. We look forward to meeting you!\nCarol", "questions": [{"q": "Who is the club for?", "options": ["Professional runners", "Beginners", "Only children"], "correctIndex": 1}, {"q": "What does Carol recommend?", "options": ["Bringing water.", "Running fast.", "Arriving at 6 a.m."], "correctIndex": 0}, {"q": "How can people join?", "options": ["By calling Carol.", "By replying to the email.", "By going to the park on Sunday."], "correctIndex": 1}], "id": "bkB1-168"}, {"type": "dorder", "level": "B1", "topic": "Gerúndio x Infinitivo", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Convite → aceite e pergunta do horário → horário e pergunta sobre comida → resposta → plano.", "lines": ["A: Would you like to come for dinner on Friday?", "B: I'd love to! What time?", "A: Around eight. Do you mind eating spicy food?", "B: Not at all. I love trying new things.", "A: Great! I'm planning to make a Thai curry."], "id": "bkB1-169"}, {"type": "mcq", "level": "B1", "topic": "Voz Passiva", "instruction": "Escolha a opção correta.", "explain": "\"By the governor\" mostra quem faz a ação: precisamos da passiva no futuro (will be opened).", "prompt": "The new hospital ___ by the governor next week.", "options": ["will be opened", "will open", "opens", "is opening"], "correctIndex": 0, "id": "bkB1-170"}, {"type": "mcq", "level": "B1", "topic": "Voz Passiva", "instruction": "Escolha a opção correta.", "explain": "Passiva no present continuous (at the moment): is being + particípio.", "prompt": "My car ___ at the moment, so I'm taking the bus.", "options": ["is being repaired", "is repairing", "has repaired", "repairs"], "correctIndex": 0, "id": "bkB1-171"}, {"type": "mcq", "level": "B1", "topic": "Voz Passiva", "instruction": "Escolha a opção correta.", "explain": "Na voz passiva, quem faz a ação é introduzido por \"by\".", "prompt": "The Mona Lisa was painted ___ Leonardo da Vinci.", "options": ["from", "of", "by", "with"], "correctIndex": 2, "id": "bkB1-172"}, {"type": "gaps", "level": "B1", "topic": "Voz Passiva", "instruction": "Complete com a voz passiva no presente.", "explain": "Passiva no presente: is + particípio (made, served); o advérbio fica depois de \"is\".", "prompt": "Feijoada ___ (make) with black beans and pork. It ___ (usually / serve) with rice, collard greens and orange slices.", "answers": [["is made"], ["is usually served"]], "id": "bkB1-173"}, {"type": "gaps", "level": "B1", "topic": "Voz Passiva", "instruction": "Complete o texto com as expressões do quadro.", "explain": "Cada tempo tem sua passiva: was built (passado), are cleaned (presente), will be installed (futuro), hasn't been (present perfect).", "prompt": "Our school has changed a lot. Last year, a new library ___. Now, the classrooms ___ every week by a team of students, and new computers ___ next month. The old gym ___ yet, but it will be soon.", "bank": ["was built", "are cleaned", "will be installed", "hasn't been renovated", "built", "clean"], "answers": [["was built"], ["are cleaned"], ["will be installed"], ["hasn't been renovated", "has not been renovated"]], "id": "bkB1-174"}, {"type": "choose", "level": "B1", "topic": "Voz Passiva", "instruction": "Escolha a forma correta.", "explain": "O ladrão sofreu a ação: was caught. \"Phones\" é plural: were returned.", "prompt": "The thief [was caught*/caught] by the police, and the stolen phones [were*/was] returned to the owners.", "id": "bkB1-175"}, {"type": "choose", "level": "B1", "topic": "Voz Passiva", "instruction": "Escolha a forma correta.", "explain": "Os vencedores e os prêmios recebem a ação: passiva no futuro (will be + particípio).", "prompt": "The winners [will be chosen*/will choose] by the public, and the prizes [will be given*/will give] on Friday.", "id": "bkB1-176"}, {"type": "error", "level": "B1", "topic": "Voz Passiva", "instruction": "Encontre o erro e corrija.", "explain": "Na passiva usamos o particípio: written, não o passado \"wrote\".", "sentence": "The letter was wrote by my grandfather.", "wrong": "wrote", "fix": ["written"], "id": "bkB1-177"}, {"type": "error", "level": "B1", "topic": "Voz Passiva", "instruction": "Encontre o erro e corrija.", "explain": "\"Cookies\" é plural, então o auxiliar da passiva é \"were\".", "sentence": "These cookies was baked by my aunt this morning.", "wrong": "was", "fix": ["were"], "id": "bkB1-178"}, {"type": "rewrite", "level": "B1", "topic": "Voz Passiva", "instruction": "Passe para a voz passiva.", "explain": "Presente simples na passiva: are + particípio (are prepared); o agente com \"by\" é opcional.", "prompt": "The chef prepares the desserts every morning.", "start": "The desserts", "accept": ["The desserts are prepared every morning.", "The desserts are prepared by the chef every morning.", "The desserts are prepared every morning by the chef."], "id": "bkB1-179"}, {"type": "rewrite", "level": "B1", "topic": "Voz Passiva", "instruction": "Passe para a voz passiva (present continuous).", "explain": "Present continuous na passiva: is being + particípio.", "prompt": "They are building a new stadium in our city.", "start": "A new stadium", "accept": ["A new stadium is being built in our city."], "id": "bkB1-180"}, {"type": "order", "level": "B1", "topic": "Voz Passiva", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Passiva com modal: can be + particípio.", "words": ["The", "tickets", "can", "be", "bought", "online"], "id": "bkB1-181"}, {"type": "order", "level": "B1", "topic": "Voz Passiva", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta na passiva no passado: When + was + sujeito + particípio.", "words": ["When", "was", "this", "church", "built"], "id": "bkB1-182"}, {"type": "match", "level": "B1", "topic": "Voz Passiva", "instruction": "Ligue as partes para formar frases.", "explain": "Singular/plural e o tempo verbal ajudam: is harvested, was launched, are sold, were held.", "left": ["Açaí", "The first iPhone", "Many Brazilian soap operas", "The 2016 Olympic Games"], "right": ["were held in Rio de Janeiro.", "is harvested in the Amazon.", "was launched in 2007.", "are sold to other countries."], "correctMap": [1, 2, 3, 0], "id": "bkB1-183"}, {"type": "sort", "level": "B1", "topic": "Voz Passiva", "instruction": "Classifique as frases: voz ativa ou passiva.", "explain": "Passiva: be + particípio, o sujeito recebe a ação. Ativa: o sujeito faz a ação.", "prompt": "Is each sentence active or passive?", "groups": ["Voz ativa", "Voz passiva"], "items": [{"w": "The kids broke the window.", "g": 0}, {"w": "The window was broken.", "g": 1}, {"w": "Someone has taken my pen.", "g": 0}, {"w": "My pen has been taken.", "g": 1}, {"w": "They will send the invitations.", "g": 0}, {"w": "The invitations will be sent.", "g": 1}], "id": "bkB1-184"}, {"type": "odd", "level": "B1", "topic": "Voz Passiva", "instruction": "Qual frase está na voz passiva?", "explain": "Só \"was won by\" tem be + particípio com o sujeito recebendo a ação; as outras são ativas.", "prompt": "Which sentence IS in the passive voice?", "options": ["The team won the game.", "The game was won by the home team.", "The fans were singing loudly.", "The coach has left the stadium."], "correctIndex": 1, "id": "bkB1-185"}, {"type": "blank", "level": "B1", "topic": "Voz Passiva", "instruction": "Complete com a voz passiva no passado.", "explain": "\"Results\" é plural e \"yesterday\" pede passado: were sent.", "prompt": "The results ___ (send) to all students by email yesterday.", "accept": ["were sent"], "id": "bkB1-186"}, {"type": "tf", "level": "B1", "topic": "Voz Passiva", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Foram criadas no Brasil, usadas por trabalhadores, vendidas em mais de 100 países e produzidas aos milhões.", "text": "Havaianas flip-flops were created in Brazil in 1962. The design was inspired by Japanese sandals called zori. At first, they were worn mostly by workers because they were cheap. Today, they are sold in more than 100 countries and are used by celebrities. Millions of pairs are produced every year.", "items": [{"s": "Havaianas were created in Japan.", "a": false}, {"s": "Workers used them because they were cheap.", "a": true}, {"s": "They are only sold in Brazil.", "a": false}, {"s": "Millions of pairs are made every year.", "a": true}], "id": "bkB1-187"}, {"type": "reading", "level": "B1", "topic": "Voz Passiva", "instruction": "Leia o texto e responda às perguntas.", "explain": "O texto explica: canos sendo trocados, usar a escada, contêineres instalados na semana passada.", "text": "NOTICE TO RESIDENTS\nThe building's water will be turned off on Tuesday from 9 a.m. to 3 p.m. because the pipes are being replaced. The elevator will also be checked on the same day, so residents are asked to use the stairs. All trash must be taken to the new containers, which were installed last week near the garage. We apologize for the inconvenience.\nThe Management", "questions": [{"q": "Why will the water be turned off?", "options": ["The pipes are being replaced.", "The building is being painted.", "The garage is closed."], "correctIndex": 0}, {"q": "What are residents asked to do?", "options": ["Use the stairs.", "Stay at home.", "Install containers."], "correctIndex": 0}, {"q": "When were the new containers installed?", "options": ["On Tuesday", "Last week", "Today"], "correctIndex": 1}], "id": "bkB1-188"}, {"type": "dorder", "level": "B1", "topic": "Voz Passiva", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Cliente pergunta → atendente pede o nome → cliente se identifica → informação do conserto → pagamento.", "lines": ["A: Excuse me, has my laptop been fixed yet?", "B: Let me check. What's your name, please?", "A: Carlos Mendes. I left it here on Monday.", "B: Yes, it was repaired this morning. The screen was replaced.", "A: Great! How much do I owe you?"], "id": "bkB1-189"}, {"type": "mcq", "level": "B1", "topic": "Relative Clauses", "instruction": "Escolha a opção correta.", "explain": "\"Whose\" indica posse: o carro do rapaz foi roubado.", "prompt": "The guy ___ car was stolen called the police.", "options": ["who", "whose", "which", "where"], "correctIndex": 1, "id": "bkB1-190"}, {"type": "mcq", "level": "B1", "topic": "Relative Clauses", "instruction": "Escolha a opção correta.", "explain": "Para tempo (the day) usamos \"when\".", "prompt": "Do you remember the day ___ we met?", "options": ["which", "who", "when", "whose"], "correctIndex": 2, "id": "bkB1-191"}, {"type": "mcq", "level": "B1", "topic": "Relative Clauses", "instruction": "Escolha a opção correta.", "explain": "Com vírgulas (informação extra) não se usa \"that\"; para lugar/coisa como sujeito usamos \"which\".", "prompt": "Rio, ___ is famous for its beaches, gets millions of tourists every year.", "options": ["that", "which", "where", "who"], "correctIndex": 1, "id": "bkB1-192"}, {"type": "gaps", "level": "B1", "topic": "Relative Clauses", "instruction": "Complete com o pronome relativo adequado.", "explain": "Para coisas usamos which/that; para pessoas, who/that.", "prompt": "The app ___ I use for studying is free. The teacher ___ recommended it is from Chile.", "answers": [["that", "which"], ["who", "that"]], "id": "bkB1-193"}, {"type": "gaps", "level": "B1", "topic": "Relative Clauses", "instruction": "Complete com o pronome relativo adequado.", "explain": "\"Where\" para lugares onde algo acontece; \"that/which\" para a igreja como sujeito da oração.", "prompt": "Salvador is the city ___ my parents grew up. It's also the place ___ they got married, in a church ___ is over 300 years old.", "answers": [["where", "in which"], ["where", "in which"], ["that", "which"]], "id": "bkB1-194"}, {"type": "choose", "level": "B1", "topic": "Relative Clauses", "instruction": "Escolha o pronome correto.", "explain": "Não usamos \"what\" como pronome relativo (erro comum de \"o que\"); para pessoas, \"who\".", "prompt": "The movie [what/that*] we saw last night had an actor [who*/which] was born in Brazil.", "id": "bkB1-195"}, {"type": "choose", "level": "B1", "topic": "Relative Clauses", "instruction": "Escolha o pronome correto.", "explain": "Com vírgulas usamos \"who\", não \"that\"; \"where\" para o lugar onde nasci.", "prompt": "My neighbor, [who*/that] is a nurse, works at the hospital [where*/which] I was born.", "id": "bkB1-196"}, {"type": "error", "level": "B1", "topic": "Relative Clauses", "instruction": "Encontre o erro e corrija.", "explain": "\"What\" não funciona como pronome relativo depois de substantivo: the book that/which.", "sentence": "The book what I'm reading is amazing.", "wrong": "what", "fix": ["that", "which"], "id": "bkB1-197"}, {"type": "error", "level": "B1", "topic": "Relative Clauses", "instruction": "Encontre o erro e corrija.", "explain": "Para posse usamos \"whose\", não \"who his\".", "sentence": "That's the student who his mother is my dentist.", "wrong": "who his", "fix": ["whose"], "id": "bkB1-198"}, {"type": "rewrite", "level": "B1", "topic": "Relative Clauses", "instruction": "Una as frases com um pronome relativo.", "explain": "Para lugar usamos \"where\" (ou \"which/that ... in\").", "prompt": "This is the café. We had breakfast there.", "start": "This is the café", "accept": ["This is the café where we had breakfast.", "This is the café in which we had breakfast.", "This is the café that we had breakfast in.", "This is the café which we had breakfast in.", "This is the café we had breakfast in."], "id": "bkB1-199"}, {"type": "rewrite", "level": "B1", "topic": "Relative Clauses", "instruction": "Una as frases usando \"who\" entre vírgulas.", "explain": "Informação extra sobre pessoa: vírgulas + who.", "prompt": "My uncle lives in Canada. He is a chef.", "start": "My uncle, who", "accept": ["My uncle, who lives in Canada, is a chef.", "My uncle, who is a chef, lives in Canada."], "id": "bkB1-200"}, {"type": "order", "level": "B1", "topic": "Relative Clauses", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"Who\" liga a pessoa (someone) à ação que ela pode fazer.", "words": ["I", "need", "someone", "who", "can", "fix", "my", "computer"], "id": "bkB1-201"}, {"type": "order", "level": "B1", "topic": "Relative Clauses", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "\"That\" introduz a informação sobre a bolsa: the bag that you lost.", "words": ["Is", "this", "the", "bag", "that", "you", "lost"], "id": "bkB1-202"}, {"type": "match", "level": "B1", "topic": "Relative Clauses", "instruction": "Ligue as partes para formar frases.", "explain": "Who = pessoa; when = tempo; which = coisa; whose = posse.", "left": ["Do you know anyone", "I'll never forget the summer", "We stayed at a hotel", "That's the singer"], "right": ["whose songs are all about Bahia.", "when we drove to Patagonia.", "who speaks Japanese?", "which had a rooftop pool."], "correctMap": [2, 1, 3, 0], "id": "bkB1-203"}, {"type": "sort", "level": "B1", "topic": "Relative Clauses", "instruction": "Classifique pelo pronome relativo que completa a expressão.", "explain": "Who para pessoas, which para coisas, whose para posse.", "prompt": "Which relative pronoun completes each phrase: who, which or whose?", "groups": ["who", "which", "whose"], "items": [{"w": "the nurse ___ took care of me", "g": 0}, {"w": "the bus ___ goes to the airport", "g": 1}, {"w": "the boy ___ bike is red", "g": 2}, {"w": "the students ___ passed the exam", "g": 0}, {"w": "the recipe ___ my grandma created", "g": 1}, {"w": "the company ___ CEO resigned", "g": 2}], "id": "bkB1-204"}, {"type": "odd", "level": "B1", "topic": "Relative Clauses", "instruction": "Qual frase NÃO está correta?", "explain": "Para pessoas usamos who/that, não which: the girl who sits...", "prompt": "Which relative clause is NOT correct?", "options": ["The man who called you is here.", "The laptop which I bought is fast.", "The girl which sits next to me is funny.", "The town where I live is small."], "correctIndex": 2, "id": "bkB1-205"}, {"type": "blank", "level": "B1", "topic": "Relative Clauses", "instruction": "Complete com o pronome relativo.", "explain": "\"Whose\" indica posse: a aula do professor.", "prompt": "Is that the teacher ___ class you enjoyed so much?", "accept": ["whose"], "id": "bkB1-206"}, {"type": "tf", "level": "B1", "topic": "Relative Clauses", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O bairro é famoso pela arte de rua; o Beco é todo pintado; os bares ficam abertos até tarde.", "text": "Vila Madalena is a neighborhood in São Paulo which is famous for its street art. Beco do Batman, where artists have painted almost every wall, is its most popular spot. Many people who visit the area also go to the bars that stay open late. Juliana, whose apartment is near the main square, says the weekends are noisy but fun.", "items": [{"s": "Vila Madalena is known for street art.", "a": true}, {"s": "Beco do Batman has very few paintings.", "a": false}, {"s": "The bars close early.", "a": false}, {"s": "Juliana lives near the main square.", "a": true}], "id": "bkB1-207"}, {"type": "reading", "level": "B1", "topic": "Relative Clauses", "instruction": "Leia o texto e responda às perguntas.", "explain": "O dono mora no primeiro andar, o quarto pega sol de manhã e a janela da cozinha não abre.", "text": "Hi Matheus,\nThe apartment that you asked about is still available. It's on a quiet street where there are lots of trees. The owner, who lives on the first floor, is very friendly. The bedroom, which faces the garden, gets sun in the morning. The only problem is the kitchen, whose window doesn't open. Let me know if you want to see it.\nRenata", "questions": [{"q": "Where does the owner live?", "options": ["On the first floor", "In another city", "Next to the park"], "correctIndex": 0}, {"q": "What is special about the bedroom?", "options": ["It is very big.", "It gets morning sun.", "It has two windows."], "correctIndex": 1}, {"q": "What is the problem with the kitchen?", "options": ["It is too small.", "The window doesn't open.", "It is on the street."], "correctIndex": 1}], "id": "bkB1-208"}, {"type": "dorder", "level": "B1", "topic": "Relative Clauses", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Pergunta sobre a mulher → identificação (whose son) → a banda (that) → o festival (where) → lembrança.", "lines": ["A: Who's the woman who is talking to your dad?", "B: That's Dona Lúcia, the neighbor whose son plays in a band.", "A: Oh, the band that played at the festival?", "B: Exactly! The festival where we first met.", "A: I remember! That was a great night."], "id": "bkB1-209"}, {"type": "mcq", "level": "B1", "topic": "Tag Questions", "instruction": "Escolha a opção correta.", "explain": "Com \"there is\" a tag repete \"there\": isn't there?", "prompt": "There's a pharmacy near here, ___?", "options": ["isn't it", "isn't there", "doesn't it", "is there"], "correctIndex": 1, "id": "bkB1-210"}, {"type": "mcq", "level": "B1", "topic": "Tag Questions", "instruction": "Escolha a opção correta.", "explain": "Frase afirmativa com \"have\" (present perfect) → tag negativa com haven't.", "prompt": "You've finished the exercise, ___?", "options": ["haven't you", "don't you", "didn't you", "have you"], "correctIndex": 0, "id": "bkB1-211"}, {"type": "mcq", "level": "B1", "topic": "Tag Questions", "instruction": "Escolha a opção correta.", "explain": "\"Everyone\" usa \"they\" na tag; verbo no passado afirmativo → didn't they.", "prompt": "Everyone loved the show, ___?", "options": ["didn't they", "didn't he", "weren't they", "did they"], "correctIndex": 0, "id": "bkB1-212"}, {"type": "gaps", "level": "B1", "topic": "Tag Questions", "instruction": "Complete com a tag question correta.", "explain": "A tag usa o mesmo auxiliar com polaridade oposta: leaves → doesn't it; should → shouldn't; won't → will.", "prompt": "A: The flight leaves at six, ___?\nB: Yes. We should leave home early, ___?\nA: Definitely. You won't forget the passports, ___?", "answers": [["doesn't it"], ["shouldn't we"], ["will you"]], "id": "bkB1-213"}, {"type": "gaps", "level": "B1", "topic": "Tag Questions", "instruction": "Complete com a tag question correta.", "explain": "Weren't → were you; was → wasn't it / wasn't he.", "prompt": "Marcos: You weren't at the party, ___?\nLia: No, I had to work. It was fun, ___?\nMarcos: It was great! Your brother was there, ___?", "answers": [["were you"], ["wasn't it"], ["wasn't he"]], "id": "bkB1-214"}, {"type": "choose", "level": "B1", "topic": "Tag Questions", "instruction": "Escolha a tag correta.", "explain": "Com \"I'm\" a tag é \"aren't I\"; no imperativo usamos \"will you\".", "prompt": "I'm your best friend, [aren't*/amn't/isn't] I? Close the door, [will*/do/are] you?", "id": "bkB1-215"}, {"type": "choose", "level": "B1", "topic": "Tag Questions", "instruction": "Escolha a tag correta.", "explain": "\"Hardly ever\" e \"never\" têm sentido negativo, então a tag é positiva.", "prompt": "She hardly ever complains, [does*/doesn't] she? They've never been to Europe, [have*/haven't] they?", "id": "bkB1-216"}, {"type": "error", "level": "B1", "topic": "Tag Questions", "instruction": "Encontre o erro e corrija.", "explain": "A tag repete o sujeito como pronome: you → don't you.", "sentence": "You like soccer, don't it?", "wrong": "don't it", "fix": ["don't you"], "id": "bkB1-217"}, {"type": "error", "level": "B1", "topic": "Tag Questions", "instruction": "Encontre o erro e corrija.", "explain": "Em inglês não existe um \"né?\" fixo: parents are → aren't they.", "sentence": "Your parents are from Belém, isn't it?", "wrong": "isn't it", "fix": ["aren't they"], "id": "bkB1-218"}, {"type": "rewrite", "level": "B1", "topic": "Tag Questions", "instruction": "Adicione a tag question.", "explain": "Com \"has\" (posse) a tag usa \"doesn't she\" (também \"hasn't she\" no inglês britânico).", "prompt": "Your sister has two kids.", "start": "Your sister has two kids", "accept": ["Your sister has two kids, doesn't she?", "Your sister has two kids, hasn't she?"], "id": "bkB1-219"}, {"type": "rewrite", "level": "B1", "topic": "Tag Questions", "instruction": "Adicione a tag question.", "explain": "Frase negativa no passado (didn't) → tag positiva: did we?", "prompt": "We didn't pay for the coffee.", "start": "We didn't pay for the coffee", "accept": ["We didn't pay for the coffee, did we?"], "id": "bkB1-220"}, {"type": "order", "level": "B1", "topic": "Tag Questions", "instruction": "Ordene as palavras para formar uma frase com tag question.", "explain": "Frase negativa (wasn't) → tag positiva (was it).", "words": ["It", "wasn't", "your", "fault", "was", "it"], "alt": ["It was your fault wasn't it"], "id": "bkB1-221"}, {"type": "order", "level": "B1", "topic": "Tag Questions", "instruction": "Ordene as palavras para formar uma frase com tag question.", "explain": "Frase afirmativa com \"can\" → tag negativa \"can't you\".", "words": ["You", "can", "speak", "Spanish", "can't", "you"], "alt": ["You can't speak Spanish can you"], "id": "bkB1-222"}, {"type": "match", "level": "B1", "topic": "Tag Questions", "instruction": "Ligue cada frase à sua tag question.", "explain": "You'd like → wouldn't you; nothing → did it; convite no imperativo → won't you; she'll → won't she.", "left": ["You'd like some coffee,", "Nothing happened,", "Sit down,", "She'll call later,"], "right": ["won't she?", "did it?", "wouldn't you?", "won't you?"], "correctMap": [2, 1, 3, 0], "id": "bkB1-223"}, {"type": "sort", "level": "B1", "topic": "Tag Questions", "instruction": "Classifique cada frase pela tag que a completa.", "explain": "To be → isn't it; presente com outro verbo → doesn't it; passado → didn't it.", "prompt": "Which tag completes each sentence?", "groups": ["isn't it?", "doesn't it?", "didn't it?"], "items": [{"w": "The movie starts at nine, ...", "g": 1}, {"w": "It's your birthday today, ...", "g": 0}, {"w": "It rained a lot yesterday, ...", "g": 2}, {"w": "This bus goes downtown, ...", "g": 1}, {"w": "The traffic is terrible, ...", "g": 0}, {"w": "The meeting ended late, ...", "g": 2}], "id": "bkB1-224"}, {"type": "odd", "level": "B1", "topic": "Tag Questions", "instruction": "Qual tag question NÃO está correta?", "explain": "Com \"was\" a tag usa \"wasn't\": She was born in Recife, wasn't she?", "prompt": "Which sentence has the wrong tag?", "options": ["He's been here before, hasn't he?", "You should rest, shouldn't you?", "They could help us, couldn't they?", "She was born in Recife, didn't she?"], "correctIndex": 3, "id": "bkB1-225"}, {"type": "blank", "level": "B1", "topic": "Tag Questions", "instruction": "Complete com a tag question.", "explain": "\"Are getting\" (afirmativo, sujeito plural) → aren't they.", "prompt": "Ana and Bruno are getting married in May, ___?", "accept": ["aren't they"], "id": "bkB1-226"}, {"type": "tf", "level": "B1", "topic": "Tag Questions", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Paula acha o ônibus atrasado, não trouxe guarda-chuva e espera que não chova; o céu está escuro.", "text": "Tiago and Paula are waiting at the bus stop. \"The bus is late again, isn't it?\" says Paula. \"Yes. You didn't bring an umbrella, did you?\" asks Tiago. \"No, I didn't,\" she answers, \"but it won't rain, will it?\" Tiago looks at the dark sky and laughs.", "items": [{"s": "Paula thinks the bus is late.", "a": true}, {"s": "Paula brought an umbrella.", "a": false}, {"s": "Paula hopes it won't rain.", "a": true}, {"s": "The sky is clear.", "a": false}], "id": "bkB1-227"}, {"type": "reading", "level": "B1", "topic": "Tag Questions", "instruction": "Leia o texto e responda às perguntas.", "explain": "Rafa leva as bebidas, o churrasco começa ao meio-dia e a casa nova de Júlio fica perto da padaria.", "text": "Hey Rafa,\nYou're still coming to Júlio's barbecue on Sunday, aren't you? I told him you'd bring the drinks. You haven't forgotten, have you? It starts at noon, but most people will arrive later. By the way, you know Júlio's new address, don't you? It's Rua das Flores, 45, near the bakery.\nSee you there!\nCami", "questions": [{"q": "What should Rafa bring?", "options": ["Meat", "Drinks", "Dessert"], "correctIndex": 1}, {"q": "When does the barbecue start?", "options": ["At noon", "In the evening", "On Saturday"], "correctIndex": 0}, {"q": "Where is Júlio's new home?", "options": ["Near the bakery", "Near the beach", "Next to Cami's house"], "correctIndex": 0}], "id": "bkB1-228"}, {"type": "dorder", "level": "B1", "topic": "Tag Questions", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Pergunta de confirmação → resposta → outra tag sobre a região → confirmação e nova tag → resposta final.", "lines": ["A: You're Brazilian, aren't you?", "B: Yes, I am. How did you know?", "A: Your accent! You're from the South, aren't you?", "B: That's right, from Porto Alegre. You've been there, haven't you?", "A: No, never. But I'd love to go."], "id": "bkB1-229"}, {"type": "mcq", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Escolha a opção correta.", "explain": "Temos uma evidência forte (ele disse que viria às sete), então deduzimos com \"must\".", "prompt": "Someone is knocking. It ___ be Diego. He said he'd come at seven, and it's seven now.", "options": ["must", "can't", "used to", "mustn't"], "correctIndex": 0, "id": "bkB1-230"}, {"type": "mcq", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Escolha a opção correta.", "explain": "Hábito/estado do passado que mudou: used to + verbo base.", "prompt": "Juliana ___ have long hair, but now it is very short.", "options": ["used to", "use to", "is used to", "was use to"], "correctIndex": 0, "id": "bkB1-231"}, {"type": "mcq", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Escolha a opção correta.", "explain": "\"Be used to\" + substantivo/pronome = estar acostumado: I'm used to it.", "prompt": "I didn't like the cold at first, but now I'm ___ it.", "options": ["used to", "use to", "using to", "use"], "correctIndex": 0, "id": "bkB1-232"}, {"type": "gaps", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Complete usando used to (afirmativa, negativa ou pergunta).", "explain": "Negativa e pergunta usam did + \"use to\" (sem d); afirmativa usa \"used to\".", "prompt": "When my dad was young, he ___ (not / have) a car. He ___ (ride) a bike everywhere.\n___ you ___ (walk) to school when you were a kid?", "answers": [["didn't use to have", "did not use to have"], ["used to ride"], ["Did"], ["use to walk"]], "id": "bkB1-233"}, {"type": "gaps", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Complete com a forma correta do verbo.", "explain": "Em \"be used to\" o \"to\" é preposição, então o verbo vem com -ing.", "prompt": "Moving to Canada was hard at first. I wasn't used to ___ (drive) in the snow. Now I'm used to ___ (wear) three layers of clothes!", "answers": [["driving"], ["wearing"]], "id": "bkB1-234"}, {"type": "choose", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Escolha a forma correta.", "explain": "\"Used to + verbo\" = hábito passado; \"be used to + -ing\" = estar acostumado.", "prompt": "My parents [used to*/are used to] live on a farm, so they [are used to*/used to] waking up at 5 a.m.", "id": "bkB1-235"}, {"type": "choose", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Escolha a forma correta.", "explain": "\"Must\" = certeza de que é verdade; \"can't\" = certeza de que não é.", "prompt": "You've been driving for ten hours, so you [must*/can't] be tired. And this [must/can't*] be our hotel: ours has a pool, and this one doesn't.", "id": "bkB1-236"}, {"type": "error", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Encontre o erro e corrija.", "explain": "Na afirmativa escrevemos \"used to\" (com d).", "sentence": "I use to play soccer when I was a child.", "wrong": "use to", "fix": ["used to"], "id": "bkB1-237"}, {"type": "error", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Encontre o erro e corrija.", "explain": "Dedução negativa usa \"can't\"; \"mustn't\" indica proibição.", "sentence": "She mustn't be at home; her car isn't in the garage.", "wrong": "mustn't", "fix": ["can't", "cannot", "couldn't"], "id": "bkB1-238"}, {"type": "rewrite", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Reescreva usando can't para dedução.", "explain": "Certeza de que algo não é verdade: can't + be.", "prompt": "I'm sure this isn't Maria's bag. Hers is red.", "start": "This", "accept": ["This can't be Maria's bag.", "This can't be Maria's.", "This cannot be Maria's bag.", "This cannot be Maria's."], "id": "bkB1-239"}, {"type": "rewrite", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Reescreva usando used to.", "explain": "Hábito do passado que não existe mais: used to + verbo base.", "prompt": "When I was a teenager, I played the drums, but I don't play anymore.", "start": "I used to", "accept": ["I used to play the drums.", "I used to play the drums when I was a teenager.", "I used to play the drums as a teenager."], "id": "bkB1-240"}, {"type": "order", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta com used to: Did + sujeito + use to + verbo.", "words": ["Did", "you", "use", "to", "have", "long", "hair"], "id": "bkB1-241"}, {"type": "order", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Dedução afirmativa: sujeito + must be + adjetivo.", "words": ["They", "must", "be", "very", "proud", "of", "their", "daughter"], "id": "bkB1-242"}, {"type": "match", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Ligue cada situação à dedução lógica.", "explain": "Cada evidência leva a uma conclusão: bocejo → sono; aliança → casado; mansão → rico; no escritório → não pode estar na praia.", "left": ["She's yawning all the time.", "He's wearing a wedding ring.", "Leo is at the office right now.", "They just bought a mansion."], "right": ["They must be rich.", "That can't be Leo at the beach.", "She must be sleepy.", "He must be married."], "correctMap": [2, 3, 1, 0], "id": "bkB1-243"}, {"type": "sort", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Qual forma completa cada frase?", "explain": "\"Used to + verbo\" para hábitos passados; \"be used to + -ing\" para estar acostumado.", "prompt": "Which form completes each sentence: used to or be used to?", "groups": ["used to (hábito passado)", "be used to (acostumado)"], "items": [{"w": "I ___ smoke, but I quit.", "g": 0}, {"w": "She ___ living alone now.", "g": 1}, {"w": "We ___ have a dog named Tupi.", "g": 0}, {"w": "He ___ working at night.", "g": 1}, {"w": "They ___ go to church every Sunday.", "g": 0}, {"w": "I ___ eating spicy food.", "g": 1}], "id": "bkB1-244"}, {"type": "odd", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Qual frase NÃO é uma dedução?", "explain": "\"Mustn't\" expressa proibição; as outras frases são deduções.", "prompt": "Which sentence is NOT a deduction?", "options": ["He must be tired.", "You mustn't smoke here.", "She can't be serious.", "They must be twins."], "correctIndex": 1, "id": "bkB1-245"}, {"type": "blank", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Complete com a forma correta.", "explain": "Situação do passado que mudou: there used to be.", "prompt": "There ___ (use to) be a cinema here, but now it's a pharmacy.", "accept": ["used to"], "id": "bkB1-246"}, {"type": "tf", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Ela trabalhava na feira, tinha pouco tempo livre, dançava aos sábados e ainda não se acostumou ao apartamento.", "text": "When Dona Célia was young, she used to sell fruit at a market in Belém. She didn't use to have much free time, but she used to dance on Saturday nights. Now she is 80 and lives with her granddaughter. She isn't used to living in a big apartment, but she enjoys the view.", "items": [{"s": "Célia used to work at a market.", "a": true}, {"s": "She had a lot of free time when she was young.", "a": false}, {"s": "She used to dance on weekends.", "a": true}, {"s": "She is completely used to apartment life.", "a": false}], "id": "bkB1-247"}, {"type": "reading", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Leia o texto e responda às perguntas.", "explain": "A cidade era tranquila; o avô não se acostumou ao barulho, mas gosta do novo hospital.", "text": "Ten years ago, Lagoa Santa used to be a quiet town. There didn't use to be any shopping malls, and people used to know all their neighbors. Now there are new buildings everywhere and lots of traffic. My grandfather says he isn't used to the noise yet. But he likes the new hospital, which is very close to his house.", "questions": [{"q": "What was Lagoa Santa like ten years ago?", "options": ["Quiet", "Noisy", "Full of malls"], "correctIndex": 0}, {"q": "How does the grandfather feel about the noise?", "options": ["He loves it.", "He isn't used to it.", "He doesn't notice it."], "correctIndex": 1}, {"q": "What does the grandfather like?", "options": ["The traffic", "The new hospital", "The shopping malls"], "correctIndex": 1}], "id": "bkB1-248"}, {"type": "dorder", "level": "B1", "topic": "Dedução (must/can't) & Used to", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Pergunta → dedução (must be) → dúvida → explicação com used to → nova conclusão.", "lines": ["A: Whose car is that in front of your house?", "B: It must be my sister's. She said she was coming today.", "A: But your sister has a small car, doesn't she?", "B: She used to. She bought a bigger one last month.", "A: Oh, then it must be hers."], "id": "bkB1-249"}, {"type": "mcq", "level": "B1", "topic": "Do x Make", "instruction": "Escolha a opção correta.", "explain": "Marcar uma consulta: make an appointment.", "prompt": "I need to ___ an appointment with the dentist.", "options": ["make", "do", "put", "give"], "correctIndex": 0, "id": "bkB1-250"}, {"type": "mcq", "level": "B1", "topic": "Do x Make", "instruction": "Escolha a opção correta.", "explain": "Fazer pesquisa/trabalho: do research.", "prompt": "Have you ___ your research for the history project?", "options": ["made", "done", "taken", "given"], "correctIndex": 1, "id": "bkB1-251"}, {"type": "mcq", "level": "B1", "topic": "Do x Make", "instruction": "Escolha a opção correta.", "explain": "Fazer uma cópia (produzir algo): make a copy.", "prompt": "Could you ___ me a copy of this document?", "options": ["do", "make", "take", "put"], "correctIndex": 1, "id": "bkB1-252"}, {"type": "gaps", "level": "B1", "topic": "Do x Make", "instruction": "Complete com do ou make.", "explain": "Do: tarefas e atividades (a lot to do, research, the ironing). Make: criar/produzir (reservation, list).", "prompt": "Before my trip to Chile, I have a lot to ___. I need to ___ a hotel reservation, ___ some research about the weather and ___ a list of things to pack. I also have to ___ the ironing!", "answers": [["do"], ["make"], ["do"], ["make"], ["do"]], "id": "bkB1-253"}, {"type": "gaps", "level": "B1", "topic": "Do x Make", "instruction": "Complete com do ou make na forma correta.", "explain": "Profissão: What does she do? Negócios: do business. Dinheiro: make money.", "prompt": "A: What does your mother ___?\nB: She's an engineer. She ___ a lot of business with China.\nA: Cool! Does she ___ a lot of money?", "answers": [["do"], ["does"], ["make"]], "id": "bkB1-254"}, {"type": "gaps", "level": "B1", "topic": "Do x Make", "instruction": "Complete com do ou make na forma correta.", "explain": "Expressões fixas: do damage (causar estragos) e do your best (fazer o melhor possível).", "prompt": "The storm ___ a lot of damage to the houses near the river, but volunteers are ___ their best to help.", "answers": [["did", "has done"], ["doing"]], "id": "bkB1-255"}, {"type": "choose", "level": "B1", "topic": "Do x Make", "instruction": "Escolha do ou make.", "explain": "Do the dishes (lavar a louça); make coffee (preparar café).", "prompt": "Can you [do*/make] the dishes while I [make*/do] the coffee?", "id": "bkB1-256"}, {"type": "choose", "level": "B1", "topic": "Do x Make", "instruction": "Escolha do ou make.", "explain": "Do well (ir bem); make a mistake (cometer um erro).", "prompt": "Don't worry, you [did*/made] well on the test. You only [did/made*] two small mistakes.", "id": "bkB1-257"}, {"type": "error", "level": "B1", "topic": "Do x Make", "instruction": "Encontre o erro e corrija.", "explain": "Bagunçar/fazer bagunça: make a mess.", "sentence": "The kids did a big mess in the living room.", "wrong": "did", "fix": ["made"], "id": "bkB1-258"}, {"type": "error", "level": "B1", "topic": "Do x Make", "instruction": "Encontre o erro e corrija.", "explain": "Fazer um curso: do (ou take) a course, nunca make.", "sentence": "She is making a Spanish course online.", "wrong": "making", "fix": ["doing", "taking"], "id": "bkB1-259"}, {"type": "rewrite", "level": "B1", "topic": "Do x Make", "instruction": "Reescreva usando make sure.", "explain": "\"Make sure\" = certificar-se, garantir.", "prompt": "Please check that the door is locked.", "start": "Please make sure", "accept": ["Please make sure the door is locked.", "Please make sure that the door is locked."], "id": "bkB1-260"}, {"type": "order", "level": "B1", "topic": "Do x Make", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Cozinhar como tarefa da casa: do the cooking.", "words": ["My", "father", "does", "the", "cooking", "on", "Sundays"], "alt": ["On Sundays my father does the cooking"], "id": "bkB1-261"}, {"type": "order", "level": "B1", "topic": "Do x Make", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Fazer um discurso: make a speech.", "words": ["She", "made", "a", "great", "speech", "at", "the", "wedding"], "alt": ["At the wedding she made a great speech"], "id": "bkB1-262"}, {"type": "match", "level": "B1", "topic": "Do x Make", "instruction": "Ligue as partes para formar frases.", "explain": "Make from scratch (fazer do zero); make someone do (obrigar); do good (fazer bem); make it hard (tornar difícil).", "left": ["The chef always makes", "Our teacher made us do", "Jogging every day does", "The noise from the party made"], "right": ["you a lot of good.", "it hard to sleep.", "an extra exercise.", "the pasta from scratch."], "correctMap": [3, 2, 0, 1], "id": "bkB1-263"}, {"type": "sort", "level": "B1", "topic": "Do x Make", "instruction": "Separe as expressões: do ou make?", "explain": "Do: tarefas e atividades (a course, the ironing, damage, the cooking). Make: resultado/criação (reservation, mess, excuse, progress).", "prompt": "Does each expression go with DO or MAKE?", "groups": ["DO", "MAKE"], "items": [{"w": "a course", "g": 0}, {"w": "the ironing", "g": 0}, {"w": "damage", "g": 0}, {"w": "the cooking", "g": 0}, {"w": "a reservation", "g": 1}, {"w": "a mess", "g": 1}, {"w": "an excuse", "g": 1}, {"w": "progress", "g": 1}], "id": "bkB1-264"}, {"type": "odd", "level": "B1", "topic": "Do x Make", "instruction": "Qual expressão NÃO combina com DO?", "explain": "Contar uma piada: make (ou tell) a joke; as outras usam do.", "prompt": "Which expression does NOT go with DO?", "options": ["the dishes", "your hair", "a joke", "a favor"], "correctIndex": 2, "id": "bkB1-265"}, {"type": "blank", "level": "B1", "topic": "Do x Make", "instruction": "Complete com do ou make.", "explain": "Fazer uma oferta (de compra): make an offer.", "prompt": "Did you ___ an offer on that apartment?", "accept": ["make"], "id": "bkB1-266"}, {"type": "tf", "level": "B1", "topic": "Do x Make", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O pai cozinha, Bia arruma as camas, os gêmeos fazem bagunça e a mãe faz café.", "text": "Every Saturday, the Silva family does the housework together. Mr. Silva does the cooking, and his daughter Bia makes the beds. The twins do the vacuuming, but they often make a mess with their toys. After lunch, Mrs. Silva makes coffee and everyone does something fun, like playing cards.", "items": [{"s": "Mr. Silva prepares the food.", "a": true}, {"s": "Bia does the vacuuming.", "a": false}, {"s": "The twins are always very tidy.", "a": false}, {"s": "Mrs. Silva makes coffee after lunch.", "a": true}], "id": "bkB1-267"}, {"type": "reading", "level": "B1", "topic": "Do x Make", "instruction": "Leia o texto e responda às perguntas.", "explain": "O recepcionista faz reservas; o hotel oferece aulas de inglês; o prazo é sexta.", "text": "JOB AD: HOTEL RECEPTIONIST\nOur hotel in Bonito is looking for a receptionist. You will make reservations, answer phone calls and do some office work. You must make guests feel welcome and do your best to solve their problems. We offer free English classes, so you can make progress with your language skills. Send your CV by Friday.", "questions": [{"q": "What will the receptionist do?", "options": ["Make reservations", "Cook for guests", "Clean the rooms"], "correctIndex": 0}, {"q": "What does the hotel offer?", "options": ["Free meals", "Free English classes", "A car"], "correctIndex": 1}, {"q": "What is the deadline?", "options": ["Monday", "Friday", "Next month"], "correctIndex": 1}], "id": "bkB1-268"}, {"type": "dorder", "level": "B1", "topic": "Do x Make", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Pergunta sobre planos → tarefas → oferta de ajuda → pedido → confirmação.", "lines": ["A: What are you doing this weekend?", "B: I have to do some shopping, and then I'm making lasagna for my parents.", "A: That sounds nice. Can I do anything to help?", "B: Sure! Could you make a salad?", "A: No problem. I'll bring it on Sunday."], "id": "bkB1-269"}, {"type": "mcq", "level": "B1", "topic": "To x For", "instruction": "Escolha a opção correta.", "explain": "\"For\" + substantivo indica para quê: saving for a laptop.", "prompt": "I'm saving money ___ a new laptop.", "options": ["to", "for", "for buy", "to buying"], "correctIndex": 1, "id": "bkB1-270"}, {"type": "mcq", "level": "B1", "topic": "To x For", "instruction": "Escolha a opção correta.", "explain": "Duração de um período: for + tempo (for ten years).", "prompt": "She has worked at the hospital ___ ten years.", "options": ["to", "for", "since", "during"], "correctIndex": 1, "id": "bkB1-271"}, {"type": "mcq", "level": "B1", "topic": "To x For", "instruction": "Escolha a opção correta.", "explain": "Estrutura: it's OK for + pessoa + to + verbo.", "prompt": "Is it OK ___ me to leave early today?", "options": ["to", "for", "with", "by"], "correctIndex": 1, "id": "bkB1-272"}, {"type": "gaps", "level": "B1", "topic": "To x For", "instruction": "Complete com to ou for.", "explain": "To indica destino (to the supermarket); for indica finalidade/beneficiário (for the cake, for me).", "prompt": "A: Where are you going?\nB: ___ the supermarket. We need eggs ___ the cake.\nA: Can you get some milk ___ me too?", "answers": [["To"], ["for"], ["for"]], "id": "bkB1-273"}, {"type": "gaps", "level": "B1", "topic": "To x For", "instruction": "Complete com to ou for.", "explain": "Apply for (candidatar-se a); send to (enviar para alguém); ask someone to + verbo.", "prompt": "I applied ___ a job at a startup. I sent my CV ___ the manager, and she asked me ___ come for an interview.", "answers": [["for"], ["to"], ["to"]], "id": "bkB1-274"}, {"type": "choose", "level": "B1", "topic": "To x For", "instruction": "Escolha to ou for.", "explain": "To indica destino (to Recife); for + substantivo indica motivo (for a conference).", "prompt": "I'm going [to*/for] Recife [for*/to] a conference next week.", "id": "bkB1-275"}, {"type": "choose", "level": "B1", "topic": "To x For", "instruction": "Escolha to ou for.", "explain": "Thanks for + -ing; to + verbo indica finalidade (to help).", "prompt": "Thanks [for*/to] coming! We need more people [to*/for] help with the event.", "id": "bkB1-276"}, {"type": "error", "level": "B1", "topic": "To x For", "instruction": "Encontre o erro e corrija.", "explain": "Cozinhar para alguém (beneficiário): cook for us.", "sentence": "My mom always cooks feijoada to us on Sundays.", "wrong": "to us", "fix": ["for us"], "id": "bkB1-277"}, {"type": "error", "level": "B1", "topic": "To x For", "instruction": "Encontre o erro e corrija.", "explain": "Pedir algo: ask for (não \"ask to\" + substantivo).", "sentence": "He asked to a glass of water.", "wrong": "to", "fix": ["for"], "id": "bkB1-278"}, {"type": "rewrite", "level": "B1", "topic": "To x For", "instruction": "Reescreva usando for + -ing para indicar a função.", "explain": "Para indicar a função de um objeto: be for + -ing.", "prompt": "This machine makes juice.", "start": "This machine is for", "accept": ["This machine is for making juice."], "id": "bkB1-279"}, {"type": "rewrite", "level": "B1", "topic": "To x For", "instruction": "Una as frases usando for.", "explain": "For indica para quem é o presente (beneficiário).", "prompt": "She bought a present. It's for her grandmother.", "start": "She bought a present", "accept": ["She bought a present for her grandmother."], "id": "bkB1-280"}, {"type": "order", "level": "B1", "topic": "To x For", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Send something to someone: o to indica o destinatário.", "words": ["I", "sent", "an", "email", "to", "the", "hotel", "manager"], "id": "bkB1-281"}, {"type": "order", "level": "B1", "topic": "To x For", "instruction": "Ordene as palavras para formar uma frase.", "explain": "To + lugar (destino) e for + evento (motivo da viagem).", "words": ["We", "went", "to", "Gramado", "for", "the", "chocolate", "festival"], "id": "bkB1-282"}, {"type": "match", "level": "B1", "topic": "To x For", "instruction": "Ligue as partes para formar frases.", "explain": "Bad for; sorry for + -ing; too young to + verbo; pass something to someone.", "left": ["Smoking is bad", "I'm really sorry", "She's too young", "Could you pass the salt"], "right": ["to drive a car.", "for your health.", "to me, please?", "for being late."], "correctMap": [1, 3, 0, 2], "id": "bkB1-283"}, {"type": "sort", "level": "B1", "topic": "To x For", "instruction": "Qual preposição acompanha cada expressão?", "explain": "Ask/apply/search for, famous for; explain/go/reply/happen to.", "prompt": "Which preposition goes with each expression: to or for?", "groups": ["to", "for"], "items": [{"w": "ask ___ help", "g": 1}, {"w": "apply ___ a visa", "g": 1}, {"w": "explain ___ someone", "g": 0}, {"w": "go ___ bed", "g": 0}, {"w": "be famous ___ something", "g": 1}, {"w": "reply ___ an email", "g": 0}, {"w": "search ___ information", "g": 1}, {"w": "happen ___ someone", "g": 0}], "id": "bkB1-284"}, {"type": "odd", "level": "B1", "topic": "To x For", "instruction": "Qual frase NÃO está correta?", "explain": "Para finalidade com verbo usamos to + verbo (to lose), nunca for + verbo.", "prompt": "Which sentence has a mistake with to or for?", "options": ["He joined a gym to get fit.", "He joined a gym for his health.", "He joined a gym for lose weight.", "He joined a gym to lose weight."], "correctIndex": 2, "id": "bkB1-285"}, {"type": "blank", "level": "B1", "topic": "To x For", "instruction": "Complete com a preposição correta.", "explain": "Famoso por algo: famous for.", "prompt": "Brazil is famous ___ its music and its beaches.", "accept": ["for"], "id": "bkB1-286"}, {"type": "tf", "level": "B1", "topic": "To x For", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Foi estudar por seis meses; a tia deu o dicionário; ele envia fotos à irmã.", "text": "Gabriel went to Lisbon for six months to study architecture. Before he left, his friends organized a party for him. His aunt gave a Portuguese dictionary to him as a gift. In Lisbon, he often writes to his parents, and he sends photos to his little sister every week.", "items": [{"s": "Gabriel went to Lisbon to study.", "a": true}, {"s": "His friends gave him a dictionary.", "a": false}, {"s": "He stayed in Lisbon for a year.", "a": false}, {"s": "He sends photos to his sister.", "a": true}], "id": "bkB1-287"}, {"type": "reading", "level": "B1", "topic": "To x For", "instruction": "Leia o texto e responda às perguntas.", "explain": "A reserva é por duas noites, as bicicletas são grátis e o e-mail confirma a reserva.", "text": "Dear Mr. Lopes,\nThank you for your email. I'm writing to confirm your booking for two nights, from May 3rd to May 5th. Breakfast is included, and it's served from 7 to 10 a.m. If you need a taxi to the airport, just ask at reception. We also have bikes for guests, free of charge.\nBest regards,\nPousada Mar Azul", "questions": [{"q": "How long is Mr. Lopes staying?", "options": ["For two nights", "For a week", "For three nights"], "correctIndex": 0}, {"q": "What can guests use for free?", "options": ["Taxis", "Bikes", "The spa"], "correctIndex": 1}, {"q": "Why is the pousada writing?", "options": ["To confirm a booking", "To cancel a booking", "To ask for payment"], "correctIndex": 0}], "id": "bkB1-288"}, {"type": "dorder", "level": "B1", "topic": "To x For", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Pedido no correio → pergunta sobre o presente → para quem é → prazo → agradecimento.", "lines": ["A: Hi! I'd like to send this package to Manaus.", "B: Sure. Is it a gift for someone?", "A: Yes, it's for my nephew's birthday.", "B: OK. It'll take about five days to get there.", "A: Perfect. Thanks for your help!"], "id": "bkB1-289"}, {"type": "mcq", "level": "B1", "topic": "Conectores avançados", "instruction": "Escolha a opção correta.", "explain": "\"In case\" = caso, por precaução.", "prompt": "Take a jacket ___ it gets cold later.", "options": ["in case", "unless", "although", "despite"], "correctIndex": 0, "id": "bkB1-290"}, {"type": "mcq", "level": "B1", "topic": "Conectores avançados", "instruction": "Escolha a opção correta.", "explain": "\"As long as\" = desde que (condição).", "prompt": "You can borrow my car ___ you drive carefully.", "options": ["as long as", "unless", "despite", "whereas"], "correctIndex": 0, "id": "bkB1-291"}, {"type": "mcq", "level": "B1", "topic": "Conectores avançados", "instruction": "Escolha a opção correta.", "explain": "\"Due to\" + substantivo indica a causa; \"because\" pediria uma oração com verbo.", "prompt": "The game was canceled ___ the heavy rain.", "options": ["because", "due to", "although", "so that"], "correctIndex": 1, "id": "bkB1-292"}, {"type": "gaps", "level": "B1", "topic": "Conectores avançados", "instruction": "Complete o texto com os conectores do quadro.", "explain": "First of all inicia a lista; Moreover acrescenta; However contrasta; Since indica causa.", "prompt": "Working from home has many advantages. ___, you save time because you don't have to commute. ___, you can organize your own schedule. ___, some people feel lonely. ___ they miss their colleagues, they often go back to the office a few days a week.", "bank": ["First of all", "Moreover", "However", "Since", "Unless", "Despite"], "answers": [["First of all", "Firstly", "First"], ["Moreover", "Furthermore", "In addition", "Also", "Besides"], ["However", "On the other hand", "Nevertheless"], ["Since", "Because", "As"]], "id": "bkB1-293"}, {"type": "gaps", "level": "B1", "topic": "Conectores avançados", "instruction": "Complete com um conector adequado.", "explain": "\"So that\" indica finalidade; \"However\" introduz um resultado contrário ao esperado.", "prompt": "I left early ___ that I could catch the last bus. ___, I missed it and had to take a taxi.", "answers": [["so", "in order"], ["However", "Unfortunately", "Nevertheless", "Even so", "But"]], "id": "bkB1-294"}, {"type": "choose", "level": "B1", "topic": "Conectores avançados", "instruction": "Escolha o conector correto.", "explain": "\"Even though\" + oração (despite pediria substantivo ou -ing); \"on the other hand\" contrasta.", "prompt": "[Even though*/Despite] Maria earns a good salary, she lives with her parents. Her brother, [on the other hand*/in addition], lives alone.", "id": "bkB1-295"}, {"type": "choose", "level": "B1", "topic": "Conectores avançados", "instruction": "Escolha o conector correto.", "explain": "\"Otherwise\" = senão, caso contrário; \"as soon as\" = assim que.", "prompt": "Save your file often. [Otherwise*/Moreover], you might lose your work. And call me [as soon as*/whereas] you finish.", "id": "bkB1-296"}, {"type": "error", "level": "B1", "topic": "Conectores avançados", "instruction": "Encontre o erro e corrija.", "explain": "Em inglês não se usa \"although\" e \"but\" juntos (erro comum de \"embora..., mas\").", "sentence": "Although it was late, but we kept dancing.", "wrong": "but we", "fix": ["we"], "id": "bkB1-297"}, {"type": "error", "level": "B1", "topic": "Conectores avançados", "instruction": "Encontre o erro e corrija.", "explain": "\"Unless\" já significa \"a menos que\", então não usamos negativa depois dele.", "sentence": "I'll go to the party unless it doesn't rain.", "wrong": "doesn't rain", "fix": ["rains"], "id": "bkB1-298"}, {"type": "rewrite", "level": "B1", "topic": "Conectores avançados", "instruction": "Reescreva começando com Despite.", "explain": "\"Despite\" é seguido de substantivo ou -ing, não de oração com sujeito + verbo.", "prompt": "She didn't have much experience, but she got the job.", "start": "Despite", "accept": ["Despite not having much experience, she got the job.", "Despite having little experience, she got the job.", "Despite her lack of experience, she got the job.", "Despite the fact that she didn't have much experience, she got the job.", "Despite not having a lot of experience, she got the job."], "id": "bkB1-299"}, {"type": "rewrite", "level": "B1", "topic": "Conectores avançados", "instruction": "Una as frases usando whereas.", "explain": "\"Whereas\" liga duas ideias em contraste direto.", "prompt": "Paulo loves spicy food. His wife hates it.", "start": "Paulo loves spicy food, whereas", "accept": ["Paulo loves spicy food, whereas his wife hates it."], "id": "bkB1-300"}, {"type": "order", "level": "B1", "topic": "Conectores avançados", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"So that\" indica finalidade: anotei para não esquecer.", "words": ["I", "wrote", "it", "down", "so", "that", "I", "wouldn't", "forget"], "id": "bkB1-301"}, {"type": "order", "level": "B1", "topic": "Conectores avançados", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"As a result of\" + substantivo indica a causa.", "words": ["The", "road", "was", "closed", "as", "a", "result", "of", "the", "flood"], "alt": ["As a result of the flood the road was closed"], "id": "bkB1-302"}, {"type": "match", "level": "B1", "topic": "Conectores avançados", "instruction": "Ligue as partes para formar frases.", "explain": "In case = por precaução; as long as = desde que; however e nevertheless = contraste.", "left": ["Bring an umbrella", "I'll help you", "The museum is free;", "She was tired;"], "right": ["nevertheless, she went to the gym.", "in case it rains.", "as long as you help me later.", "however, you need to book a ticket."], "correctMap": [1, 2, 3, 0], "id": "bkB1-303"}, {"type": "sort", "level": "B1", "topic": "Conectores avançados", "instruction": "Classifique os conectores pelo sentido.", "explain": "Condição: unless, as long as, provided that. Finalidade: so that, in order to. Causa: due to, because of, since.", "prompt": "What does each connector express: condition, purpose or cause?", "groups": ["Condição", "Finalidade", "Causa"], "items": [{"w": "unless", "g": 0}, {"w": "as long as", "g": 0}, {"w": "provided that", "g": 0}, {"w": "so that", "g": 1}, {"w": "in order to", "g": 1}, {"w": "due to", "g": 2}, {"w": "because of", "g": 2}], "id": "bkB1-304"}, {"type": "odd", "level": "B1", "topic": "Conectores avançados", "instruction": "Qual conector NÃO expressa contraste?", "explain": "\"Furthermore\" acrescenta informação; os outros expressam contraste.", "prompt": "Which connector does NOT express contrast?", "options": ["whereas", "even though", "furthermore", "nevertheless"], "correctIndex": 2, "id": "bkB1-305"}, {"type": "blank", "level": "B1", "topic": "Conectores avançados", "instruction": "Complete com o conector adequado.", "explain": "\"Despite\" / \"In spite of\" + -ing expressam contraste.", "prompt": "___ being very rich, he lives in a small house.", "accept": ["Despite", "In spite of"], "id": "bkB1-306"}, {"type": "tf", "level": "B1", "topic": "Conectores avançados", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O texto diz que faz calor, que cadeiras são pagas, que há bons museus e que Copacabana lota no Réveillon.", "text": "Rio de Janeiro is a wonderful city for tourists. However, it can be very hot in summer, so visitors should drink a lot of water. Although the beaches are free, the chairs and umbrellas are not. Moreover, the city has great museums, such as the Museum of Tomorrow. Unless you enjoy crowds, avoid Copacabana on New Year's Eve.", "items": [{"s": "Rio can be very hot in summer.", "a": true}, {"s": "Beach chairs are free.", "a": false}, {"s": "There are good museums in Rio.", "a": true}, {"s": "Copacabana is quiet on New Year's Eve.", "a": false}], "id": "bkB1-307"}, {"type": "reading", "level": "B1", "topic": "Conectores avançados", "instruction": "Leia o texto e responda às perguntas.", "explain": "Due to indica a causa (greve); a empresa oferece frete grátis; o cancelamento vale se o produto não foi enviado.", "text": "Dear customer,\nWe're sorry, but your order will arrive two days late due to a strike at the port. Although this is not our fault, we'd like to offer you free shipping on your next purchase. Furthermore, if you prefer to cancel the order, you can do so as long as the product hasn't been sent yet. Otherwise, you'll receive it on Thursday.\nBest regards,\nCasa Tech", "questions": [{"q": "Why is the order late?", "options": ["There is a strike at the port.", "The product is sold out.", "The customer made a mistake."], "correctIndex": 0}, {"q": "What is the company offering?", "options": ["A 50% discount", "Free shipping next time", "A new product"], "correctIndex": 1}, {"q": "When can the customer cancel?", "options": ["Only on Thursday", "If the product hasn't been sent", "Never"], "correctIndex": 1}], "id": "bkB1-308"}, {"type": "dorder", "level": "B1", "topic": "Conectores avançados", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Pergunta → prós e contras (however) → objeção → outro lado (on the other hand) → apoio.", "lines": ["A: Are you going to accept the job in Brasília?", "B: I'm not sure. The salary is great. However, I'd have to move.", "A: But you've always wanted to live in a new city, haven't you?", "B: True. On the other hand, my family is here.", "A: Well, whatever you decide, I'll support you."], "id": "bkB1-309"}, {"type": "mcq", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Escolha a opção correta.", "explain": "Na pergunta indireta, a ordem é de afirmação: how old he is.", "prompt": "Do you have any idea ___?", "options": ["how old is he", "how old he is", "how old does he", "he is how old"], "correctIndex": 1, "id": "bkB1-310"}, {"type": "mcq", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Escolha a opção correta.", "explain": "Pergunta de sim/não indireta usa if/whether.", "prompt": "I'd like to know ___ breakfast is included.", "options": ["that", "whether", "what", "does"], "correctIndex": 1, "id": "bkB1-311"}, {"type": "mcq", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Escolha a opção correta.", "explain": "Na pergunta indireta tiramos o \"did\" e usamos o verbo no passado: where we parked.", "prompt": "Can you remember where ___ the car?", "options": ["did we park", "we parked", "we did park", "parked we"], "correctIndex": 1, "id": "bkB1-312"}, {"type": "gaps", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Complete com a forma correta do verbo.", "explain": "Ordem de afirmação e sem do/does: where the gate is; if my flight leaves.", "prompt": "Excuse me, could you tell me where the gate ___ (be)? I'm not sure if my flight ___ (leave) on time.", "answers": [["is"], ["leaves", "is leaving", "will leave"]], "id": "bkB1-313"}, {"type": "gaps", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Complete com a forma correta do verbo.", "explain": "Sem \"did\" na pergunta indireta: why Carla left; if she found / has found.", "prompt": "A: Do you know why Carla ___ (leave) her job last month?\nB: No idea. I wonder if she ___ (find) a better one.", "answers": [["left"], ["found", "has found"]], "id": "bkB1-314"}, {"type": "choose", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Escolha a forma correta.", "explain": "Pergunta indireta: sem does e com ordem de afirmação; sim/não usa whether/if.", "prompt": "Could you tell me [how much this costs*/how much does this cost]? I'd also like to know [whether*/that] you accept credit cards.", "id": "bkB1-315"}, {"type": "choose", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Escolha a forma correta.", "explain": "Depois de \"I'm not sure\" e \"I know\" usamos ordem de afirmação, sem inversão.", "prompt": "I'm not sure [what time the show starts*/what time does the show start], but I know [where it is*/where is it].", "id": "bkB1-316"}, {"type": "error", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Encontre o erro e corrija.", "explain": "Depois de \"I wonder if\" usamos ordem de afirmação: she is.", "sentence": "I wonder if is she coming tonight.", "wrong": "is she", "fix": ["she is"], "id": "bkB1-317"}, {"type": "error", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Encontre o erro e corrija.", "explain": "Na pergunta indireta o sujeito vem antes do modal: where I can buy.", "sentence": "Could you tell me where can I buy a SIM card?", "wrong": "can I", "fix": ["I can"], "id": "bkB1-318"}, {"type": "rewrite", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Transforme em pergunta indireta.", "explain": "Ordem de afirmação: what your email address is.", "prompt": "What's your email address?", "start": "May I ask", "accept": ["May I ask what your email address is?"], "id": "bkB1-319"}, {"type": "rewrite", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Transforme em pergunta indireta.", "explain": "Sim/não indireta: if/whether + ordem de afirmação, sem does (goes).", "prompt": "Does this bus go to the airport?", "start": "Can you tell me", "accept": ["Can you tell me if this bus goes to the airport?", "Can you tell me whether this bus goes to the airport?", "Can you tell me whether or not this bus goes to the airport?"], "id": "bkB1-320"}, {"type": "order", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Depois de \"I wonder why\" usamos ordem de afirmação: the flight was canceled.", "words": ["I", "wonder", "why", "the", "flight", "was", "canceled"], "id": "bkB1-321"}, {"type": "order", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta indireta: Do you know + whose phone + this is.", "words": ["Do", "you", "know", "whose", "phone", "this", "is"], "id": "bkB1-322"}, {"type": "match", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Ligue cada pergunta direta à pergunta indireta equivalente.", "explain": "A indireta mantém o sentido, mas usa ordem de afirmação e if para sim/não.", "left": ["Where is the exit?", "Is the museum open today?", "How much is a ticket?", "When does the tour start?"], "right": ["Could you tell me when the tour starts?", "Do you know how much a ticket is?", "Can you tell me where the exit is?", "I'd like to know if the museum is open today."], "correctMap": [2, 3, 1, 0], "id": "bkB1-323"}, {"type": "sort", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Classifique as perguntas indiretas: corretas ou incorretas.", "explain": "Nas corretas não há inversão nem do/does: where she works, what this word means.", "prompt": "Is each indirect question correct or incorrect?", "groups": ["Correta", "Incorreta"], "items": [{"w": "Do you know where she works?", "g": 0}, {"w": "Do you know where does she work?", "g": 1}, {"w": "I wonder if it will rain.", "g": 0}, {"w": "I wonder will it rain.", "g": 1}, {"w": "Can you tell me what this word means?", "g": 0}, {"w": "Can you tell me what means this word?", "g": 1}], "id": "bkB1-324"}, {"type": "odd", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Qual NÃO é uma pergunta indireta?", "explain": "\"Where does he live?\" é pergunta direta; as outras são indiretas.", "prompt": "Which one is NOT an indirect question?", "options": ["Do you know where he lives?", "I wonder what time it is.", "Where does he live?", "Could you tell me who called?"], "correctIndex": 2, "id": "bkB1-325"}, {"type": "blank", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Complete com a palavra adequada.", "explain": "Pergunta indireta de sim/não: if ou whether.", "prompt": "Could you tell me ___ this seat is free?", "accept": ["if", "whether"], "id": "bkB1-326"}, {"type": "tf", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O quarto não está pronto; ela pergunta onde deixar a mala; recebe oferta de mapa; pergunta sobre o café da manhã.", "text": "Vanessa is at a hotel reception in Buenos Aires. She asks the receptionist if her room is ready, but it isn't. Then she wants to know where she can leave her suitcase. The receptionist asks her whether she would like a map of the city. Vanessa says yes and asks what time breakfast is served.", "items": [{"s": "Vanessa's room is ready.", "a": false}, {"s": "She asks where she can leave her bag.", "a": true}, {"s": "The receptionist offers her a map.", "a": true}, {"s": "She asks about lunch.", "a": false}], "id": "bkB1-327"}, {"type": "reading", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Leia o texto e responda às perguntas.", "explain": "Henrique quer comprar o violão; pergunta idade, estojo e cordas, mas não o preço; quer ver no fim de semana.", "text": "Hello,\nI saw your ad for the guitar, and I have a few questions. Could you tell me how old the guitar is? I'd also like to know if it comes with a case. And do you know whether the strings are new? If everything is OK, I'd like to see it this weekend. Can you let me know what time works for you?\nThanks,\nHenrique", "questions": [{"q": "What is Henrique interested in?", "options": ["Buying a guitar", "Selling a case", "Taking guitar lessons"], "correctIndex": 0}, {"q": "What does he NOT ask about?", "options": ["The age of the guitar", "The price", "The strings"], "correctIndex": 1}, {"q": "When does he want to see it?", "options": ["Today", "This weekend", "Next month"], "correctIndex": 1}], "id": "bkB1-328"}, {"type": "dorder", "level": "B1", "topic": "Perguntas indiretas", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Pergunta indireta → direção → segunda pergunta indireta → horário → agradecimento.", "lines": ["A: Excuse me, do you know where the nearest subway station is?", "B: Sure. It's two blocks from here, on Paulista Avenue.", "A: Thanks! And could you tell me if the trains run late?", "B: I think they run until midnight.", "A: Great, thank you so much!"], "id": "bkB1-329"}, {"level": "B2", "topic": "Reported Speech", "type": "mcq", "instruction": "Escolha a forma correta no discurso indireto.", "prompt": "Last week, Tom told me, \"I will call you tomorrow.\" → Last week, Tom told me he ___ call me the next day.", "options": ["will", "would", "shall", "can"], "correctIndex": 1, "explain": "No discurso indireto com verbo no passado, \"will\" vira \"would\".", "id": "bkB2-0"}, {"level": "B2", "topic": "Reported Speech", "type": "gaps", "instruction": "Complete a versão em discurso indireto.", "prompt": "Direct: \"We are moving to Recife next month.\"\nReported: They said that they ___ moving to Recife the ___ month.", "answers": [["were"], ["following", "next"]], "explain": "\"Are\" recua para \"were\"; \"next month\" vira \"the following month\" (ou \"the next month\").", "id": "bkB2-1"}, {"level": "B2", "topic": "Reported Speech", "type": "choose", "instruction": "Escolha as palavras corretas para a pergunta indireta.", "prompt": "The doctor asked me how long [I had*/had I] been feeling ill and [whether*/that] I was taking any medicine.", "explain": "Pergunta indireta usa ordem de afirmação (I had) e \"whether/if\" para perguntas de sim ou não.", "id": "bkB2-2"}, {"level": "B2", "topic": "Reported Speech", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "She asked me where did I buy my shoes.", "wrong": "did I buy", "fix": ["I had bought", "I bought"], "explain": "Em perguntas indiretas não se usa \"did\" nem inversão: \"where I had bought\".", "id": "bkB2-3"}, {"level": "B2", "topic": "Reported Speech", "type": "rewrite", "instruction": "Passe a ordem para o discurso indireto.", "prompt": "\"Don't touch the screen,\" the teacher told the kids.", "start": "The teacher told the kids", "accept": ["The teacher told the kids not to touch the screen."], "explain": "Ordens negativas no discurso indireto: told + pessoa + \"not to\" + verbo.", "id": "bkB2-4"}, {"level": "B2", "topic": "Reported Speech", "type": "rewrite", "instruction": "Passe a pergunta para o discurso indireto.", "prompt": "\"Where do you live?\" Paulo asked me.", "start": "Paulo asked me", "accept": ["Paulo asked me where I lived.", "Paulo asked me where I live."], "explain": "Pergunta indireta: sem \"do\", ordem sujeito + verbo, e o tempo recua (lived).", "id": "bkB2-5"}, {"level": "B2", "topic": "Reported Speech", "type": "order", "instruction": "Organize as palavras para formar a frase.", "words": ["She", "promised", "that", "she", "would", "send", "the", "report", "by", "Friday"], "explain": "\"Promise\" no passado + \"would\" + verbo: promessa relatada.", "id": "bkB2-6"}, {"level": "B2", "topic": "Reported Speech", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Did Carla call while I was out?", "B: Yes, she did. She said she needed to talk to you.", "A: Did she say what it was about?", "B: She said it was about the meeting tomorrow.", "A: OK, I'll call her back right away."], "explain": "B relata o recado de Carla usando o passado: \"she said she needed...\".", "id": "bkB2-7"}, {"level": "B2", "topic": "Reported Speech", "type": "tf", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Yesterday, Marina had a job interview at a tech company in Curitiba. The manager asked her why she wanted to leave her current job. Marina told him that she was looking for new challenges. He also asked whether she could start in March. She said she would need two weeks to hand in her notice.", "items": [{"s": "The manager asked Marina about her reasons for changing jobs.", "a": true}, {"s": "Marina said she was unhappy with her salary.", "a": false}, {"s": "Marina said she could start immediately.", "a": false}, {"s": "The interview was for a job in Curitiba.", "a": true}], "explain": "O texto relata as perguntas e respostas da entrevista em discurso indireto.", "id": "bkB2-8"}, {"level": "B2", "topic": "Reported Speech", "type": "match", "instruction": "Ligue a fala direta à versão indireta.", "left": ["He said, \"I can swim.\"", "He said, \"I am swimming.\"", "He said, \"I swam.\"", "He said, \"I will swim.\""], "right": ["He said he had swum.", "He said he would swim.", "He said he could swim.", "He said he was swimming."], "correctMap": [2, 3, 0, 1], "explain": "Recuo de tempos: can→could, am→was, swam→had swum, will→would.", "id": "bkB2-9"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "If we ___ the earlier bus, we wouldn't have missed the start of the movie.", "options": ["took", "had taken", "have taken", "would take"], "correctIndex": 1, "explain": "Third conditional: if + past perfect, would have + particípio.", "id": "bkB2-10"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "gaps", "instruction": "Complete com a forma correta (condicional misto).", "prompt": "If Lucas ___ (study) medicine ten years ago, he ___ (be) a doctor now.", "answers": [["had studied"], ["would be", "might be", "could be"]], "explain": "Condicional misto: passado irreal (had studied) com resultado no presente (would be now).", "id": "bkB2-11"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "If I [had known*/knew] about the traffic, I [would have left*/would leave] home earlier this morning.", "explain": "Situação passada (\"this morning\" já passou): third conditional com had known e would have left.", "id": "bkB2-12"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "If she would have asked me, I would have helped her.", "wrong": "would have asked", "fix": ["had asked"], "explain": "Na oração com \"if\" do third conditional usa-se past perfect, nunca \"would have\".", "id": "bkB2-13"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "rewrite", "instruction": "Reescreva usando o third conditional.", "prompt": "I didn't bring an umbrella, so I got wet.", "start": "If I had brought", "accept": ["If I had brought an umbrella, I wouldn't have got wet.", "If I had brought an umbrella, I wouldn't have gotten wet.", "If I had brought an umbrella, I would have stayed dry.", "If I had brought an umbrella, I wouldn't have been wet.", "If I had brought an umbrella, I wouldn't have gotten so wet.", "If I had brought an umbrella, I would not have got wet.", "If I had brought an umbrella, I would not have gotten wet.", "If I had brought an umbrella, I would not have gotten so wet.", "If I had brought an umbrella, I would not have been wet."], "explain": "Third conditional: if + had + particípio, would (not) have + particípio.", "id": "bkB2-14"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "rewrite", "instruction": "Reescreva usando um condicional misto.", "prompt": "He didn't save any money last year, so he can't travel now.", "start": "If he had saved", "accept": ["If he had saved some money last year, he could travel now.", "If he had saved money last year, he could travel now.", "If he had saved any money last year, he could travel now.", "If he had saved some money last year, he would be able to travel now.", "If he had saved money last year, he would be able to travel now.", "If he had saved any money last year, he would be able to travel now.", "If he had saved some money last year, he'd be able to travel now.", "If he had saved money last year, he'd be able to travel now.", "If he had saved any money last year, he'd be able to travel now."], "explain": "Condicional misto: passado (had saved) com consequência no presente (could travel now).", "id": "bkB2-15"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "order", "instruction": "Organize as palavras para formar a frase.", "words": ["If", "you", "had", "asked", "me", "I", "would", "have", "lent", "you", "money"], "alt": ["I would have lent you money if you had asked me"], "explain": "Third conditional: if + past perfect, would have + particípio.", "id": "bkB2-16"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "reading", "instruction": "Leia a mensagem e responda às perguntas.", "text": "Dear Ana, I'm so sorry I missed your birthday party on Saturday. My flight from Manaus was canceled because of a storm, and the next one was full. If the weather had been better, I would have been there with you. Honestly, if I had booked a flight on Friday instead, I wouldn't be feeling so guilty now! I'd love to take you out for dinner next week to celebrate. Love, Júlia", "questions": [{"q": "Why did Júlia miss the party?", "options": ["She forgot the date.", "Her flight was canceled because of a storm.", "She had to work on Saturday."], "correctIndex": 1}, {"q": "How does Júlia feel now?", "options": ["Relieved", "Angry", "Guilty"], "correctIndex": 2}, {"q": "What does Júlia suggest?", "options": ["Having dinner together next week", "Having another party on Saturday", "Traveling to Manaus together"], "correctIndex": 0}], "explain": "Júlia usa condicionais para falar do passado irreal e da culpa que sente agora.", "id": "bkB2-17"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "match", "instruction": "Ligue as duas partes das frases.", "left": ["If I hadn't eaten so much,", "If they had left on time,", "If she weren't so shy,", "If you had charged your phone,"], "right": ["she would have spoken at the meeting.", "they wouldn't have missed the flight.", "I wouldn't feel sick now.", "you could have called us."], "correctMap": [2, 1, 0, 3], "explain": "Cada condição combina com sua consequência lógica, no presente ou no passado.", "id": "bkB2-18"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "blank", "instruction": "Complete com um condicional misto (resultado no presente).", "prompt": "If Rafael hadn't broken his leg last month, he ___ (play) in tonight's game.", "accept": ["would be playing", "would play", "could play", "could be playing", "might be playing", "might play"], "explain": "Passado irreal (hadn't broken) com resultado agora: would be playing.", "id": "bkB2-19"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "mcq", "instruction": "Escolha a forma correta da voz passiva.", "prompt": "The new bridge ___ right now, so we have to take another route.", "options": ["is building", "is being built", "has built", "was built"], "correctIndex": 1, "explain": "Ação em andamento na passiva: is/are being + particípio.", "id": "bkB2-20"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "sort", "prompt": "Sort the passive forms by tense.", "instruction": "Classifique as formas passivas pelo tempo verbal.", "groups": ["Present Perfect", "Past Perfect", "Future (will)"], "items": [{"w": "has been cleaned", "g": 0}, {"w": "have been taken", "g": 0}, {"w": "had been cleaned", "g": 1}, {"w": "had been told", "g": 1}, {"w": "will be sent", "g": 2}, {"w": "will be finished", "g": 2}], "explain": "has/have been, had been e will be + particípio indicam cada tempo na passiva.", "id": "bkB2-21"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "gaps", "instruction": "Complete com a voz passiva no tempo correto.", "prompt": "This hotel ___ (build) in 1920 and ___ (renovate) several times since then. Next year, a new pool ___ (add).", "answers": [["was built"], ["has been renovated"], ["will be added", "is going to be added"]], "explain": "1920: simple past; \"since then\": present perfect; \"next year\": futuro, todos na passiva.", "id": "bkB2-22"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "gaps", "instruction": "Complete com a voz passiva.", "prompt": "A: Why is Paula so happy?\nB: She has just ___ (promote) to manager.\nA: Great! And who will do her old job?\nB: The position can't ___ (fill) until next month.", "answers": [["been promoted"], ["be filled"]], "explain": "Present perfect passivo: has been + particípio; modal passivo: can't be + particípio.", "id": "bkB2-23"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "The documents [need to be signed*/need to sign] before they [are sent*/send] to the lawyer.", "explain": "Os documentos não assinam nem enviam: são assinados e enviados (voz passiva).", "id": "bkB2-24"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "The car is being repair at the garage this week.", "wrong": "repair", "fix": ["repaired"], "explain": "Passiva contínua: is being + particípio (repaired).", "id": "bkB2-25"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "rewrite", "instruction": "Passe para a voz passiva, sem mencionar o agente.", "prompt": "Someone has stolen my bike.", "start": "My bike", "accept": ["My bike has been stolen.", "My bike's been stolen."], "explain": "Present perfect passivo: has been + particípio; \"someone\" não precisa aparecer.", "id": "bkB2-26"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "rewrite", "instruction": "Passe para a voz passiva, mantendo o tempo verbal.", "prompt": "They are going to open a new shopping mall in Fortaleza.", "start": "A new shopping mall", "accept": ["A new shopping mall is going to be opened in Fortaleza."], "explain": "\"Going to\" na passiva: is going to be + particípio.", "id": "bkB2-27"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "order", "instruction": "Organize as palavras para formar a frase.", "words": ["The", "new", "software", "will", "have", "been", "installed", "by", "Monday"], "alt": ["By Monday the new software will have been installed"], "explain": "Future perfect passivo: will have been + particípio.", "id": "bkB2-28"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "tf", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "The famous Christ the Redeemer statue in Rio de Janeiro was completed in 1931. It was designed by a Brazilian engineer, Heitor da Silva Costa, and the face was created by a Romanian sculptor. Over the years, the statue has been hit by lightning many times. Today it is visited by around two million people every year, and in 2007 it was chosen as one of the New Seven Wonders of the World.", "items": [{"s": "The statue was finished in the 1930s.", "a": true}, {"s": "The whole statue was designed by a Romanian artist.", "a": false}, {"s": "Lightning has never hit the statue.", "a": false}, {"s": "It was named one of the New Seven Wonders of the World in 2007.", "a": true}], "explain": "O texto usa a passiva em vários tempos para dar fatos sobre o Cristo Redentor.", "id": "bkB2-29"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "mcq", "instruction": "Escolha a dedução mais lógica.", "prompt": "The streets are all wet. It ___ during the night.", "options": ["must have rained", "can't have rained", "should rain", "must rain"], "correctIndex": 0, "explain": "Temos quase certeza sobre o passado: must have + particípio.", "id": "bkB2-30"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "odd", "instruction": "Encontre a expressão intrusa.", "prompt": "Which expression shows certainty, not possibility?", "options": ["might have", "may have", "could have", "must have"], "correctIndex": 3, "explain": "Might, may e could have indicam possibilidade; must have indica certeza.", "id": "bkB2-31"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "gaps", "instruction": "Complete com um modal de dedução no passado.", "prompt": "A: I can't find my car keys anywhere.\nB: You ___ (leave) them in the car. You drove here, right?\nA: No, I ___ (leave) them in the car. I came by bus!", "answers": [["must have left", "might have left", "may have left", "could have left"], ["can't have left", "could not have left", "couldn't have left", "cannot have left"]], "explain": "B supõe (must/might have); A tem certeza de que é impossível (can't have).", "id": "bkB2-32"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "Julia [can't have*/must have] seen the email in the afternoon—she was on a plane with no Wi-Fi. She [must have*/can't have] read it after landing, though, because she replied at 9 p.m.", "explain": "Sem Wi-Fi é impossível (can't have); a resposta às 9 prova que leu (must have).", "id": "bkB2-33"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "He must has forgotten about the meeting.", "wrong": "has", "fix": ["have"], "explain": "Depois de modal o verbo fica na forma base: must have + particípio.", "id": "bkB2-34"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "rewrite", "instruction": "Reescreva usando must have.", "prompt": "I'm sure she took the wrong train.", "start": "She must", "accept": ["She must have taken the wrong train."], "explain": "Certeza sobre o passado: must have + particípio (taken).", "id": "bkB2-35"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Why is the kitchen such a mess?", "B: The kids must have made pancakes while we were out.", "A: They can't have made pancakes. There's no flour in the house.", "B: Then their friend Leo might have brought some.", "A: Well, whoever it was, someone has to clean it up!"], "explain": "Cada fala reage à dedução anterior: must have, can't have, might have.", "id": "bkB2-36"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "reading", "instruction": "Leia o texto e responda às perguntas.", "text": "When Mr. Alves came home on Friday night, his front door was open. His laptop was missing, but his expensive watch was still on the table. There was no damage to the lock or the windows. His neighbor said she had seen a young man open the door with a key at around 8 p.m. Mr. Alves's nephew is the only other person who has a key to the house.", "questions": [{"q": "Which conclusion is the most logical?", "options": ["The person must have broken a window.", "The person can't have entered the house.", "The person must have used a key."], "correctIndex": 2}, {"q": "Which item was still on the table?", "options": ["The watch", "The laptop", "The key"], "correctIndex": 0}, {"q": "Who might have taken the laptop?", "options": ["The neighbor", "Mr. Alves's nephew", "Mr. Alves himself"], "correctIndex": 1}], "explain": "As pistas (chave, sem danos) levam às deduções sobre o que aconteceu.", "id": "bkB2-37"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "match", "instruction": "Ligue cada situação à dedução mais lógica.", "left": ["Ana's eyes are red and puffy.", "Rui has a bad sunburn.", "The whole cake is gone.", "Leo got 100% on the test."], "right": ["He must have studied hard.", "She must have been crying.", "Someone must have eaten it.", "He must have spent the day at the beach."], "correctMap": [1, 3, 2, 0], "explain": "Cada evidência presente leva a uma conclusão sobre o passado com must have.", "id": "bkB2-38"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "blank", "instruction": "Complete com um modal de dedução no passado.", "prompt": "Tiago looks exhausted. He ___ (not sleep) well last night.", "accept": ["can't have slept", "could not have slept", "couldn't have slept", "must not have slept", "mustn't have slept", "might not have slept", "may not have slept", "cannot have slept"], "explain": "Dedução negativa sobre o passado: can't have / must not have + particípio.", "id": "bkB2-39"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "mcq", "instruction": "Escolha o phrasal verb correto.", "prompt": "We had to ___ the meeting until next Tuesday because the director was sick.", "options": ["put off", "put up with", "take off", "turn down"], "correctIndex": 0, "explain": "\"Put off\" significa adiar.", "id": "bkB2-40"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "odd", "instruction": "Encontre o intruso.", "prompt": "Which phrasal verb does NOT mean \"postpone\"?", "options": ["put off", "push back", "call off", "hold off"], "correctIndex": 2, "explain": "Put off, push back e hold off indicam adiar; \"call off\" significa cancelar.", "id": "bkB2-41"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "gaps", "instruction": "Complete o texto com os phrasal verbs do banco.", "prompt": "Last year, Bia decided to ___ a new hobby: rock climbing. At first, she almost ___ because it was so hard. After a few months, she ___ with the more experienced climbers. Now she ___ to her coach as a role model. Last week, she ___ an old photo of her first climb and laughed.", "bank": ["take up", "gave up", "caught up", "looks up", "came across", "ran out"], "answers": [["take up"], ["gave up"], ["caught up"], ["looks up"], ["came across"]], "explain": "take up: começar hobby; give up: desistir; catch up: alcançar; look up to: admirar; come across: encontrar por acaso.", "id": "bkB2-42"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "gaps", "instruction": "Complete com a partícula correta.", "prompt": "A: Did you find ___ what time the store opens?\nB: Not yet. I'll look it ___ online.\nA: Thanks. I've run ___ of data on my phone.", "answers": [["out"], ["up"], ["out"]], "explain": "find out: descobrir; look up: pesquisar; run out of: ficar sem.", "id": "bkB2-43"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "choose", "instruction": "Escolha o phrasal verb correto.", "prompt": "My grandmother [brought up*/grew up] five children on her own. Everyone in the family [looks up to*/looks up at] her.", "explain": "\"Bring up\" é criar filhos; \"look up to\" é admirar alguém.", "id": "bkB2-44"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "I can't put up to all this noise anymore.", "wrong": "to", "fix": ["with"], "explain": "O phrasal verb é \"put up with\" (tolerar, aguentar).", "id": "bkB2-45"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "match", "instruction": "Ligue cada phrasal verb ao seu significado.", "left": ["turn down", "come up with", "run into", "carry out", "figure out"], "right": ["to understand or solve", "to reject an offer", "to perform or complete a task", "to meet by chance", "to think of an idea"], "correctMap": [1, 4, 3, 2, 0], "explain": "Turn down: recusar; come up with: ter ideia; run into: encontrar por acaso; carry out: realizar; figure out: entender.", "id": "bkB2-46"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "sort", "prompt": "Separable or inseparable?", "instruction": "Classifique: o objeto pode ou não ficar no meio?", "groups": ["Separable (turn it down)", "Inseparable (look after her)"], "items": [{"w": "turn down", "g": 0}, {"w": "give back", "g": 0}, {"w": "put off", "g": 0}, {"w": "pick up", "g": 0}, {"w": "look after", "g": 1}, {"w": "run into", "g": 1}, {"w": "get over", "g": 1}, {"w": "come across", "g": 1}], "explain": "Nos separáveis o pronome fica no meio (turn it down); nos inseparáveis, depois (look after her).", "id": "bkB2-47"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Hey, are we still on for dinner tonight?", "B: Sorry, I have to call it off. Something came up at work.", "A: Oh no. Can we put it off until Friday, then?", "B: Friday works. I'll make it up to you, I promise!"], "explain": "call off: cancelar; come up: surgir; put off: adiar; make it up to: compensar.", "id": "bkB2-48"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "tf", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "When Diego moved to Toronto, he found it hard to fit in. He didn't know anyone, and the cold weather really got him down. Then he signed up for a salsa class, where he ran into an old friend from Porto Alegre. She introduced him to her friends, and soon he was hanging out with them every weekend. Now he says he can't imagine going back.", "items": [{"s": "At first, the weather made Diego feel sad.", "a": true}, {"s": "Diego met his old friend at work.", "a": false}, {"s": "Diego's friend introduced him to other people.", "a": true}, {"s": "Diego is planning to return to Brazil soon.", "a": false}], "explain": "get down: deixar triste; run into: encontrar por acaso; hang out: passar tempo juntos.", "id": "bkB2-49"}, {"level": "B2", "topic": "Wish & If only", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "I wish I ___ more time to read, but I work ten hours a day.", "options": ["have", "had", "would have", "have had"], "correctIndex": 1, "explain": "Desejo sobre o presente: wish + passado simples (had).", "id": "bkB2-50"}, {"level": "B2", "topic": "Wish & If only", "type": "gaps", "instruction": "Complete com a forma correta para arrependimentos.", "prompt": "I wish I ___ (not eat) so much at the party last night. If only I ___ (listen) to my mother!", "answers": [["had not eaten", "hadn't eaten"], ["had listened"]], "explain": "Arrependimento sobre o passado: wish/if only + past perfect.", "id": "bkB2-51"}, {"level": "B2", "topic": "Wish & If only", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "I wish my neighbor [would stop*/stops] playing loud music at night. If only I [lived*/live] somewhere quieter!", "explain": "Irritação com o comportamento de outra pessoa: wish + would; desejo sobre o presente: passado (lived).", "id": "bkB2-52"}, {"level": "B2", "topic": "Wish & If only", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "I wish I can speak Japanese fluently.", "wrong": "can", "fix": ["could"], "explain": "Com wish, \"can\" recua para \"could\" ao falar de habilidade desejada.", "id": "bkB2-53"}, {"level": "B2", "topic": "Wish & If only", "type": "rewrite", "instruction": "Reescreva a frase usando wish.", "prompt": "I'm sorry I didn't go to the concert.", "start": "I wish", "accept": ["I wish I had gone to the concert.", "I wish I'd gone to the concert."], "explain": "Arrependimento sobre o passado: wish + past perfect (had gone).", "id": "bkB2-54"}, {"level": "B2", "topic": "Wish & If only", "type": "rewrite", "instruction": "Reescreva a frase usando If only.", "prompt": "It's a pity we don't live near the beach.", "start": "If only", "accept": ["If only we lived near the beach.", "If only we lived closer to the beach."], "explain": "Desejo sobre o presente: if only + passado simples (lived).", "id": "bkB2-55"}, {"level": "B2", "topic": "Wish & If only", "type": "order", "instruction": "Organize as palavras para formar a frase.", "words": ["I", "wish", "you", "would", "stop", "interrupting", "me"], "explain": "Wish + would expressa irritação com a atitude de alguém.", "id": "bkB2-56"}, {"level": "B2", "topic": "Wish & If only", "type": "reading", "instruction": "Leia a mensagem e responda às perguntas.", "text": "Hi Marcos, Remember when we were at school and I always said I wished I could travel the world? Well, I'm writing this from a hostel in Peru! The trip has been amazing, but I wish I had packed warmer clothes—the mountains are freezing. I also wish my Spanish were better; I only know a few phrases. If only you were here with me! Hugs, Lia", "questions": [{"q": "Where is Lia now?", "options": ["At her old school", "In Peru", "In Brazil"], "correctIndex": 1}, {"q": "What problem does Lia mention?", "options": ["She lost her money.", "She doesn't like the hostel.", "She didn't bring warm enough clothes."], "correctIndex": 2}, {"q": "What does Lia wish about Marcos?", "options": ["That he were with her", "That he spoke Spanish", "That he had written to her"], "correctIndex": 0}], "explain": "Lia usa wish/if only para arrependimentos (had packed) e desejos no presente (were).", "id": "bkB2-57"}, {"level": "B2", "topic": "Wish & If only", "type": "tf", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Paulo is 40 and works at a bank in Belo Horizonte. He often says, \"If only I had studied music when I was younger.\" He also wishes his job were less stressful. His wife wishes he would spend less time on his phone. Last month, he finally started taking guitar lessons on Saturdays.", "items": [{"s": "Paulo regrets not studying music when he was young.", "a": true}, {"s": "Paulo is happy with how stressful his job is.", "a": false}, {"s": "Paulo's wife is unhappy about his phone use.", "a": true}, {"s": "Paulo has never had a guitar lesson.", "a": false}], "explain": "If only + past perfect = arrependimento; wish + would = reclamação sobre atitude.", "id": "bkB2-58"}, {"level": "B2", "topic": "Wish & If only", "type": "match", "instruction": "Ligue as duas partes das frases.", "left": ["I wish I owned", "I wish I were", "I wish you would", "If only we hadn't"], "right": ["on vacation right now.", "missed the last bus.", "a quieter apartment.", "turn down the music."], "correctMap": [2, 0, 3, 1], "explain": "owned + substantivo; were + lugar; would + verbo base; hadn't + particípio.", "id": "bkB2-59"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "mcq", "instruction": "Escolha a forma que dá ênfase.", "prompt": "You may not believe me, but I ___ lock the door before I left.", "options": ["do", "did", "does", "was"], "correctIndex": 1, "explain": "Ênfase no passado: did + verbo base (did lock).", "id": "bkB2-60"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "gaps", "instruction": "Complete o diálogo; use do/does/did para dar ênfase.", "prompt": "A: I don't think Marta likes her new job.\nB: She ___ like it! She just ___ (find) the commute tiring.", "answers": [["does"], ["finds"]], "explain": "\"Does like\" enfatiza o contrário; \"finds\" é o presente simples normal.", "id": "bkB2-61"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "I know you think Pedro is lazy, but he [does work*/works does] very hard. Last month, he [did finish*/did finished] the project on time.", "explain": "Ênfase: do/does/did antes do verbo, que fica na forma base.", "id": "bkB2-62"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "She does speaks three languages, believe it or not.", "wrong": "speaks", "fix": ["speak"], "explain": "Depois de \"does\" o verbo fica na forma base: does speak.", "id": "bkB2-63"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "rewrite", "instruction": "Reescreva dando ênfase com do/does/did.", "prompt": "I enjoyed the show.", "accept": ["I did enjoy the show.", "I really did enjoy the show.", "I did really enjoy the show."], "explain": "Ênfase no passado: did + verbo base (enjoy).", "id": "bkB2-64"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "rewrite", "instruction": "Torne o convite mais enfático e caloroso com \"do\".", "prompt": "Please sit down and make yourself at home.", "accept": ["Do sit down and make yourself at home.", "Please do sit down and make yourself at home.", "Do please sit down and make yourself at home."], "explain": "\"Do\" antes do imperativo deixa o convite mais enfático e educado.", "id": "bkB2-65"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "order", "instruction": "Organize as palavras para formar a frase.", "words": ["We", "did", "warn", "you", "about", "the", "traffic"], "explain": "\"Did warn\" enfatiza que o aviso realmente aconteceu.", "id": "bkB2-66"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Did you remember to buy milk?", "B: I did buy it, but I left it at the supermarket.", "A: Seriously? You do forget things a lot lately.", "B: I know. I really do need a vacation!"], "explain": "did buy, do forget e do need dão ênfase às afirmações.", "id": "bkB2-67"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "match", "instruction": "Ligue cada acusação à resposta enfática.", "left": ["\"You didn't pay the bill.\"", "\"She doesn't care about us.\"", "\"They don't want to help.\"", "\"You don't love me.\""], "right": ["\"I do love you!\"", "\"They do want to help, but they're busy.\"", "\"I did pay it! Here's the receipt.\"", "\"She does care. She just doesn't show it.\""], "correctMap": [2, 3, 1, 0], "explain": "Do/does/did enfático contradiz uma afirmação negativa.", "id": "bkB2-68"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "odd", "instruction": "Encontre a frase intrusa.", "prompt": "Which sentence does NOT use do/does/did for emphasis?", "options": ["I do like your haircut.", "She did call you last night.", "Do you like jazz?", "He does try his best."], "correctIndex": 2, "explain": "Em \"Do you like jazz?\" o \"do\" é auxiliar de pergunta, não de ênfase.", "id": "bkB2-69"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "Never ___ such a beautiful sunset.", "options": ["I have seen", "have I seen", "I saw", "did I saw"], "correctIndex": 1, "explain": "Após advérbio negativo no início, inverte-se auxiliar e sujeito: have I seen.", "id": "bkB2-70"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "gaps", "instruction": "Complete com o auxiliar correto.", "prompt": "Not only ___ Carla win the race, but she also broke the national record. Rarely ___ we see such talent!", "answers": [["did"], ["do"]], "explain": "Inversão com auxiliar: passado \"did Carla win\"; presente \"do we see\".", "id": "bkB2-71"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "Hardly [had I*/I had] closed the door when the phone [rang*/rings].", "explain": "\"Hardly\" no início pede inversão (had I) e a outra ação no passado (rang).", "id": "bkB2-72"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "Seldom we go to the cinema these days.", "wrong": "we go", "fix": ["do we go"], "explain": "\"Seldom\" no início exige inversão com auxiliar: do we go.", "id": "bkB2-73"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "rewrite", "instruction": "Reescreva começando com a palavra dada.", "prompt": "I have never tasted such delicious food.", "start": "Never", "accept": ["Never have I tasted such delicious food.", "Never before have I tasted such delicious food."], "explain": "Never + auxiliar + sujeito: \"Never have I tasted\".", "id": "bkB2-74"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "rewrite", "instruction": "Reescreva começando com a expressão dada.", "prompt": "You should not open this door under any circumstances.", "start": "Under no circumstances", "accept": ["Under no circumstances should you open this door."], "explain": "Under no circumstances + auxiliar + sujeito: \"should you open\".", "id": "bkB2-75"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "order", "instruction": "Organize as palavras para formar a frase.", "words": ["Little", "did", "they", "know", "about", "the", "surprise", "party"], "explain": "\"Little did they know\" = eles nem imaginavam; inversão com did.", "id": "bkB2-76"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "reading", "instruction": "Leia o aviso e responda às perguntas.", "text": "IMPORTANT NOTICE – City Library. Under no circumstances may food or drinks be taken into the reading rooms. Not only does this protect our books, but it also keeps the rooms clean for everyone. Only after showing your library card will you be allowed to borrow books. Rarely do we make exceptions to these rules. Thank you for your cooperation.", "questions": [{"q": "Can you take a coffee into the reading rooms?", "options": ["Yes, if it has a lid.", "No, never.", "Only in the morning."], "correctIndex": 1}, {"q": "What do you need in order to borrow books?", "options": ["A reservation", "Some money", "Your library card"], "correctIndex": 2}, {"q": "How often does the library make exceptions?", "options": ["Very rarely", "Every day", "Only on weekends"], "correctIndex": 0}], "explain": "As inversões (Under no circumstances, Only after, Rarely) reforçam as regras.", "id": "bkB2-77"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "tf", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Last summer, Renata went hiking in Chapada Diamantina. No sooner had she arrived than it started to rain heavily. Not only did she get wet, but she also lost her map. At no point, however, did she think about giving up. Only when she reached the top of the waterfall did she realize how tired she was.", "items": [{"s": "It started raining soon after Renata arrived.", "a": true}, {"s": "Renata considered quitting the hike.", "a": false}, {"s": "Renata lost her map.", "a": true}, {"s": "Renata stayed dry during the hike.", "a": false}], "explain": "No sooner = logo que; at no point = em nenhum momento; not only = não só.", "id": "bkB2-78"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "match", "instruction": "Ligue as duas partes das frases.", "left": ["No sooner had", "Hardly had", "Under no circumstances should", "Not until I got home"], "right": ["did I notice my wallet was missing.", "you share your password with anyone.", "we sat down than the waiter brought the menu.", "the movie started when the lights went out."], "correctMap": [2, 3, 1, 0], "explain": "No sooner... than; hardly... when; should + sujeito + verbo; not until... did + sujeito.", "id": "bkB2-79"}, {"level": "B2", "topic": "Collocations avançadas", "type": "mcq", "instruction": "Escolha o verbo que forma a collocation correta.", "prompt": "Our team ___ significant progress on the project last year.", "options": ["made", "did", "took", "gave"], "correctIndex": 0, "explain": "A collocation é \"make progress\".", "id": "bkB2-80"}, {"level": "B2", "topic": "Collocations avançadas", "type": "odd", "instruction": "Encontre o intruso.", "prompt": "Which word does NOT go with \"heavy\"?", "options": ["rain", "traffic", "smoker", "mistake"], "correctIndex": 3, "explain": "Dizemos heavy rain, heavy traffic, heavy smoker; mas \"a big/serious mistake\".", "id": "bkB2-81"}, {"level": "B2", "topic": "Collocations avançadas", "type": "odd", "instruction": "Encontre o intruso.", "prompt": "Which word does NOT go with \"pay\"?", "options": ["attention", "a compliment", "a visit", "a decision"], "correctIndex": 3, "explain": "Pay attention, pay a compliment, pay a visit; mas \"make a decision\".", "id": "bkB2-82"}, {"level": "B2", "topic": "Collocations avançadas", "type": "gaps", "instruction": "Complete o texto com os verbos do banco.", "prompt": "Starting a business is never easy. First, you have to ___ research on the market. Then you need to ___ a risk and invest your savings. If things go well, you'll ___ a profit in a year or two. Along the way, you must ___ attention to your customers and ___ your promises.", "bank": ["do", "take", "make", "pay", "keep", "give"], "answers": [["do"], ["take"], ["make"], ["pay"], ["keep"]], "explain": "do research, take a risk, make a profit, pay attention, keep a promise.", "id": "bkB2-83"}, {"level": "B2", "topic": "Collocations avançadas", "type": "choose", "instruction": "Escolha a palavra que forma a collocation correta.", "prompt": "It was a [bitterly*/strongly] cold morning, but the kids were [wide*/far] awake at 6 a.m. The snow came as a [complete*/strong] surprise.", "explain": "Collocations fixas: bitterly cold, wide awake, a complete surprise.", "id": "bkB2-84"}, {"level": "B2", "topic": "Collocations avançadas", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "She did a big effort to finish the marathon.", "wrong": "did", "fix": ["made"], "explain": "A collocation é \"make an effort\", não \"do an effort\".", "id": "bkB2-85"}, {"level": "B2", "topic": "Collocations avançadas", "type": "match", "instruction": "Ligue o verbo ao complemento correto.", "left": ["strike", "raise", "meet", "draw", "break"], "right": ["a deadline", "a conclusion", "a balance", "the ice", "awareness"], "correctMap": [2, 4, 0, 1, 3], "explain": "strike a balance, raise awareness, meet a deadline, draw a conclusion, break the ice.", "id": "bkB2-86"}, {"level": "B2", "topic": "Collocations avançadas", "type": "sort", "prompt": "Strong or heavy?", "instruction": "Classifique: qual adjetivo combina com cada palavra?", "groups": ["strong", "heavy"], "items": [{"w": "coffee", "g": 0}, {"w": "argument", "g": 0}, {"w": "opinion", "g": 0}, {"w": "possibility", "g": 0}, {"w": "rain", "g": 1}, {"w": "traffic", "g": 1}, {"w": "smoker", "g": 1}, {"w": "meal", "g": 1}], "explain": "strong coffee/argument/opinion/possibility; heavy rain/traffic/smoker/meal.", "id": "bkB2-87"}, {"level": "B2", "topic": "Collocations avançadas", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: How was the job interview?", "B: I think I made a good impression. They asked me to give a short presentation.", "A: Did you manage to keep calm?", "B: Mostly, but I nearly lost my train of thought at one point.", "A: Well, you did your best. Now you just have to wait."], "explain": "make an impression, give a presentation, keep calm, lose your train of thought.", "id": "bkB2-88"}, {"level": "B2", "topic": "Collocations avançadas", "type": "reading", "instruction": "Leia o e-mail e responda às perguntas.", "text": "Dear team, Thank you for all your hard work this year. We have made great progress, and our sales have risen sharply. However, we must pay close attention to customer feedback, as some clients have raised concerns about delivery times. Next month, we will hold a meeting to address these issues and draw up a new plan. Please come prepared to share your ideas. Best regards, Helena", "questions": [{"q": "How did sales change this year?", "options": ["They fell slightly.", "They increased a lot.", "They stayed the same."], "correctIndex": 1}, {"q": "What have some clients complained about?", "options": ["Delivery times", "Prices", "Rude staff"], "correctIndex": 0}, {"q": "What will happen next month?", "options": ["New staff will be hired.", "There will be a party.", "There will be a meeting to create a new plan."], "correctIndex": 2}], "explain": "rise sharply = subir muito; raise concerns = reclamar; draw up a plan = elaborar um plano.", "id": "bkB2-89"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "mcq", "instruction": "Escolha o conector correto.", "prompt": "___ the heavy rain, the concert went ahead as planned.", "options": ["Despite", "Although", "However", "Because"], "correctIndex": 0, "explain": "\"Despite\" vem antes de substantivo; \"although\" exige sujeito e verbo.", "id": "bkB2-90"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "gaps", "instruction": "Complete com conectores de causa e contraste.", "prompt": "The flight was delayed ___ to the storm. ___ this, we still made it to the wedding on time.", "answers": [["due", "owing"], ["Despite", "In spite of"]], "explain": "\"Due/Owing to\" indica causa; \"Despite this\" indica contraste com a frase anterior.", "id": "bkB2-91"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "choose", "instruction": "Escolha os conectores corretos.", "prompt": "[Although*/Despite] she was exhausted, she kept working. [Owing to*/Even though] a strike, all the buses were canceled.", "explain": "\"Although\" + oração com verbo; \"owing to\" + substantivo para indicar causa.", "id": "bkB2-92"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "In spite of it was cold, we went swimming.", "wrong": "In spite of", "fix": ["Although", "Even though", "Though", "In spite of the fact that", "Despite the fact that"], "explain": "\"In spite of\" vem antes de substantivo; antes de oração use although/even though.", "id": "bkB2-93"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "rewrite", "instruction": "Reescreva a frase começando com \"Despite\".", "prompt": "Although he had a lot of experience, he didn't get the job.", "start": "Despite", "accept": ["Despite having a lot of experience, he didn't get the job.", "Despite his experience, he didn't get the job.", "Despite having had a lot of experience, he didn't get the job.", "Despite the fact that he had a lot of experience, he didn't get the job.", "Despite his extensive experience, he didn't get the job.", "Despite his vast experience, he didn't get the job.", "Despite his great experience, he didn't get the job.", "Despite his long experience, he didn't get the job.", "Despite all his experience, he didn't get the job."], "explain": "\"Despite\" + gerúndio, substantivo ou \"the fact that\" + oração.", "id": "bkB2-94"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "rewrite", "instruction": "Junte as duas frases começando com \"Owing to\".", "prompt": "The roads were icy. Many schools were closed.", "start": "Owing to", "accept": ["Owing to the icy roads, many schools were closed.", "Owing to icy roads, many schools were closed.", "Owing to the fact that the roads were icy, many schools were closed.", "Owing to the ice on the roads, many schools were closed."], "explain": "\"Owing to\" + substantivo (the icy roads) indica a causa.", "id": "bkB2-95"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "order", "instruction": "Organize as palavras para formar a frase.", "words": ["Whereas", "my", "brother", "loves", "football", "I", "prefer", "volleyball"], "alt": ["I prefer volleyball whereas my brother loves football", "My brother loves football whereas I prefer volleyball"], "explain": "\"Whereas\" contrasta dois fatos opostos.", "id": "bkB2-96"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Did you enjoy the trip to Salvador?", "B: Yes, even though it rained most of the time.", "A: That's a shame. Did you get to see the old town, though?", "B: We did. However, we had to skip the beach because of the rain."], "explain": "even though, though e however marcam contraste; because of indica causa.", "id": "bkB2-97"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "tf", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Although Brazil has one of the largest rainforests in the world, deforestation is still a serious problem. Due to illegal logging and cattle farming, large areas of the Amazon have been destroyed. Nevertheless, some progress has been made in recent years, as the government has increased monitoring. Whereas some people see the forest mainly as an economic resource, others believe it must be protected at all costs.", "items": [{"s": "The text says deforestation is no longer a problem.", "a": false}, {"s": "Cattle farming is mentioned as a cause of deforestation.", "a": true}, {"s": "According to the text, there has been no progress at all.", "a": false}, {"s": "People have different opinions about the forest.", "a": true}], "explain": "due to = causa; nevertheless e whereas = contraste.", "id": "bkB2-98"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "match", "instruction": "Ligue as duas partes das frases.", "left": ["The restaurant was expensive;", "Owing to a technical problem,", "Even though she had a map,", "Tom is outgoing,"], "right": ["the show started an hour late.", "nevertheless, we ate there every week.", "whereas his twin brother is very shy.", "she got lost in the old town."], "correctMap": [1, 0, 3, 2], "explain": "nevertheless e even though = contraste; owing to = causa; whereas = comparação oposta.", "id": "bkB2-99"}, {"level": "B2", "topic": "Reported Speech", "type": "mcq", "instruction": "Escolha o verbo introdutório correto.", "prompt": "My boss ___ me to double-check the figures before sending them.", "options": ["said", "suggested", "reminded", "apologized"], "correctIndex": 2, "explain": "\"remind + objeto + to\" está certo; suggest, say e apologize não seguem esse padrão.", "id": "bkB2-100"}, {"level": "B2", "topic": "Reported Speech", "type": "mcq", "instruction": "Escolha o verbo que completa o discurso indireto.", "prompt": "\"You should see a specialist,\" the doctor told Marcos. → The doctor ___ Marcos to see a specialist.", "options": ["suggested", "advised", "said", "insisted"], "correctIndex": 1, "explain": "\"advise + objeto + to\" relata conselhos (should). Suggest, say e insist não usam objeto + to.", "id": "bkB2-101"}, {"level": "B2", "topic": "Reported Speech", "type": "mcq", "instruction": "Escolha a expressão de tempo adequada.", "prompt": "Monday: Lara said, \"I'll finish the report today.\" → Friday: \"Lara said she would finish the report ___, but she didn't.\"", "options": ["today", "that day", "the day before", "the following day"], "correctIndex": 1, "explain": "Relatado dias depois, \"today\" vira \"that day\" (o próprio dia da fala).", "id": "bkB2-102"}, {"level": "B2", "topic": "Reported Speech", "type": "gaps", "instruction": "Complete aplicando o backshift aos modais.", "prompt": "Direct: \"You must wear a helmet. You may feel nervous at first, but you can stop at any time.\"\nReported: The instructor said we ___ wear a helmet. He added that we ___ feel nervous at first but that we ___ stop at any time.", "answers": [["had to", "must"], ["might"], ["could"]], "explain": "must → had to; may → might; can → could no discurso indireto.", "id": "bkB2-103"}, {"level": "B2", "topic": "Reported Speech", "type": "gaps", "instruction": "Complete com as mudanças de lugar e tempo.", "prompt": "Direct: \"I was here yesterday, and I'll come back tomorrow.\"\nReported: Bruno said he had been ___ the day ___ and would come back the ___ day.", "answers": [["there"], ["before"], ["next", "following"]], "explain": "here → there; yesterday → the day before; tomorrow → the next/following day.", "id": "bkB2-104"}, {"level": "B2", "topic": "Reported Speech", "type": "gaps", "instruction": "Complete o texto com os verbos do banco.", "prompt": "At the meeting, Sônia ___ taking a short break, and everyone agreed. Rodrigo ___ that he had made a mistake in the budget and apologized. The manager ___ to give him extra time, but Rodrigo ___ it and said he would fix it himself. Later, Sônia ___ having seen the email, although it was clearly open on her screen.", "bank": ["suggested", "admitted", "offered", "refused", "denied", "told"], "answers": [["suggested"], ["admitted"], ["offered"], ["refused"], ["denied"]], "explain": "suggest + -ing; admit (confessar); offer to; refuse (recusar); deny + -ing (negar).", "id": "bkB2-105"}, {"level": "B2", "topic": "Reported Speech", "type": "choose", "instruction": "Escolha entre say e tell.", "prompt": "Rafael [told*/said] us that the store was closed, and he [said*/told] it would reopen on Monday.", "explain": "\"tell\" exige objeto (told us); \"said\" vem sem objeto pessoal direto.", "id": "bkB2-106"}, {"level": "B2", "topic": "Reported Speech", "type": "choose", "instruction": "Escolha a forma correta para verdades gerais.", "prompt": "My grandfather always told us that the Earth [goes*/had gone] around the Sun and that honesty [is*/had been] the best policy.", "explain": "Fatos sempre verdadeiros podem manter o presente no discurso indireto.", "id": "bkB2-107"}, {"level": "B2", "topic": "Reported Speech", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "She told that she was going to be late for dinner.", "wrong": "told", "fix": ["said", "told me", "told us"], "explain": "\"tell\" exige objeto (told me); sem objeto, use \"said\".", "id": "bkB2-108"}, {"level": "B2", "topic": "Reported Speech", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "Julia suggested to go to the beach after lunch.", "wrong": "to go", "fix": ["going", "that we go", "that we should go"], "explain": "\"suggest\" não aceita \"to + verbo\": use -ing ou \"that we (should) + verbo\".", "id": "bkB2-109"}, {"level": "B2", "topic": "Reported Speech", "type": "rewrite", "instruction": "Passe a pergunta para o discurso indireto.", "prompt": "\"Have you finished the report?\" my manager asked me.", "start": "My manager asked me", "accept": ["My manager asked me if I had finished the report.", "My manager asked me whether I had finished the report.", "My manager asked me if I'd finished the report.", "My manager asked me whether I'd finished the report."], "explain": "Pergunta sim/não: if/whether + ordem direta; present perfect vira past perfect.", "id": "bkB2-110"}, {"level": "B2", "topic": "Reported Speech", "type": "rewrite", "instruction": "Reescreva usando o verbo \"deny\".", "prompt": "\"I didn't break the window,\" said Leo.", "start": "Leo denied", "accept": ["Leo denied breaking the window.", "Leo denied having broken the window.", "Leo denied that he had broken the window.", "Leo denied that he broke the window.", "Leo denied that he'd broken the window."], "explain": "\"deny\" + -ing (ou having + particípio, ou that + past perfect) relata uma negação.", "id": "bkB2-111"}, {"level": "B2", "topic": "Reported Speech", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["He", "warned", "us", "not", "to", "swim", "near", "the", "rocks"], "explain": "\"warn + objeto + not to + verbo\" relata um aviso negativo.", "id": "bkB2-112"}, {"level": "B2", "topic": "Reported Speech", "type": "match", "instruction": "Ligue a expressão direta à forma indireta.", "left": ["today", "yesterday", "next week", "two days ago", "here"], "right": ["the following week", "there", "that day", "two days before", "the day before"], "correctMap": [2, 4, 0, 3, 1], "explain": "No discurso indireto, as referências de tempo e lugar mudam.", "id": "bkB2-113"}, {"level": "B2", "topic": "Reported Speech", "type": "match", "instruction": "Ligue a fala direta ao relato correto.", "left": ["\"I'll carry your bags.\"", "\"Don't forget to call Mom.\"", "\"I'm sorry I was late.\"", "\"Be careful, the floor is wet.\""], "right": ["She reminded me to call Mom.", "She apologized for being late.", "She warned me that the floor was wet.", "She offered to carry my bags."], "correctMap": [3, 0, 1, 2], "explain": "Cada verbo introdutório resume a função: offer, remind, apologize, warn.", "id": "bkB2-114"}, {"level": "B2", "topic": "Reported Speech", "type": "sort", "instruction": "Classifique pelo padrão que o verbo introdutório usa.", "prompt": "Which pattern does each reporting verb take?", "groups": ["Verb + to-infinitive", "Verb + -ing"], "items": [{"w": "promise", "g": 0}, {"w": "deny", "g": 1}, {"w": "refuse", "g": 0}, {"w": "suggest", "g": 1}, {"w": "offer", "g": 0}, {"w": "admit", "g": 1}, {"w": "agree", "g": 0}, {"w": "recommend", "g": 1}], "explain": "promise, refuse, offer, agree + to; deny, suggest, admit, recommend + -ing.", "id": "bkB2-115"}, {"level": "B2", "topic": "Reported Speech", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: What did the teacher say about the exam?", "B: She told us it would be harder than the last one.", "A: Did she say which chapters to study?", "B: Yes, she said we should focus on chapters four and five.", "A: OK, then I'll start with chapter four tonight."], "explain": "B relata o que a professora disse usando backshift (would, should).", "id": "bkB2-116"}, {"level": "B2", "topic": "Reported Speech", "type": "tf", "instruction": "Leia e marque verdadeiro ou falso.", "text": "Last night, Heloísa called her brother Caio from Lisbon. She told him that she had found a job at a design studio and would start the following Monday. Caio asked her whether she was planning to stay in Portugal for good. Heloísa said she didn't know yet, but that she missed Brazilian food a lot. She also asked him to send her some coffee from Minas.", "items": [{"s": "Heloísa said she had already started her new job.", "a": false}, {"s": "Caio wanted to know if she would live in Portugal permanently.", "a": true}, {"s": "Heloísa said she had decided to stay in Portugal forever.", "a": false}, {"s": "Heloísa asked Caio to send her some coffee.", "a": true}], "explain": "O texto relata falas com backshift: \"would start\", \"whether she was planning\".", "id": "bkB2-117"}, {"level": "B2", "topic": "Reported Speech", "type": "reading", "instruction": "Leia a mensagem e responda.", "text": "Hi Duda, Just a quick update from the meeting you missed. Mr. Nogueira said the deadline had been moved to the 15th. He asked whether anyone could help the marketing team, and Thiago offered to do it. Mr. Nogueira also reminded us not to use the old logo anymore. Finally, he told us the office would be closed next Friday for maintenance. See you tomorrow, Bia", "questions": [{"q": "What did Mr. Nogueira say about the deadline?", "options": ["It had been changed.", "It had been canceled.", "It was the next day."], "correctIndex": 0}, {"q": "Who volunteered to help the marketing team?", "options": ["Bia", "Thiago", "Mr. Nogueira"], "correctIndex": 1}, {"q": "What were they reminded about?", "options": ["To come in on Friday", "To send the report by the 15th", "To stop using the old logo"], "correctIndex": 2}], "explain": "A mensagem relata a reunião em discurso indireto (said, asked, offered, reminded).", "id": "bkB2-118"}, {"level": "B2", "topic": "Reported Speech", "type": "blank", "instruction": "Complete no discurso indireto.", "prompt": "\"I'm waiting for the bus,\" said Nina. → Nina said she ___ (wait) for the bus.", "accept": ["was waiting"], "explain": "Present continuous (am waiting) vira past continuous (was waiting).", "id": "bkB2-119"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "mcq", "instruction": "Escolha a forma correta (condicional mista).", "prompt": "If Camila ___ so afraid of flying, she would have visited us in Lisbon last year.", "options": ["weren't", "hadn't", "wouldn't be", "isn't"], "correctIndex": 0, "explain": "Condição presente/permanente (weren't) com resultado no passado (would have visited).", "id": "bkB2-120"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "mcq", "instruction": "Escolha a forma correta da pergunta.", "prompt": "What ___ yesterday if you hadn't found your passport in time?", "options": ["would you do", "would you have done", "had you done", "did you do"], "correctIndex": 1, "explain": "Third conditional: resultado no passado = would have + particípio.", "id": "bkB2-121"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "If it ___ for my sister's help last year, I would never have finished my thesis.", "options": ["weren't", "hadn't been", "wasn't", "wouldn't have been"], "correctIndex": 1, "explain": "\"If it hadn't been for...\" = se não fosse por (algo no passado).", "id": "bkB2-122"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "gaps", "instruction": "Complete com a third conditional.", "prompt": "If the referee ___ (not / cancel) the goal, our team ___ (win) the final last Sunday.", "answers": [["hadn't canceled", "had not canceled", "hadn't cancelled", "had not cancelled"], ["would have won", "might have won", "could have won"]], "explain": "If + past perfect, would/could/might have + particípio para o passado irreal.", "id": "bkB2-123"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "gaps", "instruction": "Complete com a condicional mista.", "prompt": "If I ___ (accept) that job in São Paulo, I ___ (live) there now.", "answers": [["had accepted"], ["would be living", "would live", "might be living", "could be living", "might live", "could live"]], "explain": "Condição passada (had accepted) com resultado presente (would be living).", "id": "bkB2-124"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "gaps", "instruction": "Complete o diálogo.", "prompt": "A: Why didn't you tell me about the party?\nB: I thought you were busy. If I ___ (know) you were free, I ___ (invite) you.\nA: Well, if you ___ (ask), you'd know I'm always free on Fridays!", "answers": [["had known"], ["would have invited", "could have invited", "might have invited"], ["had asked"]], "explain": "Third conditional (had known / would have invited) e mista (had asked → you'd know now).", "id": "bkB2-125"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "If Diego weren't so impatient in general, he [wouldn't have shouted*/wouldn't shout] at the waiter yesterday. If we [had checked*/checked] the forecast, we wouldn't have gone sailing.", "explain": "Traço permanente (weren't) + resultado passado; condição passada exige past perfect.", "id": "bkB2-126"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "I [could have gotten*/could get] a discount if I [had shown*/showed] my student card at the counter, but I forgot.", "explain": "Situação passada (\"I forgot\"): could have + particípio e if + past perfect.", "id": "bkB2-127"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "If they had checked the tires, the accident wouldn't happen.", "wrong": "wouldn't happen", "fix": ["wouldn't have happened", "would not have happened", "might not have happened", "couldn't have happened", "could not have happened"], "explain": "Resultado no passado pede would have + particípio.", "id": "bkB2-128"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "If I had gone to bed earlier last night, I wouldn't have been so tired now.", "wrong": "wouldn't have been", "fix": ["wouldn't be", "would not be"], "explain": "\"now\" indica resultado presente: condicional mista com would be.", "id": "bkB2-129"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "rewrite", "instruction": "Reescreva com a third conditional.", "prompt": "Rafa didn't wear sunscreen, so he got sunburned.", "start": "If Rafa had worn", "accept": ["If Rafa had worn sunscreen, he wouldn't have gotten sunburned.", "If Rafa had worn sunscreen, he wouldn't have got sunburned.", "If Rafa had worn sunscreen, he wouldn't have been sunburned.", "If Rafa had worn sunscreen, he wouldn't have gotten a sunburn.", "If Rafa had worn sunscreen, he wouldn't have got a sunburn.", "If Rafa had worn sunscreen, he would not have gotten sunburned.", "If Rafa had worn sunscreen, he would not have got sunburned.", "If Rafa had worn sunscreen, he would not have been sunburned.", "If Rafa had worn sunscreen, he would not have gotten a sunburn.", "If Rafa had worn sunscreen, he would not have got a sunburn."], "explain": "If + past perfect, wouldn't have + particípio.", "id": "bkB2-130"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "rewrite", "instruction": "Reescreva com a condicional mista.", "prompt": "Lia is afraid of the ocean, so she didn't go diving with us.", "start": "If Lia weren't", "accept": ["If Lia weren't afraid of the ocean, she would have gone diving with us.", "If Lia weren't afraid of the ocean, she might have gone diving with us.", "If Lia weren't afraid of the ocean, she could have gone diving with us.", "If Lia weren't so afraid of the ocean, she would have gone diving with us."], "explain": "Condição presente (weren't afraid) com resultado passado (would have gone).", "id": "bkB2-131"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["We", "wouldn't", "have", "gotten", "lost", "if", "we", "had", "used", "the", "GPS"], "alt": ["If we had used the GPS we wouldn't have gotten lost"], "explain": "Resultado (wouldn't have gotten) + if + past perfect.", "id": "bkB2-132"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["If", "she", "had", "taken", "the", "job", "she", "would", "be", "rich", "now"], "alt": ["She would be rich now if she had taken the job", "She would now be rich if she had taken the job", "If she had taken the job she would now be rich"], "explain": "Mista: condição passada (had taken) + resultado presente (would be ... now).", "id": "bkB2-133"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "match", "instruction": "Ligue as metades das frases.", "left": ["If I had saved more money,", "If I were better at math,", "If Nando hadn't overslept,", "If you had told me earlier,"], "right": ["he wouldn't have missed the bus.", "I would be on vacation now.", "I wouldn't have made other plans for tonight.", "I wouldn't have failed the test last week."], "correctMap": [1, 3, 0, 2], "explain": "Observe o tempo: now = resultado presente; last week/tonight = contexto específico.", "id": "bkB2-134"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "match", "instruction": "Ligue o fato à frase condicional correspondente.", "left": ["I missed the train, so I was late.", "I don't speak German, so I didn't understand the guide.", "She broke her arm, so she can't play today.", "We didn't book a table, so we had to wait."], "right": ["If she hadn't broken her arm, she could play today.", "If we had booked a table, we wouldn't have had to wait.", "If I hadn't missed the train, I wouldn't have been late.", "If I spoke German, I would have understood the guide."], "correctMap": [2, 3, 0, 1], "explain": "A condicional inverte o fato real: afirmativo vira negativo e vice-versa.", "id": "bkB2-135"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "sort", "instruction": "Classifique: third ou mista?", "prompt": "Third or mixed conditional?", "groups": ["Third conditional", "Mixed conditional"], "items": [{"w": "If I had known, I would have come.", "g": 0}, {"w": "If I had slept more, I wouldn't be tired now.", "g": 1}, {"w": "If she had studied, she would have passed.", "g": 0}, {"w": "If he were taller, he would have joined the team.", "g": 1}, {"w": "If they had left earlier, they would have caught the train.", "g": 0}, {"w": "If we hadn't moved, we would still live in Recife.", "g": 1}], "explain": "Third: passado + passado. Mista: mistura presente e passado.", "id": "bkB2-136"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: You look upset. What happened?", "B: I failed my driving test this morning.", "A: Oh no! What went wrong?", "B: I didn't stop at a stop sign. If I had been more careful, I would have passed.", "A: Don't worry. If you practice a bit more, you'll pass next time."], "explain": "B usa a third conditional para falar do erro no teste.", "id": "bkB2-137"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "reading", "instruction": "Leia o texto e responda.", "text": "Two years ago, Otávio was offered a job in Canada, but he turned it down because he didn't want to leave his family. Last month, his former colleague Pietra, who had accepted a similar offer, visited him in Recife. She told him about her life in Vancouver: the high salary, the snow, the long winters. \"If I had gone, I would be earning twice as much now,\" Otávio thought. But then he looked at his kids playing in the yard. \"If I had left, I wouldn't have seen them grow up,\" he said to himself, smiling.", "questions": [{"q": "Why did Otávio refuse the job?", "options": ["He didn't want to leave his family.", "The salary was too low.", "He hates cold weather."], "correctIndex": 0}, {"q": "Who moved to Canada?", "options": ["Otávio", "Pietra", "Otávio's kids"], "correctIndex": 1}, {"q": "How does Otávio feel about his decision in the end?", "options": ["He regrets it deeply.", "He is at peace with it.", "He is angry with Pietra."], "correctIndex": 1}], "explain": "Otávio usa condicionais mistas e third para refletir sobre a decisão.", "id": "bkB2-138"}, {"level": "B2", "topic": "Third & Mixed Conditionals", "type": "blank", "instruction": "Complete com a forma correta.", "prompt": "Had I known about the bus strike, I ___ (take) a taxi.", "accept": ["would have taken", "could have taken", "might have taken"], "explain": "\"Had I known\" = If I had known; resultado com would have + particípio.", "id": "bkB2-139"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "mcq", "instruction": "Escolha a forma passiva correta.", "prompt": "When we arrived at the hotel, our room ___, so we had to wait in the lobby.", "options": ["was still being cleaned", "was still cleaning", "has still been cleaned", "is still cleaned"], "correctIndex": 0, "explain": "Ação em andamento no passado na passiva: was being + particípio.", "id": "bkB2-140"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "The suspect is believed ___ the country last night.", "options": ["to leave", "to have left", "having left", "to be leaving"], "correctIndex": 1, "explain": "Passiva impessoal com ação anterior: be believed + to have + particípio.", "id": "bkB2-141"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "I hate ___ when I'm speaking.", "options": ["interrupting", "being interrupted", "to interrupt", "be interrupted"], "correctIndex": 1, "explain": "hate + gerúndio passivo: being + particípio.", "id": "bkB2-142"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "gaps", "instruction": "Complete com a passiva no tempo correto.", "prompt": "By the time the firefighters arrived, most of the building ___ (destroy). Fortunately, nobody ___ (injure).", "answers": [["had been destroyed"], ["was injured", "had been injured"]], "explain": "Ação anterior a outra no passado: had been + particípio; fato passado: was + particípio.", "id": "bkB2-143"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "gaps", "instruction": "Complete o texto com a passiva nos tempos corretos.", "prompt": "Every year, thousands of tons of coffee ___ (produce) in Minas Gerais. Right now, new farming methods ___ (test) by local researchers. So far, excellent results ___ (achieve), and the whole region ___ (expect) to use them by 2030.", "answers": [["are produced"], ["are being tested"], ["have been achieved"], ["is expected"]], "explain": "Presente simples, contínuo, perfeito e \"is expected to\" na passiva.", "id": "bkB2-144"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "gaps", "instruction": "Complete com a passiva após o modal.", "prompt": "This medicine must ___ (keep) in the fridge. It shouldn't ___ (give) to children under 12.", "answers": [["be kept"], ["be given"]], "explain": "Modal + be + particípio.", "id": "bkB2-145"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "choose", "instruction": "Escolha as formas passivas corretas.", "prompt": "The winners [will be announced*/will announce] tomorrow, and the prizes [will have been*/will have] delivered by the end of the month.", "explain": "Futuro: will be + particípio; futuro perfeito: will have been + particípio.", "id": "bkB2-146"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "Marta [was given*/was giving] a bouquet of flowers after her speech. The flowers [had been sent*/had sent] by her students.", "explain": "Passiva com dois objetos (was given) e past perfect passivo (had been sent).", "id": "bkB2-147"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "The thieves are thought to have been escaped through the window.", "wrong": "have been escaped", "fix": ["have escaped"], "explain": "\"escape\" é intransitivo; o infinitivo perfeito ativo é \"to have escaped\".", "id": "bkB2-148"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "My phone was stealing while I was on the bus.", "wrong": "was stealing", "fix": ["was stolen", "got stolen"], "explain": "O celular sofreu a ação: passiva was/got + particípio (stolen).", "id": "bkB2-149"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "rewrite", "instruction": "Passe para a voz passiva.", "prompt": "They were painting the house when we visited.", "start": "The house", "accept": ["The house was being painted when we visited."], "explain": "Past continuous passivo: was being + particípio.", "id": "bkB2-150"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "rewrite", "instruction": "Reescreva com a passiva impessoal.", "prompt": "People say that the old mansion is haunted.", "start": "The old mansion", "accept": ["The old mansion is said to be haunted."], "explain": "People say that X is... → X is said to be...", "id": "bkB2-151"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "rewrite", "instruction": "Passe para a passiva começando pela pessoa.", "prompt": "Someone gave Pedro a scholarship.", "start": "Pedro", "accept": ["Pedro was given a scholarship."], "explain": "Com dois objetos, a pessoa pode ser o sujeito: Pedro was given...", "id": "bkB2-152"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["The", "meeting", "should", "have", "been", "canceled", "earlier"], "explain": "Modal perfeito passivo: should have been + particípio.", "id": "bkB2-153"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["Our", "flight", "is", "being", "delayed", "because", "of", "the", "fog"], "alt": ["Because of the fog our flight is being delayed"], "explain": "Present continuous passivo: is being + particípio.", "id": "bkB2-154"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "match", "instruction": "Ligue a frase ativa à passiva correspondente.", "left": ["They are repairing the road.", "They had repaired the road.", "They will have repaired the road.", "They might repair the road."], "right": ["The road will have been repaired.", "The road might be repaired.", "The road is being repaired.", "The road had been repaired."], "correctMap": [2, 3, 0, 1], "explain": "O tempo verbal se mantém: são as formas de \"be\" que mudam.", "id": "bkB2-155"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "sort", "instruction": "Classifique as formas passivas.", "prompt": "Continuous, perfect or modal passive?", "groups": ["Continuous", "Perfect", "Modal"], "items": [{"w": "is being built", "g": 0}, {"w": "has been sold", "g": 1}, {"w": "should be signed", "g": 2}, {"w": "was being checked", "g": 0}, {"w": "had been warned", "g": 1}, {"w": "must be returned", "g": 2}, {"w": "were being followed", "g": 0}, {"w": "can be recycled", "g": 2}], "explain": "Contínuo: being; perfeito: been após have/had; modal: modal + be.", "id": "bkB2-156"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "tf", "instruction": "Leia e marque verdadeiro ou falso.", "text": "The old train station in Campinas, which was built in 1884, is being turned into a cultural center. The project was approved last year, after the building had been abandoned for decades. The work is being paid for by the city and a private bank. When it is finished, the center will be used for concerts, exhibitions and workshops. It is expected to open next spring.", "items": [{"s": "The station is currently being transformed.", "a": true}, {"s": "The building was in use until last year.", "a": false}, {"s": "The project is being financed only by the city.", "a": false}, {"s": "The center is expected to open next spring.", "a": true}], "explain": "O texto usa passivas em vários tempos: is being turned, had been abandoned, is being paid.", "id": "bkB2-157"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Excuse me, has my car been fixed yet?", "B: Not yet, sir. It's being checked by our mechanic right now.", "A: When do you think it will be ready?", "B: It should be finished by four o'clock.", "A: Great. Will I be notified when it's done?", "B: Yes, you'll be sent a text message."], "explain": "O diálogo usa passivas: has been fixed, is being checked, should be finished.", "id": "bkB2-158"}, {"level": "B2", "topic": "Passiva avançada (todos os tempos)", "type": "odd", "instruction": "Qual frase NÃO está na voz passiva?", "prompt": "Which sentence is NOT in the passive voice?", "options": ["The keys were left on the table.", "The report has been rewritten.", "The mall is being renovated.", "The guests were having dinner."], "correctIndex": 3, "explain": "\"were having dinner\" é past continuous ativo; as outras usam be + particípio.", "id": "bkB2-159"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "mcq", "instruction": "Escolha a dedução mais lógica.", "prompt": "Yesterday I rang Rita's doorbell five times, but she didn't answer. She ___ in the shower at that time.", "options": ["must have been", "can't have been", "must be", "might be"], "correctIndex": 0, "explain": "Dedução sobre o passado com certeza: must have been.", "id": "bkB2-160"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "mcq", "instruction": "Escolha a dedução mais lógica.", "prompt": "Mateus ___ the email; he's been on a remote island without internet all week.", "options": ["must have read", "can't have read", "might have read", "should have read"], "correctIndex": 1, "explain": "Sem internet, é impossível ter lido: can't have + particípio.", "id": "bkB2-161"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "mcq", "instruction": "Escolha a forma que expressa possibilidade.", "prompt": "I'm not sure why Gabi is late. She ___ stuck in traffic, or maybe she overslept.", "options": ["must have gotten", "might have gotten", "can't have gotten", "must get"], "correctIndex": 1, "explain": "\"I'm not sure\" indica possibilidade: might have + particípio.", "id": "bkB2-162"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "gaps", "instruction": "Complete com must/might/can't have.", "prompt": "A: The window is broken and there's a baseball on the floor.\nB: The kids next door ___ (hit) it while they were playing.\nA: But they ___ (play) outside. They've been at their grandma's since Friday!", "answers": [["must have hit", "might have hit", "may have hit", "could have hit"], ["can't have been playing", "couldn't have been playing", "could not have been playing", "cannot have been playing", "can't have played", "cannot have played", "couldn't have played", "could not have played"]], "explain": "Evidência sugere o que aconteceu; \"they've been away\" torna impossível: can't have been playing.", "id": "bkB2-163"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "gaps", "instruction": "Complete com dedução no passado (passiva ou contínua).", "prompt": "The museum's alarm didn't go off last night. It ___ (switch off) by someone who knew the code. The guard ___ (sleep) at the time, because the cameras show him walking around.", "answers": [["must have been switched off", "might have been switched off", "may have been switched off", "could have been switched off"], ["can't have been sleeping", "couldn't have been sleeping", "could not have been sleeping", "cannot have been sleeping"]], "explain": "Passiva: must have been + particípio; contínua negativa: can't have been + -ing.", "id": "bkB2-164"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "gaps", "instruction": "Complete o diálogo com dedução no passado.", "prompt": "A: Lucas didn't come to the party.\nB: He ___ (forget) about it. He was talking about it all week!\nA: Maybe. Or he ___ (feel) sick. He had a cold on Friday.", "answers": [["can't have forgotten", "couldn't have forgotten", "could not have forgotten", "cannot have forgotten"], ["might have felt", "may have felt", "could have felt", "might have been feeling", "may have been feeling", "could have been feeling"]], "explain": "Falava da festa a semana toda: can't have forgotten. \"Maybe\": possibilidade com might/may/could.", "id": "bkB2-165"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "choose", "instruction": "Escolha a dedução correta.", "prompt": "Look at all these empty boxes! Luana [must have bought*/can't have bought] a lot of stuff online. She [can't have*/must have] opened them all, though, because some are still sealed.", "explain": "Muitas caixas: must have bought; algumas ainda lacradas: can't have opened them all.", "id": "bkB2-166"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "Who [could*/must] have left this note on my desk? The handwriting looks familiar, so it [must have been*/can't have been] someone from our team.", "explain": "Pergunta especulativa: Who could have...? Letra familiar: must have been.", "id": "bkB2-167"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "She can't have see the message; her phone was off.", "wrong": "see", "fix": ["seen"], "explain": "Após can't have usa-se o particípio (seen).", "id": "bkB2-168"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "The thief may have came in through the kitchen window.", "wrong": "came", "fix": ["come"], "explain": "Modal + have + particípio: may have come.", "id": "bkB2-169"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "rewrite", "instruction": "Reescreva com \"can't have\".", "prompt": "I'm sure Paulo didn't take my charger.", "start": "Paulo can't", "accept": ["Paulo can't have taken my charger."], "explain": "Certeza de que não aconteceu: can't have + particípio.", "id": "bkB2-170"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "rewrite", "instruction": "Reescreva com \"might have\".", "prompt": "Perhaps they missed the last ferry.", "start": "They might", "accept": ["They might have missed the last ferry."], "explain": "Perhaps + passado = might have + particípio.", "id": "bkB2-171"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["Someone", "must", "have", "been", "using", "my", "laptop", "while", "I", "was", "out"], "alt": ["While I was out someone must have been using my laptop"], "explain": "Dedução contínua: must have been + -ing.", "id": "bkB2-172"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["The", "package", "might", "have", "been", "sent", "to", "the", "wrong", "address"], "explain": "Possibilidade passiva: might have been + particípio.", "id": "bkB2-173"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "match", "instruction": "Ligue a evidência à dedução.", "left": ["Her car isn't in the garage.", "The baby finally fell asleep.", "There's glitter all over the sofa.", "He knows all the answers."], "right": ["The kids must have been making crafts.", "He must have seen the test before.", "She must have driven to work.", "He must have been really tired."], "correctMap": [2, 3, 0, 1], "explain": "must have + particípio tira uma conclusão lógica da evidência.", "id": "bkB2-174"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "sort", "instruction": "Classifique pelo grau de certeza.", "prompt": "How sure is the speaker?", "groups": ["Certain (yes)", "Possible", "Certain (no)"], "items": [{"w": "must have left", "g": 0}, {"w": "might have left", "g": 1}, {"w": "can't have left", "g": 2}, {"w": "must have known", "g": 0}, {"w": "could have known", "g": 1}, {"w": "couldn't have known", "g": 2}, {"w": "may have forgotten", "g": 1}], "explain": "must have = certeza (sim); might/may/could have = possível; can't/couldn't have = certeza (não).", "id": "bkB2-175"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "tf", "instruction": "Leia e marque verdadeiro ou falso.", "text": "When Clara got home, the front door was unlocked and the lights were on. Her roommate, Bia, was supposed to be in Salvador for the weekend. On the kitchen table, Clara found Bia's suitcase and a half-eaten sandwich that was still warm. \"Bia must have come back early,\" she thought. Then she heard someone singing in the shower.", "items": [{"s": "Clara expected Bia to be away.", "a": true}, {"s": "The sandwich had been there for days.", "a": false}, {"s": "Clara concluded that Bia had returned early.", "a": true}, {"s": "Clara found the front door locked.", "a": false}], "explain": "Clara deduz (\"must have come back\") a partir das pistas.", "id": "bkB2-176"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Have you seen my headphones? They were on the desk.", "B: No, but Theo was in your room earlier. He might have borrowed them.", "A: He can't have borrowed them. He's been at school all day.", "B: Then you must have put them in your backpack this morning.", "A: You're right! Here they are."], "explain": "might have (possível), can't have (impossível), must have (certeza).", "id": "bkB2-177"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "reading", "instruction": "Leia o texto e responda.", "text": "Detective Moura looked around the small bakery. The cash register was empty, but the thief hadn't touched the expensive coffee machine. There were flour footprints leading to the back door, which was open. The baker, Sr. Lopes, said he had locked it at 6 p.m. The only other person with a key was his assistant, who had been in the hospital since Tuesday.", "questions": [{"q": "What can the detective conclude about the back door?", "options": ["The thief must have left through it.", "The thief can't have used it.", "It must have been locked all night."], "correctIndex": 0}, {"q": "What can he conclude about the assistant?", "options": ["He must have taken the money.", "He can't have been the thief.", "He must have left the footprints."], "correctIndex": 1}], "explain": "Pegadas até a porta aberta: must have left; assistente no hospital: can't have been.", "id": "bkB2-178"}, {"level": "B2", "topic": "Dedução no passado (must have, can't have)", "type": "blank", "instruction": "Complete com dedução negativa no passado.", "prompt": "The ground is completely dry, so it ___ (not rain) last night.", "accept": ["can't have rained", "couldn't have rained", "could not have rained", "must not have rained", "cannot have rained"], "explain": "Chão seco = impossível ter chovido: can't/couldn't have + particípio.", "id": "bkB2-179"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "mcq", "instruction": "Escolha o phrasal verb correto.", "prompt": "The police are ___ the cause of the fire at the warehouse.", "options": ["looking into", "looking after", "looking up", "looking forward"], "correctIndex": 0, "explain": "\"look into\" = investigar.", "id": "bkB2-180"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "mcq", "instruction": "Escolha o phrasal verb correto.", "prompt": "The new restaurant didn't ___ the hype; the food was just average.", "options": ["live up to", "keep up with", "come up against", "get on with"], "correctIndex": 0, "explain": "\"live up to\" = corresponder às expectativas.", "id": "bkB2-181"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "mcq", "instruction": "Escolha o phrasal verb correto.", "prompt": "Our plans to buy the house ___ when the bank refused the loan.", "options": ["fell through", "fell out", "broke up", "turned up"], "correctIndex": 0, "explain": "\"fall through\" = (um plano) não dar certo, fracassar.", "id": "bkB2-182"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "odd", "instruction": "Qual phrasal verb NÃO significa \"reduzir\"?", "prompt": "Which phrasal verb does NOT mean \"reduce\"?", "options": ["cut down on", "cut back on", "scale back", "back up"], "correctIndex": 3, "explain": "\"back up\" = apoiar ou fazer cópia; os outros significam reduzir.", "id": "bkB2-183"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "gaps", "instruction": "Complete o texto com os phrasal verbs do banco.", "prompt": "When Joana's father retired, she ___ the family bakery in Belém. She quickly ___ that the old oven was the main problem, so she decided to ___ it and buy a new one. At a family meeting, she ___ the idea of selling cakes online. Some relatives were skeptical, but the plan ___ to be a huge success.", "bank": ["took over", "worked out", "do away with", "put forward", "turned out", "fell through"], "answers": [["took over"], ["worked out"], ["do away with"], ["put forward"], ["turned out"]], "explain": "take over: assumir; work out: descobrir; do away with: eliminar; put forward: propor; turn out: revelar-se.", "id": "bkB2-184"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "gaps", "instruction": "Complete com a partícula correta.", "prompt": "A: I'm coming ___ with a cold, so I'll stay home today.\nB: Poor you! Did you get ___ to calling the doctor?\nA: Not yet, but I'll sort it ___ later.", "answers": [["down"], ["round", "around"], ["out"]], "explain": "come down with: ficar doente; get round/around to: arranjar tempo para; sort out: resolver.", "id": "bkB2-185"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "gaps", "instruction": "Complete com a partícula correta.", "prompt": "The factory had to lay ___ 200 workers last year. Luckily, most of them were taken ___ by a competitor a few months later.", "answers": [["off"], ["on"]], "explain": "lay off: demitir (por corte); take on: contratar.", "id": "bkB2-186"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "choose", "instruction": "Escolha os phrasal verbs corretos.", "prompt": "I tried to [talk him into*/talk him over] coming to the concert, but he [backed out*/backed up] at the last minute.", "explain": "talk someone into: convencer; back out: desistir de um compromisso.", "id": "bkB2-187"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "Nobody could [make out*/make up] what the announcer was saying. The noise of the crowd [drowned it out*/drowned out it].", "explain": "make out: entender/distinguir; com pronome, verbo separável: drowned it out.", "id": "bkB2-188"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "Please don't tell anyone—I don't want him to get away of it.", "wrong": "of", "fix": ["with"], "explain": "O correto é \"get away with\" (sair impune).", "id": "bkB2-189"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "She takes after to her grandmother; they have the same smile.", "wrong": "after to", "fix": ["after"], "explain": "\"take after\" (parecer-se com parente) não leva \"to\".", "id": "bkB2-190"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "rewrite", "instruction": "Reescreva usando \"own up to\".", "prompt": "The thief finally admitted that he had stolen the painting.", "start": "The thief finally owned up to", "accept": ["The thief finally owned up to stealing the painting.", "The thief finally owned up to having stolen the painting.", "The thief finally owned up to the theft of the painting."], "explain": "\"own up to\" + -ing/substantivo = confessar algo errado.", "id": "bkB2-191"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "rewrite", "instruction": "Substitua \"the music\" por um pronome.", "prompt": "Could you turn down the music?", "start": "Could you", "accept": ["Could you turn it down?"], "explain": "Com pronome, o phrasal verb separável fica dividido: turn it down.", "id": "bkB2-192"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["I", "can't", "keep", "up", "with", "all", "these", "new", "apps"], "explain": "\"keep up with\" = acompanhar o ritmo de.", "id": "bkB2-193"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["She", "pointed", "out", "that", "the", "numbers", "didn't", "add", "up"], "explain": "point out: apontar/observar; add up: fazer sentido (bater).", "id": "bkB2-194"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "match", "instruction": "Ligue o phrasal verb ao significado.", "left": ["rule out", "stand out", "wear out", "bring about", "pull through"], "right": ["to cause something to happen", "to recover from a serious illness", "to be easily noticed", "to exclude a possibility", "to use something until it can no longer be used"], "correctMap": [3, 2, 4, 0, 1], "explain": "rule out, stand out, wear out, bring about, pull through.", "id": "bkB2-195"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "sort", "instruction": "Classifique pelo contexto de uso.", "prompt": "Work or relationships?", "groups": ["Work & career", "Relationships"], "items": [{"w": "lay off (staff)", "g": 0}, {"w": "fall out (with a friend)", "g": 1}, {"w": "take on (new staff)", "g": 0}, {"w": "split up (with a partner)", "g": 1}, {"w": "hand in (your notice)", "g": 0}, {"w": "ask (someone) out", "g": 1}, {"w": "step down (as director)", "g": 0}, {"w": "make up (after a fight)", "g": 1}], "explain": "lay off, take on, hand in, step down: trabalho; os outros: relacionamentos.", "id": "bkB2-196"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Did you hear that Caio and Fernanda fell out?", "B: Really? What happened?", "A: He forgot her birthday, and she didn't let him get away with it.", "B: I hope they sort it out soon.", "A: Me too. They've been friends since school."], "explain": "fall out: brigar; get away with: sair impune; sort out: resolver.", "id": "bkB2-197"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "reading", "instruction": "Leia a mensagem e responda.", "text": "Hi Lucas, Bad news: our trip to Ilhabela has fallen through. The hotel called to say they had overbooked, so they can't put us up anymore. I looked into other options, but everything is either full or too expensive. I don't want to rule out the trip completely, though. Maybe we can set it up again for next month? Let me know what you think. Duda", "questions": [{"q": "Why was the trip canceled?", "options": ["The hotel had too many bookings.", "Lucas got sick.", "The ferry was too expensive."], "correctIndex": 0}, {"q": "What does \"put us up\" mean here?", "options": ["make us wait", "give us a place to stay", "raise our prices"], "correctIndex": 1}, {"q": "What does Duda suggest?", "options": ["Forgetting about the trip", "Staying at another hotel this weekend", "Organizing the trip for next month"], "correctIndex": 2}], "explain": "fall through: não dar certo; put up: hospedar; rule out: descartar; set up: organizar.", "id": "bkB2-198"}, {"level": "B2", "topic": "Phrasal verbs avançados", "type": "tf", "instruction": "Leia e marque verdadeiro ou falso.", "text": "Marcelo had always stood out at work, so when his boss stepped down, he was asked to take over the team. At first, he found it hard to get his ideas across in meetings. He also had to turn down several invitations to go out with his old colleagues because he was so busy. After six months, however, the team's results had picked up, and everyone agreed he had lived up to expectations.", "items": [{"s": "Marcelo replaced his boss.", "a": true}, {"s": "At first, Marcelo found it easy to explain his ideas.", "a": false}, {"s": "He accepted every invitation from his old colleagues.", "a": false}, {"s": "The team's results improved.", "a": true}], "explain": "take over: assumir; get across: transmitir; pick up: melhorar; live up to: corresponder.", "id": "bkB2-199"}, {"level": "B2", "topic": "Wish & If only", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "I wish my brother ___ borrowing my clothes without asking.", "options": ["would stop", "stops", "stopped to", "has stopped"], "correctIndex": 0, "explain": "wish + would: irritação com o comportamento de outra pessoa.", "id": "bkB2-200"}, {"level": "B2", "topic": "Wish & If only", "type": "mcq", "instruction": "Escolha o verbo correto.", "prompt": "I ___ you have a great time in Buenos Aires next week!", "options": ["wish", "hope", "would like", "wished"], "correctIndex": 1, "explain": "Para desejos possíveis no futuro, usa-se \"hope\", não \"wish\".", "id": "bkB2-201"}, {"level": "B2", "topic": "Wish & If only", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "Now that I'm living in Tokyo, I wish I ___ Japanese at school.", "options": ["studied", "had studied", "would study", "have studied"], "correctIndex": 1, "explain": "Arrependimento sobre o passado: wish + past perfect.", "id": "bkB2-202"}, {"level": "B2", "topic": "Wish & If only", "type": "gaps", "instruction": "Complete com a forma correta.", "prompt": "I wish I ___ (can) come to your wedding, but I'll be in Europe then. If only the dates ___ (be) different!", "answers": [["could"], ["were"]], "explain": "Desejo presente: wish + could; if only + were (irreal).", "id": "bkB2-203"}, {"level": "B2", "topic": "Wish & If only", "type": "gaps", "instruction": "Complete o diálogo.", "prompt": "A: Do you regret moving to the countryside?\nB: Not really, but I wish there ___ (be) a good hospital nearby. And I wish I ___ (not sell) my car before we moved—I really need it now!", "answers": [["were", "was"], ["hadn't sold", "had not sold"]], "explain": "wish + past simple (were) para o presente; wish + past perfect para o passado.", "id": "bkB2-204"}, {"level": "B2", "topic": "Wish & If only", "type": "gaps", "instruction": "Complete com a forma correta.", "prompt": "If only it ___ (stop) raining! I wish we ___ (go) to the beach yesterday when it was sunny.", "answers": [["would stop", "stopped"], ["had gone"]], "explain": "If only + would: desejo de mudança; wish + past perfect: arrependimento.", "id": "bkB2-205"}, {"level": "B2", "topic": "Wish & If only", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "I wish I [were*/am] taller. Then I [could*/can] reach the top shelf without a ladder.", "explain": "wish + past (were) para o presente; could para habilidade hipotética.", "id": "bkB2-206"}, {"level": "B2", "topic": "Wish & If only", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "Paula wishes she [hadn't said*/didn't say] those things to her sister last night. She wishes they [were*/would be] still friends.", "explain": "Passado: wish + past perfect; estado presente: wish + past simple (were).", "id": "bkB2-207"}, {"level": "B2", "topic": "Wish & If only", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "I wish I would have more free time.", "wrong": "would have", "fix": ["had", "could have"], "explain": "Não se usa \"wish I would\" sobre si mesmo: wish I had.", "id": "bkB2-208"}, {"level": "B2", "topic": "Wish & If only", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "If only I have listened to your advice last year.", "wrong": "have listened", "fix": ["had listened"], "explain": "Arrependimento no passado: if only + past perfect.", "id": "bkB2-209"}, {"level": "B2", "topic": "Wish & If only", "type": "rewrite", "instruction": "Reescreva expressando irritação com \"wish\".", "prompt": "My roommate never washes the dishes. It's so annoying!", "start": "I wish my roommate", "accept": ["I wish my roommate would wash the dishes.", "I wish my roommate would wash the dishes sometimes.", "I wish my roommate would do the dishes.", "I wish my roommate washed the dishes.", "I wish my roommate would wash the dishes more often."], "explain": "Irritação com hábito de outra pessoa: wish + would + verbo.", "id": "bkB2-210"}, {"level": "B2", "topic": "Wish & If only", "type": "rewrite", "instruction": "Reescreva com \"If only\".", "prompt": "I regret not taking more photos on the trip.", "start": "If only", "accept": ["If only I had taken more photos on the trip.", "If only I'd taken more photos on the trip."], "explain": "Arrependimento: If only + past perfect.", "id": "bkB2-211"}, {"level": "B2", "topic": "Wish & If only", "type": "rewrite", "instruction": "Reescreva com \"I wish\".", "prompt": "Unfortunately, I can't play the piano.", "start": "I wish", "accept": ["I wish I could play the piano.", "I wish I knew how to play the piano."], "explain": "Habilidade que você não tem: wish + could.", "id": "bkB2-212"}, {"level": "B2", "topic": "Wish & If only", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["I", "wish", "I", "hadn't", "spent", "so", "much", "money", "last", "weekend"], "explain": "wish + past perfect negativo: arrependimento.", "id": "bkB2-213"}, {"level": "B2", "topic": "Wish & If only", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["If", "only", "we", "had", "more", "time", "together"], "explain": "If only + past simple: desejo sobre o presente.", "id": "bkB2-214"}, {"level": "B2", "topic": "Wish & If only", "type": "match", "instruction": "Ligue a situação ao desejo.", "left": ["I'm stuck in traffic.", "I didn't bring a jacket.", "My dog barks all night.", "I don't know how to swim."], "right": ["I wish I had brought one.", "I wish I knew how.", "I wish I weren't stuck here.", "I wish he would stop."], "correctMap": [2, 0, 3, 1], "explain": "Presente: past simple; passado: past perfect; comportamento alheio: would.", "id": "bkB2-215"}, {"level": "B2", "topic": "Wish & If only", "type": "sort", "instruction": "Classifique cada desejo.", "prompt": "What kind of wish is it?", "groups": ["Present wish", "Past regret", "Annoyance (would)"], "items": [{"w": "I wish I were at home.", "g": 0}, {"w": "I wish I had called her.", "g": 1}, {"w": "I wish you would listen.", "g": 2}, {"w": "If only I knew the answer.", "g": 0}, {"w": "If only we hadn't left early.", "g": 1}, {"w": "I wish it would stop snowing.", "g": 2}], "explain": "Past simple: presente irreal; past perfect: arrependimento; would: irritação.", "id": "bkB2-216"}, {"level": "B2", "topic": "Wish & If only", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: How was the camping trip?", "B: Terrible. It rained all weekend.", "A: Oh no. Didn't you check the forecast?", "B: No. I wish I had checked it before we left.", "A: If only you'd asked me! I could have lent you my waterproof tent."], "explain": "B expressa arrependimento com \"I wish I had checked\".", "id": "bkB2-217"}, {"level": "B2", "topic": "Wish & If only", "type": "tf", "instruction": "Leia e marque verdadeiro ou falso.", "text": "Renan is a software developer in Florianópolis. He loves his job, but he wishes he didn't have to work so late every night. He also wishes he had learned to surf when he moved there, since the beach is right outside his window. His girlfriend often says, \"I wish you would take a day off!\" Next month, he's finally taking a two-week vacation.", "items": [{"s": "Renan is unhappy with his profession.", "a": false}, {"s": "Renan knows how to surf.", "a": false}, {"s": "His girlfriend wants him to rest more.", "a": true}, {"s": "Renan has planned a vacation.", "a": true}], "explain": "\"wishes he had learned\" = ele não aprendeu; \"wish you would\" = pedido irritado.", "id": "bkB2-218"}, {"level": "B2", "topic": "Wish & If only", "type": "blank", "instruction": "Complete com a forma correta.", "prompt": "My sister wishes she ___ (have) a bigger bedroom.", "accept": ["had"], "explain": "Desejo sobre o presente: wish + past simple (had).", "id": "bkB2-219"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "mcq", "instruction": "Escolha o auxiliar enfático correto.", "prompt": "I don't eat much meat, but I ___ love a good barbecue now and then.", "options": ["do", "does", "am", "did"], "correctIndex": 0, "explain": "Ênfase no presente com \"I\": do + verbo base (contraste).", "id": "bkB2-220"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "mcq", "instruction": "Escolha o auxiliar enfático correto.", "prompt": "My late grandmother ___ make the best pão de queijo in the world—everyone said so.", "options": ["did", "does", "do", "was"], "correctIndex": 0, "explain": "Contexto passado (everyone said so): did + verbo base.", "id": "bkB2-221"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "mcq", "instruction": "Escolha a palavra correta.", "prompt": "___ come and visit us when you're in Porto Alegre!", "options": ["Do", "Does", "Did", "Are"], "correctIndex": 0, "explain": "\"Do\" antes do imperativo torna o convite mais caloroso e enfático.", "id": "bkB2-222"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "gaps", "instruction": "Complete com ênfase (do/does/did + verbo).", "prompt": "A: You never help around the house!\nB: That's not fair! I ___ (cook) dinner last night, and I ___ (take) out the trash every day.", "answers": [["did cook"], ["do take"]], "explain": "Contradição enfática: did + base (passado), do + base (hábito).", "id": "bkB2-223"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "gaps", "instruction": "Complete: negativa e depois ênfase.", "prompt": "Rafael ___ (not / enjoy) crowded places, but he ___ (enjoy) small concerts with friends.", "answers": [["doesn't enjoy", "does not enjoy"], ["does enjoy"]], "explain": "Contraste: doesn't enjoy × does enjoy (ênfase com does + base).", "id": "bkB2-224"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "He didn't pass the test, but he [did try*/tried did] his best. He [does seem*/does seems] a bit disappointed, though.", "explain": "did/does + verbo base, nessa ordem.", "id": "bkB2-225"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "Although the hotel was old, it [did have*/had did] a lovely view. The staff [did make*/did made] us feel welcome.", "explain": "Ênfase no passado: did + verbo base (have, make).", "id": "bkB2-226"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "I did told you to bring a coat!", "wrong": "told", "fix": ["tell"], "explain": "Depois de \"did\" enfático, o verbo fica na forma base.", "id": "bkB2-227"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "Do sits down, please—the doctor will see you soon.", "wrong": "sits", "fix": ["sit"], "explain": "Imperativo enfático: Do + verbo base (sit).", "id": "bkB2-228"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "rewrite", "instruction": "Reescreva dando ênfase com do/does/did.", "prompt": "She looks tired today.", "start": "She", "accept": ["She does look tired today.", "She really does look tired today.", "She does look really tired today."], "explain": "Presente, 3ª pessoa: does + verbo base (look).", "id": "bkB2-229"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "rewrite", "instruction": "Reescreva dando ênfase com do/does/did.", "prompt": "We had a great time at your party.", "start": "We", "accept": ["We did have a great time at your party.", "We really did have a great time at your party."], "explain": "Passado: did + verbo base (have).", "id": "bkB2-230"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "rewrite", "instruction": "Reescreva o convite de forma enfática.", "prompt": "Have some more cake.", "start": "Do", "accept": ["Do have some more cake.", "Do have some more cake, please."], "explain": "Imperativo enfático: Do + verbo base.", "id": "bkB2-231"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["I", "do", "hope", "you", "feel", "better", "soon"], "explain": "\"do hope\" reforça o desejo.", "id": "bkB2-232"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["She", "did", "apologize", "but", "he", "didn't", "listen"], "explain": "\"did apologize\" enfatiza que o pedido de desculpas aconteceu.", "id": "bkB2-233"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "match", "instruction": "Ligue as metades das frases.", "left": ["I don't have a car,", "She rarely eats sweets,", "We didn't win the game,", "They don't speak Spanish,"], "right": ["but she does love chocolate.", "but they do understand a little.", "but I do have a motorcycle.", "but we did score two goals."], "correctMap": [2, 0, 3, 1], "explain": "Contraste com do/does/did enfático após \"but\".", "id": "bkB2-234"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "sort", "instruction": "Classifique o uso de do/does/did.", "prompt": "How is do/does/did used?", "groups": ["Emphatic", "Question/negative auxiliary", "Main verb"], "items": [{"w": "I do love this song.", "g": 0}, {"w": "Do you like tea?", "g": 1}, {"w": "I do my homework at night.", "g": 2}, {"w": "She did warn us.", "g": 0}, {"w": "He doesn't work here.", "g": 1}, {"w": "They did the shopping.", "g": 2}, {"w": "Did you call me?", "g": 1}, {"w": "Do be careful.", "g": 0}], "explain": "Ênfase: do + verbo em afirmativa; auxiliar: perguntas/negativas; do = fazer: verbo principal.", "id": "bkB2-235"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Are you sure you sent me the file? I can't find it.", "B: I did send it! I sent it on Monday.", "A: Which email address did you use?", "B: Your work address. Check your spam folder.", "A: Oh, here it is. Sorry, you did send it."], "explain": "\"I did send it\" contradiz a dúvida de A com ênfase.", "id": "bkB2-236"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "tf", "instruction": "Leia e marque verdadeiro ou falso.", "text": "Many people think Brazilians only speak Portuguese. In fact, many Brazilians do study other languages, especially English and Spanish. Mariana, a nurse from Belém, doesn't speak Spanish fluently, but she does understand most of it. She says, \"I did try to take classes, but I never had time.\" Now she practices by watching Argentine TV series.", "items": [{"s": "Mariana understands most Spanish.", "a": true}, {"s": "Mariana speaks Spanish fluently.", "a": false}, {"s": "Mariana never tried to take Spanish classes.", "a": false}, {"s": "Mariana watches TV series to practice.", "a": true}], "explain": "\"does understand\" e \"did try\" enfatizam fatos que contrastam com o esperado.", "id": "bkB2-237"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "reading", "instruction": "Leia a avaliação e responda.", "text": "Pousada Sol, Paraty – Review. The pousada is not luxurious, and the rooms are quite small. However, it does have a beautiful garden and a great breakfast. The staff don't speak much English, but they do try hard to help. We did have one problem: the Wi-Fi stopped working on our last day. Overall, we do recommend it for a relaxing weekend.", "questions": [{"q": "What does the reviewer say about the rooms?", "options": ["They are small.", "They are luxurious.", "They have a garden view."], "correctIndex": 0}, {"q": "What was the problem?", "options": ["The breakfast was bad.", "The Wi-Fi stopped working.", "The staff were rude."], "correctIndex": 1}, {"q": "Does the reviewer recommend the pousada?", "options": ["No, not at all", "Only for business trips", "Yes, for a relaxing weekend"], "correctIndex": 2}], "explain": "does have, do try, did have, do recommend: ênfase para contrastar pontos.", "id": "bkB2-238"}, {"level": "B2", "topic": "Ênfase com do/does/did", "type": "blank", "instruction": "Complete com ênfase no passado.", "prompt": "A: Why didn't you text me?\nB: I ___ (text) you! Check your phone.", "accept": ["did text"], "explain": "Contradição no passado: did + verbo base.", "id": "bkB2-239"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "No sooner ___ the house than it started to pour.", "options": ["had we left", "we had left", "have we left", "we left"], "correctIndex": 0, "explain": "\"No sooner\" pede inversão com past perfect: had we left... than.", "id": "bkB2-240"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "Only after the meeting ___ how serious the problem was.", "options": ["did I realize", "I realized", "I did realize", "realized I"], "correctIndex": 0, "explain": "\"Only after...\" no início inverte a oração principal: did I realize.", "id": "bkB2-241"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "mcq", "instruction": "Escolha a forma correta.", "prompt": "At no time ___ in danger, the pilot assured us.", "options": ["were the passengers", "the passengers were", "did the passengers were", "passengers were"], "correctIndex": 0, "explain": "\"At no time\" no início exige inversão: were the passengers.", "id": "bkB2-242"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "gaps", "instruction": "Complete com o auxiliar correto.", "prompt": "Not until the lights came on ___ we see how many people were there. Little ___ we know that the singer was in the audience too.", "answers": [["did"], ["did"]], "explain": "Not until... e Little... no passado simples: did + sujeito + base.", "id": "bkB2-243"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "gaps", "instruction": "Complete com inversão (auxiliar + sujeito + verbo).", "prompt": "Seldom ___ (Luísa / cook) at home, but last night she made feijoada. Nowhere else ___ (you / find) such fresh seafood as in this market.", "answers": [["does Luísa cook"], ["will you find", "can you find", "do you find", "could you find", "would you find"]], "explain": "Seldom/Nowhere no início: auxiliar antes do sujeito.", "id": "bkB2-244"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "gaps", "instruction": "Complete com o auxiliar correto.", "prompt": "Scarcely ___ the plane taken off when the baby started crying. On no account ___ passengers leave their seats during takeoff.", "answers": [["had"], ["should", "must", "may", "can"]], "explain": "Scarcely + had + particípio... when; On no account + modal + sujeito.", "id": "bkB2-245"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "Not only [does Rita teach*/Rita teaches] yoga, but she also [runs*/does she run] a small café.", "explain": "Not only no início inverte a 1ª oração; a 2ª (but also) fica na ordem normal.", "id": "bkB2-246"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "choose", "instruction": "Escolha as formas corretas.", "prompt": "Under no circumstances [should you*/you should] leave your bag unattended. In no way [was the driver*/the driver was] responsible for the accident.", "explain": "Under no circumstances / In no way no início exigem inversão.", "id": "bkB2-247"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "Rarely I have seen such a crowded beach.", "wrong": "I have", "fix": ["have I"], "explain": "Rarely no início: auxiliar antes do sujeito (have I seen).", "id": "bkB2-248"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "Not until she called did I knew she was sick.", "wrong": "knew", "fix": ["know"], "explain": "Após did, o verbo fica na forma base (know).", "id": "bkB2-249"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "rewrite", "instruction": "Reescreva começando com \"Hardly\".", "prompt": "We had just started eating when the power went out.", "start": "Hardly", "accept": ["Hardly had we started eating when the power went out.", "Hardly had we begun eating when the power went out."], "explain": "Hardly + had + sujeito + particípio... when.", "id": "bkB2-250"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "rewrite", "instruction": "Reescreva começando com \"Not until\".", "prompt": "I didn't understand the joke until she explained it.", "start": "Not until", "accept": ["Not until she explained it did I understand the joke.", "Not until she had explained it did I understand the joke."], "explain": "Not until + oração, e a principal fica invertida: did I understand.", "id": "bkB2-251"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "rewrite", "instruction": "Reescreva começando com \"Not only\".", "prompt": "The museum is not only beautiful but also free.", "start": "Not only", "accept": ["Not only is the museum beautiful, but it is also free.", "Not only is the museum beautiful, it is also free.", "Not only is the museum beautiful, but also free.", "Not only is the museum beautiful, but it is free too.", "Not only is the museum beautiful, but it's also free.", "Not only is the museum beautiful, it's also free."], "explain": "Not only + is + sujeito...; but (it is) also...", "id": "bkB2-252"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["Never", "before", "had", "the", "city", "seen", "so", "much", "snow"], "explain": "Never before + had + sujeito + particípio.", "id": "bkB2-253"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["Only", "when", "the", "baby", "fell", "asleep", "could", "we", "relax"], "explain": "Only when + oração; a principal é invertida: could we relax.", "id": "bkB2-254"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "match", "instruction": "Ligue as metades das frases.", "left": ["Not only did he forget my birthday,", "Little did she know", "Only by working together", "Seldom have I felt"], "right": ["can we solve this problem.", "so welcome in a new city.", "but he also forgot our anniversary.", "that her life was about to change."], "correctMap": [2, 3, 0, 1], "explain": "Cada expressão negativa inicial pede a continuação adequada.", "id": "bkB2-255"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "sort", "instruction": "Classifique: a expressão no início exige inversão?", "prompt": "At the start of a sentence, does it need inversion?", "groups": ["Inversion", "No inversion"], "items": [{"w": "Rarely", "g": 0}, {"w": "Usually", "g": 1}, {"w": "Under no circumstances", "g": 0}, {"w": "Sometimes", "g": 1}, {"w": "Only after", "g": 0}, {"w": "Although", "g": 1}, {"w": "Not until", "g": 0}, {"w": "Even so", "g": 1}], "explain": "Advérbios negativos/restritivos pedem inversão; os outros não.", "id": "bkB2-256"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: How was your first day at the new job?", "B: Exhausting! No sooner had I sat down than my boss called me into a meeting.", "A: What was the meeting about?", "B: A big client. Not only did I have to take notes, but I also had to present a report.", "A: Wow. Seldom does anyone get so much responsibility on day one!"], "explain": "B usa inversões: No sooner had I..., not only did I...", "id": "bkB2-257"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "reading", "instruction": "Leia a notícia e responda.", "text": "Last Saturday, a fisherman from Ubatuba, Seu Jorge Matos, rescued two tourists whose boat had overturned. Never before had he seen such big waves, he said. Not only did he pull both tourists out of the water, but he also brought their dog back to shore. Only when they reached the beach did he notice that his own hand was bleeding. \"At no point did I think about my own safety,\" he told reporters.", "questions": [{"q": "How many people did Seu Jorge rescue?", "options": ["One", "Two", "Three"], "correctIndex": 1}, {"q": "When did he notice his injury?", "options": ["Before entering the water", "After reaching the beach", "While he was in the boat"], "correctIndex": 1}, {"q": "What does \"Never before had he seen such big waves\" mean?", "options": ["The waves were the biggest he had ever seen.", "He had never been to the sea.", "He often sees big waves."], "correctIndex": 0}], "explain": "Never before had he seen / Only when... did he notice: inversões enfáticas.", "id": "bkB2-258"}, {"level": "B2", "topic": "Inversão com advérbios negativos (básico)", "type": "blank", "instruction": "Complete com inversão (auxiliar + sujeito + verbo).", "prompt": "Rarely ___ (my father / get) angry, but he was furious yesterday.", "accept": ["does my father get"], "explain": "Rarely no início: does + sujeito + verbo base.", "id": "bkB2-259"}, {"level": "B2", "topic": "Collocations avançadas", "type": "mcq", "instruction": "Escolha a palavra que forma a collocation.", "prompt": "The instructions were ___ clear, so nobody got lost.", "options": ["crystal", "glass", "water", "diamond"], "correctIndex": 0, "explain": "\"crystal clear\" = claríssimo.", "id": "bkB2-260"}, {"level": "B2", "topic": "Collocations avançadas", "type": "mcq", "instruction": "Escolha o verbo correto.", "prompt": "Please ___ in mind that the museum closes early on Sundays.", "options": ["bear", "put", "hold", "take"], "correctIndex": 0, "explain": "\"bear in mind\" = ter em mente.", "id": "bkB2-261"}, {"level": "B2", "topic": "Collocations avançadas", "type": "mcq", "instruction": "Escolha o verbo correto.", "prompt": "After hours of negotiation, the two companies finally ___ an agreement.", "options": ["reached", "did", "got", "took"], "correctIndex": 0, "explain": "\"reach an agreement\" = chegar a um acordo.", "id": "bkB2-262"}, {"level": "B2", "topic": "Collocations avançadas", "type": "odd", "instruction": "Qual palavra NÃO combina com \"deeply\"?", "prompt": "Which word does NOT go with \"deeply\"?", "options": ["regret", "moved", "religious", "expensive"], "correctIndex": 3, "explain": "deeply regret/moved/religious; \"expensive\" não combina com deeply.", "id": "bkB2-263"}, {"level": "B2", "topic": "Collocations avançadas", "type": "odd", "instruction": "Qual expressão NÃO combina com \"take\"?", "prompt": "Which word does NOT go with \"take\"?", "options": ["advantage", "place", "into account", "harm"], "correctIndex": 3, "explain": "take advantage/place/into account; o certo é \"do harm\".", "id": "bkB2-264"}, {"level": "B2", "topic": "Collocations avançadas", "type": "gaps", "instruction": "Complete o texto com as palavras do banco.", "prompt": "Small businesses in Brazil ___ many challenges. Many owners work long hours just to make ends ___. To survive, they must ___ advantage of social media and ___ a strong online presence. Those who succeed often ___ a name for themselves in their city.", "bank": ["face", "meet", "take", "build", "make", "gain"], "answers": [["face"], ["meet"], ["take"], ["build", "gain"], ["make"]], "explain": "face challenges, make ends meet, take advantage, build a presence, make a name for yourself.", "id": "bkB2-265"}, {"level": "B2", "topic": "Collocations avançadas", "type": "gaps", "instruction": "Complete as collocations com \"burst\".", "prompt": "When the kids saw the clown, they burst out ___ (laugh). Their little sister, however, was scared and burst into ___.", "answers": [["laughing"], ["tears"]], "explain": "burst out laughing = cair na risada; burst into tears = cair no choro.", "id": "bkB2-266"}, {"level": "B2", "topic": "Collocations avançadas", "type": "gaps", "instruction": "Complete as collocations.", "prompt": "Could you ___ me a hand with the groceries? I'll ___ you a favor next time.", "answers": [["give", "lend"], ["do"]], "explain": "give/lend someone a hand = dar uma mão; do someone a favor = fazer um favor.", "id": "bkB2-267"}, {"level": "B2", "topic": "Collocations avançadas", "type": "choose", "instruction": "Escolha as collocations corretas.", "prompt": "The baby was [fast*/deep] asleep, even though it was [pitch*/deep] dark and thunder was crashing outside.", "explain": "fast asleep = em sono profundo; pitch dark = escuro como breu.", "id": "bkB2-268"}, {"level": "B2", "topic": "Collocations avançadas", "type": "choose", "instruction": "Escolha as collocations corretas.", "prompt": "This restaurant comes [highly*/strongly] recommended. I [strongly*/highly] advise you to book a table in advance.", "explain": "come highly recommended; strongly advise.", "id": "bkB2-269"}, {"level": "B2", "topic": "Collocations avançadas", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "The police believe the crime was made by two men.", "wrong": "made", "fix": ["committed", "carried out"], "explain": "A collocation correta é \"commit a crime\".", "id": "bkB2-270"}, {"level": "B2", "topic": "Collocations avançadas", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "The festival will make place in Olinda next February.", "wrong": "make", "fix": ["take"], "explain": "A collocation correta é \"take place\" (acontecer).", "id": "bkB2-271"}, {"level": "B2", "topic": "Collocations avançadas", "type": "blank", "instruction": "Complete com a palavra que forma a collocation.", "prompt": "The stadium is ___ new; it opened just last week.", "accept": ["brand"], "explain": "\"brand new\" = novinho em folha.", "id": "bkB2-272"}, {"level": "B2", "topic": "Collocations avançadas", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["She", "burst", "into", "tears", "when", "she", "heard", "the", "news"], "alt": ["When she heard the news she burst into tears"], "explain": "\"burst into tears\" = começar a chorar de repente.", "id": "bkB2-273"}, {"level": "B2", "topic": "Collocations avançadas", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["We", "need", "to", "take", "everyone's", "opinion", "into", "account"], "alt": ["We need to take into account everyone's opinion"], "explain": "\"take something into account\" = levar em conta.", "id": "bkB2-274"}, {"level": "B2", "topic": "Collocations avançadas", "type": "match", "instruction": "Ligue o verbo ao complemento.", "left": ["commit", "set", "pose", "lend", "place"], "right": ["an order", "a crime", "a hand", "a record", "a threat"], "correctMap": [1, 3, 4, 2, 0], "explain": "commit a crime, set a record, pose a threat, lend a hand, place an order.", "id": "bkB2-275"}, {"level": "B2", "topic": "Collocations avançadas", "type": "match", "instruction": "Ligue o intensificador ao adjetivo.", "left": ["bitterly", "highly", "sound", "painfully"], "right": ["asleep", "shy", "disappointed", "unlikely"], "correctMap": [2, 3, 0, 1], "explain": "bitterly disappointed, highly unlikely, sound asleep, painfully shy.", "id": "bkB2-276"}, {"level": "B2", "topic": "Collocations avançadas", "type": "sort", "instruction": "Classifique: break ou catch?", "prompt": "Break or catch?", "groups": ["break", "catch"], "items": [{"w": "the silence", "g": 0}, {"w": "someone's eye", "g": 1}, {"w": "a promise", "g": 0}, {"w": "a cold", "g": 1}, {"w": "the law", "g": 0}, {"w": "fire", "g": 1}, {"w": "a habit", "g": 0}, {"w": "your breath", "g": 1}], "explain": "break the silence/a promise/the law/a habit; catch someone's eye/a cold/fire/your breath.", "id": "bkB2-277"}, {"level": "B2", "topic": "Collocations avançadas", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Did the meeting with the investors go well?", "B: Yes, we finally reached an agreement after three hours.", "A: That's great news! Did they ask any difficult questions?", "B: A few, but we had done our homework, so we were ready.", "A: Well done. That's a real weight off your shoulders."], "explain": "reach an agreement, do your homework (preparar-se), a weight off your shoulders.", "id": "bkB2-278"}, {"level": "B2", "topic": "Collocations avançadas", "type": "tf", "instruction": "Leia e marque verdadeiro ou falso.", "text": "Last year, a small town in Goiás launched a campaign to reduce plastic waste. The mayor said the town was facing a serious problem, as the river was heavily polluted. Local schools played a key role, teaching children to recycle. The campaign exceeded all expectations: in just six months, plastic waste fell by 40%. Other towns are now following suit.", "items": [{"s": "The campaign aimed to reduce plastic waste.", "a": true}, {"s": "The river was only slightly polluted.", "a": false}, {"s": "Schools had an important part in the campaign.", "a": true}, {"s": "The results were disappointing.", "a": false}], "explain": "launch a campaign, heavily polluted, play a key role, exceed expectations.", "id": "bkB2-279"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "mcq", "instruction": "Escolha o conector correto.", "prompt": "___ the new subway line, it now takes me only 20 minutes to get to work.", "options": ["Thanks to", "Even so", "Although", "Whereas"], "correctIndex": 0, "explain": "\"Thanks to\" + substantivo indica causa positiva.", "id": "bkB2-280"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "mcq", "instruction": "Escolha o conector correto.", "prompt": "The hotel was fully booked. ___, we managed to find a room nearby.", "options": ["Nonetheless", "Because of", "Despite", "Since"], "correctIndex": 0, "explain": "\"Nonetheless\" = mesmo assim; liga duas frases com contraste.", "id": "bkB2-281"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "mcq", "instruction": "Escolha o conector correto.", "prompt": "___ you're going to the market anyway, could you buy some limes?", "options": ["Since", "Despite", "Whereas", "Even so"], "correctIndex": 0, "explain": "\"Since\" = já que (causa conhecida), seguido de oração.", "id": "bkB2-282"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "gaps", "instruction": "Complete com conectores de contraste.", "prompt": "___ the fact that it was a holiday, the store was open. ___, very few customers came in.", "answers": [["Despite", "In spite of"], ["However", "Nevertheless", "Nonetheless", "Even so", "Still", "Yet", "All the same"]], "explain": "Despite/In spite of + the fact that; However/Nevertheless iniciam nova frase com contraste.", "id": "bkB2-283"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "gaps", "instruction": "Complete o texto com os conectores do banco.", "prompt": "Brazil is famous for its beaches. ___, many tourists prefer the countryside. ___ some visitors love the heat of the Northeast, others choose the mild climate of the South. Many people travel by bus ___ flights are expensive. ___ the long distances, a trip around the country requires careful planning.", "bank": ["However", "While", "since", "On account of", "Despite"], "answers": [["However"], ["While", "Whereas"], ["since", "as", "because"], ["On account of", "Because of", "Owing to", "Due to", "Given"]], "explain": "However: contraste; While: comparação; since: causa + oração; On account of: causa + substantivo.", "id": "bkB2-284"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "choose", "instruction": "Escolha os conectores corretos.", "prompt": "[Much as*/Even] I love my job, I need a break. [Even if*/Even] you apologize, she won't change her mind.", "explain": "Much as = embora (com sentimento); Even if = mesmo que.", "id": "bkB2-285"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "choose", "instruction": "Escolha os conectores corretos.", "prompt": "The project failed [because of*/because] poor planning by the managers. The team, [on the other hand*/on the contrary], worked extremely hard.", "explain": "because of + substantivo; \"on the other hand\" contrasta dois lados (on the contrary corrige uma afirmação).", "id": "bkB2-286"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "Despite of the traffic, we arrived on time.", "wrong": "Despite of", "fix": ["Despite", "In spite of"], "explain": "\"Despite\" não leva \"of\"; ou use \"In spite of\".", "id": "bkB2-287"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "error", "instruction": "Encontre e corrija o erro.", "sentence": "The concert was canceled because of the singer was sick.", "wrong": "because of", "fix": ["because", "since", "as"], "explain": "Antes de oração (sujeito + verbo) use because/since/as, não \"because of\".", "id": "bkB2-288"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "rewrite", "instruction": "Reescreva começando com \"Despite being\".", "prompt": "She is very rich, but she lives in a small apartment.", "start": "Despite being", "accept": ["Despite being very rich, she lives in a small apartment.", "Despite being so rich, she lives in a small apartment."], "explain": "Despite + -ing, mantendo o mesmo sujeito.", "id": "bkB2-289"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "rewrite", "instruction": "Reescreva começando com \"Because of\".", "prompt": "Because it was raining heavily, the match was postponed.", "start": "Because of", "accept": ["Because of the heavy rain, the match was postponed.", "Because of heavy rain, the match was postponed."], "explain": "Because of + substantivo (the heavy rain).", "id": "bkB2-290"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "rewrite", "instruction": "Reescreva com a estrutura \"adjetivo + as\".", "prompt": "Although it was very late, we kept talking.", "start": "Late as", "accept": ["Late as it was, we kept talking."], "explain": "\"Late as it was\" = embora fosse tarde (concessão enfática).", "id": "bkB2-291"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["Given", "that", "it's", "a", "holiday", "the", "roads", "should", "be", "quiet"], "alt": ["The roads should be quiet given that it's a holiday"], "explain": "\"Given that\" = considerando que (causa).", "id": "bkB2-292"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "order", "instruction": "Ordene as palavras para formar a frase.", "words": ["He", "failed", "the", "test", "even", "though", "he", "had", "studied", "hard"], "alt": ["Even though he had studied hard he failed the test"], "explain": "\"even though\" + oração expressa forte contraste.", "id": "bkB2-293"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "match", "instruction": "Ligue as metades das frases.", "left": ["I'll lend you the money,", "Seeing that it's your birthday,", "As a result of the storm,", "Much as I admire her work,"], "right": ["I don't agree with her opinions.", "thousands of homes lost power.", "dinner is on me.", "but you must pay me back by Friday."], "correctMap": [3, 2, 1, 0], "explain": "Seeing that/As a result of: causa; Much as: contraste.", "id": "bkB2-294"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "sort", "instruction": "Classifique os conectores.", "prompt": "Cause or contrast?", "groups": ["Cause", "Contrast"], "items": [{"w": "on account of", "g": 0}, {"w": "much as", "g": 1}, {"w": "seeing that", "g": 0}, {"w": "nonetheless", "g": 1}, {"w": "given that", "g": 0}, {"w": "even so", "g": 1}, {"w": "thanks to", "g": 0}, {"w": "all the same", "g": 1}], "explain": "Causa: on account of, seeing that, given that, thanks to. Contraste: os demais.", "id": "bkB2-295"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Why weren't you at the conference yesterday?", "B: I couldn't go because of a family emergency.", "A: I'm sorry to hear that. Is everything OK now?", "B: Yes, thanks. Even so, I'm sad I missed the keynote speech.", "A: Don't worry. Since it was recorded, you can watch it online."], "explain": "because of (causa), Even so (contraste), Since (causa).", "id": "bkB2-296"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "reading", "instruction": "Leia a carta e responda.", "text": "Dear Mr. Castro, I am writing to complain about my recent stay at your hotel. Although the room was clean, the air conditioning did not work on account of a technical fault. As a result, I could hardly sleep. The staff were polite; nonetheless, nobody came to fix it. Given that I paid for a premium room, I believe I deserve a partial refund. Yours sincerely, Tânia Rocha", "questions": [{"q": "Why didn't the air conditioning work?", "options": ["There was a technical fault.", "The staff switched it off.", "There was a power cut in the city."], "correctIndex": 0}, {"q": "What did Tânia think of the staff?", "options": ["They were rude.", "They were polite but didn't solve the problem.", "They fixed the problem quickly."], "correctIndex": 1}, {"q": "What does Tânia want?", "options": ["A free night", "A different room", "Some of her money back"], "correctIndex": 2}], "explain": "on account of (causa), As a result (consequência), nonetheless (contraste), Given that (causa).", "id": "bkB2-297"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "tf", "instruction": "Leia e marque verdadeiro ou falso.", "text": "Much as Leandro enjoys living in São Paulo, he sometimes misses his hometown in Bahia. Thanks to his new job, he earns a good salary. Even so, the cost of living is so high that he saves very little. Since he works from home twice a week, he has more time for his hobbies. Nonetheless, he plans to move back to Bahia in a few years.", "items": [{"s": "Leandro dislikes living in São Paulo.", "a": false}, {"s": "His salary is good.", "a": true}, {"s": "Leandro saves a lot of money.", "a": false}, {"s": "He intends to return to Bahia eventually.", "a": true}], "explain": "Much as (embora), Thanks to (graças a), Even so, Since, Nonetheless.", "id": "bkB2-298"}, {"level": "B2", "topic": "Conectores de causa/contraste avançados", "type": "blank", "instruction": "Complete com um conector de causa (2 a 4 palavras).", "prompt": "The flight was delayed ___ a problem with the engine.", "accept": ["because of", "due to", "owing to", "on account of", "as a result of"], "explain": "Causa + substantivo: because of, due to, owing to, on account of, as a result of.", "id": "bkB2-299"}, {"type": "mcq", "level": "C1", "topic": "Subjuntivo", "instruction": "Escolha a forma correta do verbo.", "prompt": "The board insisted that the CFO ___ the report before Friday.", "options": ["submits", "submit", "submitting", "will submit"], "correctIndex": 1, "explain": "Após verbos como insist, demand, suggest (sentido de ordem), usa-se o subjuntivo: forma base, sem -s.", "id": "bkC1-0"}, {"type": "choose", "level": "C1", "topic": "Subjuntivo", "instruction": "Escolha a palavra correta em cada grupo.", "prompt": "It is essential that every passenger [wears/wear*] a seatbelt and that no one [is/be*] left standing.", "explain": "Depois de 'It is essential that' usa-se o subjuntivo: forma base (wear, be) para todas as pessoas.", "id": "bkC1-1"}, {"type": "error", "level": "C1", "topic": "Subjuntivo", "instruction": "Encontre e corrija o erro.", "sentence": "The doctor recommended that she takes a week off work.", "wrong": "takes", "fix": ["take", "should take"], "explain": "Recommend that pede subjuntivo: forma base 'take' (ou 'should take'), sem -s. (No inglês britânico, a forma comum com -s também aparece; aqui seguimos o padrão americano.)", "id": "bkC1-2"}, {"type": "gaps", "level": "C1", "topic": "Subjuntivo", "instruction": "Complete com o subjuntivo do verbo entre parênteses.", "prompt": "If I ___ (be) you, I would accept the offer. The committee demanded that he ___ (resign) immediately.", "answers": [["were"], ["resign", "should resign"]], "explain": "'If I were' é o subjuntivo formal; após demand that usa-se a forma base (resign).", "id": "bkC1-3"}, {"type": "rewrite", "level": "C1", "topic": "Subjuntivo", "instruction": "Reescreva com o subjuntivo, começando como indicado.", "prompt": "The manager said: \"All staff must attend the meeting.\"", "start": "The manager insisted that all staff", "accept": ["The manager insisted that all staff attend the meeting", "The manager insisted that all staff should attend the meeting"], "explain": "Insist that + sujeito + forma base (attend) expressa exigência no subjuntivo.", "id": "bkC1-4"}, {"type": "match", "level": "C1", "topic": "Subjuntivo", "instruction": "Ligue cada expressão fixa ao seu significado.", "left": ["Be that as it may", "Suffice it to say", "Come what may", "Far be it from me"], "right": ["whatever happens", "I don't want to criticize, but", "nevertheless / even so", "I'll just say briefly that"], "correctMap": [2, 3, 0, 1], "explain": "São expressões fixas que conservam o subjuntivo antigo (be, suffice, come).", "id": "bkC1-5"}, {"type": "order", "level": "C1", "topic": "Subjuntivo", "instruction": "Ordene as palavras para formar a frase.", "words": ["It", "is", "vital", "that", "the", "client", "be", "informed"], "explain": "'It is vital that' + sujeito + be + particípio: subjuntivo na voz passiva.", "id": "bkC1-6"}, {"type": "dorder", "level": "C1", "topic": "Subjuntivo", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Did you read the new policy from HR?", "B: Yes. They're requiring that everyone be back in the office three days a week.", "A: Three days? I'd rather they gave us more flexibility.", "B: Me too. I suggested that the rule apply only to new hires, but nobody listened."], "explain": "A pergunta abre; 'Three days?' reage à política; 'Me too' concorda com a opinião anterior.", "id": "bkC1-7"}, {"type": "tf", "level": "C1", "topic": "Subjuntivo", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Last month, the city council of Curitiba passed a new regulation on street noise. It requires that bars close their outdoor areas at 11 p.m. on weekdays. Some owners proposed that the rule apply only to residential areas, but the council rejected the idea. However, it did recommend that the police be flexible during the first month. Residents had long demanded that something be done.", "items": [{"s": "Bars must close their outdoor areas at 11 p.m. on weekdays.", "a": true}, {"s": "The council accepted the owners' proposal.", "a": false}, {"s": "The council suggested that the police be flexible at first.", "a": true}, {"s": "Residents had never complained about the noise.", "a": false}], "explain": "O texto diz que o conselho rejeitou a proposta e que os moradores exigiam uma solução havia tempo.", "id": "bkC1-8"}, {"type": "sort", "level": "C1", "topic": "Subjuntivo", "instruction": "Classifique: 'It is ___ that he be...' aceita subjuntivo?", "groups": ["Pede subjuntivo", "Não pede subjuntivo"], "items": [{"w": "essential", "g": 0}, {"w": "imperative", "g": 0}, {"w": "vital", "g": 0}, {"w": "advisable", "g": 0}, {"w": "obvious", "g": 1}, {"w": "likely", "g": 1}, {"w": "true", "g": 1}, {"w": "evident", "g": 1}], "explain": "Adjetivos de necessidade ou importância pedem subjuntivo; os de certeza ou probabilidade, não.", "prompt": "Classifique: 'It is ___ that he be...' aceita subjuntivo?", "id": "bkC1-9"}, {"type": "mcq", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Escolha a palavra que completa a frase clivada.", "prompt": "___ I need right now is a long vacation.", "options": ["That", "What", "Which", "It"], "correctIndex": 1, "explain": "Na pseudo-clivada, 'What' (= a coisa que) introduz a oração enfatizada: What I need is...", "id": "bkC1-10"}, {"type": "choose", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Escolha a palavra correta em cada grupo.", "prompt": "It was Carla [who*/what] fixed the bug, and what impressed us [was*/were] her speed.", "explain": "Para pessoas usa-se 'who' (ou that); a oração com 'what' é singular, logo 'was'.", "id": "bkC1-11"}, {"type": "rewrite", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Reescreva enfatizando QUEM quebrou a impressora.", "prompt": "Rafael broke the printer.", "start": "It was Rafael", "accept": ["It was Rafael who broke the printer", "It was Rafael that broke the printer"], "explain": "It was + elemento enfatizado + who/that + resto da frase.", "id": "bkC1-12"}, {"type": "error", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Encontre e corrija o erro.", "sentence": "What I really want it is a quiet place to work.", "wrong": "it is", "fix": ["is"], "explain": "Na estrutura 'What... is', não se repete o sujeito 'it': What I want is...", "id": "bkC1-13"}, {"type": "gaps", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Complete as frases clivadas.", "prompt": "It ___ (be) only when I moved abroad ___ I realized how much I missed Brazilian food. What I miss most ___ (be) my mother's feijoada.", "answers": [["was"], ["that"], ["is"]], "explain": "It was only when... that...: estrutura clivada com tempo passado; 'What I miss most is' no presente.", "id": "bkC1-14"}, {"type": "order", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Ordene as palavras para formar a frase.", "words": ["What", "we", "need", "is", "a", "clear", "plan"], "alt": ["A clear plan is what we need"], "explain": "Pseudo-clivada: What + oração + is + foco (a clear plan).", "id": "bkC1-15"}, {"type": "match", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Ligue as metades para formar frases clivadas.", "left": ["It was in 2014", "What annoys me", "All she wanted", "The reason I called"], "right": ["was a little respect.", "is that he never listens.", "that Brazil hosted the World Cup.", "is to invite you to dinner."], "correctMap": [2, 1, 0, 3], "explain": "Cada início pede um complemento: It was... that; What... is that; All... was; The reason... is to.", "id": "bkC1-16"}, {"type": "reading", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Leia o e-mail e responda às perguntas.", "text": "Hi Marcos,\nThanks for the feedback on the proposal. What the client liked most was the budget section, so we should keep it as it is. It's the timeline that worries them: they think six months is too long. What I suggest is that we cut the testing phase to three weeks. It was Júlia who designed the original schedule, so let's ask her first.\nBest,\nPaula", "questions": [{"q": "What did the client like most?", "options": ["The budget section", "The timeline", "The testing phase"], "correctIndex": 0}, {"q": "What is the client worried about?", "options": ["The cost", "The length of the project", "The design team"], "correctIndex": 1}, {"q": "Who created the original schedule?", "options": ["Marcos", "Paula", "Júlia"], "correctIndex": 2}], "explain": "As frases clivadas destacam a informação-chave: o orçamento, o prazo e quem fez o cronograma.", "id": "bkC1-17"}, {"type": "dorder", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: So, you finally quit your job at the bank?", "B: Yes, but it wasn't the salary that made me leave.", "A: Really? What was it, then?", "B: What I couldn't stand was the two-hour commute every day."], "explain": "B nega o motivo esperado, A pergunta qual foi, e B revela com uma pseudo-clivada.", "id": "bkC1-18"}, {"type": "odd", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Qual frase NÃO é clivada?", "prompt": "Which sentence is NOT a cleft sentence?", "options": ["It was Ana who called.", "What I need is sleep.", "It is raining in São Paulo.", "All I did was ask."], "correctIndex": 2, "explain": "'It is raining' usa 'it' impessoal; as outras dividem a frase para enfatizar um elemento.", "id": "bkC1-19"}, {"type": "mcq", "level": "C1", "topic": "Inversão avançada", "instruction": "Escolha a opção que completa a inversão.", "prompt": "No sooner ___ the meeting started than the fire alarm went off.", "options": ["had", "has", "did", "was"], "correctIndex": 0, "explain": "No sooner + had + sujeito + particípio... than: inversão com past perfect.", "id": "bkC1-20"}, {"type": "choose", "level": "C1", "topic": "Inversão avançada", "instruction": "Escolha a opção correta em cada grupo.", "prompt": "Hardly had we sat down [when*/than] the phone rang. Little [she knew/did she know*] that the offer was a trap.", "explain": "Hardly... when (não than); após 'Little' negativo inverte-se com auxiliar: did she know.", "id": "bkC1-21"}, {"type": "gaps", "level": "C1", "topic": "Inversão avançada", "instruction": "Complete com a inversão condicional adequada.", "prompt": "___ I known about the strike, I would have taken the metro. ___ you need any help, please call reception. ___ it not for your support, we would be lost.", "answers": [["Had"], ["Should"], ["Were"]], "bank": ["Had", "Should", "Were", "Did"], "explain": "Had = if I had (3º cond.); Should = if you should; Were it not for = if it weren't for.", "id": "bkC1-22"}, {"type": "rewrite", "level": "C1", "topic": "Inversão avançada", "instruction": "Reescreva começando com 'Never' e fazendo a inversão.", "prompt": "I had never seen such a beautiful beach.", "start": "Never", "accept": ["Never had I seen such a beautiful beach", "Never before had I seen such a beautiful beach"], "explain": "Advérbio negativo no início exige inversão: Never + had + I + seen.", "id": "bkC1-23"}, {"type": "blank", "level": "C1", "topic": "Inversão avançada", "instruction": "Complete com a inversão condicional (sem usar 'if').", "prompt": "___ you require further assistance, please contact our staff.", "accept": ["Should"], "explain": "'Should you require' equivale a 'If you require', em registro formal.", "id": "bkC1-24"}, {"type": "error", "level": "C1", "topic": "Inversão avançada", "instruction": "Encontre e corrija o erro.", "sentence": "Not only she speaks French, but she also speaks Japanese.", "wrong": "she speaks French", "fix": ["does she speak French"], "explain": "'Not only' no início exige inversão com auxiliar: Not only does she speak...", "id": "bkC1-25"}, {"type": "order", "level": "C1", "topic": "Inversão avançada", "instruction": "Ordene as palavras para formar a frase.", "words": ["Under", "no", "circumstances", "should", "you", "open", "this", "door"], "explain": "'Under no circumstances' no início pede inversão: should + you + verbo.", "id": "bkC1-26"}, {"type": "tf", "level": "C1", "topic": "Inversão avançada", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Only after the audit was completed did the company admit the losses. Not until last week were the employees told about the layoffs. Rarely has the town of Blumenau seen such anger. So strong was the reaction that the CEO resigned two days later.", "items": [{"s": "The company admitted the losses before the audit.", "a": false}, {"s": "The employees learned about the layoffs last week.", "a": true}, {"s": "Blumenau often sees this kind of anger.", "a": false}, {"s": "The CEO resigned because of the strong reaction.", "a": true}], "explain": "'Only after' = só depois; 'Rarely has' = raramente; 'So strong was... that' indica consequência.", "id": "bkC1-27"}, {"type": "match", "level": "C1", "topic": "Inversão avançada", "instruction": "Ligue as metades para formar frases com inversão.", "left": ["Seldom", "No sooner had I arrived", "Only when she explained it", "Such was her talent"], "right": ["that she won a scholarship.", "did I understand the problem.", "than it started to rain.", "have I met anyone so generous."], "correctMap": [3, 2, 1, 0], "explain": "Seldom + have I; No sooner... than; Only when... did I; Such was... that.", "id": "bkC1-28"}, {"type": "dorder", "level": "C1", "topic": "Inversão avançada", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: How was the job interview?", "B: Terrible. Not only was I late, but I also forgot the manager's name.", "A: Oh no! Did they say anything about it?", "B: No, but never have I felt so embarrassed in my life."], "explain": "A pergunta, B conta o problema, A reage e B conclui com outra inversão.", "id": "bkC1-29"}, {"type": "mcq", "level": "C1", "topic": "Nominalização", "instruction": "Escolha o substantivo correto.", "prompt": "The ___ of the new bridge took three years.", "options": ["construct", "construction", "constructive", "constructing"], "correctIndex": 1, "explain": "Depois de 'The ... of' precisamos de um substantivo: construction.", "id": "bkC1-30"}, {"type": "sort", "level": "C1", "topic": "Nominalização", "instruction": "Classifique os verbos pelo sufixo do substantivo correspondente.", "groups": ["-tion / -sion", "-ment", "-ance / -ence"], "items": [{"w": "decide", "g": 0}, {"w": "reduce", "g": 0}, {"w": "invade", "g": 0}, {"w": "improve", "g": 1}, {"w": "develop", "g": 1}, {"w": "assist", "g": 2}, {"w": "refer", "g": 2}, {"w": "appear", "g": 2}], "explain": "decision, reduction, invasion; improvement, development; assistance, reference, appearance.", "prompt": "Classifique os verbos pelo sufixo do substantivo correspondente.", "id": "bkC1-31"}, {"type": "gaps", "level": "C1", "topic": "Nominalização", "instruction": "Complete com o substantivo formado a partir do verbo.", "prompt": "The ___ (fail) of the project led to the ___ (resign) of two directors. There has also been a sharp ___ (reduce) in costs.", "answers": [["failure"], ["resignation"], ["reduction"]], "explain": "fail → failure; resign → resignation; reduce → reduction.", "id": "bkC1-32"}, {"type": "rewrite", "level": "C1", "topic": "Nominalização", "instruction": "Reescreva usando substantivos em vez de verbos, começando como indicado.", "prompt": "The company expanded rapidly, which surprised investors.", "start": "The company's rapid", "accept": ["The company's rapid expansion surprised investors"], "explain": "expanded rapidly → rapid expansion: o verbo vira substantivo e o advérbio vira adjetivo.", "id": "bkC1-33"}, {"type": "rewrite", "level": "C1", "topic": "Nominalização", "instruction": "Reescreva transformando 'decided' em substantivo.", "prompt": "They decided to close the factory, and this caused protests.", "start": "The decision", "accept": ["The decision to close the factory caused protests", "The decision to close the factory led to protests", "The decision to close the factory sparked protests"], "explain": "decided → the decision; a nominalização deixa o texto mais conciso e formal.", "id": "bkC1-34"}, {"type": "error", "level": "C1", "topic": "Nominalização", "instruction": "Encontre e corrija o erro.", "sentence": "The analyze of the data will take two weeks.", "wrong": "analyze", "fix": ["analysis"], "explain": "'Analyze' é verbo; depois de 'The ... of' é preciso o substantivo 'analysis'.", "id": "bkC1-35"}, {"type": "choose", "level": "C1", "topic": "Nominalização", "instruction": "Escolha a palavra correta em cada grupo.", "prompt": "We were impressed by her [able/ability*] to stay calm and her [willing/willingness*] to help.", "explain": "Após o possessivo 'her' vem substantivo: ability, willingness.", "id": "bkC1-36"}, {"type": "match", "level": "C1", "topic": "Nominalização", "instruction": "Ligue cada frase à sua versão nominalizada.", "left": ["Prices rose sharply.", "The team performed poorly.", "The minister refused to comment.", "Unemployment fell."], "right": ["the fall in unemployment", "the minister's refusal to comment", "the sharp rise in prices", "the team's poor performance"], "correctMap": [2, 3, 1, 0], "explain": "rose → rise; performed → performance; refused → refusal; fell → fall.", "id": "bkC1-37"}, {"type": "reading", "level": "C1", "topic": "Nominalização", "instruction": "Leia o relatório e responda às perguntas.", "text": "Report: Customer Service, Q3. Following the introduction of the new chatbot in July, there was a significant reduction in waiting times. However, the failure of the system during the Black Friday sales caused widespread dissatisfaction among customers. The management's recommendation is the recruitment of five additional agents before December. The implementation of this plan will require approval from the finance department.", "questions": [{"q": "What happened after the chatbot was introduced?", "options": ["Waiting times got shorter", "More customers complained", "Five agents were hired"], "correctIndex": 0}, {"q": "What caused customer dissatisfaction?", "options": ["The high prices", "The system failure during a sale", "The long waiting times in July"], "correctIndex": 1}, {"q": "What does management recommend?", "options": ["Removing the chatbot", "Hiring more agents", "Cutting the finance budget"], "correctIndex": 1}], "explain": "reduction = diminuição; failure = falha; recruitment = contratação. Relatórios formais usam muitas nominalizações.", "id": "bkC1-38"}, {"type": "odd", "level": "C1", "topic": "Nominalização", "instruction": "Qual palavra NÃO é substantivo?", "prompt": "Which word is NOT a noun?", "options": ["arrival", "refusal", "approval", "verbal"], "correctIndex": 3, "explain": "O sufixo -al forma substantivos a partir de verbos (arrive → arrival); 'verbal' é adjetivo.", "id": "bkC1-39"}, {"type": "mcq", "level": "C1", "topic": "Discourse markers formais", "instruction": "Escolha o conector mais adequado.", "prompt": "The results were promising. ___, further research is needed before any conclusions can be drawn.", "options": ["Nevertheless", "Consequently", "Furthermore", "Hence"], "correctIndex": 0, "explain": "'Nevertheless' introduz um contraste: os resultados são bons, mas ainda falta pesquisa.", "id": "bkC1-40"}, {"type": "gaps", "level": "C1", "topic": "Discourse markers formais", "instruction": "Complete o texto com os conectores do banco.", "prompt": "The proposal has several advantages. ___, it would reduce costs by 20%. ___, it would improve staff morale. ___, the plan has not been tested on a large scale. ___, we recommend a pilot project before full implementation.", "answers": [["Firstly", "First", "First of all", "To begin with"], ["Moreover", "Furthermore", "In addition", "Additionally"], ["However", "Nevertheless", "Nonetheless"], ["Therefore", "Consequently", "Thus", "Hence"]], "bank": ["Firstly", "Moreover", "However", "Therefore", "Whereas"], "explain": "Firstly inicia a lista; Moreover acrescenta; However contrasta; Therefore conclui.", "id": "bkC1-41"}, {"type": "choose", "level": "C1", "topic": "Discourse markers formais", "instruction": "Escolha o conector correto em cada grupo.", "prompt": "Brazil's north is hot and humid, [whereas*/moreover] the south can be quite cold in winter. The flight was delayed; [consequently*/nevertheless], we missed the connection.", "explain": "'Whereas' contrasta duas situações; 'consequently' indica resultado.", "id": "bkC1-42"}, {"type": "error", "level": "C1", "topic": "Discourse markers formais", "instruction": "Encontre e corrija o erro.", "sentence": "The company made record profits. Despite, it laid off 200 workers.", "wrong": "Despite", "fix": ["Nevertheless", "Nonetheless", "However", "Even so", "Despite this", "Despite that", "In spite of this"], "explain": "'Despite' é preposição e precisa de complemento; sozinho, use 'Nevertheless' ou 'Despite this'.", "id": "bkC1-43"}, {"type": "match", "level": "C1", "topic": "Discourse markers formais", "instruction": "Ligue cada conector à sua função.", "left": ["Moreover", "Consequently", "Nevertheless", "In other words"], "right": ["to rephrase an idea", "to introduce a contrast", "to add information", "to show a result"], "correctMap": [2, 3, 1, 0], "explain": "Moreover = além disso; Consequently = consequentemente; Nevertheless = mesmo assim; In other words = ou seja.", "id": "bkC1-44"}, {"type": "order", "level": "C1", "topic": "Discourse markers formais", "instruction": "Ordene as palavras para formar a frase.", "words": ["In", "light", "of", "these", "findings", "the", "policy", "will", "be", "revised"], "alt": ["The policy will be revised in light of these findings"], "explain": "'In light of' (tendo em vista) é um marcador formal que pode abrir ou fechar a frase.", "id": "bkC1-45"}, {"type": "dorder", "level": "C1", "topic": "Discourse markers formais", "instruction": "Coloque o diálogo da reunião na ordem correta.", "lines": ["A: Shall we begin? First of all, thank you all for coming.", "B: Thank you. To begin with, could you summarize last quarter's results?", "A: Certainly. Sales rose by 12%. However, our costs also increased significantly.", "B: I see. In that case, what do you propose?", "A: In short, we need to renegotiate our supplier contracts."], "explain": "A reunião abre com 'First of all', segue o resumo, a pergunta 'In that case' e a conclusão 'In short'.", "id": "bkC1-46"}, {"type": "tf", "level": "C1", "topic": "Discourse markers formais", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Remote work has clear benefits for employees. For instance, it eliminates long commutes. Nonetheless, some studies suggest that it may reduce collaboration. By contrast, managers of hybrid teams report higher productivity. Consequently, many companies in São Paulo now require two office days per week.", "items": [{"s": "The text says remote work eliminates long commutes.", "a": true}, {"s": "All studies show that remote work improves collaboration.", "a": false}, {"s": "Managers of hybrid teams report lower productivity.", "a": false}, {"s": "Many companies in São Paulo require some office days.", "a": true}], "explain": "'Nonetheless' introduz uma desvantagem; 'By contrast' e 'Consequently' levam à exigência de dias no escritório.", "id": "bkC1-47"}, {"type": "rewrite", "level": "C1", "topic": "Discourse markers formais", "instruction": "Reescreva em duas frases usando 'Nevertheless'.", "prompt": "Although the budget was limited, the team delivered an excellent product.", "start": "The budget was limited. Nevertheless,", "accept": ["The budget was limited. Nevertheless, the team delivered an excellent product"], "explain": "'Although' une orações; 'Nevertheless' inicia uma nova frase com a mesma ideia de contraste.", "id": "bkC1-48"}, {"type": "odd", "level": "C1", "topic": "Discourse markers formais", "instruction": "Qual conector NÃO expressa contraste?", "prompt": "Which marker does NOT express contrast?", "options": ["nonetheless", "whereas", "conversely", "hence"], "correctIndex": 3, "explain": "'Hence' indica consequência (portanto); os outros expressam contraste.", "id": "bkC1-49"}, {"type": "mcq", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Escolha a opção que expressa possibilidade no passado.", "prompt": "Carlos isn't answering. He ___ his phone at home, but I'm not sure.", "options": ["might have left", "must leave", "should have left", "can have left"], "correctIndex": 0, "explain": "'Might have + particípio' expressa uma possibilidade no passado, sem certeza.", "id": "bkC1-50"}, {"type": "choose", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Escolha a opção correta em cada grupo.", "prompt": "I'm not sure where Lia is. She [may have gone*/must go] to the gym, or she [could have stayed*/can have stayed] at work late.", "explain": "Especulação sobre o passado: may/could have + particípio. 'Can have' não se usa assim.", "id": "bkC1-51"}, {"type": "gaps", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Complete com may/might/could have + particípio (especulação).", "prompt": "A: Why is the road wet?\nB: I'm not certain. It ___ (rain) during the night.\nA: And why is Pedro so tired?\nB: He ___ (not / sleep) well, but I'm only guessing.", "answers": [["might have rained", "may have rained", "could have rained"], ["might not have slept", "may not have slept"]], "explain": "Possibilidade no passado: might/may/could have rained. Na negativa, might/may not have; 'couldn't have' seria impossibilidade.", "id": "bkC1-52"}, {"type": "error", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Encontre e corrija o erro.", "sentence": "She might has forgotten about the meeting.", "wrong": "has", "fix": ["have"], "explain": "Depois de modal usa-se sempre 'have' + particípio, nunca 'has'.", "id": "bkC1-53"}, {"type": "rewrite", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Reescreva sem 'Perhaps', usando um modal de especulação.", "prompt": "Perhaps they missed the train.", "start": "They", "accept": ["They may have missed the train", "They might have missed the train", "They could have missed the train"], "explain": "'Perhaps' + passado = may/might/could have + particípio.", "id": "bkC1-54"}, {"type": "match", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Ligue cada frase ao seu significado.", "left": ["She may have taken the bus.", "He can't have seen us.", "They must have won.", "You could have told me!"], "right": ["It's certain that they won.", "It's possible that she took the bus.", "It's impossible that he saw us.", "You didn't tell me, and I'm annoyed."], "correctMap": [1, 2, 0, 3], "explain": "may have = possível; can't have = impossível; must have = certeza; could have (crítica) = você não fez.", "id": "bkC1-55"}, {"type": "sort", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Classifique: possibilidade ou certeza sobre o passado?", "groups": ["Possibilidade", "Certeza (positiva ou negativa)"], "items": [{"w": "might have left", "g": 0}, {"w": "may have lost", "g": 0}, {"w": "could have forgotten", "g": 0}, {"w": "might not have heard", "g": 0}, {"w": "must have known", "g": 1}, {"w": "can't have heard", "g": 1}, {"w": "couldn't have seen", "g": 1}], "explain": "may/might/could have = talvez; must have = com certeza; can't/couldn't have = com certeza não.", "prompt": "Classifique: possibilidade ou certeza sobre o passado?", "id": "bkC1-56"}, {"type": "reading", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Leia a história e responda às perguntas.", "text": "When Beatriz got home, the front door was open and the lights were on. Nothing seemed to be missing, so it can't have been a burglar. Her brother has a key, so he might have come by to pick up his guitar. On the other hand, she may have forgotten to lock the door herself that morning, since she had left in a hurry. She decided to call her brother before calling the police.", "questions": [{"q": "What does Beatriz think about a burglar?", "options": ["It's impossible that it was a burglar", "A burglar probably came in", "She's sure a burglar came in"], "correctIndex": 0}, {"q": "Why might her brother have come?", "options": ["To pick up his guitar", "To fix the lights", "To call the police"], "correctIndex": 0}, {"q": "Why is it possible that she left the door unlocked?", "options": ["She lost her key", "She was in a hurry that morning", "Her brother told her to"], "correctIndex": 1}], "explain": "'can't have been' = impossível; 'might have come' e 'may have forgotten' = possibilidades.", "id": "bkC1-57"}, {"type": "dorder", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Have you seen my sunglasses? I can't find them anywhere.", "B: You might have left them in the car.", "A: No, I've already checked there.", "B: Then you may have dropped them at the beach. Or someone could have picked them up by mistake."], "explain": "A pergunta, B especula, A descarta o carro e B sugere outras possibilidades.", "id": "bkC1-58"}, {"type": "order", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Ordene as palavras para formar a frase.", "words": ["They", "might", "not", "have", "received", "our", "email"], "explain": "Negativa da especulação: might + not + have + particípio.", "id": "bkC1-59"}, {"type": "mcq", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Escolha o verbo que forma o causativo.", "prompt": "I'm going to ___ my hair cut before the wedding.", "options": ["have", "make", "let", "do"], "correctIndex": 0, "explain": "Have + objeto + particípio: alguém faz o serviço para você (cortar o cabelo no salão).", "id": "bkC1-60"}, {"type": "choose", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Escolha a forma correta em cada grupo.", "prompt": "We had our roof [repair/repaired*] last week, and we're getting the garden [redesign/redesigned*] next month.", "explain": "No causativo, o verbo principal fica no particípio: repaired, redesigned.", "id": "bkC1-61"}, {"type": "gaps", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Complete com a estrutura causativa.", "prompt": "A: Your car looks great!\nB: Thanks, I ___ it ___ (wash) yesterday.", "answers": [["had", "got"], ["washed"]], "explain": "had/got + objeto + particípio (washed): outra pessoa lavou o carro.", "id": "bkC1-62"}, {"type": "rewrite", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Reescreva com 'have something done', começando como indicado.", "prompt": "A mechanic is checking my brakes.", "start": "I'm having", "accept": ["I'm having my brakes checked", "I'm having my brakes checked by a mechanic"], "explain": "Present continuous do causativo: am having + objeto + particípio (checked).", "id": "bkC1-63"}, {"type": "blank", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Complete com a forma correta do verbo entre parênteses.", "prompt": "We're ___ (have) the kitchen renovated next month.", "accept": ["having"], "explain": "Plano futuro com present continuous: are having + objeto + particípio.", "id": "bkC1-64"}, {"type": "error", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Encontre e corrija o erro.", "sentence": "She had her passport steal while traveling in Europe.", "wrong": "steal", "fix": ["stolen"], "explain": "Have something done também indica algo ruim que aconteceu; o verbo vai no particípio: stolen.", "id": "bkC1-65"}, {"type": "match", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Ligue as metades das frases.", "left": ["I had the technician", "I got my neighbor", "I had my phone", "I got my suit"], "right": ["dry-cleaned.", "install the new router.", "screen replaced.", "to water my plants."], "correctMap": [1, 3, 2, 0], "explain": "have + pessoa + verbo base; get + pessoa + to + verbo; have/get + coisa + particípio.", "id": "bkC1-66"}, {"type": "order", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Ordene as palavras para formar a frase.", "words": ["She", "is", "having", "her", "apartment", "painted", "next", "week"], "alt": ["Next week she is having her apartment painted"], "explain": "Sujeito + is having + objeto + particípio (painted) + tempo.", "id": "bkC1-67"}, {"type": "tf", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Last Saturday, Rodrigo had a busy day of errands in Belo Horizonte. In the morning, he had his car serviced at a garage near his house. While he waited, he got his hair cut at the barbershop next door. In the afternoon, he tried to fix his broken washing machine himself, but he failed, so he's having it repaired by a technician on Monday.", "items": [{"s": "Rodrigo serviced his car himself.", "a": false}, {"s": "He got a haircut while he was waiting for his car.", "a": true}, {"s": "He managed to fix the washing machine himself.", "a": false}, {"s": "A technician will repair the machine on Monday.", "a": true}], "explain": "'had his car serviced' e 'having it repaired' indicam que outras pessoas fizeram o serviço.", "id": "bkC1-68"}, {"type": "odd", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Qual frase NÃO é causativa?", "prompt": "Which sentence is NOT causative?", "options": ["I had my teeth whitened.", "She got her visa approved.", "He had a sandwich for lunch.", "We got the windows cleaned."], "correctIndex": 2, "explain": "'Had a sandwich' = comeu um sanduíche; nas outras, alguém faz um serviço para o sujeito.", "id": "bkC1-69"}, {"type": "mcq", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Escolha o verbo que forma a colocação correta.", "prompt": "It's hard to ___ a balance between work and family life.", "options": ["strike", "hit", "make", "do"], "correctIndex": 0, "explain": "A colocação fixa é 'strike a balance' (encontrar um equilíbrio).", "id": "bkC1-70"}, {"type": "choose", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Escolha a palavra correta em cada grupo.", "prompt": "The committee finally [reached*/arrived] a consensus, and we managed to [meet*/win] the deadline.", "explain": "Colocações: 'reach a consensus' e 'meet a deadline' (cumprir o prazo).", "id": "bkC1-71"}, {"type": "gaps", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Complete o e-mail com as palavras do banco.", "prompt": "Dear team, please ___ in mind that the report is due on Friday. I know the workload is heavy, but I'm ___ aware of your efforts. Before we ___ any conclusions about the survey, let's ___ into account the low response rate.", "answers": [["bear", "keep"], ["fully", "well"], ["draw"], ["take"]], "bank": ["bear", "fully", "draw", "take", "make", "strongly"], "explain": "Colocações: bear in mind, fully aware, draw conclusions, take into account.", "id": "bkC1-72"}, {"type": "error", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Encontre e corrija o erro.", "sentence": "The new campaign aims to rise awareness of climate change.", "wrong": "rise", "fix": ["raise"], "explain": "A colocação é 'raise awareness'; 'rise' é intransitivo e não tem objeto.", "id": "bkC1-73"}, {"type": "odd", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Qual palavra NÃO combina com o verbo 'pay'?", "prompt": "Which noun does NOT go with the verb 'pay'?", "options": ["attention", "a compliment", "a visit", "a photo"], "correctIndex": 3, "explain": "Dizemos pay attention, pay a compliment, pay a visit; mas 'take a photo'.", "id": "bkC1-74"}, {"type": "match", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Ligue o adjetivo ao substantivo para formar colocações.", "left": ["a steep", "a vicious", "a hectic", "an acquired"], "right": ["taste", "schedule", "circle", "increase"], "correctMap": [3, 2, 1, 0], "explain": "a steep increase, a vicious circle, a hectic schedule, an acquired taste.", "id": "bkC1-75"}, {"type": "rewrite", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Reescreva usando 'give ... serious consideration'.", "prompt": "She considered the offer seriously.", "start": "She gave the offer", "accept": ["She gave the offer serious consideration"], "explain": "consider seriously = give something serious consideration, colocação mais formal.", "id": "bkC1-76"}, {"type": "reading", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Leia a carta e responda às perguntas.", "text": "Dear Ms. Andrade,\nThank you for your application. I'm afraid we have decided not to move forward with it at this stage. This was a tough decision, as you made a strong impression during the interview. However, we were looking for someone with more hands-on experience in logistics. We will keep your CV on file and get in touch if a suitable position becomes available. We wish you every success.", "questions": [{"q": "Did Ms. Andrade get the job?", "options": ["Yes", "No", "The decision hasn't been made yet"], "correctIndex": 1}, {"q": "How did she do in the interview?", "options": ["She impressed the interviewers", "She arrived late", "She lacked confidence"], "correctIndex": 0}, {"q": "What will the company do with her CV?", "options": ["Send it back", "Keep it for future openings", "Share it with other companies"], "correctIndex": 1}], "explain": "'made a strong impression' = impressionou; 'keep your CV on file' = guardar o currículo.", "id": "bkC1-77"}, {"type": "order", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Ordene as palavras para formar a frase.", "words": ["The", "government", "should", "take", "these", "concerns", "into", "account"], "alt": ["The government should take into account these concerns"], "explain": "'Take something into account' = levar algo em consideração.", "id": "bkC1-78"}, {"type": "dorder", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Can we get down to business? We're running out of time.", "B: Sure. Let me start by making a quick point about the budget.", "A: Go ahead, but bear in mind that we can't increase it.", "B: Understood. I just want to draw your attention to the marketing costs."], "explain": "A propõe começar, B pede a palavra, A autoriza com um aviso e B faz o ponto.", "id": "bkC1-79"}, {"type": "mcq", "level": "C1", "topic": "Elipse e substituição", "instruction": "Escolha a resposta mais lógica.", "prompt": "A: Will it rain tomorrow?\nB: I hope ___. I left my umbrella at the office.", "options": ["not", "so", "it", "neither"], "correctIndex": 0, "explain": "'I hope not' substitui 'I hope it won't rain'; B não tem guarda-chuva.", "id": "bkC1-80"}, {"type": "choose", "level": "C1", "topic": "Elipse e substituição", "instruction": "Escolha a palavra correta em cada grupo.", "prompt": "These shoes are too small. Do you have any bigger [ones*/one]? Mariana can't swim, and [neither*/either] can her husband.", "explain": "'ones' substitui um substantivo plural; 'neither can' concorda com uma negativa.", "id": "bkC1-81"}, {"type": "gaps", "level": "C1", "topic": "Elipse e substituição", "instruction": "Complete com a palavra que evita repetição.", "prompt": "A: Are you coming to the party?\nB: I'd love ___, but I have to work.\nA: What a pity! Paulo isn't coming either.\nB: Really? I thought he ___.", "answers": [["to"], ["was", "would", "was coming", "would come"]], "explain": "'I'd love to' omite o verbo; 'I thought he was' retoma 'coming' sem repeti-lo.", "id": "bkC1-82"}, {"type": "error", "level": "C1", "topic": "Elipse e substituição", "instruction": "Encontre e corrija o erro.", "sentence": "I didn't feel like going to the concert, but my wife wanted.", "wrong": "wanted", "fix": ["wanted to", "did", "wanted to go"], "explain": "'Want' não pode ficar sem complemento; use 'wanted to' (elipse após to) ou 'did'.", "id": "bkC1-83"}, {"type": "rewrite", "level": "C1", "topic": "Elipse e substituição", "instruction": "Reescreva evitando a repetição, com 'so' + auxiliar.", "prompt": "Lucas likes jazz, and I like jazz too.", "start": "Lucas likes jazz, and so", "accept": ["Lucas likes jazz, and so do I"], "explain": "So + auxiliar + sujeito substitui a oração repetida: so do I.", "id": "bkC1-84"}, {"type": "match", "level": "C1", "topic": "Elipse e substituição", "instruction": "Ligue cada fala à resposta curta correta.", "left": ["A: Is the museum open today? B: I believe", "A: I've never been to Japan. B: Neither", "A: Can you help me? B: I'd be happy", "A: Who broke the vase? B: Tom"], "right": ["did.", "to.", "have I.", "so."], "correctMap": [3, 2, 1, 0], "explain": "I believe so; Neither have I; I'd be happy to; Tom did: substituem a oração completa.", "id": "bkC1-85"}, {"type": "sort", "level": "C1", "topic": "Elipse e substituição", "instruction": "Classifique as palavras pelo que elas substituem.", "groups": ["Substitui um substantivo", "Substitui uma oração ou ação"], "items": [{"w": "one", "g": 0}, {"w": "ones", "g": 0}, {"w": "mine", "g": 0}, {"w": "so (in 'I think so')", "g": 1}, {"w": "not (in 'I hope not')", "g": 1}, {"w": "do so", "g": 1}], "explain": "one/ones/mine retomam substantivos; so, not e do so retomam orações ou ações inteiras.", "prompt": "Classifique as palavras pelo que elas substituem.", "id": "bkC1-86"}, {"type": "tf", "level": "C1", "topic": "Elipse e substituição", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Helena wanted to study medicine, and so did her twin brother, Caio. Their parents hoped they would both get into the university in Recife, and they did. Helena chose pediatrics; Caio didn't. He preferred surgery, although he admits he sometimes wishes he hadn't.", "items": [{"s": "Caio also wanted to study medicine.", "a": true}, {"s": "Only Helena got into the university in Recife.", "a": false}, {"s": "Caio chose pediatrics too.", "a": false}, {"s": "Caio sometimes regrets choosing surgery.", "a": true}], "explain": "'so did' = também quis; 'they did' = ambos entraram; 'wishes he hadn't' = às vezes se arrepende.", "id": "bkC1-87"}, {"type": "order", "level": "C1", "topic": "Elipse e substituição", "instruction": "Ordene as palavras para formar a frase.", "words": ["I", "would", "have", "helped", "if", "I", "had", "been", "able", "to"], "alt": ["If I had been able to I would have helped"], "explain": "'been able to' termina em 'to': o verbo 'help' fica subentendido (elipse).", "id": "bkC1-88"}, {"type": "dorder", "level": "C1", "topic": "Elipse e substituição", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Do you think the flight will be delayed?", "B: I'm afraid so. There's a storm over Brasília.", "A: Oh no. Will we miss our connection to Manaus?", "B: I hope not. We have two hours between flights."], "explain": "'I'm afraid so' e 'I hope not' substituem orações completas nas respostas.", "id": "bkC1-89"}, {"type": "mcq", "level": "C1", "topic": "Subjuntivo", "instruction": "Escolha a forma correta do verbo.", "prompt": "The contract stipulates that the tenant ___ the apartment in its original condition.", "options": ["returned", "return", "returning", "to return"], "correctIndex": 1, "explain": "'Stipulate that' pede o subjuntivo: forma base (return) para qualquer sujeito.", "id": "bkC1-90"}, {"type": "mcq", "level": "C1", "topic": "Subjuntivo", "instruction": "Escolha a forma correta.", "prompt": "Her lawyer advised that she ___ to any journalists until the trial.", "options": ["not to speak", "not speaking", "not speak", "didn't speak"], "correctIndex": 2, "explain": "No subjuntivo negativo usamos 'not' + forma base, sem 'do/does/did'.", "id": "bkC1-91"}, {"type": "mcq", "level": "C1", "topic": "Subjuntivo", "instruction": "Escolha a forma correta depois de \"lest\".", "prompt": "Write the password down somewhere safe lest you ___ it.", "options": ["forgetting", "to forget", "forgot", "forget"], "correctIndex": 3, "explain": "'Lest' (para que não) é seguido do subjuntivo: forma base do verbo.", "id": "bkC1-92"}, {"type": "choose", "level": "C1", "topic": "Subjuntivo", "instruction": "Escolha a forma correta.", "prompt": "[Be*/Is] it a small café or a large hotel, every business must follow the new hygiene rules.", "explain": "'Be it X or Y' é uma expressão fixa com subjuntivo, equivalente a 'whether it is'.", "id": "bkC1-93"}, {"type": "choose", "level": "C1", "topic": "Subjuntivo", "instruction": "Escolha as formas corretas.", "prompt": "The union proposed that overtime [be*/is] paid double and that the new rules [take*/took] effect in May.", "explain": "'Propose that' pede subjuntivo: 'be paid' (passiva) e 'take' (forma base).", "id": "bkC1-94"}, {"type": "choose", "level": "C1", "topic": "Subjuntivo", "instruction": "Escolha as formas corretas.", "prompt": "He talks about Paris as if he [were*/be] a local, but it is vital that he [be*/were] honest about his experience.", "explain": "'As if' + irreal usa 'were'; 'it is vital that' pede subjuntivo presente: 'be'.", "id": "bkC1-95"}, {"type": "error", "level": "C1", "topic": "Subjuntivo", "instruction": "Encontre o erro.", "sentence": "The committee's recommendation that every applicant submits two references was approved.", "wrong": "submits", "fix": ["submit", "should submit"], "explain": "Substantivos como 'recommendation that' também pedem subjuntivo: 'submit', sem -s. (No inglês britânico, a forma comum com -s também aparece; aqui seguimos o padrão americano.)", "id": "bkC1-96"}, {"type": "error", "level": "C1", "topic": "Subjuntivo", "instruction": "Encontre o erro.", "sentence": "The judge ordered that the documents not to be destroyed.", "wrong": "not to be", "fix": ["not be", "should not be"], "explain": "Subjuntivo negativo na passiva: 'not be' + particípio, sem 'to'.", "id": "bkC1-97"}, {"type": "error", "level": "C1", "topic": "Subjuntivo", "instruction": "Encontre o erro.", "sentence": "If need is, we can postpone the launch until March.", "wrong": "is", "fix": ["be"], "explain": "A expressão fixa é 'if need be' (se for necessário), com subjuntivo.", "id": "bkC1-98"}, {"type": "gaps", "level": "C1", "topic": "Subjuntivo", "instruction": "Complete com o subjuntivo dos verbos.", "prompt": "The school requires that each student ___ (wear) a uniform and that parents ___ (be) informed of any absence.", "answers": [["wear", "should wear"], ["be", "should be"]], "explain": "'Require that' pede forma base: 'wear' e, na passiva, 'be informed'.", "id": "bkC1-99"}, {"type": "gaps", "level": "C1", "topic": "Subjuntivo", "instruction": "Complete o diálogo com formas de \"be\".", "prompt": "A: What if the client rejects the design?\nB: So ___ (be) it. We'll start again.\nA: And suppose the budget ___ (be) cut in half?\nB: Then we'd need a whole new plan.", "answers": [["be"], ["were", "was"]], "explain": "'So be it' é expressão fixa; 'suppose' + situação hipotética usa 'were'.", "id": "bkC1-100"}, {"type": "match", "level": "C1", "topic": "Subjuntivo", "instruction": "Ligue cada expressão ao seu significado.", "left": ["If need be", "God forbid", "So be it", "Long live the king"], "right": ["I accept it, even if I don't like it.", "May the king live for a long time.", "If it is necessary.", "I really hope that never happens."], "correctMap": [2, 3, 0, 1], "explain": "Todas são expressões fixas que conservam o subjuntivo antigo do inglês.", "id": "bkC1-101"}, {"type": "match", "level": "C1", "topic": "Subjuntivo", "instruction": "Ligue as metades das frases.", "left": ["The landlord insists that the tenants", "We requested that the report", "Suppose he", "It's essential that the windows"], "right": ["remain closed during the storm.", "were to lose his job tomorrow.", "not keep pets in the building.", "be translated into Spanish."], "correctMap": [2, 3, 1, 0], "explain": "'Insist/request/essential that' pedem forma base; 'suppose' + hipótese usa 'were to'.", "id": "bkC1-102"}, {"type": "order", "level": "C1", "topic": "Subjuntivo", "instruction": "Ordene as palavras para formar a frase.", "words": ["The", "coach", "insisted", "that", "nobody", "leave", "before", "the", "end"], "explain": "'Insist that' + subjuntivo: 'nobody leave', sem -s.", "id": "bkC1-103"}, {"type": "order", "level": "C1", "topic": "Subjuntivo", "instruction": "Ordene as palavras para formar a frase.", "words": ["She", "demanded", "that", "the", "error", "be", "corrected", "immediately"], "alt": ["She demanded that the error be immediately corrected", "She demanded that the error immediately be corrected"], "explain": "'Demand that' + subjuntivo passivo: 'be corrected'.", "id": "bkC1-104"}, {"type": "sort", "level": "C1", "topic": "Subjuntivo", "instruction": "Classifique os verbos: pedem subjuntivo ou não?", "prompt": "Which verbs are followed by the subjunctive, as in '... that he be'?", "groups": ["Pede subjuntivo", "Não pede subjuntivo"], "items": [{"w": "demand", "g": 0}, {"w": "propose", "g": 0}, {"w": "urge", "g": 0}, {"w": "request", "g": 0}, {"w": "hope", "g": 1}, {"w": "believe", "g": 1}, {"w": "notice", "g": 1}, {"w": "realize", "g": 1}], "explain": "Verbos de ordem ou pedido pedem subjuntivo; verbos de crença ou percepção usam o indicativo.", "id": "bkC1-105"}, {"type": "tf", "level": "C1", "topic": "Subjuntivo", "instruction": "Leia o aviso e marque verdadeiro ou falso.", "text": "The residents' association of the Mar Azul building in Florianópolis has approved three new rules. First, it is required that all visitors be registered at the front desk. Second, the board has recommended that residents not leave bicycles in the hallways, although this is not mandatory. Finally, the association insists that the pool be closed on Mondays for cleaning. Any resident may request that a rule be discussed again at the next meeting.", "items": [{"s": "Visitors must be registered at the front desk.", "a": true}, {"s": "Leaving bicycles in the hallways is now forbidden.", "a": false}, {"s": "The pool is open every day of the week.", "a": false}, {"s": "Residents can ask for a rule to be discussed again.", "a": true}], "explain": "'Recommended' indica sugestão, não obrigação; 'insists that the pool be closed on Mondays'.", "id": "bkC1-106"}, {"type": "reading", "level": "C1", "topic": "Subjuntivo", "instruction": "Leia o e-mail e responda.", "text": "Dear students,\nFollowing several complaints about noise in the library, the dean has asked that the following measures be adopted immediately. It is essential that phones be kept on silent in all study areas. Group discussions are allowed only in rooms 3 and 4, and the dean requests that these rooms be booked in advance at the front desk. Should anyone ignore these rules, it is recommended that staff ask them to leave.\nLibrary Management", "questions": [{"q": "Where can students have group discussions?", "options": ["Anywhere, if they speak quietly", "Only in rooms 3 and 4", "Only outside the library"], "correctIndex": 1}, {"q": "What must students do before using rooms 3 and 4?", "options": ["Ask the dean for permission", "Switch off their laptops", "Book them at the front desk"], "correctIndex": 2}, {"q": "What may happen to students who break the rules?", "options": ["Staff may ask them to leave.", "They will pay a fine.", "They will lose their library card."], "correctIndex": 0}], "explain": "O texto usa subjuntivo: 'requests that these rooms be booked', 'recommended that staff ask them to leave'.", "id": "bkC1-107"}, {"type": "dorder", "level": "C1", "topic": "Subjuntivo", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: The client wants the logo changed again.", "B: Again? Did they say what they want this time?", "A: Only that the colors be brighter and that the font not look so formal.", "B: Fine, so be it. When do they need it?", "A: They're asking that it be ready by Monday."], "explain": "A dá a notícia, B pergunta o que querem, A explica, B aceita e pergunta o prazo.", "id": "bkC1-108"}, {"type": "rewrite", "level": "C1", "topic": "Subjuntivo", "instruction": "Reescreva usando o subjuntivo depois de \"that\".", "prompt": "It is necessary for every employee to complete the training.", "start": "It is necessary that every employee", "accept": ["It is necessary that every employee complete the training.", "It is necessary that every employee should complete the training."], "explain": "Depois de 'it is necessary that' usamos a forma base: 'complete', sem -s.", "id": "bkC1-109"}, {"type": "mcq", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Escolha a forma correta.", "prompt": "What the manager did next was ___ everyone into her office.", "options": ["call", "called", "calling", "calls"], "correctIndex": 0, "explain": "Em 'What + sujeito + did + was', usamos o verbo na forma base: 'was call'.", "id": "bkC1-110"}, {"type": "mcq", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Escolha a palavra correta.", "prompt": "It was not until the lights came back on ___ we realized the painting was gone.", "options": ["when", "than", "that", "which"], "correctIndex": 2, "explain": "A estrutura fixa é 'It was not until... that...'.", "id": "bkC1-111"}, {"type": "mcq", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Escolha a forma correta.", "prompt": "All I did ___ ask her a simple question, and she got angry.", "options": ["is", "was", "did", "were"], "correctIndex": 1, "explain": "'All I did was + verbo' enfatiza a única ação; o tempo passado pede 'was'.", "id": "bkC1-112"}, {"type": "choose", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Escolha as formas corretas.", "prompt": "It is the nurses who [deserve*/deserves] our thanks, and it was their patience [that*/what] saved the day.", "explain": "O verbo concorda com 'the nurses' (plural); na cleft com 'it' usamos 'that', não 'what'.", "id": "bkC1-113"}, {"type": "choose", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Escolha as opções corretas.", "prompt": "The reason she resigned was [that*/because of] she felt undervalued, and [where*/what] she went next was Lisbon.", "explain": "'The reason... was that' + oração; 'where she went' indica lugar.", "id": "bkC1-114"}, {"type": "choose", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Escolha as formas corretas.", "prompt": "What the students need [is*/are] more practice, and what worries me [is*/are] their lack of motivation.", "explain": "Com complemento singular ou incontável, a cleft com 'what' usa 'is'.", "id": "bkC1-115"}, {"type": "error", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Encontre o erro.", "sentence": "It were the children who noticed the smoke first.", "wrong": "were", "fix": ["was"], "explain": "Na cleft, 'it' é sempre singular: 'It was the children who...'.", "id": "bkC1-116"}, {"type": "error", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Encontre o erro.", "sentence": "The thing what bothers me is the noise from the street.", "wrong": "what", "fix": ["that", "which"], "explain": "Depois de 'the thing' usamos 'that' ou 'which', nunca 'what'.", "id": "bkC1-117"}, {"type": "error", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Encontre o erro.", "sentence": "All what we wanted was a quiet weekend in the mountains.", "wrong": "All what", "fix": ["All", "All that"], "explain": "O correto é 'All (that) we wanted', sem 'what'.", "id": "bkC1-118"}, {"type": "gaps", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Complete com What, It ou that.", "prompt": "___ I admire about Fernanda is her honesty. ___ was her honesty ___ convinced the jury.", "answers": [["What"], ["It"], ["that", "which"]], "explain": "'What I admire... is' é pseudo-cleft; 'It was X that...' destaca o elemento.", "id": "bkC1-119"}, {"type": "gaps", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Complete o texto com as palavras do quadro.", "prompt": "Many people think ___ was the price that made the project fail, but that isn't true. ___ really went wrong was the planning. The ___ we missed the deadline was that nobody coordinated the teams. ___ we needed was a single leader. In the end, it was Lucas ___ took on that role.", "answers": [["it"], ["what"], ["reason"], ["all", "what"], ["who", "that"]], "bank": ["it", "what", "reason", "all", "who", "where"], "explain": "Estruturas: 'it was X that', 'what went wrong was', 'the reason... was that', 'all we needed was'.", "id": "bkC1-120"}, {"type": "match", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Ligue cada frase à sua versão com cleft.", "left": ["I love the smell of coffee.", "Paula called the police.", "We met in Rome.", "I need some sleep."], "right": ["It was Paula who called the police.", "What I need is some sleep.", "It was in Rome that we met.", "What I love is the smell of coffee."], "correctMap": [3, 0, 2, 1], "explain": "Cleft com 'it' destaca pessoa ou lugar; com 'what' destaca o objeto.", "id": "bkC1-121"}, {"type": "match", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Ligue as metades das frases.", "left": ["The place where we stayed", "The person who helped me most", "The moment I knew it was over", "The last thing you want"], "right": ["was when he forgot my birthday.", "is to lose your passport abroad.", "was a tiny hostel in Ouro Preto.", "was my grandmother."], "correctMap": [2, 3, 0, 1], "explain": "Pseudo-clefts com 'the place where', 'the person who', 'the moment', 'the last thing'.", "id": "bkC1-122"}, {"type": "order", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Ordene as palavras para formar a frase.", "words": ["What", "she", "did", "was", "resign", "on", "the", "spot"], "explain": "'What + sujeito + did + was + verbo base' enfatiza a ação.", "id": "bkC1-123"}, {"type": "order", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Ordene as palavras para formar a frase.", "words": ["It", "was", "only", "then", "that", "I", "understood", "the", "risk"], "explain": "'It was only then that...' destaca o momento em que algo aconteceu.", "id": "bkC1-124"}, {"type": "sort", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Classifique as frases.", "prompt": "Sort the sentences by type.", "groups": ["It-cleft", "Wh-cleft", "Não é cleft"], "items": [{"w": "It was Marta who called.", "g": 0}, {"w": "It's the noise that bothers me.", "g": 0}, {"w": "It was in June that they got married.", "g": 0}, {"w": "What I need is coffee.", "g": 1}, {"w": "What she did was leave.", "g": 1}, {"w": "It is cold today.", "g": 2}, {"w": "What time is it?", "g": 2}, {"w": "It's a long story.", "g": 2}], "explain": "Clefts dividem uma ideia em duas partes para dar ênfase; 'it' ou 'what' sozinhos não bastam.", "id": "bkC1-125"}, {"type": "tf", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "It was in 1998 that Renata opened her first bakery in Porto Alegre. What made it famous was not the bread but the coffee, which came from her uncle's farm. The reason she moved to São Paulo in 2010 was that her husband got a job there. What she misses most is the southern weather. It is her daughter who runs the original bakery today.", "items": [{"s": "The bakery became famous for its bread.", "a": false}, {"s": "Renata moved because of her husband's job.", "a": true}, {"s": "Renata runs the bakery in Porto Alegre today.", "a": false}, {"s": "Renata's uncle supplied the coffee.", "a": true}], "explain": "'Not the bread but the coffee'; 'It is her daughter who runs' a padaria original.", "id": "bkC1-126"}, {"type": "reading", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Leia a avaliação e responda.", "text": "What surprised me most about Casa Verde wasn't the food, which was good, but the service. It was our waiter, a young man called Davi, who recommended the grilled fish, and he was absolutely right. The only thing I'd change is the music, which was far too loud for a Tuesday night. What I'll definitely do is come back with my parents.", "questions": [{"q": "What surprised the writer most?", "options": ["The quality of the food", "The low prices", "The service"], "correctIndex": 2}, {"q": "Who suggested the fish?", "options": ["The waiter", "The writer's parents", "The chef"], "correctIndex": 0}, {"q": "What would the writer change?", "options": ["The menu", "The volume of the music", "The opening days"], "correctIndex": 1}], "explain": "As clefts destacam: 'what surprised me most... was the service', 'it was our waiter who...'.", "id": "bkC1-127"}, {"type": "dorder", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Why did you cancel the trip to Chile?", "B: It wasn't the cost that stopped me, if that's what you think.", "A: So what was it?", "B: What really worried me was the volcano near our hotel.", "A: The one that's been active since March?", "B: Exactly. That's the reason I changed my plans."], "explain": "A pergunta, B nega uma causa, A insiste, B revela a causa real e confirma.", "id": "bkC1-128"}, {"type": "rewrite", "level": "C1", "topic": "Cleft sentences (It is... that / What...)", "instruction": "Reescreva começando com \"What\".", "prompt": "Her smile is what I remember most.", "start": "What I remember most", "accept": ["What I remember most is her smile."], "explain": "Pseudo-cleft invertida: o elemento destacado vai para o final, depois de 'is'.", "id": "bkC1-129"}, {"type": "mcq", "level": "C1", "topic": "Inversão avançada", "instruction": "Escolha a opção correta.", "prompt": "At no time ___ the passengers in any real danger.", "options": ["were", "they were", "did", "had"], "correctIndex": 0, "explain": "'At no time' no início exige inversão: verbo 'were' antes do sujeito.", "id": "bkC1-130"}, {"type": "mcq", "level": "C1", "topic": "Inversão avançada", "instruction": "Escolha a opção correta.", "prompt": "Were the bank ___ interest rates again, many families would struggle.", "options": ["raise", "raising", "raised", "to raise"], "correctIndex": 3, "explain": "Condicional formal com inversão: 'Were + sujeito + to + verbo' = 'If the bank raised'.", "id": "bkC1-131"}, {"type": "mcq", "level": "C1", "topic": "Inversão avançada", "instruction": "Escolha a opção correta.", "prompt": "Only by working together ___ this crisis.", "options": ["we can overcome", "can we overcome", "we overcome", "overcome we can"], "correctIndex": 1, "explain": "'Only by...' no início exige inversão: auxiliar 'can' antes do sujeito.", "id": "bkC1-132"}, {"type": "choose", "level": "C1", "topic": "Inversão avançada", "instruction": "Escolha as formas corretas.", "prompt": "Not once [did she complain*/she complained] during the trip, and never before [had I met*/I had met] anyone so patient.", "explain": "'Not once' e 'never before' no início exigem inversão com auxiliar.", "id": "bkC1-133"}, {"type": "choose", "level": "C1", "topic": "Inversão avançada", "instruction": "Escolha as formas corretas.", "prompt": "Scarcely had the plane landed [when*/than] the passengers stood up. Only later [did we learn*/we learned] that the pilot was ill.", "explain": "'Scarcely... when' é fixo; 'Only later' no início exige inversão com 'did'.", "id": "bkC1-134"}, {"type": "choose", "level": "C1", "topic": "Inversão avançada", "instruction": "Escolha as formas corretas.", "prompt": "So loud [was the music*/the music was] that we couldn't hear ourselves think, nor [could we*/we could] get any sleep.", "explain": "'So + adjetivo' no início e 'nor' exigem inversão do verbo e do sujeito.", "id": "bkC1-135"}, {"type": "error", "level": "C1", "topic": "Inversão avançada", "instruction": "Encontre o erro.", "sentence": "Only if you finish the report today you can leave early.", "wrong": "you can", "fix": ["can you"], "explain": "'Only if...' no início inverte a oração principal: 'can you leave'.", "id": "bkC1-136"}, {"type": "error", "level": "C1", "topic": "Inversão avançada", "instruction": "Encontre o erro.", "sentence": "Had it not being for the firefighters, the whole building would have burned down.", "wrong": "being", "fix": ["been"], "explain": "A estrutura é 'Had it not been for' = 'If it hadn't been for'.", "id": "bkC1-137"}, {"type": "error", "level": "C1", "topic": "Inversão avançada", "instruction": "Encontre o erro.", "sentence": "Not since the 1990s the city has seen such heavy rain.", "wrong": "the city has", "fix": ["has the city"], "explain": "'Not since...' no início exige inversão: 'has the city seen'.", "id": "bkC1-138"}, {"type": "gaps", "level": "C1", "topic": "Inversão avançada", "instruction": "Complete com o auxiliar correto.", "prompt": "Little ___ we suspect that the guide had never climbed the mountain before. Not only ___ he get lost, but he ___ also forgotten the map. Nowhere ___ the trail clearly marked.", "answers": [["did"], ["did"], ["had"], ["was"]], "explain": "Depois de 'little', 'not only' e 'nowhere', o auxiliar vem antes do sujeito.", "id": "bkC1-139"}, {"type": "gaps", "level": "C1", "topic": "Inversão avançada", "instruction": "Complete o diálogo.", "prompt": "A: Should I tell Marcos about the surprise party?\nB: Under no circumstances ___ you tell him!\nA: OK. But what if he asks where we're going?\nB: ___ he ask, just say we're going to the gym.", "answers": [["should", "must", "can"], ["should"]], "explain": "'Under no circumstances' exige inversão; 'Should he ask' = 'If he asks'.", "id": "bkC1-140"}, {"type": "match", "level": "C1", "topic": "Inversão avançada", "instruction": "Ligue as metades das frases.", "left": ["No sooner had she hung up", "Only by saving every month", "In no way", "Such was the demand"], "right": ["can we afford the trip.", "that the tickets sold out in an hour.", "does this affect your contract.", "than the phone rang again."], "correctMap": [3, 0, 2, 1], "explain": "'No sooner... than', 'only by' + inversão, 'in no way' + inversão, 'such was... that'.", "id": "bkC1-141"}, {"type": "match", "level": "C1", "topic": "Inversão avançada", "instruction": "Ligue cada frase formal à sua versão com \"if\".", "left": ["Should the flight be canceled,", "Were I in your shoes,", "Had the alarm gone off,", "Were it not for the rain,"], "right": ["If I were you,", "If it weren't for the rain,", "If the flight is canceled,", "If the alarm had gone off,"], "correctMap": [2, 0, 3, 1], "explain": "Should = 1ª condicional; Were = 2ª; Had = 3ª condicional, todas sem 'if'.", "id": "bkC1-142"}, {"type": "order", "level": "C1", "topic": "Inversão avançada", "instruction": "Ordene as palavras para formar a frase.", "words": ["Nowhere", "else", "will", "you", "find", "such", "fresh", "seafood"], "explain": "'Nowhere else' no início exige inversão: 'will you find'.", "id": "bkC1-143"}, {"type": "order", "level": "C1", "topic": "Inversão avançada", "instruction": "Ordene as palavras para formar a frase.", "words": ["Not", "a", "single", "word", "did", "he", "say", "all", "evening"], "alt": ["All evening not a single word did he say"], "explain": "Objeto negativo enfático no início ('Not a single word') exige inversão com 'did'.", "id": "bkC1-144"}, {"type": "sort", "level": "C1", "topic": "Inversão avançada", "instruction": "Classifique as expressões.", "prompt": "Does the expression need inversion when it starts a sentence?", "groups": ["Exige inversão", "Não exige inversão"], "items": [{"w": "Seldom", "g": 0}, {"w": "Not until", "g": 0}, {"w": "Under no circumstances", "g": 0}, {"w": "Only after", "g": 0}, {"w": "Sometimes", "g": 1}, {"w": "In fact", "g": 1}, {"w": "After a while", "g": 1}, {"w": "Usually", "g": 1}], "explain": "Expressões negativas ou restritivas exigem inversão; advérbios comuns, não.", "id": "bkC1-145"}, {"type": "tf", "level": "C1", "topic": "Inversão avançada", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Never before had the small town of Tiradentes hosted such a large festival. Not only did the hotels sell out, but many residents also rented rooms to visitors. Only on the final day did it rain, and even then the concerts continued. Such was the success of the event that the organizers have already confirmed next year's edition.", "items": [{"s": "The town had hosted bigger festivals before.", "a": false}, {"s": "Some residents rented rooms to visitors.", "a": true}, {"s": "It rained on the first day of the festival.", "a": false}, {"s": "There will be another festival next year.", "a": true}], "explain": "'Never before had...' = nunca antes; 'Only on the final day did it rain' = só no último dia.", "id": "bkC1-146"}, {"type": "dorder", "level": "C1", "topic": "Inversão avançada", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Did you hear about the merger?", "B: Yes, only this morning. At no time had the directors mentioned it before.", "A: Nor did they tell us about the new office.", "B: What new office? Little did I know we were moving!", "A: Apparently we are, but not until next year."], "explain": "A pergunta, B confirma e reclama, A acrescenta outra informação, B se surpreende, A explica.", "id": "bkC1-147"}, {"type": "rewrite", "level": "C1", "topic": "Inversão avançada", "instruction": "Reescreva começando com a expressão dada.", "prompt": "You will not be refunded under any circumstances.", "start": "Under no circumstances", "accept": ["Under no circumstances will you be refunded.", "Under no circumstances will you receive a refund.", "Under no circumstances will you get a refund."], "explain": "'Under no circumstances' no início exige inversão: 'will you be refunded'.", "id": "bkC1-148"}, {"type": "odd", "level": "C1", "topic": "Inversão avançada", "instruction": "Qual frase NÃO tem inversão?", "prompt": "Which sentence does NOT use inversion?", "options": ["Seldom do we eat out these days.", "Hardly anyone came to the party.", "Little did he know the truth.", "Rarely does it snow in this region."], "correctIndex": 1, "explain": "'Hardly anyone' é sujeito da frase, então não há inversão.", "id": "bkC1-149"}, {"type": "mcq", "level": "C1", "topic": "Nominalização", "instruction": "Escolha a preposição correta.", "prompt": "There has been a significant increase ___ the number of cyclists in Recife.", "options": ["of", "in", "on", "at"], "correctIndex": 1, "explain": "Usamos 'an increase in' para indicar aquilo que aumentou.", "id": "bkC1-150"}, {"type": "mcq", "level": "C1", "topic": "Nominalização", "instruction": "Escolha o substantivo correto.", "prompt": "The ___ of our flight was delayed by three hours because of fog.", "options": ["departing", "depart", "departure", "departed"], "correctIndex": 2, "explain": "O substantivo de 'depart' é 'departure' (sufixo -ure).", "id": "bkC1-151"}, {"type": "mcq", "level": "C1", "topic": "Nominalização", "instruction": "Escolha o substantivo correto.", "prompt": "The judge's ___ to grant bail surprised everyone in the courtroom.", "options": ["refusement", "refusal", "refusage", "refused"], "correctIndex": 1, "explain": "O substantivo de 'refuse' é 'refusal' (sufixo -al).", "id": "bkC1-152"}, {"type": "choose", "level": "C1", "topic": "Nominalização", "instruction": "Escolha os substantivos corretos.", "prompt": "The [accurate/accuracy*] of the data is crucial, and the [relevant/relevance*] of the findings is clear.", "explain": "Depois de 'the' e antes de 'of' precisamos de substantivos: accuracy, relevance.", "id": "bkC1-153"}, {"type": "choose", "level": "C1", "topic": "Nominalização", "instruction": "Escolha os substantivos corretos.", "prompt": "We were shocked by the [deep/depth*] of the lake and the [strong/strength*] of the current.", "explain": "Substantivos irregulares: deep → depth, strong → strength.", "id": "bkC1-154"}, {"type": "choose", "level": "C1", "topic": "Nominalização", "instruction": "Escolha os substantivos corretos.", "prompt": "His [deny/denial*] of the accusations did not prevent the [withdraw/withdrawal*] of his candidacy.", "explain": "Deny → denial e withdraw → withdrawal (sufixo -al).", "id": "bkC1-155"}, {"type": "error", "level": "C1", "topic": "Nominalização", "instruction": "Encontre o erro.", "sentence": "The arrive of the new trains has made commuting much easier.", "wrong": "arrive", "fix": ["arrival"], "explain": "Depois de 'the' precisamos do substantivo: 'arrival'.", "id": "bkC1-156"}, {"type": "error", "level": "C1", "topic": "Nominalização", "instruction": "Encontre o erro.", "sentence": "Her explain of the process was clear and concise.", "wrong": "explain", "fix": ["explanation"], "explain": "O substantivo de 'explain' é 'explanation'.", "id": "bkC1-157"}, {"type": "error", "level": "C1", "topic": "Nominalização", "instruction": "Encontre o erro.", "sentence": "There is a growing demand of qualified nurses in rural areas.", "wrong": "of", "fix": ["for"], "explain": "O substantivo 'demand' é seguido de 'for': 'demand for nurses'.", "id": "bkC1-158"}, {"type": "gaps", "level": "C1", "topic": "Nominalização", "instruction": "Complete o texto com as palavras do quadro.", "prompt": "The ___ of the tourism sector in Bonito has been remarkable. However, the ___ of water in the dry season is a real concern. The city council's ___ of three new hotels has divided residents, and some fear the ___ on the local rivers.", "answers": [["growth"], ["shortage"], ["approval"], ["impact"]], "bank": ["growth", "shortage", "approval", "impact", "request", "access"], "explain": "Growth (crescimento), shortage (falta), approval (aprovação), impact on (impacto sobre).", "id": "bkC1-159"}, {"type": "gaps", "level": "C1", "topic": "Nominalização", "instruction": "Complete com os substantivos dos adjetivos.", "prompt": "Despite his ___ (anxious) about the interview, Tiago spoke with great ___ (confident) and showed real ___ (enthusiastic) for the role.", "answers": [["anxiety"], ["confidence"], ["enthusiasm"]], "explain": "anxious → anxiety, confident → confidence, enthusiastic → enthusiasm.", "id": "bkC1-160"}, {"type": "match", "level": "C1", "topic": "Nominalização", "instruction": "Ligue cada verbo ao seu substantivo.", "left": ["succeed", "believe", "lose", "prove", "choose"], "right": ["loss", "choice", "success", "proof", "belief"], "correctMap": [2, 4, 0, 3, 1], "explain": "São substantivos irregulares, sem sufixo comum.", "id": "bkC1-161"}, {"type": "match", "level": "C1", "topic": "Nominalização", "instruction": "Ligue cada oração à versão nominalizada.", "left": ["Because the train was delayed,", "Since the manager is absent,", "After they had investigated carefully,", "Unless someone approves it,"], "right": ["Without approval,", "Due to the train's delay,", "In the manager's absence,", "After a careful investigation,"], "correctMap": [1, 2, 3, 0], "explain": "A nominalização troca verbos e adjetivos por substantivos: delay, absence, investigation, approval.", "id": "bkC1-162"}, {"type": "order", "level": "C1", "topic": "Nominalização", "instruction": "Ordene as palavras para formar a frase.", "words": ["The", "rapid", "growth", "of", "the", "city", "caused", "serious", "problems"], "explain": "'Rapid growth' é a forma nominal de 'the city grew rapidly'.", "id": "bkC1-163"}, {"type": "order", "level": "C1", "topic": "Nominalização", "instruction": "Ordene as palavras para formar a frase.", "words": ["Her", "sudden", "departure", "took", "everyone", "by", "surprise"], "explain": "'Her sudden departure' nominaliza 'she departed suddenly'.", "id": "bkC1-164"}, {"type": "sort", "level": "C1", "topic": "Nominalização", "instruction": "Classifique os adjetivos pelo sufixo do substantivo.", "prompt": "Which suffix forms the noun from each adjective?", "groups": ["-ness", "-ity", "-ance / -ence"], "items": [{"w": "aware", "g": 0}, {"w": "dark", "g": 0}, {"w": "weak", "g": 0}, {"w": "possible", "g": 1}, {"w": "secure", "g": 1}, {"w": "curious", "g": 1}, {"w": "important", "g": 2}, {"w": "patient", "g": 2}], "explain": "awareness, darkness, weakness; possibility, security, curiosity; importance, patience.", "id": "bkC1-165"}, {"type": "tf", "level": "C1", "topic": "Nominalização", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "The introduction of bike lanes in Fortaleza led to a noticeable reduction in traffic accidents. However, the expansion of the network has been slow because of a lack of funding. A recent survey showed strong approval of the project among young residents, while older drivers expressed concern about the loss of parking spaces.", "items": [{"s": "Accidents decreased after bike lanes were introduced.", "a": true}, {"s": "The bike lane network has grown quickly.", "a": false}, {"s": "Young residents generally support the project.", "a": true}, {"s": "Older drivers complained mainly about the lack of funding.", "a": false}], "explain": "'Reduction in accidents' = menos acidentes; 'expansion has been slow'; motoristas temem 'loss of parking spaces'.", "id": "bkC1-166"}, {"type": "rewrite", "level": "C1", "topic": "Nominalização", "instruction": "Reescreva usando nominalização e \"worried\" como verbo.", "prompt": "Prices increased sharply, and consumers were worried.", "start": "The sharp increase", "accept": ["The sharp increase in prices worried consumers.", "The sharp increase in prices worried the consumers."], "explain": "'Increased sharply' vira 'the sharp increase in prices', que passa a ser o sujeito.", "id": "bkC1-167"}, {"type": "rewrite", "level": "C1", "topic": "Nominalização", "instruction": "Reescreva usando a nominalização.", "prompt": "The minister resigned unexpectedly. This shocked the country.", "start": "The minister's unexpected", "accept": ["The minister's unexpected resignation shocked the country.", "The minister's unexpected resignation came as a shock to the country."], "explain": "'Resigned unexpectedly' vira 'unexpected resignation', sujeito do verbo 'shocked'.", "id": "bkC1-168"}, {"type": "odd", "level": "C1", "topic": "Nominalização", "instruction": "Qual palavra NÃO é nominalização de um verbo?", "prompt": "Which word is NOT a noun formed from a verb?", "options": ["arrival", "survival", "festival", "refusal"], "correctIndex": 2, "explain": "Arrival, survival e refusal vêm de verbos; 'festival' não vem de um verbo.", "id": "bkC1-169"}, {"type": "mcq", "level": "C1", "topic": "Discourse markers formais", "instruction": "Escolha o marcador mais adequado.", "prompt": "Sales in the north fell by 10%. ___, sales in the south rose by the same amount.", "options": ["Likewise", "Hence", "Conversely", "Namely"], "correctIndex": 2, "explain": "'Conversely' introduz a situação oposta à anterior.", "id": "bkC1-170"}, {"type": "mcq", "level": "C1", "topic": "Discourse markers formais", "instruction": "Escolha o marcador mais adequado.", "prompt": "The project was completed on time, ___ at a much higher cost than expected.", "options": ["albeit", "despite", "whereas", "moreover"], "correctIndex": 0, "explain": "'Albeit' (embora) introduz uma concessão curta, sem verbo.", "id": "bkC1-171"}, {"type": "mcq", "level": "C1", "topic": "Discourse markers formais", "instruction": "Escolha o marcador mais adequado.", "prompt": "Two issues remain unresolved, ___ funding and staffing.", "options": ["thus", "likewise", "whereby", "namely"], "correctIndex": 3, "explain": "'Namely' (a saber) especifica os itens mencionados.", "id": "bkC1-172"}, {"type": "choose", "level": "C1", "topic": "Discourse markers formais", "instruction": "Escolha os marcadores corretos.", "prompt": "The software is expensive. [That said*/Thus], it is the most reliable option on the market. [Accordingly*/Conversely], we recommend purchasing it.", "explain": "'That said' introduz ressalva; 'Accordingly' introduz a consequência lógica.", "id": "bkC1-173"}, {"type": "choose", "level": "C1", "topic": "Discourse markers formais", "instruction": "Escolha os marcadores corretos.", "prompt": "[Owing to*/Despite] a technical fault, the flight was canceled. The new policy has not reduced costs. [On the contrary*/On the other hand], expenses have risen by 15%.", "explain": "'Owing to' = por causa de; 'On the contrary' contradiz a ideia negativa anterior.", "id": "bkC1-174"}, {"type": "choose", "level": "C1", "topic": "Discourse markers formais", "instruction": "Escolha os marcadores corretos.", "prompt": "The report was concise; [likewise*/conversely], the presentation was brief and clear. [Notwithstanding*/Although] these strengths, the proposal was rejected.", "explain": "'Likewise' indica semelhança; 'Notwithstanding' + substantivo = apesar de.", "id": "bkC1-175"}, {"type": "error", "level": "C1", "topic": "Discourse markers formais", "instruction": "Encontre o erro.", "sentence": "The plan is risky. Although, we believe it is worth trying.", "wrong": "Although", "fix": ["However", "Nevertheless", "Nonetheless", "That said", "Even so", "Still"], "explain": "'Although' precisa de oração; no início com vírgula usamos 'However'.", "id": "bkC1-176"}, {"type": "error", "level": "C1", "topic": "Discourse markers formais", "instruction": "Encontre o erro.", "sentence": "In addition to reduce costs, the new system saves time.", "wrong": "reduce", "fix": ["reducing"], "explain": "'In addition to' tem 'to' como preposição: segue verbo com -ing.", "id": "bkC1-177"}, {"type": "error", "level": "C1", "topic": "Discourse markers formais", "instruction": "Encontre o erro.", "sentence": "Given to the circumstances, we have decided to postpone the launch.", "wrong": "Given to", "fix": ["Given", "In view of", "Owing to", "Due to", "In light of"], "explain": "'Given' (considerando) é seguido diretamente do substantivo, sem 'to'.", "id": "bkC1-178"}, {"type": "gaps", "level": "C1", "topic": "Discourse markers formais", "instruction": "Complete o texto com os marcadores do quadro.", "prompt": "The city faces a serious housing shortage. Rents have doubled in five years; ___, many young people are moving elsewhere. ___, the council has launched a new building program. ___ its limited budget, the program aims to deliver 2,000 homes by 2030. ___, the plan is a step in the right direction, albeit a small one.", "answers": [["hence", "thus", "consequently", "accordingly", "as a result", "therefore"], ["to this end", "hence", "accordingly", "consequently", "therefore", "as a result"], ["notwithstanding", "despite", "in spite of"], ["in conclusion", "overall", "all in all", "in summary"]], "bank": ["hence", "to this end", "notwithstanding", "in conclusion", "conversely"], "explain": "Hence (consequência), to this end (com esse objetivo), notwithstanding (apesar de), in conclusion (conclusão).", "id": "bkC1-179"}, {"type": "match", "level": "C1", "topic": "Discourse markers formais", "instruction": "Ligue cada marcador à sua função.", "left": ["Conversely", "Namely", "Admittedly", "Accordingly", "By the same token"], "right": ["concedes a point", "introduces a specific detail", "shows an opposite situation", "for the same reason; similarly", "as a result; therefore"], "correctMap": [2, 1, 0, 4, 3], "explain": "Cada marcador tem uma função: oposição, especificação, concessão, consequência e semelhança.", "id": "bkC1-180"}, {"type": "match", "level": "C1", "topic": "Discourse markers formais", "instruction": "Ligue as metades das frases.", "left": ["Given that the deadline is tomorrow,", "The results were inconclusive;", "Regardless of the weather,", "The plan has some flaws. Having said that,"], "right": ["the outdoor concert will take place as planned.", "we must finish the draft tonight.", "it is still the best option we have.", "hence, further tests are needed."], "correctMap": [1, 3, 0, 2], "explain": "'Given that' = considerando; 'hence' = portanto; 'regardless of' = independentemente; 'having said that' = mesmo assim.", "id": "bkC1-181"}, {"type": "order", "level": "C1", "topic": "Discourse markers formais", "instruction": "Ordene as palavras para formar a frase.", "words": ["The", "findings", "are", "thus", "consistent", "with", "previous", "studies"], "alt": ["Thus the findings are consistent with previous studies", "The findings thus are consistent with previous studies"], "explain": "'Thus' (assim, portanto) pode vir depois do verbo 'to be' ou no início.", "id": "bkC1-182"}, {"type": "order", "level": "C1", "topic": "Discourse markers formais", "instruction": "Ordene as palavras para formar a frase.", "words": ["In", "view", "of", "the", "delay", "we", "will", "extend", "the", "deadline"], "alt": ["We will extend the deadline in view of the delay"], "explain": "'In view of' (tendo em vista) é seguido de substantivo.", "id": "bkC1-183"}, {"type": "sort", "level": "C1", "topic": "Discourse markers formais", "instruction": "Classifique os marcadores pela função.", "prompt": "Sort the markers by function.", "groups": ["Adição", "Contraste", "Consequência"], "items": [{"w": "furthermore", "g": 0}, {"w": "in addition", "g": 0}, {"w": "besides", "g": 0}, {"w": "nonetheless", "g": 1}, {"w": "conversely", "g": 1}, {"w": "even so", "g": 1}, {"w": "hence", "g": 2}, {"w": "accordingly", "g": 2}], "explain": "Adição acrescenta ideias; contraste opõe; consequência mostra resultado.", "id": "bkC1-184"}, {"type": "tf", "level": "C1", "topic": "Discourse markers formais", "instruction": "Leia o e-mail e marque verdadeiro ou falso.", "text": "Dear Mr. Okafor,\nWith regard to your complaint of May 3, we have reviewed your case carefully. Admittedly, the delivery was late; however, the product was not damaged, as your own photos show. Accordingly, we are unable to offer a full refund. That said, we would be happy to give you a 15% discount on your next order.", "items": [{"s": "The company admits that the delivery was late.", "a": true}, {"s": "The photos show that the product was damaged.", "a": false}, {"s": "Mr. Okafor will receive a full refund.", "a": false}, {"s": "The company is offering a discount.", "a": true}], "explain": "'Admittedly' concede o atraso; 'Accordingly' nega o reembolso; 'That said' oferece o desconto.", "id": "bkC1-185"}, {"type": "reading", "level": "C1", "topic": "Discourse markers formais", "instruction": "Leia o aviso e responda.", "text": "Notice to residents\nOwing to essential maintenance, the water supply will be interrupted on Tuesday from 9 a.m. to 3 p.m. Residents are therefore advised to store water in advance. Furthermore, the elevators will be out of service during the same period. Notwithstanding these inconveniences, the work is expected to improve water pressure considerably. For further information, please contact the management office.", "questions": [{"q": "Why will the water supply be interrupted?", "options": ["Because of a storm", "Because of maintenance work", "Because of unpaid bills"], "correctIndex": 1}, {"q": "What else will not work on Tuesday?", "options": ["The lights", "The front gate", "The elevators"], "correctIndex": 2}, {"q": "What is the expected benefit of the work?", "options": ["Better water pressure", "Lower water bills", "New elevators"], "correctIndex": 0}], "explain": "'Owing to' dá a causa; 'Furthermore' acrescenta; 'Notwithstanding' introduz o benefício apesar dos transtornos.", "id": "bkC1-186"}, {"type": "rewrite", "level": "C1", "topic": "Discourse markers formais", "instruction": "Reescreva começando com a expressão dada.", "prompt": "The museum is small, but it attracts thousands of visitors.", "start": "Notwithstanding its", "accept": ["Notwithstanding its small size, the museum attracts thousands of visitors.", "Notwithstanding its small size, it attracts thousands of visitors."], "explain": "'Notwithstanding' é seguido de substantivo: 'its small size'.", "id": "bkC1-187"}, {"type": "rewrite", "level": "C1", "topic": "Discourse markers formais", "instruction": "Reescreva começando com a expressão dada.", "prompt": "The roads were icy, so the school was closed.", "start": "Owing to", "accept": ["Owing to the icy roads, the school was closed.", "Owing to icy roads, the school was closed.", "Owing to the roads being icy, the school was closed."], "explain": "'Owing to' (devido a) é seguido de substantivo: 'the icy roads'.", "id": "bkC1-188"}, {"type": "dorder", "level": "C1", "topic": "Discourse markers formais", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Good morning. Today I'll outline our strategy for next year.", "B: Before you begin, could you clarify the budget?", "A: Certainly. In short, it will remain the same as this year.", "B: I see. Nevertheless, you plan to hire more staff?", "A: Yes. To this end, we will reduce travel expenses."], "explain": "A abre, B pede esclarecimento, A responde, B questiona a contratação e A explica como.", "id": "bkC1-189"}, {"type": "mcq", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Escolha a opção correta.", "prompt": "The package ___ by now; it was sent by express mail three days ago.", "options": ["should have arrived", "can have arrived", "must arrive", "might arrive"], "correctIndex": 0, "explain": "'Should have + particípio' expressa expectativa lógica sobre algo que já deveria ter acontecido.", "id": "bkC1-190"}, {"type": "mcq", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Escolha a opção correta.", "prompt": "You drove straight through a red light! You ___ someone!", "options": ["must have killed", "can't have killed", "could have killed", "should have killed"], "correctIndex": 2, "explain": "'Could have + particípio' indica possibilidade passada que não se realizou.", "id": "bkC1-191"}, {"type": "mcq", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Escolha a opção correta.", "prompt": "Lara ___ exhausted after the flight — she'd been awake for thirty hours.", "options": ["can't have been", "must have been", "needn't have been", "would be"], "correctIndex": 1, "explain": "Com evidência forte, usamos 'must have been' para quase certeza no passado.", "id": "bkC1-192"}, {"type": "choose", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Escolha as formas corretas.", "prompt": "The window [might have been*/might be] broken by the storm last night, but it [can't have been*/mustn't have been] the kids — they were away.", "explain": "Passado passivo: 'might have been broken'; certeza negativa: 'can't have been'.", "id": "bkC1-193"}, {"type": "choose", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Escolha as formas corretas.", "prompt": "When I called, Otávio didn't answer. He [may have been driving*/may drive] at the time. He [couldn't have*/mustn't have] known it was urgent — nobody told him.", "explain": "Ação em andamento no passado: 'may have been driving'; impossibilidade: 'couldn't have known'.", "id": "bkC1-194"}, {"type": "choose", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Escolha as formas corretas.", "prompt": "I'm not sure, but Ana [may not have*/can't have] seen your message. She usually checks it every hour, so she [should have*/must] replied by now.", "explain": "Dúvida pede 'may not have'; expectativa sobre o passado recente pede 'should have replied'.", "id": "bkC1-195"}, {"type": "error", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Encontre o erro.", "sentence": "They must have forgot to lock the door.", "wrong": "forgot", "fix": ["forgotten"], "explain": "Depois de 'must have' usamos o particípio: 'forgotten'.", "id": "bkC1-196"}, {"type": "error", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Encontre o erro de sentido.", "sentence": "He can't have been at the party; several friends saw him there.", "wrong": "can't have", "fix": ["must have"], "explain": "Se várias pessoas o viram lá, a dedução lógica é de certeza positiva: 'must have been', não 'can't have been'.", "id": "bkC1-197"}, {"type": "error", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Encontre o erro.", "sentence": "The thieves could entered through the back window.", "wrong": "could entered", "fix": ["could have entered", "may have entered", "might have entered", "must have entered"], "explain": "Especulação sobre o passado: modal + 'have' + particípio.", "id": "bkC1-198"}, {"type": "gaps", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Complete o diálogo com os modais e verbos.", "prompt": "A: Luana missed class today.\nB: She ___ (may / be) sick. She was coughing a lot yesterday.\nA: Or she ___ (might / oversleep) again!", "answers": [["may be", "may have been"], ["might have overslept"]], "explain": "'May be/have been' para possível doença; 'might have overslept' para possibilidade passada.", "id": "bkC1-199"}, {"type": "gaps", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Complete com os modais e verbos.", "prompt": "The office lights are still on. Someone ___ (must / forget) to turn them off. It ___ (can't / be) the cleaner, because she always checks. It ___ (could / be) the new intern, though.", "answers": [["must have forgotten"], ["can't have been", "couldn't have been"], ["could have been", "could be"]], "explain": "Must have = quase certeza; can't have = impossível; could have = possibilidade.", "id": "bkC1-200"}, {"type": "match", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Ligue cada frase ao seu significado.", "left": ["She must have left.", "She can't have left.", "She may have left.", "She should have left by now.", "She could have left, but she didn't."], "right": ["I'm almost sure she didn't leave.", "It's possible she left.", "It was possible for her to leave; she chose to stay.", "I'm almost sure she left.", "I expected her to have left already."], "correctMap": [3, 0, 1, 4, 2], "explain": "Must = certeza; can't = impossível; may = possível; should = expectativa; could... but = não realizado.", "id": "bkC1-201"}, {"type": "match", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Ligue cada situação à dedução lógica.", "left": ["The ground is covered in snow.", "Tomás's car isn't in the driveway.", "Julia got 100% on the exam.", "Marco didn't recognize me at all."], "right": ["She must have studied a lot.", "He must have gone out.", "It must have snowed during the night.", "He can't have seen me very clearly."], "correctMap": [2, 1, 0, 3], "explain": "Cada evidência leva a uma dedução lógica sobre o passado.", "id": "bkC1-202"}, {"type": "order", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Ordene as palavras para formar a frase.", "words": ["She", "could", "have", "been", "waiting", "for", "hours"], "explain": "'Could have been + -ing' especula sobre uma ação em andamento no passado.", "id": "bkC1-203"}, {"type": "order", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Ordene as palavras para formar a frase.", "words": ["The", "files", "may", "have", "been", "deleted", "by", "mistake"], "explain": "Especulação passiva: 'may have been' + particípio.", "id": "bkC1-204", "alt": ["By mistake the files may have been deleted"]}, {"type": "sort", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Classifique as frases.", "prompt": "Is the speaker speculating about the present or the past?", "groups": ["Sobre o presente", "Sobre o passado"], "items": [{"w": "She might be asleep.", "g": 0}, {"w": "He must be exhausted.", "g": 0}, {"w": "It can't be true.", "g": 0}, {"w": "They could be stuck in traffic.", "g": 0}, {"w": "She might have fallen asleep.", "g": 1}, {"w": "He must have run all the way.", "g": 1}, {"w": "It can't have been cheap.", "g": 1}, {"w": "They could have gotten lost.", "g": 1}], "explain": "Modal + verbo base fala do presente; modal + 'have' + particípio fala do passado.", "id": "bkC1-205"}, {"type": "tf", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "When Rafael returned to his campsite, his tent was flattened and the food bag was torn open. There were large paw prints in the mud. His friend said it must have been a dog, but the prints were far too big for that. A park ranger suggested it might have been a bear, although bears are rarely seen in the area. Rafael thinks he should have hung the food from a tree.", "items": [{"s": "His friend thought a dog was responsible.", "a": true}, {"s": "The ranger was certain it was a bear.", "a": false}, {"s": "Bears are often seen in the area.", "a": false}, {"s": "Rafael regrets not hanging the food from a tree.", "a": true}], "explain": "'Might have been' indica só possibilidade; 'should have hung' mostra arrependimento.", "id": "bkC1-206"}, {"type": "rewrite", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Reescreva com o modal de especulação.", "prompt": "I'm sure he didn't take your keys.", "start": "He can't have", "accept": ["He can't have taken your keys."], "explain": "Certeza negativa sobre o passado: 'can't have' + particípio.", "id": "bkC1-207"}, {"type": "blank", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Complete com o modal e o verbo.", "prompt": "The meeting ___ (should / finish) by now — it's already 6 p.m.", "accept": ["should have finished", "should have been finished"], "explain": "'Should have + particípio' indica o que esperamos que já tenha acontecido.", "id": "bkC1-208"}, {"type": "odd", "level": "C1", "topic": "Modais de especulação (may/might/could have)", "instruction": "Qual frase NÃO expressa apenas possibilidade?", "prompt": "Which sentence does NOT express mere possibility?", "options": ["She may have called.", "She might have called.", "She could have called.", "She must have called."], "correctIndex": 3, "explain": "'Must have' indica quase certeza; os outros indicam só possibilidade.", "id": "bkC1-209"}, {"type": "mcq", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Escolha a forma correta.", "prompt": "I'll have my assistant ___ you the documents tomorrow.", "options": ["to send", "sent", "send", "sending"], "correctIndex": 2, "explain": "'Have + pessoa + verbo base': 'have my assistant send'.", "id": "bkC1-210"}, {"type": "mcq", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Escolha a forma correta.", "prompt": "Can you get your brother ___ us with the move on Saturday?", "options": ["help", "to help", "helped", "helps"], "correctIndex": 1, "explain": "'Get + pessoa + to + verbo': convencer alguém a fazer algo.", "id": "bkC1-211"}, {"type": "mcq", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Escolha o verbo correto.", "prompt": "Where did you ___ your nails done? They look amazing!", "options": ["make", "do", "let", "get"], "correctIndex": 3, "explain": "'Get something done' = pagar para alguém fazer algo por você.", "id": "bkC1-212"}, {"type": "choose", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Escolha as formas corretas.", "prompt": "You had better [get*/make] that cough [checked*/check] by a doctor.", "explain": "Causativo: 'get + objeto + particípio' (get it checked).", "id": "bkC1-213"}, {"type": "choose", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Escolha as formas corretas.", "prompt": "We haven't had the carpets [cleaned*/clean] yet, but we'll [have*/get] a company do it next week.", "explain": "'Have + coisa + particípio'; com pessoa sem 'to', usamos 'have': 'have a company do it'.", "id": "bkC1-214"}, {"type": "choose", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Escolha as formas corretas.", "prompt": "I finally got the report [finished*/finish] at midnight, and I got my boss [to approve*/approve] it this morning.", "explain": "'Get + coisa + particípio' = conseguir terminar; 'get + pessoa + to + verbo'.", "id": "bkC1-215"}, {"type": "error", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Encontre o erro.", "sentence": "My landlord had the plumber to fix the leak.", "wrong": "to fix", "fix": ["fix"], "explain": "'Have + pessoa + verbo base', sem 'to': 'had the plumber fix'.", "id": "bkC1-216"}, {"type": "error", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Encontre o erro.", "sentence": "We are going to get our windows replace next month.", "wrong": "replace", "fix": ["replaced"], "explain": "No causativo o objeto é seguido do particípio: 'replaced'.", "id": "bkC1-217"}, {"type": "error", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Encontre o erro.", "sentence": "She got her sister take care of the kids.", "wrong": "take", "fix": ["to take"], "explain": "'Get + pessoa' pede 'to' + verbo: 'got her sister to take'.", "id": "bkC1-218"}, {"type": "gaps", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Complete o diálogo.", "prompt": "A: Your glasses look different.\nB: Yes, I ___ (have) the lenses ___ (change) last week. I'm also going to get the frame ___ (adjust).", "answers": [["had"], ["changed"], ["adjusted"]], "explain": "'Had the lenses changed' e 'get the frame adjusted': causativo com particípio.", "id": "bkC1-219"}, {"type": "gaps", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Complete o texto com as palavras do quadro.", "prompt": "Moving to Belém was stressful. Before we left, we ___ the house painted and got a friend ___ look after our cat. When we arrived, we had to ___ the air conditioning repaired immediately, because it was 35 degrees. We still haven't had everything ___, but it's starting to feel like home.", "answers": [["had", "got"], ["to"], ["get", "have"], ["done"]], "bank": ["had", "to", "get", "done", "make"], "explain": "Have/get + coisa + particípio; get + pessoa + to + verbo; 'had everything done'.", "id": "bkC1-220"}, {"type": "match", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Ligue as metades das frases.", "left": ["I'll get the waiter", "I'll have the waiter", "I'll get the table", "The manager had us"], "right": ["fill out a form before we could enter.", "to bring us more bread.", "bring us more bread.", "cleaned before we sit down."], "correctMap": [1, 2, 3, 0], "explain": "Get + pessoa + to; have + pessoa + verbo base; get + coisa + particípio.", "id": "bkC1-221"}, {"type": "match", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Ligue cada frase ao seu significado.", "left": ["I cut my hair.", "I had my hair cut.", "I had my wallet stolen.", "I got my son to mow the lawn."], "right": ["Someone took it without my permission.", "A professional did it for me.", "I persuaded him to do it.", "I did it myself."], "correctMap": [3, 1, 0, 2], "explain": "O causativo mostra quem faz a ação; 'had my wallet stolen' descreve algo ruim que aconteceu.", "id": "bkC1-222"}, {"type": "order", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Ordene as palavras para formar a frase.", "words": ["You", "should", "have", "your", "eyes", "tested", "every", "year"], "alt": ["Every year you should have your eyes tested"], "explain": "'Have + objeto + particípio' com modal: 'should have your eyes tested'.", "id": "bkC1-223"}, {"type": "order", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Ordene as palavras para formar a pergunta.", "words": ["Did", "you", "get", "the", "car", "washed", "before", "the", "trip"], "explain": "Pergunta no passado com causativo: 'Did you get the car washed'.", "id": "bkC1-224", "alt": ["Before the trip did you get the car washed"]}, {"type": "sort", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Classifique as expressões pela estrutura.", "prompt": "Sort the phrases by structure.", "groups": ["have + coisa + particípio", "get + pessoa + to + verbo", "have + pessoa + verbo base"], "items": [{"w": "had the fence painted", "g": 0}, {"w": "have my shoes repaired", "g": 0}, {"w": "had the locks changed", "g": 0}, {"w": "got the kids to tidy up", "g": 1}, {"w": "get Leo to call me", "g": 1}, {"w": "got the bank to lower the fee", "g": 1}, {"w": "had the intern book a room", "g": 2}, {"w": "have the driver wait outside", "g": 2}], "explain": "Com coisa: particípio; com pessoa: 'get... to' ou 'have' + verbo base.", "id": "bkC1-225"}, {"type": "tf", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Before opening her café in Olinda, Júlia had a lot to organize. She had the walls painted in bright colors and got a local artist to design the menu. She wanted to install the lights herself, but she ended up having an electrician do it. The only thing she hasn't had done yet is the sign outside, which will be ready next week.", "items": [{"s": "A local artist designed the menu.", "a": true}, {"s": "Júlia installed the lights herself.", "a": false}, {"s": "The sign outside is already finished.", "a": false}, {"s": "Someone else painted the walls.", "a": true}], "explain": "'Having an electrician do it' = outra pessoa instalou; 'hasn't had done yet' = ainda não feito.", "id": "bkC1-226"}, {"type": "reading", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Leia a mensagem e responda.", "text": "Hi Pedro,\nJust a quick update on the apartment. I had the kitchen tiles replaced on Monday, and the landlord finally got someone to fix the shower. I'm having the new sofa delivered on Friday afternoon, so could you be home to let them in? Also, I asked the building manager to have our names added to the intercom, but he hasn't done it yet.\nThanks! Bia", "questions": [{"q": "Who fixed the shower?", "options": ["Bia", "Someone the landlord found", "Pedro"], "correctIndex": 1}, {"q": "What does Bia ask Pedro to do?", "options": ["Call the landlord", "Replace the tiles", "Be at home on Friday afternoon"], "correctIndex": 2}, {"q": "What has NOT been done yet?", "options": ["Adding their names to the intercom", "Fixing the shower", "Replacing the tiles"], "correctIndex": 0}], "explain": "'Got someone to fix' = outra pessoa consertou; 'hasn't done it yet' refere-se ao interfone.", "id": "bkC1-227"}, {"type": "rewrite", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Reescreva usando \"get\" no causativo.", "prompt": "I persuaded my father to lend me his car.", "start": "I got my father", "accept": ["I got my father to lend me his car."], "explain": "'Get + pessoa + to + verbo' = convencer alguém a fazer algo.", "id": "bkC1-228"}, {"type": "dorder", "level": "C1", "topic": "Causativo (have/get something done)", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Your hair looks fantastic!", "B: Thanks! I had it done at that new salon on Rua Augusta.", "A: Really? How much did they charge you?", "B: About 150 reais. I also got my eyebrows shaped while I was there.", "A: That's a bargain. I should get mine done there too."], "explain": "A elogia, B explica onde fez, A pergunta o preço, B responde e A decide ir também.", "id": "bkC1-229"}, {"type": "mcq", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Escolha o verbo que forma a colocação.", "prompt": "Rising sea levels ___ a serious threat to coastal cities.", "options": ["make", "pose", "do", "give"], "correctIndex": 1, "explain": "A colocação é 'pose a threat' (representar uma ameaça).", "id": "bkC1-230"}, {"type": "mcq", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Escolha a palavra que completa a expressão.", "prompt": "After losing his job, Diego struggled to make ends ___.", "options": ["join", "touch", "meet", "connect"], "correctIndex": 2, "explain": "'Make ends meet' = conseguir pagar as contas com pouco dinheiro.", "id": "bkC1-231"}, {"type": "mcq", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Escolha a palavra que completa a expressão.", "prompt": "It took her years to come to ___ with her father's death.", "options": ["conditions", "agreements", "rules", "terms"], "correctIndex": 3, "explain": "'Come to terms with' = aceitar uma situação difícil.", "id": "bkC1-232"}, {"type": "choose", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Escolha as palavras corretas.", "prompt": "The concert was [bitterly*/strongly] disappointing, and the sound quality [fell*/went] short of our expectations.", "explain": "Colocações: 'bitterly disappointing' e 'fall short of expectations'.", "id": "bkC1-233"}, {"type": "choose", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Escolha as palavras corretas.", "prompt": "I was so absorbed in the book that I [lost*/missed] track of time. It's [highly*/strongly] unlikely I'll finish it tonight, though.", "explain": "Colocações: 'lose track of time' e 'highly unlikely'.", "id": "bkC1-234"}, {"type": "choose", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Escolha as palavras corretas.", "prompt": "Her promotion [set*/put] a precedent for other women in the company, and several firms soon [followed*/copied] suit.", "explain": "Colocações: 'set a precedent' e 'follow suit' (fazer o mesmo).", "id": "bkC1-235"}, {"type": "error", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Encontre o erro.", "sentence": "The police went to big lengths to find the missing child.", "wrong": "big", "fix": ["great"], "explain": "A colocação é 'go to great lengths' (fazer um grande esforço).", "id": "bkC1-236"}, {"type": "error", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Encontre o erro.", "sentence": "Many people take their health for grant until they get sick.", "wrong": "grant", "fix": ["granted"], "explain": "A expressão é 'take something for granted'.", "id": "bkC1-237"}, {"type": "error", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Encontre o erro.", "sentence": "Our new program aims to build the gap between theory and practice.", "wrong": "build", "fix": ["bridge", "close", "narrow"], "explain": "A colocação é 'bridge the gap' (aproximar duas coisas).", "id": "bkC1-238"}, {"type": "gaps", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Complete o texto com os verbos do quadro.", "prompt": "When the old coach retired, the players gathered to ___ tribute to him. Nobody wanted to ___ the news to the fans, but it was eventually announced online. The coach said he would ___ a low profile for a while. He also said he didn't ___ a grudge against the club's directors.", "answers": [["pay"], ["break"], ["keep"], ["hold", "bear"]], "bank": ["pay", "break", "keep", "hold", "make", "catch"], "explain": "Colocações: pay tribute, break the news, keep a low profile, hold a grudge.", "id": "bkC1-239"}, {"type": "gaps", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Complete o diálogo.", "prompt": "A: Do you think Brazil ___ a chance of winning the next World Cup?\nB: A slim one, maybe. This team is a ___ cry from the one we had in 2002.", "answers": [["stands", "has"], ["far"]], "explain": "'Stand a chance' = ter chance; 'a far cry from' = muito diferente de.", "id": "bkC1-240"}, {"type": "match", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Ligue cada advérbio ao adjetivo com que forma colocação.", "left": ["deeply", "utterly", "highly", "painfully", "fully"], "right": ["exhausted", "rooted", "recommended", "slow", "insured"], "correctMap": [1, 0, 2, 3, 4], "explain": "deeply rooted, utterly exhausted, highly recommended, painfully slow, fully insured.", "id": "bkC1-241"}, {"type": "match", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Ligue cada expressão ao seu significado.", "left": ["a narrow escape", "a golden opportunity", "a burning question", "a tight schedule"], "right": ["an urgent issue everyone wants answered", "very little free time between tasks", "a lucky avoidance of danger", "an excellent chance that may not come again"], "correctMap": [2, 3, 0, 1], "explain": "Colocações adjetivo + substantivo com sentido idiomático.", "id": "bkC1-242"}, {"type": "order", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Ordene as palavras para formar a frase.", "words": ["The", "campaign", "is", "gaining", "momentum", "across", "the", "country"], "alt": ["Across the country the campaign is gaining momentum"], "explain": "'Gain momentum' = ganhar força, crescer.", "id": "bkC1-243"}, {"type": "order", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Ordene as palavras para formar a frase.", "words": ["This", "photo", "does", "not", "do", "justice", "to", "the", "view"], "explain": "'Do justice to' = mostrar algo com toda a sua qualidade.", "id": "bkC1-244"}, {"type": "sort", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Classifique os substantivos pelo verbo.", "prompt": "Which verb goes with each noun?", "groups": ["make", "do", "take"], "items": [{"w": "a fuss", "g": 0}, {"w": "amends", "g": 0}, {"w": "headway", "g": 0}, {"w": "justice", "g": 1}, {"w": "harm", "g": 1}, {"w": "offense", "g": 2}, {"w": "charge", "g": 2}, {"w": "advantage", "g": 2}], "explain": "make a fuss/amends/headway; do justice/harm; take offense/charge/advantage.", "id": "bkC1-245"}, {"type": "odd", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Qual palavra NÃO combina com \"strong\"?", "prompt": "Which word does NOT collocate with 'strong'?", "options": ["coffee", "accent", "wind", "rain"], "correctIndex": 3, "explain": "Dizemos 'heavy rain', não 'strong rain'; 'strong coffee/accent/wind' estão corretos.", "id": "bkC1-246"}, {"type": "tf", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "When Priscila started her own business, she knew she would run into problems, but she didn't expect to come under so much pressure. Her savings ran out after six months, and she had to take out a loan to make ends meet. Things turned around when a famous chef praised her products online, and sales gained momentum. Now she says she never takes a customer for granted.", "items": [{"s": "Priscila expected running a business to be easy.", "a": false}, {"s": "She borrowed money from a bank or lender.", "a": true}, {"s": "Sales improved after a chef's online comment.", "a": true}, {"s": "She believes customers will always come back.", "a": false}], "explain": "'Take out a loan' = pegar empréstimo; 'never takes a customer for granted' = não conta com eles como garantidos.", "id": "bkC1-247"}, {"type": "rewrite", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Reescreva usando a expressão com \"grudge\".", "prompt": "Luis still resents his old boss for firing him.", "start": "Luis still holds a", "accept": ["Luis still holds a grudge against his old boss for firing him.", "Luis still holds a grudge against his old boss for having fired him."], "explain": "'Hold a grudge against someone' = guardar rancor de alguém.", "id": "bkC1-248"}, {"type": "dorder", "level": "C1", "topic": "Colocações idiomáticas", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: I've got some bad news, I'm afraid.", "B: Go on, break it to me gently.", "A: The client has pulled out of the deal.", "B: You're kidding! After all the effort we put in?", "A: I know. We'll just have to come to terms with it."], "explain": "A anuncia má notícia, B pede para contar, A conta, B reage e A consola.", "id": "bkC1-249"}, {"type": "mcq", "level": "C1", "topic": "Elipse e substituição", "instruction": "Escolha a palavra correta.", "prompt": "The population of São Paulo is larger than ___ of Rio de Janeiro.", "options": ["this", "it", "one", "that"], "correctIndex": 3, "explain": "'That of' substitui um substantivo singular já mencionado (the population).", "id": "bkC1-250"}, {"type": "mcq", "level": "C1", "topic": "Elipse e substituição", "instruction": "Escolha a palavra correta.", "prompt": "The manager asked us to cut costs, and we have done ___.", "options": ["so", "such", "one", "them"], "correctIndex": 0, "explain": "'Do so' substitui uma ação já mencionada (cut costs).", "id": "bkC1-251"}, {"type": "mcq", "level": "C1", "topic": "Elipse e substituição", "instruction": "Escolha a resposta correta.", "prompt": "A: Is the restaurant still open?\nB: I'm afraid ___. It closed at ten.", "options": ["no", "not", "so", "don't"], "correctIndex": 1, "explain": "'I'm afraid not' substitui uma oração negativa (it isn't open).", "id": "bkC1-252"}, {"type": "choose", "level": "C1", "topic": "Elipse e substituição", "instruction": "Escolha as palavras corretas.", "prompt": "Is the report ready? If [so*/it], please send it today; if [not*/no], let me know.", "explain": "'If so' e 'if not' substituem orações inteiras.", "id": "bkC1-253"}, {"type": "choose", "level": "C1", "topic": "Elipse e substituição", "instruction": "Escolha as palavras corretas.", "prompt": "Lucas speaks more languages than his father [does*/is], and [so does*/so is] his sister.", "explain": "O auxiliar substitui 'speaks': 'than his father does' e 'so does his sister'.", "id": "bkC1-254"}, {"type": "choose", "level": "C1", "topic": "Elipse e substituição", "instruction": "Escolha as expressões corretas.", "prompt": "We visited Lisbon and Porto. [The former*/The first one of] was busier, but we preferred [the latter*/the later].", "explain": "'The former' = o primeiro citado; 'the latter' = o segundo citado.", "id": "bkC1-255"}, {"type": "error", "level": "C1", "topic": "Elipse e substituição", "instruction": "Encontre o erro.", "sentence": "Mariana has already finished her project, but I didn't.", "wrong": "didn't", "fix": ["haven't"], "explain": "O auxiliar deve repetir o tempo da primeira oração: 'has finished' → 'I haven't'.", "id": "bkC1-256"}, {"type": "error", "level": "C1", "topic": "Elipse e substituição", "instruction": "Encontre o erro.", "sentence": "I lost my umbrella, so I need to buy a new.", "wrong": "a new", "fix": ["a new one", "another", "another one"], "explain": "Adjetivo sozinho não substitui substantivo contável; usamos 'a new one'.", "id": "bkC1-257"}, {"type": "error", "level": "C1", "topic": "Elipse e substituição", "instruction": "Encontre o erro.", "sentence": "I wanted to call you last night, but I forgot to do.", "wrong": "to do", "fix": ["to", "to do so", "to do it"], "explain": "Para evitar repetição, usamos só 'to' (forgot to) ou 'to do so'.", "id": "bkC1-258"}, {"type": "gaps", "level": "C1", "topic": "Elipse e substituição", "instruction": "Complete o diálogo.", "prompt": "A: Have you ever been to Iceland?\nB: No, but my parents ___. They loved it.\nA: Would you go there with them?\nB: I'd like ___, if I could afford it.", "answers": [["have", "have been"], ["to"]], "explain": "'My parents have' repete o auxiliar; 'I'd like to' omite o verbo depois de 'to'.", "id": "bkC1-259"}, {"type": "gaps", "level": "C1", "topic": "Elipse e substituição", "instruction": "Complete o texto com as palavras do quadro.", "prompt": "Our old office was small and dark; the new ___ is bright and spacious. The desks are much better than ___ we had before. I didn't expect to like the new place, but I ___. Will we stay here for a long time? I hope ___.", "answers": [["one"], ["those", "the ones"], ["do"], ["so"]], "bank": ["one", "those", "do", "so", "neither", "not"], "explain": "'One' substitui 'office'; 'those' substitui 'desks'; 'do' substitui 'like it'; 'so' substitui a oração.", "id": "bkC1-260"}, {"type": "match", "level": "C1", "topic": "Elipse e substituição", "instruction": "Ligue as metades das frases.", "left": ["I earn less than", "Julia wanted to leave early, but", "If you haven't finished the test yet,", "He promised to be on time, and"], "right": ["her husband didn't.", "he was.", "my brother does.", "please do so by Friday."], "correctMap": [2, 0, 3, 1], "explain": "O auxiliar ou 'do so' evita repetir o verbo da primeira parte.", "id": "bkC1-261"}, {"type": "match", "level": "C1", "topic": "Elipse e substituição", "instruction": "Ligue cada pergunta à resposta com elipse.", "left": ["A: Are you going to apply for the job?", "A: Did the kids behave well?", "A: Do you mind if I open the window?", "A: Is the repair going to be expensive?"], "right": ["B: Not at all. Go ahead.", "B: I'm afraid it is.", "B: I might. I haven't decided yet.", "B: Surprisingly, they did."], "correctMap": [2, 3, 0, 1], "explain": "As respostas curtas repetem só o auxiliar ou o modal, sem o resto da oração.", "id": "bkC1-262"}, {"type": "order", "level": "C1", "topic": "Elipse e substituição", "instruction": "Ordene as palavras para formar a frase.", "words": ["She", "said", "she", "would", "help", "and", "she", "did"], "explain": "'She did' substitui 'she helped', evitando repetição.", "id": "bkC1-263"}, {"type": "order", "level": "C1", "topic": "Elipse e substituição", "instruction": "Ordene as palavras para formar a frase.", "words": ["Some", "prefer", "tea", "and", "others", "coffee"], "alt": ["Some prefer coffee and others tea"], "explain": "Elipse do verbo (gapping): 'others coffee' = 'others prefer coffee'.", "id": "bkC1-264"}, {"type": "sort", "level": "C1", "topic": "Elipse e substituição", "instruction": "Classifique as frases.", "prompt": "Is the ellipsis or substitution correct?", "groups": ["Correta", "Incorreta"], "items": [{"w": "I haven't seen it, but Ana has.", "g": 0}, {"w": "She can't swim, and neither can I.", "g": 0}, {"w": "I'd love to, but I'm busy.", "g": 0}, {"w": "If so, call me.", "g": 0}, {"w": "I hope it.", "g": 1}, {"w": "She can't swim, and neither I can.", "g": 1}, {"w": "I'd love, but I'm busy.", "g": 1}, {"w": "I think it not.", "g": 1}], "explain": "Formas corretas: 'I hope so', 'neither can I', 'I'd love to', 'I think not'.", "id": "bkC1-265"}, {"type": "tf", "level": "C1", "topic": "Elipse e substituição", "instruction": "Leia o texto e marque verdadeiro ou falso.", "text": "Marta and her colleague Ivo both applied for the manager position. Marta had more experience than Ivo did, but he had a better degree. The company interviewed both, and in the end chose the latter. Marta was disappointed at first, but she soon found a better job elsewhere. Ivo says he's glad she did.", "items": [{"s": "Ivo had more experience than Marta.", "a": false}, {"s": "Ivo got the manager position.", "a": true}, {"s": "Marta stayed disappointed for a long time.", "a": false}, {"s": "Marta found a job at another company.", "a": true}], "explain": "'The latter' = o segundo mencionado (Ivo); 'she did' = she found a better job.", "id": "bkC1-266"}, {"type": "reading", "level": "C1", "topic": "Elipse e substituição", "instruction": "Leia a mensagem e responda.", "text": "Hi Nina,\nThanks for asking about the book club. Yes, we still meet on Thursdays, though not every week — only the first and third of each month. You asked whether you need to have read the book beforehand. Ideally, yes, but many people haven't, and nobody minds. As for food, some members bring snacks; others don't. If you'd like to, you could bring some pão de queijo!\nHope to see you there,\nOtávio", "questions": [{"q": "How often does the club meet?", "options": ["Every Thursday", "Twice a month", "Once a month"], "correctIndex": 1}, {"q": "Do members have to finish the book before a meeting?", "options": ["Yes, always", "It's preferred but not required", "No, it's not recommended"], "correctIndex": 1}, {"q": "What does Otávio suggest Nina bring?", "options": ["Drinks", "A book", "Pão de queijo"], "correctIndex": 2}], "explain": "'Many people haven't' = não leram o livro; 'if you'd like to' = se quiser trazer algo.", "id": "bkC1-267"}, {"type": "rewrite", "level": "C1", "topic": "Elipse e substituição", "instruction": "Reescreva omitindo o verbo repetido.", "prompt": "Ana drank wine, and Pedro drank beer.", "start": "Ana drank wine, and Pedro", "accept": ["Ana drank wine, and Pedro beer.", "Ana drank wine, and Pedro, beer."], "explain": "Na elipse (gapping), o verbo repetido é omitido na segunda oração.", "id": "bkC1-268"}, {"type": "dorder", "level": "C1", "topic": "Elipse e substituição", "instruction": "Coloque o diálogo na ordem correta.", "lines": ["A: Are you going to Bruno's barbecue on Sunday?", "B: I'd like to, but I'm not sure I can.", "A: Why not?", "B: My sister might be visiting. If so, I'll have to stay home.", "A: Bring her along! Bruno won't mind.", "B: Maybe I will."], "explain": "A convida, B hesita, A pergunta o motivo, B explica, A sugere e B aceita.", "id": "bkC1-269"}, {"type": "mcq", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Escolha a expressão idiomática que completa a frase.", "explain": "\"Beat around the bush\" = enrolar, evitar o assunto; o oposto de falar claramente.", "prompt": "The CEO saw no reason to ___; the report would state the losses plainly.", "options": ["hit the nail on the head", "call it a day", "beat around the bush", "go the extra mile"], "correctIndex": 2, "id": "bkC2-0"}, {"type": "mcq", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Qual é o equivalente mais formal de \"We need to get the ball rolling on this project\"?", "explain": "\"Initiate\" e \"promptly\" são formais; as outras opções usam expressões coloquiais.", "prompt": "Choose the most formal version.", "options": ["Let's get cracking on this project.", "We'd better get a move on with this project.", "Time to kick this project into gear.", "We should initiate work on this project promptly."], "correctIndex": 3, "id": "bkC2-1"}, {"type": "odd", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Qual item NÃO pertence ao registro informal?", "explain": "\"Ascertain\" (verificar) é formal; as demais são expressões informais.", "prompt": "Which item does not belong?", "options": ["pull someone's leg", "ascertain", "chill out", "a piece of cake"], "correctIndex": 1, "id": "bkC2-2"}, {"type": "choose", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Escolha as opções adequadas a uma carta formal.", "explain": "\"Regret to inform\" e \"has been unsuccessful\" são fórmulas formais; as outras são gírias.", "prompt": "We [regret*/are gutted] to inform you that your application [has been unsuccessful*/didn't make the cut].", "id": "bkC2-3"}, {"type": "error", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Encontre o trecho inadequado ao registro formal.", "explain": "\"Loads of\" é informal; numa reclamação formal use \"the numerous\" ou \"the many\".", "sentence": "Dear Sir or Madam, I am writing to complain about the loads of errors in your latest invoice.", "wrong": "the loads of", "fix": ["the numerous", "the many", "the multiple", "numerous", "many", "multiple"], "id": "bkC2-4"}, {"type": "match", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Ligue cada expressão idiomática ao seu significado.", "explain": "Cada idiom tem sentido figurado fixo, que não se deduz das palavras isoladas.", "left": ["to cut corners", "to be on the ball", "to get cold feet", "to call the shots", "to turn a blind eye"], "right": ["to deliberately ignore something wrong", "to do something cheaply or carelessly", "to make the decisions", "to be alert and quick to understand", "to become nervous and hesitate"], "correctMap": [1, 3, 4, 2, 0], "id": "bkC2-5"}, {"type": "sort", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Classifique as palavras e expressões por registro.", "explain": "Palavras de origem latina costumam ser formais; phrasal verbs e gírias, informais.", "prompt": "Sort into groups: Formal, Informal.", "groups": ["Formal", "Informal"], "items": [{"w": "stuff", "g": 1}, {"w": "loads of", "g": 1}, {"w": "endeavor", "g": 0}, {"w": "subsequently", "g": 0}, {"w": "commence", "g": 0}, {"w": "kick off", "g": 1}, {"w": "hang out", "g": 1}, {"w": "furthermore", "g": 0}], "id": "bkC2-6"}, {"type": "tf", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O sócio respondeu com educação, e Marina ainda usa linguagem informal com colegas.", "text": "Marina had been working at a São Paulo law firm for only three weeks when she emailed a senior partner: \"Hey! Just a heads-up, the Silva contract is a total mess.\" The partner replied politely but pointed out that clients' documents should be discussed in a more measured tone. Marina rewrote the message: \"Please note that the Silva contract contains several significant inconsistencies.\" Since then, she has saved informal expressions for chats with colleagues her own age.", "items": [{"s": "Marina's first email used informal language.", "a": true}, {"s": "The partner reacted angrily to Marina's email.", "a": false}, {"s": "Marina's second version expressed the same concern in a formal register.", "a": true}, {"s": "Marina has stopped using informal expressions altogether.", "a": false}], "id": "bkC2-7"}, {"type": "dorder", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta inicial leva ao relato; o conselho \"don't count your chickens\" vem após a falta de compromisso.", "lines": ["A: So, how did the pitch to the investors go?", "B: Honestly, I think we nailed it. They were hanging on our every word.", "A: That's great! Did they commit to anything?", "B: Not yet, but they want a follow-up meeting next week.", "A: Well, don't count your chickens before they hatch.", "B: Fair enough. I won't celebrate until the contract is signed."], "id": "bkC2-8"}, {"type": "gaps", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Complete o texto com as palavras do banco.", "explain": "Idioms fixos: break the ice, fall flat, bite the bullet, warm up to someone.", "prompt": "The new manager was eager to make a good first impression. On her first day, she tried to break the ___ with a joke, but it fell ___. Undeterred, she decided to bite the ___ and announce the budget cuts at once. By Friday, the team had warmed ___ to her.", "answers": [["ice"], ["flat"], ["bullet"], ["up"]], "bank": ["ice", "flat", "bullet", "up", "down", "cake"], "id": "bkC2-9"}, {"type": "mcq", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Escolha a palavra que completa a frase com precisão.", "explain": "\"Ambiguous\" = aberto a mais de uma interpretação, por isso os dois lados se sentiram apoiados.", "prompt": "The minister's remarks were deliberately ___, allowing both sides to claim she supported them.", "options": ["ambiguous", "unequivocal", "ambitious", "anonymous"], "correctIndex": 0, "id": "bkC2-10"}, {"type": "mcq", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Qual palavra tem a conotação mais NEGATIVA?", "explain": "\"Stingy\" = pão-duro (crítica); thrifty, frugal e economical elogiam a economia.", "prompt": "He is so ___ with his money that his friends are tired of paying for him.", "options": ["thrifty", "frugal", "stingy", "economical"], "correctIndex": 2, "id": "bkC2-11"}, {"type": "odd", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Qual palavra NÃO significa \"tornar algo menos grave\"?", "explain": "\"Exacerbate\" significa agravar; as outras significam atenuar ou aliviar.", "prompt": "Which word does not belong?", "options": ["mitigate", "alleviate", "assuage", "exacerbate"], "correctIndex": 3, "id": "bkC2-12"}, {"type": "choose", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Escolha a palavra correta em cada par de confusão comum.", "explain": "Complement = completar; effect = substantivo; uninterested = sem interesse (disinterested = imparcial).", "prompt": "The new policy, which [complimented/complemented*] the existing rules, had a profound [effect*/affect] on staff, yet the board seemed [disinterested/uninterested*] in their feedback.", "id": "bkC2-13"}, {"type": "error", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Encontre a palavra usada com o sentido errado.", "explain": "\"Flaunt\" = ostentar; desrespeitar regras é \"flout\".", "sentence": "Several drivers were fined for flaunting the new traffic regulations.", "wrong": "flaunting", "fix": ["flouting", "violating", "breaking", "disregarding", "ignoring"], "id": "bkC2-14"}, {"type": "match", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Ligue cada verbo ao seu significado.", "explain": "São pares frequentemente confundidos: prescribe/proscribe, imply/infer, elicit/illicit.", "left": ["prescribe", "proscribe", "imply", "infer", "elicit"], "right": ["to suggest indirectly", "to recommend or order officially", "to deduce from evidence", "to draw out a response", "to forbid"], "correctMap": [1, 4, 0, 2, 3], "id": "bkC2-15"}, {"type": "sort", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Classifique os adjetivos pela conotação.", "explain": "Cada par descreve traço parecido, mas a palavra negativa sugere excesso ou crítica.", "prompt": "Sort into groups: Conotação positiva, Conotação negativa.", "groups": ["Conotação positiva", "Conotação negativa"], "items": [{"w": "pushy", "g": 1}, {"w": "curious", "g": 0}, {"w": "arrogant", "g": 1}, {"w": "nosy", "g": 1}, {"w": "determined", "g": 0}, {"w": "assertive", "g": 0}, {"w": "pig-headed", "g": 1}, {"w": "confident", "g": 0}], "id": "bkC2-16"}, {"type": "reading", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Leia o texto e responda às perguntas.", "explain": "\"Frequently\" entre dois verbos podia modificar qualquer um; antes de \"complain\" fica claro.", "text": "A notice posted in a Curitiba office read: \"Employees who complain frequently will be transferred.\" Some staff members understood that anyone who complains often would be moved. Others read it as saying that complainers would be transferred again and again. The HR director later admitted that the position of the adverb had caused the confusion. The notice was replaced with: \"Employees who often complain will be transferred.\"", "questions": [{"q": "What caused the confusion?", "options": ["A spelling mistake", "The position of an adverb", "An unclear verb tense"], "correctIndex": 1}, {"q": "In the revised notice, what does \"often\" modify?", "options": ["complain", "be transferred", "employees"], "correctIndex": 0}], "id": "bkC2-17"}, {"type": "rewrite", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Reescreva deixando claro que EU usei o telescópio.", "explain": "Na original, \"with the telescope\" pode indicar o instrumento ou quem estava com o telescópio.", "prompt": "I saw the man with the telescope.", "start": "Using the telescope", "accept": ["Using the telescope, I saw the man.", "Using the telescope, I could see the man."], "id": "bkC2-18"}, {"type": "order", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Ordene as palavras para formar a frase.", "explain": "\"Sanction\" é ambígua: pode ser aprovação ou punição, conforme o contexto.", "words": ["The", "word", "sanction", "can", "mean", "both", "approval", "and", "penalty"], "alt": ["The word sanction can mean both penalty and approval"], "id": "bkC2-19"}, {"type": "mcq", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Qual frase tem o hedging mais adequado para um artigo acadêmico?", "explain": "\"Suggest\" e \"may\" expressam cautela; as outras afirmam com certeza exagerada.", "prompt": "Choose the most appropriately hedged sentence.", "options": ["The results prove that sleep deprivation destroys memory.", "The results suggest that sleep deprivation may impair memory consolidation.", "Sleep deprivation obviously ruins memory.", "Everyone knows that sleep deprivation affects memory."], "correctIndex": 1, "id": "bkC2-20"}, {"type": "choose", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Escolha as opções que expressam cautela acadêmica.", "explain": "\"Appear to\" e \"relatively\" atenuam a afirmação, típico do hedging acadêmico.", "prompt": "These data [appear*/are certain] to support the hypothesis, although the sample was [relatively*/undeniably] small.", "id": "bkC2-21"}, {"type": "error", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Encontre o trecho que contradiz o tom cauteloso da frase.", "explain": "\"Proves beyond doubt\" é categórico e contradiz \"may\" e \"some patients\".", "sentence": "This study proves beyond doubt that the drug may reduce anxiety in some patients.", "wrong": "proves beyond doubt", "fix": ["suggests", "indicates"], "id": "bkC2-22"}, {"type": "match", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Ligue cada grupo de exemplos ao tipo de recurso de hedging.", "explain": "O hedging usa modais, verbos, advérbios e expressões que limitam o alcance da afirmação.", "left": ["may, might, could", "seem, appear, tend", "possibly, arguably, presumably", "to some extent, in most cases"], "right": ["adverbs", "limiting phrases", "modal verbs", "lexical verbs"], "correctMap": [2, 3, 0, 1], "id": "bkC2-23"}, {"type": "sort", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Classifique: a expressão atenua (hedge) ou reforça (booster)?", "explain": "Hedges reduzem o grau de certeza; boosters o aumentam.", "prompt": "Sort into groups: Hedge (atenua), Booster (reforça).", "groups": ["Hedge (atenua)", "Booster (reforça)"], "items": [{"w": "it is beyond question that", "g": 1}, {"w": "clearly demonstrates", "g": 1}, {"w": "tends to", "g": 0}, {"w": "arguably", "g": 0}, {"w": "invariably", "g": 1}, {"w": "it is conceivable that", "g": 0}, {"w": "to some extent", "g": 0}, {"w": "undoubtedly", "g": 1}], "id": "bkC2-24"}, {"type": "tf", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O texto diz que revisores veem o hedging como honestidade, e o exemplo médico é só ilustração.", "text": "In academic writing, hedging allows authors to present claims with appropriate caution. Rather than stating that a treatment \"cures\" a disease, a researcher might write that it \"appears to reduce symptoms in a subset of patients\". Hedging is not a sign of weakness; reviewers often regard it as evidence of intellectual honesty. However, excessive hedging can make an argument seem evasive or vague.", "items": [{"s": "Reviewers generally regard hedging as a weakness.", "a": false}, {"s": "Too much hedging can make an argument seem vague.", "a": true}, {"s": "The text gives a more cautious alternative to the word \"cures\".", "a": true}, {"s": "According to the text, hedging is used only in medical research.", "a": false}], "id": "bkC2-25"}, {"type": "reading", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Leia o resumo e responda às perguntas.", "explain": "Os autores atenuam as conclusões porque correlação não prova causa.", "text": "Abstract: This study examined the reading habits of 312 university students in Recife. The data indicate that students who read fiction regularly tended to score somewhat higher on measures of empathy. However, given the correlational design, it cannot be concluded that reading fiction causes greater empathy. It is possible that more empathetic individuals are simply drawn to fiction. Further longitudinal research would help to clarify the direction of this relationship.", "questions": [{"q": "What do the authors claim about fiction and empathy?", "options": ["There is an association between them.", "Reading fiction causes empathy.", "Empathy has no link to reading."], "correctIndex": 0}, {"q": "Why do the authors avoid a causal claim?", "options": ["The sample was too small.", "The students gave dishonest answers.", "The study design was correlational."], "correctIndex": 2}, {"q": "Which phrase from the text is NOT an example of hedging?", "options": ["tended to", "This study examined", "It is possible that"], "correctIndex": 1}], "id": "bkC2-26"}, {"type": "dorder", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Coloque o diálogo entre orientadora e aluno na ordem correta.", "explain": "A crítica ao verbo \"prove\" gera a pergunta, a sugestão de hedging e o tema da limitação.", "lines": ["A: I've read your draft. Your conclusion says the results \"prove\" the theory.", "B: Is that a problem? The data seemed quite convincing.", "A: With only forty participants, it's safer to say they \"lend support to\" it.", "B: I see. Should I also mention the sample size as a limitation?", "A: Yes. Reviewers tend to appreciate authors who acknowledge limitations."], "id": "bkC2-27"}, {"type": "rewrite", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Atenue a afirmação começando com \"It is possible that\" e mantendo o resto.", "explain": "\"It is possible that\" transforma uma afirmação categórica em hipótese.", "prompt": "Social media causes depression in teenagers.", "start": "It is possible that", "accept": ["It is possible that social media causes depression in teenagers.", "It is possible that social media can cause depression in teenagers.", "It is possible that social media could cause depression in teenagers.", "It is possible that social media may cause depression in teenagers."], "id": "bkC2-28"}, {"type": "gaps", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Complete o texto com as palavras do banco.", "explain": "\"Suggest\", modais e \"to some extent\" são marcas de hedging; prove e certainly seriam categóricos.", "prompt": "The results ___ that the new method is more efficient, although this ___ be due to the small sample. It ___ be argued that further trials are needed. The findings are, to some ___, consistent with earlier studies.", "answers": [["suggest"], ["may", "could"], ["could", "may"], ["extent"]], "bank": ["suggest", "may", "could", "extent", "prove", "certainly"], "id": "bkC2-29"}, {"type": "mcq", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Qual é a versão mais concisa?", "explain": "Mesma ideia com menos palavras: \"decide\" substitui \"make a decision\" e \"now\" substitui \"at this point in time\".", "prompt": "Choose the most concise sentence.", "options": ["At this point in time, we must make a decision.", "It is necessary for us to make a decision at this present moment.", "We are in a position where a decision must be made now.", "We must decide now."], "correctIndex": 3, "id": "bkC2-30"}, {"type": "odd", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Qual expressão NÃO é redundante?", "explain": "Past history, free gift e end result são pleonasmos; \"recent survey\" acrescenta informação.", "prompt": "Which phrase does not belong?", "options": ["past history", "free gift", "recent survey", "end result"], "correctIndex": 2, "id": "bkC2-31"}, {"type": "error", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Encontre a redundância.", "explain": "\"Merge\" já significa unir-se; \"together\" é redundante.", "sentence": "The two companies decided to merge together in order to cut costs.", "wrong": "merge together", "fix": ["merge"], "id": "bkC2-32"}, {"type": "error", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Encontre a redundância.", "explain": "O prefixo \"re-\" já indica repetição; \"again\" é redundante.", "sentence": "The committee will reconvene again next Tuesday to finalize the budget.", "wrong": "reconvene again", "fix": ["reconvene", "meet again"], "id": "bkC2-33"}, {"type": "choose", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Escolha a opção mais concisa em cada caso.", "explain": "\"Basic fundamentals\" é pleonasmo; \"at 40 pages\" e \"clearly\" dizem o mesmo com menos palavras.", "prompt": "The report, [which is 40 pages long/at 40 pages*], covers the [basic fundamentals/fundamentals*] of tax law [in a clear way/clearly*].", "id": "bkC2-34"}, {"type": "match", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Ligue cada expressão prolixa à forma concisa.", "explain": "Expressões longas podem ser trocadas por uma só palavra sem perda de sentido.", "left": ["due to the fact that", "in the event that", "at this point in time", "in spite of the fact that", "has the ability to"], "right": ["if", "although", "can", "now", "because"], "correctMap": [4, 0, 3, 1, 2], "id": "bkC2-35"}, {"type": "sort", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Classifique: pleonasmo ou combinação legítima?", "explain": "No pleonasmo o adjetivo repete o sentido do substantivo; nos outros ele acrescenta informação.", "prompt": "Sort into groups: Pleonasmo, Combinação legítima.", "groups": ["Pleonasmo", "Combinação legítima"], "items": [{"w": "true facts", "g": 0}, {"w": "work together", "g": 1}, {"w": "added bonus", "g": 0}, {"w": "collaborate together", "g": 0}, {"w": "unexpected surprise", "g": 0}, {"w": "true story", "g": 1}, {"w": "added cost", "g": 1}, {"w": "pleasant surprise", "g": 1}], "id": "bkC2-36"}, {"type": "reading", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Leia a mensagem do editor e responda às perguntas.", "explain": "O texto excede o limite por repetição e expressões vazias, não por falta de originalidade.", "text": "Dear authors, thank you for your submission. The editorial board found your argument original, but the manuscript exceeds our 6,000-word limit by nearly 2,000 words. Much of the excess comes from repetition: several points in the introduction are restated almost verbatim in the conclusion. We also noticed frequent phrases such as \"it is important to note that\", which rarely add meaning. Please revise the manuscript and resubmit it within 30 days.", "questions": [{"q": "What is the main problem with the manuscript?", "options": ["Its argument is unoriginal.", "It was submitted late.", "It is too long."], "correctIndex": 2}, {"q": "What does the editor imply about \"it is important to note that\"?", "options": ["It is usually unnecessary.", "It should be used more often.", "It must be replaced by a citation."], "correctIndex": 0}, {"q": "Where does most of the repetition occur?", "options": ["In the reference list", "Between the introduction and the conclusion", "In the methodology section"], "correctIndex": 1}], "id": "bkC2-37"}, {"type": "rewrite", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Elimine as redundâncias, começando com o trecho dado.", "explain": "\"Postponed\" já implica data posterior, e \"because of the fact that\" equivale a \"because\".", "prompt": "The meeting was postponed until a later date because of the fact that the director was ill.", "start": "The meeting was postponed because", "accept": ["The meeting was postponed because the director was ill.", "The meeting was postponed because the director was sick.", "The meeting was postponed because the director was unwell."], "id": "bkC2-38"}, {"type": "order", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Ordene as palavras para formar uma frase concisa.", "explain": "Frase direta: pedido + prazo + condição, sem palavras desnecessárias.", "words": ["Please", "reply", "by", "Friday", "if", "you", "can", "attend"], "alt": ["If you can attend please reply by Friday"], "id": "bkC2-39"}, {"type": "mcq", "level": "C2", "topic": "Variação de registro", "instruction": "Em que contexto \"Cheers, mate!\" seria mais adequado?", "explain": "\"Cheers, mate!\" é informal (inglês britânico), próprio de situações descontraídas entre amigos.", "prompt": "Where would \"Cheers, mate!\" be most appropriate?", "options": ["Closing a job application letter", "Ending a legal contract", "Thanking a friend at a pub", "Addressing a judge in court"], "correctIndex": 2, "id": "bkC2-40"}, {"type": "odd", "level": "C2", "topic": "Variação de registro", "instruction": "Qual expressão pertence a um registro diferente?", "explain": "\"Catch you later\" é informal; as outras são fórmulas de correspondência formal.", "prompt": "Which expression does not belong?", "options": ["Catch you later", "Yours faithfully", "Please find attached", "I look forward to hearing from you"], "correctIndex": 0, "id": "bkC2-41"}, {"type": "choose", "level": "C2", "topic": "Variação de registro", "instruction": "Escolha as opções adequadas a um e-mail para um cliente.", "explain": "Com clientes usa-se registro formal: \"apologize for\" e \"contact you\".", "prompt": "We [apologize for*/are super sorry about] the delay and will [contact you*/hit you up] shortly.", "id": "bkC2-42"}, {"type": "match", "level": "C2", "topic": "Variação de registro", "instruction": "Ligue cada verbo formal ao equivalente informal.", "explain": "Verbos de origem latina são mais formais que seus equivalentes germânicos do dia a dia.", "left": ["obtain", "assist", "inquire", "reside", "commence"], "right": ["help", "live", "get", "start", "ask"], "correctMap": [2, 0, 4, 1, 3], "id": "bkC2-43"}, {"type": "sort", "level": "C2", "topic": "Variação de registro", "instruction": "Classifique as frases por registro.", "explain": "Frases formais usam estruturas impessoais e condicionais; as informais usam gírias e reduções.", "prompt": "Sort into groups: Registro formal, Registro informal.", "groups": ["Registro formal", "Registro informal"], "items": [{"w": "Wanna grab a bite later?", "g": 1}, {"w": "No worries, happy to help!", "g": 1}, {"w": "Further to our conversation, I enclose the report.", "g": 0}, {"w": "That movie was awesome!", "g": 1}, {"w": "Should you require assistance, do not hesitate to contact us.", "g": 0}, {"w": "Give me a sec, I'll check.", "g": 1}, {"w": "I would be grateful if you could confirm receipt.", "g": 0}, {"w": "We regret any inconvenience caused.", "g": 0}], "id": "bkC2-44"}, {"type": "tf", "level": "C2", "topic": "Variação de registro", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Rafael muda de registro conforme o contexto; o cliente não reclamou, mas o gerente o aconselhou.", "text": "Rafael, a software engineer from Belo Horizonte, adapts his language to each situation. He writes formal reports for his managers, uses a neutral tone in team emails, and chats in slang with his friends on WhatsApp. Last month, he accidentally sent a message full of abbreviations and emojis to a client. The client did not complain, but Rafael's manager advised him to double-check recipients before sending.", "items": [{"s": "Rafael uses the same register in every situation.", "a": false}, {"s": "The client complained about Rafael's message.", "a": false}, {"s": "Rafael's manager gave him advice after the incident.", "a": true}], "id": "bkC2-45"}, {"type": "dorder", "level": "C2", "topic": "Variação de registro", "instruction": "Coloque o telefonema formal na ordem correta.", "explain": "Saudação da empresa, pedido, identificação e transferência: sequência típica de ligação formal.", "lines": ["A: Good afternoon, Hartley & Moss. How may I help you?", "B: Good afternoon. I'd like to speak to Ms. Moss, please.", "A: May I ask who's calling?", "B: This is Daniel Reis from Porto Consulting.", "A: Thank you, Mr. Reis. I'll put you through now."], "id": "bkC2-46"}, {"type": "gaps", "level": "C2", "topic": "Variação de registro", "instruction": "Complete a carta formal com as palavras do banco.", "explain": "Fórmulas formais fixas; com o nome do destinatário (Mr. Lopes) usa-se \"Yours sincerely\".", "prompt": "Dear Mr. Lopes,\nI am writing to ___ about the vacancy advertised on your website. I would be ___ if you could send me further details. I ___ forward to hearing from you.\nYours ___,\nAna Costa", "answers": [["inquire", "enquire"], ["grateful"], ["look"], ["sincerely"]], "bank": ["inquire", "grateful", "look", "sincerely", "faithfully", "keen"], "id": "bkC2-47"}, {"type": "rewrite", "level": "C2", "topic": "Variação de registro", "instruction": "Reescreva o pedido em registro formal, sem abreviações.", "explain": "\"Could you please\" é mais cortês, e \"ASAP\" deve ser escrito por extenso no registro formal.", "prompt": "Can you send me the file ASAP?", "start": "Could you please", "accept": ["Could you please send me the file as soon as possible?", "Could you please send the file to me as soon as possible?", "Could you please send me the file at your earliest convenience?"], "id": "bkC2-48"}, {"type": "error", "level": "C2", "topic": "Variação de registro", "instruction": "Encontre a palavra inadequada ao registro formal.", "explain": "\"Kinda\" é coloquial; em contexto corporativo use \"somewhat\" ou \"rather\".", "sentence": "The board is kinda concerned about the decline in quarterly revenue.", "wrong": "kinda", "fix": ["somewhat", "rather", "slightly"], "id": "bkC2-49"}, {"type": "mcq", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Escolha o marcador que completa a frase.", "explain": "\"That said\" introduz uma ressalva após reconhecer um ponto positivo.", "prompt": "The proposal is ambitious; ___, it lacks a realistic budget.", "options": ["that said", "hence", "likewise", "in other words"], "correctIndex": 0, "id": "bkC2-50"}, {"type": "mcq", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Escolha o marcador que completa a frase.", "explain": "\"Be that as it may\" = seja como for; introduz contraste com o que foi dito.", "prompt": "The drug showed promising results in mice. ___, human trials have yet to begin.", "options": ["Accordingly", "By the same token", "Be that as it may", "In other words"], "correctIndex": 2, "id": "bkC2-51"}, {"type": "choose", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Escolha o marcador adequado em cada caso.", "explain": "\"Notwithstanding this\" = apesar disso; \"Admittedly\" reconhece um ponto a favor.", "prompt": "The evidence was thin; [notwithstanding*/consequently] this, the committee approved the plan. [Admittedly*/Hence], the risks were small.", "id": "bkC2-52"}, {"type": "gaps", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Complete o texto com os marcadores do banco.", "explain": "However = contraste; despite + substantivo; for its part = da sua parte; accordingly = consequentemente.", "prompt": "Profits rose by 12% last year. ___, the company's debt more than doubled. ___ its strong sales, investors remain cautious. The board, ___, believes that the long-term outlook is positive. ___, it plans to expand into Chile next year.", "answers": [["However"], ["Despite"], ["for its part"], ["Accordingly"]], "bank": ["However", "Despite", "for its part", "Accordingly", "Although", "Whereas"], "id": "bkC2-53"}, {"type": "error", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Encontre o marcador usado incorretamente.", "explain": "\"Albeit\" não introduz oração com sujeito e verbo; use \"although\".", "sentence": "Albeit the weather was terrible, the ceremony went ahead as planned.", "wrong": "Albeit", "fix": ["Although", "Though", "Even though", "While"], "id": "bkC2-54"}, {"type": "match", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Ligue cada marcador à sua função.", "explain": "Cada marcador sinaliza uma relação lógica diferente entre as ideias.", "left": ["Be that as it may", "By the same token", "To put it another way", "All things considered"], "right": ["similarity", "concession", "conclusion", "reformulation"], "correctMap": [1, 0, 3, 2], "id": "bkC2-55"}, {"type": "reading", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Leia o texto e responda às perguntas.", "explain": "Granted concede, nevertheless contrasta, consequently mostra resultado, in short resume.", "text": "Remote work, it is often claimed, boosts productivity. Granted, many employees report fewer distractions at home. Nevertheless, a recent survey of tech firms in Porto Alegre found that collaboration suffered when teams never met in person. Consequently, several companies have adopted hybrid schedules. In short, the debate is less about where people work than about how they work together.", "questions": [{"q": "What is the function of \"Granted\" in the text?", "options": ["It introduces a conclusion.", "It concedes a point before a counterargument.", "It gives an example from the survey."], "correctIndex": 1}, {"q": "What does \"Consequently\" introduce?", "options": ["A result of the survey's findings", "A contrast with the previous sentence", "The author's personal experience"], "correctIndex": 0}, {"q": "Which marker signals a summary?", "options": ["Nevertheless", "Granted", "In short"], "correctIndex": 2}], "id": "bkC2-56"}, {"type": "order", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Ordene as palavras para formar a frase.", "explain": "\"Needless to say\" = nem é preciso dizer; costuma abrir a frase.", "words": ["Needless", "to", "say", "the", "launch", "was", "postponed", "indefinitely"], "alt": ["The launch needless to say was postponed indefinitely", "The launch was postponed indefinitely needless to say", "The launch was needless to say postponed indefinitely"], "id": "bkC2-57"}, {"type": "odd", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Qual marcador NÃO expressa contraste ou concessão?", "explain": "\"Hence\" indica consequência; os outros expressam contraste ou concessão.", "prompt": "Which marker does not belong?", "options": ["nonetheless", "even so", "that said", "hence"], "correctIndex": 3, "id": "bkC2-58"}, {"type": "sort", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Classifique os marcadores pela função.", "explain": "Cada marcador pertence a uma relação lógica: contraste, consequência ou adição.", "prompt": "Sort into groups: Contraste ou concessão, Consequência, Adição.", "groups": ["Contraste ou concessão", "Consequência", "Adição"], "items": [{"w": "accordingly", "g": 1}, {"w": "furthermore", "g": 2}, {"w": "nonetheless", "g": 0}, {"w": "even so", "g": 0}, {"w": "what is more", "g": 2}, {"w": "hence", "g": 1}, {"w": "thereby", "g": 1}, {"w": "albeit", "g": 0}], "id": "bkC2-59"}, {"type": "mcq", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Qual frase é um exemplo de litotes?", "explain": "Litotes afirma algo negando o contrário: \"not unfamiliar\" = bastante familiarizada.", "prompt": "Which sentence contains litotes?", "options": ["She is the greatest expert on earth.", "She is not unfamiliar with the subject.", "She knows the subject like the back of her hand.", "She studied the subject for years."], "correctIndex": 1, "id": "bkC2-60"}, {"type": "mcq", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Que figura de linguagem é usada na fala do prefeito?", "explain": "Minimizar algo grave (\"a bit of a rough week\") é understatement.", "prompt": "After a hurricane destroyed half the town, the mayor said, \"We've had a bit of a rough week.\"", "options": ["hyperbole", "alliteration", "onomatopoeia", "understatement"], "correctIndex": 3, "id": "bkC2-61"}, {"type": "odd", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Qual frase NÃO contém litotes?", "explain": "As outras negam o contrário para afirmar; \"absolutely delicious\" é afirmação direta.", "prompt": "Which sentence does not belong?", "options": ["That was no small achievement.", "He's not the brightest student.", "The food was absolutely delicious.", "The food wasn't bad at all."], "correctIndex": 2, "id": "bkC2-62"}, {"type": "tf", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O editor usa understatement como elogio; Clara é irônica, pois o livro tem 900 páginas.", "text": "When first-time novelist Clara Mendes won a national prize, her notoriously blunt editor remarked, \"Well, it's not the worst book I've read this year.\" Journalists were puzzled, but Clara laughed: she knew this was the highest praise he ever gave. Later, when a critic asked about the novel's 900 pages, Clara replied that she had \"tried to keep it short\".", "items": [{"s": "The editor's comment was meant as a compliment.", "a": true}, {"s": "Clara was offended by her editor's remark.", "a": false}, {"s": "Clara's reply about keeping the book short was ironic.", "a": true}, {"s": "The novel is very short.", "a": false}], "id": "bkC2-63"}, {"type": "dorder", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Coloque o diálogo na ordem correta.", "explain": "\"Fantastic\" é irônico; a pergunta sobre a mala e o comentário final seguem a sequência lógica.", "lines": ["A: How was your flight from Manaus?", "B: Oh, fantastic. A four-hour delay, and then they lost my suitcase.", "A: You're joking! Did you get it back?", "B: Eventually. It turned up two days later, soaking wet.", "A: Well, at least it wasn't boring.", "B: No, \"boring\" is not the word I'd use."], "id": "bkC2-64"}, {"type": "reading", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Leia o texto e responda às perguntas.", "explain": "O texto mostra que o understatement britânico esconde problemas sérios e confunde estrangeiros.", "text": "In British English, understatement is something of a social art. A person who has just run a marathon in pouring rain might describe the experience as \"a little damp\". A manager may call a disastrous quarter \"not ideal\". Foreigners sometimes take such phrases literally and underestimate how serious a situation is. For example, if a colleague says your proposal is \"interesting, with a few minor issues\", it may actually need a complete rewrite.", "questions": [{"q": "What is the main idea of the text?", "options": ["Understatement is common and can be misunderstood.", "British people dislike running in the rain.", "Managers are always honest about bad results."], "correctIndex": 0}, {"q": "What might \"interesting, with a few minor issues\" really mean?", "options": ["The proposal is excellent.", "The proposal will be approved immediately.", "The proposal needs substantial changes."], "correctIndex": 2}], "id": "bkC2-65"}, {"type": "match", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Ligue cada frase ao seu sentido real.", "explain": "Litotes e ironia dizem o contrário ou menos do que realmente se quer dizer.", "left": ["'It's not exactly cheap.'", "'She's no stranger to controversy.'", "'Well, that went well.' (after a disaster)", "'I'm not unhappy with the results.'"], "right": ["It went terribly.", "I am fairly satisfied.", "It is very expensive.", "She has often been involved in controversy."], "correctMap": [2, 3, 0, 1], "id": "bkC2-66"}, {"type": "sort", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Classifique: litotes ou hipérbole?", "explain": "Litotes atenua negando o contrário; hipérbole exagera.", "prompt": "Sort into groups: Litotes, Hipérbole.", "groups": ["Litotes", "Hipérbole"], "items": [{"w": "not uncommon", "g": 0}, {"w": "no mean feat", "g": 0}, {"w": "not the worst idea", "g": 0}, {"w": "I've told you a million times", "g": 1}, {"w": "not bad at all", "g": 0}, {"w": "I'm starving to death", "g": 1}, {"w": "this bag weighs a ton", "g": 1}, {"w": "we waited forever", "g": 1}], "id": "bkC2-67"}, {"type": "error", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Encontre a palavra errada na expressão.", "explain": "A expressão é \"no mean feat\" (feito nada pequeno); \"feet\" significa pés.", "sentence": "Winning the championship was no mean feet for such a young team.", "wrong": "feet", "fix": ["feat"], "id": "bkC2-68"}, {"type": "choose", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Escolha o termo correto em cada caso.", "explain": "Minimizar algo grave é understatement; exagerar algo pequeno é hipérbole.", "prompt": "Calling a three-day power cut 'slightly inconvenient' is an example of [understatement*/hyperbole], whereas calling a short queue 'endless' is [hyperbole*/litotes].", "id": "bkC2-69"}, {"type": "mcq", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Escolha a opção que completa a frase.", "explain": "Após \"Not until...\" no início, a oração principal exige inversão com auxiliar: did + sujeito + verbo.", "prompt": "Not until the audit was completed ___ the extent of the fraud.", "options": ["the board realized", "the board did realize", "did the board realize", "realized the board"], "correctIndex": 2, "id": "bkC2-70"}, {"type": "choose", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Escolha a forma correta em cada caso.", "explain": "Inversão condicional com \"Had\"; a pseudo-cleft com \"What\" leva verbo no singular.", "prompt": "[Had*/Would] I known about the strike, I [would have*/had] taken an earlier train. What I needed [was*/were] more time.", "id": "bkC2-71"}, {"type": "error", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Encontre o erro na inversão.", "explain": "Com \"Little\" no início, é obrigatória a inversão: \"Little did they know\".", "sentence": "Little they knew that the manuscript would later sell for millions.", "wrong": "they knew", "fix": ["did they know"], "id": "bkC2-72"}, {"type": "error", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Encontre o erro na frase clivada.", "explain": "Na cleft \"It was only when... that\", a oração após \"that\" tem ordem normal, sem inversão.", "sentence": "It was only when the lights went out that did we notice the smell of smoke.", "wrong": "did we notice", "fix": ["we noticed"], "id": "bkC2-73"}, {"type": "rewrite", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Reescreva com inversão, começando com \"Rarely\".", "explain": "Advérbio negativo no início exige auxiliar antes do sujeito: \"Rarely do we see\".", "prompt": "We rarely see such dedication.", "start": "Rarely", "accept": ["Rarely do we see such dedication."], "id": "bkC2-74"}, {"type": "rewrite", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Transforme em pseudo-cleft, começando com \"What bothers me most\".", "explain": "A pseudo-cleft \"What... is...\" coloca em destaque a informação final.", "prompt": "The noise from the construction site bothers me most.", "start": "What bothers me most", "accept": ["What bothers me most is the noise from the construction site."], "id": "bkC2-75"}, {"type": "order", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Ordene as palavras formando uma frase com inversão, começando por \"So\".", "explain": "\"So + adjetivo\" no início provoca inversão: \"So complex was the problem that...\".", "words": ["So", "complex", "was", "the", "problem", "that", "nobody", "could", "solve", "it"], "id": "bkC2-76"}, {"type": "gaps", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Complete o diálogo com uma palavra em cada lacuna.", "explain": "\"I expect so\" substitui a oração; \"neither have I\" repete o auxiliar com inversão.", "prompt": "A: Will the committee approve the budget?\nB: I expect ___, though the chair might not.\nA: Has Paulo told the treasurer?\nB: He hasn't, and neither ___ I.", "answers": [["so"], ["have"]], "id": "bkC2-77"}, {"type": "tf", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "A cleft destaca a cor; \"so do many tourists\" é elipse; \"Were the council to\" é condição hipotética.", "text": "Seldom has a building divided a city as much as the new concert hall in Salvador. What critics object to is not its size but its color: a bright orange that, they say, clashes with the colonial houses nearby. Supporters believe that the hall has brought energy to the area, and so do many tourists. Were the council to repaint it, the architect would remove her name from the project.", "items": [{"s": "Critics mainly object to the size of the building.", "a": false}, {"s": "Many tourists share the supporters' view.", "a": true}, {"s": "The council has already repainted the building.", "a": false}, {"s": "The architect might withdraw her name if the building were repainted.", "a": true}], "id": "bkC2-78"}, {"type": "match", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Ligue as metades para formar frases completas.", "explain": "Cada início com inversão exige um complemento específico: only after... did, such... that, should..., not only... but.", "left": ["Only after the results were published", "Such was the demand", "Should you need further help,", "Not only did she win the race,"], "right": ["but she also broke the record.", "please contact our office.", "did the scandal come to light.", "that tickets sold out in minutes."], "correctMap": [2, 3, 1, 0], "id": "bkC2-79"}, {"type": "mcq", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Escolha a expressão idiomática que completa a frase.", "explain": "\"Bury the hatchet\" = fazer as pazes, encerrar uma rivalidade.", "prompt": "After months of bitter negotiation, the two partners agreed to ___ and start afresh.", "options": ["bury the hatchet", "spill the beans", "jump the gun", "pass the buck"], "correctIndex": 0, "id": "bkC2-80"}, {"type": "mcq", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Qual paráfrase formal mantém o sentido da frase?", "explain": "\"Up in the air\" = ainda indefinido; \"has yet to be determined\" é o equivalente formal.", "prompt": "The launch date is still up in the air.", "options": ["The launch date has been cancelled.", "The launch date has been widely publicized.", "The launch date has yet to be determined.", "The launch date has been brought forward."], "correctIndex": 2, "id": "bkC2-81"}, {"type": "mcq", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Qual expressão significa revelar um segredo sem querer?", "explain": "\"Let the cat out of the bag\" = deixar escapar um segredo.", "prompt": "Which idiom means to reveal a secret by accident?", "options": ["hit the sack", "face the music", "break a leg", "let the cat out of the bag"], "correctIndex": 3, "id": "bkC2-82"}, {"type": "odd", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Qual expressão NÃO significa \"muito fácil\"?", "explain": "\"An uphill battle\" = uma luta difícil; as outras indicam facilidade.", "prompt": "Which expression does not mean \"very easy\"?", "options": ["a walk in the park", "an uphill battle", "child's play", "plain sailing"], "correctIndex": 1, "id": "bkC2-83"}, {"type": "odd", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Qual frase NÃO cabe numa carta formal de reclamação?", "explain": "\"A total rip-off\" é gíria; as outras são fórmulas formais.", "prompt": "Which sentence would not suit a formal letter of complaint?", "options": ["I wish to draw your attention to this matter.", "I would appreciate a prompt response.", "This is a total rip-off.", "I trust this matter will be resolved."], "correctIndex": 2, "id": "bkC2-84"}, {"type": "choose", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Escolha as opções adequadas a uma mensagem informal a um amigo.", "explain": "\"Wiped out\" (exausto) e \"rain check\" (fica para outra vez) são informais.", "prompt": "Text to a close friend: Can't make it tonight, I'm [utterly fatigued/wiped out*]. [Rain check*/Postponement requested]?", "id": "bkC2-85"}, {"type": "choose", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Escolha as opções adequadas a um comunicado formal.", "explain": "Numa comunicação formal evitam-se idioms coloquiais como \"chew over\" e \"let you know what's what\".", "prompt": "The committee has [given the matter careful consideration*/chewed it over] and will [make its decision known*/let you know what's what] in due course.", "id": "bkC2-86"}, {"type": "error", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Encontre o trecho informal demais para esta carta.", "explain": "\"Touch base with\" é jargão informal; numa carta formal use \"contact\".", "sentence": "We would be grateful if you could touch base with our legal department at your earliest convenience.", "wrong": "touch base with", "fix": ["contact", "liaise with", "get in touch with", "consult"], "id": "bkC2-87"}, {"type": "error", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Encontre o erro na expressão idiomática.", "explain": "A expressão fixa é \"cross that bridge when we come to it\".", "sentence": "Don't worry about the budget meeting; we'll cross that bridge when we come on it.", "wrong": "come on", "fix": ["come to"], "id": "bkC2-88"}, {"type": "match", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Ligue cada expressão idiomática ao seu significado.", "explain": "Idioms têm sentido figurado fixo, que não se deduz das palavras isoladas.", "left": ["to go back to the drawing board", "to bite off more than you can chew", "to be on the same page", "to throw in the towel", "to take something with a pinch of salt"], "right": ["to give up", "to start planning again from the beginning", "not to believe something completely", "to take on more than you can manage", "to share the same understanding"], "correctMap": [1, 3, 4, 0, 2], "id": "bkC2-89"}, {"type": "match", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Ligue cada frase informal ao seu equivalente formal.", "explain": "Cada par expressa a mesma ideia; o formal usa vocabulário mais neutro e completo.", "left": ["Thanks a bunch!", "Sorry for the mix-up.", "Let me know what you think.", "Hang on a sec."], "right": ["I would welcome your feedback.", "Please hold for a moment.", "Thank you very much indeed.", "We apologize for the misunderstanding."], "correctMap": [2, 3, 0, 1], "id": "bkC2-90"}, {"type": "sort", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Classifique as expressões pelo sentido.", "explain": "Hit the jackpot, come up trumps, pay off e strike gold indicam êxito; as outras, fracasso.", "prompt": "Sort the expressions into Success and Failure.", "groups": ["Sucesso", "Fracasso"], "items": [{"w": "hit the jackpot", "g": 0}, {"w": "go down in flames", "g": 1}, {"w": "come up trumps", "g": 0}, {"w": "go belly up", "g": 1}, {"w": "fall through", "g": 1}, {"w": "pay off", "g": 0}, {"w": "be a flop", "g": 1}, {"w": "strike gold", "g": 0}], "id": "bkC2-91"}, {"type": "sort", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Classifique saudações e despedidas por registro.", "explain": "Fórmulas como \"To whom it may concern\" e \"Yours sincerely\" são de cartas formais.", "prompt": "Sort the greetings and closings into Formal and Informal.", "groups": ["Formal", "Informal"], "items": [{"w": "Hi there!", "g": 1}, {"w": "To whom it may concern", "g": 0}, {"w": "Take care!", "g": 1}, {"w": "Respectfully yours", "g": 0}, {"w": "Hey guys", "g": 1}, {"w": "Yours sincerely", "g": 0}, {"w": "Talk soon!", "g": 1}, {"w": "Dear Professor Almeida", "g": 0}], "id": "bkC2-92"}, {"type": "tf", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Luana se assustou com \"break a leg\"; o show foi um sucesso e ela entendeu o segundo elogio.", "text": "Before her first theater performance in Dublin, Luana, an exchange student from Fortaleza, was alarmed when a classmate told her to 'break a leg'. Her director explained that the phrase simply means 'good luck' and that many actors consider it unlucky to say 'good luck' directly. After the show, which was a hit, the same classmate said she had 'knocked it out of the park'. This time, Luana understood the compliment immediately.", "items": [{"s": "At first, Luana took the expression literally.", "a": true}, {"s": "Many actors avoid saying \"good luck\" directly.", "a": true}, {"s": "The show was unsuccessful.", "a": false}, {"s": "Luana also misunderstood the second idiom.", "a": false}], "id": "bkC2-93"}, {"type": "reading", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Leia o e-mail e responda às perguntas.", "explain": "\"In the bag\" = garantido; \"a tall order\" = difícil; o tom geral é informal e amigável.", "text": "Hi team, quick update. The Recife deal is in the bag: the client signed yesterday. Hats off to Bruno, who went above and beyond to close it. That said, we can't rest on our laurels, as the Q3 targets are still a tall order. Let's put our heads together on Monday and figure out a plan. Cheers, Helena", "questions": [{"q": "What does 'in the bag' mean here?", "options": ["The documents are lost.", "The deal is secured.", "The deal is still under review."], "correctIndex": 1}, {"q": "What does Helena say about the Q3 targets?", "options": ["They will be hard to achieve.", "They have already been met.", "They were set by Bruno."], "correctIndex": 0}, {"q": "How would you describe the register of the email?", "options": ["Highly formal and legal", "Academic and impersonal", "Informal and friendly"], "correctIndex": 2}], "id": "bkC2-94"}, {"type": "reading", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Leia o aviso e responda às perguntas.", "explain": "O aviso é formal: \"until further notice\" = sem data para terminar; gíria como \"folks\" destoaria.", "text": "Notice to residents: Owing to unforeseen circumstances, the renovation of the east wing has been suspended until further notice. Residents are kindly requested to refrain from using the east staircase, which remains unsafe. The management wishes to thank all residents for their patience and cooperation.", "questions": [{"q": "What does 'until further notice' mean?", "options": ["for exactly one more week", "until the residents complain", "with no end date announced yet"], "correctIndex": 2}, {"q": "What are residents asked to do?", "options": ["avoid the east staircase", "help with the renovation", "move to the east wing"], "correctIndex": 0}, {"q": "Which sentence would be LEAST appropriate to add to this notice?", "options": ["We apologize for any inconvenience.", "Sorry, folks, it's a real pain, we know!", "Further updates will be posted in the lobby."], "correctIndex": 1}], "id": "bkC2-95"}, {"type": "gaps", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Complete o texto com as palavras do banco.", "explain": "Idioms fixos: burn the midnight oil, give the green light, over the moon, let one's hair down.", "prompt": "Carlos had been burning the ___ oil for weeks to finish his thesis. When his supervisor finally gave it the green ___, he was over the ___. His friends told him he deserved to let his ___ down for a while.", "answers": [["midnight"], ["light"], ["moon"], ["hair"]], "bank": ["midnight", "light", "moon", "hair", "sun", "head"], "id": "bkC2-96"}, {"type": "rewrite", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Reescreva a frase em registro formal, começando como indicado.", "explain": "\"We regret that we are unable to\" é a fórmula formal para recusar algo.", "prompt": "Sorry, but we can't give you a refund.", "start": "We regret that we are unable", "accept": ["We regret that we are unable to give you a refund.", "We regret that we are unable to offer you a refund.", "We regret that we are unable to provide you with a refund.", "We regret that we are unable to refund you.", "We regret that we are unable to issue a refund.", "We regret that we are unable to issue you a refund.", "We regret that we are unable to provide a refund.", "We regret that we are unable to offer a refund."], "id": "bkC2-97"}, {"type": "dorder", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Coloque o diálogo na ordem correta.", "explain": "\"On the fence\" (indeciso) leva a \"What's holding you back?\"; a sugestão de testar vem antes da resposta final.", "lines": ["A: I heard you're thinking of quitting your job to open a café in Paraty.", "B: Yes, but I'm still on the fence about it.", "A: What's holding you back?", "B: Mostly money. It would mean putting all my eggs in one basket.", "A: Why not test the waters first with a weekend food stall?", "B: That's not a bad idea. I could see if it works before taking the plunge."], "id": "bkC2-98"}, {"type": "order", "level": "C2", "topic": "Expressões idiomáticas e registro formal x informal", "instruction": "Ordene as palavras para formar a frase.", "explain": "\"Take the bull by the horns\" = enfrentar um problema de frente.", "words": ["She", "decided", "to", "take", "the", "bull", "by", "the", "horns"], "id": "bkC2-99"}, {"type": "mcq", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Escolha a palavra que completa a frase com precisão.", "explain": "\"Continuous\" = sem interrupção; \"continual\" = repetido, com pausas.", "prompt": "The river's ___ flow powers the mill day and night without a single break.", "options": ["continuous", "continual", "contiguous", "consecutive"], "correctIndex": 0, "id": "bkC2-100"}, {"type": "mcq", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Escolha a palavra que completa a frase com precisão.", "explain": "\"Historic\" = marcante, que faz história; \"historical\" = relativo ao passado.", "prompt": "The signing of the peace treaty was a ___ moment for both nations.", "options": ["historical", "hysterical", "historic", "histrionic"], "correctIndex": 2, "id": "bkC2-101"}, {"type": "mcq", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Qual frase é ambígua?", "explain": "\"Visiting relatives\" pode ser \"visitar parentes\" ou \"parentes que visitam\".", "prompt": "Which sentence is ambiguous?", "options": ["Relatives who visit us can be boring.", "Visiting relatives can be boring.", "Going to visit relatives can be boring.", "Relatives visiting us can be boring."], "correctIndex": 1, "id": "bkC2-102"}, {"type": "odd", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Qual palavra NÃO descreve alguém que fala pouco?", "explain": "\"Garrulous\" = tagarela; taciturn, reticent e laconic indicam poucas palavras.", "prompt": "Which word does not describe a person of few words?", "options": ["taciturn", "reticent", "laconic", "garrulous"], "correctIndex": 3, "id": "bkC2-103"}, {"type": "odd", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Qual palavra NÃO tem conotação negativa?", "explain": "\"Slender\" (esbelto) é elogio; scrawny, gaunt e emaciated sugerem magreza excessiva.", "prompt": "Which word has no negative connotation?", "options": ["slender", "scrawny", "gaunt", "emaciated"], "correctIndex": 0, "id": "bkC2-104"}, {"type": "choose", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Escolha a forma correta em cada par de confusão comum.", "explain": "\"Fewer\" com contáveis (applicants); \"loath\" = relutante (adjetivo); \"loathe\" = detestar (verbo).", "prompt": "[Fewer*/Less] applicants met the criteria this year, but the panel was [loath*/loathe] to lower its standards.", "id": "bkC2-105"}, {"type": "choose", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Escolha a palavra correta em cada grupo.", "explain": "\"Eminent\" = ilustre; \"imminent\" = prestes a acontecer.", "prompt": "An [eminent*/imminent] physicist warned of an [imminent*/eminent] crisis in research funding.", "id": "bkC2-106"}, {"type": "error", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Encontre a palavra usada com sentido errado.", "explain": "\"Adverse\" = desfavorável; para \"avesso a\" use \"averse to\".", "sentence": "The new manager was adverse to any change in the company's routine.", "wrong": "adverse", "fix": ["averse", "opposed", "resistant", "hostile"], "id": "bkC2-107"}, {"type": "error", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Encontre a palavra usada com sentido errado.", "explain": "\"Militate against\" = dificultar; \"mitigate\" = atenuar e não se usa com \"against\".", "sentence": "Several factors mitigate against the plan's success, including cost and timing.", "wrong": "mitigate", "fix": ["militate", "work", "count"], "id": "bkC2-108"}, {"type": "match", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Ligue cada palavra ao seu significado.", "explain": "Pares parecidos com sentidos distintos: discreet/discrete, venal/venial, ingenuous/ingenious.", "left": ["discreet", "discrete", "venal", "venial", "ingenuous"], "right": ["open to bribery", "innocent and trusting", "careful not to attract attention", "minor and forgivable", "separate and distinct"], "correctMap": [2, 4, 0, 3, 1], "id": "bkC2-109"}, {"type": "match", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Ligue cada manchete ambígua à sua interpretação pretendida.", "explain": "Manchetes omitem palavras e geram duplo sentido; o contexto indica a leitura pretendida.", "left": ["Police help dog bite victim", "Kids make nutritious snacks", "Man eating piranha sold as pet", "Stolen painting found by tree"], "right": ["Children prepare healthy snacks.", "A stolen painting was discovered next to a tree.", "A piranha that attacks people was sold as a pet.", "Officers assisted someone a dog had bitten."], "correctMap": [3, 0, 2, 1], "id": "bkC2-110"}, {"type": "sort", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Classifique as palavras pela conotação.", "explain": "Flexible, open-minded, adaptable e pragmatic elogiam; fickle, wishy-washy, spineless e capricious criticam.", "prompt": "Sort the words describing a person who changes opinions: praise or criticism.", "groups": ["Elogio", "Crítica"], "items": [{"w": "flexible", "g": 0}, {"w": "fickle", "g": 1}, {"w": "open-minded", "g": 0}, {"w": "wishy-washy", "g": 1}, {"w": "adaptable", "g": 0}, {"w": "spineless", "g": 1}, {"w": "pragmatic", "g": 0}, {"w": "capricious", "g": 1}], "id": "bkC2-111"}, {"type": "sort", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Classifique as frases: ambígua ou não ambígua.", "explain": "Frases ambíguas admitem duas estruturas (ex.: \"hunting dogs\" = cães de caça ou caçando cães).", "prompt": "Sort the sentences into ambiguous and unambiguous.", "groups": ["Ambígua", "Não ambígua"], "items": [{"w": "Flying planes can be dangerous.", "g": 0}, {"w": "The chicken is ready to eat.", "g": 0}, {"w": "She saw her duck.", "g": 0}, {"w": "They are hunting dogs.", "g": 0}, {"w": "The report was published last week.", "g": 1}, {"w": "He sold his old car to a neighbor.", "g": 1}, {"w": "The chef is ready to serve dinner.", "g": 1}, {"w": "Pilots who fly small planes face many risks.", "g": 1}], "id": "bkC2-112"}, {"type": "tf", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Beatriz quis dizer \"possivelmente\"; o editor é americano e ela trocou \"eventually\" por \"if necessary\".", "text": "When Beatriz began translating corporate reports from Portuguese, she wrote that the company would 'eventually' review its prices, meaning 'possibly, if necessary'. Her American editor pointed out that 'eventually' means 'in the end, after some time', which suggested that a review was certain. Beatriz changed it to 'if necessary'. She now keeps a list of such false friends, including 'pretend' and 'actually'.", "items": [{"s": "Beatriz intended to express possibility, not certainty.", "a": true}, {"s": "The editor thought Beatriz's wording made the review sound certain.", "a": true}, {"s": "Beatriz replaced 'eventually' with 'actually'.", "a": false}, {"s": "Beatriz's editor was Brazilian.", "a": false}], "id": "bkC2-113"}, {"type": "reading", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Leia o texto e responda às perguntas.", "explain": "\"Biweekly\" pode significar duas vezes por semana ou a cada duas semanas; por isso é evitado.", "text": "When a Belém-based magazine announced that it would become 'biweekly', subscribers were confused. Some expected two issues a week; others, one issue every two weeks. Both readings are listed in dictionaries, which is why many editors advise avoiding the word altogether. The publisher later clarified that the magazine would appear every other week. The style guide now recommends phrases such as 'twice a week' or 'every two weeks', depending on the meaning.", "questions": [{"q": "Why were subscribers confused?", "options": ["'Biweekly' has two accepted meanings.", "The magazine changed its name.", "The announcement was written in Portuguese."], "correctIndex": 0}, {"q": "How often does the magazine now appear?", "options": ["Twice a week", "Once every two weeks", "Once a month"], "correctIndex": 1}, {"q": "What does the style guide recommend?", "options": ["Using 'biweekly' only in headlines", "Defining 'biweekly' in a footnote", "Replacing 'biweekly' with a clearer phrase"], "correctIndex": 2}], "id": "bkC2-114"}, {"type": "reading", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Leia o texto e responda às perguntas.", "explain": "\"Nonplussed\" tradicionalmente = perplexo; o uso novo (impassível) é quase o oposto.", "text": "In a staff meeting in Campinas, the director said the new schedule had left her 'nonplussed'. Half of the team thought she was calm and unbothered; the other half thought she was confused. Traditionally, 'nonplussed' means 'so surprised that one does not know how to react', but in North America it is increasingly used to mean 'unfazed'. Because the two senses are almost opposite, careful writers often choose a clearer word such as 'baffled' or 'unfazed'.", "questions": [{"q": "What is the traditional meaning of 'nonplussed'?", "options": ["calm", "perplexed", "angry"], "correctIndex": 1}, {"q": "Why do careful writers avoid the word?", "options": ["It is too informal.", "It is rarely used in North America.", "Its two senses are nearly opposite."], "correctIndex": 2}], "id": "bkC2-115"}, {"type": "gaps", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Complete o texto com as palavras do banco.", "explain": "Equivocal = de duplo sentido; evasive = que se esquiva; tactless = sem tato; ambivalent = dividido.", "prompt": "The mayor's speech was carefully ___: every sentence was open to two readings. When pressed on the budget, she was ___, changing the subject whenever possible. Her opponent, by contrast, was blunt to the point of being ___. Voters, with mixed feelings about both, remained ___.", "answers": [["equivocal"], ["evasive"], ["tactless"], ["ambivalent"]], "bank": ["equivocal", "evasive", "tactless", "ambivalent", "ambitious", "eloquent"], "id": "bkC2-116"}, {"type": "rewrite", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Reescreva para deixar claro que a declaração foi feita na segunda-feira.", "explain": "Levar \"On Monday\" para o início elimina a dúvida: ele modifica \"said\", não \"grade\".", "prompt": "The professor said on Monday she would grade the essays.", "start": "On Monday, the professor said", "accept": ["On Monday, the professor said she would grade the essays.", "On Monday, the professor said that she would grade the essays."], "id": "bkC2-117"}, {"type": "dorder", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A dúvida sobre \"moved forward\" (antecipar ou adiar) surge e é explicada antes da decisão de perguntar.", "lines": ["A: Did you see the email saying the meeting has been moved forward a day?", "B: Yes. So is it on Wednesday now, or Friday?", "A: What do you mean? It was on Thursday, so it's Wednesday.", "B: Not necessarily. Some people use 'move forward' to mean 'postpone'.", "A: Seriously? Then I'd better ask Carla which day she meant."], "id": "bkC2-118"}, {"type": "order", "level": "C2", "topic": "Nuance lexical e ambiguidade", "instruction": "Ordene as palavras para formar a frase.", "explain": "Childlike (inocência, positivo) x childish (imaturidade, negativo).", "words": ["Childlike", "suggests", "innocence", "whereas", "childish", "suggests", "immaturity"], "alt": ["Childish suggests immaturity whereas childlike suggests innocence", "Whereas childish suggests immaturity childlike suggests innocence", "Whereas childlike suggests innocence childish suggests immaturity"], "id": "bkC2-119"}, {"type": "mcq", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Escolha o verbo que atenua a afirmação.", "explain": "\"Point to\" (indicar) é cauteloso; prove, establish e confirm expressam certeza.", "prompt": "The survey data ___ a link between long commutes and stress.", "options": ["point to", "prove", "establish", "confirm"], "correctIndex": 0, "id": "bkC2-120"}, {"type": "mcq", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Qual frase tem hedging EXCESSIVO (cautelosa demais)?", "explain": "Empilhar might, possibly, could e perhaps esvazia a afirmação.", "prompt": "Which sentence is over-hedged?", "options": ["The results indicate a slight upward trend.", "The results appear to indicate a slight upward trend.", "The results may indicate a slight upward trend.", "It might possibly be suggested that the results could perhaps indicate a slight trend."], "correctIndex": 3, "id": "bkC2-121"}, {"type": "mcq", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Qual é a melhor versão atenuada de \"Bilingual children are better at multitasking\"?", "explain": "\"May\" e \"under certain conditions\" limitam a generalização sem anular a ideia.", "prompt": "Choose the appropriately hedged version.", "options": ["Bilingual children are always better at multitasking.", "It is a fact that bilingual children multitask better.", "Bilingual children may, under certain conditions, perform better at multitasking.", "Bilingual children are clearly the best at multitasking."], "correctIndex": 2, "id": "bkC2-122"}, {"type": "odd", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Qual expressão NÃO é um hedge?", "explain": "\"It is indisputable that\" reforça a certeza (booster); as outras atenuam.", "prompt": "Which expression is not a hedge?", "options": ["there is some evidence that", "it is indisputable that", "it would seem that", "it is plausible that"], "correctIndex": 1, "id": "bkC2-123"}, {"type": "odd", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Qual advérbio NÃO atenua uma afirmação?", "explain": "\"Definitively\" expressa certeza; presumably, conceivably e apparently atenuam.", "prompt": "Which adverb does not soften a claim?", "options": ["presumably", "conceivably", "apparently", "definitively"], "correctIndex": 3, "id": "bkC2-124"}, {"type": "choose", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Escolha as opções mais cautelosas, típicas da escrita acadêmica.", "explain": "\"Would seem\", \"may\" e \"at least in part\" limitam a força da afirmação.", "prompt": "Our findings [would seem*/definitely seem] to indicate that urban gardens [may*/must] improve residents' well-being, [at least in part*/without exception].", "id": "bkC2-125"}, {"type": "choose", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Escolha as opções com o grau de certeza adequado a um artigo.", "explain": "\"It is likely\" e \"in part\" apresentam a causa como provável e parcial.", "prompt": "It [is likely*/is certain] that the decline in bee populations is [attributable in part*/entirely attributable] to pesticide use.", "id": "bkC2-126"}, {"type": "error", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Encontre a palavra que contradiz o tom cauteloso da frase.", "explain": "\"Conclusively\" (booster) choca com \"suggests\" e \"may\"; use \"tentatively\" ou \"strongly\".", "sentence": "The evidence conclusively suggests that remote learning may have widened inequality.", "wrong": "conclusively", "fix": ["tentatively", "strongly", ""], "id": "bkC2-127"}, {"type": "error", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Encontre a palavra que contradiz o tom cauteloso da frase.", "explain": "\"It could be argued\" pede cautela; \"undeniably\" é um booster. Use \"partly\" ou \"largely\".", "sentence": "It could be argued that the policy is undeniably responsible for the drop in crime.", "wrong": "undeniably", "fix": ["partly", "largely", "partially", "at least partly", "at least partially", ""], "id": "bkC2-128"}, {"type": "match", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Ligue cada afirmação exagerada à sua versão atenuada.", "explain": "Cada versão atenuada mantém a ideia central, mas reduz a certeza ou o alcance.", "left": ["This proves the theory.", "Diet causes the disease.", "All users prefer the new design.", "The effect is permanent."], "right": ["Most users appear to prefer the new design.", "This lends support to the theory.", "The effect seems to be long-lasting.", "Diet may contribute to the disease."], "correctMap": [1, 3, 0, 2], "id": "bkC2-129"}, {"type": "match", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Ligue as metades das frases acadêmicas.", "explain": "São fórmulas fixas de cautela: broadly consistent with, interpreted with caution, unclear whether, to the best of our knowledge.", "left": ["The data are broadly consistent", "These results should be interpreted", "It remains unclear whether", "To the best of our knowledge,"], "right": ["this is the first study of its kind.", "the effect is causal.", "with previous findings.", "with caution."], "correctMap": [2, 3, 1, 0], "id": "bkC2-130"}, {"type": "sort", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Classifique os trechos: cauteloso ou categórico demais.", "explain": "Tentatively, possible, partly e reasonable to assume atenuam; os demais afirmam certeza absoluta.", "prompt": "Sort the phrases into cautious and overconfident.", "groups": ["Cautelosa (hedged)", "Categórica demais"], "items": [{"w": "the findings tentatively suggest", "g": 0}, {"w": "this settles the question once and for all", "g": 1}, {"w": "a possible explanation is", "g": 0}, {"w": "there can be no doubt that", "g": 1}, {"w": "may partly account for", "g": 0}, {"w": "it is self-evident that", "g": 1}, {"w": "it is reasonable to assume that", "g": 0}, {"w": "proves conclusively", "g": 1}], "id": "bkC2-131"}, {"type": "tf", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Os revisores pediram cautela porque só havia dois locais testados; Nunes brincou que a revisão salvou sua reputação.", "text": "In a conference talk in Florianópolis, Dr. Paula Nunes described how her team revised a paper after peer review. The first draft claimed that a coastal plant 'eliminates' soil erosion. Reviewers asked for more cautious wording, since the plant had been tested at only two sites. The published version states that the plant 'appears to reduce erosion considerably at the sites studied'. Nunes joked that the revision had cost her a week but saved her reputation.", "items": [{"s": "The reviewers objected to overconfident wording.", "a": true}, {"s": "The plant had been tested at many different sites.", "a": false}, {"s": "The published version limits the claim to the sites studied.", "a": true}, {"s": "Nunes regretted making the changes.", "a": false}], "id": "bkC2-132"}, {"type": "tf", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O texto defende calibrar: combinar hedges e boosters conforme a força das evidências.", "text": "Hedging is sometimes misunderstood as avoiding commitment altogether. In fact, skilled academic writers combine hedges with boosters, strengthening claims supported by robust evidence and softening those that are speculative. A paper that hedges every sentence can appear to lack a position, while one that hedges nothing may seem naive. The goal, therefore, is calibration: matching the strength of each claim to the strength of the evidence.", "items": [{"s": "Skilled writers never use boosters.", "a": false}, {"s": "Hedging every sentence may make a writer seem to have no position.", "a": true}, {"s": "The text recommends matching the strength of a claim to the evidence.", "a": true}, {"s": "According to the text, a paper without hedges may seem sophisticated.", "a": false}], "id": "bkC2-133"}, {"type": "reading", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Leia o parecer do revisor e responda às perguntas.", "explain": "O revisor critica a conclusão exagerada, cita a falta de grupo de controle e sugere \"preliminary\".", "text": "Reviewer 2: The manuscript reports that a mindfulness app reduced stress among 58 nurses in Porto Alegre. While the results are encouraging, the conclusion that the app 'will transform mental health care in hospitals' is not warranted by the data. The study lacked a control group, so it is difficult to rule out a placebo effect. I would recommend that the authors describe the findings as 'preliminary' and propose a randomized trial as a next step.", "questions": [{"q": "What is the reviewer's main criticism?", "options": ["The app was poorly designed.", "The conclusion overstates the evidence.", "The sample included the wrong profession."], "correctIndex": 1}, {"q": "Why is it difficult to rule out a placebo effect?", "options": ["The nurses knew the researchers.", "The study lasted too long.", "There was no control group."], "correctIndex": 2}, {"q": "Which word does the reviewer suggest the authors use?", "options": ["preliminary", "transformative", "conclusive"], "correctIndex": 0}], "id": "bkC2-134"}, {"type": "reading", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Leia o trecho de discussão e responda às perguntas.", "explain": "\"Likely\", \"conceivable\" e \"seems\" mostram confiança moderada; \"Admittedly\" introduz a limitação.", "text": "Taken together, our results suggest that the decline in bird species in the Pantanal is likely linked to changes in water levels rather than to tourism. Admittedly, tourism data were available for only three of the seven years studied, and it is therefore conceivable that its effect has been underestimated. Nevertheless, the strong correlation with water levels observed in every year seems difficult to explain by chance alone.", "questions": [{"q": "How certain are the authors about the cause of the decline?", "options": ["Fairly confident, but not certain", "Completely certain", "They offer no view"], "correctIndex": 0}, {"q": "What limitation do they acknowledge?", "options": ["A small number of bird species", "Missing water-level data", "Incomplete tourism data"], "correctIndex": 2}, {"q": "Which word introduces the concession of a weakness?", "options": ["Nevertheless", "Admittedly", "Taken together"], "correctIndex": 1}], "id": "bkC2-135"}, {"type": "gaps", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Complete o texto com as palavras do banco.", "explain": "Appear to, plausible explanation, remain tentative e advisable são escolhas cautelosas típicas.", "prompt": "Although the sample was small, the data ___ to indicate a clear pattern. One ___ explanation is that participants knew they were being observed. Our conclusions must therefore remain ___, and further studies would be ___.", "answers": [["appear", "seem"], ["plausible", "possible"], ["tentative"], ["advisable"]], "bank": ["appear", "plausible", "tentative", "advisable", "proven", "invariably"], "id": "bkC2-136"}, {"type": "rewrite", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Reescreva a afirmação de forma atenuada, começando como indicado.", "explain": "\"Appears to\" transforma uma certeza em uma afirmação cautelosa.", "prompt": "Stress causes insomnia.", "start": "Stress appears to", "accept": ["Stress appears to cause insomnia.", "Stress appears to contribute to insomnia.", "Stress appears to lead to insomnia.", "Stress appears to be a cause of insomnia.", "Stress appears to be linked to insomnia.", "Stress appears to be associated with insomnia."], "id": "bkC2-137"}, {"type": "dorder", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Coloque o diálogo na ordem correta.", "explain": "O orientador questiona a causalidade, sugere \"associated with\" e depois orienta sobre as explicações.", "lines": ["A: Professor, can I write that screen time causes poor grades?", "B: Do your data show causation, or just a correlation?", "A: Just a correlation, I suppose. Students who spent more time on screens had lower grades.", "B: Then say that higher screen time is associated with lower grades.", "A: Should I suggest possible reasons too?", "B: Yes, but present them as possibilities, not facts."], "id": "bkC2-138"}, {"type": "order", "level": "C2", "topic": "Hedging acadêmico", "instruction": "Ordene as palavras para formar a frase.", "explain": "\"A degree of caution\" é uma expressão típica de hedging acadêmico.", "words": ["These", "findings", "should", "be", "interpreted", "with", "a", "degree", "of", "caution"], "id": "bkC2-139"}, {"type": "mcq", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Qual frase NÃO contém redundância?", "explain": "\"Two twins\", \"repeat again\" e \"plan ahead in advance\" são pleonasmos.", "prompt": "Which sentence contains no redundancy?", "options": ["The two twins look exactly alike.", "Could you repeat that again?", "She returned the book yesterday.", "We need to plan ahead in advance."], "correctIndex": 2, "id": "bkC2-140"}, {"type": "mcq", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Escolha a versão mais concisa.", "explain": "\"Near\" substitui \"in close proximity to\" sem perda de sentido.", "prompt": "The hotel is located in close proximity to the beach.", "options": ["The hotel is near the beach.", "The hotel is located in proximity near the beach.", "The hotel is situated in a location close to the beach.", "The hotel is located close in proximity to the beach."], "correctIndex": 0, "id": "bkC2-141"}, {"type": "mcq", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Qual revisão elimina TODA a redundância?", "explain": "Toda inovação é nova, e \"eliminate\" já significa remover completamente.", "prompt": "The new innovation will completely eliminate delays.", "options": ["The new innovation will eliminate delays.", "The innovation will eliminate delays.", "The innovation will completely eliminate delays.", "The new innovation will completely eliminate all delays."], "correctIndex": 1, "id": "bkC2-142"}, {"type": "odd", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Qual expressão NÃO é redundante?", "explain": "\"Annual budget\" é legítima; final outcome, advance warning e personal opinion são pleonasmos.", "prompt": "Which phrase is not redundant?", "options": ["final outcome", "advance warning", "personal opinion", "annual budget"], "correctIndex": 3, "id": "bkC2-143"}, {"type": "odd", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Qual expressão verbal NÃO é redundante?", "explain": "\"Return home\" é legítima; revert back, ascend up e descend down repetem a direção já contida no verbo.", "prompt": "Which verb phrase is not redundant?", "options": ["revert back", "return home", "ascend up", "descend down"], "correctIndex": 1, "id": "bkC2-144"}, {"type": "choose", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Escolha as formas mais concisas.", "explain": "\"I think\" basta (sem \"In my opinion\"); focus on e essentials não precisam de reforço.", "prompt": "[I think*/In my opinion, I think] the report should [focus on*/focus on and concentrate on] the [essentials*/main essentials] of the case.", "id": "bkC2-145"}, {"type": "choose", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Escolha as formas mais concisas.", "explain": "\"Refer back\" e \"brief summary\" são redundantes; \"prior to... beforehand\" repete a ideia.", "prompt": "Please [refer*/refer back] to the attached [summary*/brief summary] [before the meeting*/prior to the meeting beforehand].", "id": "bkC2-146"}, {"type": "error", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Encontre a redundância na frase.", "explain": "\"Identical\" já é absoluto; \"exactly\" é desnecessário.", "sentence": "The results were exactly identical to those of the 2019 study.", "wrong": "exactly identical", "fix": ["identical"], "id": "bkC2-147"}, {"type": "error", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Encontre a redundância na frase.", "explain": "\"Continue\" já indica prosseguir; \"on\" é supérfluo.", "sentence": "Despite the heavy rain, the match continued on until nine o'clock.", "wrong": "continued on", "fix": ["continued", "went on", "carried on"], "id": "bkC2-148"}, {"type": "match", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Ligue cada expressão prolixa ao equivalente conciso.", "explain": "Expressões longas podem ser trocadas por uma palavra com o mesmo sentido.", "left": ["a large number of", "with regard to", "on a daily basis", "in order to", "prior to"], "right": ["before", "daily", "many", "to", "about"], "correctMap": [2, 4, 1, 3, 0], "id": "bkC2-149"}, {"type": "match", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Ligue cada pleonasmo à forma enxuta.", "explain": "O segundo elemento de cada pleonasmo repete uma ideia já contida no primeiro.", "left": ["advance planning", "join together", "sum total", "each individual person"], "right": ["each person", "total", "planning", "join"], "correctMap": [2, 3, 1, 0], "id": "bkC2-150"}, {"type": "sort", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Classifique as frases: redundante ou concisa.", "explain": "Plan ahead for the future, currently... at the moment, reason is because e cooperate together repetem ideias.", "prompt": "Sort the sentences into redundant and concise.", "groups": ["Redundante", "Concisa"], "items": [{"w": "We have to plan ahead for the future.", "g": 0}, {"w": "The figures show a clear trend.", "g": 1}, {"w": "She is currently working in Lisbon at the moment.", "g": 0}, {"w": "Repeat the question, please.", "g": 1}, {"w": "The reason is because the server crashed.", "g": 0}, {"w": "The server crashed, so we lost the data.", "g": 1}, {"w": "They cooperated together on the project.", "g": 0}, {"w": "It was a hot summer day.", "g": 1}], "id": "bkC2-151"}, {"type": "tf", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "A editora cortou palavras, não fatos; Tiago se incomodou no início, mas mudou seus hábitos.", "text": "Tiago, a junior copywriter in Porto Alegre, submitted a product description of 180 words. His editor cut it to 90 without removing a single fact. She deleted phrases such as 'completely free of charge' and 'each and every customer', and replaced 'in the event that' with 'if'. Tiago initially felt his work had been butchered, but sales rose after the shorter text went online. He now reviews every draft by asking whether each word earns its place.", "items": [{"s": "The editor removed some of the facts from the text.", "a": false}, {"s": "'In the event that' was replaced with a shorter word.", "a": true}, {"s": "Tiago was pleased with the edit at first.", "a": false}, {"s": "The experience changed the way Tiago reviews his drafts.", "a": true}], "id": "bkC2-152"}, {"type": "tf", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "As cartas antigas usavam fórmulas arcaicas; as novas ficaram só um pouco mais curtas, e as ligações caíram.", "text": "In 2019, a municipal office in Niterói rewrote its tax notices in plain language. The original letters were packed with phrases like 'it is hereby notified that' and 'the aforementioned taxpayer'. The new versions used short sentences and addressed readers as 'you'. Within a year, the number of phone calls asking for clarification fell by roughly a third, although the notices themselves became only slightly shorter.", "items": [{"s": "The original notices used old-fashioned formal phrases.", "a": true}, {"s": "The new notices were dramatically shorter than the old ones.", "a": false}, {"s": "Calls asking for clarification decreased after the change.", "a": true}], "id": "bkC2-153"}, {"type": "reading", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Leia o memorando e responda às perguntas.", "explain": "O objetivo é encurtar e-mails: ponto principal na primeira frase e documentos longos em anexo.", "text": "To all staff: Recent audits show that the average internal email at our company is 340 words long. Many messages begin with a paragraph of pleasantries and end by repeating the request. From next month, please put your main point in the first sentence and keep messages under 150 words where possible. Longer documents should be attached rather than pasted into the body of the email.", "questions": [{"q": "What is the main purpose of the memo?", "options": ["To make internal emails shorter and clearer", "To ban attachments", "To reduce the number of emails sent to clients"], "correctIndex": 0}, {"q": "Where should the main point of an email go?", "options": ["At the end, as a summary", "In the first sentence", "In an attachment"], "correctIndex": 1}, {"q": "What does the memo say about longer documents?", "options": ["They should be split into several emails.", "They are no longer allowed.", "They should be sent as attachments."], "correctIndex": 2}], "id": "bkC2-154"}, {"type": "reading", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Compare as duas versões e responda às perguntas.", "explain": "A versão B troca a passiva prolixa pela ativa e mantém toda a informação essencial.", "text": "Version A: 'In light of the fact that a significant proportion of the participants were not in attendance at the second session, it was decided by the researchers that the session would be repeated at a later point in time.' Version B: 'Because many participants missed the second session, the researchers repeated it later.'", "questions": [{"q": "What change does Version B make?", "options": ["It adds new information about the participants.", "It replaces a passive construction with an active one.", "It changes the researchers' decision."], "correctIndex": 1}, {"q": "Which phrase in Version A corresponds to 'because'?", "options": ["at a later point in time", "a significant proportion of", "In light of the fact that"], "correctIndex": 2}, {"q": "What essential information is lost in Version B?", "options": ["None", "The reason for repeating the session", "The fact that the session was repeated"], "correctIndex": 0}], "id": "bkC2-155"}, {"type": "gaps", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Complete com a forma concisa do banco que substitui a expressão entre parênteses.", "explain": "Is in a position to = can; in the near future = soon; with the exception of = except; on a weekly basis = weekly.", "prompt": "The new plant ___ (= is in a position to) produce 5,000 units a day. It will open ___ (= in the near future) to meet demand in the North. All states ___ (= with the exception of) Amapá will be supplied ___ (= on a weekly basis).", "answers": [["can"], ["soon"], ["except", "but", "apart from", "except for"], ["weekly"]], "bank": ["can", "soon", "except", "weekly", "since", "rarely"], "id": "bkC2-156"}, {"type": "rewrite", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Reescreva a frase de forma concisa, começando como indicado.", "explain": "\"The reason why... was because\" é redundante; basta \"He resigned because\".", "prompt": "The reason why he resigned was because he disagreed with the new policy.", "start": "He resigned because", "accept": ["He resigned because he disagreed with the new policy."], "id": "bkC2-157"}, {"type": "rewrite", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Elimine \"There are... who\", começando como indicado.", "explain": "A estrutura \"There are many X who...\" pode ser reduzida a \"Many X...\".", "prompt": "There are many tourists who visit Paraty every year.", "start": "Many tourists", "accept": ["Many tourists visit Paraty every year.", "Many tourists visit Paraty each year.", "Many tourists visit Paraty annually."], "id": "bkC2-158"}, {"type": "dorder", "level": "C2", "topic": "Concisão e redundância estilística", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pede revisão, B aponta a primeira redundância, A questiona e depois traz o segundo exemplo.", "lines": ["A: Could you look over my cover letter? It feels too long.", "B: Sure. Your first line says 'I am writing this letter to apply for'.", "A: What's wrong with that?", "B: They know it's a letter. Just write 'I am applying for'.", "A: Good point. What about 'in the month of June'?", "B: 'In June' says exactly the same thing."], "id": "bkC2-159"}, {"type": "mcq", "level": "C2", "topic": "Variação de registro", "instruction": "Qual resposta é adequada a um cliente que reclamou de atraso na entrega?", "explain": "Com clientes, usa-se registro formal e cortês; as demais soam descuidadas ou rudes.", "prompt": "Which reply is most appropriate?", "options": ["My bad, it happens!", "We sincerely apologize for the delay and have dispatched your order today.", "Chill, it's on its way.", "Whatever, we're doing our best."], "correctIndex": 1, "id": "bkC2-160"}, {"type": "mcq", "level": "C2", "topic": "Variação de registro", "instruction": "Qual frase é típica da fala informal?", "explain": "A fala informal usa elipse e deslocamento (\"Nice place, this\"); as outras são formais demais.", "prompt": "Which sentence is typical of informal spoken English?", "options": ["Nice place, this.", "This establishment is pleasant.", "The venue is well appointed.", "The premises are agreeable."], "correctIndex": 0, "id": "bkC2-161"}, {"type": "mcq", "level": "C2", "topic": "Variação de registro", "instruction": "Qual versão é adequada a um ensaio acadêmico?", "explain": "\"A considerable proportion\" e \"regards... as\" são formais; loads, heaps e tons são coloquiais.", "prompt": "Choose the version suitable for an academic essay.", "options": ["Loads of people reckon climate change is a big deal.", "Heaps of folks think climate change is huge.", "Tons of people are like, climate change is bad.", "A considerable proportion of the population regards climate change as a serious concern."], "correctIndex": 3, "id": "bkC2-162"}, {"type": "odd", "level": "C2", "topic": "Variação de registro", "instruction": "Qual palavra NÃO pertence ao mesmo registro das outras?", "explain": "\"Grab\" é informal; purchase, commence e terminate são formais.", "prompt": "Which word is not formal?", "options": ["purchase", "commence", "grab", "terminate"], "correctIndex": 2, "id": "bkC2-163"}, {"type": "odd", "level": "C2", "topic": "Variação de registro", "instruction": "Qual saudação NÃO é adequada para um e-mail a um professor que você não conhece?", "explain": "\"Hey Prof!\" é íntimo demais para um primeiro contato.", "prompt": "Which greeting is inappropriate for a first email to a professor?", "options": ["Dear Professor Moraes,", "Hey Prof!", "Dear Dr. Moraes,", "Dear Professor,"], "correctIndex": 1, "id": "bkC2-164"}, {"type": "choose", "level": "C2", "topic": "Variação de registro", "instruction": "Escolha as opções adequadas a uma mensagem rápida para um colega.", "explain": "Em mensagens rápidas usa-se linguagem curta e informal (\"Running late\", \"ten\").", "prompt": "Text to a coworker: [Running late*/I am experiencing a delay], be there in [ten*/approximately ten minutes' time]!", "id": "bkC2-165"}, {"type": "choose", "level": "C2", "topic": "Variação de registro", "instruction": "Escolha as opções adequadas a um relatório formal.", "explain": "\"Rose sharply\" e \"whereas\" são formais; \"went through the roof\" e \"like\" são coloquiais.", "prompt": "The figures [went through the roof/rose sharply*] in March, [whereas*/but then, like,] April saw a modest decline.", "id": "bkC2-166"}, {"type": "error", "level": "C2", "topic": "Variação de registro", "instruction": "Encontre o trecho inadequado ao registro formal.", "explain": "\"Stuff\" é informal; numa carta formal use \"the documents\" ou \"the materials\".", "sentence": "Following our telephone conversation on Tuesday, I enclose the stuff you requested.", "wrong": "the stuff", "fix": ["the documents", "the documentation", "the materials", "the information", "the items", "the papers"], "id": "bkC2-167"}, {"type": "error", "level": "C2", "topic": "Variação de registro", "instruction": "Encontre o trecho formal demais para esta mensagem.", "explain": "\"Most gratifying\" soa solene num bilhete a um amigo; use \"great\" ou \"delicious\".", "sentence": "Hey Mike, thanks for the pizza last night, it was most gratifying!", "wrong": "most gratifying", "fix": ["great", "delicious", "amazing", "awesome", "really good", "so good", "fantastic"], "id": "bkC2-168"}, {"type": "match", "level": "C2", "topic": "Variação de registro", "instruction": "Ligue cada phrasal verb informal ao verbo formal equivalente.", "explain": "Na escrita formal, phrasal verbs costumam dar lugar a verbos de origem latina.", "left": ["put off", "look into", "turn down", "come up with", "set up"], "right": ["investigate", "devise", "establish", "postpone", "decline"], "correctMap": [3, 0, 4, 1, 2], "id": "bkC2-169"}, {"type": "match", "level": "C2", "topic": "Variação de registro", "instruction": "Ligue cada frase ao contexto em que ela aparece.", "explain": "Cada gênero tem marcas próprias: \"hereby\" (jurídico), \"OMG\" (mensagem), voz passiva (pesquisa).", "left": ["The parties hereby agree to the following terms.", "OMG can't wait for Saturday!!", "Participants were randomly assigned to two groups.", "Please return to your seat and fasten your seatbelt."], "right": ["a research article", "an in-flight announcement", "a text message", "a legal contract"], "correctMap": [3, 2, 0, 1], "id": "bkC2-170"}, {"type": "sort", "level": "C2", "topic": "Variação de registro", "instruction": "Classifique as expressões por registro.", "explain": "Kind of, stuff like that, gonna e you know são coloquiais; as demais são típicas da escrita acadêmica.", "prompt": "Sort the expressions into academic writing and casual conversation.", "groups": ["Escrita acadêmica", "Conversa informal"], "items": [{"w": "kind of", "g": 1}, {"w": "to a certain degree", "g": 0}, {"w": "stuff like that", "g": 1}, {"w": "and so forth", "g": 0}, {"w": "gonna", "g": 1}, {"w": "thus", "g": 0}, {"w": "you know", "g": 1}, {"w": "whereby", "g": 0}], "id": "bkC2-171"}, {"type": "tf", "level": "C2", "topic": "Variação de registro", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Juliana muda o estilo, não o conteúdo; alguns colegas criticam, mas a universidade elogia.", "text": "Juliana hosts a science podcast from Manaus and also writes articles for a peer-reviewed journal. On the podcast, she uses contractions, jokes and phrases like 'this stuff is wild'. In her articles, she avoids personal anecdotes and writes in a precise, impersonal style. She says the facts are identical in both formats; only the audience and the purpose change. Some colleagues think the podcast style is unprofessional, but her university has praised it for attracting new students.", "items": [{"s": "Juliana uses the same style in both formats.", "a": false}, {"s": "According to Juliana, the content stays the same across formats.", "a": true}, {"s": "All of her colleagues approve of the podcast style.", "a": false}, {"s": "The university views the podcast positively.", "a": true}], "id": "bkC2-172"}, {"type": "reading", "level": "C2", "topic": "Variação de registro", "instruction": "Leia os dois e-mails e responda às perguntas.", "explain": "O e-mail 1 é formal (à chefe); o 2 é informal, e \"I owe you one\" promete retribuir o favor.", "text": "Email 1: 'Dear Ms. Farias, I am writing to request a two-day extension for the quarterly report, as the data from the Recife branch arrived later than expected. I would be grateful for your understanding. Kind regards, Tânia' Email 2: 'Hi Leo, any chance you could cover my shift on Saturday? Something came up. I owe you one! T.'", "questions": [{"q": "Which email is written to someone in a position of authority?", "options": ["Email 1", "Email 2", "Neither"], "correctIndex": 0}, {"q": "What does 'I owe you one' express?", "options": ["A debt of money", "An apology for being late", "A promise to return the favor"], "correctIndex": 2}, {"q": "Why does Tânia need more time for the report?", "options": ["She was ill.", "Some data arrived late.", "Her manager changed the deadline."], "correctIndex": 1}], "id": "bkC2-173"}, {"type": "reading", "level": "C2", "topic": "Variação de registro", "instruction": "Leia as duas versões do aviso e responda às perguntas.", "explain": "A versão B é a formal; \"Heads up\" = atenção; \"shut\" corresponde a \"closed\".", "text": "Version A: 'Heads up, folks! The gym's shut on Monday for repairs. Sorry!' Version B: 'Please be advised that the fitness center will be closed on Monday for maintenance. We apologize for any inconvenience.'", "questions": [{"q": "Which version would suit an apartment building's official notice board?", "options": ["Version A", "Both equally", "Version B"], "correctIndex": 2}, {"q": "What does 'Heads up' mean in Version A?", "options": ["Look upwards", "Take note", "Hurry up"], "correctIndex": 1}, {"q": "Which word in Version B corresponds to 'shut'?", "options": ["closed", "advised", "maintenance"], "correctIndex": 0}], "id": "bkC2-174"}, {"type": "gaps", "level": "C2", "topic": "Variação de registro", "instruction": "Complete o diálogo informal com palavras do banco.", "explain": "Grab a bite (comer algo), shattered (exausto), no worries (tudo bem), give a shout (dar um toque).", "prompt": "A: Fancy grabbing a ___ after work?\nB: Can't, I'm ___. I've been up since five.\nA: No ___. Another time, then?\nB: Definitely. I'll give you a ___ tomorrow.", "answers": [["bite", "drink", "coffee", "beer"], ["shattered", "beat", "exhausted", "knackered", "tired"], ["worries", "problem"], ["shout", "call", "ring", "buzz"]], "bank": ["bite", "shattered", "worries", "shout", "chuffed", "hitch"], "id": "bkC2-175"}, {"type": "rewrite", "level": "C2", "topic": "Variação de registro", "instruction": "Reescreva o pedido de forma formal e cortês, começando como indicado.", "explain": "\"I would be grateful if you could\" suaviza a ordem direta.", "prompt": "I need your report by Friday.", "start": "I would be grateful if you could", "accept": ["I would be grateful if you could send me your report by Friday.", "I would be grateful if you could send your report by Friday.", "I would be grateful if you could submit your report by Friday.", "I would be grateful if you could let me have your report by Friday.", "I would be grateful if you could give me your report by Friday.", "I would be grateful if you could send your report to me by Friday."], "id": "bkC2-176"}, {"type": "dorder", "level": "C2", "topic": "Variação de registro", "instruction": "Coloque a entrevista na ordem correta.", "explain": "Saudação, agradecimento, pergunta sobre o cargo atual e, por fim, a motivação.", "lines": ["A: Good morning, Ms. Tavares. Thank you for coming in today.", "B: Good morning. Thank you for the opportunity.", "A: Could you begin by telling us about your current role?", "B: Certainly. I currently manage a team of eight analysts at a bank in Curitiba.", "A: And what prompted you to apply for this position?", "B: I'm keen to take on a role with a more international scope."], "id": "bkC2-177"}, {"type": "order", "level": "C2", "topic": "Variação de registro", "instruction": "Ordene as palavras para formar a instrução formal.", "explain": "\"Kindly ensure that\" é uma fórmula formal de pedido.", "words": ["Kindly", "ensure", "that", "all", "forms", "are", "signed", "before", "submission"], "alt": ["Before submission kindly ensure that all forms are signed"], "id": "bkC2-178"}, {"type": "blank", "level": "C2", "topic": "Variação de registro", "instruction": "Complete a fórmula formal de correspondência.", "explain": "\"We acknowledge receipt of\" = acusamos o recebimento de (fórmula formal).", "prompt": "We ___ receipt of your letter dated 3 May.", "accept": ["acknowledge", "confirm"], "id": "bkC2-179"}, {"type": "mcq", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Escolha o marcador que completa a frase.", "explain": "\"Even so\" = mesmo assim (concessão); os outros indicam consequência, semelhança ou reformulação.", "prompt": "The plan is expensive. ___, it is the only option that meets the deadline.", "options": ["Even so", "Hence", "Likewise", "That is to say"], "correctIndex": 0, "id": "bkC2-180"}, {"type": "mcq", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Escolha o marcador que completa a frase.", "explain": "\"On the contrary\" rejeita a afirmação anterior; \"in contrast\" compara duas coisas diferentes.", "prompt": "The meeting was not a failure. ___, it was the most productive one we have had all year.", "options": ["In contrast", "Conversely", "On the contrary", "Otherwise"], "correctIndex": 2, "id": "bkC2-181"}, {"type": "mcq", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Escolha o marcador que completa a frase.", "explain": "\"By contrast\" compara dois dados opostos; \"on the contrary\" serviria para negar algo dito antes.", "prompt": "Sales in the North fell by 8%. ___, sales in the South rose by 11%.", "options": ["On the contrary", "By contrast", "Thereby", "Insofar as"], "correctIndex": 1, "id": "bkC2-182"}, {"type": "odd", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Qual marcador NÃO introduz uma reformulação?", "explain": "\"By the same token\" indica semelhança; os outros reformulam o que foi dito.", "prompt": "Which marker does not introduce a reformulation?", "options": ["that is to say", "in other words", "to put it differently", "by the same token"], "correctIndex": 3, "id": "bkC2-183"}, {"type": "odd", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Qual marcador NÃO sinaliza conclusão ou resumo?", "explain": "\"What is more\" acrescenta informação; in sum, all in all e to sum up concluem.", "prompt": "Which marker does not signal a conclusion?", "options": ["what is more", "in sum", "all in all", "to sum up"], "correctIndex": 0, "id": "bkC2-184"}, {"type": "choose", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Escolha os marcadores adequados.", "explain": "\"Moreover\" adiciona outra vantagem; \"On the other hand\" introduz o contraponto.", "prompt": "The software is powerful; [moreover*/whereas], it is free. [On the other hand*/Thereby], it has a steep learning curve.", "id": "bkC2-185"}, {"type": "choose", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Escolha os marcadores adequados.", "explain": "\"Insofar as\" = na medida em que; \"Incidentally\" = a propósito (comentário lateral).", "prompt": "[Insofar as*/Inasmuch that] the data are reliable, the conclusions stand. [Incidentally*/Consequently], the dataset is now publicly available.", "id": "bkC2-186"}, {"type": "error", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Encontre o marcador usado incorretamente.", "explain": "\"On the contrary\" nega algo dito; aqui há apenas contraste, então use \"on the other hand\".", "sentence": "The hotel was expensive; on the contrary, the service was excellent.", "wrong": "on the contrary", "fix": ["on the other hand", "however", "that said", "then again", "even so"], "id": "bkC2-187"}, {"type": "error", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Encontre o erro no marcador.", "explain": "\"Notwithstanding\" não leva \"of\"; ou use \"Despite\" / \"In spite of\".", "sentence": "Notwithstanding of the delays, the bridge opened on schedule.", "wrong": "Notwithstanding of", "fix": ["Notwithstanding", "Despite", "In spite of"], "id": "bkC2-188"}, {"type": "match", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Ligue cada marcador à sua função.", "explain": "Cada marcador tem uma função discursiva específica.", "left": ["Incidentally", "Insofar as", "Thereby", "On the contrary", "Mind you"], "right": ["adds a qualification in informal speech", "limits the extent of a claim", "rejects a previous statement", "introduces a side remark", "introduces a result achieved by an action"], "correctMap": [3, 1, 4, 2, 0], "id": "bkC2-189"}, {"type": "match", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Ligue as metades das frases.", "explain": "Far from (longe de), granted... even so (concessão), thereby (resultado), by contrast (contraste).", "left": ["Far from reducing traffic,", "Granted, the rent is high;", "The firm automated its warehouse,", "Some critics loved the film;"], "right": ["thereby cutting delivery times by half.", "the new road has attracted even more cars.", "others, by contrast, found it tedious.", "even so, the location is unbeatable."], "correctMap": [1, 3, 0, 2], "id": "bkC2-190"}, {"type": "sort", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Classifique os marcadores pela função.", "explain": "Concessão admite um ponto; reformulação diz de outro modo; exemplificação ilustra.", "prompt": "Sort the markers by function.", "groups": ["Concessão", "Reformulação", "Exemplificação"], "items": [{"w": "admittedly", "g": 0}, {"w": "granted", "g": 0}, {"w": "while it is true that", "g": 0}, {"w": "i.e.", "g": 1}, {"w": "put differently", "g": 1}, {"w": "or rather", "g": 1}, {"w": "for instance", "g": 2}, {"w": "a case in point is", "g": 2}], "id": "bkC2-191"}, {"type": "tf", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "\"Admittedly\" concede o atraso; os críticos veem problemas anteriores a 2020; \"albeit\" indica menos estações.", "text": "The new metro line in Fortaleza was supposed to open in 2020. Admittedly, the pandemic caused delays that no one could have foreseen. Even so, critics argue that most of the problems predate 2020. The contractor, meanwhile, blames frequent design changes. At any rate, the line is now expected to open next year, albeit with fewer stations than planned.", "items": [{"s": "The writer concedes that the pandemic caused unforeseeable delays.", "a": true}, {"s": "Critics believe that all the problems began in 2020.", "a": false}, {"s": "The contractor blames changes to the design.", "a": true}, {"s": "The line will have more stations than originally planned.", "a": false}], "id": "bkC2-192"}, {"type": "reading", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Leia o texto e responda às perguntas.", "explain": "\"To be fair\" concede; \"so to speak\" indica sentido figurado; a causa apontada é cultural.", "text": "Much has been written about the four-day work week. Proponents cite higher morale and fewer sick days. To be fair, the early trials in Portugal were encouraging. That being so, one might expect companies to adopt it en masse. Yet few have done so. The reason, arguably, is not productivity but culture: managers still equate long hours with commitment. Until that changes, the four-day week will remain, so to speak, a pilot project.", "questions": [{"q": "What does 'To be fair' introduce?", "options": ["A concession to the other side", "A new counterargument", "The final conclusion"], "correctIndex": 0}, {"q": "According to the author, why have few companies adopted the four-day week?", "options": ["The trials in Portugal failed.", "Employees took more sick days.", "Managers link long hours with commitment."], "correctIndex": 2}, {"q": "What does 'so to speak' signal?", "options": ["The author is quoting a manager.", "The expression is used figuratively.", "A contrast with the previous sentence."], "correctIndex": 1}], "id": "bkC2-193"}, {"type": "reading", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Leia o comunicado e responda às perguntas.", "explain": "\"Incidentally\" abre um assunto paralelo; \"On balance\" mostra que prós e contras foram pesados.", "text": "Dear residents, As you know, the pool will be renovated in July. Incidentally, several of you have asked about the gym: it will remain open throughout. The renovation will, admittedly, cause some noise. On balance, however, we believe the improvements will be worth it. In the meantime, residents may use the pool at the Aurora Club free of charge.", "questions": [{"q": "What does 'Incidentally' introduce?", "options": ["The main reason for the letter", "A related side topic", "A contradiction"], "correctIndex": 1}, {"q": "What does 'On balance' suggest?", "options": ["The writer has weighed the pros and cons.", "The writer is uncertain.", "The costs equal the benefits."], "correctIndex": 0}, {"q": "What can residents do during the renovation?", "options": ["Use the gym at a discount", "Swim in the evenings only", "Use another club's pool for free"], "correctIndex": 2}], "id": "bkC2-194"}, {"type": "gaps", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Complete o texto com os marcadores do banco.", "explain": "Indeed reforça; That said concede; in response indica reação; All in all conclui.", "prompt": "The festival was a financial success. ___, attendance was the highest in a decade. ___, several neighbors complained about the noise. The organizers, ___, have promised to end concerts earlier next year. ___, the event looks set to continue.", "answers": [["Indeed"], ["That said"], ["in response"], ["All in all"]], "bank": ["Indeed", "That said", "in response", "All in all", "Conversely", "Namely"], "id": "bkC2-195"}, {"type": "rewrite", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Reescreva em duas frases, começando como indicado.", "explain": "\"Even so\" (mesmo assim) substitui \"Although\" e liga as duas frases.", "prompt": "Although the evidence was weak, the jury convicted him.", "start": "The evidence was weak. Even so,", "accept": ["The evidence was weak. Even so, the jury convicted him.", "The evidence was weak. Even so, the jury found him guilty."], "id": "bkC2-196"}, {"type": "dorder", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A opinião inicial, a crítica, a concessão (\"Granted\") e a proposta final formam a sequência lógica.", "lines": ["A: Did you read the proposal for the new campus in Sorocaba?", "B: I did. It's ambitious, to say the least.", "A: Too ambitious, if you ask me. The budget is unrealistic.", "B: Granted, but the board seems to like it.", "A: Even so, someone has to point out the risks.", "B: Fair enough. Why don't we raise it at Monday's meeting, then?"], "id": "bkC2-197"}, {"type": "order", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Ordene as palavras para formar a frase.", "explain": "\"All things being equal\" = se nada mudar.", "words": ["All", "things", "being", "equal", "prices", "should", "fall", "next", "year"], "alt": ["Prices should fall next year all things being equal", "Next year prices should fall all things being equal", "Next year all things being equal prices should fall"], "id": "bkC2-198"}, {"type": "blank", "level": "C2", "topic": "Marcadores discursivos sofisticados", "instruction": "Complete a expressão que resume a ideia.", "explain": "\"In a word\" = em suma, numa palavra.", "prompt": "The survey had a tiny sample and no control group. The data are, ___ a word, unreliable.", "accept": ["in"], "id": "bkC2-199"}, {"type": "mcq", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Identifique a figura de linguagem.", "explain": "Dizer o oposto do que se sente (\"Great\") é ironia verbal.", "prompt": "Your friend spills coffee on your laptop, and you say, 'Great. Just what I needed.' This is an example of:", "options": ["verbal irony", "litotes", "hyperbole", "euphemism"], "correctIndex": 0, "id": "bkC2-200"}, {"type": "mcq", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "O que a frase provavelmente significa?", "explain": "\"Not exactly a morning person\" é um understatement: ela detesta as manhãs.", "prompt": "What does 'She's not exactly a morning person' most likely mean?", "options": ["She loves getting up early.", "She never sleeps.", "She strongly dislikes mornings.", "She works only in the morning."], "correctIndex": 2, "id": "bkC2-201"}, {"type": "mcq", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Qual frase exemplifica ironia situacional?", "explain": "Ironia situacional = o resultado é o oposto do esperado (quartel de bombeiros em chamas).", "prompt": "Which sentence describes situational irony?", "options": ["It's raining cats and dogs.", "He's not the worst cook.", "This suitcase weighs a ton.", "A fire station burns down."], "correctIndex": 3, "id": "bkC2-202"}, {"type": "odd", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Qual expressão NÃO é litotes?", "explain": "\"Not at all\" é só negação enfática; as outras afirmam negando o contrário.", "prompt": "Which expression is not an example of litotes?", "options": ["not half bad", "not at all", "not unlike", "not a few"], "correctIndex": 1, "id": "bkC2-203"}, {"type": "odd", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Qual comentário NÃO é um understatement?", "explain": "A última frase exagera (hipérbole); as outras minimizam fatos enormes.", "prompt": "Which comment is not an understatement?", "options": ["The Amazon is quite a big river.", "Einstein was reasonably clever.", "The Titanic had a minor mishap.", "The desert was unbearably, impossibly hot."], "correctIndex": 3, "id": "bkC2-204"}, {"type": "choose", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Escolha as opções que formam um understatement.", "explain": "Chamar um desastre de \"slightly disappointing\" minimiza a situação: understatement.", "prompt": "When the chef burned the entire banquet, the host remarked, 'Well, that's [slightly*/hugely] disappointing,' a classic case of [understatement*/exaggeration].", "id": "bkC2-205"}, {"type": "choose", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Escolha as opções que dão sentido à frase.", "explain": "\"To say X would be an understatement\" exige X mais fraco que a realidade: milhares protestaram.", "prompt": "To say that the new tax was [not universally popular*/universally hated] would be an understatement: [thousands*/a handful] of protesters filled the streets.", "id": "bkC2-206"}, {"type": "error", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Encontre o erro na frase com litotes.", "explain": "A estrutura é \"It's not uncommon for X to be...\" (for + objeto + infinitivo).", "sentence": "It's not uncommon for flights to Lisbon being delayed in winter.", "wrong": "being", "fix": ["to be"], "id": "bkC2-207"}, {"type": "error", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Encontre o erro na frase.", "explain": "Para modificar o verbo \"said\" é preciso o advérbio \"ironically\".", "sentence": "After losing his wallet, his passport and his luggage, Pedro ironical said that it had been 'a relaxing trip'.", "wrong": "ironical", "fix": ["ironically"], "id": "bkC2-208"}, {"type": "match", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Ligue cada frase ao que ela realmente quer dizer.", "explain": "Understatement e ironia dizem menos (ou o oposto) do que se quer comunicar.", "left": ["'He's not the sharpest tool in the shed.'", "'The exam wasn't exactly a walk in the park.'", "'Oh, lovely weather for a picnic!' (during a storm)", "'She has been known to exaggerate.'", "'It's not rocket science.'"], "right": ["It is easy to understand.", "The weather is terrible.", "He is not very intelligent.", "She often exaggerates.", "The exam was difficult."], "correctMap": [2, 4, 1, 3, 0], "id": "bkC2-209"}, {"type": "match", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Ligue cada recurso ao seu exemplo.", "explain": "Litotes nega o contrário; understatement minimiza; ironia situacional contraria a expectativa; hipérbole exagera.", "left": ["litotes", "understatement", "situational irony", "hyperbole"], "right": ["I've got a million emails to answer.", "The hotel was not without its charms.", "Losing the final 7–0 was a bit disappointing.", "The marriage counselor filed for divorce."], "correctMap": [1, 2, 3, 0], "id": "bkC2-210"}, {"type": "sort", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Classifique cada fala, considerando o contexto: irônica ou sincera.", "explain": "A mesma frase é irônica quando contradiz a situação e sincera quando combina com ela.", "prompt": "Sort the remarks into ironic and sincere.", "groups": ["Irônica", "Sincera"], "items": [{"w": "'What a lovely surprise!' (on finding a parking ticket)", "g": 0}, {"w": "'What a lovely surprise!' (on receiving flowers from a friend)", "g": 1}, {"w": "'Thanks for your help!' (to a colleague who ignored every request)", "g": 0}, {"w": "'Thanks for your help!' (to a neighbor who carried your boxes)", "g": 1}, {"w": "'Perfect timing!' (as the bus leaves without you)", "g": 0}, {"w": "'Perfect timing!' (as dinner is served the moment you arrive)", "g": 1}, {"w": "'Great, I love queues!' (in a three-hour line)", "g": 0}, {"w": "'This is a real bargain!' (about a 70% discount)", "g": 1}], "id": "bkC2-211"}, {"type": "tf", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "\"Not bad\" era elogio (litotes); Renata exagerou um atraso pequeno; os dois lados brincam com isso.", "text": "British and Brazilian colleagues at an engineering firm in Rio often misread each other. When a British engineer called a design 'not bad', his Brazilian colleague Renata assumed he was unimpressed. In fact, he was paying her a compliment. Conversely, when Renata described a minor delay as 'a disaster', the British team panicked. Both sides now joke that they need a 'translator' for tone.", "items": [{"s": "Renata initially took 'not bad' as criticism.", "a": true}, {"s": "The British engineer disliked the design.", "a": false}, {"s": "Renata exaggerated when describing a small delay.", "a": true}, {"s": "The two teams no longer find these misunderstandings funny.", "a": false}], "id": "bkC2-212"}, {"type": "tf", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "Swift usou ironia: tom calmo para uma ideia monstruosa, criticando a política britânica.", "text": "In Jonathan Swift's 1729 essay 'A Modest Proposal', the narrator calmly suggests that poor Irish families sell their children as food for the rich. Swift, of course, did not mean this literally. By presenting a monstrous idea in a reasonable, bureaucratic tone, he attacked the cruelty of British policy toward Ireland. The title itself is ironic, since the proposal is anything but modest.", "items": [{"s": "Swift genuinely wanted the idea to be put into practice.", "a": false}, {"s": "The narrator's tone is calm and reasonable.", "a": true}, {"s": "The title is an example of irony.", "a": true}, {"s": "The essay defends British policy toward Ireland.", "a": false}], "id": "bkC2-213"}, {"type": "reading", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Leia a resenha e responda às perguntas.", "explain": "A crítica ao serviço vem atenuada (\"not ideal\", \"not unfriendly\"); \"a mere ninety minutes\" é irônico; só a sobremesa é elogiada.", "text": "The new bistro on Rua Augusta is, to put it gently, still finding its feet. Our soup arrived cold, which was not ideal, and the main course took a mere ninety minutes. The waiter was not unfriendly, though he vanished for long stretches. The dessert, a chocolate tart, was genuinely excellent: almost enough to make us forget the rest.", "questions": [{"q": "What is the reviewer's overall opinion of the service?", "options": ["It was excellent.", "It was poor, though this is expressed mildly.", "It was slow, but the reviewer did not mind."], "correctIndex": 1}, {"q": "The phrase 'a mere ninety minutes' is:", "options": ["ironic", "sincere praise", "a hedge"], "correctIndex": 0}, {"q": "What did the reviewer sincerely praise?", "options": ["the soup", "the waiter", "the dessert"], "correctIndex": 2}], "id": "bkC2-214"}, {"type": "reading", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Leia o e-mail e responda às perguntas.", "explain": "\"Not our finest hour\" minimiza um fracasso; \"I'd be lying if I said... thrilled\" indica insatisfação.", "text": "Team, as you may have heard, our server crashed during the client demo this morning, taking three months of test data with it. Not our finest hour. On the bright side, we now know exactly how not to run a demo. I'd be lying if I said the client was thrilled. Let's meet at 2 p.m. to work out a recovery plan. Coffee will be provided, and frankly, we'll need it.", "questions": [{"q": "'Not our finest hour' means:", "options": ["It was a moderately successful moment.", "The demo took less than an hour.", "It was a very bad moment."], "correctIndex": 2}, {"q": "How did the client most likely feel?", "options": ["Displeased", "Delighted", "Indifferent"], "correctIndex": 0}, {"q": "What is the purpose of the 2 p.m. meeting?", "options": ["To celebrate the demo", "To plan how to recover", "To meet the client again"], "correctIndex": 1}], "id": "bkC2-215"}, {"type": "gaps", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Complete o texto com as palavras do banco.", "explain": "Expressões fixas de understatement: no mean feat, to put it mildly, far from comfortable, nothing short of.", "prompt": "Crossing the Andes by bus was no ___ feat. The roads were, to put it ___, not ideal, and the seats were far from ___. The views, however, were nothing ___ of spectacular.", "answers": [["mean", "small"], ["mildly"], ["comfortable"], ["short"]], "bank": ["mean", "mildly", "comfortable", "short", "harshly", "plenty"], "id": "bkC2-216"}, {"type": "rewrite", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Reescreva usando litotes, começando como indicado.", "explain": "Litotes afirma algo negando o contrário: \"not difficult\" = fácil.", "prompt": "The task was easy.", "start": "The task was not", "accept": ["The task was not difficult.", "The task was not hard.", "The task was not complicated.", "The task was not challenging.", "The task was not tough."], "id": "bkC2-217"}, {"type": "dorder", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta sobre a maratona leva ao tempo, ao comentário irônico e à pergunta final.", "lines": ["A: How did your first marathon go?", "B: Well, I finished. Eventually. Six and a half hours later.", "A: Six and a half hours? That's impressive, in its own way.", "B: Thanks. My legs aren't speaking to me today, though.", "A: I'm not surprised. Are you going to run another one?", "B: Let's just say I'm not in a hurry to sign up."], "id": "bkC2-218"}, {"type": "order", "level": "C2", "topic": "Ironia, understatement e litotes", "instruction": "Ordene as palavras para formar a frase.", "explain": "\"Not without talent\" é litotes: ela tem bastante talento.", "words": ["She", "is", "not", "without", "talent", "as", "a", "writer"], "alt": ["As a writer she is not without talent"], "id": "bkC2-219"}, {"type": "mcq", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Escolha a opção que completa a inversão.", "explain": "\"No sooner\" pede inversão com past perfect: \"had the band taken\".", "prompt": "No sooner ___ the stage than the lights went out.", "options": ["had the band taken", "the band had taken", "has the band taken", "the band took"], "correctIndex": 0, "id": "bkC2-220"}, {"type": "mcq", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Escolha a opção correta.", "explain": "\"Had it not been for\" = se não fosse por (condicional com inversão).", "prompt": "___ the support of her family, she would never have finished her degree.", "options": ["Had not it been for", "If it had not for", "Were it not been for", "Had it not been for"], "correctIndex": 3, "id": "bkC2-221"}, {"type": "mcq", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Qual frase usa corretamente a elipse do verbo (gapping)?", "explain": "No gapping, o verbo repetido é omitido e marcado por vírgula: \"and Marcos, pasta\".", "prompt": "Which sentence uses gapping correctly?", "options": ["Ana ordered fish, and Marcos ordered, pasta.", "Ana ordered fish, and Marcos, pasta.", "Ana fish ordered, and Marcos pasta.", "Ana ordered fish, and pasta Marcos."], "correctIndex": 1, "id": "bkC2-222"}, {"type": "odd", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Qual frase NÃO tem inversão?", "explain": "\"Often we eat out\" mantém sujeito + verbo; as outras invertem após expressão negativa ou restritiva.", "prompt": "Which sentence has no inversion?", "options": ["Seldom have I heard such nonsense.", "Under no circumstances should you open this door.", "Often we eat out on weekdays.", "Only later did we understand the risk."], "correctIndex": 2, "id": "bkC2-223"}, {"type": "odd", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Qual frase NÃO é uma cleft sentence?", "explain": "\"It was raining\" usa \"it\" vazio de clima; as outras são clivadas para dar ênfase.", "prompt": "Which sentence is not a cleft sentence?", "options": ["It was raining when we arrived.", "It was Carla who found the error.", "What surprised us was the silence.", "All I want is a quiet weekend."], "correctIndex": 0, "id": "bkC2-224"}, {"type": "choose", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Escolha as formas corretas.", "explain": "\"Hardly... when\" é a correlação correta; \"Only then\" exige inversão: \"did we realize\".", "prompt": "Hardly had we sat down [when*/than] the alarm went off. Only then [we realized/did we realize*] that a drill had been scheduled.", "id": "bkC2-225"}, {"type": "choose", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Escolha as formas corretas.", "explain": "\"Try as she might\" = por mais que tentasse; \"nor\" já é negativo: \"nor could\".", "prompt": "[Try as she might*/Although tried she], she could not open the jar; nor [could*/couldn't] her brother.", "id": "bkC2-226"}, {"type": "error", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Encontre o erro na inversão.", "explain": "Depois de \"Under no circumstances\" é obrigatória a inversão: \"should you\".", "sentence": "Under no circumstances you should share your password with anyone.", "wrong": "you should", "fix": ["should you"], "id": "bkC2-227"}, {"type": "error", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Encontre o erro na inversão.", "explain": "\"Not a single word\" no início exige auxiliar invertido: \"did she say\".", "sentence": "Not a single word she said during the entire meeting.", "wrong": "she said", "fix": ["did she say"], "id": "bkC2-228"}, {"type": "error", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Encontre o erro na cleft sentence.", "explain": "Para pessoas, a cleft usa \"who\" ou \"that\", não \"which\".", "sentence": "It is the students which deserve the credit, not the teachers.", "wrong": "which", "fix": ["who", "that"], "id": "bkC2-229"}, {"type": "match", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Ligue as metades das frases.", "explain": "Were... to (hipótese), Nowhere else (inversão), Only by (inversão), It was not until... that, Happy though (concessão).", "left": ["Were the government to raise taxes,", "Nowhere else in Brazil", "Only by working together", "It was not until she moved to Recife", "Happy though they seemed,"], "right": ["can we meet the deadline.", "they were privately planning to separate.", "will you find beaches quite like these.", "consumer spending would fall.", "that she learned to cook."], "correctMap": [3, 2, 0, 4, 1], "id": "bkC2-230"}, {"type": "match", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Ligue cada frase à estrutura que ela exemplifica.", "explain": "Pseudo-cleft (What...), it-cleft (It was... who), inversão negativa, inversão locativa e elipse.", "left": ["What she needs is a holiday.", "It was Diego who called.", "Never have I seen such chaos.", "Into the room walked the president.", "I can swim, but my brother can't."], "right": ["locative inversion", "pseudo-cleft", "ellipsis", "negative inversion", "it-cleft"], "correctMap": [1, 4, 3, 0, 2], "id": "bkC2-231"}, {"type": "sort", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Classifique as frases: correta ou incorreta.", "explain": "Após seldom, only after, not once e em \"Had they...\" é preciso auxiliar + sujeito + verbo na forma certa.", "prompt": "Sort the sentences into correct and incorrect.", "groups": ["Correta", "Incorreta"], "items": [{"w": "Seldom does the committee meet in August.", "g": 0}, {"w": "Seldom the committee meets in August.", "g": 1}, {"w": "Only after midnight did the guests leave.", "g": 0}, {"w": "Only after midnight the guests did leave.", "g": 1}, {"w": "Not once did he apologize.", "g": 0}, {"w": "Not once he apologized.", "g": 1}, {"w": "Had they left earlier, they would have caught the ferry.", "g": 0}, {"w": "Had they leave earlier, they would have caught the ferry.", "g": 1}], "id": "bkC2-232"}, {"type": "tf", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O texto diz que o Brasil foi o último das Américas e que a lei não deu terra nem apoio aos libertos.", "text": "It was not until 1888 that Brazil abolished slavery, the last country in the Americas to do so. Rarely has a single law had such far-reaching consequences. What the Golden Law did not provide, however, was any support for the newly freed population: no land, no education, no compensation. Historians argue that this omission shaped inequalities that persist to this day.", "items": [{"s": "Brazil was the last country in the Americas to abolish slavery.", "a": true}, {"s": "The Golden Law gave land to the newly freed population.", "a": false}, {"s": "Historians believe the law's omissions still affect Brazil today.", "a": true}, {"s": "According to the text, the law had little impact.", "a": false}], "id": "bkC2-233"}, {"type": "reading", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Leia o texto e responda às perguntas.", "explain": "A cleft mostra que o festival atraiu o público; \"famous as they are\" é concessivo; há elipse em \"and the local hotels, their rooms\" (= will double their rooms).", "text": "Seldom has a small town attracted as much attention as Tiradentes did last winter. What drew the crowds was not its baroque churches, famous as they are, but a film festival that had outgrown its venue. So many visitors arrived that some had to stay in neighboring towns. Had the organizers anticipated the demand, they would have added more screenings. Next year, they say, the festival will double its screenings, and the local hotels, their rooms.", "questions": [{"q": "What attracted the crowds?", "options": ["The baroque churches", "New hotels", "A film festival"], "correctIndex": 2}, {"q": "What does 'famous as they are' mean?", "options": ["although they are famous", "because they are famous", "if they are famous"], "correctIndex": 0}, {"q": "What will the local hotels do next year?", "options": ["Add more screenings", "Add more rooms", "Lower their prices"], "correctIndex": 1}], "id": "bkC2-234"}, {"type": "gaps", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Complete com o auxiliar adequado (elipse).", "explain": "Elipses: \"than we had expected\", \"so was the restaurant\" e \"we should have (stayed)\".", "prompt": "The hotel was far more expensive than we ___ expected, and so, unfortunately, ___ the restaurant. We could have stayed at a hostel, and perhaps we ___ have.", "answers": [["had"], ["was"], ["should", "ought to"]], "id": "bkC2-235"}, {"type": "rewrite", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Reescreva a frase com inversão, começando como indicado.", "explain": "Após \"Only when + oração\", a oração principal inverte: \"did the team realize\".", "prompt": "The team only realized its mistake when the client complained.", "start": "Only when the client complained", "accept": ["Only when the client complained did the team realize its mistake.", "Only when the client complained did the team realize their mistake."], "id": "bkC2-236"}, {"type": "rewrite", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Reescreva como cleft sentence, começando como indicado.", "explain": "A it-cleft destaca a pessoa: \"It was X, not Y, who/that...\".", "prompt": "Mariana designed the logo, not Felipe.", "start": "It was Mariana, not Felipe,", "accept": ["It was Mariana, not Felipe, who designed the logo.", "It was Mariana, not Felipe, that designed the logo."], "id": "bkC2-237"}, {"type": "dorder", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A notícia, a reação, a explicação, \"rarely have I\", \"Nor have I\" e o consolo final.", "lines": ["A: Did you hear? The concert's been cancelled.", "B: You're joking! Why?", "A: The singer lost her voice. Not only that, but the venue flooded.", "B: Well, rarely have I seen such bad luck.", "A: Nor have I. What annoys me most is that we bought the tickets months ago.", "B: At least we'll get a refund. Or so I hope."], "id": "bkC2-238"}, {"type": "order", "level": "C2", "topic": "Estruturas gramaticais raras (inversão, elipse, cleft combinados)", "instruction": "Ordene as palavras para formar a frase (com inversão locativa).", "explain": "Inversão locativa: advérbio de direção + verbo + sujeito (\"Down came the rain\").", "words": ["Down", "came", "the", "rain", "and", "off", "ran", "the", "children"], "alt": ["Off ran the children and down came the rain"], "id": "bkC2-239"}, {"type": "mcq", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Escolha o plural correto.", "explain": "Palavras terminadas em -fe trocam por -ves: knife → knives.", "prompt": "Please put the two ___ on the table.", "options": ["knifes", "knives", "knife", "knifies"], "correctIndex": 1, "id": "bkA1-1001"}, {"type": "mcq", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Escolha o plural correto.", "explain": "Child tem plural irregular: children (sem -s extra).", "prompt": "The ___ are playing in the garden.", "options": ["childs", "childrens", "children", "childes"], "correctIndex": 2, "id": "bkA1-1002"}, {"type": "gaps", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Escreva o plural das palavras entre parênteses.", "explain": "Watch → watches (termina em ch, recebe -es); key → keys (vogal + y só recebe -s); photo → photos (exceção comum).", "prompt": "In my bag I have two ___ (watch), three ___ (key) and four ___ (photo).", "answers": [["watches"], ["keys"], ["photos"]], "id": "bkA1-1003"}, {"type": "choose", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Escolha a opção correta.", "explain": "Man e woman têm plural irregular (men, women); teacher vira teachers com -s.", "prompt": "Look at those [man/men*] and [woman/women*]. They are [teacher/teachers*].", "id": "bkA1-1004"}, {"type": "choose", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Escolha a opção correta.", "explain": "Jeans pede verbo no plural (are); para contar, usamos pairs of.", "prompt": "My [jeans are*/jeans is] new, and I have two [pair/pairs*] of glasses.", "id": "bkA1-1005"}, {"type": "error", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Encontre o erro e corrija.", "explain": "Consoante + y vira -ies: baby → babies.", "sentence": "My two babys are sleeping.", "wrong": "babys", "fix": ["babies"], "id": "bkA1-1006"}, {"type": "error", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Encontre o erro e corrija.", "explain": "Jeans só existe no plural e pede verbo no plural: are.", "sentence": "My jeans is too big.", "wrong": "is", "fix": ["are"], "id": "bkA1-1007"}, {"type": "rewrite", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Reescreva a frase no plural.", "explain": "Woman → women, has → have, watch → watches (termina em ch).", "prompt": "The woman has a watch.", "accept": ["The women have watches.", "The women have some watches."], "id": "bkA1-1008"}, {"type": "rewrite", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Reescreva a frase no plural.", "explain": "Leaf → leaves (-f vira -ves); this → these; is → are.", "prompt": "This leaf is green.", "accept": ["These leaves are green."], "id": "bkA1-1009"}, {"type": "order", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Para contar jeans, usamos pairs of: two pairs of jeans.", "words": ["I", "need", "two", "pairs", "of", "jeans"], "id": "bkA1-1010"}, {"type": "tf", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto cita três caixas, duas facas e cinco batatas; os dois filhos estão com ela.", "text": "Rosa works in a small shop. Today she has three boxes, two knives and five potatoes on her table. Her two children are with her. They are helping her in the shop.", "items": [{"s": "Rosa has two knives.", "a": true}, {"s": "She has four potatoes.", "a": false}, {"s": "Her children are with her.", "a": true}, {"s": "She has two boxes.", "a": false}], "id": "bkA1-1011"}, {"type": "match", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Ligue cada palavra ao seu plural.", "explain": "Man → men e mouse → mice são irregulares; knife → knives; city → cities (consoante + y).", "left": ["man", "knife", "city", "mouse"], "right": ["cities", "men", "mice", "knives"], "correctMap": [1, 3, 0, 2], "id": "bkA1-1012"}, {"type": "odd", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Encontre a palavra que não pertence ao grupo.", "explain": "Boys, keys e days têm vogal + y (só -s). Babies vem de consoante + y, por isso vira -ies.", "prompt": "Which word does not follow the same rule?", "options": ["boys", "babies", "keys", "days"], "correctIndex": 1, "id": "bkA1-1013"}, {"type": "blank", "level": "A1", "topic": "Plural dos substantivos", "instruction": "Escreva o plural da palavra entre parênteses.", "explain": "Tooth tem plural irregular: teeth.", "prompt": "Brush your ___ after lunch. (tooth)", "accept": ["teeth"], "id": "bkA1-1014"}, {"type": "mcq", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Escolha a opção correta.", "explain": "Com idiomas não usamos artigo.", "prompt": "___ English is my favorite subject.", "options": ["The", "A", "An", "(no article)"], "correctIndex": 3, "id": "bkA1-1015"}, {"type": "mcq", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Escolha a opção correta.", "explain": "Com instrumentos musicais usamos the: play the guitar.", "prompt": "My brother plays ___ guitar in a band.", "options": ["a", "an", "the", "some"], "correctIndex": 2, "id": "bkA1-1016"}, {"type": "gaps", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Complete o diálogo com a ou the.", "explain": "A primeira menção usa a (um filme qualquer); depois, as duas pessoas sabem qual é, então usamos the.", "prompt": "A: I watched ___ movie last night.\nB: Was it good?\nA: Yes! ___ movie was about a robot, and ___ robot was funny.", "answers": [["a"], ["The"], ["the"]], "id": "bkA1-1017"}, {"type": "choose", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Escolha a opção correta.", "explain": "Em generalizações (music) não usamos the; para uma música específica (in this shop), usamos the.", "prompt": "I love [the/no article*] music, but [the*/no article] music in this shop is too loud.", "id": "bkA1-1018"}, {"type": "choose", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Escolha a opção correta.", "explain": "Esportes não levam artigo (soccer); um piano específico (in his room) leva the.", "prompt": "My uncle plays [the/no article*] soccer, and [the*/no article] piano in his room is very old.", "id": "bkA1-1019"}, {"type": "error", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Encontre o erro e corrija.", "explain": "Em generalizações, o inglês não usa the: Life is beautiful.", "sentence": "The life is beautiful.", "wrong": "The life", "fix": ["Life"], "id": "bkA1-1020"}, {"type": "error", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Encontre o erro e corrija.", "explain": "Na expressão go to bed não se usa artigo.", "sentence": "I go to the bed at ten every night.", "wrong": "the bed", "fix": ["bed"], "id": "bkA1-1021"}, {"type": "rewrite", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Corrija a frase.", "explain": "Go to work e by bus são expressões sem artigo.", "prompt": "She goes to the work by the bus.", "accept": ["She goes to work by bus."], "id": "bkA1-1022"}, {"type": "rewrite", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Corrija a frase.", "explain": "Refeições (dinner) não levam artigo.", "prompt": "I had the dinner at home.", "accept": ["I had dinner at home."], "id": "bkA1-1023"}, {"type": "order", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Países com United no nome levam the: the United States.", "words": ["We", "are", "from", "the", "United", "States"], "id": "bkA1-1024"}, {"type": "tf", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que o restaurante fica perto do rio, ela vai ao mercado de ônibus, o almoço é o horário mais cheio e à noite ela toca violino.", "text": "Anna has a small restaurant by the river. She cooks Italian food. Every day she goes to the market by bus. Lunch is the busiest time. At night she goes home and plays the violin.", "items": [{"s": "Anna's restaurant is near a river.", "a": true}, {"s": "She goes to the market by car.", "a": false}, {"s": "Lunch is the busiest time.", "a": true}, {"s": "She plays the guitar at night.", "a": false}], "id": "bkA1-1025"}, {"type": "sort", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Separe as palavras: precisam de the ou não?", "explain": "Sol, lua, oceano e rádio levam the; refeições, idiomas, nomes de pessoas e ruas não levam artigo.", "prompt": "Sort the words: the or no article?", "groups": ["the", "no article"], "items": [{"w": "sun", "g": 0}, {"w": "lunch", "g": 1}, {"w": "Spanish", "g": 1}, {"w": "moon", "g": 0}, {"w": "Pacific Ocean", "g": 0}, {"w": "Paulo", "g": 1}, {"w": "radio", "g": 0}, {"w": "Main Street", "g": 1}], "id": "bkA1-1026"}, {"type": "odd", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Encontre a frase que está errada.", "explain": "Esportes não levam artigo: play soccer. Os instrumentos (guitar, piano, violin) levam the.", "prompt": "Which phrase is incorrect?", "options": ["play the guitar", "play the piano", "play the soccer", "play the violin"], "correctIndex": 2, "id": "bkA1-1027"}, {"type": "blank", "level": "A1", "topic": "Artigo The e artigo zero", "instruction": "Complete com the ou a.", "explain": "O gato já foi mencionado, então usamos the.", "prompt": "We saw a cat. ___ cat was black.", "accept": ["The", "the"], "id": "bkA1-1028"}, {"type": "mcq", "level": "A2", "topic": "Past Continuous", "instruction": "Escolha a forma correta do verbo.", "explain": "Ação em andamento em um momento específico do passado: was + verbo com -ing.", "prompt": "At nine o'clock last night, I ___ a book.", "options": ["was reading", "read", "reading", "were reading"], "correctIndex": 0, "id": "bkA2-1001"}, {"type": "mcq", "level": "A2", "topic": "Past Continuous", "instruction": "Escolha a forma correta do verbo.", "explain": "Com we, usamos were + -ing, e while introduz a ação em andamento.", "prompt": "While we ___ lunch, it started to rain.", "options": ["have", "was having", "were having", "are having"], "correctIndex": 2, "id": "bkA2-1002"}, {"type": "gaps", "level": "A2", "topic": "Past Continuous", "instruction": "Complete o diálogo com was, were, wasn't ou weren't.", "explain": "You e they usam were; I e he usam was; a negativa é weren't / were not.", "prompt": "A: What ___ you doing at seven last night?\nB: I ___ cooking, and my brother ___ watching TV.\nA: ___ your parents helping you?\nB: No, they ___. They were at the market.", "answers": [["were"], ["was"], ["was"], ["Were"], ["weren't", "were not"]], "id": "bkA2-1003"}, {"type": "choose", "level": "A2", "topic": "Past Continuous", "instruction": "Escolha a opção correta.", "explain": "A ação longa usa Past Continuous (was watching); a ação curta que interrompe usa Simple Past (called).", "prompt": "She [was*/were] watching a film when I [called*/calling] her.", "id": "bkA2-1004"}, {"type": "choose", "level": "A2", "topic": "Past Continuous", "instruction": "Escolha a opção correta.", "explain": "A ação curta (fell) usa Simple Past; a ação em andamento (was running) usa Past Continuous.", "prompt": "I [fell*/was falling] when I [ran/was running*] to the bus.", "id": "bkA2-1005"}, {"type": "error", "level": "A2", "topic": "Past Continuous", "instruction": "Encontre o erro e corrija.", "explain": "They é plural, então o auxiliar é were, não was.", "sentence": "They was playing football in the park.", "wrong": "was", "fix": ["were"], "id": "bkA2-1006"}, {"type": "error", "level": "A2", "topic": "Past Continuous", "instruction": "Encontre o erro e corrija.", "explain": "Know é verbo de estado e não costuma ir para o -ing: usamos o Simple Past (knew).", "sentence": "I was knowing the answer, but I said nothing.", "wrong": "was knowing", "fix": ["knew"], "id": "bkA2-1007"}, {"type": "rewrite", "level": "A2", "topic": "Past Continuous", "instruction": "Reescreva a frase na forma negativa.", "explain": "Na negativa colocamos not depois de was: wasn't / was not.", "prompt": "She was reading a magazine.", "accept": ["She wasn't reading a magazine.", "She was not reading a magazine."], "id": "bkA2-1008"}, {"type": "rewrite", "level": "A2", "topic": "Past Continuous", "instruction": "Transforme a frase em pergunta.", "explain": "Na pergunta, were vem antes do sujeito: Were they waiting...?", "prompt": "They were waiting for the bus.", "accept": ["Were they waiting for the bus?"], "id": "bkA2-1009"}, {"type": "order", "level": "A2", "topic": "Past Continuous", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Ação longa (was taking) + when + ação curta no Simple Past (rang).", "words": ["I", "was", "taking", "a", "shower", "when", "the", "phone", "rang"], "id": "bkA2-1010", "alt": ["When the phone rang I was taking a shower"]}, {"type": "tf", "level": "A2", "topic": "Past Continuous", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que Leo voltava do trabalho a pé, não tinha guarda-chuva e Mia estava lendo jornal.", "text": "Last Saturday, Leo was walking home from work when it began to rain. He didn't have an umbrella, so he ran into a small cafe. Inside, his friend Mia was drinking coffee and reading a newspaper. They talked for an hour.", "items": [{"s": "Leo was walking home when it began to rain.", "a": true}, {"s": "Leo had an umbrella.", "a": false}, {"s": "Mia was reading a newspaper in the cafe.", "a": true}, {"s": "Leo was driving when the rain started.", "a": false}], "id": "bkA2-1011"}, {"type": "match", "level": "A2", "topic": "Past Continuous", "instruction": "Ligue cada pergunta à resposta correta.", "explain": "A resposta curta repete was/were: Was it raining? Yes, it was.", "left": ["Were you sleeping?", "What was he doing?", "Where were they going?", "Was it raining?"], "right": ["Yes, it was.", "He was making lunch.", "No, I wasn't.", "They were going to school."], "correctMap": [2, 1, 3, 0], "id": "bkA2-1012"}, {"type": "blank", "level": "A2", "topic": "Past Continuous", "instruction": "Complete com o Past Continuous do verbo entre parênteses.", "explain": "My dad (he) usa was + verbo com -ing: was driving.", "prompt": "My dad ___ (drive) us home when the storm started.", "accept": ["was driving"], "id": "bkA2-1013"}, {"type": "dorder", "level": "A2", "topic": "Past Continuous", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Primeiro a pergunta com was/were, depois a resposta, a reação e a explicação final.", "lines": ["A: What were you doing at nine last night?", "B: I was studying for my English test.", "A: Really? I called you, but you didn't answer.", "B: Sorry, my phone was in my bag."], "id": "bkA2-1014"}, {"type": "mcq", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Escolha a opção correta.", "explain": "Para descrever o verbo sing, usamos advérbio: beautifully (beautiful + -ly).", "prompt": "Ana sings very ___.", "options": ["beautiful", "beauty", "beautifuly", "beautifully"], "correctIndex": 3, "id": "bkA2-1015"}, {"type": "mcq", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Escolha a opção correta.", "explain": "Adjetivos com -ing dizem o que causa o sentimento: a aula é boring (chata).", "prompt": "The lesson was ___, so I almost fell asleep.", "options": ["boring", "bored", "bores", "boringly"], "correctIndex": 0, "id": "bkA2-1016"}, {"type": "gaps", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Complete com a forma correta (adjetivo ou advérbio) da palavra entre parênteses.", "explain": "Antes de substantivo usamos adjetivo (careful driver); depois do verbo, advérbio (carefully, safely). Safe + -ly = safely.", "prompt": "Pedro is a ___ (careful) driver. He drives ___ (careful) and always arrives ___ (safe).", "answers": [["careful"], ["carefully"], ["safely"]], "id": "bkA2-1017"}, {"type": "choose", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Escolha a opção correta.", "explain": "O advérbio de good é well; depois de be usamos adjetivo (perfect).", "prompt": "She speaks English [good/well*], and her pronunciation is [perfect*/perfectly].", "id": "bkA2-1018"}, {"type": "choose", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Escolha a opção correta.", "explain": "Hardly significa 'quase não'; hard como advérbio significa 'muito, com esforço' e não muda.", "prompt": "I [hardly*/hard] know him, but he works [hard*/hardly] every day.", "id": "bkA2-1019"}, {"type": "error", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Encontre o erro e corrija.", "explain": "O advérbio não vem entre o verbo e o objeto: speaks English well.", "sentence": "She speaks well English.", "wrong": "well English", "fix": ["English well"], "id": "bkA2-1020"}, {"type": "error", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Encontre o erro e corrija.", "explain": "O adjetivo vem antes do substantivo: a red car.", "sentence": "My sister has a car red.", "wrong": "car red", "fix": ["red car"], "id": "bkA2-1021"}, {"type": "rewrite", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Reescreva a frase com um advérbio.", "explain": "Quick vira quickly (adjetivo + -ly); fast também é advérbio, sem mudança.", "prompt": "She is a quick learner.", "accept": ["She learns quickly.", "She learns fast.", "She learns very quickly.", "She learns very fast."], "id": "bkA2-1022"}, {"type": "rewrite", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Reescreva a frase com um advérbio.", "explain": "O advérbio de good é well.", "prompt": "He is a good dancer.", "accept": ["He dances well.", "He dances very well."], "id": "bkA2-1023"}, {"type": "order", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Ordem dos adjetivos: opinião (beautiful) antes de idade (old).", "words": ["I", "bought", "a", "beautiful", "old", "table"], "id": "bkA2-1024"}, {"type": "tf", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que o restaurante era italiano, o garçom era simpático, a música estava alta demais e Diego voltou andando devagar.", "text": "Last week, Diego visited a small Italian restaurant near his house. The waiter was very friendly and spoke politely to everyone. The pasta was delicious, but the music was too loud, so Diego couldn't talk easily with his friend. He left early and walked home slowly.", "items": [{"s": "The restaurant was Italian.", "a": true}, {"s": "The waiter was rude.", "a": false}, {"s": "Diego could talk easily with his friend.", "a": false}, {"s": "Diego walked home slowly.", "a": true}], "id": "bkA2-1025"}, {"type": "match", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Ligue cada adjetivo ao advérbio correspondente.", "explain": "Easy → easily (consoante + y vira -ily); good → well; fast não muda; gentle → gently (-le vira -ly).", "left": ["easy", "good", "fast", "gentle"], "right": ["gently", "well", "easily", "fast"], "correctMap": [2, 1, 3, 0], "id": "bkA2-1026"}, {"type": "odd", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Encontre a palavra que não pertence ao grupo.", "explain": "Friendly é adjetivo (a friendly person); carefully, slowly e happily são advérbios.", "prompt": "Which word is not an adverb?", "options": ["carefully", "slowly", "friendly", "happily"], "correctIndex": 2, "id": "bkA2-1027"}, {"type": "blank", "level": "A2", "topic": "Adjetivos e advérbios de modo", "instruction": "Escreva o advérbio da palavra entre parênteses.", "explain": "Happy vira happily (consoante + y vira -ily).", "prompt": "The children played ___ in the garden. (happy)", "accept": ["happily"], "id": "bkA2-1028"}, {"type": "mcq", "level": "A2", "topic": "Too / Enough", "instruction": "Escolha a opção correta.", "explain": "Too vem antes do adjetivo e mostra excesso: \"too heavy\" = pesado demais.", "prompt": "The suitcase is ___ heavy for me to carry.", "options": ["enough", "too", "too much", "many"], "correctIndex": 1, "id": "bkA2-1029"}, {"type": "gaps", "level": "A2", "topic": "Too / Enough", "instruction": "Complete o diálogo com too ou enough.", "explain": "Too fica antes do adjetivo e indica excesso (too big, too expensive); enough fica depois do adjetivo (big enough).", "prompt": "A: Let's buy this sofa.\nB: It's ___ big for our living room.\nA: But it's soft and nice.\nB: Yes, but it's ___ expensive for us, and the room isn't large ___.", "answers": [["too"], ["too"], ["enough"]], "id": "bkA2-1030"}, {"type": "choose", "level": "A2", "topic": "Too / Enough", "instruction": "Escolha a opção correta em cada par de colchetes.", "explain": "Too + adjetivo (too hot); too much com incontáveis, como sugar.", "prompt": "Don't drink that tea. It's [too*/enough/much] hot, and there is [too much*/too many/too] sugar in it.", "id": "bkA2-1031"}, {"type": "error", "level": "A2", "topic": "Too / Enough", "instruction": "Encontre o erro e corrija.", "explain": "\"Noise\" é incontável, então usamos too much, não too many.", "sentence": "I can't sleep because there is too many noise in the street.", "wrong": "too many", "fix": ["too much"], "id": "bkA2-1032"}, {"type": "rewrite", "level": "A2", "topic": "Too / Enough", "instruction": "Reescreva a frase na forma negativa.", "explain": "Na negativa, usamos don't / doesn't + have + enough + substantivo.", "prompt": "We have enough chairs.", "accept": ["We don't have enough chairs.", "We do not have enough chairs.", "We haven't got enough chairs.", "We have not got enough chairs."], "id": "bkA2-1033"}, {"type": "order", "level": "A2", "topic": "Too / Enough", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Enough vem depois do adjetivo (old enough) e é seguido de to + verbo.", "words": ["My", "brother", "isn't", "old", "enough", "to", "drive"], "id": "bkA2-1034"}, {"type": "tf", "level": "A2", "topic": "Too / Enough", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que a água estava fria demais, que faltaram cadeiras, que havia gente demais na lanchonete e que eles comeram no carro.", "text": "Last weekend, Rui and his friends went to the beach. The sun was out, but the water was too cold to swim. They didn't have enough chairs, so they sat on towels. There were too many people near the snack bar, so they ate sandwiches in the car.", "items": [{"s": "The water was too cold to swim.", "a": true}, {"s": "They had enough chairs.", "a": false}, {"s": "The snack bar was empty.", "a": false}, {"s": "They ate their sandwiches in the car.", "a": true}], "id": "bkA2-1035"}, {"type": "mcq", "level": "A2", "topic": "Too / Enough", "instruction": "Escolha a opção correta.", "explain": "Too fica antes do adjetivo (too expensive); \"too much\" não vai antes de adjetivo e \"much expensive\" está errado.", "prompt": "The bike is ___ expensive for Marcos to buy.", "options": ["enough", "too much", "much", "too"], "correctIndex": 3, "id": "bkA2-1036"}, {"type": "match", "level": "A2", "topic": "Too / Enough", "instruction": "Ligue cada situação à frase que explica o problema.", "explain": "Too indica excesso; enough indica falta quando está na negativa (not tall enough, not enough chairs).", "left": ["I can't buy this jacket.", "We can't all sit down.", "I can't sleep.", "The kids can't go on the ride."], "right": ["There's too much noise.", "They aren't tall enough.", "It's too expensive.", "There aren't enough chairs."], "correctMap": [2, 3, 0, 1], "id": "bkA2-1037"}, {"type": "odd", "level": "A2", "topic": "Too / Enough", "instruction": "Encontre a expressão que está incorreta.", "explain": "Enough vem antes de substantivos (enough money), mas depois de adjetivos (big enough, não \"enough big\").", "prompt": "Which expression is incorrect?", "options": ["enough money", "enough big", "enough time", "enough chairs"], "correctIndex": 1, "id": "bkA2-1038"}, {"type": "blank", "level": "A2", "topic": "Too / Enough", "instruction": "Complete com too ou enough.", "explain": "Too vem antes do adjetivo e mostra que passou do limite: \"too young\" para um filme de adultos.", "prompt": "She is ___ young to watch this movie. It's for adults.", "accept": ["too"], "id": "bkA2-1039"}, {"type": "choose", "level": "A2", "topic": "Too / Enough", "instruction": "Escolha a opção correta em cada par de colchetes.", "explain": "Enough vem depois do adjetivo (tall enough) e antes do substantivo (enough apples).", "prompt": "He's [tall enough*/enough tall/too tall] to reach the shelf, and we bought [enough*/too/very] apples for the party.", "id": "bkA2-1040"}, {"type": "error", "level": "A2", "topic": "Too / Enough", "instruction": "Encontre o erro e corrija.", "explain": "Enough vem depois do adjetivo: \"warm enough\".", "sentence": "The water isn't enough warm to swim.", "wrong": "enough warm", "fix": ["warm enough"], "id": "bkA2-1041"}, {"type": "rewrite", "level": "A2", "topic": "Too / Enough", "instruction": "Una as duas frases com too + to + verbo, começando com \"The tea is\".", "explain": "Too + adjetivo + to + verbo mostra que o excesso impede a ação.", "prompt": "The tea is very hot. I can't drink it.", "accept": ["The tea is too hot to drink.", "The tea is too hot for me to drink."], "id": "bkA2-1042", "start": "The tea is"}, {"type": "mcq", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Escolha a preposição correta.", "explain": "Behind = atrás de. Com um só objeto (the sofa), between não funciona.", "prompt": "The cat is hiding ___ the sofa, so I can't see it.", "options": ["between", "behind", "through", "onto"], "correctIndex": 1, "id": "bkA2-1043"}, {"type": "gaps", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Complete as direções com uma preposição.", "explain": "Walk down / along a street; go past um lugar; across from = do outro lado; between = entre dois lugares.", "prompt": "A: Excuse me, where is the post office?\nB: Walk ___ this street and go ___ the bank. The post office is ___ from the park, ___ the pharmacy and the school.", "answers": [["down", "along", "up"], ["past", "by"], ["across"], ["between"]], "id": "bkA2-1044"}, {"type": "choose", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Escolha a opção correta em cada par de colchetes.", "explain": "At diz onde você está; to indica o destino de um movimento (going to).", "prompt": "I'm [at*/to/into] the supermarket now. Later, I'm going [to*/at/in] the bank.", "id": "bkA2-1045"}, {"type": "error", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Encontre o erro e corrija.", "explain": "Home não leva to: \"went home\".", "sentence": "We went to home after the movie.", "wrong": "to home", "fix": ["home"], "id": "bkA2-1046"}, {"type": "rewrite", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Reescreva a frase com o sentido contrário, usando out of.", "explain": "Into = para dentro; o oposto é out of = para fora.", "prompt": "He walked into the shop.", "accept": ["He walked out of the shop."], "id": "bkA2-1047"}, {"type": "order", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Ordene as palavras para formar uma instrução.", "explain": "A instrução começa com o verbo: go past the church (passando pela igreja), depois turn left.", "words": ["Go", "past", "the", "church", "and", "turn", "left"], "id": "bkA2-1048"}, {"type": "tf", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que o prédio fica entre uma padaria e uma floricultura, que o parque fica do outro lado da rua e que Mia atravessa o parque todas as manhãs.", "text": "Mia's apartment is on Oak Street. It is between a bakery and a flower shop. Across from the building there is a small park. Every morning Mia walks through the park to the bus stop, and after work she goes straight home.", "items": [{"s": "Mia's building is between two shops.", "a": true}, {"s": "The bakery is across from her building.", "a": false}, {"s": "Mia walks through the park every morning.", "a": true}, {"s": "After work, Mia stops at the bank.", "a": false}], "id": "bkA2-1049"}, {"type": "match", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Ligue cada preposição ao seu significado.", "explain": "Across = de um lado ao outro; through = por dentro; along = ao longo de; past = passando por.", "left": ["across", "through", "along", "past"], "right": ["ao longo de", "passando por", "de um lado ao outro", "por dentro de"], "correctMap": [2, 3, 0, 1], "id": "bkA2-1050"}, {"type": "sort", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Separe as expressões entre lugar (onde algo está) e movimento (para onde vai).", "explain": "Under, behind, next to e in front of dizem a posição; into, out of, onto e past descrevem movimento.", "prompt": "Place or movement?", "groups": ["Lugar", "Movimento"], "items": [{"w": "under", "g": 0}, {"w": "behind", "g": 0}, {"w": "next to", "g": 0}, {"w": "in front of", "g": 0}, {"w": "into", "g": 1}, {"w": "out of", "g": 1}, {"w": "onto", "g": 1}, {"w": "past", "g": 1}], "id": "bkA2-1051"}, {"type": "mcq", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Escolha a preposição correta.", "explain": "Across = de um lado ao outro da rua.", "prompt": "Be careful when you walk ___ the street. Look both ways.", "options": ["across", "at", "under", "next"], "correctIndex": 0, "id": "bkA2-1052"}, {"type": "choose", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Escolha a opção correta em cada par de colchetes.", "explain": "Out of = para fora de; onto = para cima de uma superfície.", "prompt": "She took her keys [out of*/into/onto] her bag, and the dog jumped [onto*/into/across] the sofa.", "id": "bkA2-1053"}, {"type": "error", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Encontre o erro e corrija.", "explain": "Para sair de um lugar, usamos \"out of\", não só \"out\".", "sentence": "The dog ran out the house when I opened the door.", "wrong": "out", "fix": ["out of"], "id": "bkA2-1054"}, {"type": "blank", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Complete com uma preposição.", "explain": "Through = por dentro de (túnel, parque).", "prompt": "We drove ___ the tunnel and came out on the other side.", "accept": ["through"], "id": "bkA2-1055"}, {"type": "rewrite", "level": "A2", "topic": "Preposições de lugar e movimento", "instruction": "Reescreva a frase trocando \"in front of\" por \"behind\".", "explain": "Behind (atrás de) é o oposto de in front of (na frente de).", "prompt": "The bus stop is in front of the library.", "accept": ["The bus stop is behind the library."], "id": "bkA2-1056"}, {"type": "mcq", "level": "B1", "topic": "Past Perfect", "instruction": "Escolha a opção correta.", "explain": "A ação \"start\" aconteceu antes de \"we arrived\", então usamos Past Perfect: had + particípio.", "prompt": "When we arrived at the cinema, the film ___ already started.", "options": ["has", "was", "had", "did"], "correctIndex": 2, "id": "bkB1-1001"}, {"type": "gaps", "level": "B1", "topic": "Past Perfect", "instruction": "Complete com o Past Perfect do verbo entre parênteses.", "explain": "Past Perfect = had + particípio (had left); negativa = hadn't arrived; had never met mostra algo que nunca tinha acontecido até aquele momento.", "prompt": "A: Did you see Leo at the party?\nB: No. When I got there, he ___ (leave) already.\nA: And Sofia?\nB: She ___ (not / arrive) yet, so I talked to Mark.\nA: Mark? I ___ (never / meet) him before that day.", "answers": [["had left", "'d left"], ["hadn't arrived", "had not arrived"], ["had never met", "'d never met"]], "id": "bkB1-1002"}, {"type": "choose", "level": "B1", "topic": "Past Perfect", "instruction": "Escolha a opção correta em cada par de colchetes.", "explain": "A ação anterior fica no Past Perfect (had left, had passed); a mais recente fica no Simple Past (called).", "prompt": "By the time I called, they [had left*/have left/leave] home. I was happy because I [had passed*/have passed/pass] the test.", "id": "bkB1-1003"}, {"type": "error", "level": "B1", "topic": "Past Perfect", "instruction": "Encontre o erro e corrija.", "explain": "A ação \"o trem partiu\" veio antes de \"chegamos\", então precisa de had + particípio.", "sentence": "When we got to the station, the train already left.", "wrong": "left", "fix": ["had left", "'d left"], "id": "bkB1-1004"}, {"type": "rewrite", "level": "B1", "topic": "Past Perfect", "instruction": "Una as frases com When, começando com \"When I arrived,\". Mostre qual ação veio primeiro.", "explain": "A ação que veio primeiro (Tom saiu) vai no Past Perfect; a mais recente (I arrived) fica no Simple Past.", "prompt": "Tom left the house. Then I arrived.", "start": "When I arrived,", "accept": ["When I arrived, Tom had left the house.", "When I arrived, Tom had left."], "id": "bkB1-1005"}, {"type": "order", "level": "B1", "topic": "Past Perfect", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Na pergunta com Past Perfect, had vem antes do sujeito: \"Had they already eaten...?\"", "words": ["Had", "they", "already", "eaten", "when", "you", "got", "home"], "id": "bkB1-1006"}, {"type": "tf", "level": "B1", "topic": "Past Perfect", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O avião já tinha pousado, Carla esperava havia vinte minutos e o primo tinha ido ao terminal errado.", "text": "Last Friday, Carla went to the airport to meet her cousin. When she got there, his plane had already landed, but he wasn't in the arrivals hall. She had been waiting for twenty minutes when her phone rang. Her cousin had gone to the wrong terminal!", "items": [{"s": "The plane had not landed when Carla arrived.", "a": false}, {"s": "Carla had waited about twenty minutes when her phone rang.", "a": true}, {"s": "Her cousin had gone to the wrong terminal.", "a": true}, {"s": "Carla arrived before the plane landed.", "a": false}], "id": "bkB1-1007"}, {"type": "mcq", "level": "B1", "topic": "Past Perfect", "instruction": "Escolha a opção correta.", "explain": "Ela estava chateada por algo que aconteceu antes: Past Perfect (had forgotten).", "prompt": "Paula was upset because she ___ her passport at home.", "options": ["forgets", "had forgotten", "has forgotten", "would forget"], "correctIndex": 1, "id": "bkB1-1008"}, {"type": "match", "level": "B1", "topic": "Past Perfect", "instruction": "Ligue cada situação ao motivo correto.", "explain": "O motivo aconteceu antes da situação, por isso usa Past Perfect: had spilled, hadn't eaten, had planted, had lost.", "left": ["He was very hungry", "I couldn't open the door", "The garden looked wonderful", "The kitchen floor was wet"], "right": ["because the kids had spilled some juice.", "because he hadn't eaten all day.", "because she had planted new flowers.", "because I had lost my key."], "correctMap": [1, 3, 2, 0], "id": "bkB1-1009"}, {"type": "dorder", "level": "B1", "topic": "Past Perfect", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Primeiro o problema, depois a pergunta com Had you..., a resposta curta e a explicação com Past Perfect.", "lines": ["A: You look upset. What happened?", "B: I lost my wallet on the way to work.", "A: Had you checked your bag before you left home?", "B: Yes, I had. I'm sure I'd put it in my bag."], "id": "bkB1-1010"}, {"type": "blank", "level": "B1", "topic": "Past Perfect", "instruction": "Complete com a forma correta de had.", "explain": "Ela não quis almoçar porque já tinha comido: had + eaten.", "prompt": "Sara didn't want any lunch because she ___ already eaten.", "accept": ["had", "'d"], "id": "bkB1-1011"}, {"type": "choose", "level": "B1", "topic": "Past Perfect", "instruction": "Escolha a opção correta em cada par de colchetes.", "explain": "Had been waiting (ação longa até um momento do passado) e arrived (ação mais recente, Simple Past).", "prompt": "She [had been*/has been/was being] waiting for an hour when he finally [arrived*/had arrived/arrive].", "id": "bkB1-1012"}, {"type": "error", "level": "B1", "topic": "Past Perfect", "instruction": "Encontre o erro e corrija.", "explain": "Depois de had, usamos o particípio passado: seen, não saw.", "sentence": "I had never saw snow before I moved to Canada.", "wrong": "saw", "fix": ["seen"], "id": "bkB1-1013"}, {"type": "rewrite", "level": "B1", "topic": "Past Perfect", "instruction": "Reescreva a frase na forma negativa.", "explain": "Na negativa do Past Perfect, usamos hadn't / had not + particípio.", "prompt": "She had seen that film before.", "accept": ["She hadn't seen that film before.", "She had not seen that film before."], "id": "bkB1-1014"}, {"type": "mcq", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Escolha a opção correta.", "explain": "Atividade que acabou de parar e explica o cansaço: have been + -ing.", "prompt": "I'm tired because I ___ all morning.", "options": ["clean", "am cleaning", "have been cleaning", "did clean"], "correctIndex": 2, "id": "bkB1-1015"}, {"type": "gaps", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Complete com o Present Perfect Continuous.", "explain": "Pergunta: Have you been + -ing?; negativa: haven't been + -ing; afirmativa: have / 've been + -ing.", "prompt": "A: You look tired. ___ you been sleeping well?\nB: No, I ___ (not / sleep) well since Monday. I ___ (work) late every night.", "answers": [["Have"], ["haven't been sleeping", "have not been sleeping"], ["have been working", "'ve been working"]], "id": "bkB1-1016"}, {"type": "choose", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Escolha a opção correta em cada par de colchetes.", "explain": "Have/has been + -ing para duração até agora; na pergunta, have vem antes do sujeito.", "prompt": "I [have been studying*/have studying/am studied] English for three years. How long [have you been living*/do you live/you have lived] here?", "id": "bkB1-1017"}, {"type": "error", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Encontre o erro e corrija.", "explain": "Depois de \"has been\", usamos o verbo com -ing: raining.", "sentence": "It has been rain since this morning.", "wrong": "rain", "fix": ["raining"], "id": "bkB1-1018"}, {"type": "rewrite", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Reescreva a frase usando Present Perfect Continuous e since.", "explain": "Para uma ação que começou no passado e continua, usamos have been + -ing com since + ponto de partida.", "prompt": "I started working here in 2019.", "accept": ["I've been working here since 2019.", "I have been working here since 2019."], "id": "bkB1-1019"}, {"type": "order", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "How long + have + sujeito + been + verbo com -ing.", "words": ["How", "long", "have", "you", "been", "learning", "to", "drive"], "id": "bkB1-1020"}, {"type": "tf", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que Dan trabalha na padaria há oito anos, que Eva começou na segunda e que ele está cansado porque assa pão desde as quatro da manhã.", "text": "Dan is a baker. He has been working in the same bakery for eight years. This week he has been training a new assistant, Eva. She started on Monday. Today Dan is tired because he has been baking bread since four o'clock in the morning.", "items": [{"s": "Dan has worked at the same bakery for eight years.", "a": true}, {"s": "Eva started this week.", "a": true}, {"s": "Dan has been baking since noon.", "a": false}, {"s": "Dan has been training Eva since last month.", "a": false}], "id": "bkB1-1021"}, {"type": "mcq", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Escolha a opção correta.", "explain": "Since Monday indica duração até agora: has been studying.", "prompt": "She ___ for her exam since Monday.", "options": ["has been studying", "studies", "studied", "is studying"], "correctIndex": 0, "id": "bkB1-1022"}, {"type": "match", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Ligue cada situação à explicação provável.", "explain": "O Present Perfect Continuous explica sinais no presente: mãos sujas (pintando), cansaço (correndo), olhos vermelhos (chorando), rua molhada (chovendo).", "left": ["Why are your hands so dirty?", "You look exhausted!", "Your eyes are red.", "The streets are wet."], "right": ["Have you been crying?", "It's been raining all night.", "Yes, I've been running since six.", "I've been painting the fence."], "correctMap": [3, 2, 0, 1], "id": "bkB1-1023"}, {"type": "sort", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Separe as frases: atividade/duração (continuous) ou resultado/estado (simple).", "explain": "Been + -ing destaca a atividade; o Present Perfect simples mostra resultado, quantidade ou verbos de estado (know).", "prompt": "Activity or result?", "groups": ["Atividade (been + -ing)", "Resultado / estado (simples)"], "items": [{"w": "She's been painting the kitchen.", "g": 0}, {"w": "She's painted two walls.", "g": 1}, {"w": "I've known Tom for years.", "g": 1}, {"w": "We've been waiting for an hour.", "g": 0}, {"w": "He's written five emails.", "g": 1}, {"w": "They've been dancing all night.", "g": 0}], "id": "bkB1-1024"}, {"type": "blank", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Complete com for ou since.", "explain": "Since vem antes de um ponto no tempo (two o'clock); for vem antes de um período.", "prompt": "I've been waiting for you ___ two o'clock.", "accept": ["since"], "id": "bkB1-1025"}, {"type": "choose", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Escolha a opção correta em cada par de colchetes.", "explain": "Know é verbo de estado e usa Present Perfect simples; a leitura contínua de toda a semana usa has been reading.", "prompt": "I [have known*/have been knowing/am knowing] Rita since school. She [has been reading*/is reading/read] that book all week.", "id": "bkB1-1026"}, {"type": "error", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Encontre o erro e corrija.", "explain": "Know é verbo de estado e não é usado no contínuo: \"has known\".", "sentence": "She has been know him for years.", "wrong": "been know", "fix": ["known"], "id": "bkB1-1027"}, {"type": "rewrite", "level": "B1", "topic": "Present Perfect Continuous", "instruction": "Reescreva a frase na forma negativa.", "explain": "Na negativa: haven't / have not been + -ing.", "prompt": "They have been playing football lately.", "accept": ["They haven't been playing football lately.", "They have not been playing football lately."], "id": "bkB1-1028"}, {"type": "mcq", "instruction": "Escolha a opção correta.", "explain": "Proibição (regra estrita) é expressa com \"mustn't\"; \"don't have to\" significaria que não é necessário.", "prompt": "Visitors ___ touch the paintings. It is strictly forbidden.", "options": ["don't have to", "mustn't", "doesn't have to", "didn't have to"], "correctIndex": 1, "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1029"}, {"type": "mcq", "instruction": "Escolha a opção correta.", "explain": "\"Yesterday\" indica passado, e \"must\" não tem passado: usamos \"had to\".", "prompt": "Yesterday Marta ___ stay late at the office because of an urgent meeting.", "options": ["must", "has to", "have to", "had to"], "correctIndex": 3, "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1030"}, {"type": "gaps", "instruction": "Complete com have to, has to, do ou does.", "explain": "Com \"I\" usamos \"have to\"; na pergunta com \"she\" usamos \"Does ... have to\" (o verbo volta à forma base).", "prompt": "A: Why are you leaving so early?\nB: I ___ pick up my daughter at five.\nA: ___ she ___ take the bus home?\nB: No, she doesn't. I'll drive.", "answers": [["have to"], ["Does"], ["have to"]], "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1031"}, {"type": "choose", "instruction": "Escolha a opção correta em cada lacuna.", "explain": "Proibido = \"mustn't\"; feriado significa que não é necessário acordar cedo = \"don't have to\".", "prompt": "You [mustn't*/don't have to] use your phone during the exam. It is against the rules. Tomorrow is a holiday, so we [mustn't/don't have to*] get up early.", "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1032"}, {"type": "choose", "instruction": "Escolha a opção correta em cada lacuna.", "explain": "Passado: \"had to\" (must não tem passado). Futuro: \"will have to\" (must não tem futuro próprio).", "prompt": "Last week I [must/had to*] renew my passport, and next month my brother [will must/will have to*] do the same.", "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1033"}, {"type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Com \"she\" a negativa de have to usa \"doesn't\" (does + not), não \"don't\".", "sentence": "She don't have to wear a uniform at her new school.", "wrong": "don't", "fix": ["doesn't", "does not"], "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1034"}, {"type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Depois de \"Did\", o verbo fica na forma base: \"Did you have to...?\".", "sentence": "Did you had to show your passport at the airport?", "wrong": "had", "fix": ["have"], "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1035"}, {"type": "rewrite", "instruction": "Reescreva a frase com \"doesn't have to\" (não é necessário).", "explain": "\"Not necessary\" = \"don't / doesn't have to\"; com Ben (he) usamos \"doesn't\".", "prompt": "It is not necessary for Ben to come to the meeting.", "accept": ["Ben doesn't have to come to the meeting.", "Ben does not have to come to the meeting."], "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1036"}, {"type": "rewrite", "instruction": "Reescreva a frase no passado, trocando today por yesterday.", "explain": "O passado de \"have to\" é \"had to\".", "prompt": "I have to finish this essay today.", "accept": ["I had to finish this essay yesterday.", "Yesterday I had to finish this essay.", "Yesterday, I had to finish this essay."], "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1037"}, {"type": "order", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Pergunta com have to: Does + sujeito + have to + verbo base.", "words": ["Does", "your", "sister", "have", "to", "wear", "glasses"], "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1038"}, {"type": "tf", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que Lena usa uniforme, não precisa trabalhar nos fins de semana, começa às seis amanhã e que visitantes não podem usar celular.", "text": "Lena works at a hospital. She has to wear a uniform, but she doesn't have to work on weekends. Tomorrow she has to start at six because a colleague is sick. Visitors mustn't use their phones in the intensive care unit.", "items": [{"s": "Lena has to wear a uniform.", "a": true}, {"s": "Lena has to work every weekend.", "a": false}, {"s": "Lena starts work at six tomorrow.", "a": true}, {"s": "Visitors are allowed to use phones in the intensive care unit.", "a": false}], "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1039"}, {"type": "match", "instruction": "Ligue cada situação à frase correta.", "explain": "Proibição = mustn't; grátis = don't have to; passado = had to; obrigação externa = has to.", "left": ["The sign says no photos in the museum.", "Entry to the park is free.", "Mia's flight leaves at 6 a.m.", "Yesterday the train was cancelled."], "right": ["You don't have to pay.", "We had to take a taxi.", "You mustn't take photos.", "She has to get up very early."], "correctMap": [2, 0, 3, 1], "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1040"}, {"type": "sort", "instruction": "Separe as situações de acordo com a frase que combina com cada uma.", "explain": "Quando algo é proibido usamos mustn't; quando é opcional ou grátis, don't have to.", "prompt": "Which sentence fits: \"You mustn't...\" or \"You don't have to...\"?", "groups": ["mustn't", "don't have to"], "items": [{"w": "No entry after 10 p.m.", "g": 0}, {"w": "Tickets are free for students", "g": 1}, {"w": "Swimming is not allowed in the lake", "g": 0}, {"w": "The buffet is all-inclusive", "g": 1}, {"w": "Dogs are banned from the shop", "g": 0}, {"w": "The test is optional", "g": 1}], "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1041"}, {"type": "blank", "instruction": "Complete a lacuna: não é necessário.", "explain": "Como o ônibus é grátis, não é necessário pagar: \"doesn't have to\" (com \"he\").", "prompt": "My brother is a student, so he ___ pay for the bus. It is free for him.", "accept": ["doesn't have to", "does not have to", "doesn't need to", "does not need to", "needn't"], "level": "B1", "topic": "Obrigação e necessidade (have to, must, need)", "id": "bkB1-1042"}, {"type": "mcq", "instruction": "Escolha a opção correta.", "explain": "\"Cold morning\" é adjetivo + substantivo contável no singular: usamos \"such a\".", "prompt": "It was ___ cold morning that the lake froze.", "options": ["so", "such", "such a", "so a"], "correctIndex": 2, "level": "B1", "topic": "So / Such", "id": "bkB1-1043"}, {"type": "mcq", "instruction": "Escolha a opção correta.", "explain": "\"People\" é contável no plural: \"so many\". \"So much\" é para incontáveis.", "prompt": "There were ___ people at the concert that we couldn't find our friends.", "options": ["so much", "so many", "such much", "such a"], "correctIndex": 1, "level": "B1", "topic": "So / Such", "id": "bkB1-1044"}, {"type": "gaps", "instruction": "Complete com so ou such.", "explain": "\"Such a\" + substantivo; \"so\" + adjetivo; \"so much\" + incontável.", "prompt": "A: How was the hotel?\nB: It was ___ a beautiful place! The rooms were ___ big, and the staff were ___ friendly that they remembered our names.\nA: I'm sure you had ___ much fun!", "answers": [["such"], ["so"], ["so"], ["so"]], "level": "B1", "topic": "So / Such", "id": "bkB1-1045"}, {"type": "choose", "instruction": "Escolha a opção correta em cada lacuna.", "explain": "So + adjetivo (difficult). Com substantivo singular contável (test) usamos \"such a/an\".", "prompt": "The exam was [so*/such] difficult that nobody finished it. It was [so/such an*] unusual test.", "level": "B1", "topic": "So / Such", "id": "bkB1-1046"}, {"type": "choose", "instruction": "Escolha a opção correta em cada lacuna.", "explain": "\"Work\" é incontável: so much. \"Emails\" é contável no plural: so many.", "prompt": "I have [so much*/so many] work today, and there are [so much/so many*] emails to answer.", "level": "B1", "topic": "So / Such", "id": "bkB1-1047"}, {"type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Antes de substantivo (a kind person) usamos \"such a\", não \"so a\".", "sentence": "She is so a kind person that everybody loves her.", "wrong": "so a", "fix": ["such a"], "level": "B1", "topic": "So / Such", "id": "bkB1-1048"}, {"type": "error", "instruction": "Encontre o erro e corrija.", "explain": "\"Fun\" é incontável e \"such much\" não existe; a forma correta é \"so much\".", "sentence": "We had such much fun at the party last night.", "wrong": "such much", "fix": ["so much"], "level": "B1", "topic": "So / Such", "id": "bkB1-1049"}, {"type": "rewrite", "instruction": "Junte as frases usando so ... that.", "explain": "So + adjetivo + that mostra a consequência.", "prompt": "The film was very boring. I fell asleep.", "accept": ["The film was so boring that I fell asleep.", "The film was so boring I fell asleep."], "level": "B1", "topic": "So / Such", "id": "bkB1-1050"}, {"type": "rewrite", "instruction": "Junte as frases usando such ... that.", "explain": "Such a/an + adjetivo + substantivo + that mostra a consequência.", "prompt": "It was a very hot day. We stayed in the water all afternoon.", "accept": ["It was such a hot day that we stayed in the water all afternoon.", "It was such a hot day we stayed in the water all afternoon."], "level": "B1", "topic": "So / Such", "id": "bkB1-1051"}, {"type": "order", "instruction": "Ordene as palavras para formar uma frase.", "explain": "So + advérbio (fast) + that + consequência.", "words": ["She", "speaks", "so", "fast", "that", "nobody", "understands", "her"], "level": "B1", "topic": "So / Such", "id": "bkB1-1052"}, {"type": "tf", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que a paisagem era linda, o país era frio, as pessoas eram simpáticas e a viagem foi cara demais.", "text": "Last summer, Daniel went to Iceland. The landscape was so beautiful that he took more than a thousand photos. It was such a cold country that he wore a coat even in July. He met such friendly people at his hostel, and they cooked dinner together every night. The trip was so expensive that he can't travel again this year.", "items": [{"s": "Daniel took a lot of photos.", "a": true}, {"s": "The weather in Iceland was warm in July.", "a": false}, {"s": "The people at the hostel were friendly.", "a": true}, {"s": "The trip was cheap.", "a": false}], "level": "B1", "topic": "So / Such", "id": "bkB1-1053"}, {"type": "match", "instruction": "Ligue o início de cada frase ao final correto.", "explain": "O sentido de cada consequência combina com a situação; a estrutura so/such + that é a mesma.", "left": ["The soup was so hot", "It was such a long film", "She has so many friends", "They had such good seats"], "right": ["that her phone never stops ringing.", "that I burned my tongue.", "that they could see everything.", "that we took a break."], "correctMap": [1, 3, 0, 2], "level": "B1", "topic": "So / Such", "id": "bkB1-1054"}, {"type": "sort", "instruction": "Separe as palavras de acordo com o que vem antes delas.", "explain": "So vem antes de adjetivo ou advérbio sozinhos; such vem antes de substantivo (com ou sem adjetivo).", "prompt": "Which word goes before them: so or such?", "groups": ["so", "such"], "items": [{"w": "tired", "g": 0}, {"w": "a great idea", "g": 1}, {"w": "quickly", "g": 0}, {"w": "nice weather", "g": 1}, {"w": "expensive", "g": 0}, {"w": "lovely people", "g": 1}, {"w": "an easy test", "g": 1}, {"w": "carefully", "g": 0}], "level": "B1", "topic": "So / Such", "id": "bkB1-1055"}, {"type": "blank", "instruction": "Complete com so ou such.", "explain": "\"Traffic\" é incontável: so much traffic.", "prompt": "There was ___ much traffic that we missed the flight.", "accept": ["so"], "level": "B1", "topic": "So / Such", "id": "bkB1-1056"}, {"type": "mcq", "instruction": "Escolha a opção correta.", "explain": "\"This time next week\" indica ação em andamento no futuro: Future Continuous (will be + -ing).", "prompt": "This time next week, I ___ on a beach in Bahia.", "options": ["will have lain", "lay", "will be lying", "have been lying"], "correctIndex": 2, "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1001"}, {"type": "mcq", "instruction": "Escolha a opção correta.", "explain": "\"By the time ... Saturday\" indica uma ação concluída antes de um ponto futuro: Future Perfect (will have + particípio). As outras opções não expressam conclusão antes desse momento.", "prompt": "Our team ___ the project by the time the client visits on Saturday.", "options": ["will have finished", "will be finishing", "is finishing", "finishes"], "correctIndex": 0, "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1002"}, {"type": "gaps", "instruction": "Complete com Future Continuous ou Future Perfect dos verbos entre parênteses.", "explain": "\"At eight\" pede ação em andamento (will be working); \"by ten\" pede ação concluída (will have + particípio).", "prompt": "A: Will you be at home at eight tomorrow?\nB: No, I ___ (work) at the clinic at eight. But I ___ (finish) by ten, so call me then.\nA: OK. I'll be in the kitchen from six, so by ten I ___ (cook) three dishes!", "answers": [["will be working", "'ll be working"], ["will have finished", "'ll have finished"], ["will have cooked", "'ll have cooked"]], "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1003"}, {"type": "choose", "instruction": "Escolha a opção correta em cada lacuna.", "explain": "Às nove ainda estará dormindo (continuous); ao meio-dia já terá acordado (perfect, com \"by then\").", "prompt": "Don't call me at nine tomorrow. I [will be sleeping*/will have slept] then. Call me at noon; by then I [will have woken*/will be waking] up and had breakfast.", "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1004"}, {"type": "choose", "instruction": "Escolha a opção correta em cada lacuna.", "explain": "Duração com \"for five years\" até um momento futuro: will have been + -ing. \"By Monday\" indica conclusão: will have finished.", "prompt": "Next June, they [will have been living*/will live] in Canada for five years. The builders [will have finished*/will be finishing] by Monday.", "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1005"}, {"type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Depois de \"by the time\" usamos o presente, não \"will\".", "sentence": "By the time you will get here, we'll have eaten.", "wrong": "will get", "fix": ["get"], "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1006"}, {"type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Future Continuous é \"will be + -ing\": \"will be flying\".", "sentence": "This time tomorrow, I will be fly to Lisbon.", "wrong": "fly", "fix": ["flying"], "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1007"}, {"type": "rewrite", "instruction": "Reescreva a frase com Future Continuous (will be + -ing).", "explain": "Ação em andamento num momento futuro: will be teaching.", "prompt": "At ten tomorrow, I teach a class.", "accept": ["At ten tomorrow, I will be teaching a class.", "At ten tomorrow, I'll be teaching a class.", "At ten tomorrow I will be teaching a class.", "At ten tomorrow I'll be teaching a class."], "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1008"}, {"type": "rewrite", "instruction": "Reescreva a frase com Future Perfect, começando com By Friday.", "explain": "Ação concluída até um prazo: will have + particípio.", "prompt": "I will finish the report before Friday.", "accept": ["By Friday, I will have finished the report.", "By Friday, I'll have finished the report.", "By Friday I will have finished the report.", "By Friday I'll have finished the report."], "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1009", "start": "By Friday,"}, {"type": "order", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Future Perfect: will have + particípio (saved), com \"By next year\" como marcador.", "words": ["By", "next", "year", "she", "will", "have", "saved", "enough", "money"], "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1010", "alt": ["She will have saved enough money by next year"]}, {"type": "tf", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que ele estará dirigindo segunda às oito, já terá levado passageiros ao meio-dia e terá 20 anos de profissão em março; ele pretende se aposentar depois disso.", "text": "Mr. Silva is a bus driver. Next Monday at eight, he will be driving his usual route through the city. By noon, he will have taken about two hundred passengers to work. In March he will have been driving buses for twenty years, and he plans to retire the following year.", "items": [{"s": "Mr. Silva will be driving on Monday at eight.", "a": true}, {"s": "He will not have taken any passengers by noon.", "a": false}, {"s": "In March he will have worked as a driver for twenty years.", "a": true}, {"s": "He plans to stop driving buses before he completes twenty years.", "a": false}], "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1011"}, {"type": "match", "instruction": "Ligue o início de cada frase ao final correto.", "explain": "O verbo no final precisa combinar com a estrutura: will be + -ing, will have + particípio, will have been + -ing.", "left": ["At midnight tonight, we'll be", "By midnight tonight, we'll have", "By next month, she'll have been", "Will you be"], "right": ["living here for a year.", "using the printer this afternoon?", "watching the fireworks.", "watched all three episodes."], "correctMap": [2, 3, 0, 1], "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1012"}, {"type": "sort", "instruction": "Separe as formas verbais nos dois tempos.", "explain": "Future Continuous: will be + -ing. Future Perfect: will have + particípio.", "prompt": "Future Continuous or Future Perfect?", "groups": ["Future Continuous", "Future Perfect"], "items": [{"w": "will be sleeping", "g": 0}, {"w": "will have slept", "g": 1}, {"w": "will be waiting", "g": 0}, {"w": "will have arrived", "g": 1}, {"w": "will be working", "g": 0}, {"w": "will have finished", "g": 1}, {"w": "will be driving", "g": 0}, {"w": "will have cleaned", "g": 1}], "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1013"}, {"type": "blank", "instruction": "Complete a lacuna.", "explain": "Duração até um momento futuro (\"for five years\"): will have been + -ing.", "prompt": "By December, I will ___ studying English for five years.", "accept": ["have been"], "level": "B2", "topic": "Future Continuous & Future Perfect", "id": "bkB2-1014"}, {"type": "mcq", "instruction": "Escolha a opção correta.", "explain": "A ação de terminar vem antes de enviar: usamos \"Having + particípio\".", "prompt": "___ the report, he sent it to the manager.", "options": ["Finished", "To finish", "Having finished", "Finish"], "correctIndex": 2, "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1015"}, {"type": "mcq", "instruction": "Escolha a opção correta.", "explain": "Oração relativa reduzida ativa: \"students who study\" vira \"students studying\".", "prompt": "The students ___ in the library are preparing for exams.", "options": ["studied", "studying", "to study", "having studied"], "correctIndex": 1, "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1016"}, {"type": "gaps", "instruction": "Complete com a forma correta do verbo entre parênteses (-ing, particípio ou having + particípio).", "explain": "Sentido passivo = particípio (found); ação anterior = having + particípio; ação simultânea = -ing.", "prompt": "1. The vase ___ (find) in the attic is very old.\n2. ___ (live) in Spain for years, Ana speaks Spanish fluently.\n3. ___ (wait) for the bus, I read the news.", "answers": [["found"], ["Having lived"], ["Waiting"]], "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1017"}, {"type": "choose", "instruction": "Escolha a opção correta em cada lacuna.", "explain": "O livro foi escrito (passivo): \"Written\". A pessoa abre a caixa (ativo): \"Opening\".", "prompt": "[Written*/Writing] in simple English, the book is easy for beginners. [Opening*/Opened] the box, she found a letter.", "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1018"}, {"type": "choose", "instruction": "Escolha a opção correta em cada lacuna.", "explain": "O queijo é produzido (passivo): \"produced\". As crianças estão brincando (ativo): \"playing\".", "prompt": "The cheese [producing/produced*] in this region is exported. The kids [playing*/played] in the garden are my neighbours' children.", "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1019"}, {"type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Depois de \"Having\" usamos o particípio passado: \"finished\".", "sentence": "Having finish the report, he went home.", "wrong": "finish", "fix": ["finished"], "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1020"}, {"type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Os livros foram escritos por Tolkien (sentido passivo), então usamos o particípio \"written\".", "sentence": "The books writing by Tolkien are famous.", "wrong": "writing", "fix": ["written"], "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1021"}, {"type": "rewrite", "instruction": "Reescreva a frase usando uma participle clause com -ing.", "explain": "\"Because she felt nervous\" vira \"Feeling nervous\" (mesmo sujeito nas duas orações).", "prompt": "Because she felt nervous, she checked her notes again.", "accept": ["Feeling nervous, she checked her notes again."], "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1022"}, {"type": "rewrite", "instruction": "Reescreva a frase com uma participle clause, começando com Having.", "explain": "Ação anterior: Having + particípio passado (eaten).", "prompt": "After he had eaten breakfast, he left for work.", "accept": ["Having eaten breakfast, he left for work."], "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1023", "start": "Having"}, {"type": "order", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Forma negativa da participle clause: Not + -ing.", "words": ["Not", "knowing", "the", "way", "he", "asked", "a", "policeman"], "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1024", "alt": ["He asked a policeman not knowing the way"]}, {"type": "tf", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "Marco nasceu num vilarejo, abriu a loja depois de estudar design, as roupas são feitas na Itália e a cantora comprou três jaquetas.", "text": "Born in a small village, Marco moved to Milan at eighteen. Having studied design, he opened his own shop. The clothes sold in his shop are made in Italy. Impressed by the quality, a famous singer bought three jackets.", "items": [{"s": "Marco was born in Milan.", "a": false}, {"s": "Marco opened his shop after he studied design.", "a": true}, {"s": "The clothes in the shop are made in Italy.", "a": true}, {"s": "The singer bought only one jacket.", "a": false}], "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1025"}, {"type": "match", "instruction": "Ligue a oração completa à versão reduzida.", "explain": "Ativo vira -ing; passivo vira particípio; ação anterior vira having + particípio.", "left": ["The man who is waiting outside", "The cake which was made by my aunt", "After she had spoken to the manager,", "Because he felt hungry,"], "right": ["Having spoken to the manager,", "Feeling hungry,", "The man waiting outside", "The cake made by my aunt"], "correctMap": [2, 3, 0, 1], "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1026"}, {"type": "sort", "instruction": "Separe as expressões de acordo com o tipo de participle clause.", "explain": "-ing: ativo/simultâneo; particípio passado: sentido passivo; having + particípio: ação anterior.", "prompt": "Which kind of participle clause is it?", "groups": ["-ing (ativo)", "particípio passado (passivo)", "having + particípio (anterior)"], "items": [{"w": "Walking along the beach", "g": 0}, {"w": "Feeling dizzy", "g": 0}, {"w": "Painted by Picasso", "g": 1}, {"w": "Made of wood", "g": 1}, {"w": "Having read the book", "g": 2}, {"w": "Having missed the bus", "g": 2}, {"w": "Written in 1850", "g": 1}, {"w": "Looking at the map", "g": 0}], "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1027"}, {"type": "blank", "instruction": "Complete com a forma correta do verbo lose.", "explain": "Ação anterior: Having + particípio passado de lose (lost).", "prompt": "Having ___ (lose) his keys, Tom couldn't open the door.", "accept": ["lost"], "level": "B2", "topic": "Participle Clauses", "id": "bkB2-1028"}, {"type": "mcq", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Escolha a forma que expressa futuro iminente.", "explain": "\"Be about to + verbo\" indica algo prestes a acontecer; as nuvens escuras sugerem que a chuva é iminente.", "prompt": "Look at those clouds! It ___ pour.", "options": ["is due to", "has yet to", "is about to", "is to be"], "correctIndex": 2, "id": "bkC1-1001"}, {"type": "mcq", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Escolha a opção que expressa o futuro no passado.", "explain": "Quando o ponto de vista é o passado e o fato se cumpriu, usa-se \"would\" para o futuro no passado.", "prompt": "She had always known she ___ become a surgeon, and eventually she did.", "options": ["will", "would", "is to", "is going to"], "correctIndex": 1, "id": "bkC1-1002"}, {"type": "gaps", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Complete com uma palavra (yet, due, set, point, verge).", "explain": "\"Has yet to\" = ainda não fez; \"is due/set to be\" = previsto; \"on the point/verge of + -ing\" = prestes a.", "prompt": "The airline has ___ to explain the delay.\nThe merger is ___ to be announced on Friday.\nHe was on the ___ of resigning when the board intervened.", "answers": [["yet"], ["due", "set"], ["point", "verge"]], "id": "bkC1-1003"}, {"type": "choose", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Escolha a opção correta em cada grupo.", "explain": "\"Be bound to\" expressa certeza; \"was to have + particípio\" indica um plano frustrado, o que combina com a cerimônia cancelada.", "prompt": "Given the band's popularity, the concert is [bound*/due/yet] to sell out. The ceremony, which [was to have*/is to have/will have] taken place on Sunday, was cancelled.", "id": "bkC1-1004"}, {"type": "error", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Encontre o erro e corrija.", "explain": "Depois de \"on the point of\" usa-se -ing, não infinitivo com to.", "sentence": "I was on the point to leave when the phone rang.", "wrong": "to leave", "fix": ["of leaving"], "id": "bkC1-1005"}, {"type": "error", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Encontre o erro e corrija.", "explain": "\"Have yet to\" exige o infinitivo com to: \"has yet to respond\".", "sentence": "The firm has yet respond to the allegations.", "wrong": "yet respond", "fix": ["yet to respond"], "id": "bkC1-1006"}, {"type": "rewrite", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Reescreva a frase com \"be about to\".", "explain": "\"Will start in a few seconds\" equivale a \"be about to + verbo base\", que indica futuro imediato.", "prompt": "The play will start in a few seconds.", "accept": ["The play is about to start.", "The play is about to begin."], "id": "bkC1-1007"}, {"type": "rewrite", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Reescreva a frase usando \"on the point of\".", "explain": "\"On the point of\" (ou \"on the verge of\") + -ing expressa algo que quase aconteceu.", "prompt": "She almost resigned, but a colleague talked her out of it.", "accept": ["She was on the point of resigning, but a colleague talked her out of it.", "She was on the verge of resigning, but a colleague talked her out of it."], "id": "bkC1-1008"}, {"type": "order", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Ordene as palavras para formar uma frase.", "explain": "\"Was/were about to + verbo base\" indica algo que estava prestes a acontecer, quando outra coisa o interrompeu.", "words": ["The", "negotiators", "were", "about", "to", "leave", "when", "the", "call", "came"], "alt": ["When the call came the negotiators were about to leave"], "id": "bkC1-1009"}, {"type": "tf", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O navio devia atracar na segunda, quase foi desviado para o Rio, deve atracar na quarta e a empresa ainda não comentou o custo.", "text": "The cargo ship Aurora was due to dock in Santos on Monday, but a storm delayed it. By Tuesday evening the captain was on the point of diverting to Rio when the weather suddenly cleared. The port authority says the ship is now set to dock early on Wednesday. The shipping company has yet to comment on the cost of the delay.", "items": [{"s": "The Aurora docked in Santos on Monday.", "a": false}, {"s": "The captain nearly changed course to Rio.", "a": true}, {"s": "The ship is expected to dock on Wednesday.", "a": true}, {"s": "The company has already discussed the cost of the delay.", "a": false}], "id": "bkC1-1010"}, {"type": "match", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Ligue cada estrutura ao seu significado.", "explain": "Be about to = prestes a; have yet to = ainda não, mas esperado; be bound to = certeza; be due to = previsto para um horário ou prazo.", "left": ["be about to", "have yet to", "be bound to", "be due to"], "right": ["ainda não ocorreu, mas é esperado", "é certo que vai acontecer", "previsto para um horário ou prazo", "prestes a acontecer"], "correctMap": [3, 0, 1, 2], "id": "bkC1-1011"}, {"type": "reading", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Leia a notícia e responda às perguntas.", "explain": "O texto diz que o sindicato exigiu garantias, que o relatório final ainda não saiu (has yet to publish) e que os funcionários vão a reuniões informativas.", "text": "Regulators are set to approve the merger of two regional airlines, SkyLink and Norvia, officials said on Tuesday. The deal, which was to have been signed in June, was delayed after union leaders demanded guarantees on jobs. Norvia's chief executive says the airlines are bound to benefit from combining their routes, but the competition authority has yet to publish its final report, which is due by the end of the month. Staff, meanwhile, are to attend briefings at their local offices from next week.", "questions": [{"q": "Why was the signing postponed?", "options": ["The regulators rejected the deal.", "Union leaders asked for job guarantees.", "The chief executive resigned."], "correctIndex": 1}, {"q": "What is still missing?", "options": ["The competition authority's final report", "A decision by the staff", "Approval from Norvia's chief executive"], "correctIndex": 0}, {"q": "What will employees do from next week?", "options": ["Sign new contracts", "Go on strike", "Attend briefings"], "correctIndex": 2}], "id": "bkC1-1012"}, {"type": "odd", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Qual frase NÃO fala de algo futuro em relação ao presente?", "explain": "\"She was on the point of crying\" fala do passado; as outras três descrevem eventos futuros ou iminentes.", "prompt": "Which sentence does not refer to the future?", "options": ["The film is about to start.", "The summit is due to begin on Monday.", "Prices are set to rise.", "She was on the point of crying."], "correctIndex": 3, "id": "bkC1-1013"}, {"type": "blank", "level": "C1", "topic": "Futuro avançado (be to, be about to, be bound to)", "instruction": "Complete a lacuna.", "explain": "\"Were to have + particípio\" expressa um plano que não se realizou.", "prompt": "We ___ to have met at six, but my flight was late.", "accept": ["were"], "id": "bkC1-1014"}, {"type": "mcq", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Escolha a forma correta do infinitivo.", "explain": "O fato (início das negociações) é anterior ao relato e a frase tem \"last year\"; por isso usa-se o infinitivo perfeito: to have started.", "prompt": "The CEO is rumored ___ negotiations with a rival last year.", "options": ["to start", "to have started", "to be started", "starting"], "correctIndex": 1, "id": "bkC1-1015"}, {"type": "mcq", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Escolha a opção que concorda com o sujeito.", "explain": "O sujeito é \"2,000 jobs\" (plural), então: \"are estimated to be\". A estrutura passiva concorda com o sujeito.", "prompt": "Over 2,000 jobs ___ to be at risk, according to union figures.", "options": ["is estimated", "estimate", "are estimated", "have estimated"], "correctIndex": 2, "id": "bkC1-1016"}, {"type": "gaps", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Complete as lacunas (to be, to have, is, was...).", "explain": "Fato simultâneo = to be + -ing; fato anterior = to have + particípio; \"It is expected that...\" é a estrutura impessoal.", "prompt": "The author is said ___ working on a sequel at the moment.\nHe is alleged ___ stolen the funds in 2019.\nIt ___ expected that interest rates will fall.", "answers": [["to be"], ["to have"], ["is", "was"]], "id": "bkC1-1017"}, {"type": "choose", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Escolha a opção correta em cada grupo.", "explain": "Passiva com verbo de opinião: \"is believed\". Como o fato é de 2015 (anterior ao relato), usa-se \"to have been built\".", "prompt": "The warehouse [is believed*/believes/is believing] to [have been*/be/being] built without a permit in 2015.", "id": "bkC1-1018"}, {"type": "error", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Encontre o erro e corrija.", "explain": "Depois de \"said\" na passiva vem \"to + verbo\": \"are said to be planning\".", "sentence": "They are said be planning to move abroad.", "wrong": "said be", "fix": ["said to be"], "id": "bkC1-1019"}, {"type": "error", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Encontre o erro e corrija.", "explain": "Em \"There + passiva + to be\", o verbo concorda com o substantivo que vem depois: \"thousands\" pede \"are\".", "sentence": "There is thought to be thousands of undiscovered species in the deep sea.", "wrong": "is thought", "fix": ["are thought"], "id": "bkC1-1020"}, {"type": "rewrite", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Reescreva a frase na passiva com sujeito pessoal (is said to...).", "explain": "\"People say (that) the chef is planning...\" vira \"The chef is said to be planning...\" (fato simultâneo: to be + -ing).", "prompt": "People say the chef is planning to open a second restaurant.", "start": "The chef", "accept": ["The chef is said to be planning to open a second restaurant.", "The chef is believed to be planning to open a second restaurant.", "The chef is thought to be planning to open a second restaurant.", "The chef is rumored to be planning to open a second restaurant.", "The chef is reported to be planning to open a second restaurant."], "id": "bkC1-1021"}, {"type": "rewrite", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Reescreva a frase começando pelo sujeito da oração.", "explain": "Fato anterior ao relato: \"are reported to have been injured\" (infinitivo perfeito passivo); o verbo concorda com \"two officers\".", "prompt": "It is reported that two officers were injured in the clash.", "start": "Two officers", "accept": ["Two officers are reported to have been injured in the clash."], "id": "bkC1-1022"}, {"type": "order", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Em \"There + passiva + to be\", a ordem é: There are believed to be + substantivo.", "words": ["There", "are", "believed", "to", "be", "over", "a", "hundred", "survivors"], "id": "bkC1-1023"}, {"type": "tf", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto usa expressões de incerteza (believed, thought): a data é uma crença e a sacerdotisa é uma hipótese. A causa da morte ainda será investigada.", "text": "Archaeologists in Peru have unearthed a tomb that is believed to date from around 800 AD. The skeleton inside is thought to have belonged to a priestess, partly because of the ornaments found beside it. According to the lead researcher, the site is known to have been looted in the 1700s, yet the burial chamber seems to have been overlooked. Further tests are expected to reveal the cause of death.", "items": [{"s": "The tomb is believed to be about 1,200 years old or more.", "a": true}, {"s": "It is certain that the skeleton belonged to a priestess.", "a": false}, {"s": "Thieves probably missed the burial chamber.", "a": true}, {"s": "The cause of death has already been revealed.", "a": false}], "id": "bkC1-1024"}, {"type": "match", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Ligue cada frase ativa à versão com passiva impessoal.", "explain": "A oração com that vira sujeito + passiva + to: fato simultâneo = to be; anterior = to have + particípio; futuro = to + verbo.", "left": ["They say he is extremely generous.", "Experts think the virus emerged last spring.", "Officials expect that talks will resume soon.", "Journalists report that he was arrested at dawn."], "right": ["Talks are expected to resume soon.", "He is reported to have been arrested at dawn.", "He is said to be extremely generous.", "The virus is thought to have emerged last spring."], "correctMap": [2, 3, 0, 1], "id": "bkC1-1025"}, {"type": "reading", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Leia o texto e responda às perguntas.", "explain": "O texto diz que o valor é \"reported\" mas não confirmado, que Marta teria rejeitado duas ofertas e que a decisão é esperada no mês que vem.", "text": "The tech start-up Veloce is said to be in talks with a Japanese investor, according to sources close to the company. It is reported that the deal could be worth $400 million, although neither party has confirmed this. The founder, Marta Lins, is believed to have rejected two earlier offers. Veloce, which is estimated to employ 350 people, is expected to announce its decision next month.", "questions": [{"q": "What is the status of the $400 million figure?", "options": ["It was officially announced.", "It is reported but not confirmed.", "It was rejected by the investor."], "correctIndex": 1}, {"q": "What is Marta Lins believed to have done?", "options": ["Refused two previous offers", "Sold her shares", "Hired 350 new employees"], "correctIndex": 0}, {"q": "When is a decision expected?", "options": ["This week", "Next month", "Next year"], "correctIndex": 1}], "id": "bkC1-1026"}, {"type": "odd", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Encontre o verbo que não combina com a estrutura \"is ___ to be\".", "explain": "Said, believed e expected formam passiva com \"to be\"; \"enjoyed\" não é verbo de opinião ou relato.", "prompt": "Which verb cannot complete: \"She is ___ to be the best candidate\"?", "options": ["said", "enjoyed", "believed", "expected"], "correctIndex": 1, "id": "bkC1-1027"}, {"type": "blank", "level": "C1", "topic": "Passiva com verbos de opinião (It is said that / He is thought to)", "instruction": "Complete a lacuna com duas palavras.", "explain": "Fato futuro: sujeito + is expected + to be/become.", "prompt": "The new vaccine is expected ___ available by spring.", "accept": ["to be", "to become"], "id": "bkC1-1028"}, {"type": "mcq", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Escolha a forma correta.", "explain": "Depois de \"It's high time + sujeito\" usa-se o passado simples: you started.", "prompt": "It's high time you ___ taking responsibility for your own mistakes.", "options": ["to start", "will start", "started", "starting"], "correctIndex": 2, "id": "bkC1-1029"}, {"type": "mcq", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Escolha a forma correta.", "explain": "Para algo que já passou, \"would rather + sujeito\" pede past perfect: I'd rather you had told me.", "prompt": "The changes were announced yesterday. I'd rather you ___ me in advance.", "options": ["had told", "tell", "told", "have told"], "correctIndex": 0, "id": "bkC1-1030"}, {"type": "gaps", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Complete com a forma correta do verbo entre parênteses.", "explain": "As if + irreal no presente: passado (were); It's time we + passado simples; would rather you + passado (negativa: didn't).", "prompt": "He talks to me as if I ___ (be) a child.\nIt's time we ___ (pay) the bill and left.\nI'd rather you ___ (not smoke) in here.", "answers": [["were", "was"], ["paid"], ["didn't smoke", "did not smoke"]], "id": "bkC1-1031"}, {"type": "choose", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Escolha a opção correta em cada grupo.", "explain": "Aparência irreal ou de algo anterior: as though + past perfect (had seen). It's high time + sujeito pede passado simples (took).", "prompt": "She looked as though she [had seen*/would see/has seen] a ghost. It's high time the government [took*/to take/taking] action.", "id": "bkC1-1032"}, {"type": "error", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Encontre o erro e corrija.", "explain": "Would rather + verbo base, sem \"to\", quando o sujeito é o mesmo.", "sentence": "I'd rather to stay at home than go to the party.", "wrong": "to stay", "fix": ["stay"], "id": "bkC1-1033"}, {"type": "error", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Encontre o erro e corrija.", "explain": "Suppose/supposing com hipótese irreal usa passado simples, não would.", "sentence": "Suppose you would lose your job, what would you do?", "wrong": "would lose", "fix": ["lost"], "id": "bkC1-1034"}, {"type": "rewrite", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Reescreva com \"I'd rather you...\".", "explain": "Would rather + sujeito diferente + passado simples (didn't call) para um pedido sobre o presente ou futuro.", "prompt": "I would prefer you not to call me after ten.", "accept": ["I'd rather you didn't call me after ten.", "I would rather you didn't call me after ten.", "I'd rather you did not call me after ten.", "I would rather you did not call me after ten.", "I'd rather you not call me after ten.", "I would rather you not call me after ten."], "id": "bkC1-1035"}, {"type": "rewrite", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Reescreva a frase com \"It's high time\".", "explain": "It's high time + sujeito + passado simples expressa que já devia estar acontecendo, com tom de crítica.", "prompt": "You really ought to be doing your own laundry by now.", "accept": ["It's high time you did your own laundry.", "It is high time you did your own laundry.", "It's high time you did your own laundry by now.", "It is high time you did your own laundry by now."], "id": "bkC1-1036"}, {"type": "order", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Ordene as palavras para formar uma frase.", "explain": "As if + passado (owned) indica que a situação é irreal no presente.", "words": ["He", "acts", "as", "if", "he", "owned", "the", "whole", "company"], "id": "bkC1-1037"}, {"type": "tf", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "A narradora preferia que o irmão tivesse conversado antes, acha que ele ignora as regras e que já devia amadurecer; admitiria o erro se o blog desse certo.", "text": "Last week my brother Rafael announced that he was quitting his job to travel. I'd rather he had discussed it with us first, but that's just how he is: he behaves as though the rules didn't apply to him. Honestly, it's high time he grew up. Still, suppose he does manage to make a living from his blog; I'd be the first to admit I was wrong.", "items": [{"s": "The writer wishes Rafael had talked to the family earlier.", "a": true}, {"s": "The writer thinks Rafael follows rules carefully.", "a": false}, {"s": "The writer believes Rafael is already mature.", "a": false}, {"s": "The writer would admit a mistake if the blog succeeds.", "a": true}], "id": "bkC1-1038"}, {"type": "match", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Ligue o começo de cada frase ao final correto.", "explain": "Cada estrutura pede um tempo específico: It's high time + passado, I'd rather you hadn't + particípio, as if + were, suppose + passado.", "left": ["It's high time the council", "I'd rather you hadn't", "He talks as if he", "Suppose the flight"], "right": ["told her about the party.", "were the owner of the place.", "were cancelled, where would we stay?", "repaired this road before somebody gets hurt."], "correctMap": [3, 0, 1, 2], "id": "bkC1-1039"}, {"type": "reading", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Leia o texto e responda às perguntas.", "explain": "O texto diz que o alarme de fumaça acordou todos, que a autora preferia ter sido avisada e que o proprietário será acionado se Joel recusar.", "text": "Our flatmate Joel moves around the kitchen as if he were the only person who lived here. Last night he cooked at midnight, and I'd rather he had warned us, because the smoke alarm woke everyone. Tonight we're going to talk to him. It's about time somebody said something. What if he refuses to change? Then we'd have to ask the landlord to step in.", "questions": [{"q": "What woke the flatmates last night?", "options": ["Joel's music", "The smoke alarm", "A phone call"], "correctIndex": 1}, {"q": "What does the writer wish Joel had done?", "options": ["Warned them first", "Cooked earlier", "Cleaned the kitchen"], "correctIndex": 0}, {"q": "What will happen if Joel refuses to change?", "options": ["They will move out.", "They will ask the landlord to get involved.", "They will cook at midnight too."], "correctIndex": 1}], "id": "bkC1-1040"}, {"type": "odd", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Encontre a frase que NÃO usa uma forma passada para expressar irrealidade.", "explain": "\"It looks as if it's going to rain\" trata de algo provável, por isso usa o tempo normal. As outras três recuam o tempo (were, went, lost).", "prompt": "Which sentence does not use a past form to express unreality?", "options": ["He talks as if he were the manager.", "It's time you went to bed.", "Suppose I lost my passport abroad.", "It looks as if it's going to rain."], "correctIndex": 3, "id": "bkC1-1041"}, {"type": "blank", "level": "C1", "topic": "Passado irreal (It's time, would rather, as if)", "instruction": "Complete a lacuna.", "explain": "Para comparar preferências com would rather, usa-se \"than\" (e não \"to\" ou \"that\").", "prompt": "I'd rather walk home ___ take a taxi at this hour.", "accept": ["than"], "id": "bkC1-1042"}, {"type": "mcq", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Escolha a opção correta.", "explain": "\"The + singular\" representa uma invenção como um todo, em estilo formal: the invention of the telephone.", "prompt": "In the late 1800s, the invention of ___ changed long-distance communication forever.", "options": ["telephone", "the telephone", "a telephone", "some telephone"], "correctIndex": 1, "id": "bkC1-1043"}, {"type": "mcq", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Escolha a opção correta.", "explain": "Cordilheiras levam \"the\": the Andes. Mount Aconcagua, uma montanha individual, não leva.", "prompt": "The expedition will cross ___ and then climb Mount Aconcagua.", "options": ["Andes", "a Andes", "an Andes", "the Andes"], "correctIndex": 3, "id": "bkC1-1044"}, {"type": "gaps", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Complete com a, an ou the.", "explain": "Profissão: a/an (an architect); instrumento tratado como um todo: the cello; taxa: a/an (an hour).", "prompt": "My sister works as ___ architect, thinks ___ cello has the richest sound of all instruments, and tutors at $30 ___ hour.", "answers": [["an"], ["the"], ["an"]], "id": "bkC1-1045"}, {"type": "choose", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Escolha a opção correta em cada grupo.", "explain": "Generalização: sem artigo (honesty). Com restrição por \"of\" (of this candidate), usa-se the.", "prompt": "[Honesty*/The honesty/An honesty] is rare in politics, but [the honesty*/honesty/an honesty] of this candidate impressed everyone.", "id": "bkC1-1046"}, {"type": "error", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Encontre o erro e corrija.", "explain": "Em generalizações, o inglês não usa artigo antes de substantivo incontável: \"Life is too short...\".", "sentence": "The life is too short to waste on regrets.", "wrong": "The life", "fix": ["Life"], "id": "bkC1-1047"}, {"type": "error", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Encontre o erro e corrija.", "explain": "Cargo único depois de elect, appoint, make, become: sem artigo (elected mayor).", "sentence": "She was elected the mayor of Curitiba in 2020.", "wrong": "the mayor", "fix": ["mayor"], "id": "bkC1-1048"}, {"type": "rewrite", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Reescreva usando \"the\" + substantivo no singular para representar a espécie.", "explain": "Para falar da espécie como um todo em estilo formal, usa-se the + singular: The tiger is...", "prompt": "Tigers are in danger of extinction.", "start": "The tiger", "accept": ["The tiger is in danger of extinction."], "id": "bkC1-1049"}, {"type": "rewrite", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Reescreva usando \"the\" + adjetivo para designar o grupo.", "explain": "The + adjetivo (the unemployed) designa um grupo de pessoas e leva verbo no plural, sem -s.", "prompt": "People who are unemployed struggle to find affordable housing.", "start": "The unemployed", "accept": ["The unemployed struggle to find affordable housing."], "id": "bkC1-1050"}, {"type": "order", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Cargo único depois de appoint sem artigo (head); \"the department\" leva the porque é específico.", "words": ["She", "was", "appointed", "head", "of", "the", "department", "last", "spring"], "alt": ["Last spring she was appointed head of the department"], "id": "bkC1-1051"}, {"type": "tf", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que Priya vai ao acampamento-base do Everest, viaja de ônibus até o sopé, é enfermeira e não se preocupa com o frio.", "text": "Next month, Priya is flying to Nepal, where she hopes to reach the base camp of Mount Everest. She will begin in Kathmandu, travel by bus to the foothills, and then trek for twelve days. Priya has been a nurse for ten years, and she is raising money for a charity that supports the homeless in her city. She isn't worried about the cold; mountaineers say that it is the thin air that causes the most problems.", "items": [{"s": "Priya hopes to reach the base camp of Mount Everest.", "a": true}, {"s": "She will travel by plane all the way to the foothills.", "a": false}, {"s": "Priya works as a nurse.", "a": true}, {"s": "She is very worried about the cold.", "a": false}], "id": "bkC1-1052"}, {"type": "match", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Ligue cada frase à regra que explica o uso do artigo.", "explain": "Generalização = zero; espécie = the genérico; the + adjetivo = grupo; of restringe o substantivo e pede the.", "left": ["Life is short.", "The tiger is endangered.", "The rich are getting richer.", "The history of Rome is long."], "right": ["The + adjetivo: grupo de pessoas", "Generalização: sem artigo", "Substantivo restringido por of", "The genérico: espécie inteira"], "correctMap": [1, 3, 0, 2], "id": "bkC1-1053"}, {"type": "reading", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Leia o texto e responda às perguntas.", "explain": "O texto diz que Marcos ia de carro, hoje anda de bicicleta, e planeja atravessar o Mar do Norte de barco no verão.", "text": "Marcos grew up in Curitiba, but now he lives in the Netherlands, where he teaches at a school near Rotterdam. At weekends he usually cycles along the Rhine or visits friends in Amsterdam. He says that bicycles have changed his life: he used to go to work by car, but now he rides a bike in all weather. Next summer he plans to sail across the North Sea to visit his sister, who lives in England.", "questions": [{"q": "How did Marcos get to work in the past?", "options": ["By bike", "By car", "By train"], "correctIndex": 1}, {"q": "How does he plan to visit his sister?", "options": ["By sailing across the North Sea", "By flying from Rotterdam", "By taking a bus"], "correctIndex": 0}, {"q": "What does he usually do at weekends?", "options": ["Teaches at school", "Cycles or visits friends", "Stays home"], "correctIndex": 1}], "id": "bkC1-1054"}, {"type": "odd", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Encontre o nome que normalmente leva \"the\".", "explain": "Países no plural, como the Netherlands, levam the; lagos, montanhas individuais e cidades não levam.", "prompt": "Which place name normally takes \"the\"?", "options": ["Lake Como", "Paris", "Netherlands", "Mount Fuji"], "correctIndex": 2, "id": "bkC1-1055"}, {"type": "blank", "level": "C1", "topic": "Artigos avançados (the genérico e artigo zero)", "instruction": "Complete com a, an ou the.", "explain": "Em expressões de frequência usa-se a/an: twice a week.", "prompt": "I'm meeting my cousin twice ___ week.", "accept": ["a"], "id": "bkC1-1056"}, {"type": "mcq", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Escolha a opção correta.", "explain": "Com \"my sister\" (she) usamos \"has\" na afirmativa.", "prompt": "My sister ___ two cats.", "options": ["have", "has", "is", "haves"], "correctIndex": 1, "id": "bkA1-2001"}, {"type": "gaps", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Complete o diálogo com a forma certa de have (não use have got).", "explain": "Com I e you, a negativa e a pergunta usam don't / do + have; com she, a pergunta usa does + have (e a afirmativa usa has).", "prompt": "A: Do you ___ a brother?\nB: No, I ___ have a brother, but I have a sister.\nA: Does she ___ children?\nB: Yes, she ___ two boys.", "answers": [["have"], ["don't", "do not"], ["have"], ["has"]], "id": "bkA1-2002"}, {"type": "choose", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Escolha a forma correta.", "explain": "Com \"they\" usamos \"have got\"; com \"he\" a negativa de have got é \"hasn't got\".", "prompt": "They [have*/has/are] got a big garden, but he [hasn't*/doesn't/isn't] got a garden.", "id": "bkA1-2003"}, {"type": "error", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Encontre o erro e corrija.", "explain": "Com have got não se usa \"do\". A pergunta é \"Have you got...?\" ou \"Do you have...?\".", "sentence": "Do you have got a pencil?", "wrong": "have got", "fix": ["have"], "id": "bkA1-2004"}, {"type": "rewrite", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Reescreva a frase na forma negativa, usando don't ou doesn't.", "explain": "Com have, a negativa usa doesn't + have (sem -s): \"He doesn't have a phone\".", "prompt": "He has a phone.", "accept": ["He doesn't have a phone.", "He does not have a phone."], "id": "bkA1-2005"}, {"type": "order", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Ordene as palavras para formar uma pergunta com have got.", "explain": "Em have got, o auxiliar vem antes do sujeito: \"Have you got...?\"", "words": ["Have", "you", "got", "a", "bike"], "id": "bkA1-2006"}, {"type": "tf", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que Rita tem dois cachorros, não tem gatos, tem uma bicicleta e toma café da manhã às sete.", "text": "My name is Rita. I've got two dogs, but I haven't got a cat. I've got a new bike, and I ride it to work. I have breakfast at seven o'clock every day.", "items": [{"s": "Rita has two dogs.", "a": true}, {"s": "Rita has a cat.", "a": false}, {"s": "Rita has a new bike.", "a": true}, {"s": "Rita has breakfast at eight.", "a": false}], "id": "bkA1-2007"}, {"type": "match", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Ligue cada pergunta à resposta curta correta.", "explain": "A resposta curta repete o auxiliar da pergunta: Do you have...? Yes, I do. / Has he got...? No, he hasn't.", "left": ["Do you have a pen?", "Has he got a car?", "Does she have a laptop?", "Have they got a house?"], "right": ["No, he hasn't.", "Yes, they have.", "Yes, I do.", "No, she doesn't."], "correctMap": [2, 0, 3, 1], "id": "bkA1-2008"}, {"type": "sort", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Separe as frases: o verbo have indica posse ou ação?", "explain": "Have indica posse quando alguém tem algo (um carro, um irmão). Com refeição, banho ou diversão, é uma ação, e nesses casos have got não é usado.", "prompt": "Sort the phrases: posse or ação?", "groups": ["posse (have / have got)", "ação (só have)"], "items": [{"w": "have a car", "g": 0}, {"w": "have a sister", "g": 0}, {"w": "have blue eyes", "g": 0}, {"w": "have a cold", "g": 0}, {"w": "have lunch", "g": 1}, {"w": "have a shower", "g": 1}, {"w": "have a good time", "g": 1}, {"w": "have a coffee", "g": 1}], "id": "bkA1-2009"}, {"type": "dorder", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta com have got vem primeiro, depois a resposta curta, e então a nova pergunta e a resposta.", "lines": ["A: Have you got a dog, Paulo?", "B: No, I haven't, but I've got a cat.", "A: What's her name?", "B: Her name is Mimi."], "id": "bkA1-2010"}, {"type": "odd", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Encontre a frase que está errada.", "explain": "\"Do you have got\" mistura os dois jeitos. Ou é \"Do you have\" ou \"Have you got\".", "prompt": "Which sentence is wrong?", "options": ["Have you got a pen?", "Do you have a pen?", "Do you have got a pen?", "Has she got a pen?"], "correctIndex": 2, "id": "bkA1-2011"}, {"type": "mcq", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Escolha a frase correta para dizer que você tem 30 anos.", "explain": "Para idade usamos to be: \"I am 30 (years old)\". Não use have para idade.", "prompt": "How do you say your age?", "options": ["I have 30 years.", "I am 30 years old.", "I am have 30.", "I do 30 years."], "correctIndex": 1, "id": "bkA1-2012"}, {"type": "choose", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Escolha a forma correta.", "explain": "\"Lucy has got\" é a forma de posse/doença no presente (também se pode dizer \"Lucy's got\", em que o 's é \"has\"). E have como ação (breakfast) não usa got: \"doesn't have breakfast\".", "prompt": "Lucy [has*/is/does] got a cold, so she doesn't [have*/has got/is] breakfast today.", "id": "bkA1-2013"}, {"type": "blank", "level": "A1", "topic": "Have / have got (posse)", "instruction": "Complete com a forma certa de have: a ação não aceita got.", "explain": "Com \"we\" usamos \"have\" em ações como have a good time.", "prompt": "We always ___ a good time at Ana's party.", "accept": ["have"], "id": "bkA1-2014"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "mcq", "instruction": "Escolha a palavra certa para pedir permissão.", "explain": "Para pedir permissão com I, usamos can, could ou may. Aqui só Could serve; Would, Do e Are não formam esse pedido.", "prompt": "___ I sit here, please?", "options": ["Would", "Do", "Could", "Are"], "correctIndex": 2, "id": "bkA2-2001"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "mcq", "instruction": "Você está numa entrevista de emprego e quer abrir a janela. Qual frase é a mais formal e educada?", "explain": "May I é a forma mais formal para pedir permissão; com please fica ainda mais educado. I want e o imperativo soam diretos demais.", "prompt": "Which sentence is the most formal?", "options": ["I want to open the window.", "May I open the window, please?", "Open the window.", "Can I open it?"], "correctIndex": 1, "id": "bkA2-2002"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "gaps", "instruction": "Complete o diálogo na loja com a palavra certa em cada lacuna.", "explain": "Para oferecer ajuda: Can/May I help you? Para pedir: Could/Can/Would you...? Para oferecer: Would you like...? E Would you mind + -ing para pedir algo com educação.", "prompt": "A: Good morning. ___ I help you?\nB: Yes. ___ you show me that blue bag, please?\nA: Of course. Would you ___ to see the red one too?\nB: Yes, please.\nA: Would you ___ waiting a minute? I'll get it.\nB: No problem.", "answers": [["Can", "May"], ["Could", "Can", "Would"], ["like"], ["mind"]], "id": "bkA2-2003"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "choose", "instruction": "Escolha a opção certa em cada par de colchetes.", "explain": "Para oferecer algo usamos Would you like; para oferecer ajuda, Shall I + verbo base; depois de Would you mind, o verbo fica com -ing.", "prompt": "A: [Would*/Do/Are] you like some water?\nB: Yes, please. Thank you.\nA: [Shall*/Do/Are] I get a glass for you?\nB: Sure. And would you mind [opening*/open/to open] the window?", "id": "bkA2-2004"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Depois de could (e can, would), o verbo fica na forma base, sem -s: Could you help me?", "sentence": "Could you helps me with this exercise, please?", "wrong": "helps", "fix": ["help"], "id": "bkA2-2005"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Em inglês oferecemos com Would you like me to + verbo. O \"que eu\" do português não existe aqui.", "sentence": "Would you like that I carry your bag?", "wrong": "that I carry", "fix": ["me to carry"], "id": "bkA2-2006"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "rewrite", "instruction": "Reescreva a ordem como um pedido educado, começando com Could you.", "explain": "Could you + verbo base transforma a ordem em um pedido educado; please deixa ainda mais gentil.", "prompt": "Give me the menu.", "start": "Could you", "accept": ["Could you give me the menu?", "Could you give me the menu, please?", "Could you please give me the menu?"], "id": "bkA2-2007"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "rewrite", "instruction": "Reescreva a pergunta de forma mais formal, começando com May I.", "explain": "May I é a forma mais formal de pedir permissão, seguida do verbo base.", "prompt": "Can I use your phone?", "start": "May I", "accept": ["May I use your phone?", "May I use your phone, please?", "May I please use your phone?"], "id": "bkA2-2008"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "order", "instruction": "Ordene as palavras para formar um pedido educado.", "explain": "Would you mind pede o verbo com -ing: Would you mind closing the window?", "words": ["Would", "you", "mind", "closing", "the", "window"], "id": "bkA2-2009"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "tf", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "Ana pede água e Paulo oferece gelo, mas ela diz não. Paulo recusa o pedido de ligar a TV porque o irmão dorme, e sugere ouvir música.", "text": "Ana is at her friend Paulo's house. She is thirsty. \"Could I have some water, please?\" she asks. \"Of course,\" says Paulo. \"Would you like some ice?\" \"No, thanks.\" Then Ana sees the TV. \"May I turn it on?\" \"Sorry, you can't. My little brother is sleeping,\" says Paulo. \"How about listening to music?\" \"Good idea!\"", "items": [{"s": "Ana asks for water.", "a": true}, {"s": "Paulo offers some ice.", "a": true}, {"s": "Ana says yes to the ice.", "a": false}, {"s": "Paulo lets Ana turn on the TV.", "a": false}, {"s": "Paulo suggests listening to music.", "a": true}], "id": "bkA2-2010"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "match", "instruction": "Ligue cada pergunta ou sugestão à resposta mais natural.", "explain": "Um pedido de objeto aceita Sure; uma oferta aceita Yes, please; uma sugestão aceita Good idea; e Would you mind...? aceita No, not at all.", "left": ["Can I borrow your pen?", "Shall I open the window?", "Why don't we watch a film?", "Would you mind waiting a minute?"], "right": ["Good idea! I love comedies.", "No, not at all.", "Sure, here you are.", "Yes, please. It's hot in here."], "correctMap": [2, 3, 0, 1], "id": "bkA2-2011"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Primeiro vem o pedido educado, depois a resposta, o agradecimento e o No problem.", "lines": ["A: Excuse me. Could you tell me the time, please?", "B: Sure. It's half past ten.", "A: Thank you very much.", "B: No problem."], "id": "bkA2-2012"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "odd", "instruction": "Encontre a frase que não oferece ajuda.", "explain": "Could you help me? é um pedido de ajuda. As outras três oferecem ajuda.", "prompt": "Which sentence is not an offer?", "options": ["Can I help you?", "Shall I carry it?", "Would you like some help?", "Could you help me?"], "correctIndex": 3, "id": "bkA2-2013"}, {"level": "A2", "topic": "Pedidos, ofertas, permissão e sugestões", "type": "blank", "instruction": "Complete a sugestão com o verbo go na forma correta.", "explain": "Depois de How about, o verbo vai para -ing: How about going...?", "prompt": "How about ___ to the park on Sunday? (go)", "accept": ["going"], "id": "bkA2-2014"}, {"type": "mcq", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Escolha a resposta curta correta.", "explain": "A pergunta usa \"Do you...?\", então a resposta repete o auxiliar: \"Yes, I do.\" O verbo principal (like) não se repete.", "prompt": "A: Do you like horror movies?\nB: ___", "options": ["Yes, I like.", "Yes, I do.", "Yes, I am.", "Yes, I'm do."], "correctIndex": 1, "id": "bkA2-2015"}, {"type": "mcq", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Escolha a palavra que completa a resposta (concordando com A).", "explain": "A frase tem o modal \"can\"; ele se repete na resposta: \"So can I\".", "prompt": "A: I can swim very well.\nB: So ___ I!", "options": ["do", "am", "can", "does"], "correctIndex": 2, "id": "bkA2-2016"}, {"type": "gaps", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Complete o diálogo com respostas curtas.", "explain": "\"So am I\" repete o \"am\" de \"I'm hungry\", com a ordem invertida. Para \"Are you tired too?\", a resposta curta negativa é \"No, I'm not\" / \"No, I am not\".", "prompt": "A: I'm hungry.\nB: So ___ I.\nA: Are you tired too?\nB: No, ___.", "answers": [["am"], ["I'm not", "I am not"]], "id": "bkA2-2017"}, {"type": "gaps", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Complete o diálogo com um auxiliar (do ou don't).", "explain": "\"Neither do I\" usa o auxiliar afirmativo (Neither já é negativo). Para discordar de \"I love summer\", diz-se \"I don't\".", "prompt": "A: I don't like cold weather.\nB: Neither ___ I.\nA: I love summer.\nB: Really? I ___. It's too hot.", "answers": [["do"], ["don't", "do not"]], "id": "bkA2-2018"}, {"type": "choose", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Escolha a resposta correta nas duas respostas.", "explain": "Concordar com afirmação: \"So do I\" (auxiliar antes do sujeito). Concordar com negação: \"Neither can I\" (Neither já é negativo e vem com o auxiliar).", "prompt": "A: I love pizza. B: [So do I*/So I do/Neither do I].\nA: I can't swim. B: [So can I/Neither can I*/Neither I can].", "id": "bkA2-2019"}, {"type": "choose", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Escolha a opção correta.", "explain": "Depois de uma resposta curta à pergunta com \"Did\", repete-se \"did\". E em frase negativa usamos \"either\" no fim, não \"too\".", "prompt": "A: Did you call Marta? B: Yes, I [did*/called/was].\nMy sister doesn't like tea, and I don't like it [too/either*].", "id": "bkA2-2020"}, {"type": "error", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Encontre o erro e corrija.", "explain": "Na resposta curta afirmativa não se contrai: \"Yes, I am.\" (a contração \"I'm\" não pode ficar no fim).", "sentence": "Are you from Recife? Yes, I'm.", "wrong": "I'm", "fix": ["I am", "am"], "id": "bkA2-2021"}, {"type": "rewrite", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Concorde com a frase usando \"So ...\" (resposta curta).", "explain": "A frase é afirmativa no Simple Present, então usamos \"So do I\", com auxiliar antes do sujeito.", "prompt": "I work on Saturdays.", "accept": ["So do I.", "So do I"], "id": "bkA2-2022"}, {"type": "rewrite", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Concorde com a frase usando \"Neither ...\" (resposta curta).", "explain": "A frase tem \"am not\"; o auxiliar \"am\" volta afirmativo depois de Neither e antes do sujeito: \"Neither am I\".", "prompt": "I'm not ready.", "accept": ["Neither am I.", "Neither am I"], "id": "bkA2-2023"}, {"type": "order", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Ordene as palavras para concordar com: \"My sister loves K-pop.\"", "explain": "Frase afirmativa com \"loves\" (Simple Present): So + does + sujeito. A ordem é invertida: \"So does my brother.\"", "words": ["So", "does", "my", "brother"], "id": "bkA2-2024"}, {"type": "tf", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Leia o diálogo e marque verdadeiro (true) ou falso (false).", "explain": "Leo disse \"So do I\" (também ama caminhar); Bia disse \"Neither do I\" (não gosta da praia) e que não sabe nadar; Leo disse \"Neither can I\" (também não sabe).", "text": "Bia: I love hiking.\nLeo: So do I! I don't like the beach.\nBia: Neither do I. I can't swim.\nLeo: Neither can I!", "items": [{"s": "Leo loves hiking.", "a": true}, {"s": "Bia likes the beach.", "a": false}, {"s": "Leo can swim.", "a": false}, {"s": "Bia and Leo can both swim.", "a": false}], "id": "bkA2-2025"}, {"type": "match", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Ligue cada frase à resposta que concorda com ela.", "explain": "A resposta repete o auxiliar da frase: am → So am I; don't → Neither do I; can't → Neither can I; haven't → Neither have I.", "left": ["I'm so tired.", "I don't like onions.", "I can't drive.", "I haven't finished."], "right": ["Neither do I.", "Neither have I.", "So am I.", "Neither can I."], "correctMap": [2, 0, 3, 1], "id": "bkA2-2026"}, {"type": "dorder", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A diz o que está aprendendo; B reage com eco (\"Are you?\") e pergunta; A responde e diz que não fala rápido; B concorda com \"Neither can I\".", "lines": ["A: I'm learning Spanish.", "B: Are you? Is it hard?", "A: A little. I can't speak very fast.", "B: Neither can I. I'm learning it too."], "id": "bkA2-2027"}, {"type": "blank", "level": "A2", "topic": "Respostas curtas e eco (So do I / Neither do I)", "instruction": "Complete a resposta que concorda com a negação.", "explain": "A frase é negativa (didn't), então concordamos com \"Neither did I\" (ou \"Nor did I\"): o auxiliar \"did\" volta depois de Neither.", "prompt": "A: I didn't watch the game last night.\nB: ___ did I.", "accept": ["Neither", "Nor"], "id": "bkA2-2028"}, {"type": "mcq", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Escolha a pergunta correta para saber as horas.", "explain": "What time is it? é a forma padrão. As outras opções não existem em inglês.", "prompt": "Which question asks the time?", "options": ["How time is it?", "What is the hour?", "What time is it?", "Which time are you?"], "correctIndex": 2, "id": "bkA1-2015"}, {"type": "gaps", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Complete o diálogo com time, to ou at.", "explain": "Pergunta-se What time is it?; 8:45 é a quarter to nine (faltam 15 minutos); e a hora de um evento usa at.", "prompt": "A: Excuse me, what ___ is it?\nB: It's a quarter ___ nine.\nA: Thanks! And the train?\nB: It leaves ___ ten past nine.", "answers": [["time"], ["to"], ["at"]], "id": "bkA1-2016"}, {"type": "choose", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Escolha a preposição correta.", "explain": "Hora exata usa at; a parte do dia usa in (the evening); com night, usamos at.", "prompt": "The film starts [at*/in/on] 8 o'clock. I study [in*/at/on] the evening, but I sleep [in/at*/on] night.", "id": "bkA1-2017"}, {"type": "error", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Encontre o erro e corrija.", "explain": "Com the morning usamos in (in the morning), não at.", "sentence": "I get up at the morning.", "wrong": "at", "fix": ["in"], "id": "bkA1-2018"}, {"type": "rewrite", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Escreva o horário 7:30 por extenso, usando half past e começando com It's.", "explain": "Trinta minutos é half past, seguido da hora atual: It's half past seven.", "prompt": "7:30", "accept": ["It's half past seven.", "It is half past seven."], "id": "bkA1-2019", "start": "It's"}, {"type": "rewrite", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Diga o horário com to (forma falada), começando com It's.", "explain": "Depois de :30 usamos to e a próxima hora: 8:50 faltam dez para as nove, ou seja, ten to nine.", "prompt": "It's 8:50.", "accept": ["It's ten to nine.", "It is ten to nine."], "id": "bkA1-2020", "start": "It's"}, {"type": "order", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "A pergunta sobre horário de evento segue What time + does + sujeito + verbo base.", "words": ["What", "time", "does", "the", "film", "start"], "id": "bkA1-2021"}, {"type": "tf", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que a escola começa às 7:15 da manhã, o almoço é ao meio-dia, ela sai às 4:30 e dorme às dez da noite.", "text": "Ana is a student in Recife. School starts at a quarter past seven in the morning. Lunch is at noon. She finishes at half past four in the afternoon. She goes to bed at ten at night.", "items": [{"s": "School starts at 7:15.", "a": true}, {"s": "Ana has lunch at midnight.", "a": false}, {"s": "Ana finishes school at 4:30.", "a": true}, {"s": "She goes to bed at six.", "a": false}], "id": "bkA1-2022"}, {"type": "match", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Ligue cada horário digital à forma falada.", "explain": "3:15 é a quarter past three; 6:45 é a quarter to seven; 9:30 é half past nine; 12:00 p.m. é noon.", "left": ["3:15", "6:45", "9:30", "12:00 p.m."], "right": ["half past nine", "noon", "a quarter past three", "a quarter to seven"], "correctMap": [2, 3, 0, 1], "id": "bkA1-2023"}, {"type": "sort", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Separe as expressões de tempo conforme a preposição usada: in ou at.", "explain": "Usamos in com partes do dia (the morning, the afternoon, the evening) e at com night, noon, midnight e horas.", "prompt": "Sort the time words: in or at?", "groups": ["in", "at"], "items": [{"w": "the morning", "g": 0}, {"w": "the afternoon", "g": 0}, {"w": "the evening", "g": 0}, {"w": "night", "g": 1}, {"w": "noon", "g": 1}, {"w": "midnight", "g": 1}, {"w": "half past two", "g": 1}], "id": "bkA1-2024"}, {"type": "odd", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Encontre a frase que não é uma forma de perguntar as horas.", "explain": "Do you have the time?, What's the time? e Could you tell me the time? perguntam as horas; What hours are they? não faz sentido em inglês.", "prompt": "Which one is NOT a way to ask the time?", "options": ["What's the time?", "Do you have the time?", "Could you tell me the time?", "What hours are they?"], "correctIndex": 3, "id": "bkA1-2025"}, {"type": "mcq", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Escolha a forma falada de 5:45.", "explain": "Quarenta e cinco minutos é a quarter to e a próxima hora: a quarter to six.", "prompt": "How do you say 5:45?", "options": ["a quarter past five", "a quarter to six", "half past five", "a quarter to five"], "correctIndex": 1, "id": "bkA1-2026"}, {"type": "blank", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Complete a frase com a palavra que falta (hora cheia).", "explain": "Hora cheia se diz com o'clock: seven o'clock.", "prompt": "My bus leaves at seven ___.", "accept": ["o'clock"], "id": "bkA1-2027"}, {"type": "dorder", "level": "A1", "topic": "Horas (telling the time)", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta sobre as horas vem primeiro, depois a resposta; em seguida, a pergunta sobre o trem e a resposta com at.", "lines": ["A: Excuse me, what time is it?", "B: It's twenty to five.", "A: Thanks! What time does the train leave?", "B: It leaves at five o'clock."], "id": "bkA1-2028"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "mcq", "instruction": "Escolha a frase com a pontuação correta.", "explain": "However no início da frase leva ponto antes e vírgula depois: \"However, it is expensive.\"", "prompt": "Which sentence has the correct punctuation?", "options": ["I like the hotel. However, it is expensive.", "I like the hotel. However it, is expensive.", "I like the hotel However, it is expensive.", "I like the hotel, However. it is expensive."], "correctIndex": 0, "id": "bkA2-2029"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "mcq", "instruction": "Escolha a frase correta.", "explain": "It's = it is, e brother's mostra posse. Its sem apóstrofo é possessivo, não it is.", "prompt": "Which sentence is written correctly?", "options": ["Its my brother's birthday today.", "It's my brother's birthday today.", "It's my brothers birthday today.", "Its' my brother's birthday today."], "correctIndex": 1, "id": "bkA2-2030"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "odd", "instruction": "Qual palavra NÃO leva letra maiúscula em inglês?", "explain": "Dias, meses e nacionalidades levam maiúscula. As estações do ano (summer) são minúsculas.", "prompt": "Which word does not need a capital letter?", "options": ["Tuesday", "July", "Brazilian", "summer"], "correctIndex": 3, "id": "bkA2-2031"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "choose", "instruction": "Escolha a forma correta nas duas lacunas.", "explain": "Dias da semana e idiomas levam maiúscula em inglês, diferente do português.", "prompt": "We have a meeting on [monday/Monday*], and my boss speaks [portuguese/Portuguese*].", "id": "bkA2-2032"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "choose", "instruction": "Escolha its ou it's em cada lacuna.", "explain": "It's = it is (\"It's a nice day\"). Its é possessivo, sem apóstrofo (\"its tail\").", "prompt": "[Its/It's*] a nice day, and the dog is wagging [its*/it's] tail.", "id": "bkA2-2033"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Aqui queremos dizer it is, então a forma correta é com apóstrofo: It's.", "sentence": "Its raining today, so we are staying home.", "wrong": "Its", "fix": ["It's", "It is"], "id": "bkA2-2034"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Possessivo de it não leva apóstrofo: its paw. It's só significa it is.", "sentence": "The cat is licking it's paw.", "wrong": "it's", "fix": ["its"], "id": "bkA2-2035"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "sort", "instruction": "Em inglês, a palavra leva maiúscula? Separe os grupos.", "explain": "Dias, meses, idiomas e países levam maiúscula. Estações e profissões ou lugares comuns não.", "groups": ["Leva maiúscula", "Não leva maiúscula"], "items": [{"w": "friday", "g": 0}, {"w": "march", "g": 0}, {"w": "english", "g": 0}, {"w": "brazil", "g": 0}, {"w": "spring", "g": 1}, {"w": "winter", "g": 1}, {"w": "teacher", "g": 1}, {"w": "city", "g": 1}], "id": "bkA2-2036"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "tf", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "Tom mora em Chicago, a família é do México, ele ensina espanhol e inglês às sextas e visita os pais em julho.", "text": "Hi, I'm Tom. I live in Chicago, but my family is from Mexico. On Fridays, I teach Spanish and English at a school. In July, I visit my parents in Mexico City.", "items": [{"s": "Tom's family is from Mexico.", "a": true}, {"s": "Tom teaches Portuguese.", "a": false}, {"s": "Tom works on Fridays.", "a": true}, {"s": "Tom visits his parents in December.", "a": false}], "id": "bkA2-2037"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "match", "instruction": "Ligue cada uso da pontuação ao exemplo.", "explain": "Apóstrofo + s indica posse, apóstrofo também contrai, aspas marcam fala e a vírgula separa itens de lista.", "left": ["Posse", "Contração de it is", "Fala citada", "Lista de itens"], "right": ["It's cold today.", "He said, \"Good morning.\"", "Carla's bag", "I need eggs, milk, and rice."], "correctMap": [2, 0, 1, 3], "id": "bkA2-2038"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "gaps", "instruction": "Complete com its ou it's.", "explain": "Primeira lacuna: possessivo (its new bed). Segunda: it is (it's very soft).", "prompt": "My dog loves ___ new bed. ___ very soft.", "answers": [["its"], ["it's", "it is"]], "id": "bkA2-2039"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "reading", "instruction": "Leia o e-mail e responda.", "explain": "Ana chega na terça, quer visitar o Rio em março e pede para Marcos falar devagar, segundo o e-mail.", "text": "Hi Marcos,\nI'm Ana, your new colleague from Lisbon. I arrive on Tuesday, and I want to visit Rio in March. When I arrive, I will call you. However, my English isn't perfect, so please speak slowly. Thanks!", "questions": [{"q": "When does Ana arrive?", "options": ["On Tuesday", "In March", "On Friday"], "correctIndex": 0}, {"q": "What does Ana want to do in March?", "options": ["Call Marcos", "Visit Rio", "Study English"], "correctIndex": 1}, {"q": "What does Ana ask Marcos to do?", "options": ["Write a long email", "Speak slowly", "Visit Lisbon"], "correctIndex": 1}], "id": "bkA2-2040"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "order", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Nome próprio e idiomas levam maiúscula; a ordem é sujeito, verbo e objetos ligados por and.", "words": ["My", "friend", "Lucas", "speaks", "French", "and", "German"], "alt": ["My friend Lucas speaks German and French"], "id": "bkA2-2041"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "explain": "Primeiro as apresentações, depois a resposta de agrado, e por fim a pergunta de origem com a resposta.", "lines": ["A: Hi! I'm Karen. What's your name?", "B: I'm Paulo. Nice to meet you!", "A: Nice to meet you too. Where are you from?", "B: I'm from Brazil, and I speak Portuguese."], "id": "bkA2-2042"}, {"level": "A2", "topic": "Pontuação e maiúsculas", "type": "rewrite", "instruction": "Reescreva usando 's para mostrar posse.", "explain": "Para posse com uma pessoa, usamos nome + 's antes do objeto: my brother's phone.", "prompt": "This is the phone of my brother.", "start": "This is", "accept": ["This is my brother's phone"], "id": "bkA2-2043"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "mcq", "instruction": "Escolha a palavra que completa a frase.", "explain": "Cup é singular contável: usamos another (an + other), que significa mais um.", "prompt": "Can I have ___ cup of coffee, please?", "options": ["other", "another", "others", "the others"], "correctIndex": 1, "id": "bkA2-2044"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "mcq", "instruction": "Escolha a palavra que completa a frase.", "explain": "Others é pronome plural e substitui o substantivo: others = other students. Não vem seguido de substantivo.", "prompt": "Some students like math, but ___ prefer art.", "options": ["another", "other", "others", "one other"], "correctIndex": 2, "id": "bkA2-2045"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "mcq", "instruction": "Escolha a palavra que completa a pergunta.", "explain": "Anything else = mais alguma coisa. Else vem depois de anything, someone, nothing etc.", "prompt": "Would you like anything ___?", "options": ["other", "another", "others", "else"], "correctIndex": 3, "id": "bkA2-2046"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "gaps", "instruction": "Complete com another, other, the other ou others.", "explain": "Entre dois telefones, o segundo é the other. Another two hours = mais duas horas (another aceita número plural).", "prompt": "I have two phones. One is for work, and ___ is for home.\nShe isn't ready, so she needs ___ two hours.", "answers": [["the other"], ["another"]], "id": "bkA2-2047"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "choose", "instruction": "Escolha a opção correta em cada grupo.", "explain": "One é singular: another one. Others substitui other people. Com o substantivo kids, usa-se the other kids, sem s em other.", "prompt": "I don't like this shirt. Can I see [another*/other/others] one?\nSome people love rain, [other/others*] hate it.\nWhere are [the other*/another/others] kids?", "id": "bkA2-2048"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Other é invariável e não leva s antes de substantivo. Others só aparece sozinho, como pronome.", "sentence": "I like this song, but I don't like the others songs.", "wrong": "others", "fix": ["other"], "id": "bkA2-2049"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "One é singular contável e precisa de another (um outro). Other one sozinho, sem the, está errado.", "sentence": "I can't find my keys. Do you have other one?", "wrong": "other one", "fix": ["another one", "another"], "id": "bkA2-2050"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "rewrite", "instruction": "Reescreva usando another no lugar de one more.", "explain": "Another glass = one more glass. Another já contém o artigo an, então não se usa a antes dele.", "prompt": "Can I have one more glass of water?", "start": "Can I have another", "accept": ["Can I have another glass of water?", "Can I have another glass of water"], "id": "bkA2-2051"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "order", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Others funciona como pronome sujeito (= other people) e vem antes do verbo prefer.", "words": ["Some", "people", "like", "jazz", "but", "others", "prefer", "rock"], "alt": ["Others prefer rock but some people like jazz"], "id": "bkA2-2052"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A oferece ajuda, B diz que o tamanho não serve, A sugere outro tamanho (another size) e B aceita.", "lines": ["A: Can I help you?", "B: Yes, I like these shoes, but they're too small.", "A: Would you like to try another size?", "B: Yes, please. A size 8."], "id": "bkA2-2053"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "tf", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "Texto: dois empregos, alunos crianças e adultos (others), e ela ainda quer outro trabalho (another job) no fim de semana.", "text": "Maria has two jobs. In the morning, she works at a bank. In the evening, she teaches English. Some of her students are children, and others are adults. She wants another job on weekends, but her husband says no.", "items": [{"s": "Maria works at a bank in the morning.", "a": true}, {"s": "All her students are adults.", "a": false}, {"s": "Maria already has a weekend job.", "a": false}, {"s": "Maria teaches both children and adults.", "a": true}], "id": "bkA2-2054"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "reading", "instruction": "Leia a mensagem e escolha a resposta certa.", "explain": "As amigas foram ao shopping porque queriam comprar; as outras querem ir ao show; Carla e Ana vão ao parque.", "text": "Hi Paulo! I'm in Sao Paulo with Carla and her friends. Two of the friends love museums, so they visited MASP today. The other friends wanted to shop, so they went to a mall. Tomorrow we have another busy day. Carla and I want to see the park, and the others want to go to a concert. See you soon! Ana", "questions": [{"q": "Why did the other friends go to a mall?", "options": ["They wanted to shop.", "They love museums.", "It was raining."], "correctIndex": 0}, {"q": "Where do the others want to go tomorrow?", "options": ["To the park", "To a concert", "To MASP"], "correctIndex": 1}, {"q": "Who wants to see the park?", "options": ["Paulo and Ana", "Carla and Ana", "The others"], "correctIndex": 1}], "id": "bkA2-2055"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "sort", "instruction": "Separe as expressões corretas das incorretas.", "explain": "Another só com singular contável (another two weeks é exceção com número), other + plural ou incontável, e the other + substantivo. Others nunca antes de substantivo.", "groups": ["Correct", "Incorrect"], "items": [{"w": "another book", "g": 0}, {"w": "other people", "g": 0}, {"w": "the other side", "g": 0}, {"w": "another two weeks", "g": 0}, {"w": "another books", "g": 1}, {"w": "others people", "g": 1}, {"w": "the others books", "g": 1}, {"w": "a other friend", "g": 1}], "id": "bkA2-2056"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "match", "instruction": "Ligue o início de cada frase ao final certo.", "explain": "Um item restante: the other. Vários restantes: the others. Alguns e outros: others. Mais um: another one. Com any + plural: other colors.", "left": ["I have one pen here, and", "Some kids play soccer,", "This phone is old. I want", "There are ten players. Five are here, and", "I don't want this color. Do you have any"], "right": ["the others are late.", "another one.", "other colors?", "the other is in my bag.", "others play video games."], "correctMap": [3, 4, 1, 0, 2], "id": "bkA2-2057"}, {"level": "A2", "topic": "Another / other / others / the other", "type": "blank", "instruction": "Complete a frase com a expressão de reciprocidade.", "explain": "Quando duas pessoas fazem a mesma ação uma com a outra, usamos each other ou one another.", "prompt": "Maria and Joao talk to ___ every day.", "accept": ["each other", "one another"], "id": "bkA2-2058"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "mcq", "instruction": "Escolha a preposição correta.", "explain": "O adjetivo afraid pede a preposição of: afraid of dogs.", "prompt": "My sister is afraid ___ dogs.", "options": ["of", "from", "at", "with"], "correctIndex": 0, "id": "bkB1-1057"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "mcq", "instruction": "Escolha a preposição correta.", "explain": "O verbo depend pede on: depend on the weather. Nunca depend of.", "prompt": "Our trip to Bahia depends ___ the weather.", "options": ["of", "on", "from", "to"], "correctIndex": 1, "id": "bkB1-1058"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "gaps", "instruction": "Complete o diálogo com a preposição certa.", "explain": "Dizemos interested in (algo) e keen on (algo). Em inglês não se usa interested on.", "prompt": "A: Are you interested ___ jazz?\nB: Yes, I'm really keen ___ it.", "answers": [["in"], ["on"]], "id": "bkB1-1059"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "gaps", "instruction": "Complete o texto com a preposição certa.", "explain": "Combinações fixas: proud of, good at (+ -ing) e afraid of (+ -ing).", "prompt": "Marina is proud ___ her son. He is very good ___ playing chess, and he is never afraid ___ losing.", "answers": [["of"], ["at"], ["of"]], "id": "bkB1-1060"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "choose", "instruction": "Escolha a preposição correta nos dois casos.", "explain": "Dizemos married to (não married with) e famous for (não famous of).", "prompt": "She is married [to*/with/for] a doctor, and he is famous [for*/of/by] his songs.", "id": "bkB1-1061"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "choose", "instruction": "Escolha a preposição correta nos dois casos.", "explain": "Arrive in + cidade, e apologize for + motivo (-ing).", "prompt": "We arrived [in*/to/by] Curitiba at noon, and Tom apologized [for*/of/to] being late.", "id": "bkB1-1062"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "O verbo believe pede in quando falamos de acreditar na existência de algo: believe in.", "sentence": "Do you believe on ghosts?", "wrong": "on", "fix": ["in"], "id": "bkB1-1063"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "O substantivo increase pede in: an increase in prices (aumento em algo).", "sentence": "There was a big increase of prices last year.", "wrong": "of", "fix": ["in"], "id": "bkB1-1064"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "rewrite", "instruction": "Una as ideias com a preposição e -ing.", "explain": "Depois de preposição vem substantivo ou -ing: proud of winning, nunca proud of win.", "prompt": "She is proud. She won the race.", "start": "She is proud of", "accept": ["She is proud of winning the race.", "She is proud of having won the race."], "id": "bkB1-1065"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "rewrite", "instruction": "Corrija a frase.", "explain": "Wait pede for: wait for the train. Não se diz wait the train.", "prompt": "We are waiting the train.", "accept": ["We are waiting for the train.", "We're waiting for the train."], "id": "bkB1-1066"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "order", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Apologize to alguém for algo, com -ing depois de for: apologized to me for being late.", "words": ["He", "apologized", "to", "me", "for", "being", "late"], "id": "bkB1-1067"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "order", "instruction": "Ordene as palavras para formar uma pergunta.", "explain": "Substantivo + preposição: the reason for the delay (o motivo do atraso).", "words": ["What", "is", "the", "reason", "for", "the", "delay"], "id": "bkB1-1068"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta o motivo, B explica a preocupação, A anima e B fala da espera.", "lines": ["A: Why are you so worried about tomorrow?", "B: I have a job interview, and I'm afraid of making mistakes.", "A: Don't worry. You're good at talking to people.", "B: Thanks. I'm still waiting for their email with the time."], "id": "bkB1-1069"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "tf", "instruction": "Leia o texto e marque verdadeiro ou falso.", "explain": "O texto diz que ele é casado com Paula (enfermeira), é bom em explicar, ruim em nomes, e tem medo de voar.", "text": "Rafael is a teacher in Curitiba. He is married to Paula, a nurse. Rafael is good at explaining things, but he is bad at remembering names. He is proud of his students, and he is interested in science. Next week he is traveling to Recife, and he is afraid of flying.", "items": [{"s": "Rafael is married to a nurse.", "a": true}, {"s": "Rafael is good at remembering names.", "a": false}, {"s": "Rafael is interested in science.", "a": true}, {"s": "Paula is a teacher.", "a": false}], "id": "bkB1-1070"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "reading", "instruction": "Leia o e-mail e responda.", "explain": "Respostas direto do texto: waiting for a taxi, famous for its food, different from the photos.", "text": "Hi Carla, thanks for your message. I arrived in Lisbon yesterday. The hotel is different from the photos, but it is clean and quiet. Right now I'm waiting for a taxi to the old town. Lisbon is famous for its food, so I'm very excited. Tomorrow I'll look at some apartments, because I may stay here for a year. See you soon! Bruno", "questions": [{"q": "What is Bruno waiting for?", "options": ["A taxi", "A friend", "An email"], "correctIndex": 0}, {"q": "What is Lisbon famous for?", "options": ["Its beaches", "Its food", "Its hotels"], "correctIndex": 1}, {"q": "How is the hotel?", "options": ["Exactly like the photos", "Dirty and noisy", "Different from the photos"], "correctIndex": 2}], "id": "bkB1-1071"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "sort", "instruction": "Classifique pela preposição que costuma vir depois.", "explain": "Afraid, proud e tired pedem of; famous, wait e responsible pedem for.", "groups": ["of", "for"], "items": [{"w": "afraid", "g": 0}, {"w": "famous", "g": 1}, {"w": "proud", "g": 0}, {"w": "wait", "g": 1}, {"w": "tired", "g": 0}, {"w": "responsible", "g": 1}], "id": "bkB1-1072"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "match", "instruction": "Ligue cada início de frase ao final correto.", "explain": "Depends on, agree with, good at e famous for são combinações fixas.", "left": ["Success depends", "I completely agree", "He is very good", "Brazil is famous"], "right": ["with you.", "for its beaches.", "on hard work.", "at drawing."], "correctMap": [2, 0, 3, 1], "id": "bkB1-1073"}, {"level": "B1", "topic": "Preposições dependentes (interested in, good at, depend on)", "type": "blank", "instruction": "Digite a preposição que falta.", "explain": "Angry with ou angry at alguém por algo: ambas são corretas.", "prompt": "She is angry ___ her brother for losing her keys.", "accept": ["with", "at"], "id": "bkB1-1074"}, {"type": "mcq", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Escolha a palavra correta.", "explain": "Maria tem dois irmãos, então usamos both (os dois) com verbo no plural.", "prompt": "Maria has two brothers. ___ of them are engineers.", "options": ["Both", "All", "Either", "None"], "correctIndex": 0, "id": "bkB1-1075"}, {"type": "mcq", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Escolha a palavra que completa a frase.", "explain": "Either significa 'qualquer um dos dois' e leva verbo singular: Either is fine.", "prompt": "A: Do you want tea or coffee?\nB: I don't mind. ___ is fine.", "options": ["Both", "Either", "All", "None"], "correctIndex": 1, "id": "bkB1-1076"}, {"type": "mcq", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Escolha a palavra correta.", "explain": "Foram vinte convidados (mais de dois) e ninguém veio: usamos none.", "prompt": "I invited twenty people, but ___ of them came.", "options": ["both", "either", "neither", "none"], "correctIndex": 3, "id": "bkB1-1077"}, {"type": "mcq", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Escolha a opção correta.", "explain": "Com don't (já negativo), usamos either: I don't like either of them. Neither e none dariam negação dupla.", "prompt": "A: Do you like jazz or classical music?\nB: I don't like ___ of them.", "options": ["neither", "either", "none", "no"], "correctIndex": 1, "id": "bkB1-1078"}, {"type": "gaps", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Complete o texto com as palavras do quadro.", "explain": "Both = os dois primos; neither = nenhum dos dois tem carro; all = a família toda; none = nenhum dos quatro amigos.", "prompt": "I have two cousins, Rita and Paulo. ___ of them live in Salvador, in the same building. ___ of them has a car, so they take the bus. There are five people in my family, and ___ of us love football, even my grandmother. I asked my four friends for help, but ___ of them answered.", "bank": ["both", "either", "neither", "all", "none"], "answers": [["Both"], ["Neither"], ["All"], ["None"]], "id": "bkB1-1079"}, {"type": "gaps", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Complete as lacunas.", "explain": "Sem ovos: no + substantivo (no eggs). Na resposta, none substitui o substantivo (there are none).", "prompt": "There are ___ eggs in the fridge. I need to go shopping.\nA: Are there any cookies?\nB: No, there are ___.", "answers": [["no", "not any"], ["none"]], "id": "bkB1-1080"}, {"type": "choose", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Escolha a palavra correta em cada grupo.", "explain": "Both... and liga dois sujeitos; either pocket = qualquer um dos dois bolsos (singular); neither of the two = nenhum dos dois.", "prompt": "[Both*/Either/Neither] my mother and my father work at the hospital. I can't find my keys in [both/either*/neither] pocket. [Neither*/Not/None] of the two answers is correct.", "id": "bkB1-1081"}, {"type": "error", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Encontre o erro e corrija.", "explain": "Neither já é negativo. Não se usa don't; o verbo fica afirmativo (likes).", "sentence": "Neither of my brothers don't like spicy food.", "wrong": "don't like", "fix": ["likes", "like"], "id": "bkB1-1082"}, {"type": "error", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Encontre o erro e corrija.", "explain": "Depois de of, usamos pronome de objeto: both of them (não of they).", "sentence": "Both of they speak Portuguese at home.", "wrong": "they", "fix": ["them"], "id": "bkB1-1083"}, {"type": "rewrite", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Reescreva usando Neither... nor.", "explain": "Duas negações viram Neither... nor, com verbo afirmativo: Neither Julia nor her sister speaks French.", "prompt": "Julia doesn't speak French, and her sister doesn't either.", "start": "Neither", "accept": ["Neither Julia nor her sister speaks French.", "Neither Julia nor her sister speak French."], "id": "bkB1-1084"}, {"type": "order", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Ordene as palavras para formar a frase.", "explain": "Com a negativa don't, usamos either of: I don't like either of these two movies.", "words": ["I", "don't", "like", "either", "of", "these", "two", "movies"], "id": "bkB1-1085"}, {"type": "dorder", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta vem primeiro, depois a resposta com either, a reação com both e a decisão final.", "lines": ["A: Which one do you want, the blue shirt or the green one?", "B: Either one is fine with me.", "A: Really? I like both of them.", "B: Then let's buy both."], "id": "bkB1-1086"}, {"type": "tf", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "Todos passaram no primeiro teste, ninguém no segundo, e nenhum dos dois professores esperava notas baixas.", "text": "Our class has twenty students. All of them passed the first test, but none of them passed the second test. Both teachers, Mr. Lopes and Ms. Dias, were surprised. Neither of them expected such low scores.", "items": [{"s": "Every student passed the first test.", "a": true}, {"s": "Some students passed the second test.", "a": false}, {"s": "Ms. Dias was not surprised.", "a": false}, {"s": "The teachers did not expect the low scores.", "a": true}], "id": "bkB1-1087"}, {"type": "reading", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Leia a mensagem e responda.", "explain": "Neither of them = nenhum dos dois restaurantes tem mesa para dez; either place = qualquer um serve para seis; none of them = nenhum amigo quer dirigir longe.", "text": "Hi Dan, I checked two restaurants for Saturday. Neither of them has a table for ten people, because both are small. Either place can give us a table for six, though. All of our friends said they are free after 7, but none of them wants to drive far. Let's decide tomorrow. Bea", "questions": [{"q": "What is the problem with the restaurants?", "options": ["They are both closed.", "Neither has a table for ten.", "Both are too far."], "correctIndex": 1}, {"q": "What can either restaurant do?", "options": ["Give a table for six.", "Give a table for ten.", "Open after 7."], "correctIndex": 0}, {"q": "What do the friends not want to do?", "options": ["Come on Saturday.", "Eat late.", "Drive far."], "correctIndex": 2}], "id": "bkB1-1088"}, {"type": "sort", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Separe as expressões: duas coisas ou três ou mais.", "explain": "Both, either e neither falam de duas coisas; all e none falam de três ou mais.", "groups": ["Duas coisas", "Três ou mais"], "items": [{"w": "Both of my parents", "g": 0}, {"w": "Neither of the twins", "g": 0}, {"w": "Either of the two roads", "g": 0}, {"w": "Both of our hands", "g": 0}, {"w": "All twenty students", "g": 1}, {"w": "None of the five boys", "g": 1}, {"w": "All of my ten cousins", "g": 1}, {"w": "None of the 30 guests", "g": 1}], "id": "bkB1-1089"}, {"type": "match", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Ligue cada palavra ao seu significado.", "explain": "Both = os dois; either = um ou outro; neither = nenhum dos dois; none = nenhum de vários; all = todos.", "left": ["Both", "Either", "Neither", "None", "All"], "right": ["nenhum de vários", "todos (três ou mais)", "um ou outro (de dois)", "nenhum dos dois", "os dois, ambos"], "correctMap": [4, 2, 3, 0, 1], "id": "bkB1-1090"}, {"type": "blank", "level": "B1", "topic": "Both / either / neither / all / none", "instruction": "Complete com uma palavra (sentido negativo, sem usar not).", "explain": "São dois empregos e a frase é negativa sem not: neither of them pays well.", "prompt": "Jo has two jobs, but ___ of them pays well.", "accept": ["Neither"], "id": "bkB1-1091"}, {"type": "mcq", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Escolha a forma correta.", "explain": "Depois de make + objeto vem o verbo base, sem to: made me work.", "prompt": "My boss made me ___ late again last night.", "options": ["work", "to work", "working", "worked"], "correctIndex": 0, "id": "bkB1-1092"}, {"type": "mcq", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Escolha a forma correta.", "explain": "Allow + objeto pede to + verbo: allows students to use.", "prompt": "The school doesn't allow students ___ phones in class.", "options": ["use", "to use", "using", "used"], "correctIndex": 1, "id": "bkB1-1093"}, {"type": "gaps", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Complete as lacunas.", "explain": "Let não usa to (let me drive); be allowed pede to (was allowed to drive).", "prompt": "Last summer, my dad ___ (let) me drive his truck. He said I was ___ (allow) ___ drive only on country roads.", "answers": [["let"], ["allowed"], ["to"]], "id": "bkB1-1094"}, {"type": "choose", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Escolha a opção correta nos dois grupos.", "explain": "Make pede verbo base (made us write). A passiva da permissão é be allowed to; não existe be let to.", "prompt": "The teacher made us [write*/to write] the essay again. We weren't [let/allowed*] to use dictionaries.", "id": "bkB1-1095"}, {"type": "choose", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Escolha a opção correta nos dois grupos.", "explain": "Require pede objeto + to + verbo. Em helps us save, o verbo -ing não cabe.", "prompt": "The law requires companies [treat/to treat*] workers fairly. The new app helps us [save*/saving] time.", "id": "bkB1-1096"}, {"type": "error", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Encontre o erro e corrija.", "explain": "Depois de let + objeto, o verbo vem na forma base, sem to: let me stay.", "sentence": "My mom doesn't let me to stay up late.", "wrong": "to stay", "fix": ["stay"], "id": "bkB1-1097"}, {"type": "error", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Encontre o erro e corrija.", "explain": "Be allowed é seguido de to + verbo: are not allowed to park.", "sentence": "Visitors are not allowed park in front of the gate.", "wrong": "allowed park", "fix": ["allowed to park"], "id": "bkB1-1098"}, {"type": "rewrite", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Passe para a voz passiva, começando com \"The workers\".", "explain": "Na passiva, make ganha to: were made to wear.", "prompt": "They made the workers wear helmets.", "start": "The workers", "accept": ["The workers were made to wear helmets.", "The workers were made to wear helmets"], "id": "bkB1-1099"}, {"type": "rewrite", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Reescreva com \"are allowed to\", começando com \"Passengers\".", "explain": "A passiva da permissão usa be allowed to + verbo.", "prompt": "The airline allows passengers to bring one small bag.", "start": "Passengers", "accept": ["Passengers are allowed to bring one small bag.", "Passengers are allowed to bring one small bag"], "id": "bkB1-1100"}, {"type": "order", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Ordene as palavras para formar a frase.", "explain": "Let + objeto + verbo base: let me go, sem to antes de go.", "words": ["My", "parents", "let", "me", "go", "to", "the", "concert"], "id": "bkB1-1101"}, {"type": "order", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Ordene as palavras para formar a frase.", "explain": "Passiva da permissão no passado: weren't allowed to + verbo.", "words": ["We", "weren't", "allowed", "to", "take", "photos", "in", "the", "museum"], "id": "bkB1-1102"}, {"type": "dorder", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta, a explicação (made me), a nova pergunta com allowed e a resposta com let seguem a lógica.", "lines": ["A: Why can't you come to the movies tonight?", "B: My dad made me clean the garage.", "A: That's too bad. Are you allowed to come tomorrow?", "B: I think so. He'll let me go if I finish."], "id": "bkB1-1103"}, {"type": "tf", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Leia e marque verdadeiro ou falso.", "explain": "O texto diz que podem trabalhar de casa na sexta, não podem levar cachorros e devem ir à reunião; ninguém trabalha no fim de semana.", "text": "At Brightly Tech, the company lets employees work from home on Fridays. Everyone is required to attend the Monday meeting. Employees are not allowed to bring dogs to the office. The company doesn't make anyone work on weekends.", "items": [{"s": "Employees can work from home on Fridays.", "a": true}, {"s": "Employees can bring their dogs to the office.", "a": false}, {"s": "Everyone has to go to the Monday meeting.", "a": true}, {"s": "Employees must work on weekends.", "a": false}], "id": "bkB1-1104"}, {"type": "match", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Ligue cada ideia ao exemplo correspondente.", "explain": "Make = obrigar (to só na passiva); let = permitir informal; be allowed to = permissão na passiva; be made to = obrigação na passiva.", "left": ["Obrigar alguém (ativa)", "Permitir de modo informal", "Permissão na passiva", "Obrigação na passiva"], "right": ["We aren't allowed to smoke here.", "I was made to wait outside.", "The teacher made us read.", "My mom lets me stay up."], "correctMap": [2, 3, 0, 1], "id": "bkB1-1105"}, {"type": "sort", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Classifique as frases em corretas ou incorretas.", "explain": "Corretas: let/make sem to, allow com to, be made to. Erradas: made me to, be let to, allowed me go, let us to.", "groups": ["Correct", "Incorrect"], "items": [{"w": "She let me borrow her car.", "g": 0}, {"w": "We were made to wait.", "g": 0}, {"w": "They allowed us to enter.", "g": 0}, {"w": "He made me to cry.", "g": 1}, {"w": "I was let to go.", "g": 1}, {"w": "She allowed me go home.", "g": 1}, {"w": "They don't let us to smoke.", "g": 1}], "id": "bkB1-1106"}, {"type": "reading", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Leia o e-mail e responda.", "explain": "O texto diz que o professor faz os alunos deixarem o celular numa caixa, o diretor permitiu futebol e Caio ainda não pode ir sozinho.", "text": "Hi Rita, how is your new school? Here, the rules are strict. We are not allowed to use phones during class, and the teacher makes us leave them in a box. However, our principal lets us have lunch outside when the weather is nice. Last week, he even allowed our class to play soccer on the big field. I am not allowed to go home alone yet, so my dad picks me up. Write soon! Caio", "questions": [{"q": "Where do the students leave their phones?", "options": ["In a box", "At home", "With the principal"], "correctIndex": 0}, {"q": "What did the principal allow last week?", "options": ["Phones in class", "Soccer on the big field", "Lunch at home"], "correctIndex": 1}, {"q": "Why does Caio's dad pick him up?", "options": ["He lives far away", "He likes the school", "Caio isn't allowed to go home alone"], "correctIndex": 2}], "id": "bkB1-1107"}, {"type": "blank", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Complete com a forma de allow.", "explain": "Be allowed to é a passiva de allow; depois de aren't vem allowed.", "prompt": "Kids under twelve aren't ___ (allow) to ride this roller coaster.", "accept": ["allowed"], "id": "bkB1-1108"}, {"type": "error", "level": "B1", "topic": "Make / let / allow / be allowed to", "instruction": "Encontre o erro e corrija.", "explain": "Na passiva, make recebe to: was made to work. Sem to a frase fica errada.", "sentence": "I was made work all weekend.", "wrong": "made work", "fix": ["made to work"], "id": "bkB1-1109"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "mcq", "instruction": "Escolha a palavra que completa a frase.", "explain": "O filme causa o interesse: usamos -ing. Interested descreve quem sente interesse.", "prompt": "The documentary was so ___ that I watched it twice.", "options": ["interested", "interesting", "interest", "interestingly"], "correctIndex": 1, "id": "bkB2-1029"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "mcq", "instruction": "Escolha a palavra correta.", "explain": "Successive significa um após o outro; successful significa bem-sucedido.", "prompt": "Our team won four ___ games in a row.", "options": ["successful", "success", "successive", "succeeded"], "correctIndex": 2, "id": "bkB2-1030"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "gaps", "instruction": "Complete com a forma correta da palavra entre parênteses.", "explain": "Create vira creation (substantivo), friend vira friendship (substantivo) e honest vira honestly (advérbio).", "prompt": "The ___ (create) of the app took two years.\nOur ___ (friend) with the design team made it easier.\nThe CEO spoke ___ (honest) about the delay.", "answers": [["creation"], ["friendship"], ["honestly"]], "id": "bkB2-1031"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "choose", "instruction": "Escolha a palavra correta nas duas frases.", "explain": "Economic é relativo à economia; economical é econômico, que gasta pouco.", "prompt": "The [economic*/economical] crisis hit small shops hard, so we bought an [economic/economical*] car.", "id": "bkB2-1032"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "choose", "instruction": "Escolha o prefixo correto.", "explain": "Com legal usamos il-: illegal. Com fair usamos un-: unfair.", "prompt": "It is [illegal*/unlegal/inlegal] to park here, and the new rule seems [unfair*/infair/disfair].", "id": "bkB2-1033"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "A pessoa sente vergonha: embarrassed. Embarrassing descreve o que causa vergonha.", "sentence": "She felt very embarrassing when she forgot his name.", "wrong": "embarrassing", "fix": ["embarrassed"], "id": "bkB2-1034"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "O oposto de responsible é irresponsible: com palavras começadas por r, usamos ir-.", "sentence": "Leaving the stove on was completely unresponsible.", "wrong": "unresponsible", "fix": ["irresponsible"], "id": "bkB2-1035"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "rewrite", "instruction": "Reescreva com o sentido oposto, usando um prefixo.", "explain": "O oposto de honest é dishonest, com o prefixo dis-.", "prompt": "She is a very honest person.", "start": "She is a very", "accept": ["She is a very dishonest person"], "id": "bkB2-1036"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "rewrite", "instruction": "Reescreva trocando a expressão por um advérbio.", "explain": "Careful vira carefully com -ly: He drove carefully.", "prompt": "He drove in a careful way.", "start": "He drove", "accept": ["He drove carefully"], "id": "bkB2-1037"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "order", "instruction": "Ordene as palavras para formar uma frase.", "explain": "Friendship é o sujeito e vem antes de has grown; o comparativo stronger vem depois do verbo.", "words": ["Their", "friendship", "has", "grown", "stronger", "over", "the", "years"], "alt": ["Over the years their friendship has grown stronger"], "id": "bkB2-1038"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta sobre o emprego vem primeiro, depois a decisão, o nervosismo e a confiança.", "lines": ["A: Did you get the job?", "B: Not yet. They will make a decision on Friday.", "A: Are you nervous?", "B: A little, but I felt confident during the interview."], "id": "bkB2-1039"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "tf", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "O texto diz que o desemprego caiu, a cidade é mais segura e as vagas são temporárias; os moradores ficaram felizes.", "text": "The mayor announced a new plan last week. Unemployment fell by two percent, and the city is now safer because of better lighting. Many residents were pleased, but some think the plan is unrealistic. Most of the new jobs are temporary.", "items": [{"s": "Unemployment went down.", "a": true}, {"s": "The city is less safe than before.", "a": false}, {"s": "Some residents doubt the plan is realistic.", "a": true}, {"s": "Most of the new jobs are permanent.", "a": false}], "id": "bkB2-1040"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "reading", "instruction": "Leia o e-mail e responda às perguntas.", "explain": "Ele quer ajudar como voluntário, tem experiência com crianças e se oferece para trabalhar nos fins de semana.", "text": "Dear Ms. Alves,\nI am writing about the volunteer position at your reading center. I have two years of experience teaching children, and I am a patient and creative person. Unfortunately, I am unavailable on weekday mornings because of my studies, but I am completely flexible on weekends. I would be grateful for the opportunity to join your team.\nSincerely,\nPedro Lima", "questions": [{"q": "Why is Pedro writing?", "options": ["To complain about a class", "To apply for a volunteer job", "To cancel a meeting"], "correctIndex": 1}, {"q": "When is Pedro NOT available?", "options": ["Weekday mornings", "Weekends", "Weekday evenings"], "correctIndex": 0}, {"q": "What experience does Pedro have?", "options": ["Cooking for groups", "Teaching children", "Managing a team"], "correctIndex": 1}], "id": "bkB2-1041"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "sort", "instruction": "Classifique cada palavra pela sua classe gramatical.", "explain": "-ness e -ment formam substantivos; -ful e -ous formam adjetivos; -en e -ize formam verbos.", "groups": ["Substantivo", "Adjetivo", "Verbo"], "items": [{"w": "happiness", "g": 0}, {"w": "development", "g": 0}, {"w": "careful", "g": 1}, {"w": "dangerous", "g": 1}, {"w": "strengthen", "g": 2}, {"w": "modernize", "g": 2}], "id": "bkB2-1042"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "match", "instruction": "Ligue cada significado à palavra com o prefixo correto.", "explain": "Not legal é illegal, not regular é irregular, not happy é unhappy e not agree é disagree.", "left": ["not legal", "not regular", "not happy", "not agree"], "right": ["unhappy", "disagree", "illegal", "irregular"], "correctMap": [2, 3, 0, 1], "id": "bkB2-1043"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "blank", "instruction": "Digite a forma correta da palavra entre parênteses.", "explain": "True vira truth, com mudança de grafia (tr-u-e vira tr-u-th).", "prompt": "Scientists want to know the ___ (true) about the virus.", "accept": ["truth"], "id": "bkB2-1044"}, {"level": "B2", "topic": "Formação de palavras (prefixos e sufixos)", "type": "blank", "instruction": "Digite o substantivo formado a partir da palavra entre parênteses.", "explain": "Kind vira kindness: o sufixo -ness forma substantivos a partir de adjetivos.", "prompt": "Thank you for your ___ (kind) to my family.", "accept": ["kindness"], "id": "bkB2-1045"}, {"type": "match", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Ligue cada adjetivo ao seu oposto.", "explain": "São pares de opostos: big x small, hot x cold, new x old, easy x difficult, clean x dirty.", "left": ["big", "hot", "new", "easy", "clean"], "right": ["dirty", "small", "old", "cold", "difficult"], "correctMap": [1, 3, 2, 4, 0], "id": "bkA1-2029"}, {"type": "gaps", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Complete com o oposto do adjetivo.", "explain": "Opostos: hot x cold e heavy x light.", "prompt": "The soup is hot, but the ice cream is ___.\nMy bag is heavy, but your bag is ___.", "answers": [["cold"], ["light"]], "id": "bkA1-2030"}, {"type": "gaps", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Complete o diálogo com o oposto.", "explain": "Easy x difficult (ou hard); tall x short para pessoas.", "prompt": "A: Is the test easy?\nB: No, it's ___.\nA: Is your brother tall?\nB: No, he's ___.", "answers": [["difficult", "hard"], ["short"]], "id": "bkA1-2031"}, {"type": "mcq", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Escolha a frase completa correta.", "explain": "O adjetivo não vai para o plural: two small dogs.", "prompt": "We have two ___ dogs.", "options": ["small", "smalls", "smalles", "a small"], "correctIndex": 0, "id": "bkA1-2032"}, {"type": "mcq", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Escolha a palavra que completa a frase.", "explain": "Dark x light: light também significa claro (cheio de luz).", "prompt": "My room is ___: it has big windows and a lot of sun.", "options": ["dark", "light", "heavy", "short"], "correctIndex": 1, "id": "bkA1-2033"}, {"type": "odd", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Qual palavra não pertence ao grupo?", "explain": "Hot, cold e warm falam de temperatura; heavy é sobre peso.", "prompt": "Which word does not belong?", "options": ["hot", "cold", "warm", "heavy"], "correctIndex": 3, "id": "bkA1-2034"}, {"type": "choose", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Escolha o adjetivo certo em cada grupo.", "explain": "Para altura de pessoas usamos tall x short.", "prompt": "Pedro is [tall*/high]. His sister is [short*/low].", "id": "bkA1-2035"}, {"type": "choose", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Escolha a opção correta em cada grupo.", "explain": "Adjetivo antes do substantivo, sem plural; altura se pergunta com How tall.", "prompt": "This is a [house big/big house*]. We have two [big*/bigs] rooms. How [tall*/high] are you?", "id": "bkA1-2036"}, {"type": "error", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Encontre o erro e corrija.", "explain": "O adjetivo não varia: big, não bigs.", "sentence": "My brother has two bigs dogs.", "wrong": "bigs", "fix": ["big"], "id": "bkA1-2037"}, {"type": "rewrite", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Reforce o adjetivo com very.", "explain": "Very vem antes do adjetivo: very small.", "prompt": "My room is small.", "start": "My room is", "accept": ["My room is very small.", "My room is really small."], "id": "bkA1-2038"}, {"type": "order", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Monte a pergunta.", "explain": "Pergunta para pedir o oposto: What's the opposite of big?", "words": ["What's", "the", "opposite", "of", "big"], "id": "bkA1-2039"}, {"type": "order", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Monte a frase.", "explain": "Too vem antes do adjetivo e indica excesso: too heavy for me.", "words": ["Your", "bag", "is", "too", "heavy", "for", "me"], "id": "bkA1-2040"}, {"type": "dorder", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Coloque o diálogo em ordem.", "explain": "Pergunta sobre o apartamento, resposta, pergunta sobre o preço e resposta.", "lines": ["A: Is your new apartment big?", "B: No, it's small, but it's very clean.", "A: Is it expensive?", "B: No, it's cheap."], "id": "bkA1-2041"}, {"type": "tf", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Leia e marque verdadeiro ou falso.", "explain": "Pedro é alto, Lia é baixa, a casa é velha e grande, o jardim é pequeno.", "text": "Pedro is twelve years old. He is tall, but his sister Lia is short. Lia is nine. Their house is old and big. The garden is small, but it is very beautiful.", "items": [{"s": "Pedro is tall.", "a": true}, {"s": "Lia is tall.", "a": false}, {"s": "The house is new.", "a": false}, {"s": "The garden is small.", "a": true}], "id": "bkA1-2042"}, {"type": "reading", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Leia o e-mail e responda.", "explain": "O escritório é grande e limpo; o trabalho é difícil; o ônibus é lento, por isso ela chega atrasada.", "text": "Hi Rita, I have a new job. The office is big and clean, but the work is difficult. My boss is young and very nice. The coffee is cheap! But the bus is slow, so I am often late. See you soon, Carla.", "questions": [{"q": "How is the office?", "options": ["Small and dirty", "Big and clean", "Small and clean"], "correctIndex": 1}, {"q": "What is difficult?", "options": ["The coffee", "The bus", "The work"], "correctIndex": 2}, {"q": "Why is Carla late?", "options": ["The bus is slow.", "The work is easy.", "The boss is young."], "correctIndex": 0}], "id": "bkA1-2043"}, {"type": "sort", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Separe os adjetivos por grupo.", "explain": "Big/tiny: tamanho; hot/cold/wet: temperatura e clima; happy/nervous/sad: sentimentos.", "groups": ["Tamanho", "Temperatura e clima", "Sentimentos"], "items": [{"w": "big", "g": 0}, {"w": "tiny", "g": 0}, {"w": "hot", "g": 1}, {"w": "cold", "g": 1}, {"w": "wet", "g": 1}, {"w": "happy", "g": 2}, {"w": "nervous", "g": 2}, {"w": "sad", "g": 2}], "id": "bkA1-2044"}, {"type": "blank", "level": "A1", "topic": "Adjetivos e opostos (big / small, tall / short)", "instruction": "Complete com o oposto de open.", "explain": "Closed (ou shut) é o oposto de open.", "prompt": "It's Sunday, and the bank is not open. It is ___.", "accept": ["closed", "shut"], "id": "bkA1-2045"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "mcq", "instruction": "Escolha a opção correta.", "explain": "Bad é irregular: bad – worse – the worst. Não existe badder nem more bad.", "prompt": "This pizza is bad, but that one is even ___.", "options": ["worse", "badder", "more bad", "worst"], "correctIndex": 0, "id": "bkA2-2059"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "mcq", "instruction": "Escolha o superlativo correto.", "explain": "High tem uma sílaba: the highest. Com superlativo usamos the + -est.", "prompt": "Mount Everest is ___ mountain in the world.", "options": ["higher", "the highest", "the most high", "more high"], "correctIndex": 1, "id": "bkA2-2060"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "odd", "instruction": "Qual forma está errada?", "explain": "Adjetivo de uma sílaba usa -er (cheaper). More cheap é erro; as outras três estão corretas.", "prompt": "Which form is incorrect?", "options": ["faster", "more cheap", "older", "better"], "correctIndex": 1, "id": "bkA2-2061"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "gaps", "instruction": "Complete com o comparativo dos adjetivos entre parênteses.", "explain": "Heavy vira heavier (y vira i); o oposto light vira lighter. Comparativo com than.", "prompt": "Lucas's bag is ___ (heavy) than mine, so mine is ___ (light) than his.", "answers": [["heavier"], ["lighter"]], "id": "bkA2-2062"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "choose", "instruction": "Escolha a forma certa nas duas lacunas.", "explain": "Tall tem uma sílaba: taller e the tallest. Não se usa more nem most.", "prompt": "My brother is [taller*/more tall] than me. He is the [tallest*/most tall] boy in his class.", "id": "bkA2-2063"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "choose", "instruction": "Escolha a forma certa nas duas lacunas.", "explain": "Good é irregular: the best. Better já é comparativo, sem more.", "prompt": "She is [the best*/the goodest/the most good] student. My English is [better*/more better] than before.", "id": "bkA2-2064"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "Cheap tem uma sílaba, então o comparativo é cheaper, sem more.", "sentence": "This bag is more cheap than that one.", "wrong": "more cheap", "fix": ["cheaper"], "id": "bkA2-2065"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "error", "instruction": "Encontre o erro e corrija.", "explain": "No comparativo usamos than para ligar as duas partes, não that.", "sentence": "Tom is taller that his brother.", "wrong": "that", "fix": ["than"], "id": "bkA2-2066"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "rewrite", "instruction": "Diga a mesma coisa usando o adjetivo oposto.", "explain": "Se o Rio é maior, Salvador é menor: troque big por small e inverta as cidades.", "prompt": "Rio is bigger than Salvador.", "start": "Salvador", "accept": ["Salvador is smaller than Rio."], "id": "bkA2-2067"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "rewrite", "instruction": "Diga a mesma coisa usando o adjetivo oposto.", "explain": "Expensive tem como oposto cheap; invertendo os lados, fica cheaper (ou less expensive).", "prompt": "The red car is more expensive than the blue car.", "start": "The blue car", "accept": ["The blue car is cheaper than the red car.", "The blue car is less expensive than the red car."], "id": "bkA2-2068"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "order", "instruction": "Ordene as palavras para formar um superlativo.", "explain": "Estrutura: sujeito + is + the most + adjetivo + substantivo + in + lugar.", "words": ["This", "is", "the", "most", "interesting", "book", "in", "the", "library"], "id": "bkA2-2069"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "dorder", "instruction": "Coloque o diálogo na ordem correta.", "explain": "A pergunta o preço, B responde, A acha caro e pede um mais barato, B oferece e A fecha a compra.", "lines": ["A: Excuse me, how much is this laptop?", "B: It's 900 dollars.", "A: That's expensive. Do you have a cheaper one?", "B: Yes, this one is cheaper. It's 600 dollars.", "A: Great, I'll take it."], "id": "bkA2-2070"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "tf", "instruction": "Leia o texto e marque verdadeiro (true) ou falso (false).", "explain": "Davi tem 30 anos e é mais velho. Ana é mais alta que Davi. Lia, com 20, é a mais nova e mais baixa.", "text": "Ana is 25. Her brother Davi is 30, so he is older than Ana. Ana is taller than Davi, but Davi is stronger. Their sister Lia is the youngest. She is 20 and the shortest in the family.", "items": [{"s": "Davi is younger than Ana.", "a": false}, {"s": "Ana is taller than Davi.", "a": true}, {"s": "Lia is the tallest person in the family.", "a": false}, {"s": "Lia is younger than Ana.", "a": true}], "id": "bkA2-2071"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "reading", "instruction": "Leia o anúncio e responda.", "explain": "Sol é mais barato, menor e menos moderno; Mar é o mais caro e tem a maior piscina.", "text": "Looking for a hotel in Fortaleza? Hotel Sol is cheaper than Hotel Mar, but it is smaller and farther from the beach. Hotel Mar is the most expensive hotel in town, and it has the biggest pool. Hotel Sol is also less modern than Hotel Mar. Both hotels have free breakfast.", "questions": [{"q": "Which hotel is cheaper?", "options": ["Hotel Sol", "Hotel Mar", "They cost the same."], "correctIndex": 0}, {"q": "Which hotel has the biggest pool?", "options": ["Hotel Sol", "Hotel Mar", "Neither one."], "correctIndex": 1}, {"q": "Which sentence is true?", "options": ["Hotel Sol is bigger than Hotel Mar.", "Hotel Sol is less modern than Hotel Mar.", "Hotel Mar is cheaper than Hotel Sol."], "correctIndex": 1}], "id": "bkA2-2072"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "sort", "instruction": "Classifique os comparativos pela forma.", "explain": "Uma sílaba ou -y: -er/-ier. Adjetivos longos: more. Good e bad são irregulares.", "groups": ["-er / -ier", "more + adjetivo", "Irregular"], "items": [{"w": "taller", "g": 0}, {"w": "happier", "g": 0}, {"w": "bigger", "g": 0}, {"w": "more dangerous", "g": 1}, {"w": "more boring", "g": 1}, {"w": "more difficult", "g": 1}, {"w": "better", "g": 2}, {"w": "worse", "g": 2}], "id": "bkA2-2073"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "match", "instruction": "Ligue cada comparativo ao seu oposto.", "explain": "Os pares são: bigger/smaller, taller/shorter, faster/slower, hotter/colder.", "left": ["bigger", "taller", "faster", "hotter"], "right": ["slower", "colder", "smaller", "shorter"], "correctMap": [2, 3, 0, 1], "id": "bkA2-2074"}, {"level": "A2", "topic": "Opostos no comparativo e superlativo (bigger / smaller, the tallest)", "type": "blank", "instruction": "Escreva o comparativo do adjetivo entre parênteses.", "explain": "Far tem duas formas aceitas no comparativo: farther e further.", "prompt": "Recife is ___ (far) from Porto Alegre than Salvador is.", "accept": ["farther", "further"], "id": "bkA2-2075"}];
